/****** Object:  UserDefinedFunction [dbo].[GetLastIssueNumber]    Script Date: 8/27/2026 2:35:44 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[GetLastIssueNumber]
(
	-- Add the parameters for the function here
	--@IssueNumber nvarchar(max),
	@CostCenterId int,
	@DrugID int
)
RETURNS nvarchar(max)
AS
BEGIN
	return (SELECT top 1 isDep.[IssueNumber]
  FROM [Pharmacy].[IssuetoDepartment] isDep
  join [Pharmacy].[IssuetoDepartmentEntry] isDepDetails
  on isDep.ID=isDepDetails.[IssuetoDepartmentID]
  where   DrugID =@DrugID
  order by isDep.ID desc
  )

END





