/****** Object:  UserDefinedFunction [GL].[GetAccountTypeById]    Script Date: 8/27/2026 2:35:44 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE function [GL].[GetAccountTypeById]
 (
 @AccountTypeId AS int
 )
RETURNS VARCHAR(MAX)
AS
BEGIN
    declare @AccountName nvarchar(max)
	if @AccountTypeId=1
	begin
	select @AccountName= 'Debit'
	end
	else if @AccountTypeId=2 
	begin
	select @AccountName= 'Credit'
	end
	RETURN @AccountName
END


GO
/****** Object:  UserDefinedFunction [HR].[FBabySettingTS]    Script Date: 8/27/2026 2:35:44 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [HR].[FBabySettingTS](@date nvarchar(10),@emp int ) RETURNS decimal
as
begin
declare @Num decimal
set @Num =(
Select Sum(TS.BasicS) from 
(
select SUM(Emp.BasicSalary) BasicS from Nursing.Employee Emp 
where 
(@emp is NULL or Emp.Id=@emp) and 
Emp.id in(SELECT V_Babysetting.EmployeeId
from HR.V_Babysetting)
union

 select    SUM(svv.Value) sallary 
 from HR.MainElements ME
Inner join HR.SubElements SE on ME.ID = SE.MainElementID 
Left Join Hr.EmployeeSalaryVariablesVar svv  on SE.ID =svv.SubElementID 
inner join Nursing.Employee on Employee.Id=svv.EmpID
where   me.[Type]=2 and SE.InsuranceType=2 And
svv.EmpID in(SELECT V_Babysetting.EmployeeId
from HR.V_Babysetting)

and (@emp is NULL or Employee.Id=@emp)
and ( @date=svv.[Month]) 
and ID_Close IS not NULL
) as TS)

return @Num
End




GO
