/****** Object:  UserDefinedFunction [HR].[GetRemainingDaysFinal]    Script Date: 8/27/2026 2:35:44 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Function [HR].[GetRemainingDaysFinal]
 ( @EmpId int ,@VacId int , @year int,@DateFrom date 
--@Dateto date
 )
 returns int 
AS
BEGIN


--declare @EmpId int=58 ,@VacId int=1 , @year int=2020,@DateFrom date='2020-09-10'

Declare @PreviousVacationDays int , @Balance int  , @RemainingDays int   

-- get all Previous vacation Days
Set @PreviousVacationDays =ISNULL
	 (
	 (select 
	sum(vacDays) As PreviousVacationDays 
	from 
	HR.EmployeeVacations
	where 
	(HR.EmployeeVacations.EmpID=
	 @EmpId 
	 ) and 
	(HR.EmployeeVacations.vacID =  @VacId) and 
	 (HR.EmployeeVacations.Status = 2 ) --Approved
	 and HR.EmployeeVacations.Year =@year
	 --and  HR.EmployeeVacations.vacStartDate  = @DateFrom 
	 and HR.EmployeeVacations.vacEndDate <= @DateFrom 
	 ) 
	,0)
--print @PreviousVacationDays
	-- Balance if He has openbalanace _EmpOpenBalance.DaysNumber in current year else Vacation setting 
declare @ExistBal int=ISNULL((select VOB.DaysNumber
from HR.VacationOpenBalance VOB
where VOB.EmpID = 
@EmpId
 and VOB.year= 
@year
  and VOB.VacationID= 
 @VacId
  ),0)
--print @ExistBal
if(@ExistBal= 0)
begin
 declare @defaultVac int=(select 
	  VS.vac_Days
	    from  HR.VacationSettings VS
		 where  VS.ID = @VacId)

declare @SpentYears int=(select datediff( YEAR,(select JoiningDate from Nursing.Employee where Id=@EmpId),@DateFrom  ))
declare @empAge int=(select datediff( YEAR,(select BirthDate from Nursing.Employee where Id=@EmpId),@DateFrom  ))
--print '1'
declare @AgeVac int=0,@WorkVac int=0 
--print ''+ @SpentYears
--print @empAge
--spent  1 year
if(@SpentYears=1)
set @WorkVac=ISNULL((select 
	  VS.firstYearVac
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId and spentYears>=@SpentYears),0)
