愀挀愀琀椀漀渀猀⸀瘀愀挀匀琀愀爀琀䐀愀琀攀  㴀 䀀䐀愀琀攀䘀爀漀洀 ഀ਀ऀ 愀渀搀 䠀刀⸀䔀洀瀀氀漀礀攀攀嘀愀挀愀琀椀漀渀猀⸀瘀愀挀䔀渀搀䐀愀琀攀 㰀㴀 䀀䐀愀琀攀䘀爀漀洀 ഀ਀ऀ ⤀ ഀ਀ऀⰀ　⤀ഀ਀ⴀⴀ瀀爀椀渀琀 䀀倀爀攀瘀椀漀甀猀嘀愀挀愀琀椀漀渀䐀愀礀猀ഀ਀ऀⴀⴀ 䈀愀氀愀渀挀攀 椀昀 䠀攀 栀愀猀 漀瀀攀渀戀愀氀愀渀愀挀攀 开䔀洀瀀伀瀀攀渀䈀愀氀愀渀挀攀⸀䐀愀礀猀一甀洀戀攀爀 椀渀 挀甀爀爀攀渀琀 礀攀愀爀 攀氀猀攀 嘀愀挀愀琀椀漀渀 猀攀琀琀椀渀最 ഀ਀
declare @ExistBal int=ISNULL((select VOB.DaysNumber
from HR.VacationOpenBalance VOB
where VOB.EmpID = 
@EmpId
 and VOB.year= 
@year
  and VOB.VacationID= 
 @VacId
  ),0)
--print @ExistBal
if(@ExistBal= 0)
begin
 declare @defaultVac int=(select 
	  VS.vac_Days
	    from  HR.VacationSettings VS
		 where  VS.ID = @VacId)

declare @SpentYears int=(select datediff( YEAR,(select JoiningDate from Nursing.Employee where Id=@EmpId),@DateFrom  ))
declare @empAge int=(select datediff( YEAR,(select BirthDate from Nursing.Employee where Id=@EmpId),@DateFrom  ))
--print '1'
declare @AgeVac int=0,@WorkVac int=0 
--print ''+ @SpentYears
--print @empAge
--spent  1 year
if(@SpentYears=1)
set @WorkVac=ISNULL((select 
	  VS.firstYearVac
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId ),0)
--spent more than 1 year AND less than 10 Years 
if(@SpentYears>1 and @SpentYears<10)
set @WorkVac=ISNULL((select 
	  VS.vac_Days
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId ),0)
		 -- Spent more than 10 years 
if(@SpentYears>=(select 
	  VS.spentYears
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId))
		 begin
--Set @SpentYears = (select 
--	  VS.spentYears
--	    from  HR.VacationSettings VS 
--		 where VS.ID = @VacId)

set @WorkVac=ISNULL((select 
	  VS.vac_days_spent
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId ),0)
		 end
if(@WorkVac=0)
set @WorkVac=@defaultVac;
--print @defaultVac
if(@AgeVac >= (select 
	  VS.EmpAge
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId))
set @AgeVac=ISNULL((select 
	  VS.vac_days_age
	    from  HR.VacationSettings VS 
		 where VS.ID = @VacId and EmpAge>=@empAge),0)
--print @AgeVac
if(@AgeVac!=0  )
set @WorkVac=0;
--print @WorkVac
set @Balance=@WorkVac+ @AgeVac

set @RemainingDays = (@Balance - @PreviousVacationDays) 

 End
 Else
  set @RemainingDays = (@ExistBal - @PreviousVacationDays)
 
 --print @RemainingDays
 --end 
 RETURN @RemainingDays
END

GO
