CREATE VIEW [Pharmacy].[V_ItemPurch]
AS
SELECT     Pharmacy.GoodsReceivedNoteHeader.GRNNO, (Pharmacy.GoodsReceivedNoteDetails.AcceptQTY + Pharmacy.GoodsReceivedNoteDetails.BonusQTY) * Pharmacy.UnitConversionFactor.ConversionValue AS PurchQty, Pharmacy.GoodsReceivedNoteHeader.CreatedDate AS PurchDate, 
                  Pharmacy.GoodsReceivedNoteDetails.PriceFC * (Pharmacy.GoodsReceivedNoteDetails.AcceptQTY + Pharmacy.GoodsReceivedNoteDetails.BonusQTY) AS TAmountPurc, Pharmacy.GoodsReceivedNoteHeader.LPOId, Pharmacy.GoodsReceivedNoteHeader.OpeningBalance, 
