						 --DESC) AS rk

FROM
[InPatient].[AdmitPatients] adReq 
Left Join
[InPatient].[AdmissionRequest] admissionReq ON admissionReq.Id = adReq.AdmissionRequestID
Left JOIN
[InPatient].[AccommodationType] AccType on AccType.Id= adReq.AccomodationTypeID
and AccType.BranchId =adReq.BranchId
--Left JOIN
--[InPatient].[V_LastRoomTransfers] rt on  rt.AdmitPateintId = adReq.Id

WHERE        (adReq.DischargeStatusId != 4 OR adReq.DischargeStatusId IS NULL) 
OR
                         admissionReq.[Status] = 2
 












