/****** Object:  View [Radiology].[vw_GetInvestigationRequest]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Radiology].[vw_GetInvestigationRequest]
AS
SELECT DISTINCT 
                         IRH.OP_IPNumber, srf.DeviceType, IRH.Id, Pat.TranslatedFallName AS PatTranslatedFallName, ISNULL(Pat.FirstName, '') + ' ' + ISNULL(Pat.MiddleName1, '') + ' ' + ISNULL(Pat.MiddleName2, '') + ' ' + ISNULL(Pat.LastName, '') 
                         AS PatFullNameAr, IRH.BranchId
FROM            OutPatient.InvestigationRequestHeader AS IRH INNER JOIN
                         OutPatient.InvestigationRequestDetails AS IRD ON IRD.InvestigationRequestId = IRH.Id INNER JOIN
                         Radiology.vw_GetServicesForReceptions AS srf ON srf.Id = IRD.ServiceId INNER JOIN
                         Registration.Patients AS Pat ON Pat.Id = IRH.PatientID

GO
