					CREATE VIEW [Billing].[V_PatientBill]
					as

					SELECT --distinct
							InDeta.Id 
							,'Investigation Data' as DataType
						   ,[PatientID]
						  , InHea.[DoctorID]
						  ,[OP_IPNumber]
						  ,[SurgeryID]
						  ,InHea.[Code] RequestCode
						  ,InHea.ReqDate RequestDate
						  ,[Amount] ReqAmount
						  ,InDeta.[ServiceId] ItemId
						  ,[RecordName] ItemName
						  ,Ser.[Code] ItemCode
						  ,CASe when regP.SponserCategoryId > 0 then   [CustomerCategoryCostCentersID] else null end as [CustomerCategoryCostCentersID]
    
						  ,case when CtService.[IsDiscountByPer] = 1 and (select isnull(SponsorId,0) from Registration.Patients where Id=[PatientID]) > 0 then (CtService.[Discount] * [StdAmount])/100
								when (select isnull(SponsorId,0) from Registration.Patients where Id=[PatientID]) = 0  then 0 else CtService.[Discount] end  SupliesAmount
						   ,case when CtService.[Discount] is null then Ser.[Discount] else CtService.[Discount] end as [Discount]
