					  union all


						  SELECT 
						  ITC.Id 
						  ,'Telephone Charges' as DataType
						   ,ITC.PatientID  [PatientID]
						  --,[Type]
						  ,''[DoctorID]
						  ,ITC.LastIPNumber [OP_IPNumber]
      
						  ,NULL [SurgeryID]
						  ,'' RequestCode
						  ,'' RequestDate

						  ,ITC.Amount ReqAmount
						  --,[Priority]
						  ,0 ItemId

						  --,0 [CostCenterCompaniesId]
						  ,'RoomCharges'  ItemName
						  ,'' ItemCode

						  ,0 as [CustomerCategoryCostCentersID]
						  --,[ServiceID]
						  ,0 SupliesAmount
						   ,0 [Discount]
						   ,CONVERT(bit,0) [IsDiscountByPer]
