                         vp.Discount, vp.IsDiscountByPer, vp.IsApproval, vp.Deductible, vp.IsDeductibleByPer, vp.CustomerCategoryID, vp.PackageID, vp.DiscountByPer, vp.RecordType, vp.IsApproved, vp.PaymentType, vp.CompanyID, IRD.Cancelled,
                          IRD.Done, p.Code AS MRN, p.FirstName + ' ' + p.MiddleName1 + ' ' + p.MiddleName2 + ' ' + p.LastName AS PatientName, p.SponsorId, p.SponsorName, p.SponserCategoryId, p.SponserCategory, Billing.PatientBillservices.Vat+ 
                         Billing.PatientBillservices.AmountAfter as ReqAmount
FROM            Billing.V_PatientBill AS vp LEFT OUTER JOIN
                         Billing.PatientBillservices AS ps ON vp.RequestCode = ps.RequestNumber AND vp.ItemId = ps.ItemID INNER JOIN
                         Registration.Patients AS p ON vp.PatientID = p.Id INNER JOIN
                         Billing.PatientBillservices ON vp.OP_IPNumber = Billing.PatientBillservices.OP_IPNumber AND vp.ItemId = Billing.PatientBillservices.ItemID LEFT OUTER JOIN
                         OutPatient.InvestigationRequestDetails AS IRD ON ps.InvRequestDetID = IRD.Id
WHERE        (ps.ItemID IS NULL)
GO
