CREATE VIEW [dbo].[V_Transfer]  
AS
SELECT        GeneralStores.IssuetoDepartmentEntry.ItemID,
 GeneralStores.IssuetoDepartment.MainStockID, 
 GeneralStores.IssuetoDepartment.StockID, 
                         GeneralStores.IssuetoDepartmentEntry.IssueQty * GeneralStores.UnitConversionFactor.ConversionValue AS TransferQty, 
						 GeneralStores.IssuetoDepartment.CreatedDate AS TransferDate, GeneralStores.Items.CostPrice, 
                         GeneralStores.IssuetoDepartment.IssueNumber,
						  GeneralStores.Items.CostPrice * (GeneralStores.IssuetoDepartmentEntry.IssueQty * GeneralStores.UnitConversionFactor.ConversionValue) AS TransferValue, 
                         GeneralStores.Items.ItemName, 
						 GeneralStores.Items.ItemCode, 
						 GeneralStores.UnitConversionFactor.ConversionValue, 
						 GeneralStores.IssuetoDepartment.Status,
						  GeneralStores.IssuetoDepartmentEntry.IssueQty, 
