/****** Object:  View [dbo].[V_PhysicalAdjastment]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_PhysicalAdjastment]
AS
SELECT        dbo.V_PhysicalStockAdjastmentEntry.QtYDifference, GeneralStores.ItemClassification.Name AS ClassName, GeneralStores.ItemClassification.Id AS ClassID, GeneralStores.Stocks.StockName, GeneralStores.Items.ItemName, 
                         GeneralStores.Items.ItemCode, GeneralStores.Items.CostPrice * dbo.V_PhysicalStockAdjastmentEntry.QtYDifference AS AmountFC, dbo.V_PhysicalStockAdjastmentEntry.CreatedDate AS adjDate, 
                         dbo.V_PhysicalStockAdjastmentEntry.PhysiacalNO, dbo.V_PhysicalStockAdjastmentEntry.ItemID, dbo.V_PhysicalStockAdjastmentEntry.StockID, dbo.V_PhysicalStockAdjastmentEntry.QTYAdj, 
                         dbo.V_PhysicalStockAdjastmentEntry.QTYinHand, dbo.V_PhysicalStockAdjastmentEntry.BatchID, GeneralStores.Items.CostPrice
FROM            GeneralStores.ItemClassification RIGHT OUTER JOIN
                         dbo.V_PhysicalStockAdjastmentEntry INNER JOIN
                         GeneralStores.Items ON dbo.V_PhysicalStockAdjastmentEntry.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Stocks ON dbo.V_PhysicalStockAdjastmentEntry.StockID = GeneralStores.Stocks.ID ON GeneralStores.ItemClassification.Id = GeneralStores.Items.ClassificationId



