                         InPatient.RequestSupplyReturnDetails.CreatedDate AS RefundDate, dbo.V_dispenseItems.ItemID, dbo.V_dispenseItems.FirstName, dbo.V_dispenseItems.IPSellingPrice, dbo.V_dispenseItems.OPSellingPrice, 
                         dbo.V_dispenseItems.StockID, InPatient.RequestSupplyReturnDetails.ReturnedQty
FROM            InPatient.RequestSupplyReturnDetails INNER JOIN
                         InPatient.RequestSupplyReturnHeader ON InPatient.RequestSupplyReturnDetails.RequestSupplyReturnHeaderID = InPatient.RequestSupplyReturnHeader.ID INNER JOIN
                         GeneralStores.Items INNER JOIN
                         dbo.V_dispenseItems ON GeneralStores.Items.ID = dbo.V_dispenseItems.ItemID INNER JOIN
                         GeneralStores.Stocks ON dbo.V_dispenseItems.StockID = GeneralStores.Stocks.ID ON InPatient.RequestSupplyReturnDetails.RequestSupplyDetailsID = dbo.V_dispenseItems.RequestSuppliesDetailsID LEFT OUTER JOIN
                         GeneralStores.ItemClassification ON GeneralStores.Items.ClassificationId = GeneralStores.ItemClassification.Id



