/****** Object:  View [GeneralStores].[V_ItemPurch]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [GeneralStores].[V_ItemPurch]
AS
SELECT     GeneralStores.GoodsReceivedNoteDetails.ItemID, (GeneralStores.GoodsReceivedNoteDetails.AcceptQTY + GeneralStores.GoodsReceivedNoteDetails.BonusQTY) * GeneralStores.UnitConversionFactor.ConversionValue AS PurchQty, 
                  GeneralStores.GoodsReceivedNoteHeader.CreatedDate AS PurchDate, GeneralStores.GoodsReceivedNoteDetails.PriceFC * (GeneralStores.GoodsReceivedNoteDetails.AcceptQTY + GeneralStores.GoodsReceivedNoteDetails.BonusQTY) AS TAmountPurc, 
                  GeneralStores.GoodsReceivedNoteHeader.OpeningBalance, GeneralStores.Suppliers.SupplierName, GeneralStores.GoodsReceivedNoteDetails.ID, GeneralStores.GoodsReceivedNoteDetails.PriceFC, 
                  GeneralStores.GoodsReceivedNoteDetails.AcceptQTY * GeneralStores.UnitConversionFactor.ConversionValue AS ConversionAcceptQTY, GeneralStores.UnitConversionFactor.ConversionValue, GeneralStores.Units.UnitName, 
