create VIEW [GeneralStores].[V_ReturnPurch]
AS
SELECT DISTINCT 
                         GeneralStores.PurchaseReturnHeader.PurchaseReturnNumber, 
						 GeneralStores.PurchaseReturnDetails.ReturnQTY * [GeneralStores].V_ItemPurch.ConversionValue AS ReturnQTY, 
						 GeneralStores.PurchaseReturnHeader.GrnNo, 
                         GeneralStores.PurchaseReturnDetails.CreatedDate AS PRDate,
