CREATE  view [Pharmacy].[V_DispenseItemsReturn]
AS
SELECT  
Pharmacy.Substores.SubstoreNameAr  
,  
  Pharmacy.Substores.SubstoreName

, Pharmacy.DrugClassification.NameEn AS ClassName, Pharmacy.DrugClassification.Id AS ClassID, Pharmacy.Drugs.DrugFormID,
 Pharmacy.Drugs.DrugName, Pharmacy.Drugs.DrugNameAr ,
                         InPatient.RequestSupplyReturnHeader.RequestSupplyRetuenCode AS ReturnReceiptNo, InPatient.RequestSupplyReturnDetails.ReturnedQty * Pharmacy.V_DispenseItems.ConversionValue AS ReturnQty, 
                         InPatient.RequestSupplyReturnDetails.CreatedDate AS RefundDate, Pharmacy.V_DispenseItems.FirstName, Pharmacy.V_DispenseItems.IPSellingPrice, Pharmacy.V_DispenseItems.OPSellingPrice, 
                         Pharmacy.V_DispenseItems.StockID AS SubstoreID, InPatient.RequestSupplyReturnDetails.ReturnedQty, Pharmacy.Drugs.ID, Pharmacy.V_DispenseItems.DrugID, Pharmacy.Drugs.DrugCode
FROM            Pharmacy.Drugs INNER JOIN
                         Pharmacy.Substores INNER JOIN
                         Pharmacy.V_DispenseItems ON Pharmacy.Substores.ID = Pharmacy.V_DispenseItems.StockID INNER JOIN
                         InPatient.RequestSupplyReturnDetails INNER JOIN
                         InPatient.RequestSupplyReturnHeader ON InPatient.RequestSupplyReturnDetails.RequestSupplyReturnHeaderID = InPatient.RequestSupplyReturnHeader.ID ON 
                         Pharmacy.V_DispenseItems.RequestSuppliesDetailsID = InPatient.RequestSupplyReturnDetails.RequestSupplyDetailsID ON Pharmacy.Drugs.ID = Pharmacy.V_DispenseItems.DrugID LEFT OUTER JOIN
