/****** Object:  UserDefinedFunction [GL].[GetAccountPrevD]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE FUNCTION [GL].[GetAccountPrevD] 
(
	@FDate as date,
	@AccountID INT
)         
RETURNS TABLE 
AS
RETURN 
(
	-- Add the SELECT statement with parameter references here
SELECT SUM(GL.JournalDetails.LocalDebit - GL.JournalDetails.LocalCredit) AS total,@FDate as accDate,'-' as serial,
case when (SUM(GL.JournalDetails.LocalDebit - GL.JournalDetails.LocalCredit) >=0) then SUM(GL.JournalDetails.LocalDebit - GL.JournalDetails.LocalCredit) else 0 end as prevDebitT,
case when (SUM(GL.JournalDetails.LocalDebit - GL.JournalDetails.LocalCredit)<=0) then SUM(GL.JournalDetails.LocalDebit - GL.JournalDetails.LocalCredit)*-1 else 0 end as prevCreditT,@AccountID as ID
FROM            GL.JournalDetails INNER JOIN
                         GL.Journal ON GL.JournalDetails.JournalId = GL.Journal.JournalId
WHERE     (GL.Journal.IsDeleted= 0 or GL.Journal.IsDeleted is null) and    (GL.Journal.Date < @FDate) and (GL.JournalDetails.AccountId = @AccountID))


GO
