CREATE VIEW [ApplicationSetup].[VuClincalDet_Service]
AS
SELECT        ApplicationSetup.Service.NameEn, ApplicationSetup.Service.NameAr, ApplicationSetup.ClinicalCareDetails.Id
FROM            ApplicationSetup.ClinicalCareDetails INNER JOIN
                         ApplicationSetup.Service ON ApplicationSetup.ClinicalCareDetails.ServiceID = ApplicationSetup.Service.Id




