CREATE VIEW [ApplicationSetup].[vw_getNewDrugs]
AS
SELECT        Id, RecordName, Code, NameAr, NameEn
FROM            ApplicationSetup.Service
WHERE        (Id NOT IN
                             (SELECT        ServiceId
                               FROM            Pharmacy.Drugs)) AND (ItemType = 4)


