SELECT        Billing.PatientBillservices.Id, Billing.InsuranceCompanies.NameEnglish, Billing.InsuranceCompanies.NameArabic, Registration.Patients.Code AS PatientCode, Registration.Patients.Id AS PatientID, 
                         Registration.Patients.FirstName, Registration.Patients.MiddleName1, Registration.Patients.MiddleName2, Registration.Patients.LastName, Billing.ins_Company_Class.Code AS CompanyClassCode, 
                         Billing.ins_Company_Class.ClassNO, Billing.Ins_Company_Policy.Code AS Ins_Company_PolicyCode, Billing.Ins_Company_Policy.PolicyName, Billing.Ins_Company_Policy.PolicyNo, 
                         Billing.InsuranceCompanies.Code AS Inc_Code, Billing.PatientBill.PatientName, Billing.PatientBillservices.OP_IPNumber, Billing.PatientBillservices.SponsorName, Billing.PatientBill.IsEndVisit, 
                         Billing.PatientBillservices.SponserPaidAmount, Billing.PatientBillservices.PateintPaidAmount, Billing.InsuranceCompanies.ID AS InsuranceID, Billing.PatientBillservices.Paid, Registration.Patients.PatientType, 
                         Billing.PatientBill.Status, Billing.PatientBillservices.ISCash, Billing.PatientBillservices.SponserId, Billing.PatientBill.CreatedDate AS InvoiceDate, Registration.Patients.TranslatedFallName, Billing.PatientBillservices.PatVat, 
                         Billing.PatientBillservices.Vat, Billing.PatientBillservices.Vat - Billing.PatientBillservices.PatVat AS SponVat
FROM            Registration.Patients INNER JOIN
                         Billing.PatientBillservices INNER JOIN
                         Billing.PatientBill ON Billing.PatientBillservices.PatientBillID = Billing.PatientBill.Id ON Registration.Patients.Id = Billing.PatientBill.PatientID INNER JOIN
                         Billing.ins_Company_Class INNER JOIN
                         Billing.InsuranceCompanies INNER JOIN
                         Registration.PatientInsurance ON Billing.InsuranceCompanies.ID = Registration.PatientInsurance.SponsorId INNER JOIN
