                         Receivable.PatientPackagePaymentDetails.EmpName, Receivable.PatientPackagePaymentDetails.Cash, Receivable.PatientPackagePaymentDetails.Visa, Receivable.PatientPackagePaymentDetails.ReciptNo, 
                         Registration.Nationalities.Name, Registration.Nationalities.NameEn, HR.SubDepartment.Name AS DeptAr, HR.SubDepartment.NameEn AS DeptEn, Receivable.PatientPackagePaymentMaster.SpoVat, 
                         Receivable.PatientPackagePaymentMaster.SponserPaidAmount
FROM            Receivable.PatientPackagePaymentDetails INNER JOIN
                         Receivable.PatientPackagePaymentMaster ON Receivable.PatientPackagePaymentDetails.PatientPackagePaymentID = Receivable.PatientPackagePaymentMaster.Id INNER JOIN
                         ApplicationSetup.Service ON Receivable.PatientPackagePaymentMaster.PackageID = ApplicationSetup.Service.Id INNER JOIN
                         Registration.Patients AS p ON Receivable.PatientPackagePaymentMaster.PatientID = p.Id INNER JOIN
                         OutPatient.InvestigationRequestHeader ON Receivable.PatientPackagePaymentMaster.PatientID = OutPatient.InvestigationRequestHeader.PatientID AND p.Id = OutPatient.InvestigationRequestHeader.PatientID INNER JOIN
                         OutPatient.InvestigationRequestDetails ON ApplicationSetup.Service.Id = OutPatient.InvestigationRequestDetails.ServiceId AND 
                         OutPatient.InvestigationRequestDetails.InvestigationRequestId = OutPatient.InvestigationRequestHeader.Id AND Receivable.PatientPackagePaymentMaster.InvdtlId = OutPatient.InvestigationRequestDetails.Id INNER JOIN
                         ApplicationSetup.QRImage ON Receivable.PatientPackagePaymentMaster.PatientID = ApplicationSetup.QRImage.PatID AND Receivable.PatientPackagePaymentDetails.Id = ApplicationSetup.QRImage.InvoiceId INNER JOIN
                         Registration.Doctors ON OutPatient.InvestigationRequestHeader.DoctorID = Registration.Doctors.Id INNER JOIN
                         HR.SubDepartment ON Registration.Doctors.DepartmentId = HR.SubDepartment.ID LEFT OUTER JOIN
