CREATE VIEW [Billing].[V_PurchaseReportPharmacy20220109]
AS
SELECT   
 Pharmacy.Suppliers.SupplierName ,
  
CASE
         WHEN EXISTS(SELECT [GeneralStores].[Tax].PharmacyTaxPercentage
                     FROM   [GeneralStores].[Tax]
                    ) 
           THEN ('')
         ELSE ''
       END  AS TaxPercentage

,Pharmacy.GoodsReceivedNoteHeader.TaxValue as TaxValue
,Pharmacy.GoodsReceivedNoteHeader.SetEntryCode as GRNCode
,
Pharmacy.GoodsReceivedNoteHeader.TaxValue as VatValue 
 ,Pharmacy.Suppliers.SupplierCode
  ,
 "EntryCodes" = 
  CASE 
     WHEN  Pharmacy.PharmacyPayment.SetEntryCode is null THEN 0.0
  ELSE Pharmacy.PharmacyPayment.SetEntryCode
  END ,
"PaymentType" = 
  CASE 
     WHEN  Pharmacy.PharmacyPayment.PaymentMode=  1 THEN 'Cash'
 WHEN  Pharmacy.PharmacyPayment.PaymentMode is null THEN ''
     ELSE 'Bank'
  END  ,
  SUM ( Pharmacy.GoodsReceivedNoteDetails.AmountFC ) as AmountFC
