CREATE VIEW [Billing].[V_SalesDetails]
AS
SELECT        vp.PatientAmount, vp.SponsorAmount, vp.TotalAmount, vp.PatientID, ps.OP_IPNumber AS IPOPNo, vp.Paid AS BillPaid, vp.PatPaidAfterReverse, vp.CompanyID, ps.PatientBillID, ps.Id, ps.ItemID, ps.ItemName, ps.ItemCode, 
                         ps.Amount, ps.Paid AS BillServicePaid, ps.SupliesAmount, ps.Reverse, ps.AmountBefore, ps.Discount, ps.Vat, ps.CreatedDate AS CreatedDate, ps.IsService, p.Code AS MRN, 
                         p.FirstName + ' ' + p.MiddleName1 + ' ' + p.MiddleName2 + ' ' + p.LastName AS PatientName, serv.ServiceType, vp.IsEndVisit, ps.DoctorID, ps.SponserId AS ServiceSponserId, ps.BillReceipts, ps.ISCash, ps.ApprovedCode, 
                         ps.Fee_Type, ps.PateintPaidAmount, ps.SponserPaidAmount, ps.Quantity, ps.IsBooking, ps.ClinicId, ps.SponserCategoryId, ps.SponserCategory, ps.SponsorName, ps.SponserId AS SponsorId, ps.AmountAfter, ps.VisitSlipID, 
                         ps.InvRequestDetID, ps.discountVal, ps.PatVat, ps.SpoVat, ps.Canceled, ps.CanceledDate, ps.CanceledBy, ps.Paid, Registration.Nationalities.NameEn AS Nat_NameEn, Registration.Nationalities.Name AS Nat_NameAr, 
                         Registration.Nationalities.Citizen, Billing.InsuranceCompanies.NameEnglish AS Ins_nameEn, Billing.InsuranceCompanies.NameArabic AS Ins_nameAr, Billing.InsuranceCompanies.VAT_No, serv.taxable, serv.ItemType, 
                         ps.LastModifiedDate
FROM            Billing.PatientBill AS vp INNER JOIN
                         Billing.PatientBillservices AS ps ON vp.Id = ps.PatientBillID INNER JOIN
                         Registration.Patients AS p ON vp.PatientID = p.Id LEFT OUTER JOIN
                         Billing.InsuranceCompanies ON ps.SponserId = Billing.InsuranceCompanies.ID LEFT OUTER JOIN
                         Registration.Nationalities ON p.NationalityId = Registration.Nationalities.Id LEFT OUTER JOIN
                         ApplicationSetup.Service AS serv ON serv.Id = ps.ItemID
WHERE        (ps.Paid = 1)

GO
