/****** Object:  View [Billing].[V_VoucherGroup]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Billing].[V_VoucherGroup]
AS
SELECT       ROW_NUMBER() OVER (ORDER BY v.BoxID ASC) AS ID,   v.BoxID, CONVERT(date, v.CreatedDate) AS CD, v.VoucherType, SUM(vd.Amount) AS Amount
FROM            Billing.Voucher AS v INNER JOIN
                         Billing.VoucherDetails AS vd ON v.ID = vd.VoucherID
GROUP BY v.BoxID, CONVERT(date, v.CreatedDate), v.VoucherType





GO
