SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO







/****** Script for SelectTopNRows command from SSMS  ******/
CREATE VIEW [Billing].[view_CustomerMaster_report]
as
SELECT        Billing.CustomerMaster.CustomerCode, Billing.CustomerMaster.IsActive, Billing.CustomerMaster.Address, ApplicationSetup.City.Name, 
                         Registration.Nationalities.Name AS Nationalities, Billing.CustomerMaster.CustomerName, Billing.CustomerMaster.Email, Billing.CustomerMaster.POBox, 
                         Billing.CustomerMaster.ZipCode, Billing.CustomerMaster.Notes
FROM            Billing.CustomerMaster INNER JOIN
                         ApplicationSetup.City ON Billing.CustomerMaster.CityID = ApplicationSetup.City.Id INNER JOIN
                         Registration.Nationalities ON Billing.CustomerMaster.NationalityID = Registration.Nationalities.Id






GO
