/****** Object:  View [dbo].[V_DosagePrint]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[V_DosagePrint]
AS
SELECT        Pd.Dosage, F.Name, Pd.Period, CASE WHEN Pd.TypeId = 1 THEN 'Year' WHEN Pd.TypeId = 2 THEN 'Month' ELSE 'Day' END AS PeriodName, CASE WHEN Pd.TypeId = 1 THEN (24 / F.Value) 
                         * 365 * Period WHEN Pd.TypeId = 2 THEN (24 / F.Value) * 30 * Period ELSE (24 / F.Value) * Period END AS DoseCount, P.TranslatedFallName, P.Code, Pd.Id, Pd.StartDate, Pd.StartTime, Pd.EndDate, Pd.EndTime, 1 AS No
FROM            OutPatient.PrescriptionsDetails AS Pd INNER JOIN
                         Pharmacy.Frequencies AS F ON F.Id = Pd.FrequencyID INNER JOIN
                         Registration.Patients AS P ON P.Id = Pd.PatientID

GO
/****** Object:  View [dbo].[V_Excel]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_Excel]
AS
SELECT        GeneralStores.Batches.BatchNo, GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, GeneralStores.Units.UnitName, GeneralStores.StockControl.StockOnHand, GeneralStores.StockBatches.BatchId, 
                         GeneralStores.Stocks.StockName
FROM            GeneralStores.Stocks INNER JOIN
                         GeneralStores.StockControl INNER JOIN
                         GeneralStores.Items ON GeneralStores.StockControl.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.UnitTemplate INNER JOIN
                         GeneralStores.Units ON GeneralStores.UnitTemplate.BaseUnitID = GeneralStores.Units.ID ON GeneralStores.Items.BaseUnitID = GeneralStores.Units.ID ON 
                         GeneralStores.Stocks.ID = GeneralStores.StockControl.StockID LEFT OUTER JOIN
                         GeneralStores.StockBatches INNER JOIN
                         GeneralStores.Batches ON GeneralStores.StockBatches.BatchId = GeneralStores.Batches.Id ON GeneralStores.StockControl.StockID = GeneralStores.StockBatches.StockID



GO
