CREATE VIEW [dbo].[V_PHARMACY_LPO_GRN]
AS
SELECT     Pharmacy.GRN_LPOs.LPOID, Pharmacy.GRN_LPOs.GRNID, Pharmacy.GoodsReceivedNoteHeader.GRNDate, Pharmacy.GoodsReceivedNoteHeader.PaymentTermsID, Pharmacy.GoodsReceivedNoteHeader.DeliveryNoteDate, Pharmacy.GoodsReceivedNoteHeader.DeliveryNoteNo, 
                  Pharmacy.GoodsReceivedNoteHeader.InvoiceNO, Pharmacy.GoodsReceivedNoteHeader.InvoiceDate, Pharmacy.GoodsReceivedNoteHeader.TotalExpensesAmount, Pharmacy.GoodsReceivedNoteHeader.TotallandedAmount, Pharmacy.GoodsReceivedNoteHeader.TotalGRNValueFC, 
                  Pharmacy.GoodsReceivedNoteHeader.TotalGRNValueLC, Pharmacy.GoodsReceivedNoteHeader.GRNPreparedDate, Pharmacy.GoodsReceivedNoteHeader.Remarks, Pharmacy.GoodsReceivedNoteHeader.Status, Pharmacy.GoodsReceivedNoteHeader.ISOpeneingStock, 
                  Pharmacy.GoodsReceivedNoteHeader.CreatedBy, Pharmacy.GoodsReceivedNoteHeader.CreatedDate, Pharmacy.GoodsReceivedNoteHeader.LastModifiedBy, Pharmacy.GoodsReceivedNoteHeader.LastModifiedDate, Pharmacy.GoodsReceivedNoteHeader.CompanyID, 
                  Pharmacy.GoodsReceivedNoteHeader.TaxValue, Pharmacy.GoodsReceivedNoteHeader.TransType_ID, Pharmacy.GoodsReceivedNoteHeader.Direct, Pharmacy.GoodsReceivedNoteHeader.OpeningBalance, Pharmacy.GoodsReceivedNoteHeader.issueToDepartment, 
                  Pharmacy.GoodsReceivedNoteHeader.StockID, Pharmacy.GoodsReceivedNoteHeader.SetEntryCode, Pharmacy.GoodsReceivedNoteHeader.SupplierId, Pharmacy.GoodsReceivedNoteHeader.GRNNO, Pharmacy.GoodsReceivedNoteHeader.ID
FROM        Pharmacy.GoodsReceivedNoteHeader INNER JOIN
                  Pharmacy.GRN_LPOs ON Pharmacy.GoodsReceivedNoteHeader.ID = Pharmacy.GRN_LPOs.GRNID

GO
