/****** Object:  View [dbo].[V_StockBatch]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_StockBatch]
AS
SELECT        GeneralStores.StockBatches.Id, GeneralStores.StockBatches.ReceivedQty, GeneralStores.StockBatches.AcceptedQty, GeneralStores.StockBatches.AvailableQty, GeneralStores.UnitConversionFactor.ConversionValue, 
                         GeneralStores.GoodsReceivedNoteDetails.UnitConversionFactorId, GeneralStores.StockBatches.BatchId, GeneralStores.Units.UnitName, GeneralStores.UnitTemplate.UnitTemplateName, 
                         GeneralStores.Batches.GRNDetailsId
FROM            GeneralStores.StockBatches INNER JOIN
                         GeneralStores.Batches ON GeneralStores.StockBatches.BatchId = GeneralStores.Batches.Id INNER JOIN
                         GeneralStores.UnitConversionFactor INNER JOIN
                         GeneralStores.GoodsReceivedNoteDetails ON GeneralStores.UnitConversionFactor.ID = GeneralStores.GoodsReceivedNoteDetails.UnitConversionFactorId INNER JOIN
                         GeneralStores.Units ON GeneralStores.UnitConversionFactor.UnitID = GeneralStores.Units.ID INNER JOIN
                         GeneralStores.UnitTemplate ON GeneralStores.UnitConversionFactor.UnitTemplateID = GeneralStores.UnitTemplate.ID ON GeneralStores.Batches.GRNDetailsId = GeneralStores.GoodsReceivedNoteDetails.ID



GO
