/****** Object:  View [dbo].[V_SupplierPurchaseDetailsReturn]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[V_SupplierPurchaseDetailsReturn]
AS
SELECT        GeneralStores.PurchaseReturnHeader.PurchaseReturnNumber, GeneralStores.PurchaseReturnDetails.ReturnQTY, GeneralStores.Stocks.StockName, GeneralStores.GoodsReceivedNoteDetails.ItemID, 
                         GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, GeneralStores.GoodsReceivedNoteDetails.AmountFC, GeneralStores.LocalPurchaseOrderHeader.SupplierID, 
                         GeneralStores.PurchaseReturnHeader.CreatedDate AS RPurchDate, GeneralStores.ItemClassification.Name AS ClassName, GeneralStores.ItemClassification.Id AS ClassID, GeneralStores.StockBatches.StockID, 
                         GeneralStores.Suppliers.SupplierName AS Name
FROM            GeneralStores.LocalPurchaseOrderHeader INNER JOIN
 GeneralStores.GRN_LPOs on GeneralStores.GRN_LPOs.LPOID=GeneralStores.LocalPurchaseOrderHeader.ID inner join
                       
                       
                         GeneralStores.GoodsReceivedNoteHeader ON GeneralStores.GRN_LPOs.GRNID = GeneralStores.GoodsReceivedNoteHeader.id INNER JOIN
                         GeneralStores.PurchaseReturnDetails INNER JOIN
                         GeneralStores.PurchaseReturnHeader ON GeneralStores.PurchaseReturnDetails.PurchaseReturnHeaderId = GeneralStores.PurchaseReturnHeader.ID INNER JOIN
                         GeneralStores.StockBatches ON GeneralStores.PurchaseReturnDetails.StockBatchesId = GeneralStores.StockBatches.Id INNER JOIN
                         GeneralStores.Stocks ON GeneralStores.StockBatches.StockID = GeneralStores.Stocks.ID INNER JOIN
                         GeneralStores.Batches ON GeneralStores.StockBatches.BatchId = GeneralStores.Batches.Id INNER JOIN
