CREATE VIEW [dbo].[View_2]
AS
SELECT        InPatient.RequestSuppliesHeader.RequestNo, InPatient.RequestSuppliesHeader.CreatedDate, InPatient.RequestSuppliesDetails.Quantity, GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, 
                         InPatient.RequestSuppliesDetails.UnitConversionID, GeneralStores.Units.UnitName, Registration.Patients.Id, Registration.Patients.FirstName, Registration.Patients.MiddleName2, Registration.Patients.MiddleName1, 
                         Registration.Patients.LastName, Registration.Patients.TranslatedFallName
FROM            Registration.Patients INNER JOIN
                         InPatient.RequestSuppliesHeader ON Registration.Patients.Id = InPatient.RequestSuppliesHeader.PatientID INNER JOIN
                         InPatient.RequestSuppliesDetails ON InPatient.RequestSuppliesHeader.Id = InPatient.RequestSuppliesDetails.RequestSuppliesHeaderID INNER JOIN
                         GeneralStores.Items ON InPatient.RequestSuppliesDetails.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Units ON InPatient.RequestSuppliesDetails.UnitConversionID = GeneralStores.Units.ID INNER JOIN
                         Billing.PatientBill ON Registration.Patients.Id = Billing.PatientBill.Id



GO
