SELECT        Registration.Patients.MiddleName1, Registration.Patients.LastName, Registration.Patients.MiddleName2, Registration.Patients.Code, Registration.Patients.Id, Registration.Patients.FirstName, 
                         OutPatient.PrepareVisitSlip.OPnumber, OutPatient.PrepareVisitSlip.Time, OutPatient.PrepareVisitSlip.TimeOfVisit, OutPatient.PrepareVisitSlip.referralDepartmentID, OutPatient.PrepareVisitSlip.referralClinicID, 
                         OutPatient.PrepareVisitSlip.referralDoctorsID, OutPatient.PrepareVisitSlip.MedicoLegalID, OutPatient.PrepareVisitSlip.VisitStatus, OutPatient.PrepareVisitSlip.VisitNo, OutPatient.PrepareVisitSlip.Remarks, 
                         OutPatient.PrepareVisitSlip.NoCharge, OutPatient.PrepareVisitSlip.OPNumberStatus, OutPatient.PrepareVisitSlip.Purpose, OutPatient.PrepareVisitSlip.IsApproved, OutPatient.PrepareVisitSlip.VisitType, 
                         Registration.Doctors.Name AS [Doctor Name], Registration.Doctors.DepartmentId, ApplicationSetup.CostCenter.Name AS [Department Name], Registration.GenericClinics.Clinic, Registration.Patients.MobileNumber, 
                         Registration.Patients.DateOfBirth, OutPatient.PrepareVisitSlip.CreatedDate
FROM            ApplicationSetup.CostCenter INNER JOIN
                         Registration.Patients INNER JOIN
                         OutPatient.PrepareVisitSlip ON Registration.Patients.Id = OutPatient.PrepareVisitSlip.PatientID INNER JOIN
                         Registration.Doctors ON OutPatient.PrepareVisitSlip.DoctorsID = Registration.Doctors.Id ON ApplicationSetup.CostCenter.Id = Registration.Doctors.DepartmentId INNER JOIN
                         Registration.GenericClinics ON Registration.Doctors.GenericClinicID = Registration.GenericClinics.Id



