                         ISNULL(Employee_2.FirstName, '') + ' ' + ISNULL(Employee_2.MiddleName, '') + ' ' + ISNULL(Employee_2.BeforeLastName, '') + ' ' + ISNULL(Employee_2.LastName, '') AS InventoryManagerFullNameAr, 
                         ISNULL(Employee_2.FirstNameEn, '') + ' ' + ISNULL(Employee_2.MiddleNameEn, '') + ' ' + ISNULL(Employee_2.BeforeLastNameEn, '') + ' ' + ISNULL(Employee_2.LastNameEn, '') AS InventoryManagerFullNameEn, 
                         CASE [GeneralStores].[ItemRequestMaster].[ItemRequestMasterStatus] WHEN 2 THEN datediff(MINUTE, [GeneralStores].[ItemRequestMaster].[CreatedDate], getdate()) ELSE datediff(MINUTE, 
                         [GeneralStores].[ItemRequestMaster].[CreatedDate], [GeneralStores].[ItemRequestMaster].DepartmentManagerEmployeeActionDate) END AS DiffManager, 
                         GeneralStores.ItemRequestMaster.DepartmentManagerEmployeeActionDate
FROM            GeneralStores.InventorySettings INNER JOIN
                         Nursing.Employee AS Employee_2 ON GeneralStores.InventorySettings.InventoryManagerEmployeeID = Employee_2.Id CROSS JOIN
                         GeneralStores.ItemRequestMaster INNER JOIN
                         Nursing.Employee ON GeneralStores.ItemRequestMaster.RequesterEmployeeID = Nursing.Employee.Id INNER JOIN
                         GeneralStores.ItemRequestDetails ON GeneralStores.ItemRequestMaster.ID = GeneralStores.ItemRequestDetails.MasterID INNER JOIN
                         GeneralStores.Items ON GeneralStores.ItemRequestDetails.Items = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Units ON GeneralStores.ItemRequestDetails.Units = GeneralStores.Units.ID INNER JOIN
                         HR.SubDepartment ON GeneralStores.ItemRequestMaster.SubDepartment = HR.SubDepartment.ID INNER JOIN
                         Nursing.Employee AS Employee_1 ON HR.SubDepartment.ManagerEmployeeID = Employee_1.Id
WHERE        (GeneralStores.ItemRequestMaster.ID >= 1038) AND (GeneralStores.ItemRequestMaster.ItemRequestMasterStatus = 2 OR
                         GeneralStores.ItemRequestMaster.ItemRequestMasterStatus = 3) AND (GeneralStores.ItemRequestDetails.ItemStatusID = 1)

