/****** Object:  View [dbo].[Vw_EclaimPrescription]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[Vw_EclaimPrescription]
AS
SELECT        Pharmacy.Frequencies.Value, Pharmacy.Frequencies.Name, Pharmacy.Drugs.SFDA, OutPatient.PrescriptionsHeader.OPNumber, Pharmacy.Drugs.ServiceId
FROM            Pharmacy.Drugs INNER JOIN
                         OutPatient.PrescriptionsDetails ON Pharmacy.Drugs.ID = OutPatient.PrescriptionsDetails.DrugID INNER JOIN
                         OutPatient.PrescriptionsHeader ON OutPatient.PrescriptionsHeader.Id = OutPatient.PrescriptionsDetails.PrescriptionID INNER JOIN
                         Pharmacy.Frequencies ON Pharmacy.Frequencies.Id = OutPatient.PrescriptionsDetails.FrequencyID

GO
/****** Object:  View [dbo].[vw_getNewDrugs]    Script Date: 8/27/2026 2:35:45 PM ******/
