CREATE VIEW [dbo].[vw_getNewDrugs]
AS
SELECT  Id, RecordName, Code, NameAr, NameEn

FROM  ApplicationSetup.Service
where  ApplicationSetup.Service.itemtype=4
EXCEPT
SELECT ServiceId,DrugName,DrugCode,DrugNameAr,DrugName 
FROM Pharmacy.drugs ;

GO
