/****** Script for SelectTopNRows command from SSMS  ******/
CREATE VIEW [GeneralStores].[V_DosageSession_Report]
AS

 --row_number() over ( order by sub.[ID]) as ID
SELECT        DosageSessionName,SUBSTRING( CONVERT(nvarchar,DosageSessionTime),0,9) as DosageSessionTime
FROM            GeneralStores.DosageSession










