/****** Object:  View [GeneralStores].[V_itemClassification]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


create VIEW [GeneralStores].[V_itemClassification]
AS
SELECT        GeneralStores.ItemClassification.Name AS ClassName, GeneralStores.ItemClassification.Id AS ClassID, GeneralStores.Items.ItemName, GeneralStores.Items.ID, GeneralStores.Items.ItemCode
FROM            GeneralStores.Items LEFT OUTER JOIN
                         GeneralStores.ItemClassification ON GeneralStores.Items.ClassificationId = GeneralStores.ItemClassification.Id




