/****** Object:  View [GeneralStores].[VPurchaseInvoice]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


--select * from  [GeneralStores].[VPurchaseInvoice]  

CREATE View [GeneralStores].[VPurchaseInvoice]  
	              
AS

select cast(ROW_NUMBER() OVER(ORDER BY (SELECT 1)) as int) as id, sum(taxes)as texes,year(grndate) as Year,sum((AcceptQTY*PriceLC)-DiscountAmount ) as Amount
from( 
Select *
  ,Tbl1.AmountFC+Tbl1.Taxes as NetAmount from (
SELECT distinct  GeneralStores.GoodsReceivedNoteHeader.GRNNO , 
         GeneralStores.GoodsReceivedNoteHeader.GRNDate,
		 GeneralStores.GoodsReceivedNoteHeader.Status,
