/****** Object:  View [GL].[GetMonthlyBalance]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [GL].[GetMonthlyBalance]
as
SELECT        GL.FiscalYearDetails.CompanyID, GL.FiscalYearDetails.IsClose, GL.FiscalYearHeader.IsClose AS FiscalYearHeaderIsClose, GL.FiscalYearDetails.DateFrom, GL.FiscalYearDetails.DateTo, 
                         GL.FiscalYearDetails.Id AS MFiscalYearHeader
FROM            GL.FiscalYearDetails INNER JOIN
                         GL.FiscalYearHeader ON GL.FiscalYearDetails.FiscalYearHeaderId = GL.FiscalYearHeader.Id


GO
/****** Object:  View [GL].[V_allCapitalShare]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [GL].[V_allCapitalShare] as
WITH cte AS (

SELECT a.Id
,a.AccountNo+'  -  '+a.AcountNameEn as AcName
,a.AccountNo+'  -  '+a.AccountNameAr as AcNameAr
,a.[MainAccountNo],AccountNo,AccountLevel,0 as Levell
,a.AccountType
FROM [GL].[accounts]  a
WHERE 
id = (select ShareCapital from GL.GLSetting)
UNION ALL   SELECT a.Id
				  ,a.AccountNo+'  -  '+a.AcountNameEn as AcName
				  ,a.AccountNo+'  -  '+a.AccountNameAr as AcNameAr
				  ,a.[MainAccountNo],a.AccountNo,a.AccountLevel,c.Levell+1 Levell
				  ,a.AccountType
		    FROM [GL].[accounts] a JOIN cte c ON a.[MainAccountNo] = c.id 
			where a.[MainAccountNo]<>'#'
			
)
select * from cte




