/****** Object:  View [GL].[vw_GetJournalDetails]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [GL].[vw_GetJournalDetails]
AS
SELECT        GL.accounts.id AS AccountID, GL.accounts.AccountNo, GL.accounts.AccountNameAr, GL.accounts.AcountNameEn, GL.Journal.TotalDebitCredit, GL.JournalDetails.Description, GL.JournalDetails.Debit, GL.JournalDetails.Credit, 
                         GL.JournalDetails.LocalCredit, GL.JournalDetails.LocalDebit, GL.JournalDetails.CurrencyRate, GL.Journal.Serial, GL.Journal.JournalId, ApplicationSetup.Currency.Name, GL.DetailsCostCenter.Value, GL.CostCenter.CenterNo, 
                         GL.JournalDetails.JournalDetailsId, GL.accounts.CostCenterDistributionId, GL.Journal.Date, GL.accounts.IsDebit, GL.accounts.id, GL.JournalDetails.CurrencyId, ApplicationSetup.Currency.NameAr, GL.Journal.isPosted
FROM            GL.Journal INNER JOIN
                         GL.JournalDetails ON GL.Journal.JournalId = GL.JournalDetails.JournalId INNER JOIN
                         GL.accounts ON GL.JournalDetails.AccountId = GL.accounts.id LEFT OUTER JOIN
                         GL.DetailsCostCenter ON GL.JournalDetails.JournalDetailsId = GL.DetailsCostCenter.JournalDetailsId INNER JOIN
                         ApplicationSetup.Currency ON GL.JournalDetails.CurrencyId = ApplicationSetup.Currency.Id LEFT OUTER JOIN
                         GL.CostCenter ON GL.DetailsCostCenter.CostCenterId = GL.CostCenter.CostCenterId

GO
