                                                    >= cast(CONVERT(char(8), dateadd(day, [HR].[HieringDocumentGroupFile].[DaysBeforeNotify] * - 1, [HR].[HieringDocumentEmployeeFile].[ExpiryDate]), 112) AS bigint)) AS tt

