CREATE VIEW [HR].[vw_GetHousingData]
AS
SELECT    distinct 

Nursing.Employee.Id as employeeId,
HR.HousingReport.HousingId,
 HR.HousingReport.VacationPreventType1,
  HR.HousingReport.StartDate1,
   HR.HousingReport.EndDate1,
    HR.HousingReport.DiscountDays1, 
                         HR.HousingReport.TransferResult1, 
						 HR.HousingReport.VacationPreventType2,
						  HR.HousingReport.StartDate2, 
						  HR.HousingReport.EndDate2,
						   HR.HousingReport.DiscountDays2,
						    HR.HousingReport.TransferResult2, 
                         HR.HousingReport.VacationPreventType3, 
						 HR.HousingReport.EndDate3, 
						 HR.HousingReport.StartDate3,
						  HR.HousingReport.DiscountDays3,
						   HR.HousingReport.TransferResult3,
						    HR.HousingReport.VacationPreventType4, 
                         HR.HousingReport.StartDate4,
						  HR.HousingReport.EndDate4,
						   HR.HousingReport.DiscountDays4,
						    HR.HousingReport.TransferResult4,
							 Nursing.Employee.FirstNameEn +' '+ Nursing.Employee.MiddleNameEn+' '+
							 Nursing.Employee.LastNameEn as employeeNameEN,
							   
                         
						  Nursing.Employee.FirstNameAr +' '+  Nursing.Employee.MiddleNameAr +' '+Nursing.Employee.LastNameAr as employeeNameAr, 
						 
						   
						    Nursing.Employee.NationalID,
							 HR.JobDegree.JobdegreeDescription, 
                         HR.JobDegree.JobdegreeDescriptionAr, 
