CREATE VIEW [InfectionControl].[V_StuffHelthCareProgramVacc]
AS
SELECT        InfectionControl.StaffHealthCareProgram.EmployeeId, OutPatient.VaccinationMaster.VaccinationName, InfectionControl.StaffHealthCareProgram.Comment AS STH_Comment, HR.SubDepartment.NameEn AS SubDeptName, 
                         HR.Department.NameEn AS DeptName, InfectionControl.StaffHealthCareProgramDetails_Vac.StatuesId AS STHV_Status, InfectionControl.StaffHealthCareProgramDetails_Vac.Comment AS STHV_Comment, 
                         Nursing.Employee.EmployeeCode, Nursing.Employee.FirstName + ' ' + Nursing.Employee.MiddleName + ' ' + Nursing.Employee.LastName AS EmpName, 
                         Nursing.Employee.FirstNameEn + ' ' + Nursing.Employee.MiddleNameEn + ' ' + Nursing.Employee.LastNameEn AS EmpNameEn, InfectionControl.StaffHealthCareProgramDetails_Vac.Vaccinationd AS VMId, 
                         InfectionControl.StaffHealthCareProgramDetails_Vac.StatusDate
