SELECT        TOP (20000) InPatient.RequestSuppliesDetails.Id, InPatient.RequestSuppliesDetails.RequestSuppliesHeaderID, InPatient.RequestSuppliesDetails.ItemID, InPatient.RequestSuppliesDetails.UnitConversionID, 
                         InPatient.RequestSuppliesDetails.ReturnedQty, InPatient.RequestSuppliesDetails.Quantity, InPatient.RequestSuppliesDetails.IsIncluded, InPatient.RequestSuppliesDetails.StockBatchId, 
                         InPatient.RequestSuppliesDetails.IsApproved, InPatient.RequestSuppliesDetails.CreatedBy, InPatient.RequestSuppliesDetails.CreatedDate, InPatient.RequestSuppliesDetails.LastModifiedBy, 
                         InPatient.RequestSuppliesDetails.LastModifiedDate, InPatient.RequestSuppliesDetails.CompanyID, InPatient.RequestSuppliesDetails.CurrencyID, InPatient.RequestSuppliesDetails.ConvValue, 
                         InPatient.RequestSuppliesDetails.Price, InPatient.RequestSuppliesDetails.StockControlDetailList, InPatient.RequestSuppliesDetails.ISCash, InPatient.RequestSuppliesDetails.InsuranceId, 
                         InPatient.RequestSuppliesDetails.Dispense, GeneralStores.Stocks.StockName, GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, GeneralStores.Units.UnitName, GeneralStores.Units.UnitNameEn, 
                         InPatient.RequestSuppliesHeader.OP_IPNo, InPatient.RequestSuppliesHeader.SubStoreID, Registration.Patients.Code, ISNULL(Registration.Patients.FirstName, '') + ' ' + ISNULL(Registration.Patients.MiddleName1, '') 
