/****** Object:  View [InPatient].[V_BedSwap]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [InPatient].[V_BedSwap]
AS

SELECT        FWard.Name AS WardFromName, FWard.NameAr AS WardFromNameAr, TWard.Name AS WardToName, 
TWard.NameAr AS WardToNameAr, ISNULL(PFrom.FirstName, '') + ' ' + ISNULL(PFrom.MiddleName1, '') 
                         + ' ' + ISNULL(PFrom.MiddleName2, '') + ' ' + ISNULL(PFrom.LastName, '')
						  AS PFromName, PFrom.TranslatedFallName AS PFromNameEn, ISNULL(PTo.FirstName, '') + ' ' + ISNULL(PTo.MiddleName1, '') 
                         + ' ' + ISNULL(PTo.MiddleName2, '') + ' ' + ISNULL(PTo.LastName, '') 
						 AS PToName, PTo.TranslatedFallName AS PToNameEn, swap.DateSwap AS RequestDate, 
						 swap.BedSwapStatus,swap.ID SwapID,FWard.id FWardID,TWard.Id ToWardID,
						 PFrom.Id PFromID,PTo.id PToId,AdmitFrom.Id AdmitFromID,AdmitTo.id AdmitToID
FROM            InPatient.BedSwap AS swap INNER JOIN
                         InPatient.AdmitPatients AS AdmitFrom ON swap.PatientFrom = AdmitFrom.Id INNER JOIN
                         InPatient.AdmitPatients AS AdmitTo ON swap.PatientTo = AdmitTo.Id INNER JOIN
                         InPatient.Ward AS FWard ON FWard.Id = AdmitFrom.AdmissionWardID INNER JOIN
                         InPatient.Ward AS TWard ON TWard.Id = AdmitTo.AdmissionWardID INNER JOIN
                         Registration.Patients AS PFrom ON AdmitFrom.PatientID = PFrom.Id INNER JOIN
                         Registration.Patients AS PTo ON AdmitTo.PatientID = PTo.Id



GO
