GO
/****** Object:  View [InPatient].[V_GetAdmitPatientsDet]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [InPatient].[V_GetAdmitPatientsDet]
AS
SELECT        TOP (100) InPatient.AdmitPatients.Id, InPatient.AdmitPatients.IPNumber, 
                         Registration.Patients.FirstName + ' ' + Registration.Patients.MiddleName1 + ' ' + Registration.Patients.MiddleName2 + ' ' + Registration.Patients.LastName AS FullName, InPatient.AdmitPatients.AdmissionDate, 
                         Registration.Patients.GenderId, Registration.Patients.Code AS MRN, Registration.Patients.PassportNumber, InPatient.Bed.BedNumber, InPatient.Room.RoomNumber, InPatient.Ward.Name, InPatient.Ward.Code, 
                         InPatient.Ward.NameAr, CAST(InPatient.Room.WardId AS INT) AS WardId, CAST(CONVERT(CHAR(8), InPatient.AdmitPatients.AdmissionDate, 112) AS int) AS AdmissionDateInt, InPatient.AdmitPatients.DoctorID
						 ,
						
						          CAST(InPatient.AdmitPatients.AdmissionDate AS datetime) + ' ' + CAST(isnull(InPatient.AdmitPatients.AdmissionTime,cast(InPatient.AdmitPatients.LastModifiedDate as time)) AS datetime) AS AdmissionDate2

FROM            InPatient.AdmitPatients INNER JOIN
                         Registration.Patients ON InPatient.AdmitPatients.PatientID = Registration.Patients.Id INNER JOIN
                         InPatient.Bed ON InPatient.AdmitPatients.BedNO = InPatient.Bed.Id INNER JOIN
                         InPatient.Room ON InPatient.Bed.RoomId = InPatient.Room.Id AND InPatient.Bed.RoomId = InPatient.Room.Id INNER JOIN
                         InPatient.Ward ON InPatient.Room.WardId = InPatient.Ward.Id AND InPatient.Room.WardId = InPatient.Ward.Id
ORDER BY InPatient.AdmitPatients.AdmissionDate DESC



GO
