CREATE VIEW [InPatient].[V_LastAdmitPatDetails]
AS
SELECT        
ad.[Id], ad.[PatientID], ad.[AdmitDoctorID], ad.AdmitionType, ad.[DoctorID], ad.[IPNumber], 
ad.[AdmissionWardID], ad.[Days], ad.[AdmissionDate], ad.[AdmissionTime], ad.[BedNO], 
ad.[RoomTypeID], ROW_NUMBER() OVER (PARTITION BY ad.[PatientID] ORDER BY ad.[Id] DESC) AS adRow, 
[BedNumber], [RoomNumber], ward.[Name] WardName, Pat.[Code] PatientCode, 
CONCAT(FirstName, ' ', MiddleName1, ' ', MiddleName2, ' ', LastName) PatientName, roomt.[Name] RoomTypeName, 
[DayPrice], DischargeStatusId, bt.[Name] AS BedTypeName, b.[BedTypeId] AS BedTypeId, '' AS [Remarks], 
[Instructions], [MedicalCondition], Flo.[FloorCode], Flo.[Description] FloorDescription, IsIsolation,
 Flo.[NameEn] FloorDescriptionEn
FROM            [InPatient].[AdmitPatients] ad LEFT JOIN
                         [InPatient].[AdmissionRequest] AR ON AR.[Id] = ad.[AdmissionRequestID] JOIN
                         [InPatient].[Bed] b ON ad.BedNO = b.Id LEFT JOIN
                         [InPatient].[BedType] bt ON b.[BedTypeId] = bt.[Id] JOIN
                         [InPatient].[Room] room ON room.Id = b.RoomId JOIN
                         [InPatient].[Ward] ward ON ward.Id = room.WardId JOIN
                         [InPatient].[Floors] Flo ON Flo.[Id] = ward.[FloorID] JOIN
                         [InPatient].[RoomType] roomt ON roomt.Id = ad.[RoomTypeID] JOIN
