GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [InPatient].[V_test]
AS
SELECT        InPatient.PatientOrderDetail.*, InPatient.AdmitPatients.Id AS Expr1, InPatient.PatientOrderMaster.PatientId, Registration.Patients.FirstName, Registration.Patients.MiddleName1, Registration.Patients.MiddleName2, 
                         Registration.Patients.Main_Acc
FROM            InPatient.PatientOrderDetail INNER JOIN
                         InPatient.PatientOrderMaster ON InPatient.PatientOrderDetail.PatientOrderMasterId = InPatient.PatientOrderMaster.ID INNER JOIN
                         InPatient.AdmitPatients ON InPatient.PatientOrderMaster.PatientId = InPatient.AdmitPatients.PatientID INNER JOIN
                         Registration.Patients ON InPatient.AdmitPatients.PatientID = Registration.Patients.Id
WHERE        (InPatient.AdmitPatients.DischargeStatusId = 1)

GO
/****** Object:  View [InPatient].[VBodyMassIndex]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [InPatient].[VBodyMassIndex]
AS
SELECT        cast(ROW_NUMBER() OVER (ORDER BY 
                             (SELECT        1)) AS int) AS ID, PatientID, BMI, CreatedDate, ISNULL(Height,0) Height,isNULL( Weight,0) Weight
FROM            (SELECT        PatientID, round(BMI, 2) BMI, cast(CONVERT(char(8), CreatedDate, 112) AS bigint) AS CreatedDate, Height, Weight
                          FROM            [InPatient].[MedicalObservation]
                          UNION
                          SELECT        PatientID, round(BMI, 2) BMI, cast(CONVERT(char(8), [VitalSigns].Date, 112) AS bigint) AS CreatedDate, Height, Weight
                          FROM            [InPatient].[VitalSigns]) BMITbl

GO
