CREATE VIEW [LegalAffairs].[vw_GetAffairDetails]
AS
SELECT        LegalAffairs.Affair.AffairNo, LegalAffairs.Affair.opponentName, LegalAffairs.Affair.Name, LegalAffairs.Affair.Id, LegalAffairs.AffairDetails.AffairDate, LegalAffairs.AffairDetails.Decisionsissued, 
                         LegalAffairs.AffairDetails.DecisionsExcuted, LegalAffairs.AffairDetails.succinctness, LegalAffairs.Affair.RecordNo, LegalAffairs.Affair.MemberID
FROM            LegalAffairs.Affair INNER JOIN
