CREATE VIEW [Maintenance].[GetVehiclesata]
AS
SELECT        SUM(CityRoadKilometer) AS CityRoadKilometer, SUM(CountryRoad) AS CountryRoad, VehicleID, Litres, SUM(PrevKilometer) AS PrevKilometer, SUM(CurrentKilometer) AS CurrentKilometer, OilLiterCouponValue, BonNo
FROM            (SELECT        SUM(req.Endkilometer - req.StartKilometer) AS CityRoadKilometer, 0 AS CountryRoad, req.VehicleID, setting.OilLiterCouponValue, 
                                                    CASE WHEN v.Gas_Type = 1 THEN setting.GasValueInLiter WHEN v.Gas_Type = 2 THEN setting.DieselValueInLiter END AS Litres, 0 AS PrevKilometer, 0 AS CurrentKilometer, COUNT(*) AS BonNo
                           FROM            Maintenance.VehicleRequest AS req INNER JOIN
                                                    Maintenance.Vehicles AS v ON req.VehicleID = v.id INNER JOIN
                                                    Nursing.Employee AS emp ON req.DriverID = emp.Id CROSS JOIN
                                                    Maintenance.MaintenanceSetting AS setting
                           WHERE        (req.BonID <> 0) AND (req.Status = 2) AND (req.RoadType = 1)
                           GROUP BY req.VehicleID, CASE WHEN v.Gas_Type = 1 THEN setting.GasValueInLiter WHEN v.Gas_Type = 2 THEN setting.DieselValueInLiter END, setting.OilLiterCouponValue
                           UNION
                           SELECT        0 AS CityRoadKilometer, SUM(req.Endkilometer - req.StartKilometer) AS CountryRoad, req.VehicleID, setting.OilLiterCouponValue, 
                                                    CASE WHEN v.Gas_Type = 1 THEN setting.GasValueInLiter WHEN v.Gas_Type = 2 THEN setting.DieselValueInLiter END AS Litres, 0 AS PrevKilometer, 0 AS CurrentKilometer, COUNT(*) AS BonNo
                           FROM            Maintenance.VehicleRequest AS req INNER JOIN
                                                    Maintenance.Vehicles AS v ON req.VehicleID = v.id INNER JOIN
                                                    Nursing.Employee AS emp ON req.DriverID = emp.Id CROSS JOIN
