SELECT   DISTINCT     Nursing.NurseSchedule.NurseId, OutPatient.ClinicSetup.ID, OutPatient.ClinicSetup.NameArabic, OutPatient.ClinicSetup.NameEnglish, Nursing.NurseSchedule.Dayint
FROM            Nursing.NurseSchedule INNER JOIN
                         OutPatient.ClinicSetup ON Nursing.NurseSchedule.ClinicID = OutPatient.ClinicSetup.ID




GO
/****** Object:  View [Nursing].[vw_GetAssignNursesToPatients]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Nursing].[vw_GetAssignNursesToPatients]
AS
SELECT        ANP.Id, ANP.IPNumber, NM.Name, NM.NameEn, S.SessionName, S.SessionNameAr, ANP.PatientId, P.Code, P.TranslatedFallName, ANP.CreatedDate, InPatient.AdmitPatients.DischargeStatusId, P.FirstName, 
                         P.MiddleName1, P.MiddleName2, P.LastName
FROM            Nursing.AssignNurseToPatients AS ANP INNER JOIN
                         Nursing.NurseMaster AS NM ON NM.Id = ANP.NurseId INNER JOIN
                         Registration.Sessions AS S ON S.Id = ANP.SessionId INNER JOIN
                         Registration.Patients AS P ON P.Id = ANP.PatientId INNER JOIN
                         InPatient.AdmitPatients ON ANP.PatientId = InPatient.AdmitPatients.PatientID

GO
