CREATE VIEW [Nursing].[vw_GetTreatmentCycles]
AS
SELECT        OutPatient.SpecialityGroupDetails.Name, OutPatient.SpecialityGroupDetails.NameAr, Nursing.TreatmentCycle.NumOfFollowUpVisit, Nursing.TreatmentCycle.Period, Nursing.TreatmentCycle.PeriodType, 
                         Nursing.TreatmentCycle.TreatmentCycleId
FROM            Nursing.TreatmentCycle INNER JOIN
                         OutPatient.SpecialityGroupDetails ON Nursing.TreatmentCycle.SpecialityGroupDetailsId = OutPatient.SpecialityGroupDetails.ID


GO
