/****** Object:  View [Operations].[vw_GetDiagnosisForPatients]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Operations].[vw_GetDiagnosisForPatients]
AS
SELECT        InPatient.MedicalObservation.PatientID, InPatient.MedicalObservationICDCodes.ICDCodeID, InPatient.MedicalObservationICDCodes.Type, Nursing.ICDCodes.ICDDescription, InPatient.MedicalObservation.IP_OP
FROM            InPatient.MedicalObservation INNER JOIN
                         InPatient.MedicalObservationICDCodes ON InPatient.MedicalObservation.Id = InPatient.MedicalObservationICDCodes.MedicalObservationID INNER JOIN
                         Nursing.ICDCodes ON InPatient.MedicalObservationICDCodes.ICDCodeID = Nursing.ICDCodes.Id



GO
