CREATE VIEW [OutPatient].[DaignosisAnswerQuestionID]
AS
SELECT        OutPatient.DiagnosisAnswers.Id, OutPatient.DiagnosisAnswers.DiagnosisAnswerName, OutPatient.DiagnosisAnswers.DiagnosisQuestionID, OutPatient.DiagnosisQuestion.DiagnosisQuestionName
FROM            OutPatient.DiagnosisAnswers INNER JOIN
                         OutPatient.DiagnosisQuestion ON OutPatient.DiagnosisAnswers.DiagnosisQuestionID = OutPatient.DiagnosisQuestion.Id







GO
