                         OutPatient.ClinicProcedures AS ClinicProcedures ON ClinicProcedures.ProcedureID = DDSDetails.ProcedureId AND ClinicProcedures.ClinicID = DDSDetails.ClinicId JOIN
                         OutPatient.ClinicSetup ON OutPatient.ClinicSetup.ID = ClinicProcedures.ClinicID AND PrepareVisitSlip.BranchId = OutPatient.ClinicSetup.BranchId JOIN
                         ApplicationSetup.Service services ON services.Id = ClinicProcedures.ServiceID JOIN
                         Billing.PatientBillservices AS PatientBill ON PatientBill.OP_IPNumber = PrepareVisitSlip.OPnumber AND PrepareVisitSlip.OPNumberStatus != 2 JOIN
                         Registration.Doctors doctor ON doctor.id = Dds.DoctorID
WHERE        (PrepareVisitSlip.[IsApproved] IS NULL OR
                         PrepareVisitSlip.[IsApproved] = 0) AND (PrepareVisitSlip.VisitSlipStatus IS NULL OR
                         PrepareVisitSlip.VisitSlipStatus = 2 OR
                         PrepareVisitSlip.VisitSlipStatus = 3 OR
                         PrepareVisitSlip.VisitSlipStatus = 4 OR
                         PrepareVisitSlip.VisitSlipStatus = 5) AND PatientBill.Paid = 1
UNION
(SELECT        PrepareVisitSlip.Id AS Id, patient.Id AS patientId, patient.FirstName + ' ' + patient.MiddleName1 + ' ' + patient.MiddleName2 + ' ' + patient.LastName AS PatientName, patient.TranslatedFallName AS PatientNameEn, 
                          patient.Code MRN, patient.ImageUrl AS PatientImage, patient.GenderId AS GenderId, doctor.Name AS DoctorName, doctor.id AS DoctorID, Department.Name AS DepartmentName, PrepareVisitSlip.VisitStatus AS VisitStatus, 
                          PrepareVisitSlip.OPnumber AS IP_OPNumber, PrepareVisitSlip.Time AS Time, services.[ServiceCharge] AS Amount, PrepareVisitSlip.VisitNo AS VisitNo, ClinicProcedures.ItFollowUp AS ItFollowUp, PrepareVisitSlip.[IsApproved], 
