                         Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID, OutPatient.PrepareVisitSlip.ScheduleAppointmentID, OutPatient.PrepareVisitSlip.Id AS PrepareVisitSlipID, OutPatient.PrepareVisitSlip.OPnumber, 
                         Registration.DoctorsDailyScheduleDetails.Id
FROM            Registration.DoctorsDailySchedule INNER JOIN
                         Registration.DoctorsDailyScheduleDetails ON Registration.DoctorsDailySchedule.Id = Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID INNER JOIN
                         OutPatient.PrepareVisitSlip ON Registration.DoctorsDailyScheduleDetails.Id = OutPatient.PrepareVisitSlip.ScheduleAppointmentID INNER JOIN
                         Registration.Patients ON OutPatient.PrepareVisitSlip.PatientID = Registration.Patients.Id
WHERE        (CAST(CONVERT(char(8), CAST(Registration.DoctorsDailySchedule.ScheduleDate AS datetime), 112) AS bigint) >= CAST(CONVERT(char(8), GETDATE(), 112) AS bigint)) AND 
                         (Registration.DoctorsDailyScheduleDetails.EndVisitDate IS NULL) AND (OutPatient.PrepareVisitSlip.VisitSlipStatus IS NULL OR
                         OutPatient.PrepareVisitSlip.VisitSlipStatus = 1 OR
                         OutPatient.PrepareVisitSlip.VisitSlipStatus = 2)


