/****** Object:  View [OutPatient].[V_GetDocByClinic]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO






CREATE VIEW [OutPatient].[V_GetDocByClinic]
AS
SELECT DISTINCT Registration.Doctors.Id, Registration.Doctors.Name, Registration.Doctors.NameAr, OutPatient.ClinicSchedule.ClinicID
FROM            OutPatient.ClinicSchedule INNER JOIN
                         Registration.Doctors ON OutPatient.ClinicSchedule.DoctorID = Registration.Doctors.Id
WHERE        (OutPatient.ClinicSchedule.Status = 1)












