CREATE VIEW [OutPatient].[vw_GetWaitingTimeForPatients]
AS
SELECT DISTINCT 
                         TOP (100) PERCENT DATEDIFF(MINUTE, Details.PatientSeenDate, PB.LastModifiedDate) AS WaitingHours, Details.ClinicId, 
                         patient.FirstName + ' ' + patient.MiddleName1 + ' ' + patient.MiddleName2 + ' ' + patient.LastName AS patientName, CONVERT(datetime, CONVERT(nchar(20), PB.LastModifiedDate, 120), 120) AS LastModifiedDate,
