FROM            (SELECT        Id, patientName, CASE WHEN PatientType = 'InPatient' THEN IPNumber WHEN PatientType = 'OutPatient' THEN OPnumber WHEN PatientType = 'Emergency' THEN Code END AS VisitNumber, PatientType, 
                                                    CASE WHEN PatientType = 'InPatient' THEN admitPatientStatus WHEN PatientType = 'OutPatient' THEN PrepareVisitSlipStatus WHEN PatientType = 'Emergency' THEN EmergencyDetailsStatus END AS VisitStatus, 
                                                    CASE WHEN PatientType = 'InPatient' THEN AdmissionDate WHEN PatientType = 'OutPatient' THEN PatientSeenDate WHEN PatientType = 'Emergency' THEN VisiteDate END AS VisitStartDate, 
                                                    CASE WHEN PatientType = 'InPatient' THEN EndAdmitDate WHEN PatientType = 'OutPatient' THEN EndVisitDate WHEN PatientType = 'Emergency' THEN DischargeDate END AS VisitEndDate, 
                                                    CASE WHEN PatientType = 'InPatient' THEN Name WHEN PatientType = 'OutPatient' THEN NameEnglish WHEN PatientType = 'Emergency' THEN 'Triage Room' END AS VisitPlace, 
                                                    CASE WHEN PatientType = 'InPatient' THEN admitPatientDoctNameEn WHEN PatientType = 'OutPatient' THEN PrepareVisitSlipDoctNameEn WHEN PatientType = 'Emergency' THEN EmergencyDetailsDoctNameEn END
                                                     AS Physician
                           FROM            (SELECT DISTINCT 
