                                                                               THEN 'InPatient' WHEN PrepareVisitSlip.Id IS NOT NULL THEN 'OutPatient' WHEN EmergencyDetails.ID IS NOT NULL THEN 'Emergency' END AS PatientType
                                                      FROM            Registration.Patients AS pat LEFT OUTER JOIN
                                                                               OutPatient.PrepareVisitSlip AS PrepareVisitSlip ON PrepareVisitSlip.PatientID = pat.Id LEFT OUTER JOIN
                                                                               Registration.DoctorsDailyScheduleDetails AS DoctDailyScheduleDetails ON DoctDailyScheduleDetails.Id = PrepareVisitSlip.ScheduleAppointmentID LEFT OUTER JOIN
                                                                               Registration.DoctorsDailySchedule AS DoctDailySchedule ON DoctDailyScheduleDetails.DoctorsDailyScheduleID = DoctDailySchedule.Id LEFT OUTER JOIN
                                                                               Registration.Doctors AS PrepareVisitSlipDoct ON PrepareVisitSlipDoct.Id = PrepareVisitSlip.DoctorsID LEFT OUTER JOIN
                                                                               OutPatient.ClinicSetup AS ClinicSetup ON ClinicSetup.ID = DoctDailyScheduleDetails.ClinicId LEFT OUTER JOIN
                                                                               InPatient.AdmitPatients AS admitPatient ON admitPatient.PatientID = pat.Id LEFT OUTER JOIN
                                                                               InPatient.PatientDischarge AS PatientDischarge ON PatientDischarge.PatientId = pat.Id LEFT OUTER JOIN
                                                                               Registration.Doctors AS admitPatientDoct ON admitPatientDoct.Id = admitPatient.DoctorID LEFT OUTER JOIN
