/****** Object:  View [Pharmacy].[GetLocalPurchaseOrderHeader]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create View [Pharmacy].[GetLocalPurchaseOrderHeader]
as

SELECT    cast(  ROW_NUMBER() OVER(ORDER BY name ASC) as int) AS id,    Pharmacy.LocalPurchaseOrderHeader.PONumber, Pharmacy.LocalPurchaseOrderHeader.PODate, Pharmacy.GRN_LPOs.GRNID, ApplicationSetup.Currency.NameAr, ApplicationSetup.Currency.Name, 
                     Pharmacy.PaymentTermsMaster.PaymentTermDesc
FROM            Pharmacy.GRN_LPOs INNER JOIN
                         Pharmacy.LocalPurchaseOrderHeader ON Pharmacy.GRN_LPOs.LPOID = Pharmacy.LocalPurchaseOrderHeader.ID INNER JOIN
                         ApplicationSetup.Currency ON Pharmacy.LocalPurchaseOrderHeader.CurrencyID = ApplicationSetup.Currency.Id INNER JOIN
                         Pharmacy.PaymentTermsMaster ON Pharmacy.LocalPurchaseOrderHeader.PaymentTermsID = Pharmacy.PaymentTermsMaster.ID
GO
/****** Object:  View [Pharmacy].[repexpenses]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Pharmacy].[repexpenses]
AS
SELECT        Pharmacy.ExpenseMaster.ExpenseName, Pharmacy.LocalPurchaseOrderExpenses.Amount, Pharmacy.LocalPurchaseOrderExpenses.LPOID
FROM            Pharmacy.ExpenseMaster INNER JOIN
                         Pharmacy.LocalPurchaseOrderExpenses ON Pharmacy.ExpenseMaster.ID = Pharmacy.LocalPurchaseOrderExpenses.ExpensesID

GO
