CREATE VIEW [Pharmacy].[V_DrugClassification]
AS
SELECT        Pharmacy.DrugClassification.NameEn AS ClassName, Pharmacy.DrugClassification.Id AS ClassID, Pharmacy.Drugs.DrugName as DrugName 

,Pharmacy.Drugs.DrugNameAr as DrugNameAr, Pharmacy.Drugs.ID, Pharmacy.Drugs.DrugCode as  DrugCode
FROM            Pharmacy.Drugs LEFT OUTER JOIN
                         Pharmacy.DrugClassification ON Pharmacy.Drugs.ClassificationId = Pharmacy.DrugClassification.Id






GO
