/****** Object:  View [Radiology].[V_ReceptionPatientsServices]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Radiology].[V_ReceptionPatientsServices]
AS
SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY OutPatient.InvestigationRequestHeader.PatientID) Id, Radiology.ReceptionDevicsSchedule.ReceptionID, Radiology.ReceptionStocks.StockID, Radiology.DeviceServices.ServiceId, 
Radiology.ReceptionDevicsSchedule.DeviceID, OutPatient.InvestigationRequestHeader.PatientID, OutPatient.InvestigationRequestHeader.OP_IPNumber
FROM            OutPatient.InvestigationRequestHeader INNER JOIN
                         OutPatient.InvestigationRequestDetails ON OutPatient.InvestigationRequestHeader.Id = OutPatient.InvestigationRequestDetails.InvestigationRequestId INNER JOIN
                        
						 Radiology.ReceptionDevicsSchedule INNER JOIN
                         Radiology.ReceptionStocks ON Radiology.ReceptionDevicsSchedule.ReceptionID = Radiology.ReceptionStocks.ReceptionID INNER JOIN
                         Radiology.DeviceServices ON Radiology.ReceptionDevicsSchedule.DeviceID = Radiology.DeviceServices.DeviceId ON OutPatient.InvestigationRequestDetails.ServiceId = Radiology.DeviceServices.ServiceId
						 inner join Radiology.RadiologyReceptions on RadiologyReceptions.ID=ReceptionDevicsSchedule.ReceptionID and RadiologyReceptions.ID=ReceptionStocks.ReceptionID
						 where RadiologyReceptions.IsActive=1


GO
