CREATE VIEW [Radiology].[vw_GetServicesForReceptionsUsers]
AS
SELECT DISTINCT S.Id, S.Code, S.NameAr, S.NameEn, DD.DeviceType, RRDS.EmpID AS Employee_ID, RR.Emp_ReceptionAdmin
FROM            Radiology.RadiologyReceptions AS RR INNER JOIN
                         Radiology.ReceptionDevicsSchedule AS RDS ON RDS.ReceptionID = RR.ID INNER JOIN
                         Radiology.RadReceptioniestSchedule AS RRDS ON RRDS.ReceptionID = RR.ID INNER JOIN
                         Radiology.DevicesDefination AS DD ON DD.ID = RDS.DeviceID INNER JOIN
                         Radiology.DeviceServices AS DS ON DS.DeviceId = DD.ID INNER JOIN
                         ApplicationSetup.InvestigationGroupDetail AS IGD ON IGD.Service_Id = DS.ServiceId INNER JOIN
                         ApplicationSetup.Service AS S ON S.Id = IGD.Service_Id
WHERE        (RR.IsActive = 1)


GO
