CREATE VIEW [Receivable].[V_EInsurance_Claims]
AS
SELECT        TOP (100) PERCENT Billing.PatientBillservices.Id, Billing.PatientBill.PatientName, Billing.PatientBillservices.OP_IPNumber, Billing.PatientBillservices.SponsorName, Billing.PatientBill.IsEndVisit, 
                         Billing.PatientBillservices.SponserPaidAmount, Billing.PatientBillservices.PateintPaidAmount, Billing.PatientBillservices.Paid, Billing.PatientBill.Status, Billing.PatientBillservices.ISCash, Billing.PatientBillservices.SponserId, 
                         CASE LEFT(OP_IPNumber, 2) WHEN 'IP' THEN CAST(InPatient.AdmitPatients.AdmissionDate AS Date) WHEN 'OP' THEN CAST(Registration.DoctorsDailyScheduleDetails.PatientArrivalDate AS date) END AS FromDate, 
                         CASE LEFT(OP_IPNumber, 2) WHEN 'IP' THEN CAST(InPatient.PatientDischarge.DischargDate AS Date) WHEN 'OP' THEN CAST(Registration.DoctorsDailyScheduleDetails.EndVisitDate AS Date) END AS ToDate, 
                         Billing.PatientBillservices.Vat - Billing.PatientBillservices.PatVat AS SponVat
FROM            Billing.PatientBill INNER JOIN
