CREATE VIEW [Registration].[FavouriteDiseaseView]
AS
SELECT        OutPatient.DiseaseMaster.DiseaseName, Registration.Doctors.Name
FROM            Registration.FavouriteDisease INNER JOIN
                         OutPatient.DiseaseMaster ON Registration.FavouriteDisease.DiseaseId = OutPatient.DiseaseMaster.Id INNER JOIN
                         Registration.Doctors ON Registration.FavouriteDisease.DoctorId = Registration.Doctors.Id








GO
