CREATE VIEW [Registration].[FavouriteDrugsView]
AS
SELECT        Pharmacy.Drugs.DrugCode, Pharmacy.Drugs.DrugName, Registration.Doctors.Name
FROM            Registration.FavouriteDrugs INNER JOIN
                         Registration.Doctors ON Registration.FavouriteDrugs.DoctorId = Registration.Doctors.Id INNER JOIN
                         Pharmacy.Drugs ON Registration.FavouriteDrugs.DrugId = Pharmacy.Drugs.ID








GO
