CREATE VIEW [Registration].[GenericClinicDepartmentID]
AS
SELECT        Registration.GenericClinics.Id, Registration.GenericClinics.Clinic, Registration.GenericClinics.DepartmentId, Registration.GenericClinics.Active, ApplicationSetup.CostCenter.Name
FROM            ApplicationSetup.CostCenter INNER JOIN
                         Registration.GenericClinics ON ApplicationSetup.CostCenter.Id = Registration.GenericClinics.DepartmentId







