/****** Object:  View [Registration].[PatientsView]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Registration].[PatientsView]
AS
SELECT        Registration.Patients.Id, Registration.Patients.Code, Registration.Titles.ArabicTitleName, Registration.Titles.EnglishTitleName, Registration.Patients.FirstName, Registration.Patients.MiddleName1, 
                         Registration.Patients.MiddleName2, Registration.Patients.LastName, Registration.Nationalities.Name AS Nationality, Registration.Religions.Name AS Religion, CONVERT(date, Registration.Patients.DateOfBirth) AS DateOfBirth, 
                         Registration.Patients.PhoneNumber, Registration.Patients.MobileNumber, Registration.Patients.City, Registration.Patients.Email, 
                         CASE WHEN Registration.Patients.GenderId = 1 THEN 'Male' WHEN Registration.Patients.GenderId = 2 THEN 'Female' ELSE 'NotFound' END AS Gender, 
                         CASE WHEN Registration.Patients.BloodGroup = 1 THEN 'O+' WHEN Registration.Patients.BloodGroup = 2 THEN 'A+' WHEN Registration.Patients.BloodGroup = 3 THEN 'B+' WHEN Registration.Patients.BloodGroup = 4 THEN 'AB+'
                          WHEN Registration.Patients.BloodGroup = 5 THEN 'O-' WHEN Registration.Patients.BloodGroup = 6 THEN 'A-' WHEN Registration.Patients.BloodGroup = 7 THEN 'B-' WHEN Registration.Patients.BloodGroup = 8 THEN 'AB-' ELSE
                          'NotFound' END AS BloodGroupName, CASE WHEN Registration.Patients.MaritalStatusId = 1 THEN 'Single' WHEN Registration.Patients.MaritalStatusId = 2 THEN 'Married' ELSE 'NotFound' END AS MaritalStatus, 
