                         Registration.Patients.MiddleName2, Registration.Patients.LastName, Registration.Patients.PatientType, OutPatient.InvestigationRequestHeader.PatientID, OutPatient.InvestigationRequestHeader.Type, 
                         Registration.Patients.Code AS patientCode, ApplicationSetup.Service.Id, OutPatient.InvestigationRequestDetails.ServiceId
