                         ISNULL(MiddleName2, '') AS MiddleName2, ISNULL(LastName, '') AS LastName, SponsorName, MobileNumber, TranslatedFallName, CreatedDate, CompanyID
FROM            Registration.Patients
WHERE        (Active = 1) AND (Id NOT IN
                             (SELECT        PatientID
                               FROM            InPatient.AdmitPatients
                               WHERE        (DischargeStatusId <> 4))) AND (Id NOT IN
                             (SELECT DISTINCT PatientID
                               FROM            Emergency.EmergencyUnit
                               WHERE        (PatientID IS NOT NULL) AND (ID NOT IN
                                                             (SELECT        EmergencyUnitID
                                                               FROM            InPatient.PatientDischarge
                                                               WHERE        (EmergencyUnitID IS NOT NULL) AND (PatientId IS NOT NULL)))))

GO
