/****** Object:  StoredProcedure [Accounting].[OpenBalanceGetAll]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Accounting].[OpenBalanceGetAll]
as
select MA.AccountNum ,SA.SubAccountNum,FY.Year,OB.Balance,OB.BlanceType,c.Name,OB.CurrencyBalance
from Accounting.OpenBalance OB left join Accounting.MainAccount MA on OB.MainAccountId=MA.Id
left join Accounting.SubAccount SA on OB.SubAccountId=SA.Id
left join Accounting.FinancialYear FY on OB.FinancialYearId=FY.Id
LEFT JOIN ApplicationSetup.Currency C on OB.CurrencyId=C.Id





GO
/****** Object:  StoredProcedure [Accounting].[ReportAdvanceSettlement]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [Accounting].[ReportAdvanceSettlement] @FromDate datetime,@ToDate datetime
as
select A.RecieptdDate ,S.SafeNum,E.FirstName,A.Amount,T.RecieptNum
from Accounting.AdvanceSettlement A left Join Accounting.Safe S on A.SafeId=S.Id
left join Nursing.Employee E on A.EmployeeId=E.Id
left join Accounting.AdvanceTransaction T on A.AdvanceTransactionId=T.Id where A.RecieptdDate between @FromDate and @ToDate








GO
