CREATE proc [Accounting].[TaxDearationReport] @FromDate datetime,@ToDate datetime
as
select TaxDearationRecNum,RecieptdDate,SenderName,Amount,Discount,DealingNature  from Accounting.TaxDearationRec
where RecieptdDate between @FromDate and @ToDate





