GO


CREATE proc [Assets].[AddJournalDirectSales]
@ReceiptNo nvarchar(50)
as
begin

Declare @PatientID int,
@Amount float,
@StockID int,
@GRNDate datetime,
@JRN_ID int,
@userID nvarchar(200),
@JRN_NU real ,
@EntryTP int ,
@InvMainAccount Bigint,
@InvSubAccount Bigint,
@COGSMainAccount Bigint,
@COGSSubAccount Bigint ,
@CashMainAccount bigint,
@CashSubAccount bigint,
@CostCenterCompID int,
@CostCenterID int,
@RevenuSalesMainAcc bigint,
@RevenuSalesSubAcc bigint,
@TransID int

set @TransID=(select Id from InPatient.WardPharmacy where ReceiptNo=@ReceiptNo)
set @PatientID=(select PatientID from InPatient.WardPharmacy where Id=@TransID)
set @StockID =isnull((select SubStoreID from InPatient.WardPharmacy where Id=@TransID),0)
