(SELECT DISTINCT SSG_Code FROM Assets.FX_SubSubGroup WHERE   SSG_ID=Assets.FX_Assets.SSG_ID)AS SSG_Code,
(SELECT DISTINCT SSG_Name FROM Assets.FX_SubSubGroup WHERE   SSG_ID=Assets.FX_Assets.SSG_ID) AS SSG_Name,
Assets.FX_Assets. Asset_Code AS 'Code',
Assets.FX_Assets. Asset_Name AS 'Name',
Assets.FX_Assets. Purchase_Date as'PurchaseDate', 
CASE WHEN   ISNULL((SELECT e.Asset_Qty  FROM Assets.FX_Assets e WHERE e.ISNew =1 AND e.Asset_ID=Assets.FX_Assets.Asset_ID),0) = 0   then SUM(Assets.FX_Assets.Asset_Qty ) ELSE 0 end  as'AssetQty', 
CASE WHEN ISNULL((SELECT e.Total_Cost  FROM Assets.FX_Assets e WHERE e.ISNew =1 AND e.Asset_ID=Assets.FX_Assets.Asset_ID),0) =0 THEN   SUM(Assets.FX_Assets.Total_Cost) ELSE 0 END as'TotalCost',
 SUM(Assets.FX_Assets.Depr_Total) as 'TotalDeper',
SUM(Assets.FX_Assets. Asset_Net) as'AssetNet',
ISNULL((SELECT SUM(EX_Qty) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND EX_date BETWEEN @DATEFROM and @DATETO) ,0) AS'EX_Qty',
ISNULL((SELECT SUM(EX_Total) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND EX_date BETWEEN @DATEFROM and @DATETO) ,0)   
+
Assets.FX_Assets.MoneyColumn
AS 'Ex_total', 
ISNULL((SELECT SUM(Monthly_Deper) FROM Assets.FX_monthly_Deper WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND Deper_date BETWEEN @DATEFROM and @DATETO),0) AS'SUMDEPER',
 ISNULL((SELECT SUM(Monthly_Deper) FROM  FX_monthly_Deper WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND Deper_date BETWEEN @DATEFROM and @DATETO AND Assets.FX_Assets.ISNew=1),0) AS 'Add_deper',
ISNULL((SELECT e.Asset_Qty  FROM Assets.FX_Assets e WHERE e.ISNew =1 AND e.Asset_ID=Assets.FX_Assets.Asset_ID),0)AS 'ADD_QTY',
ISNULL((SELECT e.Total_Cost  FROM Assets.FX_Assets e WHERE e.ISNew =1 AND e.Asset_ID=Assets.FX_Assets.Asset_ID),0)AS 'ADD_Total',
ISNULL((SELECT SUM(Deper_new_value) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND EX_date BETWEEN @DATEFROM and @DATETO) ,0) AS 'EX_value',
Assets.FX_Assets.Genral_Depr,
Assets.FX_Assets.Depr_Total_Extrnal,
Assets.FX_Assets.Asset_Net_extrnal,
Assets.FX_Assets.MoneyColumn
FROM Assets.FX_Assets --LEFT	JOIN 
