/****** Object:  StoredProcedure [Assets].[Assets_GetAll]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[Assets_GetAll]
AS
BEGIN

SELECT   Asset_Code,Asset_ID  ,Asset_Name ,CASE WHEN IsActive = 0 THEN 'غير فعال' ELSE 'فعال' END AS IsActive   FROM Assets.FX_Assets ORDER BY Asset_ID

END






