/****** Object:  StoredProcedure [Assets].[Assets_lastCode]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[Assets_lastCode]
@G_ID INT,
@SG_ID INT , 
@SSG_ID INT,
@SSSG_ID INT
AS
BEGIN
SELECT CASE WHEN  MAX(Asset_Code) IS NULL then 1 ELSE  MAX(Asset_Code)+1 END AS Asset_Code FROM Assets.FX_Assets
WHERE G_ID=@G_ID AND SG_ID=@SG_ID AND SSG_ID =@SSG_ID AND (SSSG_ID=@SSSG_ID OR @SSSG_ID IS NULL)
END






