CREATE proc [Assets].[EndTerm]
@FromDate DATE,
@ToDate DATE
AS
BEGIN

DELETE FROM Assets.FX_Assets WHERE Asset_Qty=0

UPDATE Assets.FX_Assets SET ISNew=0




