ISNULL((SELECT SUM(Deper_new_value) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=Assets.FX_Assets.Asset_ID AND EX_date BETWEEN @FromDate and @ToDate) ,0) AS 'EX_value',
