IF (@Asset_Net = 1)AND (@Asset_Net_QTy > 0)
BEGIN
UPDATE FX_Asset_Exclusion SET Deper_new_value =0 WHERE  Asset_ID=@Asset_ID AND EX_ID=@ID 	
END

IF (@Asset_Net = 1)AND (@Asset_Net_QTy = 0)
BEGIN
UPDATE FX_Asset_Exclusion SET Deper_new_value =1 WHERE  Asset_ID=@Asset_ID AND EX_ID=@ID 	
END
	
	
IF (@Asset_Net > 1)AND (@Asset_Net_QTy = 0)AND ( ISNULL((SELECT COUNT (*) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID),0) =1) AND ((SELECT Age_Remain FROM Assets.FX_Assets WHERE Asset_ID=@Asset_ID) <=0   )
BEGIN
UPDATE FX_Asset_Exclusion SET Deper_new_value =@Asset_Net WHERE  Asset_ID=@Asset_ID AND EX_ID=@ID 	
END
	
FETCH NEXT FROM EX_Asset_Month_cursor  into @Asset_ID,@Total_cost,@Qty,@unit_price,@Deper_Precent,@EX_Total_cost,
@EX_QTy,@EX_unit_Price,@Ex_date,@ID,@Asset_Net

END


CLOSE EX_Asset_Month_cursor;
DEALLOCATE EX_Asset_Month_cursor;


END






