/****** Object:  StoredProcedure [Assets].[FX_Assets_SelectByName]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[FX_Assets_SelectByName]
@Asset_name NVARCHAR(500)
AS
BEGIN

SELECT   Asset_Code,Asset_ID  ,Asset_Name ,CASE WHEN IsActive = 0 THEN 'غير فعال' ELSE 'فعال' END AS IsActive   FROM Assets.FX_Assets
WHERE Asset_Name  LIKE '%' + @Asset_name + '%'
ORDER BY Asset_ID

END






GO
