CREATE proc [Assets].[FX_SubGroupGetAllByParentID]
@G_ID INT,
@SG_Code INT
as

SELECT Create_by ,
        Create_Date ,
        CustomeText1 ,
        CustomeText2 ,
        CustomeText3 ,
        Depreciation ,
        G_ID ,
        IsActive ,
        Modify_by ,
        Modify_Date ,
        SG_Code ,
        SG_Comment ,
        SG_ID ,
        SG_Name
        
         FROM Assets.FX_SubGroup
         WHERE G_ID=@G_ID AND SG_Code=@SG_Code






GO
