CREATE proc [Assets].[FX_SubSubSubgroups_SelectByName]
@SSSG_name NVARCHAR(500)
AS
BEGIN

SELECT   SSSG_Code,SSSG_ID  ,SSSG_Name ,CASE WHEN IsActive = 0 THEN 'غير فعال' ELSE 'فعال' END AS IsActive   FROM Assets.FX_SubSubSubGroupS
WHERE SSSG_Name  LIKE '%' + @SSSG_name + '%'
ORDER BY SSSG_ID

END






GO
/****** Object:  StoredProcedure [Assets].[FX_SubSubSubgroups_SelectByNameAndID]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[FX_SubSubSubgroups_SelectByNameAndID]
@SSSG_name NVARCHAR(500),
@SSG_ID INT,
@SG_ID int
AS
BEGIN

SELECT   SSSG_Code  ,SSSG_Name ,CASE WHEN IsActive = 0 THEN 'غير فعال' ELSE 'فعال' END AS IsActive   FROM Assets.FX_SubSubSubGroupS
WHERE SSSG_Name  LIKE '%' + @SSSG_name + '%'
AND SSG_ID=@SSG_ID AND  SG_ID=@SG_ID
ORDER BY SSSG_ID

END






