                     ELSE  28 END)				   
					   


DECLARE  Asset_Month_cursor CURSOR FOR 
SELECT Asset_ID ,Monthly_Deper,Depreciation,Depr_Start_Date,Depr_End_Date,Purchase_Date,
Asset_Age,Asset_Qty,Unite_Price,Total_Cost,Depr_Total,Asset_Net,Genral_Depr,
Depr_Total_Extrnal,Asset_Net_extrnal,Age_Remain,Age_Used,ISNew,ISNULL(CustomeText1,'0')
FROM Assets.FX_Assets WHERE IsActive=1 


OPEN Asset_Month_cursor

FETCH NEXT FROM Asset_Month_cursor into @Asset_ID,@Monthly_Deper,@Depreciation,@Depr_Start_Date,@Depr_End_Date,@Purchase_Date,
@Asset_Age,@Asset_Qty,@Unite_Price,@Total_Cost,@Depr_Total,@Asset_Net,@Genral_Depr,
@Depr_Total_Extrnal,@Asset_Net_extrnal,@Age_Remain,@Age_Used,@ISNew ,@Customtext1


WHILE @@FETCH_STATUS = 0
BEGIN


SET @Count_Execluded =ISNULL((SELECT COUNT(*) FROM Assets.FX_Asset_Exclusion WHERE EX_date BETWEEN @Company_StartDate and @Company_EndDate AND Asset_ID=@Asset_ID AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month),0)
 SET @case = (SELECT  CASE when DATEPART(month,MAX(EX_date)) IS NULL THEN @month+1 
									        WHEN   DATEPART(month,MAX(EX_date)) > 0 THEN  DATEPART(month,MAX(EX_date))
									        ELSE 0 END
									         FROM  FX_Asset_Exclusion WHERE EX_date BETWEEN @Company_StartDate and @Company_EndDate AND Asset_ID=@Asset_ID)
									         
DECLARE @Netqty FLOAT
SET @Netqty=(@Asset_Qty-ISNULL((SELECT SUM(EX_Qty) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate  AND DATEPART(year,EX_date)  =@year AND ISTaken=1),0)	)					         
									         

------------لا يوجد استبعاد------------
