IF(@Count_Execluded > 0)

BEGIN

EXEC Assets.EX_monthly_Deper @Asset_ID,@month


IF(@Age_Remain > 0)
BEGIN

DECLARE @Deper_new_value MONEY  ,@EX_Qty FLOAT,@EX_Total MONEY ,@EX_date DATE




SET @EX_Qty = (SELECT SUM(EX_Qty) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month)
SET @EX_Total=(SELECT SUM(EX_Total) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month)
SET @EX_date=(SELECT MAX(Ex_Date) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID)
SET @Deper_new_value=(SELECT SUM(Deper_new_value) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND	ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month ) 
+ (SELECT (Monthly_Deper/Asset_Qty)*(Asset_Qty-@EX_Qty) FROM Assets.FX_Assets WHERE Asset_ID=@Asset_ID)

IF	 (   (SELECT Asset_Qty FROM Assets.FX_Assets  WHERE Asset_ID=@Asset_ID) - @EX_Qty  ) = 0
BEGIN
	
	SET  @Deper_new_value = @Deper_new_value -  (SELECT SUM(Monthly_Deper) FROM Assets.FX_monthly_Deper WHERE Asset_ID=@Asset_ID AND Month < @month AND Year = @year)
	
END


INSERT INTO Assets.FX_monthly_Deper
        ( Month ,Year ,Month_Name , Company_StartDate ,Company_EndDate ,Purchase_Date ,Depr_Start_Date ,Depr_End_Date ,Asset_ID ,Monthly_Deper ,
