UPDATE Assets.FX_Assets SET Age_Used = Age_Used +1 ,Age_Remain = Asset_Age-Age_Used
WHERE Asset_ID=@Asset_ID







END
	


IF(@Age_Remain < 0) AND  ((@Asset_Net <> 1) OR (@Asset_Net <> @Asset_Qty))
BEGIN

DECLARE @Deper_new_value2 MONEY  ,@EX_Qty2 FLOAT,@EX_Total2 MONEY ,@EX_date2 DATE



SET @EX_Qty2 = (SELECT SUM(EX_Qty) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month)
SET @EX_Total2=(SELECT SUM(EX_Total) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month)
SET @EX_date2=(SELECT MAX(Ex_Date) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID)
set @Deper_new_value2 =isnull((SELECT SUM(Deper_new_value) FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID AND EX_date BETWEEN @Company_StartDate and @Company_EndDate AND	ISTaken=0 AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month ),0)

--set @Deper_new_value1 = @EX_Qty1

INSERT INTO Assets.FX_monthly_Deper
        ( Month ,Year ,Month_Name , Company_StartDate ,Company_EndDate ,Purchase_Date ,Depr_Start_Date ,Depr_End_Date ,Asset_ID ,Monthly_Deper ,
          Depreciation ,Total_Cost ,Asset_Qty,Create_Date,Deper_date ,Create_by,Modify_by,Modify_Date)
VALUES  ( @month ,@year ,@Month_Name,@Company_StartDate,@Company_EndDate ,@Purchase_Date ,@Depr_Start_Date ,@Depr_End_Date ,@Asset_ID , 
          @Deper_new_value2 ,@Depreciation ,ISNULL(@EX_Total2,0) ,ISNULL(@EX_Qty2,0)  ,GETDATE(),@EX_date2  
        ,@CreateBy,@Modifyby,@ModifyDate)

UPDATE Assets.FX_Asset_Exclusion SET ISTaken = 1 WHERE Asset_ID=@Asset_ID  AND DATEPART(year,EX_date)  =@year AND DATEPART(month,EX_date)  =@month 

UPDATE Assets.FX_Assets SET Age_Used = Age_Used +1 ,Age_Remain = Asset_Age-Age_Used
WHERE Asset_ID=@Asset_ID







END


	
END

