/****** Object:  StoredProcedure [Assets].[RepFXAssetInclude]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Assets].[RepFXAssetInclude] 
	@G_ID INT, 
	@SG_ID INT,
	@SSG_ID INT,
	@FROM_DATE DATE,
	@TO_DATE DATE
AS
BEGIN
	select 
	FX_Groups.G_ID,FX_Groups.G_Name,
	FX_SubGroup.SG_ID,FX_SubGroup.SG_Name,
	(SELECT DISTINCT SG_Code FROM Assets.FX_SubGroup WHERE   SG_ID=Assets.FX_Assets.SG_ID)AS SG_Code,

(SELECT DISTINCT SSG_Code FROM Assets.FX_SubSubGroup WHERE   SSG_ID=Assets.FX_Assets.SSG_ID)AS SSG_Code,

	FX_SubSubGroup.SSG_ID,FX_SubSubGroup.SSG_Name,
	FX_Assets.Purchase_Date,FX_Assets.Unite_Price,
	FX_Assets.Asset_Qty,FX_Assets.Total_Cost,
	ISNULL((SELECT SUM(Monthly_Deper) FROM Assets.FX_monthly_Deper WHERE  (Deper_date BETWEEN @FROM_DATE AND  @TO_DATE) AND  Asset_ID=Assets.FX_Assets.Asset_ID AND (Deper_date BETWEEN (SELECT  Fiscalyear_Start_date FROM  Assets.FX_Company) AND  (SELECT  Fiscalyear_End_Date FROM  Assets.FX_Company)) ),0)  as Depr_Total,
    FX_Assets.Asset_Name,
	Assets.FX_Assets.Asset_Code AS Asset_ID,
    FX_SubGroup.Depreciation AS Depreciation
	
	FROM FX_Assets 
	LEFT JOIN FX_Groups
	ON FX_Assets.G_ID = FX_Groups.G_ID
	LEFT JOIN FX_SubGroup 
	ON FX_Assets.SG_ID = FX_SubGroup.SG_ID
	LEFT JOIN FX_SubSubGroup
	ON FX_Assets.SSG_ID = FX_SubSubGroup.SSG_ID
	WHERE (FX_Assets.G_ID = @G_ID OR @G_ID IS NULL  AND FX_Assets.ISNew = 1)
	AND (FX_Assets.SG_ID = @SG_ID OR @SG_ID IS NULL AND FX_Assets.ISNew = 1)
	AND (FX_Assets.SSG_ID = @SSG_ID OR @SSG_ID IS NULL AND FX_Assets.ISNew = 1)
	AND FX_Assets.Purchase_Date BETWEEN @FROM_DATE AND @TO_DATE
	AND FX_Assets.ISNew = 1;
END






GO
