CREATE proc [Assets].[ReportAssetDepreciationTotal]
(
@AssetID int,
@FromDate datetime,
@ToDate datetime
)
as
SELECT        at.Code AS AssetTransactionCode, at.Transaction_Date, at.Transaction_Value, at.EntryCodes, am.Code AS AssetsMasterCode, am.NameEn AS AssetsMasterName, asg.Code AS AssetSubGroupCode, 
                         asg.NameEn AS AssetSubGroupName
						 ,sum (at.Transaction_Value) as Transaction_Value,
						 min(at.Transaction_Date) as MinTransaction_Date,
						 max(at.Transaction_Date) as MaxTransaction_Date,
						 am.Work_StartDate
FROM            Assets.Asset_Transactions AS at INNER JOIN
                         Assets.AssetsMaster AS am ON at.AssetID = am.id INNER JOIN
                         Assets.AssetSubGroup AS asg ON asg.id = am.SubGroupID
WHERE        (at.Transaction_Type = 3)

and (at.AssetID=@AssetID or @AssetID is null)
and (at.Transaction_Date>=@FromDate or @FromDate is null)
and (at.Transaction_Date<=@ToDate or @ToDate is null)

GROUP BY at.Code, at.Transaction_Date, at.Transaction_Value, at.EntryCodes, am.Code, am.NameEn, asg.Code, asg.NameEn,
am.Work_StartDate


GO
