CREATE proc [Assets].[ReportPurchedAssets]
(
@ItemID int,
@StockID int,
@AssetSubGroupID int,
@FromDate datetime,
@ToDate datetime
)
as
SELECT        apd.Purch_Value, apd.Purch_QTY, asg.NameEn, s.StockName, i.ItemName, ap.Code, ap.PurchDate, ap.Notes
FROM            Assets.Asset_Purch_Details AS apd INNER JOIN
                         Assets.AssetSubGroup AS asg ON apd.AssetSubGroupID = asg.id INNER JOIN
                         GeneralStores.Stocks AS s ON s.ID = apd.StockID INNER JOIN
                         GeneralStores.Items AS i ON i.ID = apd.ItemID INNER JOIN
                         Assets.Asset_Purchase AS ap ON apd.AssetPurchID = ap.id
WHERE        (ap.IsApproved = 1)
and (apd.ItemID=@ItemID or @ItemID is null)
and (apd.StockID=@StockID or @StockID is null)
and (apd.AssetSubGroupID=@AssetSubGroupID or @AssetSubGroupID is null)
