/****** Object:  StoredProcedure [Assets].[Start_term_measures]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[Start_term_measures]
AS
BEGIN

DELETE FROM Assets.FX_Assets WHERE Asset_Qty=0

UPDATE Assets.FX_Assets SET Depr_End_Date=ISNULL((SELECT TOP 1  DATEADD(Day, -1, Fiscalyear_Start_date) FROM Assets.FX_Company ORDER BY ID DESC),'1900-01-01'),Depr_Start_Date = ISNULL((SELECT TOP 1 Fiscalyear_Start_date FROM Assets.FX_Company ORDER BY ID DESC),'1900-01-01')
WHERE Depr_End_Date = '1900-01-01' AND IsActive = 1  AND ISNew=0

declare  @Asset_ID INT

DECLARE  Asset_cursor CURSOR FOR 
SELECT Asset_ID FROM Assets.FX_Assets WHERE IsActive=1 AND ISNew=0

OPEN Asset_cursor

FETCH NEXT FROM Asset_cursor into @Asset_ID
WHILE @@FETCH_STATUS = 0
BEGIN


UPDATE Assets.FX_Assets SET Monthly_Deper=((Total_Cost * Depreciation)/100)/12 , Asset_Age=(100/Depreciation)*12
WHERE Asset_ID=@Asset_ID 

UPDATE Assets.FX_Assets SET Age_Used=DATEDIFF(MONTH,Purchase_Date,Depr_End_Date)-1 ,Age_Remain=Asset_Age-Age_Used
WHERE Asset_ID=@Asset_ID 

FETCH NEXT FROM Asset_cursor  into @Asset_ID
    
    --end while
END



CLOSE Asset_cursor;
DEALLOCATE Asset_cursor;


END






GO
/****** Object:  StoredProcedure [Assets].[SubSubGroups_GetAll]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[SubSubGroups_GetAll]
AS
BEGIN

SELECT  SSG_Code, SSG_ID  ,SSG_Name ,CASE WHEN IsActive = 0 THEN 'غير فعال' ELSE 'فعال' END AS IsActive   FROM Assets.FX_SubSubGroup ORDER BY SSG_ID
END






GO
/****** Object:  StoredProcedure [Assets].[SubSubGroups_lastCode]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[SubSubGroups_lastCode]
@SG_ID INT,
@G_ID int
AS
BEGIN
SELECT CASE WHEN  MAX(SSG_Code) IS NULL then 1 ELSE  MAX(SSG_Code)+1 END AS SSG_Code FROM Assets.FX_SubSubGroup
WHERE SG_ID=@SG_ID AND G_ID =@G_ID
END






