CREATE proc [Assets].[usp_FX_AssetsSelectByID] 
    @Asset_ID int
AS 
	SELECT [Asset_ID]
      ,[Asset_Code]
      ,[Asset_Name]
      ,[Create_by]
      ,[Modify_by]
      ,[CustomeText1]
      ,[CustomeText2]
      ,[CustomeText3]
      ,[Asset_Comment]
      ,[Create_Date]
      ,[Modify_Date]
      ,[IsActive]
      ,[G_ID]
      ,[SG_ID]
      ,[SSSG_ID]
      ,[SSG_ID]
      ,[Supplier_ID]
      ,[Depreciation]
      ,[Depr_Start_Date]
      ,[Depr_End_Date]
      ,[Purchase_Date]
      ,[Pic_Dirctory]
      ,[POnumber]
      ,[Asset_Age]
      ,[Asset_Qty]
      ,[Unite_Price]
      ,[Total_Cost]
      ,[Depr_Total]
      ,[Asset_Net]
      ,[Extrnal_value]
      ,[Unite_ID]
      ,[Genral_Depr]
      ,[Depr_Total_Extrnal]
      ,[Asset_Net_extrnal]
      ,[Monthly_Deper]
      ,ISNULL((SELECT SUM(EX_Qty)FROM Assets.FX_Asset_Exclusion WHERE Asset_ID=@Asset_ID),0) AS TOTALEXQTY
	  	  ,SerialNumber
	  ,LocationID
	  ,EmpID
	  ,IsMedical
	  ,IsEquipment
	  MainAccNo,
		   SubAccNo,
		  DepreciationExpenceisACC,
		  TotalDepreciationAccount,
		   DepreciationExpenceisSubACC,
		  TotalDepreciationSubAccount
	FROM Assets.FX_Assets 
