CREATE proc [Assets].[usp_FX_GroupsUpdate] 
    @G_ID int,
    @G_Name nvarchar(500),
    @Modify_by nvarchar(100),
    @IsActive bit
AS 
	BEGIN

	UPDATE [Assets].[FX_Groups]
	SET    [G_Name] = @G_Name, [Modify_by] = @Modify_by,  [IsActive] = @IsActive,Modify_Date=GETDATE()
	WHERE  [G_ID] = @G_ID
	
	
	END






