CREATE proc [Assets].[usp_FX_SubGrouplastCode]
@G_ID INT
AS
BEGIN
SELECT CASE WHEN  MAX(SG_Code) IS NULL then 1 ELSE  MAX(SG_Code)+1 END AS SG_Code FROM Assets.FX_SubGroup 
WHERE G_ID=@G_ID
