CREATE proc [Assets].[usp_FX_SubSubGroupDelete] 
    @SSG_ID int
AS 
	SET NOCOUNT ON 
	SET XACT_ABORT ON  
	
	BEGIN TRAN

	DELETE
	FROM   [Assets].[FX_SubSubGroup]
	WHERE  [SSG_ID] = @SSG_ID

	COMMIT






