/****** Object:  StoredProcedure [Assets].[usp_FX_SubSubGroupInsert]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[usp_FX_SubSubGroupInsert] 
 
	@SSG_Name nvarchar(500),
	@G_ID INT,
	@SG_ID INT,
    @Create_by nvarchar(100),
    @Modify_by nvarchar(100),
    @IsActive INT,
    @SSG_Code INT
AS 
BEGIN
	
IF Not EXISTS(SELECT SSG_ID FROM Assets.FX_SubSubGroup WHERE SSG_Name=@SSG_Name)
BEGIN
		INSERT INTO [Assets].FX_SubSubGroup (SSG_Code,[SSG_Name], [Create_by], Modify_by ,[Create_Date],[IsActive],G_ID,SG_ID)
	VALUES     (@SSG_Code,@SSG_Name, @Create_by, @Modify_by, GETDATE() ,@IsActive,@G_ID,@SG_ID)
END	
END






