CREATE proc [Assets].[usp_FX_SubSubGroupSelect] 
    @SSG_Code INT,
    @SG_ID INT,
    @G_ID INT
AS 
	SET NOCOUNT ON 
	SET XACT_ABORT ON  

	BEGIN TRAN

	SELECT [SSG_ID], [SSG_Code], [SSG_Name], [Create_by], [Modify_by], [CustomeText1], [CustomeText2], [CustomeText3], [SSG_Comment], [Create_Date], [Modify_Date], [IsActive], [G_ID], [SG_ID] 
	FROM   [Assets].[FX_SubSubGroup] 
	WHERE  ([SSG_Code] = @SSG_Code OR @SSG_Code IS NULL) AND SG_ID=@SG_ID AND G_ID=@G_ID

	COMMIT






