CREATE proc [Assets].[usp_FX_SubSubGroupUpdate] 
    @G_ID int,
    @SG_ID int,
    @SSG_Code int,
    @SSG_Name nvarchar(500),
    @Modify_by nvarchar(100),
    @IsActive bit
AS 
	BEGIN

	UPDATE [Assets].[FX_SubSubGroup]
	SET    [SSG_Name] = @SSG_Name, [Modify_by] = @Modify_by,  [IsActive] = @IsActive,Modify_Date=GETDATE(),G_ID=@G_ID,SG_ID=@SG_ID
