CREATE proc [Assets].[usp_FX_SuppliersDelete] 
    @Supplier_ID int
AS 
	SET NOCOUNT ON 
	SET XACT_ABORT ON  
	
	BEGIN TRAN

	DELETE
	FROM   [Assets].[FX_Suppliers]
	WHERE  [Supplier_ID] = @Supplier_ID

	COMMIT






