/****** Object:  StoredProcedure [Assets].[usp_Fx_SuppliersInsert]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Assets].[usp_Fx_SuppliersInsert] 
    @Supplier_Name nvarchar(500),
    @Create_by nvarchar(100),
    @Modify_by nvarchar(100),
    @IsActive int,
	@MainAcc int
	,@SubAcc int
AS 
BEGIN
	
IF Not EXISTS(SELECT Supplier_ID FROM Assets.FX_Suppliers WHERE Supplier_Name=@Supplier_Name)
BEGIN
		INSERT INTO [Assets].[FX_Suppliers] (Supplier_Name, CreatedBy,LastModifiedBy ,CreatedDate,[IsActive],MainAcc,SubAcc)
	VALUES     (@Supplier_Name, @Create_by, @Modify_by, GETDATE() ,@IsActive,@MainAcc,@SubAcc)
END	



end






