CREATE proc [Assets].[usp_FX_SuppliersSelect] 
    @Supplier_ID int
AS 
	SET NOCOUNT ON 
	SET XACT_ABORT ON  

	BEGIN TRAN

	SELECT [Supplier_ID], [Supplier_Code], [Supplier_Name], CreatedBy, LastModifiedBy, [CustomeText1], [CustomeText2], [CustomeText3], [Supplier_Comment], CreatedDate, LastModifiedDate, [IsActive] ,MainAcc,SubAcc
	FROM   [Assets].[FX_Suppliers] 
	WHERE  ([Supplier_ID] = @Supplier_ID OR @Supplier_ID IS NULL) 

	COMMIT






