GO

CREATE procedure [Banking].[SP_ChequesReport]
@BankAccount nvarchar(50) null,
@ChequeNumber nvarchar(50) null,
@status int null
as
begin
select Banking.ChequeDetails.BankAccount,Banking.ChequeDetails.ChequeNumber,Banking.ChequeDetails.[Status]
from Banking.ChequeDetails
where (Banking.ChequeDetails.BankAccount = @BankAccount or @BankAccount is null)
and (Banking.ChequeDetails.ChequeNumber = @ChequeNumber or @ChequeNumber is null)
