/****** Object:  StoredProcedure [Billing].[BoxTotalreport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE proc [Billing].[BoxTotalreport]
(@DateFrom datetime,@DateTo datetime)
AS
BEGIN
select jd.AccountId
  ,sum(jd.LocalCredit) LocalCredit
  ,sum(jd.LocalDebit) LocalDebit
  ,box.NameAr BoxName
  ,box.NameEn BoxNameEn
  ,a.AccountNo
  ,a.AccountNameAr
  ,a.AcountNameEn
from gl.Journal j 
	inner join gl.JournalDetails jD on j.JournalId=jd.JournalId
	inner join Billing.CashierBox box on jd.AccountId=box.AccNo
	inner join gl.accounts a on jd.AccountId=a.id

WHERE 
--	j.Date >= Convert(date,@DateFrom,103)
--and j.Date<= Convert(date,@DateTo,103)
(@DateFrom is null or j.Date>= Cast(@DateFrom as date))
 and (@DateTo is null or j.Date<= Cast(@DateTo as date))
 group by  jd.AccountId,box.NameAr ,box.NameEn , a.AccountNo,a.AccountNameAr,a.AcountNameEn
END 




GO
/****** Object:  StoredProcedure [Billing].[CancelledServices]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Billing].[CancelledServices]
(
@dateFrom Datetime,
@dateTo dateTime 
)
AS
SELECT 
	PatientLimit.ReasonofRejection , 
	ser.NameEn ,
	PatientLimit.otherReason ,
	[Registration].Patients.Code, 
	[Registration].Patients.TranslatedFallName,
	Billing.InsuranceCompanies.NameEnglish as InsuranceNameEn , 
	Billing.InsuranceCompanies.NameArabic as InsuranceNameAr ,
	PatientLimit.LastModifiedDate  CancelDate,
 Case  when ISNULL(PatientLimit.Cancelled,0) =1 then 'Cancelled' else 'Pay Cash' End RejectionAction

FROM 
	[Billing].PatientInsuranceLimitdetail PatientLimit
	inner Join [Billing].PatientInsuranceLimitMaster on [Billing].PatientInsuranceLimitMaster.Id=PatientLimit.PatientInsuranceLimitMasterId
	inner join [Registration].Patients on [Registration].Patients.Id=[Billing].PatientInsuranceLimitMaster.PatientId
	Join [ApplicationSetup].Service as ser on ser.Id = PatientLimit.ServiceId
	inner Join Billing.InsuranceCompanies on Billing.InsuranceCompanies.ID= [Billing].PatientInsuranceLimitMaster.InsCompID
where PatientLimit.DetStatus =3 
