select distinct  null as EntryCode,'' as VoucherCode,format(op.Datetime,'dd/MM/yyyy HH:mm') as VoucherDate ,'' as PatientCode,ConfByu.UserName  as Confirmed,u.UserName,op.CreatedDate,cb.AccNo, cb.id , [Description]='Confirmed by master'

,
'' as [Person Name]
,[Incomming]=0

,[Exporting]=op.Amount
,0[cash],0 [visa]
From Billing.CashierBox as CB
inner join Billing.CashierBoxOpenSessions As op on CB.id=op.BoxID
left join JCIT_MembershipDB.dbo.AspNetUsers as u on op.UserID=u.id
left join Billing.CashierBoxOpenSessions as ConfBy on op.ConfirmedByCashierBoxOpenSessionID=ConfBy.ID
left join JCIT_MembershipDB.dbo.AspNetUsers as ConfByu on ConfBy.UserID=ConfByu.id
join Billing.CashierBox as Confirmedcb on Confirmedcb.ID=ConfBy.BoxID
where cb.BoxType=2 and Confirmedcb.BoxType=1
and (op.BoxID=@BoxID or @BoxID is null)
and (op.ConfirmDate >= Convert(datetime2(7),@Date)  or @Date is null) 
and (op.ConfirmDate <= Convert(datetime2(7),@ToDate)  or @ToDate is null) 
and @VoOnly=0
and op.Status=4
) ConfirmedByMaster
) AllTbl
order by CreatedDate
End




