CREATE procEDURE [Billing].[CashierSessionsBalance] --'2020-01-01','2023-01-01',0,''

(
@DateFrom DateTime = null,@DateTo DateTime = null,
@CahierBoxId int=null,@UserId nvarchar(50)=null

)
AS
BEGIN
if(@CahierBoxId=0 and @UserId='')
begin
SELECT        CashierBox.NameEn as CashierBoxName, AspNetUsers.UserName as UserName,
 openChild.Status As StatusNo,
    
 DATEDIFF(HOUR, openChild.ConfirmDate, openChild.CloseDate) 
                         AS SessionHours, confuser.EnglishName AS confirmedby, 
						 AspNetUsers.EnglishName AS cashieruser, 
						 closeuser.EnglishName AS Closedby, 
						 AspNetUsers.EnglishName AS ClosingUser, 
						openChild.ConfirmDate as ConfirmDate,
						openChild.Datetime as SessionStartDate,
						openChild.CloseDate  as CloseDate,
						 openChild.SessionStartBalance,openChild.InAmount, 
                         openChild.OutAmount,openChild.Amount,
						 ISNULL(openChild.SessionStartBalance,0)+isnull(openChild.Amount,0) as total
						 ,case when openChild.Status=2 then 'Confirmed' when openChild.Status=3 then'Closed' else 'Confirmed By Master' End as StatusName


FROM            Billing.CashierBox AS CashierBox INNER JOIN
                         Billing.CashierBoxOpenSessions AS openChild ON CashierBox.ID = openChild.BoxID LEFT OUTER JOIN
                         JCIT_MembershipDB.dbo.AspNetUsers AS AspNetUsers ON openChild.UserID = AspNetUsers.Id LEFT OUTER JOIN
