/****** Object:  StoredProcedure [Billing].[CashierSessionsBalance_AR]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [Billing].[CashierSessionsBalance_AR]
(
    @DateFrom    DATETIME = NULL,
    @DateTo      DATETIME = NULL,
    @CahierBoxId INT = NULL,
    @UserId      NVARCHAR(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
         COALESCE(CashierBox.NameAr, CashierBox.NameEn) AS [اسم_الصندوق]
        ,AspNetUsers.UserName                           AS [اسم_المستخدم]
        ,openChild.Status                               AS [رقم_الحالة]
        ,DATEDIFF(HOUR, openChild.ConfirmDate, openChild.CloseDate) AS [عدد_ساعات_الجلسة]
        ,confuser.EnglishName                           AS [تم_التأكيد_بواسطة]
        ,AspNetUsers.EnglishName                        AS [اسم_الكاشير]
        ,closeuser.EnglishName                          AS [تم_الإغلاق_بواسطة]
        ,AspNetUsers.EnglishName                        AS [مستخدم_الإغلاق]
        ,openChild.ConfirmDate                          AS [تاريخ_التأكيد]
        ,openChild.[Datetime]                           AS [تاريخ_بدء_الجلسة]
        ,openChild.CloseDate                            AS [تاريخ_الإغلاق]
        ,openChild.SessionStartBalance                  AS [رصيد_بداية_الجلسة]
        ,openChild.InAmount                             AS [إجمالي_الوارد]
        ,openChild.OutAmount                            AS [إجمالي_المنصرف]
        ,openChild.Amount                               AS [صافي_الحركة]
        ,ISNULL(openChild.SessionStartBalance, 0) + ISNULL(openChild.Amount, 0) AS [الإجمالي]
        ,CASE
            WHEN openChild.Status = 2 THEN N'مؤكد'
            WHEN openChild.Status = 3 THEN N'مغلقة'
            ELSE N'مؤكد من الصندوق الرئيسي'
         END                                            AS [اسم_الحالة]
    FROM Billing.CashierBox AS CashierBoxਊ    䤀一一䔀刀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀愀猀栀椀攀爀䈀漀砀伀瀀攀渀匀攀猀猀椀漀渀猀 䄀匀 漀瀀攀渀䌀栀椀氀搀਀        伀一 䌀愀猀栀椀攀爀䈀漀砀⸀䤀䐀 㴀 漀瀀攀渀䌀栀椀氀搀⸀䈀漀砀䤀䐀਀    䰀䔀䘀吀 䨀伀䤀一 䨀䌀䤀吀开䴀攀洀戀攀爀猀栀椀瀀䐀䈀⸀搀戀漀⸀䄀猀瀀一攀琀唀猀攀爀猀 䄀匀 䄀猀瀀一攀琀唀猀攀爀猀਀        伀一 漀瀀攀渀䌀栀椀氀搀⸀唀猀攀爀䤀䐀 㴀 䄀猀瀀一攀琀唀猀攀爀猀⸀䤀搀਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀愀猀栀椀攀爀䈀漀砀伀瀀攀渀匀攀猀猀椀漀渀猀 䄀匀 挀氀漀猀攀瀀愀爀攀渀琀਀        伀一 漀瀀攀渀䌀栀椀氀搀⸀倀愀爀攀渀琀䌀愀猀栀椀攀爀䈀漀砀伀瀀攀渀匀攀猀猀椀漀渀䤀䐀 㴀 挀氀漀猀攀瀀愀爀攀渀琀⸀䤀䐀਀    䰀䔀䘀吀 䨀伀䤀一 䨀䌀䤀吀开䴀攀洀戀攀爀猀栀椀瀀䐀䈀⸀搀戀漀⸀䄀猀瀀一攀琀唀猀攀爀猀 䄀匀 挀氀漀猀攀甀猀攀爀਀        伀一 挀氀漀猀攀甀猀攀爀⸀䤀搀 㴀 挀氀漀猀攀瀀愀爀攀渀琀⸀唀猀攀爀䤀䐀਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀愀猀栀椀攀爀䈀漀砀伀瀀攀渀匀攀猀猀椀漀渀猀 䄀匀 䌀漀渀昀䈀礀਀        伀一 䌀漀渀昀䈀礀⸀䤀䐀 㴀 漀瀀攀渀䌀栀椀氀搀⸀䌀漀渀昀椀爀洀攀搀䈀礀䌀愀猀栀椀攀爀䈀漀砀伀瀀攀渀匀攀猀猀椀漀渀䤀䐀਀    䰀䔀䘀吀 䨀伀䤀一 䨀䌀䤀吀开䴀攀洀戀攀爀猀栀椀瀀䐀䈀⸀搀戀漀⸀䄀猀瀀一攀琀唀猀攀爀猀 䄀匀 挀漀渀昀甀猀攀爀਀        伀一 挀漀渀昀甀猀攀爀⸀䤀搀 㴀 䌀漀渀昀䈀礀⸀唀猀攀爀䤀䐀਀    圀䠀䔀刀䔀 漀瀀攀渀䌀栀椀氀搀⸀匀琀愀琀甀猀 㸀 ㄀਀      䄀一䐀 ⠀漀瀀攀渀䌀栀椀氀搀⸀嬀䐀愀琀攀琀椀洀攀崀 㸀㴀 䀀䐀愀琀攀䘀爀漀洀 伀刀 䀀䐀愀琀攀䘀爀漀洀 䤀匀 一唀䰀䰀⤀਀      䄀一䐀 ⠀䤀匀一唀䰀䰀⠀漀瀀攀渀䌀栀椀氀搀⸀䌀氀漀猀攀䐀愀琀攀Ⰰ 䀀䐀愀琀攀吀漀⤀ 㰀㴀 䀀䐀愀琀攀吀漀 伀刀 䀀䐀愀琀攀吀漀 䤀匀 一唀䰀䰀⤀਀      䄀一䐀 ⠀਀            䀀䌀愀栀椀攀爀䈀漀砀䤀搀 䤀匀 一唀䰀䰀਀            伀刀 䀀䌀愀栀椀攀爀䈀漀砀䤀搀 㴀 　਀            伀刀 漀瀀攀渀䌀栀椀氀搀⸀䈀漀砀䤀䐀 㴀 䀀䌀愀栀椀攀爀䈀漀砀䤀搀਀          ⤀਀      䄀一䐀 ⠀਀            䀀唀猀攀爀䤀搀 䤀匀 一唀䰀䰀਀            伀刀 䀀唀猀攀爀䤀搀 㴀 一✀✀਀            伀刀 漀瀀攀渀䌀栀椀氀搀⸀唀猀攀爀䤀䐀 㴀 䀀唀猀攀爀䤀搀਀          ⤀਀    伀刀䐀䔀刀 䈀夀 漀瀀攀渀䌀栀椀氀搀⸀嬀䐀愀琀攀琀椀洀攀崀㬀਀䔀一䐀਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䈀椀氀氀椀渀最崀⸀嬀䌀愀猀栀椀攀爀吀漀琀愀氀䴀漀渀攀礀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 倀爀漀挀 嬀䈀椀氀氀椀渀最崀⸀嬀䌀愀猀栀椀攀爀吀漀琀愀氀䴀漀渀攀礀崀ഀ਀⠀ഀ਀䀀䘀爀漀洀䐀愀琀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ 渀甀氀氀Ⰰഀ਀䀀吀漀䐀愀琀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ 渀甀氀氀Ⰰഀ਀䀀䈀漀砀䤀䐀 椀渀琀 渀甀氀氀ഀ਀⤀ഀ਀愀猀ഀ਀ഀ਀ഀ਀匀䔀䰀䔀䌀吀     䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀⸀䌀愀猀栀Ⰰ䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀⸀嘀椀猀愀Ⰰ䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀⸀䌀愀猀栀椀攀爀䈀漀砀䤀䐀Ⰰ 䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀⸀䤀搀Ⰰ䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀⸀倀愀椀搀䐀愀琀攀Ⰰഀ਀椀猀渀甀氀氀⠀⠀䌀愀猀栀⬀嘀椀猀愀⤀Ⰰ　⤀ 䄀匀 倀愀琀攀椀渀琀倀愀椀搀䄀洀漀甀渀琀Ⰰ 椀猀渀甀氀氀⠀匀瀀漀渀猀攀爀倀愀椀搀䄀洀漀甀渀琀Ⰰ　⤀ 䄀匀 匀瀀漀渀猀攀爀䄀洀漀甀渀琀Ⰰ ഀ਀䈀椀氀氀椀渀最⸀䌀愀猀栀椀攀爀䈀漀砀⸀一愀洀攀䔀渀 愀猀 䌀愀猀栀椀攀爀一愀洀攀䔀渀Ⰰ 䈀椀氀氀椀渀最⸀䌀愀猀栀椀攀爀䈀漀砀⸀一愀洀攀䄀爀 愀猀 䌀愀猀栀椀攀爀一愀洀攀䄀爀ഀ਀Ⰰ䈀椀氀氀椀渀最⸀䤀渀猀甀爀愀渀挀攀䌀漀洀瀀愀渀椀攀猀⸀一愀洀攀䄀爀愀戀椀挀 愀猀 匀瀀漀渀猀攀爀一愀洀攀䄀爀Ⰰ䈀椀氀氀椀渀最⸀䤀渀猀甀爀愀渀挀攀䌀漀洀瀀愀渀椀攀猀⸀一愀洀攀䔀渀最氀椀猀栀 愀猀 匀瀀漀渀猀攀爀一愀洀攀䔀渀Ⰰഀ਀ഀ਀䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀匀攀爀瘀椀挀攀⸀刀攀挀漀爀搀一愀洀攀 愀猀 匀攀爀瘀椀挀攀一愀洀攀䔀渀 Ⰰ䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀匀攀爀瘀椀挀攀⸀一愀洀攀䄀爀 愀猀 匀攀爀瘀椀挀攀一愀洀攀䄀爀ഀ਀ Ⰰ椀猀渀甀氀氀 ⠀刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀⸀䘀椀爀猀琀一愀洀攀Ⰰ✀✀⤀ ⬀ ✀ ✀⬀ 椀猀渀甀氀氀 ⠀刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀⸀䴀椀搀搀氀攀一愀洀攀㄀Ⰰ✀✀⤀ ⬀ ✀ ✀⬀椀猀渀甀氀氀 ⠀刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀⸀䴀椀搀搀氀攀一愀洀攀㈀Ⰰ✀✀⤀ ⬀ ✀ ✀⬀椀猀渀甀氀氀 ⠀刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀⸀䰀愀猀琀一愀洀攀Ⰰ✀✀⤀ഀ਀ ഀ਀
 --Registration.Patients.FirstName +' ' +Registration.Patients.MiddleName1 +' ' + Registration.Patients.MiddleName2 +
 --' ' + Registration.Patients.LastName 
 as PatientNameAr,
 isnull (Registration.Patients.TranslatedFallName,Registration.Patients.FirstName)as PatientNameEn,Billing.PatientBillservices.PaidDate
 --Registration.Patients.TranslatedFallName 
 
FROM            Billing.PatientBillservices INNER JOIN
                         Billing.PatientBill ON Billing.PatientBillservices.PatientBillID = Billing.PatientBill.Id INNER JOIN
                         Billing.CashierBox ON Billing.PatientBillservices.CashierBoxID = Billing.CashierBox.ID
						 inner join ApplicationSetup.Service on PatientBillservices.ItemID=ApplicationSetup.Service.Id
						 inner join Registration.Patients on Billing.PatientBill.PatientID=Registration.Patients.id
						 left join Billing.InsuranceCompanies on  
						 Billing.PatientBillservices.SponserId=Billing.InsuranceCompanies.ID
WHERE        (Billing.PatientBillservices.Paid = 1) 
and (Billing.PatientBillservices.Canceled is NULL or Billing.PatientBillservices.Canceled=0)
and(Billing.PatientBillservices.CashierBoxID=@BoxID )
and (Billing.PatientBillservices.PaidDate >= Cast(@FromDate as date) )
and (Billing.PatientBillservices.PaidDate <= DATEADD(day, 1, @ToDate))

--and (Billing.PatientBillservices.PaidDate < convert(datetime,@Todate) or @Todate is null) 
--(Billing.PatientBillservices.PaidDate >= convert(datetime,@FromDate) or @FromDate is null)
--and (Billing.PatientBillservices.PaidDate < convert(datetime,@Todate) or @Todate is null)
--                and (Billing.PatientBillservices.CashierBoxID  = BoxID )
--and (((@FromDate is null or Billing.PatientBillservices.PaidDate>= Cast(@FromDate as date))
-- and (@ToDate is null or Billing.PatientBillservices.PaidDate<= Cast(@ToDate as date))))  
				order by Billing.PatientBillservices.PaidDate
                 
				
				




--update [Billing].[PatientBillservices] set [CashierBoxID]=12 where Billing.PatientBillservices.Paid = 1

