/****** Object:  StoredProcedure [Billing].[ContractReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE Proc [Billing].[ContractReport]
(

@InsuranceCompanyId int ,@year int 
)
as


SELECT      InsCompany.NameEnglish ,
InsCompany.NameArabic ,
InsCompany.Address ,
InsCompany.Phone ,
IContract .Renewal_date ,
IContract.Issue_Date ,
IContract.Valid_To ,
IContract.PriceList_Header_Id 
,
'Deduction_Applied '
 = 
  CASE 
     WHEN IContract.Deduction_Applied=  1 THEN 'After Discount'
     WHEN IContract.Deduction_Applied = 2THEN 'Before Discount'
     
     ELSE ''
  END ,
  
'Discount_Offered '
 = 
  CASE 
     WHEN IContract.Discount_Offered  = 1 THEN 'Yes'
     WHEN IContract.Discount_Offered = 0THEN 'No'
     
     ELSE ''
  END 

,Billing.PriceListHeader. Name_En 
,Billing.PriceListHeader. Name_Ar
,Discount   .Discount
,Discount   .DeptID
,
costcenter.Name ,
'Discount_Type'
 = 
  CASE 
     WHEN Discount.Discount_Type=  1 THEN 'Fixed'
     WHEN Discount.Discount_Type = 2THEN '%'
     
     ELSE ''
  END


FROM            Billing.Insurance_Comp_Contract as IContract 
  inner  join Billing.InsuranceCompanies as InsCompany
				  on IContract.Ins_CompanyID =InsCompany.ID
                 left  JOIN
                  Billing.INS_Company_Contract_Discount  as Discount   
				  on   IContract.ID = Discount.ContractID
				
				  left Join Billing.PriceListHeader 
				  on  IContract.PriceList_Header_Id = PriceListHeader.PriceList_Header_Id
			left Join ApplicationSetup.CostCenter as costcenter
				  on Discount.DeptID =costcenter.Id

WHERE       IContract.Ins_CompanyID =@InsuranceCompanyId
