/****** Object:  StoredProcedure [Billing].[CoverageApprovalsFollow-upReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [Billing].[CoverageApprovalsFollow-upReport]
@PatientId INT = NULL,
@DateFrom DATETIME = NULL,
@DateTo DATETIME = NULL
AS
BEGIN
SET NOCOUNT ON;
SELECT
    InsuranceLimitMaster.ApprovalCode AS ApprovalNo,
    patients.Code AS MRN,
    patients.TranslatedFallName,
    Registration.Doctors.Name AS Physician,
    'Clinic' =
        CASE
            WHEN InsuranceLimitMaster.PatientType = 1 THEN OutPatient.ClinicSetup.NameEnglish
            WHEN InsuranceLimitMaster.PatientType = 2 THEN InPatient.Ward.Name
            WHEN InsuranceLimitMaster.PatientType = 3 THEN 'Referred '
            WHEN InsuranceLimitMaster.PatientType = 4 THEN 'Emergancy Triage'
            ELSE 'All'
        END,
    'PatientType' =
        CASE
            WHEN InsuranceLimitMaster.PatientType = 1 THEN ' OutPateint'
            WHEN InsuranceLimitMaster.PatientType = 2 THEN 'InPateint'
            WHEN InsuranceLimitMaster.PatientType = 3 THEN 'Referred '
            WHEN InsuranceLimitMaster.PatientType = 4 THEN 'Emergancy'
            ELSE 'All'
        END,
    patients.Id,
    FORMAT(InsuranceLimitMaster.RequestDate, 'dd/MM/yyyy ') AS Requesteddate,
    'Status' =
        CASE
            WHEN InsuranceLimitMaster.Status = 1 THEN 'Requested'
            WHEN InsuranceLimitMaster.Status = 2 THEN 'Approved'
            WHEN InsuranceLimitMaster.Status = 3 THEN 'Closed'
            ELSE ''
        END
FROM Billing.PatientInsuranceLimitMaster AS InsuranceLimitMaster
INNER JOIN Registration.Patients AS patients
    ON InsuranceLimitMaster.PatientId = patients.Id

LEFT JOIN OutPatient.InvestigationRequestDetails
