DECLARE @DoctorServiceCashPercentage DECIMAL  
SELECT  @DoctorServiceCashPercentage=DoctorServiceCashPercentage FROM Billing.DoctorFeesPercentage
--PRINT @DoctorServiceCashPercentage

 --get doctor precentage of insurance service
DECLARE @DoctorServiceInsurancePercentage DECIMAL  
SELECT  @DoctorServiceInsurancePercentage=DoctorServiceInsurancePercentage FROM Billing.DoctorFeesPercentage
--PRINT @DoctorServiceInsurancePercentage

--get doctor precentage of cash Operation
DECLARE @DoctorOperationCashPercentage DECIMAL  
