DECLARE @OperationDiscountPrecentage DECIMAL   

DECLARE @PaymentTypeCash NVARCHAR(MAX)
 SET @PaymentTypeCash = CASE 
							 WHEN @Lang = 'En' THEN 'Cash'
							 ELSE N'كاش'
					   END

DECLARE @DetectFeesType NVARCHAR(MAX)
 SET @DetectFeesType = CASE 
							 WHEN @Lang = 'En' THEN 'Detect'
							 ELSE N'كشف'
					   END

DECLARE @ServiceFeesType NVARCHAR(MAX)
 SET @ServiceFeesType = CASE 
							 WHEN @Lang = 'En' THEN 'Service'
							 ELSE N'خدمة'
					     END


DECLARE @OperationFeesType NVARCHAR(MAX)
 SET @OperationFeesType = CASE 
							 WHEN @Lang = 'En' THEN 'Operation'
							 ELSE N'عملية'
					      END
DECLARE @ServiceDeviceFeesType NVARCHAR(MAX)
 SET @ServiceDeviceFeesType = CASE 
							 WHEN @Lang = 'En' THEN 'Service With Device'
							 ELSE N'خدمة تستخدم جهاز'
					     END
