----------------------------------------------------Detects-----------------------------------------------------
WITH [TempTable] AS
(
select IC.id AS IcId, PLS.ServiceId, ServicePriceAfterInsuranceDiscount=PLS.PriceAfterDiscount from Billing.InsuranceCompanies IC
													join Billing.Insurance_Comp_Contract ICC on ICC.Ins_CompanyID=IC.ID
													join Billing.PriceListHeader PLH on PLH.PriceList_Header_Id=ICC.PriceList_Header_Id
													join Billing.PriceListDepartment PLD on PLD.PriceList_Header_Id =PLH.PriceList_Header_Id
													join Billing.PriceListServices PLS on PLS.PriceListDepartment_ID = PLD.PriceListDepartment_ID 
													where ICC.Valid_To >= CONVERT(DATE,getdate())
)
--  IC.id=Pat.SponsorId and  PLS.ServiceId= Serv.Id
SELECT distinct  	DDSD.Id , Pat.FirstName+' '+Pat.MiddleName1+' '+Pat.MiddleName1+' '+Pat.LastName [Patien Name], 
       DDS.ScheduleDate [Service Date],
	   Serv.RecordName [Service Name],
	   Serv.price [Service Price],
	   [RefeeralDoctor Name] =CASE 
							WHEN  @Lang = 'En'  THEN RTY.NameEnglish
							ELSE   RTY.NameArabic
						END
	   
	   
