 UNION ALL

SELECT distinct 	PBS.Id , Pat.FirstName+' '+Pat.MiddleName1+' '+Pat.MiddleName1+' '+Pat.LastName [Patien Name],
       RSH.CreatedDate [Service Date],
	   Serv.RecordName [Service Name],
	   Serv.price [Service Price],
	   '',
	   Doc.Name [DoctorName]
	   ,[Doctor Percentage]= CASE
	   	WHEN Pat.SponsorId= 0 or Pat.SponsorId IS NULL    THEN 
									Case When dfd.Service_Cash_Perc  IS NULL
									then
									Serv.price*(@DoctorServiceCashPercentage/100)
									else
									Serv.price*(dfd.Service_Cash_Perc /100)
									End

									ELSE

									Case When dfd.Service_Sponser_Perc  IS NULL
									then
										CASE
											WHEN  [TempTable].[IcId] IS NOT NULL
											THEN [TempTable].[ServicePriceAfterInsuranceDiscount] *(@DoctorServiceInsurancePercentage/100)
											ELSE Serv.price*(@DoctorServiceInsurancePercentage/100)
										END 
