CREATE  Procedure [Billing].[E_Claims_Report] --'2023-04-01','2023-04-26',5079
(@FDate nvarchar(20)=null,@TDate nvarchar(20)=null,@ins_ID int=null
)
as
begin

update   Billing.PatientInsuranceLimitdetail
set IPOPNo=(select top 1 IPNumber from InPatient.AdmitPatients  where id= Billing.PatientInsuranceLimitdetail.AdmitPatientID)
where AdmitPatientID >0 and IPOPNo is null
--delete [Billing].EclaimEdit;
 
SELECT distinct ISNULL(PatientBillservices.Canceled,0) Canceled,
--Comment By maher
 @ins_ID ins_ID ,
[InsuranceCompanies].ID as tt,
PatientBillservices.id as UniqeID,[PatientInsuranceLimitdetail].RejectResponsibility,[PatientInsuranceLimitdetail].ReasonofRejection as ReasonReject,
[PatientInsuranceLimitdetail].otherReason as otherReason,
PatientBillservices.SponserApproveStatus,
-------------
[PatientBill].[ReceiptDate],

	[Patients].[Id] AS [PatientId]
	, DENSE_RANK() OVER (ORDER BY [Patients].[Id]) AS [ClaimCount]
	, [Registration].[PatientInsurance].MemberShipId AS [PatientMemberShipId]
	, [Patients].[Code] AS [PatientCode]
	,    [Ins_Company_Policy].[PolicyNo] PolicyNo
	, [InsuranceCompanies].[NameArabic] AS[InsuranceCompaniesNameArabic]
	, [InsuranceCompanies].[NameEnglish] AS[InsuranceCompaniesNameEnglish]
	, [Ins_Company_Policy].[PolicyName]
	, ISNULL([Patients].[FirstName], '') + N' ' + ISNULL([Patients].[MiddleName1], '') + N' ' + ISNULL([Patients].[MiddleName2], '') + N' ' + ISNULL([Patients].[LastName], '') AS [PatientName]
