	, CONVERT(VARCHAR(8), DATEADD(SECOND, DATEDIFF(SECOND,LEmergencyUnit.[Date], LEmergencyUnit.[SeenDateTime]),0), 108) AS [EmergencyWaitingTime]
	, Billing.EclaimEdit.[ServiceEventType]
	, Billing.EclaimEdit. [CareType]
	, Billing.EclaimEdit. [ActivityObjectCode_LOINC]
	, Billing.EclaimEdit. [ActivityObjectCodeValue_LOINC]
	,Billing.EclaimEdit.id as EditID,0 as Selected,
	[PatientInsuranceLimitdetail].Id as PatientInsuranceLimitdetail_ID,
	[PatientInsuranceLimitdetail].DetStatus ,
	[PatientBillservices].SponserApproveStatus
	,
	 [Billing].PriceListServices.Approve
FROM
	[Registration].[Patients]

	
 INNER JOIN [Billing].[PatientBill] ON [Patients].[Id] = [PatientBill].[PatientID]
	INNER JOIN [Billing].[PatientBillservices] ON [PatientBill].[Id] = [PatientBillservices].[PatientBillID]
INNER JOIN [Billing].[InsuranceCompanies]  on [InsuranceCompanies].[ID]  =[PatientBillservices].SponserId
INNER JOIN [Billing].Ins_Company_Policy ON [InsuranceCompanies].ID = [Ins_Company_Policy].InsCompanyID
INNER JOIN [Billing].[ins_Company_Class] ON [ins_Company_Class].PolicyID= [Ins_Company_Policy].ID 
inner join [Registration].[PatientInsurance] on Registration.PatientInsurance.PatientId=[Registration].[Patients].id
	and Registration.PatientInsurance.SponsorId=[PatientBillservices].SponserId
	and Registration.PatientInsurance.ins_ClassID=[ins_Company_Class].ID 
	
	inner join [Billing].Insurance_Comp_Contract on [Billing].Insurance_Comp_Contract.Ins_CompanyID= [InsuranceCompanies].[ID]
	and Insurance_Comp_Contract.Ins_CompanyID =[PatientBillservices].SponserId
	inner join [Billing].PriceListHeader on [Billing].PriceListHeader.PriceList_Header_Id=[Billing].Insurance_Comp_Contract.PriceList_Header_Id
	inner join [Billing].PriceListDepartment on [Billing].PriceListDepartment.PriceList_Header_Id= [Billing].PriceListHeader.PriceList_Header_Id
	inner join [Billing].PriceListServices on  [Billing].PriceListServices.PriceListDepartment_ID= [Billing].PriceListDepartment.PriceListDepartment_ID
