	OUTER APPLY (SELECT TOP 1 * FROM [Inpatient].[MedicalObservationICDCodes] WHERE [MedicalObservationID] = MOb2.[Id] AND [Type] = 3 AND [Id] < [MedicalObservationICDCodesFinal13].[Id] ORDER BY [Id] DESC) AS [MedicalObservationICDCodesFinal14]
