create  Procedure [Billing].[E_Claims_ReportTotal]
(@FDate nvarchar(20)=null,@TDate nvarchar(20)=null,@ins_ID int=null
)
as
begin

--delete [Billing].EclaimEdit;
--DECLARE @FDate nvarchar(20)=null,@TDate nvarchar(20)=null,@ins_ID int=null
select sum(BilledAmount) BilledAmount,SUM(Vat) Vat,SUM(LineItemDiscount) LineItemDiscount,SUM(TotalInvoiceDeductible) TotalInvoiceDeductible
from (
SELECT distinct 
--Comment By maher
-- 
PatientBillservices.id as UniqeID,
-------------
[PatientBill].[ReceiptDate],
	[Patients].[Id] AS [PatientId]
	, DENSE_RANK() OVER (ORDER BY [Patients].[Id]) AS [ClaimCount]
	, [Registration].[PatientInsurance].MemberShipId AS [PatientMemberShipId]
	, [Patients].[Code] AS [PatientCode]
	, [Ins_Company_Policy].[PolicyNo]
	, [InsuranceCompanies].[NameArabic] AS[InsuranceCompaniesNameArabic]
	, [InsuranceCompanies].[NameEnglish] AS[InsuranceCompaniesNameEnglish]
	, [Ins_Company_Policy].[PolicyName]
	, ISNULL([Patients].[FirstName], '') + N' ' + ISNULL([Patients].[MiddleName1], '') + N' ' + ISNULL([Patients].[MiddleName2], '') + N' ' + ISNULL([Patients].[LastName], '') AS [PatientName]
	, [Patients].[TranslatedFallName] AS [PatientNameEn]
	, [PatientBill].[ReceiptNumber] AS [InvoiceNumber]
	, FORMAT ([PatientBill].[ReceiptDate], 'ddMMyyyy') AS [InvoiceDate]
	, CASE LEFT([PatientBillservices].[OP_IPNumber], 2) WHEN 'OP' THEN  [PatientInsuranceLimitdetail].ApprovalCode else' ' End AS [PreauthId]
	, [Doctors].[Name] AS [DoctorNameEn]
	, [Doctors].[NameAr] AS [DoctorNameAr]
	, SpecialityGroupDetails.[Name] AS [SpecialtyNameEn]
	, SpecialityGroupDetails.[NameAr] AS [SpecialtyNameAr]
	, case when SpecialityGroupDetails.[Name]='Dental'  then  MOb2 .Complaints  else  MOb1 .Complaints End AS [ClinicalData]
	, [ICDCodesProvisional2].[ICDCode] AS [ICD10_1]
	, [ICDCodesPrimary2].[ICDCode] AS [ICD10_2]
	, [ICDCodesFinal11].[ICDCode] AS [ICD10_3]
	, [ICDCodesFinal12].[ICDCode] AS [ICD10_4]
	, CASE LEFT([PatientBillservices].[OP_IPNumber], 2)WHEN 'ER' THEN 'E' WHEN 'OP' THEN 'O' WHEN 'IP' THEN 'I' END AS [ClaimType]		-- OP:Outpatient, IP:InPatient, Pending Emergency
