	, [Patients].[PassportNumber] AS [UniqueMemberId]
	, [Patients].SCHC_LicenceNO AS [UniquePhysicianId]
	, FORMAT (CASE LEFT([PatientBillservices].[OP_IPNumber], 2) WHEN 'IP' THEN [AdmitPatients].[AdmissionDate] END, 'ddMMyyyy') AS [DateOfAdmission]
	,FORMAT( [PatientDischarge].[DischargDate],'ddMMyyyy') AS [DateOfDischarge]
	--, FORMAT (CASE LEFT([PatientBill].[IPOPNo], 2) WHEN 'IP' THEN NULL END, 'dd/MM/yyyy') AS [DateOfDischarge]
	--, CASE LEFT([PatientBillservices].[OP_IPNumber], 2) WHEN 'OP' THEN 'OutPatient' WHEN 'IP' THEN 'InPatient'WHEN 'ER' THEN 'Emergency' END AS [ClaimType]		-- OP:Outpatient, IP:InPatient, Pending Emergency
	, CASE LEFT([PatientBillservices].[OP_IPNumber], 2) WHEN 'IP' THEN [PatientBillservices].[OP_IPNumber] END AS [AdmissionType]
	, DischargeReason.Code [DischargeDisposition]
	, '' AS [EmergencyDepartmentDisposition]
	, [ICDCodesProvisional1].[ICDCode] AS [AdmissionDiagnosis]
	, [ICDCodesFinal1].[ICDCode] AS [PrincipalDiagnosis]
	, [ICDCodesPrimary1].[ICDCode] AS [AdditionalDiagnosis]
	, '' AS [ConditionOnsetFlag]
	, '' AS [PrincipalProcedure_ACHI]
	, '' AS [AdditionalProcedures_ACHI]
	, [Drugs].SFDA AS [AR_DRG]
	, '' AS [AdmittedCase]
	, CASE LEFT([PatientBillservices].[OP_IPNumber], 2) WHEN 'IP' THEN   [PatientInsuranceLimitdetail].ApprovalCode else '' End AS [AuthorizationNumber]
	, '' AS [DaysSupply] 
	, LEmergencyUnit.ArrivalTypeID AS [EmergencyArrivalCode]
	, LEmergencyUnit.[Date] AS [EmergencyServiceStart]
	, CONVERT(VARCHAR(8), DATEADD(SECOND, DATEDIFF(SECOND,LEmergencyUnit.[Date], LEmergencyUnit.[SeenDateTime]),0), 108) AS [EmergencyWaitingTime]
	, '' AS [ServiceEventType]
	, '' AS [CareType]
	, '' AS [ActivityObjectCode_LOINC]
	, '' AS [ActivityObjectCodeValue_LOINC]
	,Billing.EclaimEdit.id as EditID,0 as Selected,
	[PatientInsuranceLimitdetail].Id as PatientInsuranceLimitdetail_ID,
	[PatientInsuranceLimitdetail].DetStatus ,
	[PatientBillservices].SponserApproveStatus
FROM
	[Registration].[Patients]

	
