	LEFT OUTER JOIN [OutPatient].SpecialityGroupDetails ON [Doctors].[SpecialtyId] = SpecialityGroupDetails.[Id]
	LEFT OUTER JOIN [Inpatient].[MedicalObservation] as MOb1 ON [PatientBillservices].[OP_IPNumber] = MOb1.[IP_OP] and  MOb1.DoctorID =[PatientBillservices].DoctorID
    LEFT OUTER JOIN [Inpatient].[MedicalObservation] as MOb2 ON [PatientBillservices].[OP_IPNumber] = MOb2.[IP_OP] and  MOb2.DoctorID =[PatientBillservices].DoctorID


	Left Outer Join [InPatient].[EyesightMeasurement] on MOb1.Id=[InPatient].[EyesightMeasurement].MedicalObservationID
	Left Outer Join [InPatient].[MedicalObservationDental] on MOb2.Id=[InPatient].[MedicalObservationDental].MedicalObservationID
	and [MedicalObservationDental].ServiceID=[PatientBillservices].ItemID
	OUTER APPLY (SELECT TOP 1 * FROM [Inpatient].[MedicalObservationICDCodes] WHERE [MedicalObservationID] = MOb1.[Id] AND [Type] = 1 ORDER BY [Id] DESC) AS [MedicalObservationICDCodesProvisional1]
	LEFT OUTER JOIN [Nursing].[ICDCodes] AS [ICDCodesProvisional1] ON [MedicalObservationICDCodesProvisional1].[ICDCodeID] = [ICDCodesProvisional1].[Id]
	
	OUTER APPLY (SELECT TOP 1 * FROM [Inpatient].[MedicalObservationICDCodes] WHERE [MedicalObservationID] = MOb2.[Id] AND [Type] = 1 ORDER BY [Id] DESC) AS [MedicalObservationICDCodesProvisional2]
	LEFT OUTER JOIN [Nursing].[ICDCodes] AS [ICDCodesProvisional2] ON [MedicalObservationICDCodesProvisional2].[ICDCodeID] = [ICDCodesProvisional2].[Id]



	
	OUTER APPLY (SELECT TOP 1 * FROM [Inpatient].[MedicalObservationICDCodes] WHERE [MedicalObservationID] = MOb1.[Id] AND [Type] = 2 ORDER BY [Id] DESC) AS [MedicalObservationICDCodesPrimary1]
	LEFT OUTER JOIN [Nursing].[ICDCodes] AS [ICDCodesPrimary1] ON [MedicalObservationICDCodesPrimary1].[ICDCodeID] = [ICDCodesPrimary1].[Id]
