	LEFT OUTER JOIN [OutPatient].[PrepareVisitSlip] ON [PatientBillservices].[OP_IPNumber] = [PrepareVisitSlip].[OPnumber]
	LEFT OUTER JOIN [Registration].[DoctorsDailyScheduleDetails] ON [PrepareVisitSlip].[ScheduleAppointmentID] = [DoctorsDailyScheduleDetails].[Id]
	LEFT OUTER JOIN [Registration].[DoctorsDailySchedule] ON [DoctorsDailyScheduleDetails].[DoctorsDailyScheduleID] = [DoctorsDailySchedule].[Id]

	LEFT OUTER JOIN [InPatient].[AdmitPatients] ON [PatientBillservices].[OP_IPNumber] = [AdmitPatients].[IPNumber]

	Left Outer Join [Emergency].[EmergencyDetails] on [PatientBillservices].[OP_IPNumber] =[EmergencyDetails].[Code]

	OUTER APPLY (SELECT TOP 1 * FROM [Emergency].[EmergencyUnit] WHERE [EmergencyUnit].[PatientID] = Patients.[Id]  ORDER BY [EmergencyUnit].[ID] DESC) AS LEmergencyUnit
	
