CREATE proc [Billing].[GetInsuranceCompaniesPayMent]
(
@InsuranceCompaniesIDFrom int,
@InsuranceCompaniesTo int,
@DueDateFrom int,
@DueDateTo int,
@Title nvarchar(400)
)
as
SELECT        TOP (200) Receivable.InsuranceClaimsMaster.Id, Receivable.InsuranceClaimsMaster.Ins_Id, Receivable.InsuranceClaimsMaster.ClaimValue, Receivable.InsuranceClaimsMaster.createDate, 
                         Receivable.InsuranceClaimsMaster.FromDate, Receivable.InsuranceClaimsMaster.ToDate, Receivable.InsuranceClaimsMaster.EntryCodes, Receivable.InsuranceClaimsMaster.CompanyID, 
                         Billing.InsuranceCompanies.NameEnglish, Billing.InsuranceCompanies.NameArabic, Billing.InsuranceCompanies.Code,
						sum(ISNULL(Receivable.InsuranceClaims.LpaidValue,0)) as paied
FROM            Receivable.InsuranceClaimsMaster INNER JOIN
                         Billing.InsuranceCompanies ON Receivable.InsuranceClaimsMaster.Ins_Id = Billing.InsuranceCompanies.ID
						 left join Receivable.InsuranceClaims on Receivable.InsuranceClaims.ClaimID=
						 Receivable.InsuranceClaimsMaster.Id

						 where  Receivable.InsuranceClaimsMaster.Ins_Id between @InsuranceCompaniesIDFrom and @InsuranceCompaniesTo
						 and 
						cast( CONVERT(char(8), Receivable.InsuranceClaimsMaster.FromDate,112) as bigint)
						between @DueDateFrom and @DueDateTo

							 and 
