create proc  [Billing].[GetSectionsrevenue] --20200101,20210101,'محمد'

@From int,@To int ,@Title nvarchar(4000)
as

select @Title,sum(Amount) Amount,NameAr,Name
from(
SELECT DISTINCT TOP (100) PERCENT Billing.PatientBillservices.Id, Billing.PatientBillservices.Amount, Billing.PatientBillservices.CreatedDate, ApplicationSetup.CostCenter.NameAr, ApplicationSetup.CostCenter.Name
FROM            ApplicationSetup.CostCenter INNER JOIN
                         ApplicationSetup.Service ON ApplicationSetup.CostCenter.Id = ApplicationSetup.Service.CostCenterID INNER JOIN
