/****** Object:  StoredProcedure [Billing].[Insurance_Claims]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Billing].[Insurance_Claims] -- '2021-01-01','2024-08-31', 5079,0
                    (@FDate nvarchar(20)=null,
					@TDate nvarchar(20)=null,
					@InsuranceID int=null ,
					@StatusID int=null)
	
AS
BEGIN


if(@StatusID =1)
begin
Select ROW_NUMBER( )OVER (
      PARTITION BY Inc_Code
	  order by  V_Insurance_Claims.PatientID
   )  as Id,
	   NameEnglish,
       NameArabic,
	   PatientCode,
	   V_Insurance_Claims.PatientID,
	   V_Insurance_Claims.TranslatedFallName as PATname,
	   --MiddleName1,
	   --MiddleName2,
	   --LastName,
	   CompanyClassCode,
	   ClassNO,
	   Ins_Company_PolicyCode,
	   PolicyName,
	   PolicyNo,
	   Inc_Code,
	   PatientName,
	   LEFT(OP_IPNumber, 2) as PatientType,
	   OP_IPNumber,
	  
	   IsEndVisit,
	  Sum( SponserPaidAmount)  as SponserPaidAmount,
	  SUM( PateintPaidAmount) + SUM(PatVat)as PateintPaidAmount,
     
	 InPatient.AdmitPatients.ExpectedDateOfDischarge,
	 DoctorsDailySchedule.ScheduleDate,
	 Left(OP_IPNumber,2) as PatientType,
	 Case Left(OP_IPNumber,2) when'OP' then DoctorsDailySchedule.ScheduleDate else AdmitPatients.AdmissionDate End AS VisitDate
	 

FROM [Billing].[V_Insurance_Claims]
Left outer join InPatient.AdmitPatients  on [Billing].[V_Insurance_Claims].OP_IPNumber = InPatient.AdmitPatients.IPNumber
Left outer join OutPatient.PrepareVisitSlip  on [Billing].[V_Insurance_Claims].OP_IPNumber = OutPatient.PrepareVisitSlip.OPnumber
