Left Outer join Registration.DoctorsDailySchedule on Registration.DoctorsDailySchedule.Id=Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID

where  --[V_Insurance_Claims].IsEndVisit=1 and 
[V_Insurance_Claims].InsuranceID=@InsuranceID  
and [V_Insurance_Claims].Paid=0
and [V_Insurance_Claims].ISCash=0 
and [V_Insurance_Claims].SponserId is not Null and [V_Insurance_Claims].SponserId!=0

and ((@FDate is null or InvoiceDate>= Cast(@FDate as date)) and (@TDate is null or InvoiceDate<=DATEADD(day,1,Cast(@TDate as date))))
group by  V_Insurance_Claims.PatientID,NameEnglish, OP_IPNumber,
       NameArabic,
	   PatientCode,
	   PatientType,
	  
	   TranslatedFallName,
	   CompanyClassCode,
	   ClassNO,
	   Ins_Company_PolicyCode,
	   PolicyName,
	   PolicyNo,
	   Inc_Code,
	   PatientName,
	  
	   IsEndVisit,	 
	   InPatient.AdmitPatients.ExpectedDateOfDischarge,
	   DoctorsDailySchedule.ScheduleDate ,
	   DoctorsDailySchedule.ScheduleDate,AdmissionDate
End

END



