/****** Object:  StoredProcedure [Billing].[InsuranceContractPriceListReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Billing].[InsuranceContractPriceListReport]
(
@Date datetime, @Ins_CompanyID int
)
as
SELECT        plh.Name_En AS PriceListHeaderNameEn, plh.Name_Ar AS PriceListHeaderNameAr, plh.Code AS PriceListHeaderCode, plh.Date AS PriceListHeaderDate, pls.Price, s.NameAr AS ServiceNameAr, s.NameEn AS ServiceNameEn, 
                         cc.Name AS CostCenterName, cc.NameAr AS CostCenterNameAr, s.Code AS ServiceCode, icc.Issue_Date, icc.Valid_To, ic.NameArabic AS InsuranceCompanyNameArabic, ic.NameEnglish AS InsuranceCompanyNameEnglish, 
                         pls.Price - CASE WHEN isnull(iccd.Discount_Type, 1) = 1 THEN isnull(iccd.Discount, 0) ELSE (pls.Price / 100) * isnull(iccd.Discount, 0) END AS PriceAfterDiscount,
						 pld.CostcenterID,
						 iccd.Discount,case when  iccd.Discount_Type=1 then N'Fixed' 
						 when  iccd.Discount_Type is NULL  then N''
						 else N'Prcentage' end  as Discount_Type,
						 case when isnull(pls.Approve,0) =1 then N'Yes' else N'No' end as Approved
