CREATE proc [Billing].[Invoice_Insurance] --'2020-01-01','2024-08-31',1,1
 @DateFrom Datetime null,
 @DateTo Datetime null,
 --@PatientID int null,
@SponsoerID int Null,
@catID int null

as
begin
if(@catID=0)
begin
set @catID=null
end
if(@SponsoerID=0)
begin
set @SponsoerID=null
end
select 
distinct vp.RequestCode as RequestNumber,
P.ReceiptNumber,
P.PatientName,
(select top 1 CategoryName from Billing.CustomerCategory where Id=RP.SponserCategoryId) as CategoryName,
PS.ItemCode,
(CASe when PS.ItemCode Like 'S%' then (Select top 1 RecordName from ApplicationSetup.Service where Code=PS.ItemCode)
	         when PS.ItemCode Like 'WP%' then 'Pharmacy' else '' end) as SerName ,  
PS.Amount,
P.[SponsorAmount],
P.[PatientAmount],
P.ReceiptDate
from  Billing.PatientBill P 
