/****** Object:  StoredProcedure [Billing].[NoofservicesandpreapprvePriceListReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE  proc [Billing].[NoofservicesandpreapprvePriceListReport]
 @ID int 


as
begin
select
ph.Code as HeaderCode,ph.Name_Ar as HeaderNameAr,ph.Name_En as HeaderNameEn,
count (Ps.ServiceId ) as Noofservices,
(
select count(Ps.Approve) as NOOfPreApproval
from [Billing].PriceListHeader Ph
inner join [Billing].PriceListDepartment Pd
on ph.PriceList_Header_Id=pd.PriceList_Header_Id
inner join [Billing].PriceListServices Ps
on pd.PriceListDepartment_ID=ps.PriceListDepartment_ID
inner join [ApplicationSetup].CostCenter C 
on pd.CostcenterID=c.Id
inner join [ApplicationSetup].Service S
on ps.ServiceId=s.Id
where Ps.Approve = 1
and ph.PriceList_Header_Id =  @ID
)as NOOfPreApproval

from [Billing].PriceListHeader Ph
inner join [Billing].PriceListDepartment Pd
on ph.PriceList_Header_Id=pd.PriceList_Header_Id
inner join [Billing].PriceListServices Ps
on pd.PriceListDepartment_ID=ps.PriceListDepartment_ID
inner join [ApplicationSetup].CostCenter C
on pd.CostcenterID=c.Id
inner join [ApplicationSetup].Service S
on ps.ServiceId=s.Id
where 
 ph.PriceList_Header_Id = @ID
 group by  ph.Code ,ph.Name_Ar  ,ph.Name_En  
end

GO
/****** Object:  StoredProcedure [Billing].[OverallBudgetreport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Billing].[OverallBudgetreport]
	(@year int)
	as
	BEGIN 
	declare @acc nvarchar= (select AccountNo from gl.accounts where id=(select MainRevenueAccount from GL.GLSetting))
	declare @acc2 nvarchar= (select AccountNo from gl.accounts where id=(select MainExpenseAccount from GL.GLSetting))

select * from(
select 'm'+convert (nvarchar,month (JournalDetails.CreatedDate))  mmonth, 
	sum(GL.JournalDetails.Debit-GL.JournalDetails.Credit) as Prbalance ,'profit' tit
from gl.accounts 	
left join 	
	 GL.JournalDetails on gl.accounts.id=JournalDetails.AccountId
	where 
	--AccountNo like CONCAT('2','%') and
	AccountNo like CONCAT(@acc,'%') and
