CREATE PROC [Billing].[PatientBillservicesCanceledRPT] --20240907,20240910,0,999999
(

@Date int,
@ToDate int,
@BoxIDFrom int,
@BoxIDTo int
)
						       
						
AS

SELECT distinct Billing.PatientBillservicesCanceled.ID,
		Billing.PatientBillservicesCanceled.CreatedBy, 
		Billing.PatientBillservicesCanceled.CreatedDate, 
		Billing.PatientBillservicesCanceled.PrepareVisitSlipID, 
        Billing.PatientBillservicesCanceled.InvestigationRequestDetailsID, 
		Billing.PatientBillservicesCanceled.UserName, 
		Billing.PatientBillservices.PatVat, 
		Users.EnglishName,
		Billing.PatientBillservicesCanceled.CashBoxID,
        Registration.Patients.TranslatedFallName AS Pname, 
		[ApplicationSetup].[Service].RecordName, 
        OutPatient.InvestigationRequestHeader.OP_IPNumber, 
