		Billing.PatientBillservicesCanceled.PrepareVisitSlipID, 
        Billing.PatientBillservicesCanceled.InvestigationRequestDetailsID, 
		Billing.PatientBillservicesCanceled.UserName, 
		Billing.PatientBillservices.PatVat, 
		Users.ArabicName,
		Billing.PatientBillservicesCanceled.CashBoxID,
        Registration.Patients.FirstName + ' ' +Registration.Patients.MiddleName1+ ' '+ Registration.Patients.MiddleName2 + ' ' + Registration.Patients.LastName AS Pname, 
		[ApplicationSetup].[Service].RecordName, 
        OutPatient.InvestigationRequestHeader.OP_IPNumber, 
		Billing.CashierBox.NameAr, 
		Registration.Doctors.NameAr as DoctorName , 
		OutPatient.InvestigationRequestHeader.TotalAmount,
		OutPatient.InvestigationRequestDetails.Amount,
		PatientBillservices.PatVat + OutPatient.InvestigationRequestDetails.Amount as ServiceWithAmpount
FROM    OutPatient.InvestigationRequestDetails 
			INNER JOIN Billing.PatientBillservicesCanceled ON OutPatient.InvestigationRequestDetails.Id = Billing.PatientBillservicesCanceled.InvestigationRequestDetailsID 
			INNER JOIN OutPatient.InvestigationRequestHeader ON OutPatient.InvestigationRequestDetails.InvestigationRequestId = OutPatient.InvestigationRequestHeader.Id 
			left JOIN Registration.Patients ON OutPatient.InvestigationRequestHeader.PatientID = Registration.Patients.Id
			left join Billing.PatientBill on PatientBill.PatientID = Registration.Patients.Id
			inner join Billing.PatientBillservices on PatientBillservices.PatientBillID = Billing.PatientBill.Id
			left join JCIT_MembershipDB.dbo.AspNetUsers Users ON Billing.PatientBillservicesCanceled.UserName = Users.UserName
			left  JOIN ApplicationSetup.Service ON OutPatient.InvestigationRequestDetails.ServiceId = ApplicationSetup.Service.Id 
			INNER JOIN Billing.CashierBox ON Billing.PatientBillservicesCanceled.CashBoxID = Billing.CashierBox.ID  
			JOIN Registration.Doctors ON OutPatient.InvestigationRequestHeader.DoctorID = Registration.Doctors.Id

			
where PatientBillservices.PatVat is not null and cast(convert(char(8),Billing.PatientBillservicesCanceled.[CreatedDate],112) as bigint) between @Date and @ToDate
