/****** Object:  StoredProcedure [Billing].[PatientRevenues_Ar]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [Billing].[PatientRevenues_Ar]
(
    @DateFrom NVARCHAR(20),
    @DateTo   NVARCHAR(20),
    @DoctorID INT
)
AS
BEGIN
    SELECT 
        PB.PatientName     AS [اسم المريض],
        Doc.NameAr          AS [اسم الطبيب],
        PBS.Cash            AS [نقدي],
        PBS.Visa            AS [فيزا],
        PBS.PateintPaidAmount AS [المبلغ المدفوع],
        PB.ReceiptDate      AS [تاريخ الإيصال],
        PB.ReceiptNumber    AS [رقم الإيصال],
        @DateFrom           AS [من تاريخ],
        @DateTo             AS [إلى تاريخ]
    FROM Billing.PatientBill AS PB
    INNER JOIN Billing.PatientBillservices AS PBS 
        ON PB.ID = PBS.PatientBillID
    LEFT OUTER JOIN Registration.Doctors AS Doc 
        ON PB.DoctorID = Doc.Id
    WHERE PB.ReceiptDate >= CONVERT(DATE, @DateFrom)
      AND PB.ReceiptDate <= CONVERT(DATE, @DateTo)
      AND (PB.DoctorID = @DoctorID OR @DoctorID IS NULL)
END

GO
/****** Object:  StoredProcedure [Billing].[PatientServicesPayment]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Billing].[PatientServicesPayment]
(
@PatientID int,
@Paid bit,
@FromDate datetime,
@ToDate datetime
)
as
SELECT    
    Billing.PatientBill.PatientID
	,Registration.Patients.Code as MRN,
	 CASE WHEN Billing.PatientBillservices.Paid = 1 THEN N'مدفوع' ELSE N'غير مدفوع' END AS "خدمة الدفع",
	  CASE WHEN Billing.PatientBillservices.Paid = 1 THEN N'Paid' ELSE N'UnPaid' END AS PaidServiceEn,
	format(Billing.PatientBillservices.CreatedDate, 'dd/MM/yyyy HH:mm:ss') AS ReqDate, 
ISNULL(Registration.Patients.FirstName, '') + ' ' +
 ISNULL(Registration.Patients.MiddleName1, '') + ' ' +
  ISNULL(Registration.Patients.MiddleName2, '') + ' ' +
  ISNULL(Registration.Patients.LastName, '') AS "اسم المريض", 
