/****** Object:  StoredProcedure [Billing].[RepCashierAccountingAmount]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procEDURE [Billing].[RepCashierAccountingAmount] 
@BoxId int  null,
@UserId nvarchar(256) null,
@DateFrom Datetime null,
@DateTo Datetime null

as
begin

--declare @UserId nvarchar(256)='0'
if @UserId='0' 
set @UserId = null
-- open balance
select subtable.ID
,subtable.BoxAr
,subtable.BoxEn
,subtable.UserName
,subtable.PatientName

 
,Sum(isnull(PatientAmount,0)) PatientAmount from (
select  distinct CB.ID
,NameAr as BoxAr
,NameEn as BoxEn
,CBB.UserName
, ' ' as PatientName
 
,Sum(isnull(COB.Amount,0)) PatientAmount

 
from Billing.CashierBoxUsers CBU
inner join Billing.CashierBox CB on CB.ID = CBU.BoxID
left join Billing.CashierOpenBalance as COB on CB.id=COB.BoxID
left join JCIT_MembershipDB.dbo.AspNetUsers CBB on COB.CreatedBy = CBB.id 

where CB.ID =@BoxId
  
and(CBU.UserID = @UserId or @UserId is null) and COB.CreatedDate between @DateFrom and @DateTo
group by CB.ID
,NameAr  
,NameEn  
,CBB.UserName
 
union 

select  distinct CB.ID
,NameAr as BoxAr
,NameEn as BoxEn
,CBB.UserName
, isnull (P.FirstName,'') + ' '+ isnull (P.MiddleName1,'') + ' '+isnull (P.MiddleName2,'') + ' '+isnull (P.LastName,'') as PatientName

,Sum(isnull(PBS.PateintPaidAmount+PBS.PatVat,0)) PatientAmount

from Billing.CashierBox CB
