/****** Object:  StoredProcedure [Billing].[ReportHeaderRecepit]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Billing].[ReportHeaderRecepit]
@FromDate datetime null,
@Todate datetime null,
@PatientID int null 
as
select 
a.Id,
ReceiptNumber,
ReceiptDate,
PatientID,
p.FirstName+''+p.MiddleName1+''+p.MiddleName2+''+p.LastName as patientName,
ar.AdvanceReceiptId,
i.Name,
ar.Amount as NetAmount
from [Billing].[AdvanceReceipts] a left join Registration.Patients p on a.PatientID=p.Id
left join
[Billing].[AdvanceReceiptsItems] ar
on a.Id = ar.AdvanceReceiptId
 left join ApplicationSetup.Item i on ar.ItemID=i.ID
where
(a.ReceiptDate >= convert(datetime,@FromDate,103) or @FromDate is null)
and (a.ReceiptDate < convert(datetime,@Todate,103) or @Todate is null)
and (a.PatientID = @PatientID or @PatientID is null)
order by ReceiptNumber





