	, [Service].[Id] AS [ServiceId]
	, [Service].[NameAr] AS [ServiceNameArabic]
	, [Service].[NameEn] AS [ServiceNameEnglish]
	,
		CASE WHEN [ContractPriceListServices].[PriceListService_Id] IS NOT NULL THEN
		ISNULL(	[ContractPriceListServices].[PriceAfterDiscount],0)
		ELSE
			CASE WHEN [DefaultPriceListServices].[PriceListService_Id] IS NOT NULL THEN
			ISNULL(	[DefaultPriceListServices].[PriceAfterDiscount],0)
			ELSE
			ISNULL(	[Service].[StanderCharge],0)
			END
		END
		AS [Price]
	,
		CASE WHEN [ContractPriceListServices].[PriceListService_Id] IS NOT NULL THEN
			[INS_Company_Contract_Discount].[Discount_Type]
		ELSE
			0
		END
		AS [Discount_Type]
	,
		CASE WHEN [ContractPriceListServices].[PriceListService_Id] IS NOT NULL THEN
		ISNULL(	[INS_Company_Contract_Discount].[Discount],0)
		ELSE
			0
		END
		AS [Discount]
	--,
	--	CASE WHEN [ContractPriceListServices].[PriceListService_Id] IS NOT NULL THEN
