	--	ELSE
	--		0
	--	END
	--	AS [Deduction_Max]
FROM
	[Registration].[Patients]

	INNER JOIN [Billing].[V_NonPaidPatientBills] ON [Patients].[Id] = [V_NonPaidPatientBills].[PatientID]
	INNER JOIN [ApplicationSetup].[Service] ON [V_NonPaidPatientBills].[ItemId] = [Service].[Id]
	INNER JOIN [ApplicationSetup].[CostCenterCompanies] ON [Service].[CostCenterCompaniesId] = [CostCenterCompanies].[Id]
	INNER JOIN [ApplicationSetup].[CostCenter] ON [CostCenterCompanies].[CostCenterId] = [CostCenter].[Id]
	
	-- 1st branch
