CREATE procedure [Billing].[RepPharmacyBill]
@Id int null 
as
begin
Select PharmacyBillHeaderID,PatientName,TotalAmount,ItemCode,ItemName,Quantity,Amount,Price,CAST(PharmacyBillHeader.CreatedDate AS DATE) as  CreatedDate From Billing.PharmacyBillHeader 
inner join Billing.PharmacyBillDetail on PharmacyBillHeader.id=PharmacyBillDetail.PharmacyBillHeaderID
where PharmacyBillHeader.id=@Id

end


