CREATE proc [Billing].[RptRejectedInsClaim]
(


@insCompID int null,
@FromDate DateTime null,
@ToDate DateTime null
)
as

select p.TranslatedFallName, isnull(p.FirstName,'') +' ' +
isnull( p.MiddleName1,'')+' ' + ISNULL( p.MiddleName2,'')+' ' +
ISNULL(p.LastName,'') patName, m.InsName ,m.InsNameAr,
CASE  
     WHEN m.MasterStatus=1 
      THEN 'New'
   when m.MasterStatus=2
   then 'Sent To Company'
   when m.MasterStatus=3
   then 'Closed'
  END  as MasterStatus  ,
CASE  
     WHEN d.DetailStatus=1 
      THEN 'New'
   when d.DetailStatus=2
   then 'Refused'
   when d.DetailStatus=3
   then 'Accepted' else 'Removed'
    
END  as DetailStatus , comp.NameArabic CompNameAr,comp.NameEnglish CompNameEn ,
