on AdvanceReceiptsPaymentRefund.ReceiptNumber=AdvanceReceiptsPayment.ReceiptNumber

left join Registration.Patients as Patients
on Patients.Id=AdvanceReceipts.PatientID

left join Billing.InvoiceReceipt as InvoiceReceipt
on  AdvanceReceipts.id= InvoiceReceipt.ReceiptNumber

left join Billing.PatientBill as PatientBill
on PatientBill.Id=InvoiceReceipt.InvoiceNumber


where (AdvanceReceipts.PatientID=@PatientID or @PatientID=0)
and (AdvanceReceipts.CreatedDate >= Convert(Datetime,@FromDate,103) or @FromDate is null)
and (AdvanceReceipts.CreatedDate < Convert(Datetime,@ToDate,103) or @ToDate is null)

group by  AdvanceReceipts.ReceiptNumber,AdvanceReceipts.ReceiptDate,AdvanceReceiptsItems.Amount,
AdvanceReceiptsPayment.Amount,AdvanceReceiptsPayment.CreatedDate,AdvanceReceiptsPaymentRefund.Amount,
AdvanceReceiptsPaymentRefund.ReceiptNumber,PatientBill.IPOPNo,Patients.FirstName,Patients.MiddleName1,
Patients.LastName
END





