CREATE procedure  [Billing].[SP_AuditReportsPatient]
@FromDate datetime=null,
@ToDate datetime=null,
@PatientID int=0,
@LocationID int=0
AS
BEGIN
Select distinct PatientBill.ReceiptNumber as InvoiceNo,PatientBill.ReceiptDate as InvoiceDate,Doctors.Name as DoctorName,
PatientBillservices.RequestNumber as ReqNo, PatientBillservices.RequestDate as ReqDate ,PatientBillservices.ItemName as Service,
(PatientBillservices.Quantity*PatientBillservices.Amount) as Amount,PatientBill.Discount,PatientBill.ReceiptNumber,
'' as EnteredBy, sum(PatientBillservices.Quantity * PatientBillservices.Amount) as TotalAmount
,ISNULL( Patients.[FirstName],'')+' '+ISNULL( Patients.[MiddleName1],'')+' '+ISNULL( Patients.[MiddleName2],'')+' '+ISNULL( Patients.[LastName],'') PatientsNameAr,
ISNULL(
    NULLIF(Patients.TranslatedFallName, ''),
    
    ISNULL(Patients.FirstName,'') + ' ' +
    ISNULL(Patients.MiddleName1,'') + ' ' +
    ISNULL(Patients.MiddleName2,'') + ' ' +
    ISNULL(Patients.LastName,'')
) AS PatientsNameEN

