/****** Object:  StoredProcedure [Billing].[SP_AuditReportsPatientAr]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [Billing].[SP_AuditReportsPatientAr]
    @FromDate   DATETIME = NULL,
    @ToDate     DATETIME = NULL,
    @PatientID  INT = 0,
    @LocationID INT = 0
AS
BEGIN
    SELECT
        PatientBill.ReceiptNumber AS [رقم الفاتورة],
        PatientBill.ReceiptDate   AS [تاريخ الفاتورة],
        Doctors.NameAr            AS [اسم الطبيب],
        PatientBillservices.RequestNumber AS [رقم الطلب],
        PatientBillservices.RequestDate   AS [تاريخ الطلب],
        PatientBillservices.ItemName      AS [الخدمة],
        (PatientBillservices.Quantity * PatientBillservices.Amount) AS [المبلغ],
        PatientBill.Discount      AS [الخصم],
        PatientBill.ReceiptNumber AS [رقم الإيصال],
        N''                       AS [مدخل بواسطة],
        SUM(PatientBillservices.Quantity * PatientBillservices.Amount)               AS [إجمالي المبلغ]
	,	ISNULL( Patients.[FirstName],'')+' '+ISNULL( Patients.[MiddleName1],'')+' '+ISNULL( Patients.[MiddleName2],'')+' '+ISNULL( Patients.[LastName],'') PatientsNameAr,
Patients.TranslatedFallName PatientsNameEN
    FROM Billing.PatientBill AS PatientBill
    LEFT JOIN Billing.PatientBillservices AS PatientBillservices
        ON PatientBill.Id = PatientBillservices.PatientBillID
    LEFT JOIN Registration.Doctors AS Doctors
        ON PatientBillservices.DoctorID = Doctors.Id
    LEFT JOIN Billing.CustomerMaster AS CustomerMaster
        ON CustomerMaster.Id IN (
            SELECT Id
            FROM Billing.CustomerMaster
            WHERE CustomerName = PatientBill.CustomerName
        )
    LEFT JOIN Billing.CustomerCategory AS CustomerCategory
        ON CustomerMaster.Id = CustomerCategory.CustomerMasterID
    LEFT JOIN Billing.CustomerCategoryDrugType AS DrugType
        ON CustomerCategory.Id = DrugType.CustomerCategoryID
    LEFT JOIN Billing.CustomerCategoryDrugs AS DrugsCategory
        ON DrugType.Id = DrugsCategory.CustomerCategoryDrugTypeID
    LEFT JOIN Billing.CustomerCategoryCostCenters AS CostCenters
