/****** Object:  StoredProcedure [Billing].[SP_CashierBatchesReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [Billing].[SP_CashierBatchesReport]
@PosId int null ,
@FromDate DateTime null,
@ToDate DateTime null
as
begin
select [Nursing].[Employee].[FirstName]+''+[Nursing].[Employee].[MiddleName]+' '+[Nursing].[Employee].[LastName]
,[Billing].[PointOfSale].POSName,[Billing].[CashierBatches].[StartDate],[Billing].[CashierBatches].OpeningAmount
,[Billing].[CashierBatches].[EndDate],[Billing].[CashierBatches].ClosingAmount,[Billing].[CashierBatches].PayOut
from [Billing].[CashierBatches]
join [Nursing].[Employee] on [Billing].[CashierBatches].CashierID=[Nursing].[Employee].Id
join [Billing].[PointOfSale] on [Billing].[CashierBatches].POSID=[Billing].[PointOfSale].ID

where ([billing].[CashierBatches].[POSID] = @PosId or @PosId is null )
and ([billing].[CashierBatches].CreatedDate >= convert(datetime,@FromDate,103) or @FromDate is null)
and ([billing].[CashierBatches].CreatedDate >= convert(datetime,@ToDate,103) or @ToDate is null)

end





