/****** Object:  StoredProcedure [Billing].[SP_CountofInvoices]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [Billing].[SP_CountofInvoices]
@InvoicesYear int 
AS
BEGIN

select distinct Count(*) as invoicesCount ,case([Status]) when 1 then Substring(IPOPNO,0,3)+' Invoices-(Open)' when 2 then Substring(IPOPNO,0,3)+' Invoices-(Cancelled)' when 3 then Substring(IPOPNO,0,3)+' Invoices-(Printed)'
when 4 then Substring(IPOPNO,0,3)+' Invoices-(Closed)' when 5 then Substring(IPOPNO,0,3)+' Invoices-(ReOpen)' else Substring(IPOPNO,0,3)+' Invoices-(Return)' end as InvoiceStatus
,DateName(mm,DATEADD(mm,MONTH(ReceiptDate),-1)) as [MonthName],Year(ReceiptDate)as [Year],MONTH(ReceiptDate) 
