挀攀猀䄀爀崀ഀ਀䀀䤀渀瘀漀椀挀攀猀夀攀愀爀 䤀一吀 ഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀ഀ਀匀䔀䰀䔀䌀吀 䐀䤀匀吀䤀一䌀吀 ഀ਀    䌀伀唀一吀⠀⨀⤀ 䄀匀 一✀㤀⼆⼆ ✀䐆䄆䠆✆⨆䨆ㄆ✆Ⰰഀ਀ഀ਀    䌀䄀匀䔀⠀嬀匀琀愀琀甀猀崀⤀ ഀ਀        圀䠀䔀一 ㄀ 吀䠀䔀一 匀唀䈀匀吀刀䤀一䜀⠀䤀倀伀倀一伀Ⰰ　Ⰰ㌀⤀ ⬀ 一✀ 䄀䠆✆⨆䨆ㄆ ⴀ ⠀䔀䄆⨆䠆ⴆ⤆⤆✀ഀ਀        圀䠀䔀一 ㈀ 吀䠀䔀一 匀唀䈀匀吀刀䤀一䜀⠀䤀倀伀倀一伀Ⰰ　Ⰰ㌀⤀ ⬀ 一✀ 䄀䠆✆⨆䨆ㄆ ⴀ ⠀䔀䐆㨆䨆⤆⤆✀ഀ਀
        WHEN 3 THEN SUBSTRING(IPOPNO,0,3) + N' فواتير - (مطبوعة)'
        WHEN 4 THEN SUBSTRING(IPOPNO,0,3) + N' فواتير - (مغلقة)'
        WHEN 5 THEN SUBSTRING(IPOPNO,0,3) + N' فواتير - (إعادة فتح)'
        ELSE SUBSTRING(IPOPNO,0,3) + N' فواتير - (مرتجعة)'
    END AS N'حالة الفاتورة',

    CASE MONTH(ReceiptDate)
        WHEN 1 THEN N'يناير'
        WHEN 2 THEN N'فبراير'
        WHEN 3 THEN N'مارس'
        WHEN 4 THEN N'أبريل'
        WHEN 5 THEN N'مايو'
        WHEN 6 THEN N'يونيو'
        WHEN 7 THEN N'يوليو'
        WHEN 8 THEN N'أغسطس'
        WHEN 9 THEN N'سبتمبر'
        WHEN 10 THEN N'أكتوبر'
        WHEN 11 THEN N'نوفمبر'
        WHEN 12 THEN N'ديسمبر'
    END AS N'الشهر',

    YEAR(ReceiptDate) AS N'السنة',
    MONTH(ReceiptDate) AS N'رقم الشهر'

FROM Billing.PatientBill
WHERE YEAR(ReceiptDate) = @InvoicesYear
GROUP BY MONTH(ReceiptDate), Status, SUBSTRING(IPOPNO,0,3), YEAR(ReceiptDate)

UNION

SELECT 
    COUNT(*) AS N'عدد الفواتير',

    CASE(Status) 
        WHEN 1 THEN SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (مفتوحة)'
        WHEN 2 THEN SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (ملغية)'
        WHEN 3 THEN SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (مطبوعة)'
        WHEN 4 THEN SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (مغلقة)'
        WHEN 5 THEN SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (إعادة فتح)'
        ELSE SUBSTRING(OPIPNO,0,3) + N' فواتير الباقات - (مرتجعة)'
    END AS N'حالة الفاتورة',

    CASE MONTH(RegisterDate)
        WHEN 1 THEN N'يناير'
        WHEN 2 THEN N'فبراير'
        WHEN 3 THEN N'مارس'
        WHEN 4 THEN N'أبريل'
        WHEN 5 THEN N'مايو'
        WHEN 6 THEN N'يونيو'
        WHEN 7 THEN N'يوليو'
        WHEN 8 THEN N'أغسطس'
        WHEN 9 THEN N'سبتمبر'
        WHEN 10 THEN N'أكتوبر'
        WHEN 11 THEN N'نوفمبر'
        WHEN 12 THEN N'ديسمبر'
    END AS N'الشهر',

    YEAR(ReceiptDate) AS N'السنة',
    MONTH(ReceiptDate) AS N'رقم الشهر'

FROM Billing.RegisterPackage 
INNER JOIN Billing.PatientBill
    ON Billing.PatientBill.Id = Billing.RegisterPackage.InvoiceNO
WHERE YEAR(ReceiptDate) = @InvoicesYear
GROUP BY MONTH(RegisterDate), Status, OPIPNO, YEAR(ReceiptDate), MONTH(ReceiptDate)

