Select *, ApplicationSetup.Nationality.Name as Nationality,ApplicationSetup.City.Name as City
,ApplicationSetup.Currency.Name as Currency , Billing.PaymentModes.PaymentModeDescription
from Billing.CustomerMasterDetails

inner join  Billing.CustomerMaster
on Billing.CustomerMaster.Id=Billing.CustomerMasterDetails.CustomerMasterID
 
inner join ApplicationSetup.Nationality
on ApplicationSetup.Nationality.Id=Billing.CustomerMaster.BillingNationalityID

inner join ApplicationSetup.City
on ApplicationSetup.City.Id=Billing.CustomerMaster.BillingCityID

inner join ApplicationSetup.Currency
on ApplicationSetup.Currency.Id=Billing.CustomerMaster.CurrencyID

inner join Billing.PaymentModes
on Billing.PaymentModes.Id=Billing.CustomerMaster.BillCollectorID

where (Billing.CustomerMaster.CreatedDate >= @DateFrom or @DateFrom is null )
and  (Billing.CustomerMaster.CreatedDate < @DateTo or @DateTo is null )
and (Billing.CustomerMaster.IsActive=@Active or @Active=0)

END





