CREATE procEDURE [Billing].[SP_MakePatientBill_Report] --'R','PBR000000000000002337',18156,null,null,18299
@tt nvarchar(50),
@Receipt nvarchar(250),
 @InvoiceId int null,
 @FromDate Datetime null,
 @ToDate Datetime null,
 @PatientID int null

AS
BEGIN
Declare @LNo int
Declare @RNo int
Declare @RDate Datetime
Declare @Ldate Datetime

Set @LNo=0
Set @RNo=0



if(@tt='R')
begin
declare @LabCount int
declare @RadCount int
set @LabCount=(select count(*) from Billing.PatientBill as  PBill
join Billing.PatientBillservices as BillServices on PBill.Id=BillServices.PatientBillID
