  and CashierBoxUsers.BoxID= BillServices.CashierBoxID
Left JOIN ApplicationSetup.[Service] on [Service].Id=BillServices.ItemID
Left join ApplicationSetup.CostCenterCompanies on  CostCenterCompanies.Id= [Service].CostCenterCompaniesId
Left join ApplicationSetup.CostCenter on  CostCenter.Id=CostCenterCompanies.CostCenterId

where BillServices.Paid=1 and (BillServices.BillReceipts=@Receipt) and (BillServices.PatientBillID=@InvoiceId)
and (PBill.PatientID=@PatientID or @PatientID is null) and Service.ServiceType=8
)
set @RNo=  (select count(*)+1 from Billing.PatientBill as  PBill
join Billing.PatientBillservices as BillServices on PBill.Id=BillServices.PatientBillID
Left Join Registration.PatientInsurance PAINS on PBill.PatientID = PAINS.PatientId and BillServices.SponserId =PAINS.SponsorId
Left join Billing.InsuranceCompanies on BillServices.SponserId=InsuranceCompanies.ID
Left Join Billing.ins_Company_Class on PAINS.ins_ClassID =ins_Company_Class.ID

join Registration.Patients on Registration.Patients.id=PBill.PatientID
left join Registration.Nationalities on Registration.Patients.NationalityId= Registration.Nationalities.Id

left join Registration.Doctors as Doctors on BillServices.DoctorID=Doctors.Id
join Billing.CashierBox as CashierBox  on CashierBox.ID = BillServices.CashierBoxID
join JCIT_MembershipDB.dbo.AspNetUsers  as Users on Users.Id = BillServices.CashierId 
join Billing.CashierBoxUsers  as CashierBoxUsers
 on  CashierBoxUsers.userID = BillServices.CashierId
  and CashierBoxUsers.BoxID= BillServices.CashierBoxID
Left JOIN ApplicationSetup.[Service] on [Service].Id=BillServices.ItemID
Left join ApplicationSetup.CostCenterCompanies on  CostCenterCompanies.Id= [Service].CostCenterCompaniesId
Left join ApplicationSetup.CostCenter on  CostCenter.Id=CostCenterCompanies.CostCenterId

where BillServices.Paid=1 and (BillServices.BillReceipts<@Receipt)  and cast(CONVERT(char(8),PBill.ReceiptDate,112) as bigint)=cast(CONVERT(char(8),@Ldate,112) as bigint)
and (PBill.PatientID<>@PatientID ) and Service.ServiceType=8
)
end



