 @PatientID int null

AS
BEGIN
Declare @LNo int
Declare @RNo int
Set @LNo=9000
Set @RNo=9000


if(@tt='R')
begin


 select @LNo Lno,@RNo Rno,
 ( select top 1 [Image] from [ApplicationSetup].[QRImage] where [ApplicationSetup].[QRImage].[PatID]=@PatientID and [ApplicationSetup].[QRImage].ReportName=N'RepInvioce' and   [ApplicationSetup].[QRImage].InvoiceId=@InvoiceId    order by id desc) as QrImage
  , (select top 1 Company.taxfileNo  from [ApplicationSetup].Company ) as hospitalTax
  
  ,Registration.Patients.TranslatedFallName as FULLNAME,PBill.[PatientName]
      ,PBill.[ReceiptNumber] As InvoiceNumber
      ,PBill.[ReceiptDate]
	  ,PBill.[Remarks]
	  ,BillServices.OP_IPNumber
	  ,BillServices.BillReceipts
	  ,InsuranceCompanies.NameEnglish  [SponsorName]
      ,BillServices.[SponserCategory]
	  ,isnull( BillServices.SponserPaidAmount,0) SponserPaidAmount
	  ,BillServices.PateintPaidAmount
	  ,BillServices.PatVat
	  ,ISNULL(BillServices.DiscountOfferValue,0) DiscountOfferValue
	  ,BillServices.Cash
	  ,BillServices.Visa
	  ,BillServices.VisaReceipt
	 ,BillServices.[Discount]
      ,ISNULL(BillServices.discountVal,0) DiscountVal
      ,BillServices.[OP_IPNumber]
      ,PBill.[CustomerName]
      ,[ItemCode]
      ,[ItemName]
      ,[RequestNumber]
      ,isnull([Quantity],1) as [Quantity]
      ,[Amount]
	  ,BillServices.PatVat +IsNULL(BillServices.SpoVat,0) Vat  
      ,[RequestDate]
      ,[AmountBefore]
	  ,Doctors.Name as DocName
	  ,CashierBox.NameEn as CashierBoxName
	  ,Users.EnglishName as CaxhierName
	  ,CostCenter.Name as COName
	    ,Registration.Patients.code as MRN
	  ,Registration.Nationalities.NameEn as NatName
	   ,Registration.Nationalities.NameEn as NatNameEn,
	   case when Registration.Patients.PaymentType =9
	   then 'Insurance' else 'Cash' end as PType,
	   ISNULL(BillServices.ReceiptDescount,0) ReceiptDescount,
	   BillServices.ReceiptNo,BillServices.ApprovedCode,
	   ins_Company_Class.ClassNO,
	   InsuranceCompanies.VAT_No,BillServices.PatVat,
	   isnull(BillServices.SpoVat,0) SpoVat,
