/****** Object:  StoredProcedure [Billing].[SP_OpenInvoice_Report]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [Billing].[SP_OpenInvoice_Report]
 @FromDate Datetime=null,
 @ToDate Datetime=null

AS
Select distinct 
Billing.PatientBill.PatientName, 
Billing.PatientBill.PatientID ,
ISNULL(TotalAmount,0) as InvoiceAmount,
Billing.PatientBill.ReceiptNumber as InvoiceNo, 
Billing.PatientBill.ReceiptDate as InvoiceDate,
Substring(IPOPNo,0,3) as IPOP ,
CustomerName, Status  , 
RequestDate , 
ISNULL(Amount,0) as RecieptAmount,
AdvanceReceipts.ReceiptNumber as ReceiptNumber , 
AdvanceReceipts.ReceiptDate as ReceiptDate

from Billing.PatientBill 

inner join Billing.PatientBillservices as BillServices 
on PatientBill.Id=BillServices.PatientBillID 

left join Billing.InvoiceReceipt
on PatientBill.Id=InvoiceReceipt.InvoiceNumber

left join Billing.AdvanceReceipts
on AdvanceReceipts.id=InvoiceReceipt.ReceiptNumber


where (PatientBill.ReceiptDate >= Convert(Datetime,@FromDate,103) or @FromDate is null)
and (PatientBill.ReceiptDate < Convert(Datetime,@ToDate,103) or @ToDate is null)
and Status=1








GO
