CREATE   PROCEDURE [Billing].[SP_OpenInvoice_ReportAr]
    @FromDate DATETIME = NULL,
    @ToDate DATETIME = NULL
AS
SELECT DISTINCT
    LTRIM(RTRIM(
        ISNULL(p.FirstName, '') + ' ' + 
        ISNULL(p.MiddleName1, '') + ' ' + 
        ISNULL(p.MiddleName2, '') + ' ' + 
        ISNULL(p.LastName, '')
    )) AS [اسم المريض],
