/****** Object:  StoredProcedure [Billing].[SP_PatientRequests_Ar]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [Billing].[SP_PatientRequests_Ar]
    @FromDate     DATETIME     = NULL,
    @ToDate       DATETIME     = NULL,
    @SubstoreID   INT          = 0,
    @EnteredByID  NVARCHAR(50) = NULL,
    @PatientID    INT          = 0,
    @IPatientType BIT          = 0,
    @OPatientType BIT          = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT DISTINCT
        LTRIM(RTRIM(
            ISNULL(Patients.FirstName, '') + ' ' +
            ISNULL(Patients.MiddleName1, '') + ' ' +
            ISNULL(Patients.LastName, '')
        ))                                        AS [اسم المريض],
        Patients.DateOfBirth                      AS [تاريخ الميلاد],
        CASE Patients.GenderId
            WHEN 1 THEN N'ذكر'
            WHEN 2 THEN N'أنثى'
            ELSE N'غير محدد'
        END                                       AS [النوع],
        PatientBill.PatientID                     AS [رقم المريض],
        PatientBill.IPOPNo                        AS [رقم الدخول],
        PatientBill.CustomerName                  AS [اسم العميل],
        BillServices.RequestNumber                AS [رقم الطلب],
        BillServices.RequestDate                  AS [تاريخ الطلب],
        BillServices.SponsorName                  AS [جهة الدفع],
        BillServices.SponserCategory              AS [فئة جهة الدفع],
ਊ        䐀漀挀琀漀爀猀⸀一愀洀攀䄀爀                            䄀匀 嬀✀㌆䔆 ✀䐆㜆⠆䨆⠆崆Ⰰഀ਀        倀愀琀椀攀渀琀䈀椀氀氀⸀刀攀挀攀椀瀀琀一甀洀戀攀爀                 䄀匀 嬀㄀䈆䔆 ✀䐆䄆✆⨆䠆ㄆ⤆崆Ⰰഀ਀        倀愀琀椀攀渀琀䈀椀氀氀⸀刀攀挀攀椀瀀琀䐀愀琀攀                   䄀匀 嬀⨀✆ㄆ䨆⸆ ✀䐆䄆✆⨆䠆ㄆ⤆崆Ⰰഀ਀        倀愀礀洀攀渀琀䐀攀琀愀椀氀猀⸀䄀洀漀甀渀琀                     䄀匀 嬀㔀✆䄆䨆 ✀䐆䔆⠆䐆㨆崆Ⰰഀ਀        一✀✀                                       䄀匀 嬀⨀䔆 ✀䐆┆⼆⸆✆䐆 ⠀䠆✆㌆㜆⤆崆Ⰰഀ਀        䈀椀氀氀匀攀爀瘀椀挀攀猀⸀䄀洀漀甀渀琀                       䄀匀 嬀㌀㤆ㄆ ✀䐆䠆ⴆ⼆⤆崆Ⰰഀ਀        䈀椀氀氀匀攀爀瘀椀挀攀猀⸀䤀琀攀洀䌀漀搀攀                     䄀匀 嬀䌀䠆⼆ ✀䐆⸆⼆䔆⤆崆Ⰰഀ਀        䈀椀氀氀匀攀爀瘀椀挀攀猀⸀䤀琀攀洀一愀洀攀                     䄀匀 嬀✀㌆䔆 ✀䐆⸆⼆䔆⤆崆Ⰰഀ਀        䤀匀一唀䰀䰀⠀䈀椀氀氀匀攀爀瘀椀挀攀猀⸀儀甀愀渀琀椀琀礀Ⰰ ㄀⤀          䄀匀 嬀✀䐆䌆䔆䨆⤆崆Ⰰഀ਀        倀愀琀椀攀渀琀猀⸀倀愀猀琀䠀椀猀琀漀爀礀                      䄀匀 嬀✀䐆⨆✆ㄆ䨆⸆ ✀䐆䔆ㄆ㘆䨆崆Ⰰഀ਀        䌀䄀匀䔀ഀ਀            圀䠀䔀一 倀愀琀椀攀渀琀䈀椀氀氀⸀刀攀挀攀椀瀀琀一甀洀戀攀爀 䤀匀 一唀䰀䰀 吀䠀䔀一 一✀㨀䨆ㄆ 䔀⼆䄆䠆㤆✆ഀ਀            䔀䰀匀䔀 一✀䔀⼆䄆䠆㤆✆ഀ਀        䔀一䐀                                       䄀匀 嬀ⴀ✆䐆⤆ ✀䐆⼆䄆㤆崆Ⰰഀ਀        圀愀爀搀⸀圀愀爀搀一愀洀攀                             䄀匀 嬀✀㌆䔆 ✀䐆䈆㌆䔆崆ഀ਀ഀ਀    䘀刀伀䴀 䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀 䄀匀 倀愀琀椀攀渀琀䈀椀氀氀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀倀愀琀椀攀渀琀䈀椀氀氀猀攀爀瘀椀挀攀猀 䄀匀 䈀椀氀氀匀攀爀瘀椀挀攀猀ഀ਀        伀一 倀愀琀椀攀渀琀䈀椀氀氀⸀䤀搀 㴀 䈀椀氀氀匀攀爀瘀椀挀攀猀⸀倀愀琀椀攀渀琀䈀椀氀氀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀 䄀匀 倀愀琀椀攀渀琀猀ഀ਀        伀一 倀愀琀椀攀渀琀猀⸀䤀搀 㴀 倀愀琀椀攀渀琀䈀椀氀氀⸀倀愀琀椀攀渀琀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 伀甀琀倀愀琀椀攀渀琀⸀䄀搀洀椀琀琀椀渀最倀愀琀椀攀渀琀 䄀匀 䄀搀洀椀琀琀椀渀最倀愀琀椀攀渀琀ഀ਀        伀一 倀愀琀椀攀渀琀猀⸀䤀搀 㴀 䄀搀洀椀琀琀椀渀最倀愀琀椀攀渀琀⸀倀愀琀椀攀渀琀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 一甀爀猀椀渀最⸀圀愀爀搀 䄀匀 圀愀爀搀ഀ਀        伀一 圀愀爀搀⸀䤀搀 㴀 䄀搀洀椀琀琀椀渀最倀愀琀椀攀渀琀⸀圀愀爀搀䤀搀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀倀愀礀洀攀渀琀䐀攀琀愀椀氀猀 䄀匀 倀愀礀洀攀渀琀䐀攀琀愀椀氀猀ഀ਀        伀一 倀愀礀洀攀渀琀䐀攀琀愀椀氀猀⸀刀攀挀攀椀瀀琀一甀洀戀攀爀 㴀 倀愀琀椀攀渀琀䈀椀氀氀⸀刀攀挀攀椀瀀琀一甀洀戀攀爀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀䐀漀挀琀漀爀猀 䄀匀 䐀漀挀琀漀爀猀ഀ਀        伀一 䈀椀氀氀匀攀爀瘀椀挀攀猀⸀䐀漀挀琀漀爀䤀䐀 㴀 䐀漀挀琀漀爀猀⸀䤀搀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀甀猀琀漀洀攀爀䴀愀猀琀攀爀 䄀匀 䌀甀猀琀漀洀攀爀䴀愀猀琀攀爀ഀ਀        伀一 䌀甀猀琀漀洀攀爀䴀愀猀琀攀爀⸀䌀甀猀琀漀洀攀爀一愀洀攀 㴀 倀愀琀椀攀渀琀䈀椀氀氀⸀䌀甀猀琀漀洀攀爀一愀洀攀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀 䄀匀 䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀ഀ਀        伀一 䌀甀猀琀漀洀攀爀䴀愀猀琀攀爀⸀䤀搀 㴀 䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀⸀䌀甀猀琀漀洀攀爀䴀愀猀琀攀爀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䐀爀甀最吀礀瀀攀 䄀匀 䐀爀甀最吀礀瀀攀ഀ਀        伀一 䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀⸀䤀搀 㴀 䐀爀甀最吀礀瀀攀⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䐀爀甀最猀 䄀匀 䐀爀甀最猀䌀愀琀攀最漀爀礀ഀ਀        伀一 䐀爀甀最吀礀瀀攀⸀䤀搀 㴀 䐀爀甀最猀䌀愀琀攀最漀爀礀⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䐀爀甀最吀礀瀀攀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䈀椀氀氀椀渀最⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䌀漀猀琀䌀攀渀琀攀爀猀 䄀匀 䌀漀猀琀䌀攀渀琀攀爀猀ഀ਀        伀一 䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀⸀䤀搀 㴀 䌀漀猀琀䌀攀渀琀攀爀猀⸀䌀甀猀琀漀洀攀爀䌀愀琀攀最漀爀礀䤀䐀ഀ਀
    LEFT JOIN ApplicationSetup.CostCenterCompanies AS CostCenterCompanies
        ON CostCenterCompanies.Id = CostCenters.CostCenterCompaniesID
    LEFT JOIN Pharmacy.Substores AS Substores
        ON CostCenterCompanies.Id = Substores.CostCenterCompaniesID

    WHERE
        (@FromDate IS NULL OR PatientBill.ReceiptDate >= @FromDate)
        AND (@ToDate IS NULL OR PatientBill.ReceiptDate < DATEADD(DAY, 1, @ToDate))
        AND (@PatientID IS NULL OR @PatientID = 0 OR PatientBill.PatientID = @PatientID)
        AND (@SubstoreID IS NULL OR @SubstoreID = 0 OR Substores.ID = @SubstoreID)
        AND (
            (ISNULL(@IPatientType, 0) = 0 AND ISNULL(@OPatientType, 0) = 0)
            OR (ISNULL(@IPatientType, 0) = 1 AND LEFT(ISNULL(PatientBill.IPOPNo, ''), 2) = 'IP')
            OR (ISNULL(@OPatientType, 0) = 1 AND LEFT(ISNULL(PatientBill.IPOPNo, ''), 2) = 'OP')
        );
END
GO
/****** Object:  StoredProcedure [Billing].[SP_patientUnPaiedServicesReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [Billing].[SP_patientUnPaiedServicesReport]
(
-- @startDate varchar(50),@endDate varchar(50))
 @startDate Datetime,@endDate Datetime,
 @patientId int null
 )
 as
SELECT        b.Id, b.PatientID,isnull( p.FirstName,'') + ' ' + isnull(p.MiddleName1,'') +' '+ isnull(p.MiddleName2,'')+ ' ' + isnull(p.LastName,'') AS PatientName, p.Code, a.ItemCode, a.ItemName, a.Quantity, a.CreatedDate, a.Discount, a.Amount, a.DoctorID, Registration.Doctors.Name, 
                         ISNULL(a.AmountBefore * (a.Discount / 100), 0) AS DiscountVal, a.Vat, a.AmountAfter, a.ReceiptDescount, CASE WHEN p.SponsorId IS NULL THEN N'كاش' ELSE N'تحت تأمين' END AS PType, b.IPOPNo, 
                         CASE WHEN p.PatientType = 1 THEN N'مريض خارجي' WHEN p.PatientType = 4 THEN N'مريض طوارئ' WHEN p.PatientType = 2 THEN N'مريض داخلي' WHEN p.PatientType = 3 THEN N'مريض محول' WHEN p.PatientType = 0 THEN 'All' ELSE '' END
                          AS PatientType, Spec.NameAr, Spec.Name AS NameEN, Registration.Doctors.NameAr AS DNameAR
FROM            Billing.PatientBillservices AS a INNER JOIN
