/****** Object:  StoredProcedure [Billing].[SP_PaymentInvoice_Report_AR]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   PROCEDURE [Billing].[SP_PaymentInvoice_Report_AR]
    @FromDate     DATETIME     = NULL,
    @ToDate       DATETIME     = NULL,
    @PatientID    INT          = NULL,
    @CustomerID   INT          = NULL,
    @RequestedByID NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        Registration.Patients.FirstName + ' ' + 
        ISNULL(Registration.Patients.MiddleName1, '') + ' ' + 
        ISNULL(Registration.Patients.MiddleName2, '') + ' ' + 
        ISNULL(Registration.Patients.LastName, '')      AS [اسم المريض],

        BillServices.OP_IPNumber                        AS [رقم الملف],
        InsCo.NameArabic                                AS [شركة التأمين],
        FORMAT(BillServices.CreatedDate, 'dd/MM/yyyy')  AS [تاريخ الطلب],
        Service.NameAr                                  AS [الخدمة],
        Doctors.NameAr                                  AS [الطبيب],
        ISNULL(BillServices.PateintPaidAmount, 0) + 
        ISNULL(BillServices.PatVat, 0)                  AS [المبلغ]

    FROM Registration.Patients
    INNER JOIN Billing.PatientBill 
        ON Patients.Id = PatientBill.PatientID
    INNER JOIN Billing.PatientBillservices AS BillServices 
        ON PatientBill.Id = BillServices.PatientBillID
    INNER JOIN Billing.InsuranceCompanies InsCo 
        ON BillServices.SponserId = InsCo.ID
    INNER JOIN ApplicationSetup.Service 
        ON BillServices.ItemID = Service.Id
    LEFT JOIN Registration.Doctors AS Doctors 
        ON BillServices.DoctorID = Doctors.Id

    WHERE (BillServices.PaidDate >= CONVERT(DATETIME, @FromDate, 103) OR @FromDate IS NULL)
      AND (BillServices.PaidDate <  CONVERT(DATETIME, @ToDate,   103) OR @ToDate  IS NULL)
