/****** Object:  StoredProcedure [Billing].[SP_ReceiptPrint_Report]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Billing].[SP_ReceiptPrint_Report]
    @Receipt int = null
AS
SELECT 
    AdvanceReceipts.ReceiptNumber, 
    AdvanceReceipts.ReceiptDate, 
    Patients.AlternateNo, 
    Patients.DateOfBirth, 
    Patients.SponsorName,
    Patients.GenderId, 
    Doctors.Name, 
    PaymentModes.PaymentModeDescription, 
    PaymentDetails.TransactionNo, 
    PaymentDetails.TransactionDate,
    PaymentDetails.Amount, 
    Banks.BanksDescription,
    ISNULL(Patients.FirstName, N'') + ' ' + ISNULL(Patients.MiddleName1, N'') + ' ' + ISNULL(Patients.MiddleName2, N'') + ' ' + ISNULL(Patients.LastName, N'') AS PatientName, 
    Item.Name AS ItemName, 
    PaymentDetails.Amount,
    AdvanceReceiptsItems.Quantity
FROM Billing.AdvanceReceipts AS AdvanceReceipts               -- البداية بقت من هنا بدل AdvanceReceiptsItems
JOIN Registration.Patients AS Patients
    ON AdvanceReceipts.PatientID = Patients.Id
LEFT JOIN Billing.AdvanceReceiptsItems AS AdvanceReceiptsItems -- تعديل: LEFT بدل INNER
    ON AdvanceReceiptsItems.AdvanceReceiptId = AdvanceReceipts.Id
LEFT JOIN ApplicationSetup.Item AS Item                         -- تعديل: LEFT بدل INNER
    ON AdvanceReceiptsItems.ItemID = Item.ID
LEFT JOIN Registration.Doctors AS Doctors                       -- تعديل: LEFT بدل INNER
    ON AdvanceReceipts.DoctorID = Doctors.Id
LEFT JOIN Billing.PaymentDetails AS PaymentDetails              -- تعديل: LEFT بدل INNER
    ON PaymentDetails.AdvanceReceiptId = AdvanceReceipts.Id 
LEFT JOIN Billing.PaymentModes AS PaymentModes                  -- تعديل: LEFT بدل INNER
    ON PaymentDetails.PaymentModeId = PaymentModes.Id 
LEFT JOIN hr.Banks AS Banks                                     -- تعديل: LEFT بدل INNER
    ON PaymentDetails.BankID = Banks.ID 
