/****** Object:  StoredProcedure [Billing].[UnConfirmedCashierBoxOpenSessions]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [Billing].[UnConfirmedCashierBoxOpenSessions] 
(
@UserID nvarchar(max),
@BoxID int
)
as 
begin
SELECT        cb.NameEn, u.UserName, format(os.ConfirmDate, 'dd/MM/yyyy HH:mm:ss') AS StartDate, format(os.CloseDate, 'dd/MM/yyyy HH:mm:ss') AS EndDate,
isnull(os.Amount,0)+isnull(os.SessionStartBalance,0)  as SessionEndBalance
FROM            Billing.CashierBoxOpenSessions AS os INNER JOIN
                         Billing.CashierBox AS cb ON os.BoxID = cb.ID LEFT OUTER JOIN
                         JCIT_MembershipDB.dbo.AspNetUsers AS u ON os.UserID = u.Id
WHERE        (os.Status = 3) AND (cb.BoxType = 2)
and (os.UserID=@UserID or @UserID is null)
and (os.BoxID=@BoxID or @BoxID is null)
end



GO
/****** Object:  StoredProcedure [Billing].[VoucherReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [Billing].[VoucherReport]
(

@Date int,
@ToDate int,
@BoxIDFrom int
,
@BoxIDTo int
)
as
SELECT        Billing.Voucher.ID, Billing.Voucher.BoxID, Billing.Voucher.VoucherCode, Billing.Voucher.PersonNameAr, Billing.Voucher.PersonNameEN, Billing.Voucher.Date, Billing.Voucher.IsConfirmed, Billing.VoucherDetails.Amount, 
                         Billing.VoucherDetails.Description, Billing.Voucher.VoucherType, CASE WHEN Billing.Voucher.VoucherType = 1 THEN N'تقرير الصرفيات' WHEN Billing.Voucher.VoucherType = 2 THEN N'تقرير الوارد' END AS VType, 
                         Billing.CashierBox.NameAr
FROM            Billing.Voucher INNER JOIN
                         Billing.VoucherDetails ON Billing.Voucher.ID = Billing.VoucherDetails.VoucherID INNER JOIN
                         Billing.CashierBox ON Billing.Voucher.BoxID = Billing.CashierBox.ID

