/****** Object:  StoredProcedure [BloodBank].[BloodBankDoners]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [BloodBank].[BloodBankDoners]
	(@DonarID int=NULL, @FromDate NVARCHAR(20)=NULL,@ToDate NVARCHAR(20)=null)
AS
BEGIN
	
	SELECT Concat(DonorRegistration.FirstNameLatin,'  ',DonorRegistration.SecoendNameLatin,' ',
	DonorRegistration.ThirdNameLatin,' ',DonorRegistration.LastNameLatin)as FullName,
Donor.donationDate,
 Donor.Code,
  GroupName.GroupNameLatin,
 Campaign.NameEn as CampaignName,
case when Donor.VoucherID IS Not NULL  then 'Paid' else 'Not Paid'end as Status,
 case when Donor.BagDeal=1 then 'Balance' when Donor.BagDeal=2 then 'Free' else 'For Money' end as BagDealName,
 case when Donor.FinalResult=1 then 'Passed' when ISNull( Donor.FinalResult ,0)=0 then 'Not Passed' End as FinalResult,
 case when Donor.Status=1 then 'Not Tested' when Donor.Status=2 then 'Active'
 when Donor.Status=3 then 'Scrap' when Donor.Status= 4  then 'Expired' when Donor.Status=5 then 'Seperated'
 when Donor.Status=6 then 'Dispensed' End as BagStatus

 FROM BloodBank.DonorRegistration As DonorRegistration INNER JOIN
 BloodBank.DBloodBags As Donor ON DonorRegistration.ID = Donor.DonorID
 LEFT OUTER JOIN BloodBank.Campaign As Campaign ON Campaign.ID = Donor.CampaignID
 LEFT OUTER JOIN BloodBank.BloodGroup As GroupName ON GroupName.ID = Donor.BloodGroup_ID
 WHERE (DonorRegistration.id=@donarID OR @donarID IS NULL)AND 
 (@fromDate IS NULL or Donor.donationDate>=
 
  CAST(@FromDate AS date) )
  --Convert(Datetime,@FromDate,103)	)
   and 
 (@ToDate IS NULL or
  Donor.donationDate<=
 -- Convert(Datetime,@ToDate,103)	
  DATEADD(day,1,CAST(@ToDate AS date)) 
 )
END



