CREATE proc [BloodBank].[QuantityofScrapBloodBagsReport]
(
@FromStoreID int,
@ToStoreID int
)
as
SELECT        BloodBank.DBloodBags.StoreID, BloodBank.BloodGroup.BloodGroupCode, BloodBank.BloodGroup.GroupNameLatin, BloodBank.BloodGroup.GroupNameLocal, BloodBank.BloodProduct.BloodProductCode, 
                         BloodBank.BloodProduct.ProductNameLatin, BloodBank.BloodProduct.ProductNameLocal, BloodBank.BloodBankInventory.NameAr, BloodBank.BloodBankInventory.NameEn, BloodBank.DBloodBags.Size, 
                         BloodBank.DBloodBags.ScrapDate, BloodBank.DBloodBags.ScrapReson, BloodBank.DBloodBags.LastModifiedBy, ISNULL(Nursing.Employee.FirstName, N'') + ' ' + ISNULL(Nursing.Employee.MiddleName, N'') 
                         + ' ' + ISNULL(Nursing.Employee.BeforeLastName, N'') + ISNULL(Nursing.Employee.LastName, N'') AS EmpNameAr, ISNULL(Nursing.Employee.FirstNameEn, N'') + ' ' + ISNULL(Nursing.Employee.MiddleNameEn, N'') 
