/****** Object:  StoredProcedure [BloodBank].[Sp_BBInventoryAdjustmentReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE  proc [BloodBank].[Sp_BBInventoryAdjustmentReport]
(@ID int)
as
begin
select JCIT_MembershipDB.dbo.AspNetUsers.EnglishName as Username, 
BloodBank.BloodBankInventory.NameEn  stockname,
reasons.Description as AdjustmentReason
,
BloodGroup.GroupNameLatin
,'Status'=
CASE 
    WHEN BloodBank.InventoryAdjustment.Status =1 THEN 'Pending'
    WHEN BloodBank.InventoryAdjustment.Status =1  THEN 'Done'
    
    ELSE ''
END 
,BloodBank.InventoryAdjustment.Date ,
BloodBank.InventoryAdjustment.Remarks ,
BloodBank.InventoryAdjustment.PhysiacalNO ,
BloodBank.InventoryAdjustmentEntry.QTYAdj
, BloodBank.InventoryAdjustmentEntry.QtYDifference ,
BloodBank.InventoryAdjustmentEntry.QTYinHand

from  BloodBank.InventoryAdjustment

inner join BloodBank.InventoryAdjustmentEntry 
on BloodBank.InventoryAdjustment.ID=BloodBank.InventoryAdjustmentEntry.PhysiacalAdjID 
inner join BloodBank.BloodBankInventory
on BloodBank.InventoryAdjustment.StockID = BloodBank.BloodBankInventory.ID
inner join  GeneralStores.StockAdjustmentReasons as reasons
on BloodBank.InventoryAdjustment.ReasonAdjusyId = reasons.ID
inner join  BloodBank.BloodGroup  as BloodGroup
on BloodBank.InventoryAdjustmentEntry.BloodGroupId  = BloodGroup.ID
inner join  JCIT_MembershipDB.dbo.AspNetUsers
on BloodBank.InventoryAdjustment.CreatedBy = JCIT_MembershipDB.dbo.AspNetUsers.Id

 where BloodBank.InventoryAdjustment.ID=@ID

end


GO
/****** Object:  StoredProcedure [BloodBank].[Sp_BloodBagsReceipt]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [BloodBank].[Sp_BloodBagsReceipt](@bagID int)
as
begin
select DBloodBags.*,BloodGroup.GroupNameLatin,DonorRegistration.FirstNameLatin+' '+DonorRegistration.SecoendNameLatin+' '+DonorRegistration.ThirdNameLatin as DonorName from BloodBank.DBloodBags
inner join BloodBank.DonorRegistration on DBloodBags.DonorID=DonorRegistration.ID
inner join BloodBank.BloodGroup on DBloodBags.BloodGroup_ID=BloodGroup.ID
 where DBloodBags.ID=@bagID
end


