on BloodBankInventory.ID =BloodBankInventoryBloodGroup.BloodBankInventoryId
inner join BloodBank.DonorRegistration
on DonorRegistration.id=BloodBankInventory.DonorID

inner join BloodBank.BloodGroup
on BloodGroup.ID=BloodBankInventoryBloodGroup.BloodGroupID

inner join BloodBank.BloodProduct
on BloodProduct.ID=BloodBankInventory.BloodProductID

where 
(BloodProduct.ID=@BloodProductID or @BloodProductID=0) 
and (BloodGroup.ID=@BloodGroupID or @BloodGroupID=0)
and (DonorRegistration.id=@DonorID or @DonorID=0)
and (DonorRegistration.DateFrom>=@DateFrom or  @DateFrom is null)
and (DonorRegistration.DateTo<@DateTo or @DateTo is null)

END





