CREATE procEDURE [BloodBank].[SP_DonorVisits_Report]
@DonorId int=0,
@DateFrom datetime=null,
@DateTo datetime=null
AS
BEGIN
Select Distinct 
	DBloodBags.Code as BagNo,
	BloodGroup.GroupNameLocal as BloodGroup,
	DonorRegistration.FirstNameLocal+' '+DonorRegistration.SecoendNameLocal+' '+DonorRegistration.ThirdNameLocal+' '+DonorRegistration.LastNameLocal as DonorFullName,
	DBloodBags.CreatedDate as DonDate,
	Laboratory.Tests.TestName as TestName,
	BloodTestingResultDetail.CreatedDate as TestDate,
	BloodTesting.Description as Testdesc,
	case when BloodTestingResultDetail.Result=1 then 'Passed' else 'Not Passed' end  as ResultName
	
	 
from 

	BloodBank.DonorRegistration 
	inner join BloodBank.BloodGroup on BloodGroup.ID=DonorRegistration.BloodGroupID
	inner join BloodBank.DBloodBags on DBloodBags.BloodGroup_ID=BloodGroup.ID and DBloodBags.DonorID=DonorRegistration.ID
	inner join BloodBank.BloodTestingResultDetail on DBloodBags.ID=BloodTestingResultDetail.BagID 
    inner join BloodBank.BloodTesting on BloodTesting.ID =BloodTestingResultDetail.TestID 
	inner join Laboratory.Tests on Tests.ServiceId=BloodTesting.ServiceId 
	
