/****** Object:  StoredProcedure [Budgeting].[Financialpositionreport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE proc [Budgeting].[Financialpositionreport] @Date as datetime ,@year nvarchar(20)
as 
 
select a1.id,a1.AccountNo,a1.AccountNameAr,b1.BudgetValue 'ربط اصلى', sum(t1.Amount) 'تعزيز'
, (select sum (t2.Amount) 
from [Budgeting].BudgetTransaction t2
where t2.OtherAccount=a1.id and t2.Year=b1.YearNo
) 'نقل',
--جديد
( select sum(ex.Amount) from Budgeting.BudgetExpends ex where ex.AccountID =a1.id and MONTH(ex.ReqestDate) = MONTH(@Date) ) AS 'منصرف حالى'
,
( select sum(ex.Amount) from Budgeting.BudgetExpends ex where ex.AccountID =a1.id and (ex.ReqestDate) < (@Date) ) AS 'منصرف سابق'
　
from [gl].accounts a1
left join [Budgeting].Yearly_Budget b1
on a1.id=b1.AccountID 
left join [Budgeting].BudgetTransaction t1
on t1.AccountId=a1.id and t1.Year=b1.YearNo
-- جديد
--left join Budgeting.BudgetExpends BE 
--on BE.AccountID=a1.id and convert(nvarchar, Year(Be.ReqestDate))=convert(nvarchar(4), b1.YearNo)
group by a1.id,a1.AccountNo,a1.AccountNameAr,b1.BudgetValue,b1.YearNo
-- جديد
having b1.YearNo = @year




GO
