						update @BDG_ACC_Tbl
						set BDG_LINE_ID = @BDG_LINE_ID

						if @mode = 'U'
						begin
							----delete old data from BDG_ACC
							delete from [Budgeting].BDG_ACC where BDG_LINE_ID = @BDG_LINE_ID
						end

						INSERT INTO [Budgeting].BDG_ACC
						(
							BDG_LINE_ID,
							BDG_YEAR,
							BDG_CODE,
							BDG_LIN,
							BDG_ORD,
							ACC_NU,
							ACC_NU_C,
							SUB_NU,
							SUB_NU_C,
							BDG_TYP_Y,
							BDG_TYP_N,
							BDG_TBL
						)
						SELECT
							BDG_LINE_ID,
							BDG_YEAR,
							BDG_CODE,
							BDG_LIN,
							BDG_ORD,
							ACC_NU,
							ACC_NU_C,
							SUB_NU,
							SUB_NU_C,
							BDG_TYP_Y,
							BDG_TYP_N,
							BDG_TBL
						from @BDG_ACC_Tbl 	
					end
				end
				else if @BDG_TYP = '3' --Equation
				begin
					if exists(select BDG_LINE_ID from [Budgeting].BDG_EQT where BDG_LINE_ID = @BDG_LINE_ID)
					begin
						update BDG_EQT
						set
							BDG_EQT = @BDG_EQT,
							CELL_FM = @CELL_FM,
							CELL_LINF = @CELL_LINF,
							CELL_TO = @CELL_TO,
							COL_FM = @COL_FM,
							COL_TO = @COL_TO,
							CELL_LINT = @CELL_LINT,
							ROW_CRT = @ROW_CRT
						where BDG_LINE_ID = @BDG_LINE_ID
					end
					else
					begin
						insert into [Budgeting].BDG_EQT
						values
						(
							@BDG_LINE_ID,
							@BDG_YEAR,
							@BDG_CODE,
							@BDG_LIN,
							@BDG_EQT,
							@CELL_FM,
							@CELL_LINF,
							@CELL_TO,
							@COL_FM,
							@COL_TO,
							@CELL_LINT,
							@ROW_CRT
						)
					end
				end

			COMMIT TRAN
			print 'SUCCESS'
			-- ReturnValue
			select 'S' + cast(@BDG_LIN as varchar(50))
	END TRY
	BEGIN CATCH
				IF @@TRANCOUNT > 0
					ROLLBACK TRAN --RollBack in case of Error
