CREATE PROC [ClinicalPharmacy].[CategorizedMedicalErrorsReportproc]
    @PidFrom  NVARCHAR(4000) = NULL,
    @PidTo    NVARCHAR(4000) = NULL,
    @DateFrom NVARCHAR(4000),          -- ✅ mandatory - مفيش default
    @DateTo   NVARCHAR(4000)           -- ✅ mandatory - مفيش default
AS
BEGIN
    -- التحقق من التاريخ إجباري
    IF @DateFrom IS NULL OR @DateTo IS NULL
    BEGIN
        RAISERROR('DateFrom and DateTo are required', 16, 1)
        RETURN
    END

    SELECT DISTINCT * 
    FROM [ClinicalPharmacy].Categorized_MedicalErrorsReport 
    WHERE
        -- ✅ البيشنت اختياري - لو NULL هيجيب الكل
        (
            @PidFrom IS NULL 
            OR 
            Paid BETWEEN CAST(@PidFrom AS BIGINT) AND CAST(@PidTo AS BIGINT)
        )
        AND
        -- ✅ التاريخ إجباري دايماً
        (
            CAST(CONVERT(CHAR(8), CreatedDate, 112) AS BIGINT) 
                BETWEEN CAST(@DateFrom AS BIGINT) AND CAST(@DateTo AS BIGINT)
            OR CreatedDate IS NULL
        )
END
GO
