CREATE procEDURE  [ClinicalPharmacy].[ReFollowUp]
@PatientID int  null
 
 
as
begin



SELECT p.id,p.Age,  CAST(LastIP.IP_OP AS NVARCHAR(250))  IP_OP, ISNULL(p.FirstName,'')+' '+ISNULL(p.MiddleName1,'')+' '
+ISNULL(p.MiddleName2,'')+' '+ISNULL(p.LastName,'') AS FullName,
LastIP.Diagnosis,LastIP.Past,LastIP.Complaints,p.Smoker,LastIP.Height,LastIP.Weight
    FROM Registration.Patients p  
CROSS APPLY
        (
        SELECT  TOP 1 ISNULL(obs.IP_OP,'') IP_OP,STUFF((Select ','+codes.ICDDescription
from  InPatient.MedicalObservationICDCodes T1
JOIN Nursing.ICDCodes codes ON t1.ICDCodeID
= codes.Id
where T1.MedicalObservationID=obs.id
FOR XML PATH('')),1,1,'') Diagnosis,obs.Height,obs.Weight,obs.Complaints
,
STUFF((Select ','+t1.Name
FROM InPatient.MedicalObservation_TagsValues v 
JOIN InPatient.Tags t1 ON v.PageTagsId=t1.id
WHERE v.Value1 IS NOT NULL AND  
 v.MedicalObservationId=obs.Id and
