/****** Object:  StoredProcedure [ClinicalPharmacy].[SP_ClinicalIntervention_ReportAr]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [ClinicalPharmacy].[SP_ClinicalIntervention_ReportAr] 
    @patientId int = NULL
AS
SELECT
    patient.FirstName + ' ' + patient.MiddleName1 + ' ' + patient.MiddleName2 + ' ' + patient.LastName AS PatientName,
    ClinicalIntervention.Code AS Code,
    ISantimicromedical AS antimicromedical,
    DrugRelatedProblemEnum AS DrugRelatedProblem,
    DrugRelatedProblemNote,
    DrugDrugInteractionEnum AS DrugDrugInteraction,
    ClinicalSignificanceEnum AS ClinicalSignificance,
    ISCostSaving AS CostSaving,
    ISADR AS ADR,
    ISEnhanced AS Enhanced,
    ExpectedOutComeNote,
    ClinicalPharmcistNote,
    FollowUpNote,
    PhyisionResponseEnum AS PhyisionResponse,
    IFReectedNote AS RejectedReason,
    Drugs.DrugNameAr,
    CostCenter.NameAr AS CostCenter,
    ClinicalIntervention.PhyisionSpicialistID AS PhyisionSpicialist,
    Employee.FirstNameAr + ' ' + Employee.MiddleNameAr + ' ' + Employee.LastNameAr AS ClinicalPharmcist
FROM ClinicalPharmacy.ClinicalIntervention AS ClinicalIntervention
JOIN Registration.Patients AS patient ON ClinicalIntervention.PatientID = patient.Id
JOIN Pharmacy.Drugs AS Drugs ON ClinicalIntervention.DrugID = Drugs.ID
JOIN ApplicationSetup.CostCenter AS CostCenter ON ClinicalIntervention.CostCenterID = CostCenter.Id
JOIN Nursing.Employee AS Employee ON ClinicalIntervention.ClinicalPharmcistID = Employee.Id
WHERE
    (@patientId IS NULL OR ClinicalIntervention.PatientID = @patientId)

GO
