 from Registration.DoctorsDailySchedule left join  Registration.DoctorsDailyScheduleDetails
 on Registration.DoctorsDailySchedule.Id =  Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID
 where Registration.DoctorsDailySchedule.DoctorID=Registration.DoctorDutyRosters.DoctorID and Registration.DoctorsDailySchedule.ScheduleDate= '+@test+')
  as Slots
from Registration.DoctorDutyRostersDetails inner join  Registration.DoctorDutyRosters
on  Registration.DoctorDutyRosters.Id = Registration.DoctorDutyRostersDetails.DoctorDutyRostersHeaderId
inner join Registration.Doctors 
on Registration.Doctors.Id=Registration.DoctorDutyRosters.DoctorID
where DATEPART(MINUTE,TimeSlot) != 0 and '+@test+'  between Registration.DoctorDutyRosters.DateFrom and Registration.DoctorDutyRosters.DateTo
and Registration.DoctorDutyRostersDetails.Day like DATENAME(dw,'+@test+') 
 Registration.Doctors.GenericClinicID= @GenericClinicID
) x
pivot
(
max(x.Slots)
for x.Name in (' + @cols + ') 
) p 
select  * from   #Test  '

