-- Description:	This stored procedure is intended for updating 	data_patientradiologystudy table
-- ==========================================================================================
CREATE PROCEDURE [dbo].[data_patientradiologystudy_Update]
(
	
	@uid int,
	@patientname nvarchar(100),
	@radiologyname nvarchar(50) = NULL,
	@radiotime datetime
)
AS
	SET NOCOUNT ON

	UPDATE data_patientradiologystudy SET 

		[patientname] = @patientname ,
		[radiologyname] = @radiologyname ,
		[radiotime] = @radiotime 
	WHERE [uid]=@uid


GO
