CREATE PROCEDURE [dbo].[data_radioimages_Update]
(
	
	@id int,
	@radiouid int,
	@radioimage nvarchar(150) = NULL
)
AS
	SET NOCOUNT ON

	UPDATE data_radioimages SET 

		[radiouid] = @radiouid ,
		[radioimage] = @radioimage 
	WHERE [id]=@id


GO
