/****** Object:  StoredProcedure [dbo].[DynamicPivotTableInSql]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[DynamicPivotTableInSql]
  @ColumnToPivot  NVARCHAR(255),
  @ListToPivot    NVARCHAR(255)
AS
BEGIN
 
  DECLARE @SqlStatement NVARCHAR(MAX)
  SET @SqlStatement = N'
    SELECT * FROM (
      SELECT
        
        [EmUnit.ArrivalTypeID],
        [EmUnit.PatientID ]
      FROM [Registration].[Patients] patient
  inner join [Emergency].[EmergencyUnit] EmUnit on EmUnit.PatientID = patient.Id
  inner join  [Emergency].[EmergencyDetails] EmergencyDetail on EmergencyDetail.PatientID =patient.Id
  inner join [Emergency].[ComplainSetup] ComplainSet on ComplainSet.Id = EmUnit.ComplainID
  inner join [Registration].[Doctors] Doct on Doct.Id = EmUnit.DoctorID
  inner join [Emergency].[CasePriority] CasePriority on CasePriority.Id = EmUnit.CasePriortyID
  where EmUnit.ArrivalTypeID=@cols  
    ) StudentResults
    PIVOT (
      Count([EmUnit.PatientID ])
      FOR ['+@ColumnToPivot+']
      IN (
        '+@ListToPivot+'
      )
    ) AS PivotTable
  ';
 
  EXEC(@SqlStatement)
 
END
GO
/****** Object:  StoredProcedure [dbo].[Findtext]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[Findtext] @textname NVARCHAR(100)
AS

SELECT [Scehma]=schema_name(o.schema_id), o.Name, o.type 
FROM sys.sql_modules m
INNER JOIN sys.objects o
ON o.object_id = m.object_id
WHERE m.definition like '%'+@textname+'%'
order by schema_id

GO
