-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE  [dbo].[GetAllLPOInfo] (@LPOID int)
	-- Add the parameters for the stored procedure here
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
		SELECT (select top 1 [Image] from [ApplicationSetup].[QRImage] 
		where [ReportName]=N'GeneralStoresLocal' and 
		[InvoiceId]=@LPOID order by id desc) as QRImage,  
		GeneralStores.LocalPurchaseOrderHeader.PONumber,
		convert(nvarchar(50),FORMAT( GeneralStores.LocalPurchaseOrderHeader.PODate ,'dd/MM/yyyy HH:mm:ss')) as PODate , 
		GeneralStores.Stocks.StockName, GeneralStores.Suppliers.SupplierName, Items_1.ItemCode, Items_1.ItemName,
		GeneralStores.Units.UnitNameEn, GeneralStores.UnitTemplate.UnitTemplateName, 
