CREATE procEDURE [dbo].[PatientAllergy]
	-- Add the parameters for the stored procedure here
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT        Registration.Patients.Id, Registration.Patients.Code, Registration.PatientAllergy.Id AS AllergyID, Registration.PatientAllergy.AllergyDesc, Registration.PatientAllergy.AllergyTypeEnumValue, Registration.PatientAllergy.PatientID, 
                         Registration.PatientAllergy.CreatorName
FROM            Registration.Patients INNER JOIN
                         Registration.PatientAllergy ON Registration.Patients.Id = Registration.PatientAllergy.PatientID
END



