CREATE procEDURE [dbo].[PatientInfo]
	-- Add the parameters for the stored procedure here	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT        P.*,u.FirstName+' '+u.LastName as FullName
FROM            Registration.Patients P
inner join JCIT_MembershipDB.dbo.AspNetUsers u on
u.Id=p.CreatedBy
END




