SELECT       GeneralStores.IssuetoDepartment.ID, GeneralStores.IssuetoDepartment.IssueNumber, GeneralStores.IssuetoDepartment.IssueDate, GeneralStores.IssuetoDepartment.IssueRequestID,
 (select GeneralStores.Stocks.StockName from GeneralStores.Stocks where GeneralStores.Stocks.ID=GeneralStores.IssuetoDepartment.MainStockID) as MainStockName,
(select GeneralStores.Stocks.StockName from GeneralStores.Stocks where GeneralStores.Stocks.ID=GeneralStores.IssuetoDepartment.StockID) as BranchStockName,
                         GeneralStores.IssuetoDepartmentEntry.IssueQty, GeneralStores.IssuetoDepartmentEntry.Date, GeneralStores.IssuetoDepartmentEntry.TotalReturnQty,
						 (select GeneralStores.Items.ItemName from GeneralStores.Items where GeneralStores.Items.ID= GeneralStores.IssuetoDepartmentEntry.ItemID) as ItemName, 
                         GeneralStores.UnitConversionFactor.ConversionValue, GeneralStores.UnitTemplate.UnitTemplateName, GeneralStores.IssuetoDepartmentEntry.CurrentQty
FROM            GeneralStores.Stocks INNER JOIN
                         GeneralStores.IssuetoDepartment ON GeneralStores.Stocks.ID = GeneralStores.IssuetoDepartment.ID INNER JOIN
                         GeneralStores.Items ON GeneralStores.Stocks.ID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.IssuetoDepartmentEntry ON GeneralStores.IssuetoDepartment.ID = GeneralStores.IssuetoDepartmentEntry.IssuetoDepartmentId INNER JOIN
                         GeneralStores.Batches ON GeneralStores.Stocks.ID = GeneralStores.Batches.Id CROSS JOIN
                         GeneralStores.UnitTemplate CROSS JOIN
                         GeneralStores.UnitConversionFactor
						 where GeneralStores.IssuetoDepartment.ID=@ID
END




