-- =============================================
-- Author:		Mahmoud Mostafa
-- Create date: 02/04/2016
-- Description:	Search Users
-- =============================================
CREATE PROCEDURE [dbo].[SearchUsers]
	@ApplicationId nvarchar(255) = NULL, 
	@UserName nvarchar(255) = NULL, 
	@FirstName nvarchar(255) = NULL,
	@LastName nvarchar(255) = NULL,
	@Email nvarchar(255) = NULL, 
	@PhoneNumber nvarchar(255) = NULL, 
	@AccountStatus int = NULL, 
	@RangeFrom datetime = NULL, 
	@RangeTo datetime = NULL, 
	@StartRowIndex int = NULL, 
	@PageSize int = NULL
AS
BEGIN
	SET NOCOUNT ON;

	SELECT @PageSize = COALESCE(@PageSize, 2000000000);

	SELECT [Id]
      ,[UserName]
      ,[Email]
      ,[PhoneNumber]
      ,[FirstName]
      ,[LastName]
      ,[Address]
      ,[BirthDate]
      ,[LoweredEmail]
      ,[LoweredUserName]
      ,[IsLockedOut]
      ,[CreateDate]
	  ,[LastActivityDate]
	  ,TableCountUsers.CountUsers,[EmployeeID]
	  --,ROW_NUMBER() OVER(ORDER BY UserName) AS RowNumber
  FROM JCIT_MembershipDB.[dbo].[AspNetUsers]
  CROSS JOIN (SELECT Count(*) AS CountUsers FROM [dbo].[AspNetUsers]) AS TableCountUsers
  WHERE (ApplicationId = @ApplicationId)
  AND  (@UserName IS NULL OR (UserName like '%' + @UserName +'%'))
  AND (@FirstName IS NULL OR (FirstName like '%' + @FirstName +'%'))
  AND (@LastName IS NULL OR (LastName like '%' + @LastName +'%'))
  AND (@Email IS NULL OR (Email like '%' + @Email +'%'))
  AND (@PhoneNumber IS NULL OR (PhoneNumber like '%' + @PhoneNumber +'%'))
