CREATE procEDURE [dbo].[SPSearch]
	@USR_C varchar(10)
	,@Description nvarchar(100)=null
	,@Table varchar(100)
	,@TMPFields varchar(200)  	
	,@Fields varchar(300) 
	,@Conditions nvarchar(max) = null
	,@Group bit = 0 -- 0 not group
	--,@OrderByFields varchar(300) = null 
	--,@IsDesOrder bit = 0 -- 0 not group

AS
BEGIN
declare @MySql nvarchar(1000)
delete from TMP_Search Where USR_C = @USR_C
if @Description Is Null
Begin
	set @MySql = 'Insert INTO TMP_Search (USR_C,' + @TMPFields +') SELECT distinct '''+ @USR_C +''',' + @Fields + ' From ' + @Table
	if @Conditions is not null
		begin
			set @MySql = @MySql + ' where ' +  @Conditions 	
			print @MySql
		end 
	if @Group <> 0
		begin
			set @MySql = @MySql + ' group by ' + @Fields
		end 

		--if @OrderByFields is not null
		--begin
		--	set @MySql = @MySql + ' group by ' + @Fields
		--end 

	execute (@MySql)
End
Else
Begin
	if @Conditions Is Not Null
		exec ('exec ' + @Description +' '+ @USR_C +' , '''+ @Conditions +''' , '''+ @TMPFields +''' , '''+ @Fields+'''') 	
	Else
