/****** Object:  StoredProcedure [dbo].[SupplierBalanceReview]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [dbo].[SupplierBalanceReview](@supFrom int=null,@supTo int=null,@DateFrom nvarchar(50)=null,@DateTo nvarchar(50)=null)
as
begin

select *,
(OBCredit+STCredit+BCredit) CreditBalance,
(OBDebit+STDebit+BDebit) DebitBalance
from(

Select ID,SupplierName, 
isNull(OpenBalance.Debit,0) OBDebit ,isNull(OpenBalance.Credit,0)OBCredit,
isNULL(TSupplierTrans.Debit,0)STDebit,isNull(TSupplierTrans.Credit,0)STCredit,
isNull(DataBefore.Debit,0) BDebit,isNull(DataBefore.Credit,0) BCredit


from 
GeneralStores.Suppliers Supp
Left Outer Join
(select Sum(ISNULL(Debit,0)) Debit,SUM(ISNULL(Credit,0)) as Credit,N'رصيد افتتاحى' as Mtype,SupplierID
from GeneralStores.AddSupplierBalance 
where ((@supFrom is null or SupplierID>=@supFrom) 
     and (@supTo is null or SupplierID<=@supTo))
and IsOpeningBalance=1  
group by SupplierID) as OpenBalance on OpenBalance.SupplierID=Supp.ID
 Left Outer Join
(
--Supplier Purchase
Select Sum(ISNULL(Debit,0))Debit,Sum(ISNULL(Credit,0))Credit ,Name,SupplierID from (
select 0 Debit,Sum(ISNULL(PurchQty,0)) as Credit,N'مشتريات' TransType,Name,SupplierID
from V_SupplierPurchaseDetails  
where  ((@supFrom is null or SupplierID>=@supFrom) 
and    (@supTo is null or SupplierID<=@supTo))
and    ((@DateFrom is null or PurchDate>=Cast(@DateFrom as date)) 
and    (@DateTo is null or PurchDate<=Cast(@DateTo as date)))
group by SupplierID,Name
 
 Union
--Supplier Purchase Return

select  Sum(ISNULL(ReturnQTY,0)) Depit,0 as Credit,N' مرتجع مشتريات' TransType,Name,SupplierID
from V_SupplierPurchaseDetailsReturn  
where  ((@supFrom is null or SupplierID>=@supFrom) 
and    (@supTo is null or SupplierID<=@supTo))
and    ((@DateFrom is null or RPurchDate>=Cast(@DateFrom as date)) 
and    (@DateTo is null or RPurchDate<=Cast(@DateTo as date)))
group by SupplierID,Name

Union
select Sum(ISNULL(Debit,0)) Depit,SUM(ISNULL(Credit,0)) as Credit,N'تسوية' as Mtype,Suppliers.SupplierName,SupplierID
