SELECT Users.Id, ApplicationId, UserName, Email, EmailConfirmed, PasswordHash, SecurityStamp, PhoneNumber, PhoneNumberConfirmed
, TwoFactorEnabled, LockoutEndDateUtc, LockoutEnabled, AccessFailedCount, FirstName,LastName, Address, BirthDate, LoweredEmail
, LoweredUserName, LegacyUserName, LegacyPasswordHash, PasswordQuestion, PasswordAnswer, IsApproved, IsLockedOut, IsPasswordExpired
, CreateDate, LastLoginDate, LastActivityDate, LastPasswordChangedDate, LastUserNameChangedDate, LastLockoutDate
, FailedPasswordAttemptCount, FailedPasswordAttemptWindowStart, FailedPasswordAnswerAttemptCount, 
FailedPasswordAnswerAttemptWindowStart, Comment, SessionID, DefaultModuleId, UserTypeId, DepartmentId
, EnglishName, ArabicName, GenderID, CountryID, EmployeeID, BranchID, SecurityLevelID, case when IsActive=1 then 'Active' else 'Not Active' End as IsActive,cost.Name AS DepName ,LanguageID
