/****** Object:  StoredProcedure [dbo].[UserPermissions]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[UserPermissions]

	@UserId nvarchar(255)
as

    WITH EXPL (ParentId, id, name,PrivilegeId,ItemCategory,UltimateParentName) AS

     (
      SELECT ROOT.ParentId, ROOT.id, ROOT.Name,PrivilegeId,ItemCategory, ROOT.Name as UltimateParentName

      FROM   ApplicationPrivileges   ROOT

      WHERE  isnull(ROOT.ParentId,0) = 0

 

      UNION ALL

 

      SELECT CHILD.ParentId, CHILD.id, CHILD.Name,CHILD.PrivilegeId,CHILD.ItemCategory,PARENT.UltimateParentName

      FROM   EXPL PARENT, ApplicationPrivileges CHILD

      WHERE  PARENT.id = CHILD.ParentId

     )

  SELECT EXPL.id, EXPL.name
		, AspNetUsers.UserName, EXPL.ParentId, EXPL.ItemCategory,
	   EXPL.UltimateParentName
		,case EXPL.ItemCategory when 1 then 'defind' when 2 then 'Transact' when 3 then 'Report' end as  ItemCategoryName
		
		  FROM AspNetUserRoles INNER JOIN
			   AspNetUsers ON AspNetUserRoles.UserId = AspNetUsers.Id INNER JOIN
			   AspNetRoles ON AspNetUserRoles.RoleId = AspNetRoles.Id INNER JOIN
