/****** Object:  StoredProcedure [Emergency].[DoctorsScheduleAr]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   procedure [Emergency].[DoctorsScheduleAr]

@DoctorID int Null
AS
BEGIN

	SELECT 
		   D.Code        as 'الكود',
	       D.Id          as 'رقم الطبيب', 
		   D.NameAr      as 'اسم الطبيب',
		   FORMAT (cast(RS.StartTime as datetime2(7)) , 'HH:mm:ss ') AS 'وقت البداية',
		   FORMAT (cast(RS.EndTime as datetime2(7)) , 'HH:mm:ss ')   AS 'وقت النهاية',
		   
			CASE ES.DayID
			WHEN 1 THEN N'السبت'
			WHEN 2 THEN N'الأحد'
			WHEN 3 THEN N'الاثنين'
			WHEN 4 THEN N'الثلاثاء'
			WHEN 5 THEN N'الأربعاء'
			WHEN 6 THEN N'الخميس'
			ELSE N'الجمعة'
	        END AS 'اليوم'

	FROM Registration.Doctors as D 
	inner join Emergency.EmergencySchedule ES on ES.DoctorID = D.Id
	inner join Registration.Sessions RS on RS.Id = ES.SessionId

	where (@DoctorID is null or @DoctorID = ES.DoctorID) 

END

GO
