	count(case when emergencyU.SeenDateTime is not null then emergencyU.PatientID end) as SeenListCount,
	count(case when admit.EmergencyUnitID > 0 and	admit.DischargeStatusId=1 then admit.Id end) as AdmitI_PCount,
	 CASE
    WHEN ERcode=1 THEN 'Red'
    WHEN ERcode=2 THEN 'Orange'
    WHEN ERcode=3 THEN 'Yellow'
	WHEN ERcode=4 THEN 'Green'
	WHEN ERcode=5 THEN 'White'
  END as StatusName
	 -- VisitNo
	FROM Emergency.EmergencyUnit as emergencyU
	left join InPatient.AdmitPatients as admit on admit.EmergencyUnitID=emergencyU.ID
	
  where emergencyU.Date between @DateFrom and @DateTo
	group by  CASE
    WHEN ERcode=1 THEN 'Red'
    WHEN ERcode=2 THEN 'Orange'
    WHEN ERcode=3 THEN 'Yellow'
	WHEN ERcode=4 THEN 'Green'
	WHEN ERcode=5 THEN 'White'
  END 
  END 
