/****** Object:  StoredProcedure [Emergency].[MortalityRateRep]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [Emergency].[MortalityRateRep] 

@type nvarchar(50) null,
@FromDate datetime null,
@Todate datetime null
as
begin
if(@type='Speciality')
select @type, count(PatientID) patientCount,sp.Name ,(
select count(PatientID)  from   Emergency.EmergencyUnit deth
where deth.SpecialityID= EmergencyUnit.SpecialityID and deth.PatientStatusID=4
) patientDCount 

 from   Emergency.EmergencyUnit  
join OutPatient.SpecialityGroupDetails sp on EmergencyUnit.SpecialityID = sp.ID


where 
(EmergencyUnit.Date >= convert(datetime,@FromDate,103) or @FromDate is null)
and 
(EmergencyUnit.Date  < convert(datetime,@Todate,103) or @Todate is null)

group by sp.Name ,EmergencyUnit.SpecialityID

else

select @type, count(PatientID) patientCount,sp.Name  ,(
select count(PatientID)  from   Emergency.EmergencyUnit deth
where deth.DoctorID= EmergencyUnit.DoctorID and deth.PatientStatusID=4
) patientDCount 

 from   Emergency.EmergencyUnit  
join Registration.Doctors sp on EmergencyUnit.DoctorID = sp.ID


