CREATE procEDURE [Emergency].[RepEmergencyByArrivalTypeNoOfPATIENTS]
	@DateFrom datetime = null,
	@DateTo datetime = null,
	@ArrivalTypeID int null
  AS 
--SELECT 'NoOfPatients' AS ArrivalType,   
--  [0], [1], [2], [3], [4]  
--  --@ArrivalTypeID 
--FROM  
--(
--  SELECT ArrivalTypeID, patient.Id as id

--   from [Registration].[Patients] patient
--  inner join [Emergency].[EmergencyUnit] EmUnit on EmUnit.PatientID = patient.Id
--  inner join  [Emergency].[EmergencyDetails] EmergencyDetail on EmergencyDetail.PatientID =patient.Id
--  inner join [Emergency].[ComplainSetup] ComplainSet on ComplainSet.Id = EmUnit.ComplainID
--  inner join [Registration].[Doctors] Doct on Doct.Id = EmUnit.DoctorID
--  inner join [Emergency].[CasePriority] CasePriority on CasePriority.Id = EmUnit.CasePriortyID
--  where EmUnit.ArrivalTypeID=@ArrivalTypeID and EmUnit.[Date] between  	@DateFrom and 	@DateTo
--) AS SourceTable  
--PIVOT  
--(  
--  count(id  )  
-- --FOR ArrivalTypeID IN ([@ArrivalTypeID] )  
--  FOR ArrivalTypeID IN ([0], [1], [2], [3], [4])  
--) AS PivotTable ; 
	select distinct count(patient.Id ) as NoOfPatients,ISNULL([Emergency].[ArrivalType].ArrivalTypeDescEnglish,'Other') as ArrivalName
  from [Registration].[Patients] patient
  inner join [Emergency].[EmergencyUnit] EmUnit on EmUnit.PatientID = patient.Id
  inner join  [Emergency].[EmergencyDetails] EmergencyDetail on EmergencyDetail.PatientID =patient.Id
