/****** Object:  StoredProcedure [Emergency].[SP_GetEmergencyReport]    Script Date: 8/27/2026 2:35:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Emergency].[SP_GetEmergencyReport] 
(
@FromDate nvarchar(50),@ToDate nvarchar(50)
)

as

begin
SET NOCOUNT ON;

SELECT
         ISNULL(b.NameEn, 'Unknown Facility') AS Facility,

        p.FirstName + ' '
        + ISNULL(p.MiddleName1,'') + ' '
        + ISNULL(p.LastName,'') AS Patient,

        p.MobileNumber AS Mobile,
        p.Email AS Email,

        n.Name AS Nationality,

        idt.Name AS EID,

        p.PassportNumber AS Passport,

        sx.NameEn AS Gender,

        Convert(Date,p.DateOfBirth) as DateOfBirth,
        p.Age,

        p.City AS EmirateResidence,

        p.Address,
        p.Occupation,

        p.SocialEconomicStatus AS PeopleDetermination,

      
     CASE eu.EncounterType
      WHEN 1 THEN 'No Bed - No Emergency Room'
      WHEN 2 THEN 'No Bed - Emergency Room'
      WHEN 3 THEN 'Inpatient Bed - No Emergency Room'
      WHEN 4 THEN 'Inpatient Bed - Emergency Room'
      WHEN 5 THEN 'Daycase Bed - No Emergency Room'
      WHEN 6 THEN 'Daycase Bed - Emergency Room'
      WHEN 7 THEN 'Nationals Screening'
      WHEN 8 THEN 'New Visa Screening'
      WHEN 9 THEN 'Renewal Visa Screening'
      WHEN 10 THEN 'Pre-OP Test Procedures'
      WHEN 11 THEN 'Home'
      ELSE 'Unknown'
      END AS  VisitType,

		CONVERT(Date,ed.VisiteDate) AS VisitDate,
         
        FORMAT(ed.VisiteDate, 'hh:mm tt') AS VisitTime,

        FORMAT(p.RegistrationDate, 'hh:mm tt') AS RegistrationTime,


