CREATE procedure [Emergency].[SP_NormalAndFastEmergencyReport]
@patientId int null
as
select [Emergency].[NormalEmergancy].[ERCode]
, [Registration].[Patients].FirstName +' '+[Registration].[Patients].MiddleName1+' '+[Registration].[Patients].MiddleName2+' '+
[Registration].[Patients].LastName, [Pharmacy].OtherHospitals.HospitalName,[Registration].Doctors.Name,[Emergency].[NormalEmergancy].PaymentMethodID
from [Emergency].[NormalEmergancy]
join [Registration].[Patients] on [Emergency].[NormalEmergancy].patientID = [Registration].[Patients].Id
join [Pharmacy].OtherHospitals on  [Emergency].[NormalEmergancy].CameFrom = [Pharmacy].OtherHospitals.Id
join [Registration].Doctors on  [Emergency].[NormalEmergancy].DoctorID = [Registration].Doctors.Id
where ([Emergency].[NormalEmergancy].patientID=@patientId or @patientId is null)
union all   
select  [Emergency].FastEmergancy.[ERCode]
, [Registration].[Patients].FirstName +' '+[Registration].[Patients].MiddleName1+' '+[Registration].[Patients].MiddleName2+' '+
[Registration].[Patients].LastName, [Pharmacy].OtherHospitals.HospitalName,[Registration].Doctors.Name,Emergency.FastEmergancy.PaymentMethodID
from [Emergency].FastEmergancy
join [Registration].[Patients] on [Emergency].FastEmergancy.patientID = [Registration].[Patients].Id
join [Pharmacy].OtherHospitals on  [Emergency].FastEmergancy.ComeFrom = [Pharmacy].OtherHospitals.Id
join [Registration].Doctors on  [Emergency].FastEmergancy.DoctorID = [Registration].Doctors.Id 
where ([Emergency].FastEmergancy.patientID =@patientId or @patientId is null)





GO
