CREATE procEDURE [Emergency].[SP_NormalEmergancy_Report]


AS
Select
NormalEmergancy.ERCode,
patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
OtherHospitals.HospitalName,NormalEmergancy.PaymentMethodID,Doctors.Name
from Emergency.NormalEmergancy as NormalEmergancy
join Registration.Patients as patient on NormalEmergancy.PatientId=patient.Id
