CREATE procEDURE [Finance].[SP_BSP_PostEntry]
 @EntryTP nvarchar(50)
,@EntryDate datetime
,@RfndAcc nvarchar(50)
,@CloseAcc nvarchar(50)
,@SubACC real
,@BSP_Iata nvarchar(10) 
,@USR_C nvarchar(10) = null
AS
BEGIN
declare @MyReturn_Nu  varchar(50)
BEGIN TRY

	BEGIN TRANSACTION
	Declare @Flag nvarchar(20);
	Declare @ID int;
	Print('-------------START------------')
	select top 1 @ID = ID From ENTRY_TP Where JRN_TYP = @EntryTP order by ID desc	
	Print('-------------ID------------')
	Print(@ID)
	Print '--------------------------------------------------------------------'
	Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2100'
	Print('------------- Flag ------------')
	Print(@Flag)
	Print '--------------------------------------------------------------------'

	--IF SUBSTRING( @Flag,5,1) = '-' 
	--	select Max(JRN_NU)+1 From JOURNAL Where Year(JRN_DATE) > Year(@EntryDate)-1 AND JRN_TYP = @ID
	--else IF SUBSTRING( @Flag,5,1) = 'M' 
	--	select Max(JRN_NU)+1 From JOURNAL Where Year(JRN_DATE) = Year(@EntryDate) AND Month(JRN_DATE) = Month(@EntryDate) AND JRN_TYP = @ID
	--else 
	--	select Max(JRN_NU)+1 From JOURNAL Where Year(JRN_DATE) = Year(@EntryDate) AND Month(JRN_DATE) = Month(@EntryDate) 


	-- Delete From Journal ------------ Wait
		Declare @JRN_NU real
		Declare @AIR_COMP real
		Select @JRN_NU = (case when SUBSTRING( @Flag,5,1) = '-' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) > Year(@EntryDate)-1 AND JRN_TYP = @ID)
			 when SUBSTRING( @Flag,5,1) = 'M' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) = Year(@EntryDate) AND Month(JRN_DATE) = Month(@EntryDate) AND JRN_TYP = @ID)
ਊऀऀऀ 攀氀猀攀 ⠀猀攀氀攀挀琀 䴀愀砀⠀椀猀渀甀氀氀⠀䨀刀一开一唀Ⰰ　⤀⤀⬀㄀ 䘀爀漀洀 䨀伀唀刀一䄀䰀 圀栀攀爀攀 夀攀愀爀⠀䨀刀一开䐀䄀吀䔀⤀ 㴀 夀攀愀爀⠀䀀䔀渀琀爀礀䐀愀琀攀⤀ 䄀一䐀 䴀漀渀琀栀⠀䨀刀一开䐀䄀吀䔀⤀ 㴀 䴀漀渀琀栀⠀䀀䔀渀琀爀礀䐀愀琀攀⤀ ⤀ഀ਀ऀऀऀ 攀渀搀⤀ऀഀ਀ऀऀ椀昀 ऀ䀀䨀刀一开一唀 椀猀 一甀氀氀  匀攀琀 䀀䨀刀一开一唀 㴀 ㄀ ഀ਀ऀऀ倀爀椀渀琀⠀✀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ䨀刀一开一唀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ✀⤀ഀ਀ऀऀ倀爀椀渀琀⠀䀀䨀刀一开一唀⤀ഀ਀ऀऀ倀爀椀渀琀 ✀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ✀ഀ਀ऀऀ倀爀椀渀琀 ✀匀琀愀爀琀 䤀渀猀攀爀琀 䤀渀琀漀 䨀漀甀爀渀愀氀✀ഀ਀ऀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ䨀伀唀刀一䄀䰀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀഀ਀ऀ䤀一匀䔀刀吀 䤀一吀伀 樀漀甀爀渀愀氀⠀䨀刀一开吀夀倀Ⰰ䨀刀一开一唀Ⰰ䨀刀一开䐀䄀吀䔀Ⰰ䨀刀一开唀匀䔀刀Ⰰ匀夀匀开䐀䄀吀䔀Ⰰ匀夀匀开吀䤀䴀䔀Ⰰ䨀刀一开䐀䔀匀⤀ഀ਀ऀऀ匀攀氀攀挀琀 ഀ਀ऀऀ䀀䤀䐀Ⰰഀ਀ऀऀ䀀䨀刀一开一唀ऀⰀഀ਀ऀऀ䀀䔀渀琀爀礀䐀愀琀攀Ⰰഀ਀ऀऀ⠀猀攀氀攀挀琀 䌀吀刀䰀⸀唀匀䔀刀䤀䐀 昀爀漀洀 䌀吀刀䰀 圀栀攀爀攀 唀匀䔀刀一䄀䴀䔀㴀 䀀唀匀刀开䌀⤀ഀ਀ऀऀⰀ ⴀⴀ 圀䄀䤀吀ഀ਀ऀऀ挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ 最攀琀搀愀琀攀⠀⤀Ⰰ ㄀　㄀⤀ 愀猀 匀夀匀开䐀䄀吀䔀Ⰰഀ਀ऀऀ匀唀䈀匀吀刀䤀一䜀⠀ 挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ 最攀琀搀愀琀攀⠀⤀Ⰰ ㄀　㠀⤀Ⰰ㄀Ⰰ㔀⤀ 愀猀 匀夀匀开吀䤀䴀䔀Ⰰഀ਀ऀऀ匀唀䈀匀吀刀䤀一䜀⠀✀⨀䔆 ─⼆⸆✆䐆䜆 ⠀䠆㌆㜆⤆ ✀䐆䀆 䈀匀倀✀Ⰰ㄀Ⰰ㄀　　⤀ഀ਀ऀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ 䤀渀猀攀爀琀 䔀渀琀爀礀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀഀ਀ऀऀ匀攀氀攀挀琀 䀀䄀䤀刀开䌀伀䴀倀 㴀 䄀䤀刀开䌀伀䴀倀 䘀爀漀洀  匀夀匀开䐀䄀吀䄀ഀ਀ऀऀ倀爀椀渀琀⠀✀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ䄀䤀刀开䌀伀䴀倀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ✀⤀ഀ਀ऀऀ倀爀椀渀琀⠀䀀䄀䤀刀开䌀伀䴀倀⤀ഀ਀ऀऀ倀爀椀渀琀 ✀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ✀ഀ਀ऀऀ倀爀椀渀琀 ✀匀琀愀爀琀 䤀渀猀攀爀琀 䤀渀琀漀 䔀渀琀爀礀✀ഀ਀ऀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀ 䐀攀氀攀琀攀 䘀爀漀洀 䔀渀琀爀礀 䈀礀 䨀爀渀开䤀䐀 㼀㼀 圀愀椀琀ऀऀഀ਀ऀऀ椀一匀䔀刀吀 椀一吀伀 攀一吀刀夀⠀䨀刀一开䤀䐀Ⰰ䄀䌀䌀开一唀Ⰰ匀唀䈀开一唀Ⰰഀ਀ऀऀऀऀऀऀ䌀唀刀开一唀Ⰰ䔀一吀开刀䔀䌀㄀Ⰰ䔀一吀开刀䔀䌀㈀Ⰰഀ਀ऀऀऀऀऀऀ䔀一吀开䌀伀一嘀Ⰰ䔀一吀开䐀刀Ⰰ䔀一吀开䌀刀Ⰰ䔀一吀开䐀䔀匀Ⰰഀ਀ऀऀऀऀऀऀ䔀一吀开䘀䰀䜀Ⰰ䔀一吀开刀䔀䌀㌀Ⰰ䔀一吀开刀䔀䐀㌀Ⰰ䔀一吀开刀䔀䐀㐀⤀ऀഀ਀ऀऀ猀攀氀攀挀琀 ഀ਀ऀऀ䨀刀一开䤀䐀Ⰰഀ਀ऀऀऀऀऀऀऀⴀⴀ䌀愀猀攀 圀栀攀渀 猀甀洀⠀吀䬀吀开吀伀吀⤀ 㸀 　 琀栀攀渀 ഀ਀ऀऀ䀀䄀䤀刀开䌀伀䴀倀ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀氀猀攀 䀀刀昀渀搀䄀挀挀ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀渀搀 ഀ਀ऀऀⰀഀ਀ऀऀ䌀䄀匀吀 ⠀吀䴀倀开䈀匀倀⸀䄀䤀刀开䌀伀䴀倀 䄀猀 爀攀愀氀⤀Ⰰഀ਀ऀऀ㄀Ⰰഀ਀ऀऀ✀✀Ⰰഀ਀ऀऀ✀✀Ⰰഀ਀ऀऀ　Ⰰഀ਀ऀऀऀऀऀऀऀⴀⴀ䌀愀猀攀 圀栀攀渀 猀甀洀⠀吀䬀吀开吀伀吀⤀ 㸀 　 琀栀攀渀ഀ਀ऀऀ 愀戀猀⠀猀甀洀⠀吀䬀吀开吀伀吀⤀⤀ऀⴀⴀ猀甀洀⠀䄀䤀刀开䌀伀䴀䴀⤀ⴀ猀甀洀⠀䄀䤀刀开䌀伀䴀吀⤀⤀ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀氀猀攀 　ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀渀搀ഀ਀ऀऀⰀഀ਀ऀऀऀऀऀऀऀⴀⴀ䌀愀猀攀 圀栀攀渀 猀甀洀⠀吀䬀吀开吀伀吀⤀ 㸀 　 琀栀攀渀ഀ਀ऀऀ 　ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀氀猀攀 愀戀猀⠀猀甀洀⠀吀䬀吀开吀伀吀⤀ⴀ猀甀洀⠀䄀䤀刀开䌀伀䴀䴀⤀ⴀ猀甀洀⠀䄀䤀刀开䌀伀䴀吀⤀ⴀ匀唀䴀⠀䄀䤀刀开刀䘀⤀⤀ഀ਀ऀऀऀऀऀऀऀⴀⴀ攀渀搀ഀ਀ऀऀⰀഀ਀ऀऀ匀唀䈀匀吀刀䤀一䜀⠀✀⨀䔆 ─⼆⸆✆䐆䜆 ⠀䠆㌆㜆⤆ ✀䐆䀆 䈀匀倀✀Ⰰ㄀Ⰰ㄀　　⤀Ⰰഀ਀ऀऀ✀✀Ⰰഀ਀ऀऀ✀✀Ⰰഀ਀ऀऀ✀　㄀⼀　㄀⼀㄀㤀㤀　✀Ⰰഀ਀ऀऀ✀　㄀⼀　㄀⼀㄀㤀㤀　✀ഀ਀ऀऀ䘀爀漀洀 吀䴀倀开䈀匀倀 䤀渀渀攀爀 䨀漀椀渀 䨀伀唀刀一䄀䰀 伀渀 䨀刀一开䐀䄀吀䔀 㴀 䀀䔀渀琀爀礀䐀愀琀攀 䄀一䐀 䨀刀一开一唀 㴀 䀀䨀刀一开一唀 䄀一䐀 䨀刀一开吀夀倀 㴀 䀀䤀䐀ഀ਀ऀऀ圀栀攀爀攀 唀匀刀开䌀 㴀䀀唀匀刀开䌀 愀渀搀 ⠀吀䬀吀开吀夀倀 㴀 ✀䤀猀猀甀攀✀ 伀刀 吀䬀吀开吀夀倀 㴀 ✀刀攀䤀猀猀甀攀✀ 伀刀 吀䬀吀开吀夀倀 㴀 ✀䔀䴀䐀✀ 伀爀 吀䬀吀开吀夀倀 㴀 ✀䄀䐀䴀✀ 伀刀 ⠀吀䬀吀开吀夀倀 㴀 ✀嘀漀椀搀✀ 䄀一䐀 吀䬀吀开吀伀吀 㰀㸀 　 䄀渀搀 吀䬀吀开吀伀吀 䤀匀 一伀琀 一甀氀氀⤀⤀ 䄀渀搀 吀䴀倀开䈀匀倀⸀䄀䤀刀开䤀䄀吀䄀 㴀 䀀䈀匀倀开䤀愀琀愀ഀ਀
		Group By AIR_COMP ,JRN_ID

		iNSERT iNTO eNTRY(JRN_ID,ACC_NU,SUB_NU,
						CUR_NU,ENT_REC1,ENT_REC2,
						ENT_CONV,ENT_DR,ENT_CR,ENT_DES,
						ENT_FLG,ENT_REC3,ENT_RED3,ENT_RED4)	
		select 
		JRN_ID,
		@RfndAcc	
		,
		CAST (TMP_BSP.AIR_COMP As real),
		1,
		'',
		'',
		0,
		0
		,
		abs(sum(TKT_TOT))--sum(AIR_COMM)-sum(AIR_COMT)-SUM(AIR_RF))		
		,
		SUBSTRING('تم إدخاله بوسطة الـ BSP',1,100),
		'',
		'',
		'01/01/1990',
		'01/01/1990'
		From TMP_BSP Inner Join JOURNAL On JRN_DATE = @EntryDate AND JRN_NU = @JRN_NU AND JRN_TYP = @ID
		Where  USR_C =@USR_C and (TKT_TYP = 'Refund' OR TKT_TYP = 'ACM') And TMP_BSP.AIR_IATA = @BSP_Iata
		Group By AIR_COMP ,JRN_ID
	------------------------------Final Entry-----------------------------------------------------------
		Print 'Start Insert Into Final Entry'
		iNSERT iNTO eNTRY(JRN_ID,ACC_NU,SUB_NU,
						CUR_NU,ENT_REC1,ENT_REC2,
						ENT_CONV,ENT_DR,ENT_CR,ENT_DES,
						ENT_FLG,ENT_REC3,ENT_RED3,ENT_RED4)
		select ENTRY.JRN_ID,@CloseAcc,@SubACC,1,'','',0,
		Case When (sum(ISNULL(ENT_DR,0))-sum(ISNULL(ENT_CR,0))) > 0 then 
		0
		else abs(sum(ISNULL(ENT_DR,0))-sum(ISNULL(ENT_CR,0)))
		end,
		Case When (sum(ISNULL(ENT_DR,0))-sum(ISNULL(ENT_CR,0))) < 0 then 
		0
		else abs(sum(ISNULL(ENT_DR,0))-sum(ISNULL(ENT_CR,0)))
		end,
		SUBSTRING('تم إدخاله بوسطة الـ BSP',1,100),'','','01/01/1990','01/01/1990'
		From JOURNAL Inner Join ENTRY ON ENTRY.JRN_ID = JOURNAL.JRN_ID AND JRN_DATE = @EntryDate AND JRN_NU = @JRN_NU AND JRN_TYP = @ID 
		Group By ENTRY.JRN_ID			
	Print ''
		COMMIT TRAN
		-- ReturnValue
		set @MyReturn_Nu =cast(@JRN_NU as varchar(20))
		set @MyReturn_Nu='S' +@MyReturn_Nu
		select 1
		--print @MyReturn_Nu
	END TRY
BEGIN CATCH
	IF @@TRANCOUNT > 0
		print 'rollback'
		ROLLBACK TRAN --RollBack in case of Error
		 declare @SYS_DATE datetime 
		declare @SYS_TIME varchar(5) 
		set @SYS_DATE=convert(varchar(10), getdate(), 110)
		set @SYS_TIME=CONVERT(VARCHAR(5),getdate(),108)
		insert into [SYS_ERR](  ERR_DATE, ERR_TIME, ERR_MSG, PRG_CODE)
		values( @SYS_DATE, @SYS_TIME,ERROR_MESSAGE(),'SP_BSP_PostEntry')  
		SELECT -1  
		
END CATCH
