栀愀琀夀攀愀爀  昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀倀爀攀吀栀愀琀夀攀愀爀  昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀吀栀愀琀䴀漀渀琀栀  昀氀漀愀琀ഀ਀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀夀开䄀䌀吀开夀开䴀 昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀夀䈀䐀䜀开夀开䴀 昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀礀䄀䌀吀开倀开夀开䴀 昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀礀䄀䌀吀开夀吀伀开䴀 昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀礀䈀䐀䜀开夀吀伀开䴀 昀氀漀愀琀ഀ਀䐀䔀䌀䰀䄀刀䔀 䀀䴀礀䄀䌀吀开倀开夀吀伀开䴀 昀氀漀愀琀ഀ਀
DECLARE @MyField varchar(500)
DECLARE @MyRound int
DECLARE @BDG_LIN int
declare @Value float
declare @MyStr nvarchar(4000)
DECLARE @BDG_ORD1 int
declare  @OriginalEquation varchar(200)
set @ThatYear = @BDG_YEAR
set @PreThatYear = @BDG_YEAR - 1

set @ThatMonth = @BDG_MONTH

if @MyTmpVarString='1'
	begin 
		set @MyTmpVarString= ' * Values are in real'
		set @MyRound=1
	end

else if @MyTmpVarString='10' 
	begin 
		set @MyTmpVarString= ' * Values are in tens'
		set @MyRound=10
	end
else if @MyTmpVarString='100' 
	begin 
		set @MyTmpVarString= ' * Values are in hundreds'
		set @MyRound=100
	end

else
	begin 
		set @MyTmpVarString= ' * Values are in thousands'
		set @MyRound=1000
	end

 -- Delete statements for procedure here
    delete  FROM TMP_BDG_ENT WHERE USR_C=@USR_C
	delete  FROM TMP_ACCO1350 WHERE USR_C=@USR_C
	--DELETE FROM TMP_BDG WHERE USR_C=@USR_C
	
	DECLARE tLINE_NO_cursor CURSOR FOR    
	SELECT distinct BDG_ACC_ID    FROM BDG_ACC  where  BDG_YEAR=@BDG_YEAR  AND BDG_CODE=@BDG_CODE

	
	OPEN tLINE_NO_cursor  DECLARE @LINE_NO [real]  

	FETCH NEXT FROM tLINE_NO_cursor INTO @LINE_NO
	WHILE (@@FETCH_STATUS <> -1) 
	BEGIN  
		--'Get MyData
	    SELECT @BDG_ORD=BDG_ORD ,@ACC_NU=ACC_NU,@sub_NU=sub_NU,@BDG_LIN=BDG_LIN   FROM BDG_ACC  where   BDG_ACC_ID=@LINE_NO
	    insert INTO TMP_BDG_ENT ( USR_C, JRN_DATE, BDG_YEAR, BDG_CODE, BDG_LIN, BDG_ORD, ACC_NU, ACC_NU_C, SUB_NU, SUB_NU_C, JRN_TYP, DR_CR
)
	    SELECT  @USR_C as usr_c,  JRN_DATE  as JRN_DATE ,
	            @BDG_YEAR AS BDG_YEAR, @BDG_CODE AS BDG_CODE, 
	            @BDG_LIN AS BDG_LIN, @BDG_ORD AS BDG_ORD,
	             @ACC_NU AS ACC_NU, @ACC_NU AS ACC_NU_C, 
	             @sub_NU AS SUB_NU, @sub_NU AS SUB_NU_C
	             ,JOURNAL.JRN_TYP as JRN_TYP,isnull(SUM(isnull(ENT_DR,0) - isnull(ENT_CR,0)),0) AS DR_CR    
	     FROM         ENTRY INNER JOIN
                      JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID INNER JOIN
                      ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID 
	     
	     where ACC_NU =  @ACC_NU   AND   ( SUB_NU =@sub_NU  or @sub_NU  is null )   
	     AND  year(jrn_date) in(@PreThatYear,@BDG_YEAR ) GROUP BY JRN_DATE, JOURNAL.JRN_TYP
		
		
