						declare @counter int = 1	
						set @MyField=''
						While(@counter<= @ThatMonth)
						Begin
						if @counter <> 1													
						Begin
							set @MyField = @MyField + '+'
						End
							set @MyField = @MyField + 'ISNULL(E1.BDJ_'+ cast(@counter as varchar(2))+',0)'
							SET @counter = @counter+1
						End		
						PRINT @MyField
						



						set @MyStr='SELECT @out_param = isnull(SUM('+ @MyField + '),0) 
							  
											FROM BDG_ACC b LEFT OUTER JOIN  BUDJET E1 
											ON b.BDG_YEAR = E1.BDJ_YEAR 
											AND E1.ACC_NU = b.ACC_NU 
											
											Where   BDG_YEAR= '+ cast(@BDG_YEAR as varchar(4)) + ' AND BDG_CODE= ''' + cast(@BDG_CODE as varchar(50)) + '''
												AND BDG_LIN= ' + cast(@LINE_NO2 as varchar(10)) + ' AND BDG_ORD= ' + cast(@BDG_ORD1 as varchar(10)) +' AND E1.ACC_NU= '+ cast(@MyACC_NU as varchar(10))  +'
												AND  ((  E1.SUB_NU= ' + isnull(cast(@MySub_NU as varchar(10)),'null') +'  or '+ isnull(cast(@MySub_NU as varchar(10)),'null')  +' is null)  ) 
												and (  E1.SUB_NU = b.SUB_NU or b.SUB_NU is null)
												'										

							Print '---------------Error------------------------'
							Print 'BDG_CODE'
							Print @BDG_CODE
							Print @LINE_NO2
							print @BDG_ORD1
							print @MyACC_NU
							print @MySub_NU
							Print '----------------------------------------------'
							PRINT @MyStr
								EXEC sp_executesql @MyStr,
												   N'@out_param dec(18,2) OUTPUT',
