					Declare @Equation nvarchar(50) 
					declare @MyOrgQuery varchar(4000)
begin try
					set @BDG_Y_M = 0
					set @ACT_Y_M = 0
					set @ACT_P_Y_M = 0
					set @BDG_YTO_M = 0
					set @ACT_YTO_M = 0
					set @ACT_P_YTO_M = 0

					select @ROW_ORD=ROW_ORD ,@BDG_TTLLin =BDG_TTL from BDG_LINE WHERE    BDG_YEAR=@BDG_YEAR and BDG_CODE=@BDG_CODE and BDG_LIN=@LINE_NO3 and BDG_REP IN ('Y','y')
					
					SELECT @OriginalEquation=BDG_Eqt from BDG_Eqt WHERE    BDG_YEAR=@BDG_YEAR and BDG_CODE=@BDG_CODE and BDG_LIN=@LINE_NO3 
					
					--'***************************************
					--'get my totals
					set @OriginalEquation =replace(@OriginalEquation,' ','')					
					set @Equation = @OriginalEquation

					SET @end = PATINDEX('%[^0-9]%', @Equation)
					Set @Query = 'Select  @out_param=Isnull((Select Isnull(BDG_Y_M,0) From TMP_ACCO1350 Where  USR_C = '''+@USR_C+''' and  BDG_LIN = ' + SUBSTRING(@OriginalEquation,1,@end-1)+')'+SUBSTRING(@OriginalEquation,@end,1);

					WHILE @end > @start
					BEGIN
						IF @end = LEN(@Equation)+1
						Begin		
							break
						End	
						SET @Equation = STUFF(@Equation, @end, 1, '0')	
						Set @start = @end
						SET @end = PATINDEX('%[^0-9]%', @Equation)	
						If @end < @start
						BEGIN
							set	@end = LEN(@Equation)+1
							Set @Query = @Query + ' (Select Isnull(BDG_Y_M,0) From TMP_ACCO1350 Where USR_C = '''+@USR_C+''' and BDG_LIN = ' + SUBSTRING(@OriginalEquation,@start+1,@end-@start)+'),0)'
						END	
						ELSE
							Set @Query = @Query + ' (Select Isnull(BDG_Y_M,0) From TMP_ACCO1350 Where USR_C = '''+@USR_C+''' and BDG_LIN = ' + SUBSTRING(@OriginalEquation,@start+1,@end-@start-1)+')'+SUBSTRING(@OriginalEquation,@end,1)	
					end
					set @MyOrgQuery=@Query
					Print '-------------------------------------- Start Test %'
					Print 'Test %'
					Print @Query
					
					begin try
					set @Query=replace(@Query,'%','*100/')					
					EXEC sp_executesql @Query,N'@out_param dec(18,2) OUTPUT', @out_param=@BDG_Y_M OUTPUT
					end try
					begin catch	
					set @BDG_Y_M = 0;
					end catch
					
					begin try
