CREATE procEDURE [Finance].[SPACCO2020]
		@USR_C varchar(10)
  , @TransDate datetime
  , @TransNo float = null
  , @TransType int = null

AS
BEGIN

	delete from  TMP_ACCO2020 where USR_C=  @USR_C 
	insert into TMP_ACCO2020

	SELECT  @USR_C ,
		ENTRY_20.Entry_20_ID,
		ENTRY_20.JRN_DATE, 
		ENTRY_20.JRN_NU, 
		ENTRY_20.ACC_NU, 
		ENTRY_20.SUB_NU, 
		ENTRY_20.CUR_NU, 
		ENTRY_20.VECHILE_REG_NO, 
		ENTRY_20.ENT_CUST_NAME, 
		ENTRY_20_DETAILS.CST_NU, 
		ENTRY_20_DETAILS.ENT_OPR, 
		ENTRY_20_DETAILS.ENT_DES, 
		ENTRY_20_DETAILS.ENT_AMT, 
		ENTRY_20_DETAILS.COST_NU, 
		ENTRY_20_DETAILS.ENT_STR, 
		ENTRY_20_DETAILS.ENT_END, 
		ENTRY_20_DETAILS.ENT_STARTING_TIME, 
		ENTRY_20_DETAILS.ENT_ENDING_TIME,
		MAIN_ACC.ACC_NM_A, 
		MAIN_ACC.ACC_NM_E, 
		SUB_ACC_1.SUB_NM_A, 
		SUB_ACC_1.SUB_NM_E, 
		CUR_CODE.CUR_NAME
		
