-- Check if have transactions 
	IF EXISTS (SELECT * FROM TMP_ACCO2200 WHERE USR_C = @USR_C )
	BEGIN
	  PRINT 'Do nothing.';
	END
	ELSE
	BEGIN
	  	
	insert into tmp_acco2200 
		(
		USR_C,CompanyName, CASH_NU,CASH_NAME,
		JRN_DATE, ENT_DES , ENT_BAL, Debit , 
		Credit , ENT_REC1 , ENT_REC2  , checkValue , Advance
		)

		SELECT DISTINCT @USR_C AS USR_C,(SELECT  CO_NAMEE FROM Finance.SYS_PARA) AS CompanyName, 
		e10.CASH_NU as CASH_NU , CASH_NAME as CASH_NAME ,
		@date AS JRN_DATE, '' as ENT_DES , e10.ENT_BAL AS ENT_BAL , 0 AS Debit, 0 AS Credit, 
		'' AS ENT_REC1, '' AS ENT_REC2, 
		
		ISNULL((SELECT SUM(ISNULL(ENT_DR, 0)) AS Expr1 FROM ENTRY_10_REC AS e10rc WHERE (CASH_NU = e10.CASH_NU) AND (JRN_DATE <= e10.JRN_DATE) AND (ENT_CHECK IS NOT NULL) AND (ENT_CHECK <> '') AND  
                         -- Under Work By KHaled In 23-08-2015
                         
                         (NOT exists (SELECT ENT_CHECK,ENT_CHECK_BANK,ENT_CHECK_DATE FROM ENTRY_10_PAY AS e10p 
