CREATE procEDURE [Finance].[SPACCO2200C]
	-- Add the parameters for the stored procedure here
		@USR_C varchar(10)
		, @cash varchar(2)
		, @date DateTime

AS
BEGIN
/*
DECLARE @cash VARCHAR(2)
DECLARE @date DATETIME
SET @cash='na'
SET @date='01/07/2014'  

*/
delete from TMP_ACCO2200C where  USR_C=@USR_C

insert into TMP_ACCO2200C (USR_C, CASH_NU, CASH_NAME, ENT_REC1, JRN_DATE, ENT_DES, CUR_NU, CUR_NAME, ENT_DR, ENT_CHECK, ENT_CHECK_BANK, ENT_CHECK_DATE, ENT_DR_CONV, ENT_CR
							)
SELECT        @USR_C,e10rc.CASH_NU, CASH_NAME.CASH_NAME, e10rc.ENT_REC1, e10rc.JRN_DATE, e10rc.ENT_DES,
 CUR_CODE.CUR_NU, CUR_CODE.CUR_NAME, 
                         ISNULL(e10rc.ENT_DR, 0) AS ENT_DR, e10rc.ENT_CHECK, e10rc.ENT_CHECK_BANK,e10rc.ENT_CHECK_DATE, ISNULL(E10.ENT_DR, 0) AS ENT_DR_Conv,
                          E10.ENT_CR
FROM            ENTRY_10_REC AS e10rc INNER JOIN
                         ENTRY_10 AS E10 ON e10rc.CASH_NU = E10.CASH_NU AND e10rc.JRN_DATE = E10.JRN_DATE 
                         AND e10rc.ENT_REC1 = E10.ENT_REC1 INNER JOIN
                         CASH_NAME ON e10rc.CASH_NU = CASH_NAME.CASH_NU INNER JOIN
                         CUR_CODE ON CASH_NAME.CUR_NU = CUR_CODE.CUR_NU
WHERE        (e10rc.CASH_NU = @cash) AND (e10rc.JRN_DATE <= @date) AND (e10rc.RECEIPT_STATUS IS NULL OR
                         e10rc.RECEIPT_STATUS = '-') AND (e10rc.ENT_CHECK IS NOT NULL) AND (e10rc.ENT_CHECK <> '') AND (e10rc.ENTRY_10_REC_ID NOT IN
                             (SELECT        ENTRY_10_REC_ID
                                FROM            ENTRY_10_PAY AS e10p
                                WHERE      e10p.JRN_DATE <= @date and   (CASH_NU = e10rc.CASH_NU) AND (ENTRY_10_REC_ID IS NOT NULL) AND (RECEIPT_STATUS IS NULL OR
                                                         RECEIPT_STATUS = '-')))

	
END








GO
