GO

CREATE proc [Finance].[SPACCO2204_UPDATE] 
    @CASH_NU varchar(2),
    @JRN_DATE datetime, --'
    @ENT_11_AMT float = NULL, --UPDATED AMOUNT 
    @EMP_CODE VARCHAR(10),
	@ENT_11_DES VARCHAR(90),
	@ENT_11_ORG_AMT fLOAT
AS 
	BEGIN 
	declare @ENTRY_10_SER int = 1
	declare @ENT_LINE float
	declare @Serial int
	declare @NewDate datetime
	declare @ENT_BAL float
	
	declare @Sum_Debit as float
	declare @Sum_Credit as float

		set @ENTRY_10_SER= isnull((select max(ENTRY_10_SER) From ENTRY_10 Where Entry_10.CASH_NU = @CASH_NU  AND Entry_10.JRN_DATE =@JRN_DATE),1)
		set @ENT_LINE=isnull((select Max(ENT_LINE)+1 from ENTRY_10 Where CASH_NU = @CASH_NU AND JRN_DATE = @JRN_DATE ),1)
		set @NewDate = (select max(JRN_DATE) from ENTRY_10 where JRN_DATE < @JRN_DATE and CASH_NU = @CASH_NU)
		IF not EXISTS (SELECT * FROM ENTRY_10 WHERE CASH_NU = @CASH_NU AND JRN_DATE = @JRN_DATE )
		begin
			set @Sum_Debit =ISNULL((SELECT SUM(ISNULL( ENT_DR,0)) 
				FROM         ENTRY_10_REC
				WHERE     (CASH_NU = @CASH_NU) AND (JRN_DATE = @NewDate)  AND (RECEIPT_STATUS IS NULL OR  RECEIPT_STATUS = '-')),0)

	
			set @sum_Credit =ISNULL((SELECT SUM(ISNULL( ENT_CR,0)) 
				FROM         ENTRY_10_PAY
				WHERE     (CASH_NU = @CASH_NU) AND (JRN_DATE = @NewDate)  AND (RECEIPT_STATUS IS NULL OR  RECEIPT_STATUS = '-')),0)

			set @ENT_BAL =isnull((select max(ENT_BAL) from ENTRY_10 Where CASH_NU = @CASH_NU AND JRN_DATE = @NewDate ),0)	

			set @ENT_BAL=@Sum_Debit +@ENT_BAL -@sum_Credit
			

	
	INSERT INTO [ENTRY_10](CASH_NU ,JRN_DATE,ENTRY_10_SER,ENT_BAL,ENT_LINE)
