    --15--
	UPDATE [Finance].TMP_ACC3101G SET ENT_Balance = ISNULL(ENT_DR,0)-ISNULL(ENT_CR,0)
	WHERE  USR_C=@USR_C

	--16--
	UPDATE [Finance].TMP_ACC3101G SET ENT_CR =ISNULL(ENT_CR,0)/@conv , ENT_DR=ISNULL(ENT_DR,0)/@conv 
	WHERE USR_C=@USR_C

	--17--
	IF @ZeroBalanceAppear ='0'
	BEGIN
		--DELETE FROM TMP_ACC3101G WHERE USR_C=@USR_C  AND abs(ENT_CR- ENT_DR)<0.01 
		DELETE FROM [Finance].TMP_ACC3101G
		FROM            (SELECT        ACC_NU, SUB_NU
                           FROM            [Finance].TMP_ACC3101G AS TMP_ACC3101G_1
                           WHERE        (USR_C =@USR_C) 
                           GROUP BY  ACC_NU, SUB_NU
                           HAVING        abs((SUM(ENT_DR) - SUM(ENT_CR))) < 0.01) AS t INNER JOIN
                         [Finance].TMP_ACC3101G ON  t.ACC_NU = TMP_ACC3101G.ACC_NU AND t.SUB_NU = TMP_ACC3101G.SUB_NU
                      
      WHERE        (USR_C =@USR_C)             


	END
    

	 IF @NonInvoiceNo =1
	BEGIN
		DELETE FROM [Finance].TMP_ACC3101G
ਊऀ    圀䠀䔀刀䔀        ⠀唀匀刀开䌀 㴀䀀唀匀刀开䌀⤀ 愀渀搀 ⠀䔀渀琀开刀攀挀㌀㰀㸀✀　✀ 漀爀 䔀渀琀开刀攀挀㌀㰀㸀✀✀ ⤀ഀ਀ഀ਀ഀ਀ऀ䔀一䐀  ഀ਀ऀⴀⴀ㄀㠀ⴀⴀഀ਀ऀ搀攀氀攀琀攀 昀爀漀洀 嬀䘀椀渀愀渀挀攀崀⸀吀䴀倀开䄀䌀䌀㌀㄀　㄀ 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀 ഀ਀ऀ䤀一匀䔀刀吀 䤀一吀伀 嬀䘀椀渀愀渀挀攀崀⸀嬀吀䴀倀开䄀䌀䌀㌀㄀　㄀崀 ⠀ഀ਀ऀऀ嬀唀匀刀开䌀崀      Ⰰ嬀䌀漀洀瀀愀渀礀一愀洀攀崀      Ⰰ嬀䔀一吀开䌀伀一嘀崀      Ⰰ嬀䌀唀刀开一唀崀      Ⰰ嬀䌀唀刀开䌀伀䐀䔀崀ഀ਀      Ⰰ嬀琀礀瀀攀崀      Ⰰ嬀䘀爀漀洀䐀愀琀攀崀      Ⰰ嬀吀漀䐀愀琀攀崀      Ⰰ嬀䄀䌀䌀开一唀崀      Ⰰ嬀匀唀䈀开一唀崀      Ⰰ嬀䄀䌀䌀开一䴀开䄀崀ഀ਀      Ⰰ嬀䄀䌀䌀开一䴀开䔀崀      Ⰰ嬀匀唀䈀开一䴀开䄀崀      Ⰰ嬀匀唀䈀开一䴀开䔀崀      Ⰰ嬀搀愀琀攀崀      Ⰰ嬀樀爀渀渀漀崀      Ⰰ嬀䨀刀一开刀䔀䌀㌀崀Ⰰ䨀刀一开䌀䠀䬀ഀ਀      Ⰰ嬀搀猀㄀崀      Ⰰ嬀搀猀㈀崀      Ⰰ嬀䔀一吀开刀䔀䌀㄀崀      Ⰰ嬀䔀一吀开刀䔀䌀㈀崀      Ⰰ嬀䔀一吀开刀䔀䌀㌀崀ഀ਀      Ⰰ嬀搀攀戀椀琀崀      Ⰰ嬀挀爀攀搀椀琀崀      Ⰰ嬀䔀焀甀椀瘀崀      Ⰰ嬀䈀䘀漀爀眀漀爀搀搀攀戀椀琀崀      Ⰰ 嬀䈀䘀漀爀眀漀爀搀䌀爀攀搀椀琀崀ഀ਀      ഀ਀ऀ⤀ഀ਀ऀ匀䔀䰀䔀䌀吀  ഀ਀ऀऀ嬀唀匀刀开䌀崀Ⰰ✀✀Ⰰ嬀䔀一吀开䌀伀一嘀崀  Ⰰ吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀嬀䌀唀刀开一唀崀 Ⰰ䌀唀刀开䌀伀䐀䔀⸀䌀唀刀开䌀伀䐀䔀 ഀ਀ऀऀⰀ䔀一吀刀夀开吀倀⸀嬀䨀刀一开吀夀倀崀 Ⰰ䀀昀爀漀洀搀愀琀攀 䄀匀 䘀刀伀䴀开䐀䄀吀䔀Ⰰ䀀琀漀搀愀琀攀 䄀匀 吀伀开䐀䄀吀䔀ऀⰀ吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀嬀䄀䌀䌀开一唀崀Ⰰ吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀嬀匀唀䈀开一唀崀Ⰰ䤀匀一唀䰀䰀⠀䴀䄀䤀一开䄀䌀䌀⸀䄀䌀䌀开一䴀开䄀Ⰰ✀✀⤀Ⰰ䤀匀一唀䰀䰀⠀䴀䄀䤀一开䄀䌀䌀⸀䄀䌀䌀开一䴀开䔀Ⰰ✀✀⤀ഀ਀ऀऀⰀ䤀匀一唀䰀䰀⠀匀唀䈀开䄀䌀䌀⸀匀唀䈀开一䴀开䄀Ⰰ✀✀⤀Ⰰ䤀匀一唀䰀䰀⠀匀唀䈀开䄀䌀䌀⸀匀唀䈀开一䴀开䔀Ⰰ✀✀⤀Ⰰ嬀䨀刀一开䐀䄀吀䔀崀      Ⰰ嬀䨀刀一开一唀崀 Ⰰ䤀匀一唀䰀䰀⠀嬀䨀刀一开刀䔀䌀㌀崀Ⰰ✀✀⤀ 愀猀 嬀䨀刀一开刀䔀䌀㌀崀 Ⰰ䤀匀一唀䰀䰀⠀䨀刀一开䌀䠀䬀Ⰰ✀✀⤀ 愀猀 䨀刀一开䌀䠀䬀ഀ਀ऀऀⰀ吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀䨀刀一开䐀䔀匀 愀猀 嬀搀猀㄀崀Ⰰ嬀䔀一吀开䐀䔀匀崀  愀猀 嬀搀猀㈀崀ഀ਀ऀऀ Ⰰ䤀匀一唀䰀䰀⠀嬀䔀一吀开刀䔀䌀㄀崀Ⰰ✀✀⤀   Ⰰ䤀匀一唀䰀䰀⠀嬀䔀一吀开刀䔀䌀㈀崀Ⰰ✀✀⤀    Ⰰ䤀匀一唀䰀䰀⠀嬀䔀一吀开刀䔀䌀㌀崀Ⰰ✀✀⤀  Ⰰ嬀䔀一吀开䐀刀崀  Ⰰ刀伀唀一䐀⠀嬀䔀一吀开䌀刀崀Ⰰ㈀⤀Ⰰ 䔀一吀开䌀伀一嘀Ⰰ　 愀猀嬀䈀䘀漀爀眀漀爀搀搀攀戀椀琀崀 Ⰰ　 愀猀 嬀䈀䘀漀爀眀漀爀搀䌀爀攀搀椀琀崀ഀ਀ऀऀഀ਀ऀ䘀刀伀䴀         嬀䘀椀渀愀渀挀攀崀⸀䌀唀刀开䌀伀䐀䔀 䤀一一䔀刀 䨀伀䤀一ഀ਀                      嬀䘀椀渀愀渀挀攀崀⸀䴀䄀䤀一开䄀䌀䌀 䤀一一䔀刀 䨀伀䤀一ഀ਀                      嬀䘀椀渀愀渀挀攀崀⸀吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀 伀一 䴀䄀䤀一开䄀䌀䌀⸀䄀䌀䌀开一唀 㴀 吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀䄀䌀䌀开一唀 伀一 䌀唀刀开䌀伀䐀䔀⸀䌀唀刀开一唀 㴀 吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀䌀唀刀开一唀 䰀䔀䘀吀 伀唀吀䔀刀 䨀伀䤀一ഀ਀                      嬀䘀椀渀愀渀挀攀崀⸀匀唀䈀开䄀䌀䌀 伀一 吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀䄀䌀䌀开一唀 㴀 匀唀䈀开䄀䌀䌀⸀䄀䌀䌀开一唀 䄀一䐀 吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀匀唀䈀开一唀 㴀 匀唀䈀开䄀䌀䌀⸀匀唀䈀开一唀 ഀ਀                      䰀䔀䘀吀 伀唀吀䔀刀 䨀伀䤀一 嬀䘀椀渀愀渀挀攀崀⸀䔀一吀刀夀开吀倀 伀一 吀䴀倀开䄀䌀䌀㌀㄀　㄀䜀⸀䨀刀一开吀夀倀 㴀 䔀一吀刀夀开吀倀⸀䤀䐀ഀ਀                      ⴀⴀ䌀刀伀匀匀 䨀伀䤀一ഀ਀                      ⴀⴀ嬀䘀椀渀愀渀挀攀崀⸀匀夀匀开倀䄀刀䄀 ഀ਀ऀऀऀऀऀ  眀栀攀爀攀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀   ⴀⴀ㄀㤀ⴀⴀഀ਀   搀攀氀攀琀攀 昀爀漀洀 嬀䘀椀渀愀渀挀攀崀⸀吀䴀倀开䄀䌀䌀㌀㄀　㄀吀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀 ഀ਀   䤀一匀䔀刀吀 䤀一吀伀 嬀䘀椀渀愀渀挀攀崀⸀嬀吀䴀倀开䄀䌀䌀㌀㄀　㄀吀崀 ⠀ഀ਀ऀऀ嬀唀匀刀开䌀崀      Ⰰ嬀䌀漀洀瀀愀渀礀一愀洀攀崀      ഀ਀      Ⰰ嬀琀礀瀀攀崀      Ⰰ䔀砀瀀爀㄀     Ⰰ  䔀砀瀀爀㈀    Ⰰ嬀䄀䌀䌀开一唀崀      Ⰰ嬀匀唀䈀开一唀崀      Ⰰ嬀䄀䌀䌀开一䴀开䄀崀ഀ਀      Ⰰ嬀䄀䌀䌀开一䴀开䔀崀      Ⰰ嬀匀唀䈀开一䴀开䄀崀      Ⰰ嬀匀唀䈀开一䴀开䔀崀      Ⰰ嬀搀愀琀攀崀      Ⰰ嬀樀爀渀渀漀崀      Ⰰ嬀䨀刀一开刀䔀䌀㌀崀Ⰰ䨀刀一开䌀䠀䬀ഀ਀
      ,[ds1]      ,[ds2]      ,[ENT_REC1]      ,[ENT_REC2]      ,[ENT_REC3]
      ,[debit]      ,[credit]        ,[BForworddebit]      , [BForwordCredit]
      
	)
	SELECT  
		[USR_C],''
		,ENTRY_TP.[JRN_TYP] ,@fromdate AS FROM_DATE,@todate AS TO_DATE	,TMP_ACC3101G.[ACC_NU],TMP_ACC3101G.[SUB_NU],ISNULL(MAIN_ACC.ACC_NM_A,''),ISNULL(MAIN_ACC.ACC_NM_E,'')
		,ISNULL(SUB_ACC.SUB_NM_A,''),ISNULL(SUB_ACC.SUB_NM_E,''),[JRN_DATE]      ,[JRN_NU] ,ISNULL([JRN_REC3],'') as [JRN_REC3] ,ISNULL(JRN_CHK,'') as JRN_CHK
		,TMP_ACC3101G.JRN_DES as [ds1],[ENT_DES]  as [ds2]
		 ,ISNULL([ENT_REC1],'')   ,ISNULL([ENT_REC2],'')   ,ISNULL([ENT_REC3],'')  ,[ENT_DR]  ,[ENT_CR],0 as[BForworddebit] ,0 as [BForwordCredit]
		
	FROM         [Finance].CUR_CODE INNER JOIN
                      [Finance].MAIN_ACC INNER JOIN
                      [Finance].TMP_ACC3101G ON MAIN_ACC.ACC_NU = TMP_ACC3101G.ACC_NU ON CUR_CODE.CUR_NU = TMP_ACC3101G.CUR_NU LEFT OUTER JOIN
                      [Finance].SUB_ACC ON TMP_ACC3101G.ACC_NU = SUB_ACC.ACC_NU AND TMP_ACC3101G.SUB_NU = SUB_ACC.SUB_NU
                      LEFT OUTER JOIN [Finance].ENTRY_TP ON TMP_ACC3101G.JRN_TYP = ENTRY_TP.ID
                      -- CROSS JOIN
                      --[Finance].SYS_PARA  
					  where  USR_C=@USR_C                 
        select * from TMP_ACC3101 WHERE USR_C=@USR_C 

END











