					  where USR_C=@USR_C
   --19--
   delete from TMP_ACC3101T WHERE USR_C=@USR_C 
   INSERT INTO [TMP_ACC3101T] (
		[USR_C]      ,[CompanyName]      
      ,[type]      ,Expr1     ,  Expr2    ,[ACC_NU]      ,[SUB_NU]      ,[ACC_NM_A]
      ,[ACC_NM_E]      ,[SUB_NM_A]      ,[SUB_NM_E]      ,[date]      ,[jrnno]      ,[JRN_REC3],JRN_CHK
      ,[ds1]      ,[ds2]      ,[ENT_REC1]      ,[ENT_REC2]      ,[ENT_REC3]
      ,[debit]      ,[credit]        ,[BForworddebit]      , [BForwordCredit]
      
	)
	SELECT  
		[USR_C],SYS_PARA.CO_NAMEE
		,ENTRY_TP.[JRN_TYP] ,@fromdate AS FROM_DATE,@todate AS TO_DATE	,TMP_ACC3101G.[ACC_NU],TMP_ACC3101G.[SUB_NU],ISNULL(MAIN_ACC.ACC_NM_A,''),ISNULL(MAIN_ACC.ACC_NM_E,'')
		,ISNULL(SUB_ACC.SUB_NM_A,''),ISNULL(SUB_ACC.SUB_NM_E,''),[JRN_DATE]      ,[JRN_NU] ,ISNULL([JRN_REC3],'') as [JRN_REC3] ,ISNULL(JRN_CHK,'') as JRN_CHK
		,TMP_ACC3101G.JRN_DES as [ds1],[ENT_DES]  as [ds2]
		 ,ISNULL([ENT_REC1],'')   ,ISNULL([ENT_REC2],'')   ,ISNULL([ENT_REC3],'')  ,[ENT_DR]  ,[ENT_CR],0 as[BForworddebit] ,0 as [BForwordCredit]
		
	FROM         CUR_CODE INNER JOIN
                      MAIN_ACC INNER JOIN
                      TMP_ACC3101G ON MAIN_ACC.ACC_NU = TMP_ACC3101G.ACC_NU ON CUR_CODE.CUR_NU = TMP_ACC3101G.CUR_NU LEFT OUTER JOIN
                      SUB_ACC ON TMP_ACC3101G.ACC_NU = SUB_ACC.ACC_NU AND TMP_ACC3101G.SUB_NU = SUB_ACC.SUB_NU
                      LEFT OUTER JOIN ENTRY_TP ON TMP_ACC3101G.JRN_TYP = ENTRY_TP.ID
                       CROSS JOIN
                      SYS_PARA  
					  where  USR_C=@USR_C                 
