if  @BalanceApper=0
begin
INSERT INTO [Finance].TMP_ACC3103(USR_C,ACC_NU,SUB_NU,ENT_DR,ENT_CR,[DES],BAL,D_FROM,D_TO)SELECT  @USR_C,ACC_NU,SUB_NU,SUM(round(isnull(ENT_DR,0),2)/@convRate) ,SUM(ENT_CR/@convRate),'details','',@fromdate,@todate  From [Finance].ENTRY INNER JOIN  [Finance].JOURNAL ON [Finance].ENTRY.JRN_ID = [Finance].JOURNAL.JRN_ID WHERE JRN_DATE BETWEEN @fromdate AND @todate AND ACC_NU BETWEEN @FrommainAccount AND @TomainAccount GROUP BY ACC_NU,SUB_NU

end 
