		INSERT INTO [Finance].TMP_ACC3103A (USR_C,ACC_NU,SUB_NU,ENT_DR,ENT_CR,[DES],BAL,D_FROM,D_TO,STR_DR,STR_CR) 
		SELECT @USR_C,A.ACC_NU,A.SUB_NU,SUM(isnull(isnull(ENT_DR,0)/@convRate,0)),SUM(isnull(isnull(ENT_CR,0)/@convRate,0)),'Details',''
		 , @fromdate,@todate , 0 , 0  
		 From [Finance].TMP_ACC3103B AS A LEFT OUTER JOIN  TMP_ENTRY_I AS ENTRY ON ENTRY.USR_C = A.USR_C
		  AND A.ACC_NU = ENTRY.ACC_NU And A.SUB_NU = ENTRY.SUB_NU

		 Where a.ACC_NU BETWEEN @FrommainAccount AND @TomainAccount and a.USR_C=@USR_C 
		 
		 GROUP BY a.ACC_NU,a.SUB_NU


