		update [Finance].TMP_ACC3103A set  TMP_ACC3103A.str_cr=TMP_ACC3103A.str_cr+ISNULL((SELECT round(SUM(isnull(entry.ent_cr,0)/@convRate)  ,2)
		 From [Finance].ENTRY left outer JOIN JOURNAL ON ENTRY.JRN_id = JOURNAL.JRN_ID  
		 where  TMP_ACC3103A.ACC_NU=entry.ACC_NU AND TMP_ACC3103A.SUB_NU=ENTRY.SUB_NU  AND JRN_DATE <= @TmpDate
		  AND JRN_DATE >= @MyDate and USR_C=@USR_C 
