update [Finance].TMP_ACC3103a set BAL_CR = round(isnull(ENT_CR,0),2)- round(isnull(ENT_DR,0),2)+round( isnull(STR_CR,0),2)- round(isnull(STR_DR,0),2) where  USR_C=@USR_C AND (isnull(ENT_CR,0)- isnull(ENT_DR,0)+ isnull(STR_CR,0)- isnull(STR_DR,0)) > 0
update [Finance].TMP_ACC3103A set BAL_DR=0 where BAL_DR is null and usr_c=@USR_C
update [Finance].TMP_ACC3103A set BAL_CR=0 where BAL_CR is null and usr_c=@USR_C
DELETE From [Finance].TMP_ACC3103A WHERE USR_C=@USR_C AND ENT_DR=0 AND ENT_CR =0 AND STR_DR=0 AND STR_CR=0
		--'====================================================

delete From [Finance].TMP_ACCO3103 where  USR_C=@USR_C

INSERT INTO [Finance].[TMP_ACCO3103]  (
		[USR_C]      ,[FromDate]      ,[ToDate]      ,[Debit]      ,[Credit]      ,[BalanceDr]
      ,[BalanceCr]           ,[SBALDR]   ,[SBALCR]    ,[ACC_NU]      ,[SUB_NU]      ,[CompanyName]
      ,[ACC_NM_E]      ,[Sub_NM_E]
	)
	SELECT  [USR_C] ,[D_FROM] ,[D_TO], [ENT_DR]     ,[ENT_CR]  ,[STR_DR],[STR_CR],[BAL_DR]      ,[BAL_CR]  
	 ,TMP_ACC3103A.[ACC_NU]      ,TMP_ACC3103A.[SUB_NU], '',
	 
	 -- ***** NR **** 22/03/2016 ****
	case When @CULT = 0  then ( MAIN_ACC.ACC_NM_A ) else ( MAIN_ACC.ACC_NM_E ) end  ,
	case When @CULT = 0 then SUB_ACC.SUB_NM_a else SUB_ACC.SUB_NM_E  end  
	-- SUB_ACC.SUB_NM_a

	From [Finance].TMP_ACC3103A INNER JOIN
                      MAIN_ACC ON TMP_ACC3103A.ACC_NU = MAIN_ACC.ACC_NU LEFT OUTER JOIN
                      SUB_ACC ON TMP_ACC3103A.ACC_NU = SUB_ACC.ACC_NU AND TMP_ACC3103A.SUB_NU = SUB_ACC.SUB_NU 
					  -- CROSS JOIN SYS_PARA 
					  where USR_C=@USR_C	

