-------------------------------------------------
as
begin


DECLARE @MyYear  int
	DECLARE @MyDay  int
	DECLARE @MyMonth  int
	SET @MyYear = Year(@fromdate)
	SET @MyDay = Day(@fromdate)
	SET @MyMonth = Month(@fromdate)

	DECLARE @MYD varchar(2) 
	DECLARE @MYM varchar(2)
	DECLARE @MYY varchar(4)
	
	
	DECLARE @MyDate  datetime
	DECLARE @TmpDate  datetime
	
	DECLARE @STR_YEAR  int
	DECLARE @ACCOUNTING_MONTH int 

	DECLARE @ENT_CR float 
	DECLARE @ENT_DR float 
	set @ENT_CR = 0
	set @ENT_DR = 0

	DECLARE @STR_CR float 
	DECLARE @STR_DR float 
	set @STR_CR = 0
	set @STR_DR = 0

	DECLARE @BAL_CR float  
	DECLARE @BAL_DR float 
	DECLARE @MyBAlEqu float 
	set @BAL_CR = 0 
	set @BAL_DR = 0
	set @MyBAlEqu=0
	
	
	DECLARE @SBAL_CR float  
	DECLARE @SBAL_DR float 
	set @SBAL_CR = 0 
	set @SBAL_DR = 0

-- ******** Calculate Year ***********************************************************
	SET @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From Sys_data)
	IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		IF @MyMonth >= @ACCOUNTING_MONTH 
		BEGIN
			SET @STR_YEAR = Year(@fromdate)
		END
		ELSE
			SET @STR_YEAR = Year(@fromdate)- 1 
	END
	ELSE 
		SET @STR_YEAR = Year(@fromdate)
-- **************************************************************************
-- ******** Calculate MONTH ***********************************************************
	IF @ACCOUNTING_MONTH = 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = Year(@fromdate) 
	END
	ELSE
		SET @MYD = 1 
		SET @MYM = @ACCOUNTING_MONTH 
		SET @MYY = @STR_YEAR
-- **************************************************************************
	SET @MyDate = @MYM + '/' + @MYD +'/'+  @MYY
	SET @TmpDate = DATEADD(DAY , -1 ,@fromdate )

