--*******************************************************************************************
--INSERT INTO TMP_ACC3105
--	([USR_C],CompanyName,[Cur_nu] ,[Cur_Code],[type] ,[FromDate] ,[ToDate] ,[ACC_NU] ,[SUB_NU] ,[ACC_NM_A] ,[ACC_NM_E]
--      ,[SUB_NM_A],[SUB_NM_E] ,[date],[jrnno],[jrn_rec3],[jrn_chk] ,[ds1],[ds2] ,[ENT_REC1] ,[ent_rec2] ,[ent_rec3]
--      ,[debit],[credit],[Equiv_Dr],[Equiv_Cr])
--SELECT        @USR_C AS USR_C,'' as CompanyName, @CurPar AS Cur_nu, 'USD' AS Cur_Code,'' as [type], '01/01/1990' AS FromDate, '01/01/1990' AS ToDate
--			,MAIN_ACC.ACC_NU, SUB_NU,ACC_NM_A,ACC_NM_E, SUB_NM_A, SUB_NM_E, 
--              '01/01/1990' AS [date], 0 AS [jrnno], '' AS [jrn_rec3], '' AS [jrn_chk], '' AS [ds1], '' AS [ds2]
--			  , '' AS [ENT_REC1], '' AS [ent_rec2], '' AS [ent_rec3], 0 AS [debit], 0 AS [credit], 0 AS [Equiv_Dr], 
--                         0 AS [Equiv_Cr]
--FROM            MAIN_ACC inner JOIN
--                         SUB_ACC ON MAIN_ACC.ACC_NU = SUB_ACC.ACC_NU
--WHERE        (MAIN_ACC.ACC_NU = @mainAccount)
--GROUP BY MAIN_ACC.ACC_NU, SUB_ACC.SUB_NU, MAIN_ACC.ACC_NM_A, MAIN_ACC.ACC_NM_E, SUB_ACC.SUB_NM_A, SUB_ACC.SUB_NM_E
INSERT INTO TMP_ACC3105

select  @USR_C , CompanyName=(SELECT CO_NAMEE FROM SYS_PARA),e.Cur_nu,Cur_Code,[type]=tp.JRN_TYP
,@fromdate as FromDate,@todate as ToDate,  e.ACC_NU ,e.SUB_NU,ACC_NM_A,ACC_NM_E,SUB_NM_A,SUB_NM_E,
[date]='01/01/1990',jrnno=0,'','' ,'','','','','',
 debit=0, credit=0, Equiv_Dr=0, Equiv_Cr=0
from ENTRY as e
join JOURNAL as j
on j.JRN_ID=e.JRN_ID 
join ENTRY_TP as tp
on j.JRN_TYP=tp.id
join main_acc as macc
on e.acc_nu=macc.acc_nu
left join sub_acc as sacc
on e.SUB_NU=sacc.SUB_NU
AND macc.ACC_NU = sacc.ACC_NU  
join CUR_CODE as Cur
on e.CUR_NU=Cur.CUR_NU 
where
e.ACC_NU=@mainAccount 
and ((e.SUB_NU = @subAccount) or (@subAccount is null))
and JRN_DATE<@fromdate 
and ((e.CUR_NU  = @CurPar) or  @CurPar is null)
and ((j.JRN_TYP<> @TypeOut_1) or (@TypeOut_1 is null))
and ((j.JRN_TYP<> @TypeOut_2) or (@TypeOut_2 is null))
and ((j.JRN_TYP<> @TypeOut_3) or (@TypeOut_3 is null))
