	DECLARE Currency_cursor CURSOR FOR   SELECT DISTINCT CUR_NU From TMP_ACC3105 where USR_C=@USR_C
			
			OPEN Currency_cursor   DECLARE @CurrCur int
			FETCH NEXT FROM Currency_cursor  INTO @CurrCur
			WHILE (@@FETCH_STATUS <> -1) 
			BEGIN  
			-----------------------------------
			-- isert open balance line for each currency  ---
			insert into TMP_ACC3105
				SELECT  @USR_C as USR_C ,CompanyName=(SELECT CO_NAMEE FROM SYS_PARA)
				,CUR_NU=@CurrCur,Cur_Code=(select  Cur_Code from CUR_CODE where CUR_NU=@CurrCur)
				,'' as type,@fromdate as fromdate,@todate as todate
				,ACC_NU=@mainAccount,SUB_NU=@subAccount
				,(select top 1 ACC_NM_A from MAIN_ACC where ACC_NU =@mainAccount) as ACC_NM_A
				,(select top 1 ACC_NM_E from MAIN_ACC where ACC_NU =@mainAccount) as ACC_NM_E
				,SUB_NM_A=(select top 1 SUB_NM_A from SUB_ACC where ACC_NU=@mainAccount and SUB_NU=@subAccount)
				,SUB_NM_E =(select top 1 SUB_NM_E from SUB_ACC where ACC_NU=@mainAccount and SUB_NU=@subAccount)
				,''as [date],'' as jrnno,'' as jrn_rec3,'' as jrn_chk,'Open Balance' as ds1,'' as ds2,'' as ENT_REC1,'' as ent_rec2,'' as ent_rec3
				,0 as debit,0 as credit
				,0 as Equiv_Dr,0 as Equiv_Cr
				
				-- Get openning balance for each curr -----------		
				set @MyAccount=isnull((SELECT  ACC_NU FROM TMP_ACC3105  where ds1 ='Open Balance' AND USR_C=@USR_C and CUR_NU = @CurrCur) ,0)
				set @MysubAccount=isnull((SELECT  SUB_NU FROM TMP_ACC3105  where ds1='Open Balance' AND USR_C=@USR_C and CUR_NU = @CurrCur) ,0)
				CREATE TABLE #MyStored (Dr float, Cr float,Equ_dr Float,Equ_Cr Float)
				INSERT INTO #MyStored EXECUTE  SPGetOpeningBalanceCur @MAIN_ACC=@MyAccount ,@SUB_ACC=@MysubAccount ,@FROM_DATE= @fromdate ,@TO_DATE= @todate,@Cur_No = @CurrCur

				set @MyBAlDr =isnull((select Dr from   #MyStored),0)
				set @MyBAlCr =isnull((select Cr from   #MyStored),0)
				set @MyBAlEquDr =isnull((select Equ_dr from   #MyStored),0)
				set @MyBAlEquCr =isnull((select Equ_Cr from   #MyStored),0)
				update TMP_ACC3105 set debit=@MyBAlDr/1  where ds1 ='Open Balance' AND USR_C=@USR_C and CUR_NU = @CurrCur
