SET @MyYear = Year(@fromdate) - 1
SET @MyDate = @MyMonth + '/' + @MyDay +'/'+  @MyYear
 
SET @MyToYear = Year(@Todate) - 1
SET @MyToDate = @MytoMonth + '/' + @MytoDay +'/'+  @MyToYear 
INSERT INTO TMP_ACCO3107 (USR_C , ACC_NU , SUB_NU , FLG , CRR_BAL0 , CRR_BAL1 , CRR_BAL2) 
       SELECT @USR_C , ACC_NU , SUB_NU , 1 , 0 ,  ISNULL( SUM(ENT_DR),0) -  ISNULL( SUM(ENT_CR),0 ),0 FROM ENTRY  INNER JOIN JOURNAL ON JOURNAL.JRN_ID = ENTRY.JRN_ID WHERE JRN_DATE >= @MyDate AND (JRN_DATE)<= @MyToDate   AND ACC_NU BETWEEN @FromMainAccount And @ToMainAccount 
