-- '*-*Current Year-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*

set @MYY = Year(@fromdate) 
set @MYD = DAY(@fromdate)
set @MYM = MONTH(@fromdate)
 -- ******** Calculate Year ***********************************************************
	SET @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From Sys_data)
	IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		IF @MyMonth >= @ACCOUNTING_MONTH 
		BEGIN
			SET @STR_YEAR = Year(@fromdate) 
		END
		ELSE
			SET @STR_YEAR = Year(@fromdate)- 1 
	END
	ELSE 
		SET @STR_YEAR = Year(@fromdate) 
-- ******** Calculate MONTH ***********************************************************
	IF @ACCOUNTING_MONTH = 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = Year(@fromdate) 
	END
	ELSE
		SET @MYD = 1 
		SET @MYM = @ACCOUNTING_MONTH 
		SET @MYY = @STR_YEAR
-- **************************************************************************
SET @MyDate = @MYM + '/' + @MYD +'/'+  @MYY 
SET @TmpDate = DATEADD(DAY , -1 ,@fromdate )
-- **************************************************************************
-- ***** Add ACC not have a transaction have only str_bal and found in str_bal ****
INSERT into TMP_ACCO3107 (USR_C , ACC_NU , SUB_NU , FLG , CRR_BAL0 , CRR_BAL1 , CRR_BAL2 , CRR_STRBAL0 , CRR_STRBAL1 , CRR_STRBAL2)
            SELECT @USR_C , ACC_NU , 0 , 4 , 0 , 0 , 0 , 0 , 0 , 0
			FROM STR_BAL WHERE STR_YEAR = @STR_YEAR AND ACC_NU BETWEEN @FromMainAccount AND @ToMainAccount AND 
				 ACC_NU not in (SELECT ACC_NU from TMP_ACCO3107 where USR_C =  @USR_C GROUP BY ACC_NU )
-- ************************************************************************************************
-- ***** Add acc  have a transaction only in pecious Period ,No str_bal and No Transaction *******
INSERT into TMP_ACCO3107 (USR_C , ACC_NU , SUB_NU , FLG , CRR_BAL0 , CRR_BAL1 , CRR_BAL2 , CRR_STRBAL0 , CRR_STRBAL1 , CRR_STRBAL2)
