Update TMP_ACCO3107 set  TMP_ACCO3107.CRR_STRBAL1 = TMP_ACCO3107.CRR_STRBAL1 + ISNULL((SELECT SUM(entry.ENT_DR) FROM Entry INNER JOIN JOURNAL ON JOURNAL.JRN_ID = ENTRY.JRN_ID  
where  TMP_ACCO3107.ACC_NU = ENTRY.ACC_NU AND TMP_ACCO3107.SUB_NU = entry.SUB_NU AND JOURNAL.JRN_DATE <= @MyDate AND JOURNAL.JRN_DATE >= @TmpDate AND USR_C = @USR_C ),0)

Update TMP_ACCO3107 set  TMP_ACCO3107.CRR_STRBAL1 = TMP_ACCO3107.CRR_STRBAL1 - ISNULL((SELECT SUM(entry.ENT_CR) FROM Entry INNER JOIN JOURNAL ON JOURNAL.JRN_ID = ENTRY.JRN_ID   
where  TMP_ACCO3107.ACC_NU = ENTRY.ACC_NU AND TMP_ACCO3107.SUB_NU = entry.SUB_NU  AND JOURNAL.JRN_DATE <= @MyDate AND JOURNAL.JRN_DATE >= @TmpDate and USR_C = @USR_C ),0)
 
 
  
 print @MyDate
 print @TmpDate
 
 --'*-*Pervious previous Year-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*
 --'*-*Pervious previous Year-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*'*-*-*-**-*-*-*-*-*-*
set @MYY = Year(@fromdate) - 2 
set @MYD = DAY(@fromdate)
set @MYM = MONTH(@fromdate)
 -- ******** Calculate Year ***********************************************************
	SET @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From Sys_data)
	IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		IF @MyMonth >= @ACCOUNTING_MONTH 
		BEGIN
			SET @STR_YEAR = Year(@fromdate) -2
		END
		ELSE
			SET @STR_YEAR = Year(@fromdate)- 1 - 2
	END
	ELSE 
		SET @STR_YEAR = Year(@fromdate) - 2
-- ******** Calculate MONTH ***********************************************************
	IF @ACCOUNTING_MONTH = 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = Year(@fromdate) 
	END
	ELSE
		SET @MYD = 1 
		SET @MYM = @ACCOUNTING_MONTH 
		SET @MYY = @STR_YEAR
-- **************************************************************************
SET @MyDate = @MYM + '/' + @MYD +'/'+  @MYY 
SET @TmpDate = DATEADD(DAY , -1 ,@fromdate )
