Update TMP_ACCO3107 set TMP_ACCO3107.CRR_STRBAL2 = TMP_ACCO3107.CRR_STRBAL2 + ISNULL((SELECT SUM(str_bal.STR_BAL) from str_bal  
	where TMP_ACCO3107.ACC_NU = str_bal.ACC_NU AND TMP_ACCO3107.SUB_NU = str_bal.SUB_NU AND str_bal.STR_TYP = 1 AND STR_YEAR = @STR_YEAR and USR_C = @USR_C ),0)

Update TMP_ACCO3107 set TMP_ACCO3107.CRR_STRBAL2 = CRR_STRBAL2 - ISNULL((SELECT SUM(STR_BAL)  from str_bal  
	WHERE TMP_ACCO3107.ACC_NU = STR_BAL.ACC_NU AND TMP_ACCO3107.SUB_NU = str_bal.SUB_NU and STR_TYP = 2 and STR_YEAR = @STR_YEAR and USR_C = @USR_C ),0)

Update TMP_ACCO3107 set  TMP_ACCO3107.CRR_STRBAL2 = TMP_ACCO3107.CRR_STRBAL2 + ISNULL((SELECT SUM(entry.ENT_DR) FROM Entry INNER JOIN JOURNAL ON JOURNAL.JRN_ID = ENTRY.JRN_ID  
where  TMP_ACCO3107.ACC_NU = ENTRY.ACC_NU AND TMP_ACCO3107.SUB_NU = entry.SUB_NU AND JOURNAL.JRN_DATE <= @MyDate AND JOURNAL.JRN_DATE >= @TmpDate AND USR_C = @USR_C ),0)

Update TMP_ACCO3107 set  TMP_ACCO3107.CRR_STRBAL2 = TMP_ACCO3107.CRR_STRBAL2 - ISNULL((SELECT SUM(entry.ENT_CR) FROM Entry INNER JOIN JOURNAL ON JOURNAL.JRN_ID = ENTRY.JRN_ID   
where  TMP_ACCO3107.ACC_NU = ENTRY.ACC_NU AND TMP_ACCO3107.SUB_NU = entry.SUB_NU  AND JOURNAL.JRN_DATE <= @MyDate AND JOURNAL.JRN_DATE >= @TmpDate and USR_C = @USR_C ),0)
 
 
 print @MyDate
 print @TmpDate


END

update TMP_ACCO3107 set  ACC_NM_E = (select ACC_NM_E from MAIN_ACC where MAIN_ACC.Acc_nu = TMP_ACCO3107.Acc_nu)
update TMP_ACCO3107 set  SUB_NM_E = (select SUB_NM_E from MAIN_ACC INNER JOIN SUB_ACC ON MAIN_ACC.ACC_NU = SUB_ACC.ACC_NU where MAIN_ACC.Acc_nu = TMP_ACCO3107.Acc_nu AND   SUB_ACC.SUB_NU = TMP_ACCO3107.SUB_NU)

