CREATE procEDURE [Finance].[SPACCO3110]

  @USR_C varchar(10)

, @FmDate datetime
, @ToDate datetime

, @entryTPID int = null
, @DateType int = null

, @User varchar(255) = null

 --, @Unbalanced varchar(10)  = null
 --, @EntName varchar(10)  = null
 as 
 begin

DELETE  FROM TMP_ACCO3110  WHERE USR_C = @USR_C
 --------------------------------------------------------


INSERT INTO TMP_ACCO3110 
			

       SELECT @USR_C  AS USR_C ,   EntTyp.JRN_TYP , j.JRN_DATE, j.JRN_NU , j.SYS_DATE , 
                     SUM(ISNULL(e.ENT_DR, 0)) , SUM(ISNULL(e.ENT_CR, 0)) , j.JRN_DES, '',
					 j.JRN_USER, CTRL.Username,
                    (CASE SUM(isnull(e.ENT_DR, 0)) - SUM(isnull(e.ENT_CR, 0)) WHEN 0 THEN 'True' ELSE 'False' END) 
					 as Balanc
				FROM  ENTRY AS e LEFT OUTER JOIN JOURNAL AS j ON e.JRN_ID = j.JRN_ID INNER JOIN ENTRY_TP AS EntTyp ON j.JRN_TYP = EntTyp.ID INNER JOIN CTRL ON CTRL.UserID = j.JRN_USER
					WHERE  (@entryTPID IS NOT NULL) AND (j.JRN_TYP = @entryTPID) AND (CASE @DateType WHEN 0 THEN J.JRN_DATE WHEN 1 THEN J.SYS_DATE ELSE J.SYS_Date END BETWEEN @FmDate AND @todate) OR
