--4   Payment flag 0
INSERT INTO  TMP_ACCO3116 

(USR_C,ACC_NU,SUB_NU,ENT_REC3,CUR_NU,FLG,ENT_CONV_CR,ENT_CONV_DR,ENT_CR,ENT_DR,ENT_RED3,ENT_DES) 

SELECT @User_Name,
E.ACC_NU, E.SUB_NU,
E.ENT_REC3,
C.CUR_NU
,FLAG=(CASE SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1) WHEN 1 THEN 0 ELSE 1 END)

,ENT_CONV_CR = SUM(ISNULL(E.ENT_CONV,0))
,ENT_CONV_DR = 0
,CR = SUM(ISNULL(E.ENT_CR,0))
,DR = SUM(ISNULL(E.ENT_DR,0))

,min(J.JRN_DATE) AS DATE
,MAX(E.ENT_DES) AS ENT_DES

FROM [ENTRY_i] AS E 
join JOURNAL AS J ON J.JRN_ID=E.JRN_ID
JOIN CUR_CODE AS C ON C.CUR_NU=E.CUR_NU

WHERE 

E.ACC_NU=@ACC_NU AND 
E.SUB_NU between @SUB_NU and @SUB_NU2

 AND J.JRN_DATE <= @PaymentToDate
 --AND J.JRN_DATE BETWEEN @FromDate AND @ToDate
AND E.ENT_CR >0 AND SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1)=1

AND ((E.CUR_NU= @Currency)OR(@Currency IS NULL))
group by C.CUR_NU,E.ENT_REC3,E.ACC_NU, E.SUB_NU
 
 --5   Payment flag 1
 
INSERT INTO  TMP_ACCO3116 

(USR_C,ACC_NU,SUB_NU,ENT_REC3,CUR_NU,FLG,ENT_CONV_CR,ENT_CONV_DR,ENT_CR,ENT_DR,ENT_RED3,ENT_DES) 

SELECT @User_Name,
E.ACC_NU, E.SUB_NU,
E.ENT_REC3,
C.CUR_NU
,FLAG=(CASE SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1) WHEN 1 THEN 0 ELSE 1 END)


--,ENT_CONV_CR = SUM(ISNULL(E.ENT_CONV,0))
--,ENT_CONV_DR = 0
,ENT_CONV_CR = 0
,ENT_CONV_DR = SUM(ISNULL(E.ENT_CONV,0))

--,CR = SUM(ISNULL(E.ENT_CR,0))
--,DR = SUM(ISNULL(E.ENT_DR,0))
,CR = SUM(ISNULL(E.ENT_DR,0))
,DR = SUM(ISNULL(E.ENT_CR,0))
,min(J.JRN_DATE) AS DATE
,MAX(E.ENT_DES) AS ENT_DES


FROM [ENTRY_i] AS E 
join JOURNAL AS J ON J.JRN_ID=E.JRN_ID
JOIN CUR_CODE AS C ON C.CUR_NU=E.CUR_NU

WHERE 

E.ACC_NU=@ACC_NU AND 
E.SUB_NU between @SUB_NU and @SUB_NU2

 AND J.JRN_DATE <= @PaymentToDate
 --AND J.JRN_DATE BETWEEN @FromDate AND @ToDate
AND E.ENT_DR >0 AND SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1)=2
--AND SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1)=2

AND ((E.CUR_NU= @Currency)OR(@Currency IS NULL))
group by C.CUR_NU,E.ENT_REC3,E.ACC_NU, E.SUB_NU, e.ENT_RED3  ORDER by E.ENT_RED3

 


ਊ ⴀⴀ㜀 䴀椀渀甀猀嘀愀氀甀攀䄀瀀瀀攀愀爀ഀ਀䤀䘀 䀀䴀椀渀甀猀嘀愀氀甀攀䄀瀀瀀攀愀爀 㴀 　ഀ਀䈀䔀䜀䤀一ഀ਀ऀⴀⴀ渀愀 甀瀀搀愀琀攀搀 㘀ⴀ㜀⼀㈀　㄀㔀ഀ਀   ⴀⴀ 䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 ഀ਀ऀ ⴀⴀ圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  愀渀搀 攀渀琀开爀攀挀㌀ 椀渀⠀猀攀氀攀挀琀 攀渀琀开爀攀挀㌀ 昀爀漀洀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  䄀一䐀 匀唀䈀匀吀刀䤀一䜀⠀䌀伀一嘀䔀刀吀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㄀⤀㴀㄀  最爀漀甀瀀 戀礀 攀渀琀开爀攀挀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀  栀愀瘀椀渀最 猀甀洀⠀䔀一吀开䐀刀⤀ⴀ猀甀洀⠀䔀一吀开䌀刀⤀ 㰀　 ⤀ഀ਀ऀ 䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀ഀ਀䘀刀伀䴀            ⠀匀䔀䰀䔀䌀吀        䔀一吀开刀䔀䌀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀ഀ਀                           䘀刀伀䴀            吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 䄀匀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀开㄀ഀ਀                           圀䠀䔀刀䔀        ⠀唀匀刀开䌀 㴀 䀀唀猀攀爀开一愀洀攀⤀ 䄀一䐀 ⠀匀唀䈀匀吀刀䤀一䜀⠀䌀伀一嘀䔀刀吀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ 䄀䌀䌀开一唀⤀Ⰰ ㄀Ⰰ ㄀⤀ 㴀 ㄀⤀ഀ਀                           䜀刀伀唀倀 䈀夀 䔀一吀开刀䔀䌀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀ഀ਀                           䠀䄀嘀䤀一䜀        ⠀匀唀䴀⠀䔀一吀开䐀刀⤀ ⴀ 匀唀䴀⠀䔀一吀开䌀刀⤀ 㰀 　⤀⤀ 䄀匀 琀 䤀一一䔀刀 䨀伀䤀一ഀ਀                         吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 伀一 琀⸀䔀一吀开刀䔀䌀㌀ 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀䔀一吀开刀䔀䌀㌀ 䄀一䐀 琀⸀䄀䌀䌀开一唀 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀䄀䌀䌀开一唀 䄀一䐀 琀⸀匀唀䈀开一唀 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀匀唀䈀开一唀ഀ਀ऀⴀⴀ 䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 ഀ਀ऀⴀⴀ 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  愀渀搀 攀渀琀开爀攀挀㌀ 椀渀⠀猀攀氀攀挀琀 攀渀琀开爀攀挀㌀ 昀爀漀洀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  䄀一䐀 匀唀䈀匀吀刀䤀一䜀⠀䌀伀一嘀䔀刀吀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㄀⤀㴀㈀  最爀漀甀瀀 戀礀 攀渀琀开爀攀挀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀  栀愀瘀椀渀最 猀甀洀⠀䔀一吀开䌀刀⤀ⴀ猀甀洀⠀䔀一吀开䐀刀⤀ 㰀　 ⤀ഀ਀ऀ䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀ഀ਀䘀刀伀䴀            ⠀匀䔀䰀䔀䌀吀        䔀一吀开刀䔀䌀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀ഀ਀                           䘀刀伀䴀            吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 䄀匀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀开㄀ഀ਀                           圀䠀䔀刀䔀        ⠀唀匀刀开䌀 㴀 䀀唀猀攀爀开一愀洀攀⤀ 䄀一䐀 ⠀匀唀䈀匀吀刀䤀一䜀⠀䌀伀一嘀䔀刀吀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ 䄀䌀䌀开一唀⤀Ⰰ ㄀Ⰰ ㄀⤀ 㴀 ㈀⤀ഀ਀                           䜀刀伀唀倀 䈀夀 䔀一吀开刀䔀䌀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀ഀ਀                           ⴀⴀ䠀䄀嘀䤀一䜀        ⠀匀唀䴀⠀䔀一吀开䌀刀⤀ ⴀ 匀唀䴀⠀䔀一吀开䐀刀⤀ 㰀 　⤀⤀ 䄀匀 琀 䤀一一䔀刀 䨀伀䤀一ഀ਀ऀऀऀऀऀऀ   䠀䄀嘀䤀一䜀        ⠀匀唀䴀⠀䔀一吀开䐀刀⤀ ⴀ 匀唀䴀⠀䔀一吀开䌀刀⤀ 㰀 　⤀⤀ 䄀匀 琀 䤀一一䔀刀 䨀伀䤀一ഀ਀                         吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 伀一 琀⸀䔀一吀开刀䔀䌀㌀ 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀䔀一吀开刀䔀䌀㌀ 䄀一䐀 琀⸀䄀䌀䌀开一唀 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀䄀䌀䌀开一唀 䄀一䐀 琀⸀匀唀䈀开一唀 㴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀⸀匀唀䈀开一唀ഀ਀䔀一䐀ഀ਀ ഀ਀ ⴀⴀ㠀 䈀愀氀愀渀挀攀娀攀爀漀䄀瀀瀀攀愀爀ഀ਀䤀䘀 䀀䈀愀氀愀渀挀攀娀攀爀漀䄀瀀瀀攀愀爀 㴀 　ഀ਀ऀⴀⴀ䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 ഀ਀ऀⴀⴀ 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  愀渀搀 攀渀琀开爀攀挀㌀ 椀渀⠀猀攀氀攀挀琀 攀渀琀开爀攀挀㌀ 昀爀漀洀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀  䄀一䐀 匀唀䈀匀吀刀䤀一䜀⠀䌀伀一嘀䔀刀吀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㄀⤀㴀㄀  最爀漀甀瀀 戀礀 攀渀琀开爀攀挀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀  栀愀瘀椀渀最 猀甀洀⠀䔀一吀开䐀刀⤀ⴀ猀甀洀⠀䔀一吀开䌀刀⤀ 㴀　 ⤀ഀ਀ऀ䐀䔀䰀䔀吀䔀 䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㄀㄀㘀ഀ਀䘀刀伀䴀            ⠀匀䔀䰀䔀䌀吀        䔀一吀开刀䔀䌀㌀Ⰰ 䄀䌀䌀开一唀Ⰰ 匀唀䈀开一唀ഀ਀
                           FROM            TMP_ACCO3116 AS TMP_ACCO3116_1
                           WHERE        (USR_C = @User_Name) AND (SUBSTRING(CONVERT(varchar(10), ACC_NU), 1, 1) = 1)
                           GROUP BY ENT_REC3, ACC_NU, SUB_NU
                      --    HAVING         (SUM(ENT_DR) - SUM(ENT_CR) = 0)
					  HAVING        (ROUND(SUM(ENT_DR), 2) - ROUND(SUM(ENT_CR), 2) = 0)
						  ) AS t INNER JOIN
                         TMP_ACCO3116 ON t.ENT_REC3 = TMP_ACCO3116.ENT_REC3 AND t.ACC_NU = TMP_ACCO3116.ACC_NU AND t.SUB_NU = TMP_ACCO3116.SUB_NU
	-- DELETE FROM TMP_ACCO3116 
	-- WHERE USR_C=@User_Name  and ent_rec3 in(select ent_rec3 from TMP_ACCO3116 where USR_C=@User_Name  AND SUBSTRING(CONVERT(varchar(10),ACC_NU),1,1)=2  group by ent_rec3, ACC_NU, SUB_NU  having sum(ENT_cR)-sum(ENT_dR) =0 )
	DELETE FROM TMP_ACCO3116
FROM            (SELECT        ENT_REC3, ACC_NU, SUB_NU
                           FROM            TMP_ACCO3116 AS TMP_ACCO3116_1
                           WHERE        (USR_C = @User_Name) AND (SUBSTRING(CONVERT(varchar(10), ACC_NU), 1, 1) = 2)
                           GROUP BY ENT_REC3, ACC_NU, SUB_NU
                           --HAVING        (round(SUM(ENT_CR) - SUM(ENT_DR),2) = 0)
						   HAVING        (ROUND(SUM(ENT_CR), 2) - ROUND(SUM(ENT_DR), 2) = 0)
						   ) AS t INNER JOIN
                         TMP_ACCO3116 ON t.ENT_REC3 = TMP_ACCO3116.ENT_REC3 AND t.ACC_NU = TMP_ACCO3116.ACC_NU AND t.SUB_NU = TMP_ACCO3116.SUB_NU

