--6   الغاء الفواتير المصدرة خارج الفترة ولها سدادات داخل الفترة
  --'عميل
  DELETE FROM TMP_ACCO3116
FROM            (SELECT  E.ENT_REC3, E.SUB_NU
                           FROM            ENTRY_I AS E INNER JOIN
                                                    JOURNAL AS J ON J.JRN_ID = E.JRN_ID
                           WHERE        (E.ACC_NU = @ACC_NU) AND (E.ENT_DR > 0) AND (SUBSTRING(CONVERT(varchar(10), E.ACC_NU), 1, 1) = 1) AND (J.JRN_DATE < @FromDate)
                           GROUP BY E.ENT_REC3, E.SUB_NU
                           HAVING        (E.SUB_NU BETWEEN @SUB_NU AND @SUB_NU2)) AS p INNER JOIN
