CREATE proc [Finance].[SPACCO3117]

(
	 @USR_C varchar(10)
	, @fromdate datetime
	, @todate datetime
	, @ACC_NU varchar(1000) 

)

AS

delete from  TMP_ACCO3117 WHERE USR_C= @USR_C

-- **************************************************************************	
-- Read Account and fill it in temp table it's send from code	
	
DECLARE @idoc int

DECLARE @doc varchar(1000)
--set @ACC_NU = '<Contact MainAcc=x122100x  /><Contact MainAcc=x122200x   />"'
set @ACC_NU = REPLACE( @ACC_NU ,'x' , '"')

print @ACC_NU
SET @doc ='<Accounts>' + @ACC_NU +'</Accounts>' print coalesce(@doc, ' ')

--alter an internal representation of the XML document.
EXEC sp_xml_preparedocument @idoc OUTPUT, @doc

-- Execute a SELECT statement that uses the OPENXML rowset provider.
-- **************************************************************************	


DECLARE @Temp TABLE(MainAcc VARCHAR(250),User_c varchar(50))  
INSERT INTO @Temp(User_c,MainAcc)
SELECT @USR_C,*
FROM OPENXML (@idoc, '/Accounts/Contact',1)
