CREATE procEDURE [Finance].[SPACCO3121]
@USR_C VARCHAR(10)
, @todate datetime
, @EMP varchar(10)=null
, @ReportType varchar(1) --if @ReportType='O'=0 out
						--If @ReportType='A' All
 as 
 begin
 delete  FROM TMP_ACCO3121 where USR_C=@USR_C
 
-- --out
IF (upper(@ReportType) ='0')
begin
		insert into TMP_ACCO3121 (USR_C, ENTRY_11_ID, CASH_NU, CASH_NAME, JRN_DATE, ENT_11_DES, EMP_CODE, EMP_NAME, ENT_11_AMT, FLG)
		SELECT 
		@USR_C,
		max(ENTRY_11_ID) as ENTRY_11_ID ,
		E.CASH_NU,C.CASH_NAME,
		max(E.JRN_DATE) AS JRN_DATE,
		E.ENT_11_DES,
		E.EMP_CODE,
		EMP.EMP_NAME,
		min(E.ENT_11_AMT) AS ENT_11_AMT,
		FLG='O'
		FROM ENTRY_11 AS E
		JOIN CASH_NAME AS C ON C.CASH_NU = E.CASH_NU
		JOIN EMP ON EMP.EMP_CODE =E.EMP_CODE
