 if @DateType = 0 
	Begin
	INSERT INTO TMP_ACCO3122 (USR_C,CHK_BOOK,CHK_SER ,ACC_NU,SUB_NU, CHK_NAME, CHK_AMT , DES_1 , DES_2 , CHK_DATE , CUR_CODE , CHK_APP , JRN_DATE , JRN_NU , NAME , [DESCRIPTION])
	Select @USR_C, CHK_BOOK,CHK_SER ,ACC_NU,SUB_NU, CHK_NAME, CHK_AMT , DES_1 , DES_2 , CHK_DATE , CUR_CODE , CHK_APP , JRN_DATE , JRN_NU , NAME , [DESCRIPTION]
			FROM CHKQUS
				WHERE JRN_DATE BETWEEN @fromdate AND @todate  
					and (ACC_NU = @ACC_NU OR @ACC_NU IS NULL) 
					and	(SUB_NU = @SUB_NU OR @SUB_NU IS NULL)
					and	(CUR_CODE = @Currency OR @Currency IS NULL)
					and (CHK_SER between  @FromCheck and  @ToCheck  OR @FromCheck IS NULL)
	End 
Else 
	Begin
	INSERT INTO TMP_ACCO3122 (USR_C,CHK_BOOK,CHK_SER ,ACC_NU,SUB_NU, CHK_NAME, CHK_AMT , DES_1 , DES_2 , CHK_DATE , CUR_CODE , CHK_APP , JRN_DATE , JRN_NU , NAME , [DESCRIPTION])
	Select @USR_C, CHK_BOOK,CHK_SER ,ACC_NU,SUB_NU, CHK_NAME, CHK_AMT , DES_1 , DES_2 , CHK_DATE , CUR_CODE , CHK_APP , JRN_DATE , JRN_NU , NAME , [DESCRIPTION]
			FROM CHKQUS
				WHERE CHK_DATE BETWEEN @fromdate AND @todate  
					and (ACC_NU = @ACC_NU OR @ACC_NU IS NULL) 
					and	(SUB_NU = @SUB_NU OR @SUB_NU IS NULL)
					and	(CUR_CODE = @Currency OR @Currency IS NULL)
					and (CHK_SER between  @FromCheck and  @ToCheck  OR @FromCheck IS NULL)
    End

 if @ReportData = 1 --- Aproved
 Begin 
	Delete  FROM TMP_ACCO3122 where USR_C = @USR_C and ( CHK_APP = 'V' or   CHK_APP = '' or CHK_APP = ' ')
 End

 if @ReportData = 2 --- Cancelled
 Begin 
	Delete  FROM TMP_ACCO3122 where USR_C = @USR_C and ( CHK_APP = 'U' or   CHK_APP = '' or CHK_APP = ' ')
 End

end











