		While(@FromMonthcounter <= @ToMonth)
		BEGIN	 
			set @MyQueryString='
				update TMP_ACCO3124 
					set  TMP_ACCO3124.M'+cast(@FromMonthcounter as varchar(3)) +'_D =TMP_ACCO3124.M'+cast(@FromMonthcounter as varchar(3))+'_D + P.Sum_Dr,
						 TMP_ACCO3124.M'+cast(@FromMonthcounter as varchar(3))+'_C=TMP_ACCO3124.M'+cast(@FromMonthcounter as varchar(3))+'_C + P.Sum_Cr
					from  TMP_ACCO3124 
						  inner Join (SELECT ENTRY.ACC_NU, round(ISNULL(SUM(ISNULL(ENTRY.ENT_DR, 0)), 0),2) AS Sum_Dr
									  , round(ISNULL(SUM(ISNULL(ENTRY.ENT_CR, 0)), 0),2) AS Sum_Cr
										FROM   ENTRY LEFT OUTER JOIN
				                                JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID
										WHERE       
										(MONTH(JOURNAL.JRN_DATE) = '+cast(@FromMonthcounter as varchar(3))+') 
										'+isnull('and Cur_nu = '+cast(@Cur as varchar(4)),'')+'	 
										AND 
