 IF @RepTyp = 2
 begin
INSERT into TMP_ACCO3125 (USR_C , JRN_REC3 , JRN_DATE , PAY_TO , DLV_DATE , CUR_NU , ACC_NU ,SUB_NU , ACC_NU_D ,  SUB_NU_D , JRN_CHK , ENT_DES , ENT_CR )
	Select @USR_C ,  JRN_REC3, JRN_DATE, PAY_TO, DLV_DATE, CUR_CODE, ACC_NU, SUB_NU, ACC_NU_D, SUB_NU_D , JRN_CHK , ENT_DES , ENT_CR
	FROM   ENTRY_12_CHK INNER JOIN CUR_CODE ON  ENTRY_12_CHK.CUR_NU  = CUR_CODE.CUR_NU 
	WHERE  JRN_DATE >=  @fromdate AND  JRN_DATE <=  @todate  AND
		   --DLV_DATE <>  '01/01/1990' AND 
		   (ENTRY_12_CHK.CUR_NU = @CurrCode OR @CurrCode IS NULL) AND
		   --CUR_NU = @CurrCode AND 
		    (ACC_NU = @CMainAccount OR @CMainAccount IS NULL) AND
		    (SUB_NU = @CSubAccount OR @CSubAccount IS NULL) AND
		    (ACC_NU_D = @DMainAccount OR @DMainAccount IS NULL) AND
		    (SUB_NU_D = @DSubAccount OR @DSubAccount IS NULL) AND
		   --ACC_NU = @CMainAccount AND SUB_NU =@CSubAccount AND 
		   --ACC_NU_D = @DMainAccount AND SUB_NU_D = @DSubAccount AND 
		   ENTRY_12_CHK.JRN_CHK > '0'
 end
 
 
 IF @RepTyp = 3
 begin
INSERT into TMP_ACCO3125 (USR_C , JRN_REC3 , JRN_DATE , PAY_TO , DLV_DATE , CUR_NU , ACC_NU ,SUB_NU , ACC_NU_D ,  SUB_NU_D , JRN_CHK , ENT_DES , ENT_CR )
	Select @USR_C ,  JRN_REC3, JRN_DATE, PAY_TO, DLV_DATE, CUR_CODE, ACC_NU, SUB_NU, ACC_NU_D, SUB_NU_D, JRN_CHK , ENT_DES , ENT_CR
	FROM   ENTRY_12_CHK INNER JOIN CUR_CODE ON  ENTRY_12_CHK.CUR_NU  = CUR_CODE.CUR_NU 
	WHERE  JRN_DATE >=  @fromdate AND  JRN_DATE <=  @todate  AND
		   DLV_DATE <>  '01/01/1990' AND 
		   (ENTRY_12_CHK.CUR_NU = @CurrCode OR @CurrCode IS NULL) AND
		  -- CUR_NU = @CurrCode AND 
		    (ACC_NU = @CMainAccount OR @CMainAccount IS NULL) AND
		    (SUB_NU = @CSubAccount OR @CSubAccount IS NULL) AND
		    (ACC_NU_D = @DMainAccount OR @DMainAccount IS NULL) AND
		    (SUB_NU_D = @DSubAccount OR @DSubAccount IS NULL)
		   --ACC_NU = @CMainAccount AND SUB_NU =@CSubAccount AND 
		   --ACC_NU_D = @DMainAccount AND SUB_NU_D = @DSubAccount AND 
		   --ENTRY_12_CHK.dlv_DATE <> '1990/01/01'
 end
 
