 		INSERT INTO TMP_ACCO3128 ([year] , [month] , [fromday] ,ACC_Nu, [ACC_NM_NO] , d1 , c1,d2,c2,d3,c3,d4,c4,d5,c5,d6,c6, [USR_C]) 
			( SELECT @year, @month , @fromday, ACC_NU , '' ,0,0,0,0,  sum(ent_dr) , sum(ent_cr) ,  0,0,0,0 ,0,0,  @USR_C AS USR_C 
                           FROM JOURNAL INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID INNER JOIN ENTRY_TP AS tp ON JOURNAL.JRN_TYP = tp.ID where 
						   Acc_Nu=  @Account AND YEAR(jrn_date) = @year AND  month(jrn_date) = @month and   day(jrn_date) = @count 
						   and ((tp.JRN_TYP <> ''' + @TypeOut_1 + ''') or (''' + @TypeOut_1 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_2 + ''') or (''' + @TypeOut_2 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_3 + ''') or (''' + @TypeOut_3 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_4 + ''') or (''' + @TypeOut_4 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_5 + ''') or (''' + @TypeOut_5 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_6 + ''') or (''' + @TypeOut_6 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_7 + ''') or (''' + @TypeOut_7 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_8 + ''') or (''' + @TypeOut_8 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_9 + ''') or (''' + @TypeOut_9 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_10 + ''') or (''' + @TypeOut_10 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_11 + ''') or (''' + @TypeOut_11 + ''' is null))
							and ((tp.JRN_TYP <> ''' + @TypeOut_12 + ''') or (''' + @TypeOut_12 + ''' is null))
						   group by ACC_NU )

END

IF @count = 4 or @count= 9 or @count=  14 or @count=  19 or @count=  24 or  @count= 29
