			WHERE  STR_YEAR = @STR_YEAR and STR_BAL.ACC_NU=@MainAccount2 and STR_BAL.SUB_NU not in (select SUB_NU from TMP_ACCO3129 where USR_C=@USR_C AND ACC_NU=@MainAccount2 )
