			--Get Str Bal--------------------------------------------------------------
			print 'get str_Dr'
			--get str_Dr
			set @MyQueryString = 'update TMP_ACCO3129 set TMP_ACCO3129.STRBAl_ACC_'+ cast (@Counter as varchar(2) )+' =TMP_ACCO3129.STRBAl_ACC_'+ cast (@Counter as varchar(2) )+' + ISNULL((SELECT SUM(round(isnull(str_bal.STR_BAL,0),2)) 
									from str_bal  
									where TMP_ACCO3129.ACC_NU = str_bal.ACC_NU AND TMP_ACCO3129.SUB_NU=STR_BAL.SUB_NU 
									and str_bal.ACC_NU ='+ cast (@MainAccount2 as varchar(6) )+'  and str_bal.STR_TYP = 1 and  STR_YEAR = '+ cast (@STR_YEAR as varchar(4) )+'   and USR_C='''+ cast (@USR_C as varchar(20) )+'''  ),0)'
			print @MyQueryString
			EXEC sp_executesql @MyQueryString


			--get str_Cr
			print 'str_Cr'
			set @MyQueryString = 'update TMP_ACCO3129 set TMP_ACCO3129.STRBAl_ACC_'+ cast (@Counter as varchar(2) )+' =TMP_ACCO3129.STRBAl_ACC_'+ cast (@Counter as varchar(2) )+' - ISNULL((SELECT SUM(round(isnull(str_bal.STR_BAL,0),2)) 
									from str_bal  
									where TMP_ACCO3129.ACC_NU = str_bal.ACC_NU AND TMP_ACCO3129.SUB_NU=STR_BAL.SUB_NU 
									and str_bal.ACC_NU ='+ cast (@MainAccount2 as varchar(6) )+'  and str_bal.STR_TYP =2 and  STR_YEAR = '+ cast (@STR_YEAR as varchar(4) )+'   and USR_C='''+ cast (@USR_C as varchar(20) )+'''  ),0)'
			print @MyQueryString
			EXEC sp_executesql @MyQueryString


			--Get Trans_dr
			print 'Trans_dr'
