刀䔀䌀䤀嘀䔀开䘀䴀ഀ਀ऀऀऀऀऀⴀⴀⰀ䔀一吀开䄀䴀吀 愀猀 䔀一吀开䄀䴀吀ഀ਀
					,(case when  CUR_NU =1 then ENT_AMT else round(ENT_AMT * (isnull((select  [CUR_CONV] from Cur Where Cur_Nu=ENTRY_12_TAX.CUR_NU and CUR_DATE  =(SELECT MAX(CUR_DATE) FROM CUR WHERE CUR_NU=ENTRY_12_TAX.CUR_NU AND CUR_DATE <= JRN_DATE) ),1)),2) end ) as ENT_AMT
					, ENT_TAX AS ENT_TAX
					--,ENT_T_AMT AS ENT_T_AMT
					,(case when  CUR_NU =1 then ENT_T_AMT else round(ENT_T_AMT * (isnull((select top 1 [CUR_CONV] from Cur Where Cur_Nu=ENTRY_12_TAX.CUR_NU and CUR_DATE  =(SELECT MAX(CUR_DATE) FROM CUR WHERE CUR_NU=ENTRY_12_TAX.CUR_NU AND CUR_DATE <= JRN_DATE) ),1)),2) end ) as ENT_T_AMT
					,CUR_NU AS CUR_NU,TAX_FILE AS TAX_FILE,
					TAX_CARD AS TAX_CARD,TAX_NAME AS TAX_NAME,RECIVE_FM_ACC AS RECIVE_FM_ACC, RECIVE_FM_SUB AS RECIVE_FM_SUB,TAX_NAME_ACC AS TAX_NAME_ACC,TAX_NAME_SUB AS TAX_NAME_SUB,
					SUPP_ADD AS SUPP_ADD,TAX_TYPE AS TAX_TYPE,(ENT_AMT-ENT_T_AMT) AS NET_ENT_AMT
			FROM       ENTRY_12_TAX
			Where	year(JRN_DATE)=@YEAR
         			and ((CUR_NU= Convert(smallint,@CurrencyCode) ) or (@CurrencyCode is null))
					AND TAX_FLG=@TAX_FLG 
					AND  Month(JRN_DATE)  BETWEEN CONVERT(int, @LowerBoundPeriod) AND CONVERT(int, @UpperBoundPeriod)

		end 
     end
 
 
 else
 begin
	 print 'ممول'
		 INSERT INTO [TMP_ACCO3130] 
			(USR_C,ENT_AMT,	ENT_TAX,ENT_T_AMT,TAX_NAME_ACC,TAX_NAME_SUB,NET_ENT_AMT,JRN_DATE,RECIVE_FM,CUR_NU,TAX_FILE,TAX_CARD,TAX_NAME,RECIVE_FM_ACC,RECIVE_FM_SUB,SUPP_ADD,TAX_TYPE)
		 SELECT @USR_C AS User_C,SUM(ENT_AMT) AS ENT_AMT, SUM(ENT_TAX) AS ENT_TAX, SUM(ENT_T_AMT) AS ENT_T_AMT, TAX_NAME_ACC AS TAX_NAME_ACC, TAX_NAME_SUB AS TAX_NAME_SUB,
