	delete  FROM TMP_ACCO3133 WHERE USR_C=@USR_C
	-----------------------------------------------------------------------------------
	 INSERT INTO [TMP_ACCO3133] 
   (USR_C,
    ENT_REC5,
	JRN_DATE,
	RECIVE_FM,
	ENT_AMT,
	ENT_TAX,
	ENT_T_AMT,
	CUR_NU,
	RECIVE_FM_ACC,
	RECIVE_FM_SUB,
	TAX_NAME_ACC,
	TAX_NAME_SUB,
	TAX_TYPE,
	NET_ENT_AMT,
	CUR_CODE,
	SUB_NM_A,
	SUB_DES,
	SUB_DES1,
	SUB_DES2,
	SUB_DES3)
	SELECT        @USR_C AS USR_C,
				  ENT_REC5 AS ENT_REC5,
				  ENTRY_12_TAX.JRN_DATE AS JRN_DATE,
			      ENTRY_12_TAX.RECIVE_FM AS RECIVE_FM,
	              ENTRY_12_TAX.ENT_AMT AS ENT_AMT,
	              ENTRY_12_TAX.ENT_TAX AS ENT_TAX,
		          ENTRY_12_TAX.ENT_T_AMT AS ENT_T_AMT,
		          ENTRY_12_TAX.CUR_NU AS CUR_NU,
		          ENTRY_12_TAX.RECIVE_FM_ACC AS RECIVE_FM_ACC,
		          ENTRY_12_TAX.RECIVE_FM_SUB AS RECIVE_FM_SUB,
		          ENTRY_12_TAX.TAX_NAME_ACC AS TAX_NAME_ACC, 
                  ENTRY_12_TAX.TAX_NAME_SUB AS TAX_NAME_SUB,
                  ENTRY_12_TAX.TAX_TYPE AS TAX_TYPE,
                  ENTRY_12_TAX.ENT_AMT - ENTRY_12_TAX.ENT_T_AMT AS NET_ENT_AMT, 
                  CUR_CODE.CUR_CODE AS CUR_CODE,
                  SUB_ACC.SUB_NM_A AS SUB_NM_A,
                  SUB_ACC.SUB_DES AS SUB_DES , 
                  SUB_ACC.SUB_DES1 AS SUB_DES1,
                  SUB_ACC.SUB_DES2 AS SUB_DES2, 
                  SUB_ACC.SUB_DES3 AS SUB_DES2
                  

FROM          
				 ENTRY_12_TAX INNER JOIN
                 CUR_CODE ON ENTRY_12_TAX.CUR_NU = CUR_CODE.CUR_NU LEFT OUTER JOIN
                 SUB_ACC ON ENTRY_12_TAX.TAX_NAME_ACC = SUB_ACC.ACC_NU AND ENTRY_12_TAX.TAX_NAME_SUB = SUB_ACC.SUB_NU

where	   TAX_NAME_ACC=convert(float, @MainACC) AND 
          ((@FMSUBACC is NUll AND @TOSUBACC is Null) OR (TAX_NAME_SUB BETWEEN CONVERT(float,@FMSUBACC) AND CONVERT(FLOAT,@TOSUBACC)))
          AND  ENTRY_12_TAX.JRN_DATE BETWEEN @FMDATE AND @TODATE
         

END
