  匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ ⼀⨀ഀ਀ ⨀⼀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀䔀䐀唀刀䔀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㄀㌀㘀崀ഀ਀䀀唀匀刀开䌀 嘀䄀刀䌀䠀䄀刀⠀㄀　⤀ഀ਀Ⰰ 䀀䘀爀漀洀搀愀琀攀 搀愀琀攀琀椀洀攀ഀ਀Ⰰ 䀀琀漀搀愀琀攀 搀愀琀攀琀椀洀攀ഀ਀Ⰰ 䀀䌀䄀匀䠀开一唀 瘀愀爀挀栀愀爀⠀㈀⤀ഀ਀
,@ReportType varchar(1)-- @ReportType=1 then RecNo
						--@ReportType=2 then PayNo
 as 
 begin
 delete  FROM TMP_ACCO3136 where USR_C=@USR_C
 

 --RecNo
--**************************
 if @ReportType='2' 

	begin
		
		insert into tmp_acco3136 ( USR_C, RECIPT_NO, JRN_DATE, CASH_NU, CASH_NAME, ENT_DR_10, ENT_CR_10, JRN_NU, ENT_DES, ENT_DR, ENT_CR, CUR_NU, CUR_NAME, 
                         JRN_TYP, CASH_WAY, ACC_NU, SUB_NU)
		SELECT          @USR_C, ENTRY_10_PAY.ENT_REC2, ENTRY_10_PAY.JRN_DATE, ENTRY_10_PAY.CASH_NU, CASH_NAME.CASH_NAME,  0 AS ENT_Dr_10, 
                         ENTRY_10_PAY.ENT_CR AS ENT_Cr_10, JOURNAL.JRN_NU, ENTRY.ENT_DES,
						  (CASE WHEN entry.ENT_DR > 0 THEN (CASE WHEN entry.cur_nu = 1 THEN entry.ENT_DR ELSE entry.ent_conv END) ELSE 0 END) AS ENT_DR
						  ,(CASE WHEN entry.ENT_CR > 0 THEN (CASE WHEN entry.cur_nu = 1 THEN entry.ENT_CR ELSE ent_conv END) ELSE 0 END) as Ent_Cr, CASH_NAME.CUR_NU as CUR_NU, 
                         CUR_CODE.CUR_CODE, JRN_TYP, CASH_NAME.CASH_WAY, ENTRY.ACC_NU, ENTRY.SUB_NU
		FROM            Finance.ENTRY_10_PAY LEFT OUTER JOIN
                         Finance.ENTRY RIGHT OUTER JOIN
                         Finance.JOURNAL ON Finance.ENTRY.JRN_ID = Finance.JOURNAL.JRN_ID ON Finance.ENTRY_10_PAY.CASH_NU = Finance.JOURNAL.CASH_NU AND 
                         Finance.ENTRY_10_PAY.JRN_DATE = Finance.JOURNAL.JRN_DATE AND Finance.ENTRY_10_PAY.ENT_REC2 = Finance.ENTRY.ENT_REC1 LEFT OUTER JOIN
                         Finance.CASH_NAME INNER JOIN
                         Finance.CUR_CODE ON Finance.CASH_NAME.CUR_NU = Finance.CUR_CODE.CUR_NU ON Finance.ENTRY_10_PAY.CASH_NU = Finance.CASH_NAME.CASH_NU

		WHERE      (CASH_WAY = 1) and
					 (RECEIPT_STATUS IS NULL OR  RECEIPT_STATUS = '-')
					and	 (ENTRY_10_PAY.JRN_DATE BETWEEN @FROMDATE AND @TODATE) 
						
						AND (ENTRY_10_PAY.CASH_NU =  @CASH_NU or @CASH_NU is null)
	end
			--*************************************************************************************

else --recNo
