CREATE proc   [Finance].[SPACCO3201]
	-- Add the parameters for the stored procedure here
	@USR_C varchar(10)
	, @FmDate Datetime  
	, @ToDate Datetime  
	, @Jrn_Typ int= null 
	, @FileType varchar(5)= null 
	, @COST_TYPE  varchar(1)--C=Tourism,J=Journy
	
AS
BEGIN
	
	
	
	delete  FROM TMP_ACCO3201 WHERE USR_C=@USR_C

	insert into TMP_ACCO3201 (USR_C, ENT_INV, ENT_INVD, JRN_TYP, JRN_NU, COST_NU, COST_ARRIVAL_DATE, COST_DEPARTURE_DATE, ENT_VAL, ENT_ORG, ENT_REC,  ENT_EXT, ENT_RECD )
	SELECT      @USR_C , COST_ENT.ENT_INV, COST_ENT.ENT_INVD, JOURNAL.JRN_TYP, JOURNAL.JRN_NU,COST_ENT.COST_NU, COST.COST_ARRIVAL_DATE, 
                         COST.COST_DEPARTURE_DATE, COST_ENT.ENT_VAL, COST_ENT.ENT_ORG, COST_ENT.ENT_EXT, COST_ENT.ENT_REC, 
                         COST_ENT.ENT_RECD
	FROM            COST_ENT INNER JOIN
                         JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID INNER JOIN
                         COST ON COST_ENT.COST_NU = COST.COST_NU
	where JRN_DATE BETWEEN @FmDate AND @ToDate and COST_FLAG=@COST_TYPE
	and (JRN_TYP<> @Jrn_Typ or @Jrn_Typ is null)
	and ((COST.COST_typ = @FileType )or(@FileType is null))


	--'update Entry_type
		 update TMP_ACCO3201
		 set [JRN_TYP]= (SELECT    Finance.ENTRY_TP.JRN_TYP
		FROM            
								 Finance.ENTRY_TP where  Finance.TMP_ACCO3201.JRN_TYP = Finance.ENTRY_TP.ID and USR_C = @USR_C ) 
		WHERE   USR_C = @USR_C 
END


		














