--*************************gET data insert into tmp3202A**************************************
	-----------------------------------
			
			insert into   TMP_ACC3202A 
			SELECT @USR_C as USR_C,COST_ENT.[COST_NU] as COST_NU,JRN_DATE as DATEM,JOURNAL.JRN_TYP as JRN_TY,JRN_NU as JRN_N,
				COST_ENT.ACC_NU as ACC,COST_ENT.SUB_NU as SUB,ENTRY.ENT_DES as DES1,isnull(CST_DES,'') as [DES2],isnull(COST_ENT.ENT_REC1,'') as ENT_RE1,
				isnull(COST_ENT.ENT_REC2,'') as ENT_RE2,
				0 as ENT_VAL_HOTEL,0 as ENT_VAL_RESTURA,0 as ENT_VAL_BUS,0 as ENT_VAL_TRAIN ,0 as ENT_VAL_REPRES
				,0 as ENT_VAL_GIUDS,0 as [ENT_VAL_OTHER],0 as ENT_VAL_ERADAT,isnull(COST_ENT.ENT_REC,'') as ENT_REC,0 as ENT_VAL_7,isnull(round(COST_ENT.ENT_VAL,2),0) as ENT_VAL_7,isnull(DR_CR,1) as DR_CR
				
				
				--, '' , '' ,'' ,'' ,'' ,'' ,'' , '', '', '', '', ''
				--, '', 0 ,'', '', '', '', '' , NULL , NULL , NULL

				, TMP_A.FILED1, TMP_A.FILED2, TMP_A.FILED3, TMP_A.FILED4, TMP_A.FILED5, TMP_A.FILED6, TMP_A.FILED7, TMP_A.FILED8, TMP_A.FILED9, COST.COST_DES, 
				COST.COST_ADD, COST.COST_1ADD, COST.CUR_NU, COST.COST_CONT, COST.COST_STAT, EMP.EMP_NAME, CUR_CODE.CUR_NAME, COST.COST_FILE_NAME, 
				COST.COST_FILE_TYPE, COST.COST_EXECUTION_DATE, COST.COST_DEPARTURE_DATE, COST.COST_ARRIVAL_DATE

			FROM COST_ENT INNER JOIN JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID
						  INNER JOIN Finance.ENTRY on ENTRY.ENT_ID=COST_ENT.ENT_ID

						 -- -- new join ********************
						  INNER JOIN COST AS COST ON COST_ENT.COST_NU = COST.COST_NU 
						  INNER JOIN TMP_A AS TMP_A ON @USR_C = TMP_A.USR_C 
						  LEFT OUTER JOIN CUR_CODE AS CUR_CODE ON COST.CUR_NU = CUR_CODE.CUR_NU 
						  LEFT OUTER JOIN EMP AS EMP ON COST.EMP_CODE = EMP.EMP_CODE
