-- ================================================

CREATE proc   [Finance].[SPAcco3207]
	-- Add the parameters for the stored procedure here
	@USR_C varchar(10), @FmDate Datetime , @ToDate Datetime
	,@FileType1 varchar(3)= null 
	,@FileType2 varchar(3)= null 
	,@FileType3 varchar(3)= null 
	,@FileType4 varchar(3)= null 
	,@FileType5 varchar(3)= null 
	,@FileType6 varchar(3)= null 
	,@FileType7 varchar(3)= null 
	,@FileType8 varchar(3)= null 
	,@CstAccount real= null
	,@CstSubAccount real= null

	, @RepType real = null
	, @Average real = null
	, @ProfLosses real = null -- ارباح وخسارة 
	, @COST_TYPE  varchar(1)--C=Tourism,J=Journy
	
AS
BEGIN
	

    -- Insert statements for procedure here
	delete  FROM TMP_ACC3207 WHERE USR_C=@USR_C
	delete  FROM TMP_INC_EXPN WHERE USR_C=@USR_C
	
	
	--1
	INSERT INTO TMP_INC_EXPN 
	select @USR_C AS USR_C, c.COST_NU AS COST_NU,
	sum(abs(isnull(c.ENT_VAL,0))) as ENT_VAL,'1' AS INC_FLG 
    from cost_ent as c
	join entry as e on e.ENT_ID = C.ENT_ID 
	INNER JOIN  COST ON c.COST_NU = COST.COST_NU
	-----------------
	where e.ent_cr > 0 
	And COST_FLAG =@COST_TYPE
	and COST_EXECUTION_DATE BETWEEN @FmDate AND @ToDate 
	and (
		(COST.COST_typ in( @FileType1 , @FileType2 , @FileType3, @FileType4, @FileType5, @FileType6, @FileType7, @FileType8 ) 
		or (@FileType1 is null and @FileType2 is null and @FileType3 is null and @FileType4 is null and @FileType5 is null and @FileType6 is null and @FileType7 is null and @FileType8 is null ) 
		)
