  and ((subString(convert(varchar,e.ACC_NU),1,2) in (select subString(convert(varchar,cus_tours_rev),1,2) from sys_data))or (subString(convert(varchar,e.ACC_NU),1,2) in (select subString(convert(varchar,cus_JOURNEY_rev),1,2) from sys_data))) group by c.COST_NU 
 
 
