 --5
 insert into TMP_ACC3207  
	SELECT        @USR_C AS USR_C, Cost.COST_NU, COST_STAT AS stat, 0 AS amt, 0 AS SAL,
                             cc.ent_val3 + cc.ent_val4 *-1 AS W_TOT_1
                            ,  cc.ent_val1 + cc.ent_val2 *-1 AS W_TOT_2, COST_DES AS DES, 
                         COST_FILE_NAME AS CST, '' AS FATORA, emp.EMP_CODE AS empcode, EMP_NAME as empName
	FROM             COST
				INNER JOIN  EMP ON COST.EMP_CODE = EMP.EMP_CODE
				inner Join (SELECT        COST_NU, ent_val1, ent_val2, ent_val3, ent_val4
							FROM            (
						   SELECT         TMP_INC_EXPN.COST_NU, SUM(CASE WHEN INC_FLG = 1 THEN (isnull(ent_val, 0)) ELSE 0 END) AS ent_val1, 
										 SUM(CASE WHEN INC_FLG = 2 THEN isnull(ent_val, 0) ELSE 0 END) AS ent_val2, SUM(CASE WHEN INC_FLG = 3 THEN isnull(ent_val, 0) ELSE 0 END) AS ent_val3, 
										 SUM(CASE WHEN INC_FLG = 4 THEN isnull(ent_val, 0) ELSE 0 END) AS ent_val4
							FROM            COST INNER JOIN
													 TMP_INC_EXPN ON COST.COST_NU = TMP_INC_EXPN.COST_NU
							WHERE         TMP_INC_EXPN.USR_C = @USR_C
							GROUP BY TMP_INC_EXPN.COST_NU
						   ) as pp) as cc on cc.cost_nu=Cost.cost_nu

	WHERE  
	 COST_FLAG =@COST_TYPE
    And COST_EXECUTION_DATE BETWEEN @FmDate AND @ToDate 
