		DELETE from TMP_ACC3207 where  ( (W_Tot_1 <> 0 ) or  (W_Tot_2 <> 0 )) and usr_c = @USR_C -- {TMP_ACC3207.W_Tot_1} =0 and {TMP_ACC3207.W_Tot_2} =0"
	END
	
	IF @RepType = 5
	BEGIN
		DELETE from TMP_ACC3207 where W_Tot_1 <= W_Tot_2  and usr_c=@USR_C -- {TMP_ACC3207.W_Tot_1} > {TMP_ACC3207.W_Tot_2}
	END
	
	IF @Average IS NOT NULL AND  @Average <> 0
	BEGIN
	
		-- if Prof  Grater Than delete in all cases 
		IF @ProfLosses = 1 
		BEGIN
			DELETE FROM TMP_ACC3207 WHERE usr_c = @USR_C AND TMP_ACC3207.W_Tot_2 = 0  
		END

		IF @Average > 0 
		BEGIN --- Prof
					IF @ProfLosses = 1 
					BEGIN
						DELETE from  TMP_ACC3207 where  usr_c = @USR_C   and   (case when W_Tot_2=0 then 0 else  (((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2)) end )  <  @Average
					END 
					ELSE 
					BEGIN
						DELETE from  TMP_ACC3207 where  usr_c = @USR_C   and   (case when W_Tot_2=0 then 0 else  (((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2)) end )  >  @Average or @Average < 0
					END
		END

		ELSE  ---- Loss
		BEGIN
					IF @ProfLosses = 1 
					BEGIN
						DELETE from  TMP_ACC3207 
						where  usr_c = @USR_C  
						and  (( (case when W_Tot_2=0 then 0 else  (ABS((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2)) end ) <  ABS(@Average) ) 
						or ((case when W_Tot_2=0 then 0 else (W_Tot_2 - W_Tot_1 )*100 / W_Tot_2 end))  >= 0 )
					END 
					ELSE 
					BEGIN
						DELETE from  TMP_ACC3207 
						where  usr_c = @USR_C  
						and  (( (case when W_Tot_2=0 then 0 else  (ABS((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2)) end ) >  ABS(@Average) ) 
						or ((case when W_Tot_2=0 then 0 else (W_Tot_2 - W_Tot_1 )*100 / W_Tot_2 end))  > 0 )
						--DELETE from  TMP_ACC3207 where  usr_c = @USR_C and W_Tot_2<>0  and  ((abs((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2) >  ABS( @Average) ) or ((W_Tot_2 - W_Tot_1 )*100 / W_Tot_2)  > 0 )
					END
			
END
 
END

 
