	,@ToDepDate Datetime = null 

	,@FromArrDate Datetime  = null 
	,@ToArrDate Datetime = null 

	,@FileType varchar(3)= null 
	,@EmpCode varchar(10)= null 

	,@ReportType  int = null 

	,@Acounting int = null 
	,@Process int = null 
	,@Canceled int = null 
	,@Execution int = null 
	,@CULT varchar(10)= null 
	 , @COST_TYPE  varchar(1)--C=Tourism,J=Journy

AS
BEGIN
    -- Insert statements for procedure here
	delete  FROM TMP_ACCO3209 WHERE USR_C=@USR_C

	if @ReportType <> 1
	begin 
	if @FromDepDate is not null and @FromArrDate is  null 
		begin 

		insert into  TMP_ACCO3209 
		SELECT   @USR_C AS USR_C, COST.COST_NU, COST.COST_CONT, COST.COST_DES, COST.EMP_CODE, COST.COST_ARRIVAL_DATE AS COST_A_DT, COST_DEPARTURE_DATE AS COST_D_DT, '' AS Notes , EMP_NAME as EMP_NAME , COST_STAT as COST_STAT
			FROM  COST 
			INNER JOIN  EMP ON COST.EMP_CODE = EMP.EMP_CODE
			WHERE COST_DEPARTURE_DATE BETWEEN  @FromDepDate AND @ToDepDate AND COST_STAT <> '2' 
				And COST_FLAG =@COST_TYPE
				  and ((cost_stat in( @Acounting , @Process , @Canceled, @Execution) 
				  and  ((COST.COST_typ = @FileType )or(@FileType is null)) and ((cost.emp_code =@EmpCode)or  @EmpCode is null) 
					or (@Acounting is null and @Process is null and @Canceled is null and @Execution is null)))
			and COST_NU not IN
                       (SELECT COST.COST_NU FROM COST  
					   INNER JOIN COST_ENT ON COST_ENT.COST_NU = COST.COST_NU 
					   INNER JOIN ENTRY ON COST_ENT.ENT_ID = ENTRY.ENT_ID 
					   INNER JOIN JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID AND ENTRY.JRN_ID = JOURNAL.JRN_ID 
						where  ENTRY.Ent_Cr <> 0 And COST_FLAG =@COST_TYPE and  ((substring(convert(varchar,COST_ENT.ACC_NU),1,2)= (select CUS_TOURS_REV from SYS_DATA) ) or   substring(convert(varchar,COST_ENT.ACC_NU),1,2)= (select CUS_JOURNEY_REV from SYS_DATA)))

		end
		else 
		if @FromDepDate is  null and @FromArrDate is not null 
		begin 
				insert into  TMP_ACCO3209 
		SELECT   @USR_C AS USR_C, COST.COST_NU, COST.COST_CONT, COST.COST_DES, COST.EMP_CODE, COST.COST_ARRIVAL_DATE AS COST_A_DT, COST_DEPARTURE_DATE AS COST_D_DT, '' AS Notes , EMP_NAME as EMP_NAME , COST_STAT as COST_STAT
			FROM  COST 
