	else 
	begin 
	if @FromDepDate is not null and @FromArrDate is  null 
		begin 
		insert into  TMP_ACCO3209 
		 SELECT        @USR_C AS USR_C, cost.COST_NU, COST.COST_CONT, COST.COST_DES, COST.EMP_CODE AS EMP_CODE, 
							 cost.COST_ARRIVAL_DATE AS COST_A_DT, cost.COST_DEPARTURE_DATE AS COST_D_DT , '' as Notes , EMP_NAME as EMP_NAME , COST_STAT as COST_STAT
							 FROM  COST 
							 INNER JOIN  EMP ON COST.EMP_CODE = EMP.EMP_CODE
							 left outer join INVOICE_B
							 ON Finance.INVOICE_B.COST_NU = Finance.COST.COST_NU 
							 where INVOICE_B.COST_NU  is null and  cost.COST_DEPARTURE_DATE BETWEEN @FromDepDate AND @ToDepDate  
								And COST.COST_FLAG =@COST_TYPE AND [COST_STAT]<>'2' and  ((COST.COST_typ = @FileType )or(@FileType is null)) and ((cost.emp_code =@EmpCode)or  @EmpCode is null) 
								  and ((cost_stat in( @Acounting , @Process , @Canceled, @Execution) 
								or (@Acounting is null and @Process is null and @Canceled is null and @Execution is null) ))  

						--and cost_stat in ('1','0','3','2')
		end
		
		else 
		 if @FromDepDate is  null and @FromArrDate is not null 
		 begin
		 insert into  TMP_ACCO3209 
