	delete  FROM TMP_Ent WHERE USR_C=@USR_C
	

	--2
	INSERT INTO TMP_ENT 
	SELECT 
	@USR_C AS USR_C, 
	SUM(abs(ISNULL(A.ENT_VAL,0))) AS W_TOT_1, 
	SUM(abs(ISNULL(A.ENT_VAL,0))) AS W_TOT_2,
	A.COST_NU			AS COST_NU, 
	B.ACC_NU			AS ACC_NU,  
	abs(ISNULL(B.ENT_DR,0))		AS ENT_DR, 
	abs(ISNULL(B.ENT_CR,0))		AS ENT_CR, 
	B.ENT_FLG			AS ENT_FLG 
	 
	FROM COST_ENT A 
		 INNER JOIN ENTRY B ON A.Ent_Id = B.Ent_Id 
		 INNER JOIN  COST ON A.COST_NU = COST.COST_NU
		 INNER JOIN  Journal ON B.Jrn_Id = Journal.Jrn_Id   
	 
	 WHERE 
	  cost.COST_FLAG =@COST_TYPE 
		and ((COST_EXECUTION_DATE	BETWEEN		@FmExDate AND @ToExDate )or(@FmExDate is null)or(@ToExDate is null))
	 AND((JRN_DATE				 BETWEEN	@FmTrDate AND @ToTrDate )or(@FmTrDate is null)or(@ToTrDate is null))
	   
	 AND 
	  (
	  ((COST.COST_typ = @FileType1 )or(@FileType1 is null))
	or((COST.COST_typ = @FileType2 )or(@FileType2 is null))
	or((COST.COST_typ = @FileType3 )or(@FileType3 is null))
	or((COST.COST_typ = @FileType4 )or(@FileType4 is null))
	or((COST.COST_typ = @FileType5 )or(@FileType5 is null))
	or((COST.COST_typ = @FileType6 )or(@FileType6 is null))
	or((COST.COST_typ = @FileType7 )or(@FileType7 is null))
	or((COST.COST_typ = @FileType8 )or(@FileType8 is null))
	)
	 
	 
	 AND ((cost.COST_Nu BETWEEN @FmCostNu and @ToCostNu )or(@FmCostNu is null)or(@ToCostNu is null))
	 GROUP BY A.COST_NU, JRN_TYP, JRN_DATE, JRN_NU, COST_id, B.ACC_NU, B.ENT_DR, B.ENT_CR, B.ENT_FLG

	--3
	update TMP_ENT set W_TOT_1=W_TOT_1 * 1 , W_TOT_2=0 where
	 ((SUBSTRING(convert(varchar,ACC_NU),1,2)='31') or (SUBSTRING(convert(varchar,ACC_NU),1,2)='0') ) 
	 and ent_dr>0 AND USR_C=@USR_C


	--4
	update TMP_ENT set W_TOT_1=W_TOT_1 * -1 , W_TOT_2=0 where 
	((SUBSTRING(convert(varchar,ACC_NU),1,2)='31') or (SUBSTRING(convert(varchar,ACC_NU),1,2)='0'))
	 and ent_dr<=0 AND USR_C=@USR_C


	--5
	update TMP_ENT set W_TOT_1=0 , W_TOT_2=W_TOT_2 * 1 where 
	((SUBSTRING(convert(varchar,ACC_NU),1,2)='41') or (SUBSTRING(convert(varchar,ACC_NU),1,2)='0') ) 
	and ent_cr>0 AND USR_C=@USR_C


