		update TMP_ENT set W_TOT_1=0 , W_TOT_2=W_TOT_2 * -1 where 
ਊऀऀ⠀⠀匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㴀✀㐀㄀✀⤀ 漀爀 ⠀匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㴀✀　✀⤀  ⤀ ഀ਀ऀऀ愀渀搀 攀渀琀开挀爀㰀㴀　 䄀一䐀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ऀऀഀ਀ऀⴀⴀ㜀ഀ਀ऀऀ搀攀氀攀琀攀 昀爀漀洀 吀䴀倀开䔀一吀 眀栀攀爀攀 匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㰀㸀✀㌀㄀✀ 愀渀搀 ഀ਀ऀऀ匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㰀㸀✀㐀㄀✀ 愀渀搀 匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㰀㸀✀　✀ ഀ਀ऀऀ愀渀搀 匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀㰀㸀✀　✀  䄀一䐀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ഀ਀ऀⴀⴀ㠀ഀ਀ऀ䤀一匀䔀刀吀 䤀一吀伀 吀䴀倀开䄀䌀䌀㌀㈀㄀　 猀攀氀攀挀琀 䀀唀匀刀开䌀 愀猀 唀匀刀开䌀Ⰰ䌀伀匀吀开一唀Ⰰ圀开吀伀吀开㄀Ⰰ圀开吀伀吀开㈀Ⰰ✀✀ 愀猀 䌀匀吀Ⰰ　 愀猀 䌀匀吀开䌀伀一吀Ⰰ✀　㄀⼀　㄀⼀㄀㤀㤀　✀ ഀ਀ऀ愀猀 䌀伀匀吀开䐀䄀吀䔀Ⰰ　 愀猀 一漀倀攀爀刀漀洀 䘀刀伀䴀 吀䴀倀开䔀一吀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ഀ਀ऀⴀⴀ㤀ഀ਀ऀ搀攀氀攀琀攀 昀爀漀洀 吀䴀倀开䄀䌀䌀㌀㈀㄀　 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀匀刀开䌀 ഀ਀ऀ愀渀搀 渀漀琀 ⠀䌀伀匀吀开一唀 戀攀琀眀攀攀渀 䀀䘀洀䌀漀猀琀一甀 䄀一䐀 䀀吀漀䌀漀猀琀一甀⤀ഀ਀ഀ਀ऀⴀⴀ㄀　ഀ਀ऀ唀倀䐀䄀吀䔀 吀䴀倀开䄀䌀䌀㌀㈀㄀　 猀攀琀 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀䌀匀吀㴀䌀伀匀吀⸀䌀伀匀吀开䘀䤀䰀䔀开一䄀䴀䔀 Ⰰ 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀䌀匀吀开䌀伀一吀㴀䌀伀匀吀⸀䌀伀匀吀开䌀伀一吀 Ⰰഀ਀ऀ 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀䌀伀匀吀开䐀䄀吀䔀㴀䌀伀匀吀⸀䌀伀匀吀开䔀堀䔀䌀唀吀䤀伀一开䐀䄀吀䔀 昀爀漀洀  䌀伀匀吀 圀䠀䔀刀䔀 挀漀猀琀⸀䌀伀匀吀开䘀䰀䄀䜀 㴀䀀䌀伀匀吀开吀夀倀䔀  愀渀搀 ഀ਀ऀ  吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀䌀伀匀吀开一唀㴀䌀伀匀吀⸀䌀伀匀吀开一唀 䄀一䐀 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ഀ਀ऀⴀⴀ㄀㄀ഀ਀ऀ唀倀䐀䄀吀䔀 吀䴀倀开䄀䌀䌀㌀㈀㄀　 猀攀琀 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀一漀倀攀爀刀漀洀㴀⠀䐀愀琀攀䐀椀昀昀⠀䐀䐀Ⰰ䌀伀匀吀⸀䌀伀匀吀开䄀刀刀䤀嘀䄀䰀开䐀䄀吀䔀 Ⰰ䌀伀匀吀⸀䌀伀匀吀开䐀䔀倀䄀刀吀唀刀䔀开䐀䄀吀䔀⤀⤀⨀䌀伀匀吀开䌀伀一吀开䄀䌀䌀伀䴀 ഀ਀ऀ昀爀漀洀 䌀伀匀吀 圀䠀䔀刀䔀 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀䌀伀匀吀开一唀㴀䌀伀匀吀⸀䌀伀匀吀开一唀 䄀一䐀 吀䴀倀开䄀䌀䌀㌀㈀㄀　⸀唀匀刀开䌀㴀䀀唀匀刀开䌀 愀渀搀 挀漀猀琀⸀䌀伀匀吀开䘀䰀䄀䜀 㴀䀀䌀伀匀吀开吀夀倀䔀 ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ⴀⴀ 匀倀 䔀渀搀ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㈀㄀㌀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀   嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㈀㄀㌀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀ䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀洀䐀愀琀攀 䐀愀琀攀琀椀洀攀 ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀䔀洀瀀䌀漀搀攀 瘀愀爀挀栀愀爀⠀㄀　⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㄀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㈀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㌀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㐀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㔀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㘀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㜀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㠀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㄀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㈀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㌀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㐀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㔀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㘀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㜀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㠀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀
	, @COST_TYPE  varchar(1)--C=Tourism,J=Journy
AS
BEGIN
	

    -- Insert statements for procedure here
	delete  FROM TMP_ACC3213 WHERE USR_C=@USR_C
	delete  FROM TMP_INC_EXPN WHERE USR_C=@USR_C
		--1
INSERT INTO TMP_INC_EXPN 

select 
@USR_C AS USR_C,
c.COST_NU AS COST_NU,
sum(c.ENT_VAL) as ENT_VAL,
'1' AS INC_FLG 

from  cost_ent as c 
JOIN entry as e ON e.ENT_ID = C.ENT_ID
INNER JOIN  COST ON c.COST_NU = COST.COST_NU

WHERE 

 e.ent_cr > 0 
 And COST_FLAG =@COST_TYPE
AND(
	--(([COST_NU] like + '%' + @FileType1 + '%')or(@FileType1 is null))	or(([COST_NU] like + '%' + @FileType2 + '%')or(@FileType2 is null))	or(([COST_NU] like + '%' + @FileType3 + '%')or(@FileType3 is null))	or(([COST_NU] like + '%' + @FileType4 + '%')or(@FileType4 is null))	or(([COST_NU] like + '%' + @FileType5 + '%')or(@FileType5 is null))	or(([COST_NU] like + '%' + @FileType6 + '%')or(@FileType6 is null))or(([COST_NU]like + '%' + @FileType7 + '%')or(@FileType7 is null))or(([COST_NU] like + '%' + @FileType8 + '%')or(@FileType8 is null))
	  ((COST.COST_typ = @FileType1 )or(@FileType1 is null))
	or((COST.COST_typ = @FileType2 )or(@FileType2 is null))
	or((COST.COST_typ = @FileType3 )or(@FileType3 is null))
	or((COST.COST_typ = @FileType4 )or(@FileType4 is null))
	or((COST.COST_typ = @FileType5 )or(@FileType5 is null))
	or((COST.COST_typ = @FileType6 )or(@FileType6 is null))
	or((COST.COST_typ = @FileType7 )or(@FileType7 is null))
	or((COST.COST_typ = @FileType8 )or(@FileType8 is null))
	)
	AND ((COST.COST_TYP <> @FileNotType1 )or(@FileNotType1 is null))
	AND((COST.COST_TYP <> @FileNotType2 )or(@FileNotType2 is null))
	AND((COST.COST_TYP <> @FileNotType3 )or(@FileNotType3 is null))
	AND((COST.COST_TYP <> @FileNotType4 )or(@FileNotType4 is null))
	AND((COST.COST_TYP <> @FileNotType5 )or(@FileNotType5 is null))
	AND((COST.COST_TYP <> @FileNotType6 )or(@FileNotType6 is null))
	AND((COST.COST_TYP <> @FileNotType7 )or(@FileNotType7 is null))
	AND((COST.COST_TYP <> @FileNotType8 )or(@FileNotType8 is null))
		 
		 
		 and c.COST_NU in (select distinct(cost.COST_NU) from COST where   
		 COST_EXECUTION_DATE BETWEEN @FmDate AND @ToDate 
