	    	--
	   (((JRN_TYP =  @EntryType1 )or(@EntryType1 is null))
		or((JRN_TYP = @EntryType2 )or(@EntryType2 is null))
		or((JRN_TYP = @EntryType3)or(@EntryType3 is null))
		or((JRN_TYP = @EntryType4 )or(@EntryType4 is null))
		or((JRN_TYP = @EntryType5 )or(@EntryType5 is null))
		or((JRN_TYP = @EntryType6 )or(@EntryType6 is null))
		or((JRN_TYP = @EntryType7 )or(@EntryType7 is null)))
	   --
