		AND  ((JRN_TYP <> @notEntryType2 )or(@notEntryType2 is null))
		AND  ((JRN_TYP <> @notEntryType3)or(@notEntryType3 is null))
		AND  ((JRN_TYP <> @notEntryType4 )or(@notEntryType4 is null))
		AND  ((JRN_TYP <> @notEntryType5 )or(@notEntryType5 is null))
		AND  ((JRN_TYP <> @notEntryType6 )or(@notEntryType6 is null))
		AND  ((JRN_TYP <> @notEntryType7 )or(@notEntryType7 is null)
	    )
	    --
