--2
	INSERT INTO TMP_INC_EXPN select @USR_C AS USR_C,c.COST_NU AS COST_NU
	, sum(c.ENT_VAL) as ENT_VAL,'2' AS INC_FLG 
	
FROM JOURNAL AS J 
LEFT OUTER JOIN ENTRY AS E ON J.JRN_ID = E.JRN_ID 
--LEFT OUTER JOIN ENTRY_TP ON J.JRN_TYP = ID 
LEFT OUTER JOIN COST_ENT AS C ON J.JRN_ID = C.JRN_ID AND E.ENT_ID = C.ENT_ID
                      
where
	 e.ent_dr > 0  AND  c.COST_NU
	 in (select distinct(cost.COST_NU) from COST 
	 where  COST_FLAG =@COST_TYPE and ( COST_EXECUTION_DATE BETWEEN @FmExDate AND @ToExDate  
	 and  
	 (([CST_ACC_NU]=@MainAcc) or (@MainAcc is null)) 
	 and  
	 ((cost.CST_SUB_NU=@CstAcc) or (@CstAcc is null))
AND(( COST.COST_TYP =@FileType ) or (@FileType is null))
	 AND(( COST.EMP_CODE =@EmpCode ) or (@EmpCode is null))
	 ))
