-- ================================================

CREATE proc   [Finance].[SPAcco3215]
	-- Add the parameters for the stored procedure here
	 @USR_C varchar(10)
	,@FmDate Datetime 
	,@FileType varchar(3)
	,@DatePenalty Datetime= null 
	,@DateType varchar(10)= null 
	,@FileStatus varchar(10)= null 
	,@EmpCode varchar(10)= null 
	,@InvoiceStatus varchar(10)= null 
	,@AllowedDays int= null 
	, @COST_TYPE  varchar(1)--C=Tourism,J=Journy
AS
BEGIN

    -- Insert statements for procedure here
	declare @SysDate datetime 
	declare @INV_FLG int
	declare @RsCstInv int 
	declare @Date_Compar varchar(10)
	declare @Date_Compar_Inv varchar(10)
	
	
--1
	delete  FROM TMP_ACC3215 WHERE USR_C=@USR_C

	-- Select Date from sys_data
	set @SysDate = ( select DBASE_DATE from ADATABASE_VER )

--

 DECLARE tCost_Nu_cursor CURSOR FOR    
		SELECT  Cost_Nu   FROM COST    
		where  COST_FLAG =@COST_TYPE and COST_DEPARTURE_DATE >= @FmDate
			  AND COST_DEPARTURE_DATE <= @SysDate  
			  and  [COST_NU] LIKE  '%'+ @FileType +'%'
													
 
OPEN tCost_Nu_cursor  DECLARE @Cost_Nu varchar (15) 

FETCH NEXT FROM tCost_Nu_cursor INTO @Cost_Nu
WHILE (@@FETCH_STATUS <> -1) 
BEGIN  

--3
	INSERT INTO TMP_ACC3215
		SELECT @USR_C AS USR_C
		,@Cost_Nu as COST_FIL  
		, cost.EMP_CODE as EMP_CODE 
		, COST_ARRIVAL_DATE  as COST_ARRIVAL_DATE
		, COST_DEPARTURE_DATE as COST_DEPARTURE_DATE 

		, COST_STAT as  COST_STAT
		, EMP_NAME as EMP_NAME
		
		,0  as COST_DIFF
		, '01/01/2014' as  INV_DAT
		
		, '01/01/1990' as  INV_ON_CONF
		, '01/01/1990' as  INV_Alter
		, 1 as INV_NO
		, 1 as FLG 
		 
		 from  COST
			INNER JOIN  EMP ON COST.EMP_CODE = EMP.EMP_CODE
ਊऀऀ  眀栀攀爀攀 挀漀猀琀开渀甀㴀䀀挀漀猀琀开渀甀 愀渀搀 䌀伀匀吀开䘀䰀䄀䜀 㴀䀀䌀伀匀吀开吀夀倀䔀 ഀ਀ऀഀ਀ऀ䘀䔀吀䌀䠀 一䔀堀吀 䘀刀伀䴀 琀䌀漀猀琀开一甀开挀甀爀猀漀爀 䤀一吀伀 䀀䌀漀猀琀开一甀 ഀ਀ऀഀ਀䔀一䐀 ഀ਀ഀ਀䌀䰀伀匀䔀 琀䌀漀猀琀开一甀开挀甀爀猀漀爀 ഀ਀䐀䔀䄀䰀䰀伀䌀䄀吀䔀 琀䌀漀猀琀开一甀开挀甀爀猀漀爀 ഀ਀ഀ਀   ഀ਀   ഀ਀   ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㈀㄀㘀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀   嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㈀㄀㘀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀ 䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀夀攀愀爀 椀渀琀㴀 渀甀氀氀 ഀ਀ഀ਀ऀⰀ 䀀䴀漀渀琀栀 椀渀琀㴀 渀甀氀氀 ഀ਀ऀഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㄀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㈀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㌀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㐀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㔀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㘀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㜀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀吀礀瀀攀㠀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀഀ਀ऀഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㄀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㈀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㌀ 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㐀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㔀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㘀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㜀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ䀀䘀椀氀攀一漀琀吀礀瀀攀㠀 瘀愀爀挀栀愀爀⠀㌀⤀㴀 渀甀氀氀 ഀ਀ऀഀ਀ऀഀ਀ऀⰀ 䀀䌀漀猀琀吀礀瀀攀㄀ 瘀愀爀挀栀愀爀⠀㄀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ 䀀䌀漀猀琀吀礀瀀攀㈀ 瘀愀爀挀栀愀爀⠀㄀⤀㴀 渀甀氀氀 ഀ਀ऀⰀ 䀀䌀漀猀琀吀礀瀀攀㌀ 瘀愀爀挀栀愀爀⠀㄀⤀㴀 渀甀氀氀 ഀ਀ऀഀ਀ऀⰀ䀀䘀椀氀攀倀吀礀瀀攀 瘀愀爀挀栀愀爀⠀㄀⤀㴀渀甀氀氀ഀ਀ऀഀ਀ऀⰀ䀀䌀猀琀䄀挀挀漀甀渀琀 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀䌀猀琀匀甀戀䄀挀挀漀甀渀琀㄀ 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀䌀猀琀匀甀戀䄀挀挀漀甀渀琀㈀ 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀䌀猀琀匀甀戀䄀挀挀漀甀渀琀㌀ 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀䌀猀琀匀甀戀䄀挀挀漀甀渀琀㐀 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀䌀猀琀匀甀戀䄀挀挀漀甀渀琀㔀 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀഀ਀ऀⰀ䀀刀攀瘀䄀挀挀漀甀渀琀 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ䀀刀攀瘀匀甀戀䄀挀挀漀甀渀琀 爀攀愀氀㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䌀伀匀吀开吀夀倀䔀  瘀愀爀挀栀愀爀⠀㄀⤀ⴀⴀ䌀㴀吀漀甀爀椀猀洀Ⰰ䨀㴀䨀漀甀爀渀礀ഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀ഀ਀ऀऀ搀攀挀氀愀爀攀 䀀䈀䜀䐀䄀吀䔀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䔀渀搀䐀愀琀攀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䴀礀䘀椀氀攀吀礀瀀攀䌀漀渀搀 瘀愀爀挀栀愀爀⠀㌀　　⤀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䴀礀䘀椀氀攀吀礀瀀攀一漀琀䌀漀渀搀 瘀愀爀挀栀愀爀⠀㌀　　⤀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䴀礀䄀挀挀漀甀渀琀䌀漀渀搀 瘀愀爀挀栀愀爀⠀㌀　　⤀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䴀礀刀攀瘀䄀挀挀漀甀渀琀一漀琀䌀漀渀搀 瘀愀爀挀栀愀爀⠀㌀　　⤀ഀ਀ഀ਀ऀഀ਀ऀ搀攀挀氀愀爀攀 䀀䰀䤀一一伀 椀渀琀ഀ਀ऀ猀攀琀  䀀䰀䤀一一伀㴀㄀ഀ਀ऀഀ਀ऀ搀攀挀氀愀爀攀 䀀䤀渀挀漀洀攀倀 爀攀愀氀ഀ਀ऀ搀攀挀氀愀爀攀 䀀䤀渀挀漀洀攀䴀 爀攀愀氀ഀ਀ऀ猀攀琀 䀀䤀渀挀漀洀攀倀 㴀　ഀ਀ऀ猀攀琀 䀀䤀渀挀漀洀攀䴀 㴀　ഀ਀ഀ਀   ⴀⴀ✀ⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀⴀഀ਀ഀ਀ऀഀ਀ऀⴀⴀⴀⴀⴀⴀⴀ㄀ⴀ攀洀瀀琀椀礀 琀洀瀀ഀ਀ऀ搀攀氀攀琀攀  䘀刀伀䴀 吀䴀倀开䄀䌀䌀㌀㈀㄀㘀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ऀഀ਀ऀⴀⴀ⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀ഀ਀ऀ搀攀挀氀愀爀攀 䀀挀甀猀开琀漀甀爀猀开爀攀瘀  爀攀愀氀㴀 渀甀氀氀ഀ਀
	set @cus_tours_rev  =(select subString(convert(varchar,cus_tours_rev),1,2) from sys_data)

	declare @cus_JOURNEY_rev  real= null
	set  @cus_JOURNEY_rev = ( select subString(convert(varchar,cus_JOURNEY_rev),1,2) from sys_data)
	  
	declare @COST_FILE_NAME varchar(30)
	declare @COST_ARRIVAL_DATE datetime
	declare @COST_DEPARTURE_DATE datetime

	declare @COST_CONT real
	declare @COST_EXECUTION_DATE datetime
	--*******************************
		insert Into TMP_ACC3216 ( USR_C, LINNO, COST_NU, COST_CST, COST_A_DT, COST_D_DT, COST_CONT, TOT_NGHT, TOT_SRV, COST_MNTH
						,COST_CONT_ACCOM,COST_FILE_NAME,COST_NAT		)
		SELECT        @USR_C AS Usr_C, 1 AS LINNO
		, cost.COST_NU,  COST.COST_FILE_NAME,  COST.COST_ARRIVAL_DATE,  COST.COST_DEPARTURE_DATE, 
                          COST.COST_CONT, 0 AS Tot_Nght,
						ISNULL(SUM(CASE WHEN isnull(ENT_CR, 0) > 0  AND ((subString(convert(varchar,c.ACC_NU),1,2) in (@cus_tours_rev)) or (subString(convert(varchar,c.ACC_NU),1,2) in (@cus_JOURNEY_rev)) ) THEN c.ent_val ELSE 0 END), 0) - ISNULL(SUM(CASE WHEN isnull(ENT_DR, 0) > 0 AND ((subString(convert(varchar,c.ACC_NU),1,2) in (@cus_tours_rev)) or (subString(convert(varchar,c.ACC_NU),1,2) in (@cus_JOURNEY_rev)) ) THEN c.ent_val ELSE 0 END)
						, 0) 
						 
						 
						 AS Tot_Svr,  COST.COST_EXECUTION_DATE,COST_CONT_ACCOM,COST_FILE_NAME,COST_NAT
		FROM             COST_ENT AS c INNER JOIN
								  ENTRY AS e ON c.ENT_ID = e.ENT_ID RIGHT OUTER JOIN
								  COST ON c.COST_NU =  COST.COST_NU
								  INNER JOIN COST_NATIONALITY ON COST_NATIONALITY.NAT_ID = COST.NAT_ID
		where	 COST.COST_STAT <> '2'  
				And COST.COST_FLAG =@COST_TYPE
				and month(COST_EXECUTION_DATE) =@Month
				and year(COST_EXECUTION_DATE) =@Year
		 		and (
				( COST_TYP in( @FileType1 , @FileType2 , @FileType3, @FileType4, @FileType5, @FileType6, @FileType7, @FileType8) 
				or (@FileType1 is null and @FileType2 is null and @FileType3 is null and @FileType4 is null and @FileType5 is null and @FileType6 is null and @FileType7 is null and @FileType8 is null) 
				)
				) 			 						
				and  (UPPER(COST_TYP) <> @FileNotType1 or @FileNotType1 is null)
				and  (UPPER(COST_TYP) <> @FileNotType2 or @FileNotType2 is null)
