漀 吀䴀倀开䄀 ⠀唀匀刀开䌀Ⰰ䘀䤀䰀䔀䐀㄀Ⰰ䘀䤀䰀䔀䐀㈀⤀ 瘀愀氀甀攀猀 ⠀䀀唀匀刀开䌀 Ⰰ䀀䘀洀吀爀䐀愀琀攀Ⰰ䀀吀漀吀爀䐀愀琀攀⤀ഀ਀ⴀⴀ㌀ഀ਀ ഀ਀椀渀猀攀爀琀 椀渀琀漀 吀䴀倀开䄀䌀䌀㌀㈀㄀㜀 ⠀唀匀刀开䌀Ⰰ䨀刀一开䐀䄀吀䔀Ⰰ䨀刀一开一唀Ⰰ䨀刀一开吀夀倀Ⰰ䌀匀吀开䐀䔀匀Ⰰ䔀一吀开嘀䄀䰀Ⰰ䌀伀匀吀开一唀Ⰰ䔀一吀开䐀䔀匀Ⰰ䔀一吀开䐀刀Ⰰ䔀一吀开䌀刀Ⰰ䄀䌀䌀开一唀Ⰰ匀唀䈀开一唀ഀ਀
					, COST_ADD , COST_1ADD  , COST_FILE_NAME,  COST_CONT ,  COST_ARRIVAL_DATE ,  COST_DEPARTURE_DATE
					, COST_EXECUTION_DATE , COST_FILE_TYPE ,  COST_STAT ,  CUR_NAME ,  EMP_NAME
					 , SUB_NM_A , SUB_NM_E , ACC_NM_A , ACC_NM_E
)
 
SELECT @USR_C,
	 JOURNAL.JRN_DATE, 
	 JOURNAL.JRN_NU, 
	 ENTRY_TP.JRN_TYP, 
	 COST.COST_DES,
	 COST_ENT.ENT_VAL, 
	 COST_ENT.COST_NU, 
	 ENTRY.ENT_DES, 
	 ENTRY.ENT_DR,
	 ENTRY.ENT_CR , 
	 ENTRY.ACC_NU, 
	 ENTRY.SUB_NU , 

	COST.COST_ADD ,
	COST.COST_1ADD ,
	COST.COST_FILE_NAME ,
	COST.COST_CONT ,
	COST.COST_ARRIVAL_DATE ,
	COST.COST_DEPARTURE_DATE ,
	COST.COST_EXECUTION_DATE ,
	COST.COST_FILE_TYPE ,
	COST.COST_STAT ,

	 CUR_CODE.CUR_NAME  ,
	 EMP.EMP_NAME ,

	 SUB_ACC.SUB_NM_A ,
	 SUB_ACC.SUB_NM_E ,
	 MAIN_ACC.ACC_NM_A ,
	 MAIN_ACC.ACC_NM_E

FROM  ENTRY 
	INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID 
	INNER JOIN COST_ENT ON ENTRY.ENT_ID = COST_ENT.ENT_ID AND JOURNAL.JRN_ID = COST_ENT.JRN_ID
	INNER JOIN ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID
	INNER JOIN COST ON COST_ENT.COST_NU = COST.COST_NU
	INNER JOIN CUR_CODE ON COST.CUR_NU = CUR_CODE.CUR_NU 
	INNER JOIN EMP ON COST.EMP_CODE = EMP.EMP_CODE
	INNER JOIN MAIN_ACC ON ENTRY.ACC_NU = MAIN_ACC.ACC_NU 
	LEFT JOIN SUB_ACC ON ENTRY.ACC_NU = SUB_ACC.ACC_NU AND ENTRY.SUB_NU = SUB_ACC.SUB_NU

where  
	 cost.COST_FLAG =@COST_TYPE
	and JOURNAL.JRN_DATE >= @FmTrDate
AND JOURNAL.JRN_DATE <= @ToTrDate  

And ((COST_ENT.COST_NU >= @FmFileNo)or(@FmFileNo is null))
And ((COST_ENT.COST_NU <= @ToFileNo)or(@ToFileNo is null))

AND(( COST.COST_TYP = @FileType) or(@FileType is null))
 
 
--4
and(
   Left(ENTRY.ACC_NU, 2) = (select top 1 CUS_TOURS_EX from sys_data)
Or Left(ENTRY.ACC_NU, 2) = (select top 1 CUS_TOURS_REV from sys_data)
Or Left(ENTRY.ACC_NU, 2) = (select top 1 CUS_JOURNEY_EX from sys_data)
Or Left(ENTRY.ACC_NU, 2) = (select top 1 CUS_JOURNEY_REV from sys_data))
-- SP End
END


		

















