--UPDATE Data In eradat			
UPDATE TMP_ACCO3219 set ENT_VAL_ERADAT = TMP_ACCO3219.ENT_VAL

  where USR_C=@USR_C and 
  (substring(convert(varchar,ACC),1,2)= (select CUS_TOURS_REV from SYS_DATA)
  or 
  substring(convert(varchar,ACC),1,2)= (select CUS_JOURNEY_REV from SYS_DATA))
	
--update Data in Masrofat
DECLARE tID_cursor CURSOR FOR    
SELECT distinct [ID]  FROM TMP_ACCO3219 where USR_C= @USR_C  and ENT_VAL_ERADAT = 0  

OPEN tID_cursor  DECLARE @ID [real]  

FETCH NEXT FROM tID_cursor INTO @ID
WHILE (@@FETCH_STATUS <> -1) 
BEGIN  
	set @MyStatus=isnull((SELECT  DR_CR    FROM TMP_ACCO3219  where TMP_ACCO3219.ID=@ID) ,null)
	
	set @mySubNo=isnull((SELECT  SUB    FROM TMP_ACCO3219  where TMP_ACCO3219.ID=@ID) ,null)
	set @myAccNo=isnull((SELECT  ACC    FROM TMP_ACCO3219  where TMP_ACCO3219.ID=@ID) ,0)
	set @myColLine = isnull((SELECT [LINE_NO] fROM [FILES_EXPENSES_DISTRIBUTION]
	 where [ACC_NU]=@myAccNo 
	 AND (((SUB_NU = @mySubNo )or(@mySubNo is null))or(SUB_NU is null) or SUB_NU =0 ) 
	 and [COST_TYP]=@Cost_Type),8)
	
	--Get Field Name To Update
	set @myFieldName=(
	CASE @myColLine
     WHEN 1 THEN  'ENT_VAL_HOTEL' 
     WHEN 2 THEN 'ENT_VAL_RESTURA' 
     WHEN 3 THEN 'ENT_VAL_BUS' 
     WHEN 4 THEN 'ENT_VAL_TRAIN' 
     WHEN 5 THEN 'ENT_VAL_REPRES' 
     WHEN 6 THEN 'ENT_VAL_GIUDS' 
     WHEN 7 THEN 'ENT_VAL_7' 
     else 'ENT_VAL_OTHER'
	END ) 
	print @myFieldName
	
		-- if 
	IF  substring(convert(varchar,@myAccNo ),1,2)  = @MASROFAT_SEAHA or substring(convert(varchar,@myAccNo ),1,2)= @MASROFAT_JOURNEY  
BEGIN
		if @MyStatus = 2
		BEGIN
			set @sqlCommand ='UPDATE [TMP_ACCO3219] set '+ @myFieldName + '= [TMP_ACCO3219].ENT_VAL   * -1 where  [TMP_ACCO3219].id='+ convert(varchar,@ID)	
		END
		ELSE
			set @sqlCommand ='UPDATE [TMP_ACCO3219] set '+ @myFieldName + '= [TMP_ACCO3219].ENT_VAL   where  [TMP_ACCO3219].id='+ convert(varchar,@ID)
END

ELSE

IF  substring(convert(varchar,@myAccNo ),1,2)  = @ERADAT_SEAHA or substring(convert(varchar,@myAccNo ),1,2)= @ERADAT_JOURNEY  
BEGIN
		if @MyStatus = 1
		BEGIN
