	delete  FROM TMP_ACCO3220 WHERE USR_C=@USR_C
	
	Declare @privFrom datetime 
	Declare @privTo datetime 

	set @privFrom  = @FmDate -1  
	set @privTo  = @ToDate -1  

set @privFrom  = DateAdd(yy , -1, @FmDate)
set @privTo  = DateAdd(yy , -1, @ToDate)


