	DECLARE COST_T_cursor CURSOR FOR    
	SELECT  COST_TYP  FROM COST_NUM  
	where (
				   ((UPPER(COST_NUM.COST_TYP) = @FileType1 )or(@FileType1 is null))
				or ((UPPER(COST_NUM.COST_TYP) = @FileType2 )or(@FileType2 is null))
				or ((UPPER(COST_NUM.COST_TYP) = @FileType3 )or(@FileType3 is null))
				or ((UPPER(COST_NUM.COST_TYP) = @FileType4 )or(@FileType4 is null))
				or ((UPPER(COST_NUM.COST_TYP) = @FileType5 )or(@FileType5 is null))
				or ((UPPER(COST_NUM.COST_TYP) = @FileType6 )or(@FileType6 is null))
