		WHERE COST_FLAG =@COST_TYPE and  (COST_ENT.COST_NU IN (SELECT DISTINCT COST_NU FROM COST AS COST_1 WHERE COST_1.COST_FLAG =@COST_TYPE and (COST_EXECUTION_DATE BETWEEN @FmDate AND @ToDate) AND ((EMP_CODE = @EmpCode)or @EmpCode is null ))) AND (SUBSTRING(CONVERT(varchar,COST_ENT.ACC_NU), 1, 2) IN (SELECT SUBSTRING(CONVERT(varchar, CUS_TOURS_REV), 1, 2) AS Expr1 FROM SYS_DATA)) AND (Finance.ENTRY.ENT_DR > 0) AND (SUBSTRING(COST_ENT.COST_NU, LEN(COST_ENT.COST_NU) - 2, 3) =  @COSTTYPE OR SUBSTRING(Finance.COST_ENT.COST_NU, 1, 3) =  @COSTTYPE)), 0)
		--'3- get Expensese Plus   ExComPlus	
		
		set @ExComPlus = isnull((SELECT SUM(COST_ENT.ENT_VAL)  FROM  COST INNER JOIN  COST_ENT ON COST.COST_NU = COST_ENT.COST_NU INNER JOIN JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID INNER JOIN ENTRY ON COST_ENT.ENT_ID = ENTRY.ENT_ID AND JOURNAL.JRN_ID = ENTRY.JRN_ID 
		WHERE COST_FLAG =@COST_TYPE and (COST_ENT.COST_NU IN (SELECT DISTINCT COST_NU FROM COST AS COST_1 WHERE COST_1.COST_FLAG =@COST_TYPE and (COST_EXECUTION_DATE BETWEEN @FmDate  AND @ToDate) AND ((EMP_CODE = @EmpCode)or @EmpCode is null ))) AND (SUBSTRING(CONVERT(varchar, COST_ENT.ACC_NU), 1, 2)  IN (SELECT SUBSTRING(CONVERT(varchar, CUS_TOURS_EX), 1, 2) AS Expr1 FROM  SYS_DATA)) AND (ENTRY.ENT_DR > 0) AND (COST.COST_TYP = @COSTTYPE)),0)
		--'4- get Expensese Mins   ExComMinus
		set @ExComMinus  = isnull((SELECT SUM(COST_ENT.ENT_VAL)  FROM  COST INNER JOIN  COST_ENT ON COST.COST_NU = COST_ENT.COST_NU INNER JOIN JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID INNER JOIN ENTRY ON COST_ENT.ENT_ID = ENTRY.ENT_ID AND JOURNAL.JRN_ID = ENTRY.JRN_ID
		 WHERE COST_FLAG =@COST_TYPE and  (COST_ENT.COST_NU IN (SELECT DISTINCT COST_NU FROM COST AS COST_1 WHERE COST_1.COST_FLAG =@COST_TYPE and (COST_EXECUTION_DATE BETWEEN @FmDate  AND @ToDate) AND ((EMP_CODE = @EmpCode)or @EmpCode is null))) AND (SUBSTRING(CONVERT(varchar, COST_ENT.ACC_NU), 1, 2)  IN (SELECT SUBSTRING(CONVERT(varchar, CUS_TOURS_EX), 1, 2) AS Expr1 FROM  SYS_DATA)) AND (ENTRY.ENT_CR > 0) AND (COST.COST_TYP = @COSTTYPE)),0)

		set @TotIncom = (@InComPlus - @InComMinus)
        set @TotEexp = (@ExComPlus - @ExComMinus)

