		 COST_FLAG =@COST_TYPE and  (COST_ENT.COST_NU IN (SELECT DISTINCT COST_NU FROM COST AS COST_1 WHERE COST_1.COST_FLAG =@COST_TYPE and  (COST_EXECUTION_DATE BETWEEN @privFrom  AND @privTo) AND ((EMP_CODE = @EmpCode)or @EmpCode is null ))) AND (SUBSTRING(CONVERT(varchar, COST_ENT.ACC_NU), 1, 2)  IN (SELECT SUBSTRING(CONVERT(varchar, CUS_TOURS_EX), 1, 2) AS Expr1 FROM  SYS_DATA)) AND (ENTRY.ENT_DR > 0) AND (COST.COST_TYP = @COSTTYPE)),0)
		 --'4- get Expensese Mins   ExComMinus
		 Set @ExComMinus = isnull((SELECT SUM(COST_ENT.ENT_VAL)  FROM  COST INNER JOIN  COST_ENT ON COST.COST_NU = COST_ENT.COST_NU INNER JOIN JOURNAL ON COST_ENT.JRN_ID = JOURNAL.JRN_ID INNER JOIN ENTRY ON COST_ENT.ENT_ID = ENTRY.ENT_ID AND JOURNAL.JRN_ID = ENTRY.JRN_ID 
		 WHERE COST_FLAG =@COST_TYPE and (COST_ENT.COST_NU IN (SELECT DISTINCT COST_NU FROM COST AS COST_1 WHERE COST_1.COST_FLAG =@COST_TYPE and (COST_EXECUTION_DATE BETWEEN @privFrom  AND @privTo) AND ((EMP_CODE = @EmpCode)or @EmpCode is null ))) AND (SUBSTRING(CONVERT(varchar, COST_ENT.ACC_NU), 1, 2)  IN (SELECT SUBSTRING(CONVERT(varchar, CUS_TOURS_EX), 1, 2) AS Expr1 FROM  SYS_DATA)) AND (ENTRY.ENT_CR > 0) AND (COST.COST_TYP = @COSTTYPE)),0)

		 set @TotIncomLast = (@InComPlus - @InComMinus)
         set @TotEexpLast = (@ExComPlus - @ExComMinus)
		-----------------------------------------------------------------------------	
		

		INSERT INTO TMP_ACCO3220 (USR_C,COST_TYP,PERIOD_REV,PERIOD_EXP,LAST_PERIOD_REV,LAST_PERIOD_EXP) values (@USR_C , @COSTTYPE , @TotIncom , @TotEexp , @TotIncomLast , @TotEexpLast )
			
		FETCH NEXT FROM COST_T_cursor INTO @COSTTYPE
	END 
