OPEN tCost_Nu_cursor  DECLARE @Cost_Nu varchar (15) 
FETCH NEXT FROM tCost_Nu_cursor INTO @Cost_Nu
WHILE (@@FETCH_STATUS <> -1) 
BEGIN  
	--'***********************************************
	set @IncomeP = ISNULL((select  sum(c.ENT_VAL)    
   FROM  Finance.COST_ENT AS c INNER JOIN
        Finance.ENTRY AS e ON c.ENT_ID = e.ENT_ID
		where  ((subString(convert(varchar,c.ACC_NU),1,2) in (@cus_tours_rev)) 
		or (subString(convert(varchar,c.ACC_NU),1,2) in (@cus_JOURNEY_rev)))
		and e.ent_cr > 0  and c.COST_NU= @Cost_Nu 
		AND (C.ACC_NU <>  @OutRevMainAccount or @OutRevMainAccount is null  )
		AND (C.SUB_NU <>  @OutRevSubAccount or @OutRevSubAccount is null  )
		),0)
		
	set @IncomeM =  ISNULL((select  sum(c.ENT_VAL)    
  FROM  Finance.COST_ENT AS c INNER JOIN
        Finance.ENTRY AS e ON c.ENT_ID = e.ENT_ID
		where  ((subString(convert(varchar,c.ACC_NU),1,2) in (@cus_tours_rev)) 
		or (subString(convert(varchar,c.ACC_NU),1,2) in (@cus_JOURNEY_rev)))
		and e.ent_Dr > 0  and c.COST_NU= @Cost_Nu
		AND (C.ACC_NU <>  @OutRevMainAccount or @OutRevMainAccount is null  )
		AND (C.SUB_NU <>  @OutRevSubAccount or @OutRevSubAccount is null  )
		),0)

	
	SET @myIncTotal=@myIncTotal+(@IncomeP-@IncomeM)
	
	--***********************************************
	
	select distinct @NO_OF_P = ISNULL(SUM(COST_CONT),0) , @NO_OF_N = SUM(DATEDIFF([day], COST_ARRIVAL_DATE, COST_DEPARTURE_DATE) * ISNULL(COST_CONT_ACCOM,0)) 
    from COST where
