set @myIncTotal=0
 DECLARE tCost_Nu_cursor CURSOR FOR    

 (SELECT distinct COST_NU FROM COST INNER JOIN Finance.COST_NATIONALITY ON Finance.COST.NAT_ID = Finance.COST_NATIONALITY.NAT_ID
			WHERE 
			(COST_NAT = @COST_NATC )
			and (COST.COST_STAT <> '2'  
			and year(COST_EXECUTION_DATE) = @Year
		and (
					(
					UPPER(COST_TYP) in( upper(@FileType1) , upper(@FileType2) , upper(@FileType3), upper(@FileType4), upper(@FileType5), upper(@FileType6), upper(@FileType7), upper(@FileType8)) 
					or (@FileType1 is null and @FileType2 is null and @FileType3 is null and @FileType4 is null and @FileType5 is null and @FileType6 is null and @FileType7 is null and @FileType8 is null)
					)
				)
										
			and  (UPPER(COST_TYP) <> @FileNotType1 or @FileNotType1 is null)
			and  (UPPER(COST_TYP) <> @FileNotType2 or @FileNotType2 is null)
			and  (UPPER(COST_TYP)<> @FileNotType3 or @FileNotType3 is null)
			and  (UPPER(COST_TYP) <> @FileNotType4 or @FileNotType4 is null)
			and  (UPPER(COST_TYP) <> @FileNotType5 or @FileNotType5 is null)
			and  (UPPER(COST_TYP) <> @FileNotType6 or @FileNotType6 is null)
			and  (UPPER(COST_TYP) <> @FileNotType7 or @FileNotType7 is null)
			and  (UPPER(COST_TYP) <> @FileNotType8 or @FileNotType8 is null)
			)
			and (
					(
					COST_FILE_TYPE in( @CostType1 , @CostType2 , @CostType3) 
					or (@CostType1 is null and @CostType2 is null and @CostType3 is null)
					)
				)

			AND (CST_ACC_NU <>  @OutMainAccount or @OutMainAccount is null  )
			AND (CST_SUB_NU <>  @OutSubAccount or @OutSubAccount is null  )
			)
			order by COST_NU 
			
OPEN tCost_Nu_cursor  DECLARE @Cost_Nu varchar (15) 
FETCH NEXT FROM tCost_Nu_cursor INTO @Cost_Nu
WHILE (@@FETCH_STATUS <> -1) 
BEGIN  
	--'***********************************************
	set @IncomeP =  ISNULL((select  sum(c.ENT_VAL)    
    FROM  Finance.COST_ENT AS c INNER JOIN
        Finance.ENTRY AS e ON c.ENT_ID = e.ENT_ID
		where  ((subString(convert(varchar,c.ACC_NU),1,2) in (@cus_tours_rev)) 
		or (subString(convert(varchar,c.ACC_NU),1,2) in (@cus_JOURNEY_rev)))
		and e.ent_cr > 0  and c.COST_NU= @Cost_Nu
