	--set @MyAccountCond=( ( COST.cost_main= 111111  and COST.CST_NO1=1)  or ( COST.cost_main= 111777  and COST.CST_NO1=2) )
	
	set @MyTypeCond=( select '( ' + '%' + COST_TYP +'%'  +' Or ' + '%' + COST_TYP1 +'%' 
					+' oR ' +'%' + COST_TYP2 +'%'  +' Or ' + '%' + COST_TYP3 +'%'
					+' oR ' +'%' + COST_TYP4 +'%'  +' Or ' + '%' + COST_TYP5 +'%'
					+' oR ' +'%' + COST_TYP6 +'%'  +' Or ' + '%' + COST_TYP7 +'%'
					+' oR ' +'%' + COST_TYP8 +'%'  +' Or ' + '%' + COST_TYP9 +'%'
					+' oR ' +'%' + COST_TYP10 +'%'  +' Or ' + '%' + COST_TYP11 +'%'
					+' oR ' +'%' + COST_TYP12 +'%'  +' Or ' + '%' + COST_TYP13 +'%'
					+' oR ' +'%' + COST_TYP14 +'%'  +' Or ' + '%' + COST_TYP15 +'%'
					+' oR ' +'%' + COST_TYP16 +'%'  +' Or ' + '%' + COST_TYP17 +'%'
					+' oR ' +'%' + COST_TYP18 +'%'  +' Or ' + '%' + COST_TYP19 +'%'
