	set @MyAccountCond=( select 'and (' 
					+ '(COST.cost_main= ' + CONVERT (varchar,CST_MAIN1) + ' And COST.CST_NO1= ' +CONVERT (varchar,CST_SUB1) +')'
					+' OR '	+ '(COST.cost_main= ' + CONVERT (varchar,CST_MAIN2) + ' And COST.CST_NO1= ' +CONVERT (varchar,CST_SUB2) +')'
					+' OR '	+ '(COST.cost_main= ' + CONVERT (varchar,CST_MAIN3) + ' And COST.CST_NO1= ' +CONVERT (varchar,CST_SUB3) +')'
					+' OR '	+ '(COST.cost_main= ' + CONVERT (varchar,CST_MAIN4) + ' And COST.CST_NO1= ' +CONVERT (varchar,CST_SUB4) +')'
					+' OR '	+ '(COST.cost_main= ' + CONVERT (varchar,CST_MAIN5) + ' And COST.CST_NO1= ' +CONVERT (varchar,CST_SUB5) +')'
				    + ' )' 
	from COST_TOTAL where cost_nu=@cost_nu)	
	
	INSERT INTO TMP_ACC3224_1 
	SELECT @USR_C AS USR_C,( select cost_nu from COST_TOTAL where cost_nu=@cost_nu ) as COST_NU_Total
