琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀⤀㰀㸀㌀㄀ ഀ਀ऀ愀渀搀 挀漀渀瘀攀爀琀⠀爀攀愀氀Ⰰ匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀⤀㰀㸀㐀㄀ ഀ਀ऀ愀渀搀 挀漀渀瘀攀爀琀⠀爀攀愀氀Ⰰ匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀⤀㰀㸀㌀㈀ ഀ਀ऀ愀渀搀 挀漀渀瘀攀爀琀⠀爀攀愀氀Ⰰ匀唀䈀匀吀刀䤀一䜀⠀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀Ⰰ䄀䌀䌀开一唀⤀Ⰰ㄀Ⰰ㈀⤀⤀㰀㸀　  ഀ਀ऀ䄀一䐀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ऀഀ਀
	INSERT INTO TMP_ACC3224 (USR_C,COST_NU_TOTAL,COST_NU,W_TOT_1,W_TOT_2,CST_CONT,COST_DATE,NoPerRom , COST_EXECUTION_DATE) 
	select @USR_C as USR_C,COST_NU_TOTAL,COST_NU,W_TOT_1,W_TOT_2,0 as CST_CONT,COST_DATE,0 as NoPerRom  , COST_EXECUTION_DATE as COST_EXECUTION_DATE 
	FROM TMP_ACC3224_1 WHERE USR_C=@USR_C
	
	
	UPDATE TMP_ACC3224 set TMP_ACC3224.NoPerRom=(DateDiff(DD,COST.COST_ARRIVAL_DATE ,COST_DEPARTURE_DATE))*COST_CONT_ACCOM 
	from COST WHERE TMP_ACC3224.COST_NU=COST.COST_NU AND TMP_ACC3224.USR_C=@USR_C  And COST_FLAG =@COST_TYPE
	
	

