	,@FileNotType7 varchar(3)= null 
	,@FileNotType8 varchar(3)= null 
	, @COST_TYPE  varchar(1)--C=Tourism,J=Journy
AS
BEGIN
	

    -- Insert statements for procedure here
	
	--1
	delete  FROM TMP_ACC3225 WHERE USR_C=@USR_C
	

	--2
	insert into TMP_ACC3225(USR_C,W_TOT_1,W_TOT_2,FILE_COUNT,EMP_CODE) 
	
	select @USR_C AS USR_C
	,sum(case inc_flg when '3' then ISNULL(ent_val,0) when '4' then -ISNULL(ent_val,0) end) as w_tot_1, 
	sum(case inc_flg when '1' then ISNULL(ent_val,0) when '2' then -ISNULL(ent_val,0) end) as w_tot_2,count(distinct(COST_NU)) as file_count, 
	EMP_CODE from ( 
