	  AND (COST_EXECUTION_DATE BETWEEN @FmExDate AND @ToExDate)  
	  AND (([emp_code] =@EmpCode  )or (@EmpCode is null))
	  group by c.COST_NU, EMP_CODE
	 
	 union
	 --4 
	select @USR_C AS USR_C,c.COST_NU AS COST_NU, sum(ISNULL(c.ENT_VAL,0)) as ENT_VAL,'3' AS INC_FLG, EMP_CODE 
	from cost_ent c 
	inner join entry e on  C.ENT_id = E.ENT_id
	 INNER JOIN cost on c.cost_nu = cost.cost_nu
	 
	Where  E.ENT_DR > 0 And COST_FLAG =@COST_TYPE
	and ((subString(convert(varchar,c.ACC_NU),1,2) in (select subString(convert(varchar,cus_tours_ex),1,2) 
	from sys_data)) or (subString(convert(varchar,c.ACC_NU),1,2) in (select subString(convert(varchar,cus_JOURNEY_ex),1,2)
	 from sys_data))) 
	 AND 
	(
		  ((COST.COST_typ = @FileType1 )or(@FileType1 is null))
		or((COST.COST_typ = @FileType2 )or(@FileType2 is null))
		or((COST.COST_typ = @FileType3 )or(@FileType3 is null))
		or((COST.COST_typ = @FileType4 )or(@FileType4 is null))
		or((COST.COST_typ = @FileType5 )or(@FileType5 is null))
		or((COST.COST_typ = @FileType6 )or(@FileType6 is null))
		or((COST.COST_typ = @FileType7 )or(@FileType7 is null))
		or((COST.COST_typ = @FileType8 )or(@FileType8 is null))
	)
		AND((COST.COST_TYP <> @FileNotType1 )or(@FileNotType1 is null))
		AND((COST.COST_TYP <> @FileNotType2 )or(@FileNotType2 is null))
