-- ================================================
CREATE proc   [Finance].[SPACCO3228]
	-- Add the parameters for the stored procedure here
	@USR_C varchar(10)
	,@FromReservDate Datetime  = null 
	,@ToReservDate Datetime = null 

	,@FromExeDate Datetime  = null 
	,@ToExeDate Datetime = null 

	,@FileType varchar(3)= null 
	,@EmpCode varchar(10)= null 

	,@Acounting int = null 
	,@Process int = null 
	,@Canceled int = null 
	,@Execution int = null 

	 , @COST_TYPE  varchar(1)--C=Tourism,J=Journy

AS
BEGIN
    -- Insert statements for procedure here
	delete  FROM TMP_ACCO3228 WHERE USR_C=@USR_C

		if @FromReservDate is not null and @FromExeDate is  null 
		begin 

		insert into  TMP_ACCO3228 
		SELECT   @USR_C AS USR_C, 
		COST_NU, COST_TYP, cost.EMP_CODE, CST_SUB_NU, COST_DES, COST_ADD, COST_1ADD, CUR_NU, COST_FILE_NAME, COST_CONT, COST_ARRIVAL_DATE, 
                         COST_DEPARTURE_DATE, COST_EXECUTION_DATE, COST_FILE_TYPE, CST_ACC_NU, COST_VCH, COST_STAT, COST_USER_CREATE, COST_DATE_CREATE, 
                         COST_TIME_CREATE, COST_USER_UPDATE, COST_DATE_UPDATE, COST_TIME_UPDATE, NAT_ID, COST_SERVICE, COST_CONT_ACCOM, COST_FLAG , EMP_NAME

			FROM  COST 
			INNER JOIN  EMP ON COST.EMP_CODE = EMP.EMP_CODE
