 CREATE proc   [Finance].[SPACCO3301]
	-- Add the parameters for the stored procedure here
	  @USR_C varchar(10)
	, @FromDate Datetime
	, @ToDate Datetime 
	, @AirComp VARCHAR(3)=null


	, @FrmTravelDate Datetime = null
	, @ToTravelDate Datetime = null

	, @Branch VARCHAR(3)=null
	, @FareBase VARCHAR(3)=null
	, @ReportType VARCHAR(3)=null
	, @ReportData VARCHAR(3)=null

	, @Route1 VARCHAR(3)=null
	, @Route2 VARCHAR(3)=null
	, @Route3 VARCHAR(3)=null
	
AS
	BEGIN

	--set @FromDate ='01/01/2015'
	--set @ToDate='10/10/2015'
	--set @AirComp='ms'

	--set @Branch=null
	--set @ReportType=null
	--set @FareBase=null
	--set @Route1 =null--'R1'
	--set @Route2 =null--'R2'
	--set @Route3 =null--'R3'


		--1    DELETE
		delete  FROM TMP_ACCO3301 WHERE USR_C= @USR_C
		--2    Insert statements for procedure here


;WITH T AS(
	SELECT '4' AS FLAG 
	,AL.AIR_COD AS SERIAL
	, AL.AIR_DAT AS [DATE] 
	,(SELECT MIN(TKT_NR) AS TKT_NO FROM AIR_TKT WHERE AL.AIR_COD=AIR_TKT.AIR_COD) AS TKT_NO 
	,air_bas AS bas_cash 
	,0 AS bas_cc 
	,0 AS bas_cr 
	,(isnull(air_bas,0) + isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) AS TOT_CASH 
	,0 AS TOT_CC 
	,0 AS TOT_CR 
	,air_comm AS COM_RC 
	, air_or AS COM_OR 
	,air_comt + air_ort as COM_STX 
	,CF=isnull((SELECT SUM(PAY_AMT) AS CF FROM AIR_PAY WHERE  AIR_COD =AL.AIR_COD  AND PAY_TYP = 4),0)  
	,air_s_f  as COM_SF,
	
--Ruf Cash
	( -(abs(isnull(air_comm,0)) + abs(isnull(air_or,0))) 
		+ abs((isnull(air_comt,0)) + abs(isnull(air_ort,0)) )
		+abs(isnull((select sum(isnull(PAY_AMT,0)) from air_pay where air_cod=al.air_cod and PAY_TYP='5'),0))
	) AS NET_FARE 

