匀 一䔀吀开䘀䄀刀䔀 ഀ਀ऀऀऀഀ਀
		,(SELECT MIN(TKT_FB) AS FB FROM AIR_TKT WHERE AL.AIR_COD=AIR_TKT.AIR_COD) AS FB ,SUBSTRING(air_rout,1,30) AS ROUTE,SUBSTRING(AIR_CREDIT_CARDNO,1,30) AS Rem ,isnull(air_bas,0) * isnull(air_car,0) AS CARR ,SUBSTRING(AIR_PASS,1,30) AS PASS,cst_no AS CUST_COD ,(select CUS_AIR from sys_data) AS CUST_MAIN ,ISNULL((SELECT  SUM(PAY_AMT) AS Sum_Air_AMT FROM AIR_PAY  WHERE AIR_COD =AL.AIR_COD  AND PAY_TYP = '5' ),0) AS RFAMT,'' AS PONR  ,CASE isdate(AIR_TRAVEL_DATE)  WHEN 1 THEN AIR_TRAVEL_DATE WHEN 0 THEN '' END AS rem2  
	FROM AIR_LINE as AL where  UPPER(AL.air_comp) =@AirComp and AL.air_dat between @FromDate and @ToDate and ((AL.air_bran =@Branch) or (@Branch is null)) and ((AL.air_f_typ = @ReportType) or(@ReportType is null)) and  (((UPPER(air_rout) like '%' + @Route1 + '%' )or(@Route1 is null)) or ((UPPER(air_rout) like '%' + @Route2 + '%' )or(@Route2 is null)) or ((UPPER(air_rout) like '%' + @Route3 + '%' )or(@Route3 is null)) ) and ((AL.air_cod in (select distinct(AIR_COD) FROM AIR_TKT WHERE TKT_FB =@FareBase))or(@FareBase is null)) AND AL.air_k_typ IN ('3') AND AL.air_c_py IN ('2') and  ((AL.AIR_TRAVEL_DATE  >= @FrmTravelDate) or (@FrmTravelDate is null)) and  ((AL.AIR_TRAVEL_DATE  <= @ToTravelDate) or (@ToTravelDate is null))
--------------------
	union all
		SELECT '4' AS FLAG ,AL.AIR_COD AS SERIAL, AL.AIR_DAT AS [DATE] ,(SELECT MIN(TKT_NR) AS TKT_NO FROM AIR_TKT WHERE AL.AIR_COD=AIR_TKT.AIR_COD) AS TKT_NO ,0 AS bas_cash ,0 AS bas_cc ,(air_bas) AS bas_cr ,0 AS TOT_CASH ,0 AS TOT_CC ,(isnull(air_bas,0) + isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) AS TOT_CR ,air_comm AS COM_RC , air_or AS COM_OR ,air_comt + air_ort as COM_STX ,CF=isnull((SELECT SUM(PAY_AMT) AS CF FROM AIR_PAY WHERE  AIR_COD =AL.AIR_COD  AND PAY_TYP = 4),0)  ,air_s_f  as COM_SF
		,(-(abs(isnull(air_bas,0)))
			-abs(isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0))
			+abs((isnull(air_comm,0) + isnull(air_or,0)) -
			(isnull(air_comt,0) + isnull(air_ort,0)))
			+abs(isnull((select sum(isnull(PAY_AMT,0)) from air_pay where air_cod=al.air_cod and PAY_TYP='5'),0))
		) AS NET_FARE 

