	,(SELECT MIN(TKT_FB) AS FB FROM AIR_TKT WHERE AL.AIR_COD=AIR_TKT.AIR_COD) AS FB ,SUBSTRING(air_rout,1,30) AS ROUTE,SUBSTRING(AIR_CREDIT_CARDNO,1,30) AS Rem ,isnull(air_bas,0) * isnull(air_car,0) AS CARR ,SUBSTRING(AIR_PASS,1,30) AS PASS,cst_no AS CUST_COD ,(select CUS_AIR from sys_data) AS CUST_MAIN ,0 AS RFAMT,'' AS PONR  ,CASE isdate(AIR_TRAVEL_DATE)  WHEN 1 THEN AIR_TRAVEL_DATE WHEN 0 THEN '' END AS rem2  
	FROM AIR_LINE as AL  where UPPER(AL.air_comp) =@AirComp and AL.air_dat between @FromDate and @ToDate and ((AL.air_bran =@Branch) or (@Branch is null)) and ((AL.air_f_typ = @ReportType) or(@ReportType is null)) and  (((UPPER(air_rout) like '%' + @Route1 + '%' )or(@Route1 is null))or ((UPPER(air_rout) like '%' + @Route2 + '%' )or(@Route2 is null))or ((UPPER(air_rout) like '%' + @Route3 + '%' )or(@Route3 is null)))and ((AL.air_cod in (select distinct(AIR_COD) FROM AIR_TKT WHERE TKT_FB =@FareBase))or(@FareBase is null))  AND AL.air_k_typ IN ('1','2') AND AL.air_c_py IN ('3') and  ((AL.AIR_TRAVEL_DATE  >= @FrmTravelDate) or (@FrmTravelDate is null)) and  ((AL.AIR_TRAVEL_DATE  <= @ToTravelDate) or (@ToTravelDate is null))
