 CREATE proc   [Finance].[SPACCO3301_1]
	-- Add the parameters for the stored procedure here
	  @USR_C varchar(10)
	, @FromDate Datetime
	, @ToDate Datetime 
	, @AirComp VARCHAR(3)=null


	, @FrmTravelDate Datetime = null
	, @ToTravelDate Datetime = null

	, @Branch VARCHAR(3)=null
	, @FareBase VARCHAR(3)=null
	, @ReportType VARCHAR(3)=null
	, @ReportData VARCHAR(3)=null

	, @Route1 VARCHAR(3)=null
	, @Route2 VARCHAR(3)=null
	, @Route3 VARCHAR(3)=null
	
AS
	BEGIN

	--set @FromDate ='01/01/2015'
	--set @ToDate='10/10/2015'
	--set @AirComp='ms'

	--set @Branch=null
	--set @ReportType=null
	--set @FareBase=null
	--set @Route1 =null--'R1'
	--set @Route2 =null--'R2'
	--set @Route3 =null--'R3'


		--1    DELETE
		delete  FROM TMP_ACCO3301_1 WHERE USR_C=@USR_C
		--2    Insert statements for procedure here


Insert into TMP_ACCO3301_1 
SELECT @USR_C as USR_C , 
 AL.AIR_COD
,ISNULL(AL.AIR_COMM,0) AS AIR_COMM
,ISNULL(AL.AIR_COMT,0) AS AIR_COMT
,ISNULL(AL.AIR_OR,0)   AS AIR_OR
,ISNULL(AL.AIR_ORT,0)  AS AIR_ORT
,ISNULL(AL.AIR_S_F,0)  AS AIR_S_F
,AL.AIR_K_TYP

,NETINCOME=
CASE 
WHEN AL.AIR_K_TYP IN('1','2') THEN 
--Issue/Reissue(NetComm+MangementFee-Discount)
(Isnull(AL.Air_Comm,0) + Isnull(AL.Air_OR,0))-(Isnull(AL.Air_ComT,0)+Isnull(AL.Air_ORT,0)) 
+  IsNull(AL.AIR_S_F,0)
-(SELECT ISNULL(SUM(PAY_AMT),0) FROM AIR_PAY WHERE AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2'))

WHEN AL.AIR_K_TYP IN('3') THEN 
--Refund(-NetComm-MangementFee+Discount)
-abs((Isnull(AL.Air_Comm,0) + Isnull(AL.Air_OR,0))-(Isnull(AL.Air_ComT,0)+Isnull(AL.Air_ORT,0)) )
- abs(IsNull(AL.AIR_S_F,0))
+abs((SELECT ISNULL(SUM(PAY_AMT),0) FROM AIR_PAY WHERE AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2','4')))
END

 
,AP.PAY_TYP
,ISNULL(AP.PAY_AMT,0)  AS PAY_AMT
,AP.PAY_DES
,AP.LINE_NU

,AT.TKT_NR
,FLAG=
CASE 
WHEN AL.AIR_K_TYP IN('1','2') THEN 'I'
WHEN AL.AIR_K_TYP IN('3') THEN 'R'
END

--*

FROM AIR_LINE AS AL
JOIN AIR_TKT AS AT
ON AT.AIR_COD=AL.AIR_COD

JOIN AIR_PAY AS AP
ON AP.AIR_COD=AL.AIR_COD

where  
ਊ唀倀倀䔀刀⠀䄀䰀⸀愀椀爀开挀漀洀瀀⤀ 㴀䀀䄀椀爀䌀漀洀瀀 ഀ਀愀渀搀 䄀䰀⸀愀椀爀开搀愀琀 戀攀琀眀攀攀渀 䀀䘀爀漀洀䐀愀琀攀 愀渀搀 䀀吀漀䐀愀琀攀 ഀ਀愀渀搀  ⠀⠀䄀䰀⸀䄀䤀刀开吀刀䄀嘀䔀䰀开䐀䄀吀䔀  㸀㴀 䀀䘀爀洀吀爀愀瘀攀氀䐀愀琀攀⤀ 漀爀 ⠀䀀䘀爀洀吀爀愀瘀攀氀䐀愀琀攀 椀猀 渀甀氀氀⤀⤀ 愀渀搀  ⠀⠀䄀䰀⸀䄀䤀刀开吀刀䄀嘀䔀䰀开䐀䄀吀䔀  㰀㴀 䀀吀漀吀爀愀瘀攀氀䐀愀琀攀⤀ 漀爀 ⠀䀀吀漀吀爀愀瘀攀氀䐀愀琀攀 椀猀 渀甀氀氀⤀⤀ഀ਀愀渀搀 ⠀⠀䄀䰀⸀愀椀爀开戀爀愀渀 㴀䀀䈀爀愀渀挀栀⤀ 漀爀 ⠀䀀䈀爀愀渀挀栀 椀猀 渀甀氀氀⤀⤀ ഀ਀愀渀搀 ⠀⠀䄀䰀⸀愀椀爀开昀开琀礀瀀 㴀 䀀刀攀瀀漀爀琀吀礀瀀攀⤀ 漀爀⠀䀀刀攀瀀漀爀琀吀礀瀀攀 椀猀 渀甀氀氀⤀⤀ ഀ਀ഀ਀愀渀搀  ⠀ഀ਀   ⠀⠀唀倀倀䔀刀⠀愀椀爀开爀漀甀琀⤀ 氀椀欀攀 ✀─✀ ⬀ 䀀刀漀甀琀攀㄀ ⬀ ✀─✀ ⤀漀爀⠀䀀刀漀甀琀攀㄀ 椀猀 渀甀氀氀⤀⤀ ഀ਀漀爀 ⠀⠀唀倀倀䔀刀⠀愀椀爀开爀漀甀琀⤀ 氀椀欀攀 ✀─✀ ⬀ 䀀刀漀甀琀攀㈀ ⬀ ✀─✀ ⤀漀爀⠀䀀刀漀甀琀攀㈀ 椀猀 渀甀氀氀⤀⤀ ഀ਀漀爀 ⠀⠀唀倀倀䔀刀⠀愀椀爀开爀漀甀琀⤀ 氀椀欀攀 ✀─✀ ⬀ 䀀刀漀甀琀攀㌀ ⬀ ✀─✀ ⤀漀爀⠀䀀刀漀甀琀攀㌀ 椀猀 渀甀氀氀⤀⤀ഀ਀     ⤀ഀ਀愀渀搀 ⠀⠀䄀吀⸀吀䬀吀开䘀䈀㴀䀀䘀愀爀攀䈀愀猀攀⤀ 伀刀 ⠀䀀䘀愀爀攀䈀愀猀攀 椀匀 一唀䰀䰀⤀⤀ഀ਀ഀ਀䄀一䐀 䄀䰀⸀䄀䤀刀开䬀开吀夀倀 㰀㸀 ✀㐀✀ഀ਀ ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㌀　㈀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀ ഀ਀ 䌀刀䔀䄀吀䔀 瀀爀漀挀   嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㌀　㈀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀ  䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀爀漀洀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 䐀愀琀攀琀椀洀攀 ഀ਀ഀ਀ऀⰀ 䀀䈀爀愀渀挀栀 渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀ഀ਀ऀⰀ 䀀刀攀瀀漀爀琀吀礀瀀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀ഀ਀ऀⰀ 䀀吀䬀吀吀礀瀀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀ഀ਀ऀⰀ 䀀䜀爀愀瀀栀  渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀ഀ਀ऀഀ਀䄀匀ഀ਀ऀ䈀䔀䜀䤀一ഀ਀ഀ਀ഀ਀ऀऀⴀⴀ㄀    䐀䔀䰀䔀吀䔀ഀ਀ऀऀ搀攀氀攀琀攀  䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㌀　㈀ 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ऀऀⴀⴀ㈀    䤀渀猀攀爀琀 猀琀愀琀攀洀攀渀琀猀 昀漀爀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ഀ਀ഀ਀ⴀⴀ搀攀挀氀愀爀攀 䀀䘀爀漀洀 䐀愀琀攀吀椀洀攀ഀ਀ⴀⴀ搀攀挀氀愀爀攀 䀀吀漀 䐀愀琀攀吀椀洀攀ഀ਀ⴀⴀ搀攀挀氀愀爀攀 䀀䄀椀爀开䈀爀愀渀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ഀ਀ⴀⴀ搀攀挀氀愀爀攀 䀀刀攀瀀漀爀琀开吀礀瀀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ഀ਀ⴀⴀ搀攀挀氀愀爀攀 䀀吀䬀吀开吀礀瀀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ഀ਀ⴀⴀⴀⴀ刀攀焀ഀ਀ⴀⴀ猀攀琀 䀀䘀爀漀洀㴀✀　㄀⼀　㄀⼀㈀　㄀㄀✀ⴀⴀ吀伀ഀ਀ⴀⴀ猀攀琀 䀀吀漀㴀✀　㄀⼀　㄀⼀㈀　㄀㌀✀ ⴀⴀ䘀爀漀洀ഀ਀ⴀⴀ猀攀琀 䀀䄀椀爀开䈀爀愀渀㴀一唀䰀䰀ഀ਀ⴀⴀ猀攀琀 䀀刀攀瀀漀爀琀开吀礀瀀攀㴀渀甀氀氀ഀ਀ⴀⴀ猀攀琀 䀀吀䬀吀开吀礀瀀攀㴀渀甀氀氀ഀ਀ⴀⴀ㬀ഀ਀ഀ਀㬀眀椀琀栀 琀 愀猀⠀ഀ਀猀攀氀攀挀琀 搀椀猀琀椀渀挀琀 愀氀⸀䄀䤀刀开䌀伀䴀倀 ഀ਀Ⰰ挀漀搀攀 㴀 ⠀ 猀攀氀攀挀琀 琀漀瀀 ㄀ 匀唀䈀开一唀 昀爀漀洀 匀唀䈀开䄀䌀䌀 眀栀攀爀攀 匀唀䈀开一䴀开䔀 䰀䤀䬀䔀 愀氀⸀䄀䤀刀开䌀伀䴀倀 ⬀ ✀─✀ 愀渀搀 䄀䌀䌀开一唀㴀⠀匀䔀䰀䔀䌀吀 䄀䤀刀开䌀伀䴀倀 䘀刀伀䴀 匀夀匀开䐀䄀吀䄀⤀⤀ഀ਀Ⰰ䤀猀猀甀攀䌀漀甀渀琀 㴀 ⠀猀攀氀攀挀琀 䌀漀甀渀琀⠀⨀⤀ 愀猀 䈀开䤀匀匀唀䔀 䘀刀伀䴀 䄀䤀刀开吀䬀吀Ⰰ愀椀爀开氀椀渀攀  圀栀攀爀攀 䄀䤀刀开䰀䤀一䔀⸀䄀䤀刀开䌀伀䐀 㴀 䄀䤀刀开吀䬀吀⸀䄀䤀刀开䌀伀䐀 ഀ਀ऀऀऀ愀渀搀 䄀䤀刀开䰀䤀一䔀⸀䄀䤀刀开䬀开吀夀倀 䤀一 ⠀✀㄀✀Ⰰ✀㈀✀⤀ ഀ਀ऀऀऀ愀渀搀 䄀䤀刀开䰀䤀一䔀⸀愀椀爀开搀愀琀 䈀攀琀眀攀攀渀 䀀䘀爀漀洀䐀愀琀攀 愀渀搀 䀀吀漀䐀愀琀攀ഀ਀ऀऀऀ愀渀搀 䄀䤀刀开䰀䤀一䔀⸀䄀䤀刀开䌀伀䴀倀㴀愀氀⸀䄀䤀刀开䌀伀䴀倀ഀ਀ऀऀऀ愀渀搀⠀⠀ 䄀䤀刀开䰀䤀一䔀⸀愀椀爀开琀开琀礀 㴀䀀吀䬀吀吀礀瀀攀⤀漀爀⠀䀀吀䬀吀吀礀瀀攀 椀猀 渀甀氀氀⤀⤀ഀ਀ऀऀऀ愀渀搀⠀⠀ 䄀䤀刀开䰀䤀一䔀⸀愀椀爀开昀开琀礀瀀 㴀䀀刀攀瀀漀爀琀吀礀瀀攀⤀漀爀⠀䀀刀攀瀀漀爀琀吀礀瀀攀 椀猀 渀甀氀氀⤀⤀ഀ਀ऀऀऀ愀渀搀⠀⠀ 䄀䤀刀开䰀䤀一䔀⸀䄀䤀刀开䈀刀䄀一 㴀䀀䈀爀愀渀挀栀⤀漀爀⠀䀀䈀爀愀渀挀栀 椀猀 渀甀氀氀⤀⤀⤀ഀ਀
,RefuntCount = (select Count(*) as B_ISSUE FROM AIR_TKT,air_line  Where AIR_LINE.AIR_COD = AIR_TKT.AIR_COD 
			and AIR_LINE.AIR_K_TYP IN ('3') 
			and AIR_LINE.air_dat Between @FromDate and @ToDate
			and AIR_LINE.AIR_COMP=al.AIR_COMP
			and(( AIR_LINE.air_t_ty =@TKTType)or(@TKTType is null))
			and(( AIR_LINE.air_f_typ =@ReportType)or(@ReportType is null))
			and(( AIR_LINE.AIR_BRAN =@Branch)or(@Branch is null)))
,VoidCount = (Select Count(*) as B_ISSUE FROM AIR_TKT,air_line  Where AIR_LINE.AIR_COD = AIR_TKT.AIR_COD 
			and AIR_LINE.AIR_K_TYP IN ('4') 
			and AIR_LINE.air_dat Between @FromDate and @ToDate
			and AIR_LINE.AIR_COMP=al.AIR_COMP
			and(( AIR_LINE.air_t_ty =@TKTType)or(@TKTType is null))
			and(( AIR_LINE.air_f_typ =@ReportType)or(@ReportType is null))
			and(( AIR_LINE.AIR_BRAN =@Branch)or(@Branch is null)))
,IssueSum = isnull((select Sum(AIR_TKT.TKT_AMT) as B_ISSUE  FROM AIR_TKT,air_line Where AIR_LINE.AIR_COD = AIR_TKT.AIR_COD 
			and AIR_LINE.AIR_K_TYP IN ('1','2') 
			and AIR_LINE.air_dat Between @FromDate and @ToDate
			and AIR_LINE.AIR_COMP=al.AIR_COMP
			and(( AIR_LINE.air_t_ty =@TKTType)or(@TKTType is null))),0)
,RefuntSum = isnull((select Sum(AIR_TKT.TKT_AMT) as B_ISSUE  FROM AIR_TKT,air_line  Where AIR_LINE.AIR_COD = AIR_TKT.AIR_COD 
			and AIR_LINE.AIR_K_TYP IN ('3') 
			and AIR_LINE.air_dat Between @FromDate and @ToDate
			and AIR_LINE.AIR_COMP=al.AIR_COMP
			and(( AIR_LINE.air_t_ty =@TKTType)or(@TKTType is null))
			and(( AIR_LINE.air_f_typ =@ReportType)or(@ReportType is null))
			and(( AIR_LINE.AIR_BRAN =@Branch)or(@Branch is null))),0)
				from AIR_LINE as AL 
					where  al.air_dat Between @FromDate and @ToDate
						group by AIR_COMP)

insert into TMP_ACCO3302 
select  @USR_C as  USR_C ,* from t
where  t.IssueCount <> 0  or t.RefuntCount <> 0 or t.VoidCount <> 0 
order by code
 
END



















