,T_Cash_R=  (case when  al.AIR_C_PY='1' AND AL.AIR_K_TYP IN ('3') then (ISNULL(air_bas,0) + ISNULL( AIR_TAX1,0) + ISNULL( AIR_TAX2,0) + ISNULL(AIR_TAX3 ,0) + ISNULL(AIR_TAX4 ,0) + ISNULL(AIR_TAX5 ,0) + ISNULL(AIR_STMP ,0)) ELSE 0 end)
,T_CC_R=    (case when  al.AIR_C_PY='2' AND AL.AIR_K_TYP IN ('3') then (ISNULL(air_bas,0) + ISNULL( AIR_TAX1,0) + ISNULL( AIR_TAX2,0) + ISNULL(AIR_TAX3 ,0) + ISNULL(AIR_TAX4 ,0) + ISNULL(AIR_TAX5 ,0) + ISNULL(AIR_STMP ,0)) ELSE 0 end)
,T_Credit_R=(case when  al.AIR_C_PY='3' AND AL.AIR_K_TYP IN ('3') then (ISNULL(air_bas,0) + ISNULL( AIR_TAX1,0) + ISNULL( AIR_TAX2,0) + ISNULL(AIR_TAX3 ,0) + ISNULL(AIR_TAX4 ,0) + ISNULL(AIR_TAX5 ,0) + ISNULL(AIR_STMP ,0)) ELSE 0 end)

 
,RC_I=(case when  AL.AIR_K_TYP IN ('1','2') then ISNULL(Air_Comm,0) ELSE 0 end)
,OR_I=(case when  AL.AIR_K_TYP IN ('1','2') then ISNULL(Air_OR,0) ELSE 0 end)

,RC_R=(case when  AL.AIR_K_TYP IN ('3') then ISNULL(Air_Comm,0) ELSE 0 end)
,OR_R=(case when  AL.AIR_K_TYP IN ('3') then ISNULL(Air_OR,0) ELSE 0 end)



,FC_I=(case when  AL.AIR_K_TYP IN ('1','2') then (SELECT SUM(AIR_PAY.PAY_AMT) FROM AIR_PAY WHERE AIR_PAY.AIR_COD=AL.AIR_COD AND PAY_TYP='4') ELSE 0 end)
,RF_I=(case when  AL.AIR_K_TYP IN ('1','2') then (SELECT SUM(AIR_PAY.PAY_AMT) FROM AIR_PAY WHERE AIR_PAY.AIR_COD=AL.AIR_COD AND PAY_TYP='5') ELSE 0 end)

,FC_R=(case when  AL.AIR_K_TYP IN ('3') then (SELECT SUM(AIR_PAY.PAY_AMT) FROM AIR_PAY WHERE AIR_PAY.AIR_COD=AL.AIR_COD AND PAY_TYP='4') ELSE 0 end)
,RF_R=(case when  AL.AIR_K_TYP IN ('3') then (SELECT SUM(AIR_PAY.PAY_AMT) FROM AIR_PAY WHERE AIR_PAY.AIR_COD=AL.AIR_COD AND PAY_TYP='5') ELSE 0 end)


,STX_I=(case when  AL.AIR_K_TYP IN ('1','2') then (ISNULL(AIR_COMT,0)+ ISNULL(air_ort,0)) ELSE 0 end)
,STX_R=(case when  AL.AIR_K_TYP IN ('3') then (ISNULL(AIR_COMT,0)+ ISNULL(air_ort,0)) ELSE 0 end)

