,NETFARE_IR_Credit=(
case
when AL.AIR_K_TYP IN ('1','2') AND AIR_C_PY IN('3') THEN

(ISNULL(AL.AIR_BAS,0)+
ISNULL(AL.AIR_TAX1,0) + ISNULL(AL.AIR_TAX2,0) + ISNULL(AL.AIR_TAX3,0) 
+ ISNULL(AL.AIR_TAX4,0) + ISNULL(AL.AIR_TAX5,0) + ISNULL(AL.AIR_STMP,0)
)
-((ISNULL(Air_Comm,0) + ISNULL(Air_OR,0))-(ISNULL(Air_ComT,0)+ISNULL(Air_ORT,0)))
ELSE 
 0
END
)
