 INSERT INTO  TMP_ACCO3303 

SELECT @USR_C as USR_C,  AIR_COMP
,(SELECT top 1 SUB_NU FROM SUB_ACC WHERE ACC_NU IN (SELECT TOP 1 AIR_COMP FROM SYS_DATA) AND SUB_NM_E LIKE T.AIR_COMP ) AS COMP_NU  
,AIR_T_TY
, SUM(B_Cash_I) AS B_Cash_I
, SUM(B_CC_I) AS B_CC_I
, SUM(B_Credit_I) AS B_Credit_I

, SUM(T_Cash_I) AS T_Cash_I
, SUM(T_CC_I) AS T_CC_I
, SUM(T_Credit_I) AS T_Credit_I

, SUM(B_Cash_R) AS B_Cash_R
, SUM(B_CC_R) AS B_CC_R
, SUM(B_Credit_R) AS B_Credit_R

, SUM(T_Cash_R) AS T_Cash_R
, SUM(T_CC_R) AS T_CC_R
, SUM(T_Credit_R) AS T_Credit_R
, SUM(RC_I) AS RC_I
, SUM(OR_I) AS OR_I
, SUM(RC_R) AS RC_R
, SUM(OR_R) AS OR_R
, SUM(FC_I) AS FC_I
, SUM(RF_I) AS RF_I
, SUM(FC_R) AS FC_R
, SUM(RF_R) AS RF_R
, SUM(STX_I) AS STX_I
, SUM(STX_R) AS STX_R
,(SUM(NETFARE_IR_Credit)+SUM(NETFARE_IR_CashCc)) AS NETFARE_I
,(SUM(NETFARE_Refund_Credit)+SUM(NETFARE_Refund_Cash)+SUM(NETFARE_Refund_Cc)) AS NETFARE_R
,SUM(AIRCAR_I) AS AIRCAR_I
,SUM(AIRCAR_R) AS AIRCAR_R
 FROM T
 
GROUP BY AIR_COMP,AIR_T_TY 
 
ORDER BY AIR_COMP
  
 
END



















