-- inser Prev Company Which Not have value In Current
insert into TMP_ACCO3306 
SELECT  @USR_C as  USR_C , 

 
AIR_COMP as AirLine 
--,air_rout
,[CODE]=(select min(SUB_ACC.SUB_NU) from sub_acc where sub_acc.acc_nu=234000 and sub_nm_e like AIR_LINE.AIR_COMP + '%') 
,BASIC1=0
,TOTAL1=0
,NETCOMM1=0
,BASIC2=isnull(( SUM(isnull(AIR_BAS,0)) ),0)
,TOTAL2=isnull(( SUM(isnull(AIR_BAS,0) + isnull(AIR_tax1,0) + isnull(AIR_tax2,0) 
			+ isnull(AIR_tax3,0) + isnull(AIR_tax4,0) + isnull(AIR_tax5,0) + isnull(AIR_stmp,0)) ),0)
,NETCOMM2=isnull((SELECT SUM((isnull(AIR_COMM,0) + isnull(AIR_OR,0))  - (isnull(AIR_COMT,0) + isnull(AIR_ORT,0)) )),0)

 from air_line 
-- INNER JOIN
   --                     AIR_TKT ON AIR_LINE.AIR_COD =AIR_TKT.AIR_COD
where  (AIR_LINE.AIR_DAT between @FromPrev AND @ToPrev)  
AND
((UPPER(Air_Line.air_comp) =@Air_Line)or(@Air_Line is null))
and  ((Air_Line.AIR_ACC =@Main )or(@Main is null))
and  ((Air_Line.cst_no =@Sub )or(@Sub is null))

and  ((Air_Line.air_bran =@Air_Bran )or(@Air_Bran is null))

and  ((Air_Line.air_f_typ = @ReportType)OR(@ReportType IS NULL))
and  ((Air_Line.air_t_ty = @TicketType)OR(@TicketType IS NULL))
and 
(
   (UPPER(Air_Line.air_rout) like upper('%' + @Route1 + '%') OR (@Route1 IS NULL))
or (UPPER(Air_Line.air_rout) like upper('%' + @Route2 + '%') OR (@Route2 IS NULL))
or (UPPER(Air_Line.air_rout) like upper('%' + @Route3 + '%') OR (@Route3 IS NULL))
ਊ⤀ഀ਀愀渀搀 ⠀䄀䤀刀开䌀伀䐀 䤀一⠀匀䔀䰀䔀䌀吀        䄀䤀刀开䌀伀䐀ഀ਀䘀刀伀䴀            䄀䤀刀开吀䬀吀ഀ਀圀䠀䔀刀䔀        ⠀吀䬀吀开䘀䈀 㴀 䀀䘀愀爀攀䈀愀猀攀⤀ഀ਀䜀刀伀唀倀 䈀夀 䄀䤀刀开䌀伀䐀⤀漀爀⠀䀀䘀愀爀攀䈀愀猀攀 椀猀 渀甀氀氀⤀⤀ഀ਀愀渀搀  䄀䤀刀开䌀伀䴀倀 渀漀琀 椀渀 ⠀猀攀氀攀挀琀  䄀椀爀䰀椀渀攀 昀爀漀洀 吀䴀倀开䄀䌀䌀伀㌀㌀　㘀 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀匀刀开䌀 最爀漀甀瀀 戀礀 䄀椀爀䰀椀渀攀 ⤀ഀ਀最爀漀甀瀀 戀礀 䄀䤀刀开䌀伀䴀倀ഀ਀ഀ਀ഀ਀ 搀攀氀攀琀攀 昀爀漀洀  吀䴀倀开䄀䌀䌀伀㌀㌀　㘀 眀栀攀爀攀 唀匀刀开䌀㴀䀀唀匀刀开䌀 愀渀搀 ഀ਀ 䈀䄀匀䤀䌀㄀㴀　 愀渀搀 吀伀吀䄀䰀㄀㴀　 愀渀搀 一䔀吀䤀一䌀伀䴀㄀㴀　 愀渀搀 䈀䄀匀䤀䌀㈀㴀　 愀渀搀 吀伀吀䄀䰀㈀㴀　 愀渀搀 一䔀吀䤀一䌀伀䴀㈀㴀　ഀ਀ഀ਀ ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㌀　㜀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀ ഀ਀ 䌀刀䔀䄀吀䔀 瀀爀漀挀   嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㌀　㜀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ഀ਀ऀ  䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀爀漀洀䐀愀琀攀 䐀愀琀攀吀椀洀攀ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 䐀愀琀攀吀椀洀攀ഀ਀ഀ਀ऀⰀ 䀀䄀椀爀开䰀椀渀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䄀椀爀开䈀爀愀渀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䄀䤀刀开䄀䌀䌀 椀渀琀 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䄀䤀刀开匀唀䈀 椀渀琀 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀愀椀爀开挀开瀀礀 渀瘀愀爀挀栀愀爀⠀㄀　⤀ 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䄀䤀刀开刀䔀䴀㌀ 渀瘀愀爀挀栀愀爀⠀㄀　⤀ 㴀 渀甀氀氀ഀ਀ഀ਀䄀匀ഀ਀ऀ䈀䔀䜀䤀一ഀ਀ഀ਀ ⼀⨀ഀ਀搀攀挀氀愀爀攀 䀀䘀爀漀洀 䐀愀琀攀吀椀洀攀ഀ਀搀攀挀氀愀爀攀 䀀吀漀 䐀愀琀攀吀椀洀攀ഀ਀ഀ਀搀攀挀氀愀爀攀 䀀䄀椀爀开䰀椀渀攀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ഀ਀搀攀挀氀愀爀攀 䀀䄀椀爀开䈀爀愀渀 渀瘀愀爀挀栀愀爀⠀㈀　⤀ഀ਀搀攀挀氀愀爀攀 䀀䄀䤀刀开䄀䌀䌀 椀渀琀ഀ਀搀攀挀氀愀爀攀 䀀䄀䤀刀开匀唀䈀 椀渀琀ഀ਀搀攀挀氀愀爀攀 䀀愀椀爀开挀开瀀礀 渀瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀搀攀挀氀愀爀攀 䀀䄀䤀刀开刀䔀䴀㌀ 渀瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ⴀⴀ刀攀焀ഀ਀猀攀琀 䀀䘀爀漀洀㴀✀　㄀⼀　㄀⼀㈀　㄀㌀✀ⴀⴀ吀伀ഀ਀猀攀琀 䀀吀漀㴀✀　㄀⼀　㄀⼀㈀　㄀㐀✀ ⴀⴀ䘀爀漀洀ഀ਀ ഀ਀ⴀⴀ伀瀀琀椀漀渀愀氀ഀ਀猀攀琀 䀀䄀椀爀开䰀椀渀攀㴀 一唀䰀䰀ⴀⴀ✀㌀伀✀   ⴀⴀ䄀椀爀开䰀椀渀攀ഀ਀猀攀琀 䀀䄀椀爀开䈀爀愀渀㴀一唀䰀䰀ⴀⴀ✀㈀✀    ⴀⴀ䄀椀爀开䈀爀愀渀ഀ਀猀攀琀 䀀䄀䤀刀开䄀䌀䌀㴀㄀㈀㈀㈀　　ⴀⴀ一唀䰀䰀ⴀⴀ  ⴀⴀ洀愀椀渀ഀ਀猀攀琀 䀀䄀䤀刀开匀唀䈀㴀  渀甀氀氀ⴀⴀ ㄀ⴀⴀ   ⴀⴀ猀甀戀ഀ਀猀攀琀 䀀䄀䤀刀开刀䔀䴀㌀㴀一唀䰀䰀ⴀⴀ✀㄀✀    ⴀⴀ挀爀椀搀椀琀 䌀愀爀琀ഀ਀ഀ਀ⴀⴀ匀攀琀 䐀攀昀愀甀氀琀ഀ਀猀攀琀 䀀愀椀爀开挀开瀀礀㴀✀㈀✀ഀ਀⨀⼀ഀ਀ഀ਀ऀऀⴀⴀ㄀    䐀䔀䰀䔀吀䔀ഀ਀ऀऀ搀攀氀攀琀攀  䘀刀伀䴀 吀䴀倀开䄀䌀䌀伀㌀㌀　㜀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ഀ਀ऀऀⴀⴀ㈀    䤀渀猀攀爀琀 猀琀愀琀攀洀攀渀琀猀 昀漀爀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀䤀一匀䔀刀吀 椀渀琀漀 吀䴀倀开䄀䌀䌀伀㌀㌀　㜀 ഀ਀ऀ匀䔀䰀䔀䌀吀  䀀唀匀刀开䌀 愀猀  唀匀刀开䌀 Ⰰ 䄀䰀⸀䄀䤀刀开䌀伀䐀 Ⰰ 䀀䘀爀漀洀䐀愀琀攀 䄀匀 嬀䘀刀伀䴀崀 Ⰰ䀀吀漀䐀愀琀攀 䄀匀 嬀吀伀崀 Ⰰ 䌀匀吀开一伀 䄀匀 䌀唀匀开䌀伀䐀 ഀ਀ऀऀⰀ 䄀䤀刀开䄀䌀䌀 愀猀 䴀䄀䤀一开䌀伀䐀 Ⰰ 䌀匀吀开一伀 愀猀 䌀唀匀开䌀伀䐀Ⰰ ⠀猀攀氀攀挀琀 猀甀洀⠀䄀倀⸀瀀愀礀开愀洀琀⤀ 昀爀漀洀 愀椀爀开瀀愀礀 愀猀 䄀倀 眀栀攀爀攀 ⠀䄀倀⸀倀䄀夀开吀夀倀 䤀匀 一唀䰀䰀 ऀ伀刀 䄀倀⸀倀䄀夀开吀夀倀 䤀一 ⠀✀✀Ⰰ✀ ✀Ⰰ✀㄀✀Ⰰ✀㈀✀Ⰰ✀㌀✀⤀⤀ 愀渀搀 䄀倀⸀䄀䤀刀开䌀伀䐀㴀䄀䰀⸀䄀䤀刀开䌀伀䐀⤀ 䄀匀 䐀䤀匀䌀伀唀一吀 ഀ਀ऀऀⰀ ⠀匀䔀䰀䔀䌀吀 䴀䤀一⠀吀䬀吀开一刀⤀ 䘀刀伀䴀 䄀䤀刀开吀䬀吀 愀猀 䄀吀 圀䠀䔀刀䔀 䄀吀⸀䄀䤀刀开䌀伀䐀㴀䄀䰀⸀䄀䤀刀开䌀伀䐀⤀ 䄀匀 吀䤀䌀䬀䔀吀开一伀 ഀ਀ऀऀⰀ䄀䤀刀开䤀匀匀Ⰰ䄀䤀刀开倀䄀匀匀ഀ਀ऀऀⰀ䄀䤀刀开䈀䄀匀 㴀椀猀渀甀氀氀⠀䄀䤀刀开䈀䄀匀Ⰰ　⤀ഀ਀ऀऀⰀ䄀䤀刀开吀䄀堀㄀㴀椀猀渀甀氀氀⠀䄀䤀刀开吀䄀堀㄀Ⰰ　⤀ഀ਀ऀऀⰀ䄀䤀刀开吀䄀堀㈀㴀椀猀渀甀氀氀⠀䄀䤀刀开吀䄀堀㈀Ⰰ　⤀ഀ਀ऀऀⰀ䄀䤀刀开吀䄀堀㌀㴀椀猀渀甀氀氀⠀䄀䤀刀开吀䄀堀㌀Ⰰ　⤀ഀ਀ऀऀⰀ䄀䤀刀开吀䄀堀㐀㴀椀猀渀甀氀氀⠀䄀䤀刀开吀䄀堀㐀Ⰰ　⤀ഀ਀ऀऀⰀ䄀䤀刀开吀䄀堀㔀㴀椀猀渀甀氀氀⠀䄀䤀刀开吀䄀堀㔀Ⰰ　⤀ഀ਀
		,AIR_STMP=isnull(AIR_STMP,0)
		,total = (isnull(AIR_BAS,0) + isnull(AIR_TAX1,0) + isnull(AIR_TAX2,0) + isnull(AIR_TAX3,0) + isnull(AIR_TAX4,0) + isnull(AIR_TAX5,0) + isnull(AIR_STMP,0))
		,AIR_CREDIT_CARDNO
			FROM AIR_LINE as AL join SUB_ACC on ACC_NU=AL.air_acc and SUB_NU=al.cst_no
				where  air_c_py = @air_c_py and AL.air_dat  between @FromDate and @ToDate 
				and ( (UPPER(air_comp) = @Air_Line AND @Air_Line is not null) OR (@Air_Line is null))
				and ((cst_no =@AIR_SUB ) or (@AIR_SUB is null))
				and ((AIR_ACC =@AIR_ACC and @AIR_ACC is not null)or(@AIR_ACC is null))
				and(( UPPER(AIR_CREDIT_CARDNO) like '%' + @AIR_REM3 + '%') OR (@AIR_REM3 is null)	)
				and 
(
(UPPER(air_bran) =@Air_Bran and @Air_Bran is not null)
OR(@Air_Bran is null)
)
  
 
END



















