吀开刀⤀ 䄀匀 䈀䌀刀䔀䐀䤀吀开刀ഀ਀Ⰰ匀唀䴀⠀䈀䌀刀䔀䐀䤀吀开䤀⤀ ⬀ 匀唀䴀⠀䈀䌀刀䔀䐀䤀吀开刀⤀ 䄀匀 匀唀䴀䌀刀䔀䐀䤀吀ഀ਀ഀ਀Ⰰ匀唀䴀⠀吀䌀刀䔀䐀䤀吀开䤀⤀ 䄀匀 吀䌀刀䔀䐀䤀吀开䤀ഀ਀Ⰰ匀唀䴀⠀吀䌀刀䔀䐀䤀吀开刀⤀ 䄀匀 吀䌀刀䔀䐀䤀吀开刀ഀ਀Ⰰ匀唀䴀⠀吀䌀刀䔀䐀䤀吀开䤀⤀ ⬀ 匀唀䴀⠀吀䌀刀䔀䐀䤀吀开刀⤀ 䄀匀 匀唀䴀吀䌀刀䔀䐀䤀吀ഀ਀ⴀⴀഀ਀Ⰰ匀唀䴀⠀䈀䌀䄀匀䠀开䤀⤀ ⬀ 匀唀䴀⠀䈀䌀刀䔀䐀䤀吀开䤀⤀ 䄀匀 吀伀吀䄀䰀䈀䄀匀䤀䌀开䤀ഀ਀
,SUM(BCASH_R) + SUM(BCREDIT_R) AS TOTALBASIC_R
--
,SUM(BCASH_I) + SUM(BCREDIT_I) + SUM(BCASH_R) + SUM(BCREDIT_R) AS TotalBasic
,SUM(tCASH_I) + SUM(tCREDIT_I) + SUM(tCASH_R) + SUM(tCREDIT_R) AS TotalTotal
,SUM(NETINCOME_I) as NETINCOME_I
,SUM(NETINCOME_R) as NETINCOME_R
,SUM(NETINCOME_I)+SUM(NETINCOME_R) as SumNETINCOME
,SUM(Discount_I) as Discount_I
,SUM(Discount_R) as Discount_R
,SUM(MF_I) as MF_I
,SUM(MF_R) as MF_R
,SUM(Services_I) as Services_I
,SUM(Services_R) as Services_R
,SUM(isnull(CountSales,0))  as CountSales
,SUM(CountRefund) as CountRefund
,SUM(isnull(CountVoid,0))   as CountVoid
,SUM(tCASH_I) + SUM(tCREDIT_I)  as SUMTOTAL_I
,SUM(tCASH_R) + SUM(tCREDIT_R)  as SUMTOTAL_R
,@ORDER AS [ORDER]
,@COUNT AS [COUNT]

FROM T
GROUP BY CST_NO,SUB_NM_E
 
)
INSERT into  TMP_ACCO3309 
SELECT 
TOP (CASE WHEN (@COUNT IS NOT NULL) THEN @COUNT ELSE  999999999 END ) @USR_C as USR_C ,  * FROM TT ORDER BY
		CASE @ORDER 
			WHEN 0 THEN TotalBasic
			WHEN 1 THEN TotalTotal
			WHEN 2 THEN SumNETINCOME
			ELSE TotalBasic
		END 
	 DESC

update TMP_ACCO3309 set TMP_ACCO3309.CountSales=isnull((
									SELECT  isnull(COUNT(isnull(AIR_LINE.AIR_COD,0)),0) AS Expr1
									FROM   AIR_LINE 
									WHERE air_acc=@MainAcc
									and  AIR_LINE.CST_NO = TMP_ACCO3309.CST_NO
									and AIR_K_TYP in ('1','2')
									AND air_dat Between @FromDate and @ToDate 
									and ((UPPER(air_comp) =@AirLine)OR(@AirLine is null))
									and ((air_bran =@Branch )OR(@Branch  is null))
									and ((air_f_typ = @ReportType)OR(@ReportType IS NULL))
									GROUP BY AIR_LINE.CST_NO),0)
where USR_C=@USR_C


update TMP_ACCO3309 set TMP_ACCO3309.CountRefund=isnull((
									SELECT  isnull(COUNT(isnull(AIR_LINE.AIR_COD,0)),0) AS Expr1
									FROM   AIR_LINE 
									WHERE air_acc=@MainAcc
									and  AIR_LINE.CST_NO = TMP_ACCO3309.CST_NO
									and AIR_K_TYP in ('3')
									AND air_dat Between @FromDate and @ToDate 
									and ((UPPER(air_comp) =@AirLine)OR(@AirLine is null))
									and ((air_bran =@Branch )OR(@Branch  is null))
									and ((air_f_typ = @ReportType)OR(@ReportType IS NULL))
									GROUP BY AIR_LINE.CST_NO),0)
where USR_C=@USR_C

