;WITH T AS(

SELECT AL.AIR_COD,air_acc,CST_NO,SUB_NM_E,AIR_K_TYP,air_p_ty

,BCASH_I = CASE WHEN  AIR_K_TYP IN ('1','2') AND (AIR_C_PY IN (1, 2)) THEN ISNULL(Air_BAS,0) ELSE 0 END
,BCASH_R = CASE WHEN  AIR_K_TYP IN ('3') AND  (AIR_C_PY IN (1, 2)) THEN ISNULL(Air_BAS,0) ELSE 0 END
,TCASH_I = CASE WHEN  AIR_K_TYP IN ('1','2') AND  (AIR_C_PY IN (1, 2)) THEN (ISNULL(Air_BAS,0)+ isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) ELSE 0 END
,TCASH_R = CASE WHEN  AIR_K_TYP IN ('3') AND  (AIR_C_PY IN (1, 2)) THEN (ISNULL(Air_BAS,0)+ isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) ELSE 0 END
,BCREDIT_I = CASE WHEN  AIR_K_TYP IN ('1','2') AND (AIR_C_PY IN (3)) THEN (ISNULL(Air_BAS,0)) ELSE 0 END
,BCREDIT_R = CASE WHEN  AIR_K_TYP IN ('3') AND (AIR_C_PY IN (3)) THEN (ISNULL(Air_BAS,0)) ELSE 0 END 
,TCREDIT_I = CASE WHEN  AIR_K_TYP IN ('1','2') AND (AIR_C_PY IN (3)) THEN (ISNULL(Air_BAS,0)+ isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) ELSE 0 END
,TCREDIT_R = CASE WHEN  AIR_K_TYP IN ('3') AND (AIR_C_PY IN (3)) THEN (ISNULL(Air_BAS,0)+ isnull(air_tax1,0) + isnull(air_tax2,0) + isnull(air_tax3,0) + isnull(air_tax4,0) + isnull(air_tax5,0) + isnull(air_stmp,0)) ELSE 0 END
,NETINCOME_I = ISNULL(CASE WHEN AL.AIR_K_TYP IN('1','2') THEN (Isnull(AL.Air_Comm,0) + Isnull(AL.Air_OR,0))-(Isnull(AL.Air_ComT,0) + Isnull(AL.Air_ORT,0)) +  IsNull(AL.AIR_S_F,0) - Pay.Des1_2 END,0)
,NETINCOME_R = ISNULL(CASE WHEN AL.AIR_K_TYP IN('3') THEN - ((abs(Isnull(AL.Air_Comm,0)) + abs(Isnull(AL.Air_OR,0)))-(abs(Isnull(AL.Air_ComT,0))+abs(Isnull(AL.Air_ORT,0)))) - abs(IsNull(AL.AIR_S_F,0)) + abs(PAY.Des4) END ,0)
,Discount_I = ISNULL(CASE WHEN AL.AIR_K_TYP IN('1','2') THEN  PAY.Des1_2 END,0)
,Discount_R = ISNULL(CASE WHEN AL.AIR_K_TYP IN('3') THEN  PAY.Des4 END,0)
