,Discount_I = ISNULL( CASE WHEN AL.AIR_K_TYP IN('1','2') THEN  (select sum(PAY_AMT) FROM AIR_PAY  WHERE AIR_COD= AL.AIR_COD AND PAY_TYP IN ('1','2')) END ,0)
,Discount_R = ISNULL( CASE WHEN AL.AIR_K_TYP IN('3') THEN  (select sum(PAY_AMT) FROM AIR_PAY  WHERE AIR_COD= AL.AIR_COD AND PAY_TYP IN ('1','2','4') ) END ,0)
,MF_I = ISNULL( CASE  WHEN AL.AIR_K_TYP IN('1','2') THEN (IsNull(AL.AIR_S_F,0) ) END ,0)
,MF_R = ISNULL( CASE WHEN AL.AIR_K_TYP IN('3') THEN  ( IsNull(AL.AIR_S_F,0) ) END ,0)
,NETINCOME_I = ISNULL( CASE  WHEN AL.AIR_K_TYP IN('1','2') THEN  (Isnull(AL.Air_Comm,0) + Isnull(AL.Air_OR,0))-(Isnull(AL.Air_ComT,0)+Isnull(AL.Air_ORT,0))  +  IsNull(AL.AIR_S_F,0) - (SELECT ISNULL(SUM(PAY_AMT),0) FROM AIR_PAY WHERE AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2')) END,0)
,NETINCOME_R = ISNULL( CASE WHEN AL.AIR_K_TYP IN('3') THEN  - ((abs(Isnull(AL.Air_Comm,0)) + abs(Isnull(AL.Air_OR,0)))-(abs(Isnull(AL.Air_ComT,0))+abs(Isnull(AL.Air_ORT,0)))) - abs(IsNull(AL.AIR_S_F,0)) + abs((SELECT ISNULL(SUM(PAY_AMT),0) FROM AIR_PAY WHERE AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2','4'))) END ,0)
--<<<<<<<<<Net Payment>>>>>>>
,NetPay_ISS_REI = ( case when (AL.AIR_K_TYP IN ('1','2') AND AL.AIR_C_PY IN ('1','3')) THEN (((ISNULL(AL.AIR_BAS,0) + ISNULL(AL.AIR_TAX1,0) + ISNULL(AL.AIR_TAX2,0) + ISNULL(AL.AIR_TAX3,0) + ISNULL(AL.AIR_TAX4,0) + ISNULL(AL.AIR_TAX5,0) + ISNULL(AL.AIR_STMP,0) + ISNULL(AIR_S_F,0)) - ISNULL((SELECT SUM(AP.PAY_AMT) FROM AIR_PAY AS AP WHERE AP.AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2')),0))) ELSE 0 END )
,NetPay_ISS_CC = ( case when (AL.AIR_K_TYP IN ('1') AND AL.AIR_C_PY IN ('2'))  THEN  ( -ISNULL((SELECT SUM(AP.PAY_AMT) FROM AIR_PAY AS AP WHERE AP.AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2')),0) + ISNULL(AIR_S_F,0) ) ELSE 0 END )
,NetPay_ISS_REFUND = ( case when (AL.AIR_K_TYP IN ('3') AND AL.AIR_C_PY IN ('1','3'))  THEN  ( (-(abs(ISNULL(AL.AIR_BAS,0) ) + abs(ISNULL(AL.AIR_TAX1,0)) + abs(ISNULL(AL.AIR_TAX2,0)) + abs(ISNULL(AL.AIR_TAX3,0)) + abs(ISNULL(AL.AIR_TAX4,0)) + abs(ISNULL(AL.AIR_TAX5,0)) + abs(ISNULL(AL.AIR_STMP,0))) - abs(ISNULL(AIR_S_F,0))) + abs(ISNULL((SELECT SUM(AP.PAY_AMT) FROM AIR_PAY AS AP WHERE AP.AIR_COD=AL.AIR_COD AND PAY_TYP IN ('1','2','4','5')),0)) ) ELSE 0 END )
