CREATE proc   [Finance].[SPACCO3313]
	-- Add the parameters for the stored procedure here
	  @USR_C varchar(10)
	, @FromDate DateTime
	, @ToDate DateTime
	, @CustMainAcc Real
	, @FMCustSub Real
	, @ToCustSub Real
	, @AirComp varchar(3) = null
	, @Branch varchar(3) = null
    , @RepType varchar(1) = null --0 all ,1=intl (air_f_typ = '1') ,2=Dom (air_f_typ = '2')
	
AS
declare  @FromDate2 DateTime
declare  @ToDate2 DateTime
	BEGIN
	set @FromDate2 = DateAdd("YYYY", -1,@FromDate)
	
	set @ToDate2 = DateAdd("YYYY", -1, @ToDate)
	print @FromDate2
	print @ToDate2
	--if @Branch  is null
	--set @Branch='All'
	--if @AirComp is null
	--set @AirComp='All'
	
	--1    DELETE
	delete  FROM TMP_ACCO3313 WHERE USR_C=@USR_C
	
	insert into TMP_ACCO3313 (
	USR_C, FROMDATE1, FROMDATE2, TODATE1, TODATE2, AIRLINECO, BRANCH, REPTYP, CSTCOD, CSTNAME, FLAG, BAS1, TOT1, NETIN1, DES1, 
                         BASPER, TOTPER, BAS2, TOT2, NETIN2, DES2

	)
	SELECT    @USR_C,@FromDate,@FromDate2,@ToDate,@ToDate2, @AirComp, @Branch,@RepType ,AIR_LINE.CST_NO, SUB_ACC.SUB_NM_E,case when AIR_K_TYP='3' then '3' else '1' end as  flag
						, sum(ISNULL(AIR_LINE.AIR_BAS, 0)) AS AIR_BAS, 
                        sum( ISNULL(AIR_LINE.AIR_BAS, 0) + ISNULL(AIR_LINE.AIR_TAX1, 0) + ISNULL(AIR_LINE.AIR_TAX2, 0) + ISNULL(AIR_LINE.AIR_TAX3, 0) 
                         + ISNULL(AIR_LINE.AIR_TAX4, 0) + ISNULL(AIR_LINE.AIR_TAX5, 0) + ISNULL(AIR_LINE.AIR_STMP, 0)) AS Total
						 ,sum( (ISNULL(AIR_LINE.AIR_COMM, 0)  + ISNULL(AIR_LINE.AIR_OR, 0)) - (ISNULL(AIR_LINE.AIR_COMT, 0) + ISNULL(AIR_LINE.AIR_ORT, 0))) + sum(ISNULL(AIR_LINE.AIR_S_F, 0))   -sum(ISNULL(Pay.Pay_Amt, 0)) AS NetIn1
