	--	DELETE FROM TMP_ACCO3317_2 WHERE (TAX IN (0) OR TAX IS NULL)
-- --------------------------------------------------------------------------------------------------------------------
 DECLARE TKT_cursor CURSOR FOR    SELECT   TKTNO 	FROM  TMP_ACCO3317_1 WHERE  USR_C = @USR_C  ORDER BY TKTNO
	OPEN TKT_cursor  DECLARE @TKTNO REAL
	FETCH NEXT FROM TKT_cursor INTO @TKTNO
	WHILE (@@FETCH_STATUS <> -1) 
	BEGIN  
		-----------------------------------
		
		If @MyLastTkt <> 0 AND @TKTNO <> @MyLastTkt + 1 And @TKTNO <> @MyLastTkt 
		BEGIN
			SET @MyMiss  = @MyMiss  +1
			INSERT INTO TMP_ACCO3317_1  (usr_c,reqno,tktno,missing,AIRLINECO,FROMTKT,TOTKT,[ROOT]) 
					values ( @USR_C , 0 , @MyLastTkt + 1  , @MyMiss , @AIR_COMP , @FROMTKTNO , @TOTKTNO , 0 ) 
		END 
		SET @MyLastTkt = @TKTNO
		-----------------------------------
		FETCH NEXT FROM TKT_cursor INTO @TKTNO
END 

CLOSE TKT_cursor
DEALLOCATE TKT_cursor

