----- UPDATE TMP_ACC3317_1 FROM AIR_PAY --------------------------
UPDATE TMP_ACCO3317_1 SET TMP_ACCo3317_1.DIS_CASH = ISNULL(((SELECT SUM(AIR_PAY.PAY_AMT)  from air_pay WHERE USR_C = @USR_C and TMP_ACCo3317_1.REQNO = AIR_PAY.AIR_COD)),0) where USR_C = @USR_C

