	   and (((air_tkt.TKT_NR)<=@TOTKTNR) or(@TOTKTNR is NULL))
	   and  ((UPPER(air_line.air_comp)=@AIR_COMP) or(@AIR_COMP is NULL)) 
	   and  ((UPPER(air_line.air_bran)=@AIR_BRAN) or(@AIR_BRAN is NULL)) 
	   and ((UPPER(air_line.EMP_CODE)=@EMP_COD) or(@EMP_COD is NULL))  
	  
	   select *  FROM TMP_ACCO3318 WHERE USR_C=@USR_C

END










