猀猀甀攀Ⰰ 䤀匀一唀䰀䰀⠀倀愀礀⸀䐀攀猀㄀开㈀开㐀Ⰰ 　⤀ 䄀匀 䐀椀猀挀漀甀渀琀开刀攀昀甀渀搀Ⰰ 䄀䰀⸀䄀䤀刀开䈀䄀匀Ⰰ 吀欀琀⸀吀欀琀开一漀Ⰰ ഀ਀ऀऀऀ 䤀匀一唀䰀䰀⠀匀爀瘀⸀匀爀瘀开䄀䴀吀Ⰰ 　⤀ 䄀匀 匀爀瘀开䄀䴀吀Ⰰ ഀ਀
			 ISNULL(CASE WHEN Air_K_Typ IN (1, 2) THEN ((isnull(air_comm, 0) + isnull(Air_or, 0)) - (isnull(air_comt, 0) + air_ort) + isnull(air_s_f, 0) - isnull(Des1_2, 0)) ELSE 0 END, 0) AS NetIncomeIssue, 
			 ISNULL(CASE WHEN Air_K_Typ IN (3) THEN (- abs((isnull(air_comm, 0) + isnull(Air_or, 0)) - (isnull(air_comt, 0) + air_ort)) - abs(isnull(air_s_f, 0)) + abs(isnull(Des1_2_4, 0))) ELSE 0 END, 0) AS NetIncomeRefund,
			 isnull(isnull((air_comm),0) + isnull((Air_or),0) - isnull((air_comt),0) + isnull(air_ort,0),0) as NetCommX,
			 Des1_2 , Des1_2_4 , PayType
		
		FROM  Finance.AIR_LINE AS AL 
				LEFT OUTER JOIN 
				(SELECT   ISNULL(SUM(ISNULL(PAY_AMT, 0)), 0) AS PAY_AMT, 
					ISNULL(SUM(CASE WHEN PAY_TYP IN (1, 2) THEN isnull(PAY_AMT, 0) ELSE 0 END), 0) AS Des1_2, 
					ISNULL(SUM(CASE WHEN PAY_TYP IN (4) THEN isnull(PAY_AMT, 0) ELSE 0 END), 0) AS Des1_2_4, AIR_COD,
					min(PAY_TYP) as PayType
						   FROM  Finance.AIR_PAY
								GROUP BY AIR_COD
				) AS Pay ON AL.AIR_COD = Pay.AIR_COD 
				
				LEFT OUTER JOIN
				Finance.EMP AS EMP_1 ON AL.EMP_CODE = EMP_1.EMP_CODE 
				INNER JOIN
				(SELECT    AIR_COD, min(TKT_NR)  AS Tkt_No
									 FROM    Finance.AIR_TKT
									 where  (
												(TKT_FB in( @TKT_FB1 , @TKT_FB2 , @TKT_FB3, @TKT_FB4, @TKT_FB5, @TKT_FB6, @TKT_FB7, @TKT_FB8, @TKT_FB9, @TKT_FB10 ) 
												or (@TKT_FB1 is null and @TKT_FB2 is null and @TKT_FB3 is null and @TKT_FB4 is null and @TKT_FB5 is null and @TKT_FB6 is null and @TKT_FB7 is null and @TKT_FB8 is null and @TKT_FB9 is null and @TKT_FB10 is null ) 
												)
											 )  
									   GROUP BY AIR_COD
				) AS Tkt ON AL.AIR_COD = Tkt.AIR_COD 
				
				INNER JOIN
				Finance.SUB_ACC ON AL.CST_NO = Finance.SUB_ACC.SUB_NU AND AL.AIR_ACC = Finance.SUB_ACC.ACC_NU 
				LEFT OUTER JOIN
				(SELECT     SUM(ISNULL(SRV_AMT, 0)) AS Srv_AMT, AIR_COD
									 FROM         Finance.AIR_SRV
									 GROUP BY AIR_COD
				) AS Srv ON AL.AIR_COD = Srv.AIR_COD
		where 
							(AL.EMP_CODE = @EmpCode OR @EmpCode IS NULL)
							and air_dat between @FromDate and @ToDate
							and ((UPPER(air_bran) =@Branch and @Branch is not null)or(@Branch is null))
