		delete  FROM TMP_ACCO3321 WHERE USR_C = @USR_C
	--2    Insert statements for procedure here


			
		IF (@ReportData ='0') ---- Completed 
		begin 
			insert into TMP_ACCO3321
			SELECT  @USR_C , AIR_COD, AIR_PASS, EMP_CODE, CST_NO, (SELECT SUB_ACC.SUB_NM_E FROM  SYS_DATA INNER JOIN SUB_ACC ON SYS_DATA.CUS_AIR = SUB_ACC.ACC_NU WHERE (SUB_ACC.SUB_NU = AIR_LINE.CST_NO)) AS CSTNAME, 
					AIR_ROUT, AIR_COMP, AIR_BAS, ISNULL(AIR_TAX1, 0) + ISNULL(AIR_TAX2, 0) + ISNULL(AIR_TAX3, 0) + ISNULL(AIR_TAX4, 0) + ISNULL(AIR_TAX5, 0) AS TAX, AIR_STMP, 
					ISNULL(AIR_BAS, 0) + ISNULL(AIR_STMP, 0) + ISNULL(AIR_TAX1, 0) + ISNULL(AIR_TAX2, 0) + ISNULL(AIR_TAX3, 0) + ISNULL(AIR_TAX4, 0) + ISNULL(AIR_TAX5, 0) AS TOTAL, AIR_ISS , 'F' , 0
			FROM  AIR_LINE
					WHERE (AIR_DAT BETWEEN @FromDate AND @ToDate) 
					 AND (( air_cod BETWEEN @FROMREQU AND @TOREQU) OR (@TOREQU IS NULL))
					 AND ((AIR_BRAN= @AIR_BRAN ) or (@AIR_BRAN is null))
					 AND (AIR_K_TYP <> '4')  and  EMP_CODE <> ''  and air_pay is not null
					ORDER BY AIR_COD
	
		End
		
		IF (@ReportData ='1') ---- Not Completed
		begin 
			insert into TMP_ACCO3321
			SELECT  @USR_C , AIR_COD, AIR_PASS, EMP_CODE, CST_NO, (SELECT SUB_ACC.SUB_NM_E FROM  SYS_DATA INNER JOIN SUB_ACC ON SYS_DATA.CUS_AIR = SUB_ACC.ACC_NU WHERE (SUB_ACC.SUB_NU = AIR_LINE.CST_NO)) AS CSTNAME, 
					AIR_ROUT, AIR_COMP, AIR_BAS, ISNULL(AIR_TAX1, 0) + ISNULL(AIR_TAX2, 0) + ISNULL(AIR_TAX3, 0) + ISNULL(AIR_TAX4, 0) + ISNULL(AIR_TAX5, 0) AS TAX, AIR_STMP, 
					ISNULL(AIR_BAS, 0) + ISNULL(AIR_STMP, 0) + ISNULL(AIR_TAX1, 0) + ISNULL(AIR_TAX2, 0) + ISNULL(AIR_TAX3, 0) + ISNULL(AIR_TAX4, 0) + ISNULL(AIR_TAX5, 0) AS TOTAL, AIR_ISS , 'F' , 0
			FROM  AIR_LINE
					WHERE (AIR_DAT BETWEEN @FromDate AND @ToDate) 
					 AND (( air_cod BETWEEN @FROMREQU AND @TOREQU) OR (@TOREQU IS NULL))
					 AND ((AIR_BRAN= @AIR_BRAN ) or (@AIR_BRAN is null))
					 AND (AIR_K_TYP <> '4')  and  (EMP_CODE = '' or AIR_PAY is null)
					ORDER BY AIR_COD
		
		End

		IF (@ReportData ='2')  --- Get All
