SELECT       @USR_C, AIR.ACC_NU, AIR.AIR_COD, isnull(AIR.DIS_CASH,0),  isnull(AIR.DIS_PAY,0), AIR.AIR_PASS, AIR.CST_NO, AIR.AIR_COMP, AIR.AIR_C_PY,  isnull(AIR.AIR_BAS,0), isnull(AIR.TOTTAX,0), 
                          isnull(AIR.AIR_COMM,0), isnull( AIR.AIR_OR,0),  isnull(AIR.COMMTAX,0), AIR.AIR_DAT, AIR.AIR_REC1, AIR.AIR_P_TY, AIR.AIR_K_TYP,  isnull(pay.CR_AMT,0) AS pay,  isnull(AIR.AIR_S_F,0),'' as SUB_NM_E
FROM            (SELECT        @USR_C AS USR_C, AIR_LINE.AIR_ACC AS ACC_NU, AIR_LINE.AIR_COD, CASE WHEN AIR_LINE.AIR_P_TY = 1 THEN SUM(AIR_PAY.PAY_AMT) 
