                                                    + ISNULL(AIR_LINE.AIR_TAX3, 0) + ISNULL(AIR_LINE.AIR_TAX4, 0) + ISNULL(AIR_LINE.AIR_TAX5, 0) + ISNULL(AIR_LINE.AIR_STMP, 0) AS TOTTAX, 
                                                    AIR_LINE.AIR_COMM, AIR_LINE.AIR_OR, ISNULL(AIR_LINE.AIR_COMT, 0) + ISNULL(AIR_LINE.AIR_ORT, 0) AS COMMTAX, AIR_LINE.AIR_DAT, 
