 CREATE proc   [Finance].[SPACCO3323]
	-- Add the parameters for the stored procedure here
	@USR_C varchar(10)
	,@FromDate Datetime
	,@ToDate Datetime 

	,@FromPrev Datetime = null
	,@ToPrev  Datetime = null
	,@AIR_BRAN VARCHAR(3) = null

	, @ZeroBalanceAppear VARCHAR(1) = null
 
AS
	BEGIN

	--set @FromCurr='01/01/2013' 
	--set @ToCurr='01/01/2014'  

	--set @FromPrev='01/01/2012' 
	--set @ToPrev='01/01/2013' 
	--set @Air_Bran =null--'1'


			--1    DELETE
		delete  FROM TMP_ACCO3323 WHERE USR_C = @USR_C
			--2    Insert statements for procedure here

;WITH t as (
	select 
	 al.EMP_CODE
	, al.air_cod
	, (AIR_BAS) as BASIC1
	, (AIR_BAS)+ (ISNULL(AIR_TAX1,0)) +(ISNULL(AIR_TAX2,0)) +(ISNULL(AIR_TAX3,0))+(ISNULL(AIR_TAX4,0))+(ISNULL(AIR_TAX5,0))+(ISNULL(AIR_STMP,0)) as TOTAL1
	, NET1 = CASE WHEN (al.AIR_K_TYP =1 OR al.AIR_K_TYP=2) 
	--ISSUE/REISSUE
			THEN ( (isnull(AIR_COMM ,0)+ isnull(AIR_OR,0))  - (isnull(AIR_COMT,0) + isnull(AIR_ORT,0)) +isnull(AIR_S_F,0) -(isnull(( select sum(air_pay.pay_amt) from  air_pay where  al.air_cod=air_pay.air_cod AND air_pay.pay_typ in ('1','2') ),0)) )
				WHEN (al.AIR_K_TYP =3 ) --REFUND      
			THEN ( -((abs(isnull(al.AIR_COMM ,0))+ abs(isnull(al.AIR_OR,0)))  - (abs(isnull(al.AIR_COMT,0)) + abs(isnull(al.AIR_ORT,0)))) - abs(isnull(AIR_S_F,0)) + (abs(isnull(( select sum(air_pay.pay_amt) from  air_pay where  al.air_cod=air_pay.air_cod AND air_pay.pay_typ in ('1','2','4') ),0))) ) ELSE 0 END from air_line as al
					where al.AIR_DAT BETWEEN @FromDate AND  @ToDate AND ((al.AIR_BRAN=@Air_Bran and @Air_Bran is not null)or(@Air_Bran is null))  )
