CREATE procedure [Finance].[SPACCO3324]
	-- Add the parameters for the stored procedure here
		@USR_C varchar(10) ,
		@FROMTKTNO bigint = null ,
		@TOTKTNO bigint= null ,

		@FromDate Datetime ,
		@ToDate Datetime ,
		@AIR_COMP VARCHAR(3)= null ,
		@MyRoot1 VARCHAR(3)= null ,
		@MyRoot2 VARCHAR(3)= null ,
		@MyRoot3 VARCHAR(3)= null 
	 
AS
BEGIN


	DELETE  FROM  TMP_ACCO3324 WHERE USR_C = @USR_C
 

 --***********************************************************************************************
 --na replace above sql with this
 insert into TMP_ACCO3324
 SELECT     @USR_C AS USR_C, Finance.AIR_TKT.TKT_NR AS TKTNO, 1 AS MISSING, AL.AIR_COD AS REQNO, AL.AIR_COMP AS AIRLINECO, 
                      @FROMTKTNO AS FROMTKT, @TOTKTNO AS TOTKT, @FromDate AS FROMDATE, @ToDate AS TODATE, LEFT(AL.AIR_ROUT, 30) AS ROUTE, 
                      ISNULL(Finance.AIR_TKT.TKT_FB, '') AS FB, AL.AIR_DAT AS Date, AL.AIR_COMP AS CARR, CASE WHEN AIR_C_PY IN (1) THEN isnull(Tkt_Amt, 0) ELSE 0 END AS BCASH, 
                      CASE WHEN AIR_C_PY IN (2) THEN isnull(Tkt_Amt, 0) ELSE 0 END AS BCC, CASE WHEN AIR_C_PY IN (3) THEN isnull(Tkt_Amt, 0) ELSE 0 END AS BCREDIT, 
                      CASE WHEN AIR_C_PY IN (1) THEN isnull(Tkt_Tot, 0) ELSE 0 END AS TOTCASH, CASE WHEN AIR_C_PY IN (2) THEN isnull(Tkt_Tot, 0) ELSE 0 END AS TOTCC, 
                      CASE WHEN AIR_C_PY IN (3) THEN isnull(Tkt_Tot, 0) ELSE 0 END AS TOTCREDIT, CASE WHEN isnull(AL.AIR_BAS, 0) = 0 THEN isnull(AIR_COMM, 0) 
                      ELSE isnull(AL.AIR_COMM, 0) / isnull(AL.AIR_BAS, 0) * isnull(.AIR_TKT.TKT_AMT, 0) END AS COMM, LEFT(ISNULL(Finance.AIR_TKT.TKT_PASS, ''), 30) AS PASS, 
                      AL.CST_NO AS CSTCODE, ISNULL(Finance.SUB_ACC.SUB_NM_E, '') AS CSTNAME, ISNULL(AL.AIR_REC1, '') AS INVOICE, LEFT(ISNULL(AL.AIR_REM, ''), 50) AS Rem, 
