-- =============================================
-- Author:		<Author,,Name>
-- alter date: <alter Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Finance].[SPACCO3326]
	-- Add the parameters for the stored procedure here
	  @USR_C varchar(10),
	  @FROMTKTNR bigint,
	  @ToTktNo bigint
	 
AS
BEGIN

DECLARE @Var1ForSet bigint

	delete  FROM TMP_ACCO3326 WHERE USR_C=@USR_C
	
Declare @count bigint = @FROMTKTNR

while (@count <= @ToTktNo)
begin
 -- some statements
SET @Var1ForSet = isnull ((SELECT   (TKT_NR) as tt FROM AIR_TKT WHERE  TKT_NR =@count group by TKT_NR),0)
IF @Var1ForSet = 0
BEGIN
	INSERT INTO  TMP_ACCO3326  ( USR_C , TKT_NR )
	VALUES ( @USR_C,  @count )
END
	set @count += 1 -- basically increment by 1 day
end

END










