--SELECT SUM(AIR_BAS + AIR_TAX1 + AIR_TAX2 + AIR_TAX3 + AIR_TAX4 + AIR_TAX5 + AIR_STMP)   FROM aIR_lINE WHERE Air_line.AIR_COMP = '' and  AIR_DAT >= '01/01/2014 ' AND  AIR_DAT <= '01/30/2014' 
Update TMP_ACCO3330 SET AIR_TOT_PREV_YEAR = (SELECT isnull(SUM(isnull(AIR_BAS,0) + isnull(AIR_TAX1,0) + isnull(AIR_TAX2,0) + isnull(AIR_TAX3,0) + isnull(AIR_TAX4,0) + isnull(AIR_TAX5,0) + isnull(AIR_STMP,0)),0)  FROM aIR_lINE WHERE  AIR_DAT >= @FromDate AND  AIR_DAT <= @ToDate and TMP_ACCO3330.AIR_COMP = AIR_LINE.AIR_COMP)  WHERE  USR_C=@USR_C


set @FromDate =  DATEADD(year, -1, @FromDate)
set @ToDate =  DATEADD(year, -1, @ToDate)
--SELECT SUM(Air_Line.AIR_BAS) FROM aIR_lINE WHERE Air_line.AIR_COMP = '' and  AIR_DAT >= '01/01/2013 ' AND  AIR_DAT <= '01/30/2013' 
Update TMP_ACCO3330 SET AIR_BAS2 = (SELECT isnull(SUM(Air_Line.AIR_BAS), 0) FROM aIR_lINE WHERE AIR_DAT >= @FromDate AND  AIR_DAT <= @ToDate and TMP_ACCO3330.AIR_COMP = AIR_LINE.AIR_COMP)  WHERE  USR_C=@USR_C

