CREATE procEDURE [Finance].[SPACCO3401]
	-- Add the parameters for the stored procedure here
		@USR_C varchar(10) -- إسم المستخدم
		, @IssuePayFM Datetime -- إصدار و سداد من تاريخ
		, @IssuePayTO Datetime -- إصدار و سداد إلى تاريخ 
		, @FMInvoiceNO int = null -- من رقم فاتورة 
		, @TOInvoiceNo int= null -- إلى رقم فاتورة
		, @ACC_NU int -- رقم الحساب الرئيسى
		, @FM_SUB_NU int= null -- رقم الحساب الفرعى
		, @ReportType int -- نوع التقرير مدين = 1 دائن = 2 كل الحركات = 0

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DELETE TMP_ACC3401 WHERE USR_C = @USR_C


If @ReportType  = '1'  -- كل الدائنة 
BEGIN
	INSERT INTO  TMP_ACC3401
	([USR_C],[ENT_REC3],[JRN_DATE],[ENT_DR],[ENT_CR],[SUB_NU],[ACC_NU],[JRN_TYP],[ENT_DES],[SUB_NM_A],[ACC_NM_A],[JRN_NU])

		SELECT 
		@USR_C AS [USR_C],EI.ENT_REC3,J.JRN_DATE,EI.ENT_DR,EI.ENT_CR,EI.SUB_NU,EI.ACC_NU,ENTRY_TP.JRN_TYP,EI.ENT_DES,SUB.SUB_NM_A,ACC.ACC_NM_A,J.JRN_NU
	  FROM
		ENTRY_I  AS EI 
		INNER JOIN MAIN_ACC as ACC ON EI.ACC_NU = ACC.ACC_NU 
ਊऀऀ䤀一一䔀刀 䨀伀䤀一 匀唀䈀开䄀䌀䌀 愀猀 匀唀䈀 伀一 䔀䤀⸀匀唀䈀开一唀 㴀 匀唀䈀⸀匀唀䈀开一唀 䄀一䐀 䔀䤀⸀䄀䌀䌀开一唀 㴀 匀唀䈀⸀䄀䌀䌀开一唀 䄀一䐀 䄀䌀䌀⸀䄀䌀䌀开一唀 㴀 匀唀䈀⸀䄀䌀䌀开一唀 ഀ਀ऀऀ䤀一一䔀刀 䨀伀䤀一 䨀伀唀刀一䄀䰀 愀猀 䨀 伀一 䔀䤀⸀䨀刀一开䤀䐀 㴀 䨀⸀䨀刀一开䤀䐀ഀ਀ऀऀ 䤀一一䔀刀 䨀伀䤀一 䔀一吀刀夀开吀倀 伀一 䨀⸀䨀刀一开吀夀倀 㴀 䔀一吀刀夀开吀倀⸀䤀䐀ഀ਀ऀऀ ഀ਀ऀ  圀䠀䔀刀䔀 ഀ਀ऀ  䔀䤀⸀䔀一吀开刀䔀䌀㌀ 㰀㸀 ✀　✀ഀ਀ऀ  䄀一䐀 䔀䤀⸀䄀䌀䌀开一唀 㴀 䀀䄀䌀䌀开一唀 ഀ਀ऀ  ⴀⴀ 倀䰀 　㜀⼀　㘀⼀㈀　㄀㔀ഀ਀ऀ  ⴀⴀ䄀一䐀 䔀䤀⸀匀唀䈀开一唀 㴀 䀀䘀䴀开匀唀䈀开一唀 ഀ਀ऀ  䄀一䐀 ⠀䀀䘀䴀开匀唀䈀开一唀 椀猀 渀甀氀氀 漀爀⠀䀀䘀䴀开匀唀䈀开一唀 椀猀 渀漀琀 渀甀氀氀 愀渀搀 䔀䤀⸀匀唀䈀开一唀 㴀 䀀䘀䴀开匀唀䈀开一唀⤀⤀ ഀ਀ऀ  ⴀⴀഀ਀ऀഀ਀ऀ  䄀一䐀 䨀⸀䨀刀一开䐀䄀吀䔀 䈀䔀吀圀䔀䔀一 䀀䤀猀猀甀攀倀愀礀䘀䴀 䄀一䐀 䀀䤀猀猀甀攀倀愀礀吀伀ഀ਀ऀ   ⴀⴀ 倀䰀 　㜀⼀　㘀⼀㈀　㄀㔀ഀ਀  ऀ  䄀一䐀⠀⠀挀愀猀攀  椀猀渀甀洀攀爀椀挀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 眀栀攀渀 ㄀ 琀栀攀渀 挀愀猀琀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀ 愀猀  一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀⤀ 攀氀猀攀 　 攀渀搀 㸀㴀 䀀䘀䴀䤀渀瘀漀椀挀攀一漀 ഀ਀ऀ  䄀一䐀 挀愀猀攀  椀猀渀甀洀攀爀椀挀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 眀栀攀渀 ㄀ 琀栀攀渀 挀愀猀琀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀ 愀猀  一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀⤀ 攀氀猀攀 　 攀渀搀 㰀㴀 䀀吀伀䤀渀瘀漀椀挀攀一漀  ⤀ഀ਀ऀ  ⴀⴀ 䄀一䐀⠀⠀挀漀渀瘀攀爀琀⠀一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀Ⰰ 䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 㸀㴀 䀀䘀䴀䤀渀瘀漀椀挀攀一漀 ഀ਀ऀ  ⴀⴀ䄀一䐀 挀漀渀瘀攀爀琀⠀一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀Ⰰ 䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 㰀㴀 䀀吀伀䤀渀瘀漀椀挀攀一漀  ⤀ഀ਀ऀ  ⴀⴀഀ਀  ऀഀ਀ऀ  漀爀⠀䀀䘀䴀䤀渀瘀漀椀挀攀一漀 椀猀 渀甀氀氀⤀漀爀⠀䀀吀伀䤀渀瘀漀椀挀攀一漀 椀猀 渀甀氀氀⤀⤀ऀऀഀ਀  ऀ  䄀一䐀 䔀䤀⸀䔀一吀开䐀刀 㰀㸀 　ഀ਀  ऀ  ഀ਀䔀一䐀 ഀ਀䔀䰀匀䔀 䤀䘀 䀀刀攀瀀漀爀琀吀礀瀀攀  㴀 ✀㈀✀  ⴀⴀ ✀䐆ⴆㄆ䌆✆⨆ ✀䐆䔆⼆䨆䘆⤆ ഀ਀ऀ䈀䔀䜀䤀一ഀ਀ऀ䤀一匀䔀刀吀 䤀一吀伀  吀䴀倀开䄀䌀䌀㌀㐀　㄀ഀ਀ऀ⠀嬀唀匀刀开䌀崀Ⰰ嬀䔀一吀开刀䔀䌀㌀崀Ⰰ嬀䨀刀一开䐀䄀吀䔀崀Ⰰ嬀䔀一吀开䐀刀崀Ⰰ嬀䔀一吀开䌀刀崀Ⰰ嬀匀唀䈀开一唀崀Ⰰ嬀䄀䌀䌀开一唀崀Ⰰ嬀䨀刀一开吀夀倀崀Ⰰ嬀䔀一吀开䐀䔀匀崀Ⰰ嬀匀唀䈀开一䴀开䄀崀Ⰰ嬀䄀䌀䌀开一䴀开䄀崀Ⰰ嬀䨀刀一开一唀崀⤀ഀ਀ഀ਀ऀऀ匀䔀䰀䔀䌀吀 ഀ਀ऀऀऀ䀀唀匀刀开䌀 䄀匀 嬀唀匀刀开䌀崀Ⰰ䔀䤀⸀䔀一吀开刀䔀䌀㌀Ⰰ䨀⸀䨀刀一开䐀䄀吀䔀Ⰰ䔀䤀⸀䔀一吀开䐀刀Ⰰ䔀䤀⸀䔀一吀开䌀刀Ⰰ䔀䤀⸀匀唀䈀开一唀Ⰰ䔀䤀⸀䄀䌀䌀开一唀Ⰰ䔀一吀刀夀开吀倀⸀䨀刀一开吀夀倀Ⰰ䔀䤀⸀䔀一吀开䐀䔀匀Ⰰ匀唀䈀⸀匀唀䈀开一䴀开䄀Ⰰ䄀䌀䌀⸀䄀䌀䌀开一䴀开䄀Ⰰ䨀⸀䨀刀一开一唀ഀ਀ऀ  䘀刀伀䴀ഀ਀ऀऀ䔀一吀刀夀开䤀  䄀匀 䔀䤀 ഀ਀ऀऀ䤀一一䔀刀 䨀伀䤀一 䴀䄀䤀一开䄀䌀䌀 愀猀 䄀䌀䌀 伀一 䔀䤀⸀䄀䌀䌀开一唀 㴀 䄀䌀䌀⸀䄀䌀䌀开一唀 ഀ਀ऀऀ䤀一一䔀刀 䨀伀䤀一 匀唀䈀开䄀䌀䌀 愀猀 匀唀䈀 伀一 䔀䤀⸀匀唀䈀开一唀 㴀 匀唀䈀⸀匀唀䈀开一唀 䄀一䐀 䔀䤀⸀䄀䌀䌀开一唀 㴀 匀唀䈀⸀䄀䌀䌀开一唀 䄀一䐀 䄀䌀䌀⸀䄀䌀䌀开一唀 㴀 匀唀䈀⸀䄀䌀䌀开一唀 ഀ਀ऀऀ䤀一一䔀刀 䨀伀䤀一 䨀伀唀刀一䄀䰀 愀猀 䨀 伀一 䔀䤀⸀䨀刀一开䤀䐀 㴀 䨀⸀䨀刀一开䤀䐀ഀ਀ऀऀ 䤀一一䔀刀 䨀伀䤀一 䔀一吀刀夀开吀倀 伀一 䨀⸀䨀刀一开吀夀倀 㴀 䔀一吀刀夀开吀倀⸀䤀䐀ഀ਀ഀ਀ऀ  圀䠀䔀刀䔀 ഀ਀ऀ  䔀䤀⸀䔀一吀开刀䔀䌀㌀ 㰀㸀 ✀　✀ഀ਀ऀ  䄀一䐀 䔀䤀⸀䄀䌀䌀开一唀 㴀 䀀䄀䌀䌀开一唀 ഀ਀ऀ ⴀⴀ 倀䰀 　㜀⼀　㘀⼀㈀　㄀㔀ഀ਀ऀ  ⴀⴀ䄀一䐀 䔀䤀⸀匀唀䈀开一唀 㴀 䀀䘀䴀开匀唀䈀开一唀 ഀ਀ऀ  䄀一䐀 ⠀䀀䘀䴀开匀唀䈀开一唀 椀猀 渀甀氀氀 漀爀⠀䀀䘀䴀开匀唀䈀开一唀 椀猀 渀漀琀 渀甀氀氀 愀渀搀 䔀䤀⸀匀唀䈀开一唀 㴀 䀀䘀䴀开匀唀䈀开一唀⤀⤀ ഀ਀ऀ  ⴀⴀഀ਀ऀ  䄀一䐀 䨀⸀䨀刀一开䐀䄀吀䔀 䈀䔀吀圀䔀䔀一 䀀䤀猀猀甀攀倀愀礀䘀䴀 䄀一䐀 䀀䤀猀猀甀攀倀愀礀吀伀ഀ਀  ऀ ⴀⴀ 倀䰀 　㜀⼀　㘀⼀㈀　㄀㔀ഀ਀  ऀ  䄀一䐀⠀⠀挀愀猀攀  椀猀渀甀洀攀爀椀挀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 眀栀攀渀 ㄀ 琀栀攀渀 挀愀猀琀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀ 愀猀  一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀⤀ 攀氀猀攀 　 攀渀搀 㸀㴀 䀀䘀䴀䤀渀瘀漀椀挀攀一漀 ഀ਀ऀ  䄀一䐀 挀愀猀攀  椀猀渀甀洀攀爀椀挀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 眀栀攀渀 ㄀ 琀栀攀渀 挀愀猀琀⠀䔀䤀⸀䔀一吀开刀䔀䌀㌀ 愀猀  一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀⤀ 攀氀猀攀 　 攀渀搀 㰀㴀 䀀吀伀䤀渀瘀漀椀挀攀一漀  ⤀ഀ਀ऀ  ⴀⴀ 䄀一䐀⠀⠀挀漀渀瘀攀爀琀⠀一唀䴀䔀刀䤀䌀⠀㈀　Ⰰ　⤀Ⰰ 䔀䤀⸀䔀一吀开刀䔀䌀㌀⤀ 㸀㴀 䀀䘀䴀䤀渀瘀漀椀挀攀一漀 ഀ਀
	  --AND convert(NUMERIC(20,0), EI.ENT_REC3) <= @TOInvoiceNo  )
	  --
	  or(@FMInvoiceNo is null)or(@TOInvoiceNo is null))		
  	  AND EI.ENT_CR <> 0
  	   
	END 
	
	Else IF @ReportType  = '3'  -- كل الحركات 
	BEGIN
	INSERT INTO  TMP_ACC3401
	([USR_C],[ENT_REC3],[JRN_DATE],[ENT_DR],[ENT_CR],[SUB_NU],[ACC_NU],[JRN_TYP],[ENT_DES],[SUB_NM_A],[ACC_NM_A],[JRN_NU])

	SELECT 
		@USR_C AS [USR_C],EI.ENT_REC3,J.JRN_DATE,EI.ENT_DR,EI.ENT_CR,EI.SUB_NU,EI.ACC_NU,ENTRY_TP.JRN_TYP,EI.ENT_DES,SUB.SUB_NM_A,ACC.ACC_NM_A,J.JRN_NU
	  FROM
		ENTRY_I  AS EI 
		INNER JOIN MAIN_ACC as ACC ON EI.ACC_NU = ACC.ACC_NU 
		INNER JOIN SUB_ACC as SUB ON EI.SUB_NU = SUB.SUB_NU AND EI.ACC_NU = SUB.ACC_NU AND ACC.ACC_NU = SUB.ACC_NU 
		INNER JOIN JOURNAL as J ON EI.JRN_ID = J.JRN_ID
		 INNER JOIN ENTRY_TP ON J.JRN_TYP = ENTRY_TP.ID

	  WHERE 
	  EI.ENT_REC3 <> '0'
	  AND EI.ACC_NU = @ACC_NU 
	   -- PL 07/06/2015
	  --AND EI.SUB_NU = @FM_SUB_NU 
	  AND (@FM_SUB_NU is null or(@FM_SUB_NU is not null and EI.SUB_NU = @FM_SUB_NU)) 
	  --
	  AND J.JRN_DATE BETWEEN @IssuePayFM AND @IssuePayTO
  	 -- PL 07/06/2015
  	  AND((case  isnumeric(EI.ENT_REC3) when 1 then cast(EI.ENT_REC3 as  NUMERIC(20,0)) else 0 end >= @FMInvoiceNo 
	  AND case  isnumeric(EI.ENT_REC3) when 1 then cast(EI.ENT_REC3 as  NUMERIC(20,0)) else 0 end <= @TOInvoiceNo  )
	  -- AND((convert(NUMERIC(20,0), EI.ENT_REC3)>= @FMInvoiceNo 
	  --AND convert(NUMERIC(20,0), EI.ENT_REC3) <= @TOInvoiceNo  )
	  --
	  or(@FMInvoiceNo is null)or(@TOInvoiceNo is null))		
	END 
	
	SELECT * FROM TMP_ACC3401
   

END











