CREATE procEDURE [Finance].[SPACCO3405] 
	  @USR_C varchar(10)
	, @IssuePayFM Datetime
	, @IssuePayTO Datetime
	, @FMInvoiceNO float = null
	, @TOInvoiceNO float = null
	, @ACC_NU real 
	, @FM_SUB_NU real = null
	, @TO_SUB_NU real = null
	
AS
BEGIN
