UPDATE TMP_ACC3413 SET TOTAL =isnull((select [FirstDAY]+[SecondDAY]+[ThirdDAY]+[fourthDAY]+[OtherDAY] 
								FROM TMP_ACC3413 as A 
								WHERE A.ACC_NU = @ACC_NU 
								AND TMP_ACC3413.SUB_NU= A.SUB_NU 
								AND TMP_ACC3413.ENT_REC3= A.ENT_REC3 
								 AND  USR_C = @USR_C),0)
	where USR_C = @USR_C


	UPDATE TMP_ACC3413 SET DTOTAL =isnull((select ([FirstDAY]+[SecondDAY]+[ThirdDAY]+[fourthDAY]+[OtherDAY] )/@CUR_CONV
								FROM TMP_ACC3413 as A 
								WHERE A.ACC_NU = @ACC_NU 
								AND TMP_ACC3413.SUB_NU= A.SUB_NU 
								AND TMP_ACC3413.ENT_REC3= A.ENT_REC3 
								 AND  USR_C = @USR_C),0)
	where USR_C = @USR_C

	UPDATE TMP_ACC3413 SET CREDIT_LIMIT =isnull((select CREDIT_LIMIT
								FROM SUB_ACC as  A
								WHERE A.ACC_NU = @ACC_NU 
								AND TMP_ACC3413.SUB_NU= A.SUB_NU
								
								 ),0)
	where USR_C = @USR_C


	
						 
