ऀഀ਀Ⰰ 䀀倀愀礀洀攀渀琀吀漀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀Ⰰ 䀀吀愀砀䐀攀搀甀挀琀椀漀渀 昀氀漀愀琀 㴀渀甀氀氀ഀ਀ऀഀ਀Ⰰ 䀀䄀䌀䌀开一唀 椀渀琀 ഀ਀Ⰰ 䀀䘀䴀开匀唀䈀开一唀 椀渀琀ഀ਀Ⰰ 䀀吀伀开匀唀䈀开一唀 椀渀琀ഀ਀ऀഀ਀ऀഀ਀Ⰰ 䀀匀漀爀琀椀渀最 瘀愀爀挀栀愀爀⠀㄀⤀ 㴀渀甀氀氀ഀ਀Ⰰ 䀀䌀甀爀爀攀渀挀礀 瘀愀爀挀栀愀爀⠀㄀⤀ 㴀渀甀氀氀ഀ਀ऀഀ਀ऀഀ਀Ⰰ 䀀䴀椀渀甀猀嘀愀氀甀攀䄀瀀瀀攀愀爀 瘀愀爀挀栀愀爀⠀㄀⤀㴀渀甀氀氀ഀ਀
, @BalanceZeroAppear varchar(1)=null
	
, @DownPayment varchar (8)=null
, @DownPaymentD varchar (50)=null
	
, @ChkdBy varchar(30)=null
, @PrepairedBy varchar(30)=null
, @Attention varchar(30)=null
, @Remark varchar(170)=null
	
	
AS
BEGIN

--DECLARE @MyCR float
--DECLARE @DATEMyCR DATE
	
--DECLARE @MyDR float
--DECLARE @DATEMyDR DATE
--DECLARE @MyEntConv float
	
--DECLARE @MyEntConv1 float
--DECLARE @curSymbol  varchar(5)
DECLARE @FromCstName  varchar(50)
DECLARE @Flag varchar(50)
DECLARE @MyAccType int --==1 =customer ,2=supplier
Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO3414'

set @FromCstName=(select SUB_NM_E from SUB_ACC where ACC_NU =@ACC_NU and SUB_NU =@FM_SUB_NU)
	
--SET NOCOUNT ON;
  if substring(cast(@ACC_NU as varchar(10)) , 1, 1) = '1' 
begin
	set @MyAccType=1
end 

else
	begin 
	set @MyAccType=-2
	end
	print @MyAccType

DELETE FROM [Finance].[TMP_ACC3414] WHERE USR_C = @USR_C
	
DELETE FROM [Finance].[TMP_ENTRY_I] WHERE USR_C = @USR_C
	
--********Insert Data To Tmp_entry_I***************************************************	
--**************************************************
if 	(@InvToDate=@PaymentToDate ) --تاريخ الى صدار نفسه تاريخ الى سداد
begin
	print '@InvToDate<>@PaymentToDate '
	INSERT INTO TMP_ENTRY_I
	(JRN_TYP,JRN_DATE,JRN_NU,
	ENT_COST,
	ACC_NU,SUB_NU,CUR_NU,ENT_REC1,
	ENT_REC2,ENT_CONV,ENT_DR,ENT_CR,ENT_DES,
	ENT_FLG,ENT_REC3,ENT_RED3,
	ENT_RED4,USR_C) 				 
	SELECT   JOURNAL.JRN_TYP, JOURNAL.JRN_DATE, JOURNAL.JRN_NU,
	ENT_ID, --ENTRY_I.ENT_COST,
	ENTRY_I.ACC_NU, ENTRY_I.SUB_NU, ENTRY_I.CUR_NU, isnull(ENTRY_I.ENT_REC1,''), 
	isnull(ENTRY_I.ENT_REC2,''), isnull(ENTRY_I.ENT_CONV,0), ENTRY_I.ENT_DR, ENTRY_I.ENT_CR, 
	isnull(ENTRY_I.ENT_DES,''),ENTRY_I.ENT_FLG, ENTRY_I.ENT_REC3, ENTRY_I.ENT_RED3,
	ENTRY_I.ENT_RED4, @USR_C
	FROM         ENTRY_I INNER JOIN
			JOURNAL ON ENTRY_I.JRN_ID = JOURNAL.JRN_ID
	WHERE (ENTRY_I.ACC_NU = @ACC_NU) 
			AND (ENTRY_I.SUB_NU >= @FM_SUB_NU) 
			AND (ENTRY_I.SUB_NU <= @To_SUB_NU) 
			AND (LTRIM(ENTRY_I.ENT_REC3) <> '')	
		 AND (JRN_DATE <= @InvToDate) AND (JRN_DATE >= @InvFromDate)

end
