	--WHERE (ENT_REC3 IN 
	--			(
	--				SELECT ENT_REC3 
	--				 FROM [ENTRY_i] AS E 
	--				 join JOURNAL AS J ON J.JRN_ID=E.JRN_ID
	--				 WHERE E.ACC_NU=@ACC_NU AND 
