	DELETE FROM TMP_ENTRY_I
FROM            (SELECT        E.ENT_REC3, E.ACC_NU, E.SUB_NU
                           FROM            ENTRY_I AS E INNER JOIN
                                                    JOURNAL AS J ON J.JRN_ID = E.JRN_ID
                           WHERE        (E.ACC_NU = @ACC_NU) AND (E.SUB_NU BETWEEN @FM_SUB_NU AND @TO_SUB_NU) AND (E.ENT_DR > 0) AND (SUBSTRING(CONVERT(varchar(10), E.ACC_NU), 1, 1) = 1) AND 
                                                    (J.JRN_DATE < @InvFromDate)) AS del INNER JOIN
                         TMP_ENTRY_I ON del.ACC_NU = TMP_ENTRY_I.ACC_NU AND del.SUB_NU = TMP_ENTRY_I.SUB_NU AND del.ENT_REC3 = TMP_ENTRY_I.ENT_REC3


