                           WHERE        (USR_C = @USR_C) AND (SUBSTRING(CONVERT(varchar(10), ACC_NU), 1, 1) = 1)
                           GROUP BY ENT_REC3, ACC_NU, SUB_NU
                           HAVING        (SUM(ENT_DR) - SUM(ENT_CR) >= 0)and (SUM(ENT_dR) - SUM(ENT_cR) <= 0.01)) AS t INNER JOIN
                         TMP_ENTRY_I ON t.ENT_REC3 = TMP_ENTRY_I.ENT_REC3 AND t.ACC_NU = TMP_ENTRY_I.ACC_NU AND t.SUB_NU = TMP_ENTRY_I.SUB_NU
	DELETE FROM TMP_ENTRY_I
	FROM            (SELECT        ENT_REC3, ACC_NU, SUB_NU
                           FROM            TMP_ENTRY_I AS TMP_ENTRY_I_1
                           WHERE        (USR_C = @USR_C) AND (SUBSTRING(CONVERT(varchar(10), ACC_NU), 1, 1) = 2)
                           GROUP BY ENT_REC3, ACC_NU, SUB_NU
                           HAVING        (SUM(ENT_CR) - SUM(ENT_DR) >= 0) and (SUM(ENT_CR) - SUM(ENT_DR) <= 0.01)) AS t INNER JOIN
                         TMP_ENTRY_I ON t.ENT_REC3 = TMP_ENTRY_I.ENT_REC3 AND t.ACC_NU = TMP_ENTRY_I.ACC_NU AND t.SUB_NU = TMP_ENTRY_I.SUB_NU
END
 


