	([USR_C]      ,[FROM]      ,[INVUPTO]      ,[PAYUPTO]      ,[MAINACC]      ,[MAINNAME]      ,[FCST]      ,[FCSTNAME]      ,[TOCST]      ,[TOCSTNAME]      ,[CHECK]      ,[REPAR]      ,[ATTEN]      ,[INVNO]      ,[DATE]      ,[OURREF]      ,[DR]      ,[CR]      ,[BAL]      ,[BDATE]      ,[CUR_SYMBOL]      ,[JRN_CHK]      ,[Down_P]     ,[Down_P_D])

	SELECT     @USR_C AS usr_c, @From AS [from], @InvToDate as InvUpTo,@PaymentToDate as PayUpT
	,mainAcc as mainAcc,mainName as Fcst, @FM_SUB_NU AS Fcst,@FromCstName AS FCstName,ToCst,ToCstName, @ChkdBy AS [check]
