	INSERT INTO [TMP_ACC3414]
	([USR_C]      ,[FROM]      ,[INVUPTO]      ,[PAYUPTO]      ,[MAINACC]      ,[MAINNAME]      ,[FCST]      ,[FCSTNAME]      ,[TOCST]      ,[TOCSTNAME]      ,[CHECK]      ,[REPAR]      ,[ATTEN]      ,[INVNO]      ,[DATE]      ,[OURREF]      ,[DR]      ,[CR]      ,[BAL]      ,[BDATE]      ,[CUR_SYMBOL]      ,[JRN_CHK]      ,[Down_P]     ,[Down_P_D])

	SELECT     @USR_C AS usr_c, @From AS [from], @InvToDate as InvUpTo,@PaymentToDate as PayUpT
	,mainAcc as mainAcc,mainName as Fcst, @FM_SUB_NU AS Fcst,@FromCstName AS FCstName,ToCst,ToCstName, @ChkdBy AS [check]
	,@PrepairedBy AS REPAR, @Attention AS ATTEN
	,INVNO, MIN([DATE]) AS [DATE] , min( OURREF) as OURREF
	,isnull( SUM(conv_Dr),0) AS dr,isnull( SUM(conv_cr),0) AS cr, isnull( SUM(conv_Dr)-SUM(conv_cr), 0 )as bal,'01/01/1990' AS BDATE
	,CUR_SYMBOL,'' AS JRN_CHK,  @DownPayment AS Down_P, @DownPaymentD AS Down_P_D
	FROM         (SELECT      TMP_ENTRY_I.ACC_NU AS mainAcc, MAIN_ACC.ACC_NM_E AS mainName, 
												   TMP_ENTRY_I.SUB_NU AS ToCst, SUB_ACC.SUB_NM_E AS ToCstName, 
												   TMP_ENTRY_I.ENT_REC3 AS INVNO
												   , isnull (min(p.ENT_DES),min(TMP_ENTRY_I.ENT_DES)) AS OURREF
												   , MIN(TMP_ENTRY_I.JRN_DATE) AS [DATE] 
												  , CASE WHEN isnull(TMP_ENTRY_I.ENT_DR, 0) > isnull(TMP_ENTRY_I.ENT_cR, 0) THEN SUM(TMP_ENTRY_I.ENT_conv)
												   ELSE 0 END AS conv_Dr, CASE WHEN isnull(SUM(TMP_ENTRY_I.ENT_cR), 0) > isnull(SUM(TMP_ENTRY_I.ENT_dR), 0) 
												  THEN SUM(TMP_ENTRY_I.ENT_conv) ELSE 0 END AS conv_cr 
												  , CUR_CODE.CUR_CODE AS CUR_SYMBOL
							FROM         TMP_ENTRY_I INNER JOIN
												  MAIN_ACC ON TMP_ENTRY_I.ACC_NU = MAIN_ACC.ACC_NU INNER JOIN
												  CUR_CODE ON TMP_ENTRY_I.CUR_NU = CUR_CODE.CUR_NU INNER JOIN
												  SUB_ACC ON TMP_ENTRY_I.ACC_NU = SUB_ACC.ACC_NU AND TMP_ENTRY_I.SUB_NU = SUB_ACC.SUB_NU
							 left outer JOIN (SELECT        ACC_NU, SUB_NU, ENT_REC3, max(ENT_DES) as ENT_DES, USR_C  FROM  TMP_ENTRY_I  WHERE  (ent_Cr > 0) AND (USR_C = @USR_C) GROUP BY ACC_NU, SUB_NU, ENT_REC3, USR_C) as P
							
							on TMP_ENTRY_I.ACC_NU=p.ACC_NU and TMP_ENTRY_I.SUB_NU=p.SUB_NU and TMP_ENTRY_I.ENT_REC3=p.ENT_REC3
							
ਊऀऀऀऀऀऀऀ圀䠀䔀刀䔀     ⠀吀䴀倀开䔀一吀刀夀开䤀⸀䄀䌀䌀开一唀 㴀 䀀䄀䌀䌀开一唀⤀ 䄀一䐀 ⠀吀䴀倀开䔀一吀刀夀开䤀⸀䨀刀一开䐀䄀吀䔀 㰀㴀 䀀倀愀礀洀攀渀琀吀漀䐀愀琀攀⤀ 䄀一䐀 ⠀吀䴀倀开䔀一吀刀夀开䤀⸀䨀刀一开䐀䄀吀䔀 㸀㴀 䀀䤀渀瘀䘀爀漀洀䐀愀琀攀⤀ 䄀一䐀 ഀ਀ऀऀऀऀऀऀऀऀऀऀऀऀ  ⠀吀䴀倀开䔀一吀刀夀开䤀⸀唀匀刀开䌀 㴀 䀀唀匀刀开䌀⤀ 䄀一䐀 ⠀䰀吀刀䤀䴀⠀吀䴀倀开䔀一吀刀夀开䤀⸀䔀一吀开刀䔀䌀㌀⤀ 㰀㸀 ✀✀⤀ 䄀一䐀 ⠀䰀吀刀䤀䴀⠀吀䴀倀开䔀一吀刀夀开䤀⸀䔀一吀开刀䔀䌀㌀⤀ 㰀㸀 ✀　✀⤀ ഀ਀ऀऀऀऀऀऀऀऀऀऀऀऀ  䄀一䐀 ഀ਀ऀऀऀऀऀऀ  ⠀吀䴀倀开䔀一吀刀夀开䤀⸀䌀唀刀开一唀 㰀㸀 ㄀⤀ഀ਀ऀऀऀऀऀऀऀऀऀऀऀऀ  ഀ਀ऀऀऀऀऀऀऀ䜀刀伀唀倀 䈀夀 吀䴀倀开䔀一吀刀夀开䤀⸀䄀䌀䌀开一唀Ⰰ 吀䴀倀开䔀一吀刀夀开䤀⸀匀唀䈀开一唀Ⰰ 吀䴀倀开䔀一吀刀夀开䤀⸀䌀唀刀开一唀Ⰰ 吀䴀倀开䔀一吀刀夀开䤀⸀䔀一吀开刀䔀䌀㌀Ⰰ 䴀䄀䤀一开䄀䌀䌀⸀䄀䌀䌀开一䴀开䔀Ⰰ ഀ਀ऀऀऀऀऀऀऀऀऀऀऀऀ  䌀唀刀开䌀伀䐀䔀⸀䌀唀刀开䌀伀䐀䔀Ⰰ 匀唀䈀开䄀䌀䌀⸀匀唀䈀开一䴀开䔀Ⰰ 吀䴀倀开䔀一吀刀夀开䤀⸀䔀一吀开䌀刀Ⰰ 吀䴀倀开䔀一吀刀夀开䤀⸀䔀一吀开䐀刀⤀ 䄀匀 搀攀爀椀瘀攀搀琀戀氀开㄀ഀ਀ऀ                                              ഀ਀ऀ䜀刀伀唀倀 䈀夀 洀愀椀渀䄀挀挀Ⰰ洀愀椀渀一愀洀攀Ⰰ吀漀䌀猀琀Ⰰ吀漀䌀猀琀一愀洀攀Ⰰ䤀一嘀一伀Ⰰ䌀唀刀开匀夀䴀䈀伀䰀 ഀ਀ഀ਀ഀ਀ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㐀㄀㔀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀  ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀   嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀挀挀漀㌀㐀㄀㔀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀ䀀唀猀攀爀开一愀洀攀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀爀漀洀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 䐀愀琀攀琀椀洀攀 ഀ਀ऀⰀ 䀀䄀䌀䌀开一唀 椀渀琀 ഀ਀ऀⰀ 䀀匀唀䈀开一唀 椀渀琀ഀ਀ ഀ਀ऀഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀ऀഀ਀ഀ਀    ⴀⴀ 䤀渀猀攀爀琀 猀琀愀琀攀洀攀渀琀猀 昀漀爀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀഀ਀ऀⴀⴀ㄀ഀ਀ऀ搀攀氀攀琀攀  䘀刀伀䴀 吀䴀倀开䄀䌀䌀㌀㐀㄀㔀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀猀攀爀开一愀洀攀ഀ਀ऀ ഀ਀ऀⴀⴀ㈀ഀ਀ ഀ਀ऀⴀⴀ㌀ഀ਀ऀⴀⴀ⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀⨀ഀ਀ऀ ഀ਀ऀ ഀ਀ⴀⴀ 匀倀 䔀渀搀ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ऀऀഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㐀㄀㘀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㔀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀ⴀⴀ 䄀甀琀栀漀爀㨀ऀऀ㰀一攀愀洀愀 刀愀洀愀搀愀渀㸀ഀ਀ⴀⴀ 䄀氀琀攀爀 搀愀琀攀㨀 㰀　㈀⼀　㐀⼀㈀　㄀㐀㸀ഀ਀ⴀⴀ 䐀攀猀挀爀椀瀀琀椀漀渀㨀ऀ㰀䐀愀琀愀 䘀漀爀 刀攀瀀漀爀琀 䄀䌀䌀伀㌀㐀㄀㘀㸀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀䔀䐀唀刀䔀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㐀㄀㘀崀 ഀ਀ഀ਀ऀ  䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀爀漀洀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 䐀愀琀攀琀椀洀攀ഀ਀ऀ ഀ਀ऀⰀ 䀀吀礀瀀攀 挀栀愀爀⠀㄀⤀ 㴀 渀甀氀氀 ഀ਀ऀⰀ 䀀匀琀愀琀甀猀 挀栀愀爀⠀㄀⤀ 㴀 渀甀氀氀 ഀ਀ऀⰀ 䀀䘀椀氀攀一漀 瘀愀爀挀栀愀爀⠀㄀㔀⤀ 㴀 渀甀氀氀ഀ਀ऀⰀ 䀀䘀椀氀攀吀礀瀀攀 瘀愀爀挀栀愀爀⠀㌀⤀ 㴀 渀甀氀氀 ഀ਀ऀഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀ऀ匀䔀吀 一伀䌀伀唀一吀 伀一㬀ഀ਀ഀ਀ऀ䐀䔀䰀䔀吀䔀 䘀刀伀䴀 嬀䘀椀渀愀渀挀攀崀⸀嬀吀䴀倀开䄀䌀䌀㌀㐀㄀㘀崀 圀䠀䔀刀䔀 唀匀刀开䌀 㴀 䀀唀匀刀开䌀ഀ਀ऀഀ਀ऀ搀攀氀攀琀攀  䘀刀伀䴀 吀䴀倀开䄀 圀䠀䔀刀䔀 唀匀刀开䌀㴀䀀唀匀刀开䌀ഀ਀ऀ䤀渀猀攀爀琀 椀渀琀漀 吀䴀倀开䄀 ⠀唀匀刀开䌀Ⰰ䘀䤀䰀䔀䐀㄀Ⰰ䘀䤀䰀䔀䐀㈀ ⤀ 瘀愀氀甀攀猀 ⠀䀀唀匀刀开䌀Ⰰ䀀䘀爀漀洀䐀愀琀攀 Ⰰ  䀀吀漀䐀愀琀攀 ⤀ ഀ਀ऀഀ਀
	INSERT INTO TMP_ACC3416 ( USR_C, INV_NU ,  INV_FIL , INV_A_DAT , INV_D_DAT , INV_PAX , INV_DAT , CTC_NAME , CTC_TITLE , INV_RE , INV_CUR , INV_FLG , INV_TYP , INV_Amt)
	SELECT  @USR_C , INV_NU , INVOICE_B.COST_NU, INVOICE_B.COST_ARRIVAL_DATE , INVOICE_B.COST_DEPARTURE_DATE , INV_PAX , INV_ISSUE_DATE 
	,(select top 1 SA.SUB_NM_E from SUB_ACC SA where  Invoice_B.SUB_NU  = SA.SUB_NU) as ACC_NAME   ,
	 INV_COVERING , INV_REFERENCE, CUR_CODE, INV_FLG, INV_TYP , 				
				(
				SELECT 
				--sum(isnull(INV_NTS,0)) 
			 SUM(CASE WHEN inv_nts = 0 THEN (INV_LINE_B.INV_PAX * INV_LINE_B.INV_RATE) ELSE (INV_LINE_B.INV_PAX * INV_LINE_B.INV_RATE * isnull((INV_LINE_B.INV_NTS), 1)) END) AS amt

				FROM INV_LINE_B 
					where INV_ID =INVOICE_B.INV_ID
					 AND ((INV_TYP= @Type)OR(@Type IS NULL))
					 AND ((INVOICE_B.COST_NU= @FileNo)OR(@FileNo IS NULL))
				) 
			from Invoice_B
			INNER JOIN CUR_CODE ON INVOICE_B.INV_CUR = CUR_CODE.CUR_NU
			INNER JOIN COST ON COST.COST_NU = INVOICE_B.COST_NU          -- Added By khaled in 02-03-2016             
				where  INV_ISSUE_DATE BETWEEN  @FromDate AND @ToDate 
					  AND ((INV_TYP= @Type)OR(@Type IS NULL))
					  AND ((INVOICE_B.COST_NU= @FileNo)OR(@FileNo IS NULL))
					  AND ((INV_FLG= @Status)OR(@Status IS NULL))
					  AND ((COST.COST_TYP = @FileType)OR(@FileType IS NULL)) -- Added By khaled in 02-03-2016
		
END














