	delete  FROM TMP_ACC3418 WHERE USR_C=@USR_C
	 
	--2
  insert into TMP_ACC3418 
 
(USR_C,REQ_NO,INV_DAT,TYPE,BASIC,TOTAL,CUSTOMER) 

select @USR_C, AIR_LINE.AIR_COD, AIR_LINE.AIR_DAT,  AIR_LINE.AIR_K_TYP, ISNULL(AIR_LINE.AIR_BAS,0),  
	( ISNULL(AIR_LINE.AIR_BAS,0) +  ISNULL(AIR_LINE.AIR_TAX1,0) +  ISNULL(AIR_LINE.AIR_TAX2,0) 
	+  ISNULL(AIR_LINE.AIR_TAX3,0) +  ISNULL(AIR_LINE.AIR_TAX4,0) +  ISNULL(AIR_LINE.AIR_TAX5,0)
	 +  ISNULL(AIR_LINE.AIR_STMP,0)) AS Total,
	SUB_ACC.SUB_NM_E  
	
		FROM  SUB_ACC 
			 JOIN  AIR_LINE 
				ON  SUB_ACC.SUB_NU = AIR_LINE.CST_NO AND SUB_ACC.ACC_NU = AIR_LINE.AIR_ACC  
				
	WHERE  AIR_LINE.AIR_DAT BETWEEN @FromDate AND @ToDate 
		and AIR_LINE.air_k_typ <> '4' 
		 
		and ((AIR_LINE.AIR_ACC=@ACC_NU) or(@ACC_NU is null))
		and ((AIR_LINE.CST_NO=@SUB_NU ) or(@SUB_NU is null)) 
		 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP1,'') FROM INVOICE_A)
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP2,'') FROM INVOICE_A)  
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP3,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP4,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP5,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP6,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP7,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP8,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP9,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REP0,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPa,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPb,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPc,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPd,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPe,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPf,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPg,'') FROM INVOICE_A) 
		AND AIR_LINE.AIR_COD NOT IN (SELECT isnull(INV_REPh,'') FROM INVOICE_A) 
