-- Execute a SELECT statement that uses the OPENXML rowset provider.
-- **************************************************************************	


DECLARE @Temp TABLE(MainAcc VARCHAR(250),SubAcc VARCHAR(250),User_c varchar(50))  
INSERT INTO @Temp(User_c,MainAcc,SubAcc)
SELECT @USR_C,*
FROM OPENXML (@idoc, '/Accounts/Contact',1)
WITH (MainAcc varchar(50),SubAcc varchar(50))

select * from @Temp	
	
	
	
	
	DECLARE tAccounts_cursor CURSOR FOR    SELECT     MainAcc FROM       @Temp where User_c=@USR_C GROUP BY MainAcc

	OPEN tAccounts_cursor  DECLARE @MainAccount varchar(10)

	FETCH NEXT FROM tAccounts_cursor INTO @MainAccount
	WHILE (@@FETCH_STATUS <> -1) 
	BEGIN  
	
		-----------------------------------
		--********Insert Data To Tmp_entry_I***************************************************	
DECLARE tSub_cursor CURSOR FOR    SELECT     SubAcc FROM       @Temp where MainAcc=@MainAccount and User_c=@USR_C
	OPEN tSub_cursor  DECLARE @SubAccount varchar(10)
	FETCH NEXT FROM tSub_cursor INTO @SubAccount
	WHILE (@@FETCH_STATUS <> -1) 
	BEGIN  
	print 'nabila' + cast(@SubAccount as varchar(6))
	INSERT INTO TMP_ENTRY_I
		(JRN_TYP,JRN_DATE,JRN_NU,
		ENT_COST,
		ACC_NU,SUB_NU,CUR_NU,ENT_REC1,
		ENT_REC2,ENT_CONV,ENT_DR,ENT_CR
		,ENT_DES,
		ENT_FLG
		,ENT_REC3
		,ENT_RED3
		,ENT_RED4
		,USR_C
		) 				 
		
		SELECT   Finance.JOURNAL.JRN_TYP, Finance.JOURNAL.JRN_DATE, Finance.JOURNAL.JRN_NU,
				  0, 
				 Finance.ENTRY_I.ACC_NU, Finance.ENTRY_I.SUB_NU, Finance.ENTRY_I.CUR_NU, Finance.ENTRY_I.ENT_REC1, 
				 Finance.ENTRY_I.ENT_REC2, Finance.ENTRY_I.ENT_CONV, Finance.ENTRY_I.ENT_DR, Finance.ENTRY_I.ENT_CR
				 , Finance.ENTRY_I.ENT_DES,Finance.ENTRY_I.ENT_FLG
				 , Finance.ENTRY_I.ENT_REC3
				 , Finance.ENTRY_I.ENT_RED3
				 ,Finance.ENTRY_I.ENT_RED4
				 , @USR_C
	FROM         Finance.ENTRY_I INNER JOIN
						  Finance.JOURNAL ON Finance.ENTRY_I.JRN_ID = Finance.JOURNAL.JRN_ID
	WHERE (LTRIM(Finance.ENTRY_I.ENT_REC3) <> '')
	and (JRN_DATE <= @InvToDate) AND (JRN_DATE >= @InvFromDate)
							AND ACC_NU	= @MainAccount 
							AND SUB_NU=@SubAccount
							
		
				FETCH NEXT FROM tSub_cursor INTO @SubAccount
END 

