CREATE proc   [Finance].[SPAcco3421]
	-- Add the parameters for the stored procedure here
	 @USR_C varchar(10)
	, @FromDate Datetime
	, @ToDate Datetime 
	, @PaymentToDate Datetime 
	
	, @Currency varchar(10) =null
	
	, @ACC_NU int 
	, @SUB_NU int
	, @SUB_NU2 int
	, @Sorting varchar(1) =null
 
	, @TaxDeduction varchar(7)=null
	
	, @OthrDdction varchar(10)=null
	, @OthrDdction2 varchar(50)=null
	, @OthrDdction3 varchar(10)=null
	, @OthrDdction4 varchar(50)=null
	
	, @ChkdBy varchar(30)=null
	, @PrepairedBy varchar(30)=null
	
	, @MinusValueAppear varchar(1)=null--'0=checked else no checked
	, @BalanceZeroAppear varchar(1)=null --'0=checked else no checked
	, @CompleteDescription varchar(1)=null--'0=checked else no checked
	
AS
BEGIN
    -- Insert statements for procedure here
	
	--1
	delete  FROM TMP_ACC3421 WHERE USR_C=@USR_C
	 
	--2  ISSUE CUSTOMER FLAG 0
	 
INSERT INTO  TMP_ACC3421 

(USR_C,ACC_NU,SUB_NU,ENT_REC3,CUR_NU,FLG,ENT_CONV_CR,ENT_CONV_DR,ENT_CR,ENT_DR,ENT_RED3,ENT_DES) 

SELECT @USR_C,
E.ACC_NU, E.SUB_NU,
E.ENT_REC3,
C.CUR_NU
,FLAG=(CASE SUBSTRING(CONVERT(varchar(10),E.ACC_NU),1,1) WHEN 1 THEN 0 ELSE 1 END)


,ENT_CONV_CR = 0
,ENT_CONV_DR = SUM(ISNULL(E.ENT_CONV,0))
,CR = SUM(ISNULL(E.ENT_CR,0))
,DR = SUM(ISNULL(E.ENT_DR,0))

,min(J.JRN_DATE) AS DATE
,MAX(E.ENT_DES) AS ENT_DES


FROM [ENTRY_i] AS E 
