CREATE proc   [Finance].[SPAcco3422]
	-- Add the parameters for the stored procedure here
	@USR_C varchar(10)
	, @IssueToDate Datetime
	, @PaymentToDate Datetime 
	
	, @ACC_NU int 
	, @SUB_NU int
	, @SUB_NU2 int
	
	,@Day1 INT = null
	,@Day2 INT = null
	,@Day3 INT = null
	,@Day4 INT = null
	 
	
	,@TransactionType int
	
AS
BEGIN

	DECLARE @Date1 DATETIME set @Date1 = DATEADD(day, -@DAY1, @IssueToDate)
	DECLARE @Date2 DATETIME set @Date2 = DATEADD(day, -@DAY2, @Date1)
	DECLARE @Date3 DATETIME set @Date3 = DATEADD(day, -@DAY3, @Date2)
	DECLARE @Date4 DATETIME set	@Date4 = DATEADD(day, -@DAY4, @Date3)

    -- Insert statements for procedure here
	--1
	delete  FROM TMP_ACC3422 WHERE USR_C=@USR_C
	 
	--2
INSERT INTO TMP_ACC3422 (USR_C,ACC_NU,SUB_NU, cur_CONV , CUR_NU ,ENT_REC3,JRN_DATE,FLG,DES,[30_DAY],[60_DAY],[90_DAY],[120_DAY],[0_DAY])
	select @USR_C,ACC_NU,SUB_NU,min(isnull(ENT_conv,0)),max(cur_nu),ENT_REC3,MIN(ENT_RED3),1,'',case @TransactionType when 0 then sum(ISNULL(ENT_DR,0)) - sum(ISNULL(ENT_CR,0)) when 1 then sum(ISNULL(ENT_DR,0)) else  sum(ISNULL(ENT_CR,0))end,0,0,0,0 FROM  ENTRY_I Join JOURNAL as j on j.JRN_ID = ENTRY_I.JRN_ID WHERE JRN_DATE<= @PaymentToDate AND ACC_NU= @ACC_NU AND SUB_NU BETWEEN @SUB_NU AND @SUB_NU2 AND LTRIM(ENT_REC3)<>'0' AND LTRIM(ENT_REC3)<>'' GROUP BY ACC_NU,SUB_NU,ENT_REC3 HAVING  MIN(JRN_DATE)> @Date1 AND MIN(JRN_DATE)<=@IssueToDate
