	SET @Day_4=120
	DECLARE @CUR_CONV float set @CUR_CONV = 1
	DECLARE @Date1 DATETIME set @Date1 = DATEADD(day, -@Day_1, @IssueToDate)
	DECLARE @Date2 DATETIME set @Date2 = DATEADD(day, -@Day_2, @Date1)
	DECLARE @Date3 DATETIME set @Date3 = DATEADD(day, -@Day_3, @Date2)
	DECLARE @Date4 DATETIME set	@Date4 = DATEADD(day, -@Day_4, @Date3)	
	delete  from TMP_ACCO3427 where USR_C=@USR_C
	print @Date1
	print @Date2
	print @Date3
	print @Date4
	
	 If SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '1' Or SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '3'
		begin
			set @Cust_Sup='C'
			set @Rate=1
		end
	 else
		begin
			set @Cust_Sup='S'
			set @Rate=-1
		end
