	INSERT INTO TMP_ACCO3427 (USR_C, ACC_NU, SUB_NU, CUR_NU, ENT_REC3, JRN_DATE, END_DATE, FLG, [DES]
							, [30_DAY], [60_DAY], [90_DAY], [120_DAY], [0_DAY], [30_DAY_C], [60_DAY_C]
							, [90_DAY_C], [120_DAY_C], [0_DAY_C]
							)
	select @USR_C,ACC_NU,SUB_NU,CUR_NU,ENT_REC3,min(JRN_DATE),min(JRN_DATE),case when  @Cust_Sup='C' then 1 else 0 end as FLG,'' as [DES]
					,case when CUR_NU=1 then sum(ISNULL(ENT_Dr,0))  else sum(ISNULL(ENT_Conv,0)) end  ,0,0,0,0,0,0,0,0,0 FROM  ENTRY_I Join JOURNAL as j on j.JRN_ID = ENTRY_I.JRN_ID  
					WHERE JRN_DATE<= @PaymentToDate and Ent_dr>0  
					AND ACC_NU= @ACC_NU AND SUB_NU BETWEEN @SUB_NU 
					AND @SUB_NU2 AND LTRIM(ENT_REC3)<>'0' AND LTRIM(ENT_REC3)<>''  
					GROUP BY ACC_NU,SUB_NU,ENT_REC3,CUR_NU 
					HAVING  MIN(JRN_DATE)> @Date1 AND MIN(JRN_DATE)<=@IssueToDate
	
