		INSERT INTO TMP_ACCO3427 (USR_C, ACC_NU, SUB_NU, CUR_NU, ENT_REC3, JRN_DATE, END_DATE, FLG, [DES]
							, [30_DAY], [60_DAY], [90_DAY], [120_DAY], [0_DAY], [30_DAY_C], [60_DAY_C]
							, [90_DAY_C], [120_DAY_C], [0_DAY_C]
							)
	select @USR_C,ACC_NU,SUB_NU,CUR_NU,ENT_REC3,min(JRN_DATE),min(JRN_DATE),case when  @Cust_Sup='S' then 5 else 0 end as FLG,'' as [DES]
					,0,0,0,0,
					
					case when @DR_CR=2  then
						case when CUR_NU=1 then sum(ISNULL(ENT_Cr,0))  else sum(ISNULL(ENT_Conv,0)) end 
