					 FROM  ENTRY_I Join JOURNAL as j on j.JRN_ID = ENTRY_I.JRN_ID  WHERE JRN_DATE<= @PaymentToDate and Ent_Cr>0 AND ACC_NU= @ACC_NU AND SUB_NU BETWEEN @SUB_NU AND @SUB_NU2 AND LTRIM(ENT_REC3)<>'0' AND LTRIM(ENT_REC3)<>''  GROUP BY ACC_NU,SUB_NU,ENT_REC3,CUR_NU HAVING  MIN(JRN_DATE)> '01/01/1990' AND MIN(JRN_DATE)<=@Date4
