	--Calc Cr 
				UPDATE       TMP_ACCO3427
				SET      [30_DAY] =  case when p.Flg=1 then p.SumDrCr *@Rate else 0 end 
						,[60_DAY] =  case when p.Flg=2 then p.SumDrCr*@Rate else 0 end 
						,[90_DAY] =  case when p.Flg=3 then p.SumDrCr*@Rate else 0 end 
						,[120_DAY] =  case when p.Flg=4 then p.SumDrCr*@Rate else 0 end 
						,[0_DAY] =  case when p.Flg=5 then p.SumDrCr*@Rate else 0 end 
				FROM            (SELECT        USR_C AS Usr_c, ACC_NU, SUB_NU, ENT_REC3, CUR_NU, SUM(([30_DAY] + [60_DAY] + [90_DAY] + [120_DAY] + [0_DAY]) 
																- ([30_DAY_C] + [60_DAY_C] + [90_DAY_C] + [120_DAY_C] + [0_DAY_C])) AS SumDrCr, MAX(FLG) AS Flg
