	DECLARE @Month_Other_To int--(2)

	declare @Cust_Sup varchar(1)-- 1=cust,2=supp
	declare @Rate int-- 1=cust,-1=supp
	
	---************************************************
	--clac months
	SET @Month_1=@Month
	SET @Year_1=@Year
	---------------------------------
	if @Month_1-1=0 
		begin
			set @Month_2=12
			set @Year_2=@Year_1-1
		end

	else
		begin
			set @Month_2 =@Month_1-1
			set @Year_2=@Year_1
		end 
	--------------------------------- 
	if @Month_2-1=0 
	 begin
			set @Month_3=12
			set @Year_3=@Year_2-1
		end
	else
	
		begin
			 set @Month_3 =@Month_2-1
			set @Year_3=@Year_2
		end 
---------------------------------
	 if @Month_3-1=0 
		 begin
			set @Month_4=12
			set @Year_4=@Year_3-1
		end
	else
		begin
			 set @Month_4 =@Month_3-1
			set @Year_4=@Year_3
		end 
	 
---------------------------------

	  if @Month_4-1=0 
		
		 begin
			set @Month_5=12
			set @Year_5=@Year_4-1
		end
	else
		begin
			set @Month_5 =@Month_4-1
			set @Year_5=@Year_4
		end 
	 
---------------------------------
	if @Month_5-1=0 
	 
	  begin
			set @Month_6=12
			set @Year_6=@Year_5-1
		end
	else
		begin
			set @Month_6 =@Month_5-1
			set @Year_6=@Year_5
		end 
	 
---------------------------------
	 if @Month_6-1=0 
	 
	  begin
			set @Month_Other=12
			set @Year_Other=@Year_6-1
		end
	else
		begin
			 set @Month_Other =@Month_6-1
			set @Year_Other=@Year_6
		end 
	

	--Set Other Month To
	if @Month_Other<=12 
		set @Month_Other_To=12
	else

---------------------------------

	print  @Month_1 
	print  @Month_2 
	print  @Month_3
	print  @Month_4
	print  @Month_5
	print  @Month_6
	print  @Month_Other
	print  @Year_1
	print  @Year_2 
	print  @Year_3
	print  @Year_4
	print  @Year_5
	print  @Year_6
	print  @Year_Other
