	DECLARE @CUR_CONV float set @CUR_CONV = 1

	delete  from TMP_ACCO3428 where USR_C=@USR_C
	print @Month_1
	print @Month_2
	print @Month_3
	print @Month_4
	print @Month_5
	print @Month_6
	
	 If SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '1' Or SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '3'
		begin
			set @Cust_Sup='C'
