爀琀 䄀䌀䌀伀㌀㔀　㄀㸀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀䔀䐀唀刀䔀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀㌀㔀　㄀崀ഀ਀ऀⴀⴀ 䄀搀搀 琀栀攀 瀀愀爀愀洀攀琀攀爀猀 昀漀爀 琀栀攀 猀琀漀爀攀搀 瀀爀漀挀攀搀甀爀攀 栀攀爀攀ഀ਀ऀ䀀唀匀刀开䌀 瘀愀爀挀栀愀爀⠀㄀　⤀ഀ਀ऀⰀ 䀀䘀洀䐀愀琀攀 搀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀吀漀䐀愀琀攀 搀愀琀攀琀椀洀攀ഀ਀ऀⰀ 䀀嘀攀挀栀椀挀氀攀 椀渀琀ഀ਀
	, @VECHILE_REG_NO varchar(60)
AS
BEGIN
	declare @MyConve float 
	
	delete  FROM TMP_ACCO3501 WHERE USR_C=@USR_C
				
	INSERT INTO [TMP_ACCO3501] 
	(USR_C,JRN_DATE,JRN_NU,ACC_NU,
	SUB_NU,TRN_TYP,
	CST_NU,ENT_DES,ENT_OPR,
	ENT_AMT ,ENT_CONV,COST_NU,ENT_STR,
	ENT_END , ROUT_CODE , CUR_NU, ENT_CUST_NAME,VECHILE_REG_NO) -- Added By khaled
	
	 
    --set @MyConve = (select CUR_CONV from cur where CUR_NU=1 and CUR_DATE=(select max(CUR_DATE) from cur where CUR_NU=1 and CUR_DATE<=@FmDate))

	SELECT        @USR_C AS User_C,
			      ENTRY_20.JRN_DATE AS JRN_DATE,
				  ENTRY_20.JRN_NU AS JRN_NU,
	              ENTRY_20.ACC_NU AS ACC_NU,
	              ENTRY_20.SUB_NU As SUB_NU,
	              ENTRY_TP.JRN_TYP AS TRN_TYP,
	              ENTRY_20_DETAILS.CST_NU AS CST_NU, 
                  ENTRY_20_DETAILS.ENT_DES AS ENT_DES,
                  ENTRY_20_DETAILS.ENT_OPR AS ENT_OPR,
                
                  ENTRY_20_DETAILS.ENT_AMT AS ENT_AMT,
                   (ENTRY_20_DETAILS.ENT_AMT)*(SELECT TOP (1) CUR.CUR_CONV 
						FROM  CUR INNER JOIN CUR_CODE ON CUR.CUR_NU = CUR_CODE.CUR_NU
						WHERE (CUR.CUR_NU = ENTRY_20.CUR_NU) 
						AND (CUR.CUR_DATE <= ENTRY_20.JRN_DATE)
						ORDER BY CUR.CUR_DATE DESC) AS ENT_CONV,
						
                  ENTRY_20_DETAILS.COST_NU AS COST_NU, 
                  ENTRY_20_DETAILS.ENT_STR AS ENT_STR,
                  ENTRY_20_DETAILS.ENT_END AS ENT_END,
                  ENTRY_20_DETAILS.ROUT_CODE AS ROUT_CODE,
                  
                    ENTRY_20.CUR_NU AS CUR_NU,
                  ENTRY_20.ENT_CUST_NAME AS ENT_CUST_NAME,
                  ENTRY_20.VECHILE_REG_NO AS VECHILE_REG_NO
                  
FROM              ENTRY_20 INNER JOIN
                  ENTRY_20_DETAILS ON ENTRY_20.Entry_20_ID = ENTRY_20_DETAILS.Entry_20_ID INNER JOIN
                  ENTRY_20_ROUT ON ENTRY_20_DETAILS.ROUT_CODE = ENTRY_20_ROUT.ROUT_CODE INNER JOIN
                  ENTRY_TP ON ENTRY_20.JRN_TYP_ID = ENTRY_TP.ID LEFT OUTER JOIN
                  EMP ON ENTRY_20_DETAILS.ENT_DRIVER_CODE = EMP.EMP_CODE 
