-- =============================================
-- Author:		<Author,,Name>
-- alter date: <alter Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Finance].[SPACCO3508]
	  @USR_C varchar(10)
	, @FmDate datetime = null 
	, @ToDate datetime= null
	, @MainAcc int = null 
	, @SubAcc int = null

AS
BEGIN
    -- Delete statements for procedure here

	delete  FROM TMP_ACCO3508 WHERE USR_C=@USR_C
	
    -- Insert statements for procedure here
	INSERT INTO [TMP_ACCO3508] 
	(USR_C,JRN_DATE,LINE_NO,ENT_REC3,SUB_NM_E,ENT_AMT,ENT_TAX,TOTAL_AMT,CUR_NAME,ACC_NU,SUB_NU)

	SELECT  @USR_C AS USR_C,
		INVOICE_T.INV_DAT AS JRN_DATE,
		INV_LINE_T.LINE_NO AS LINE_NO,
		INV_LINE_T.INV_NU AS ENT_REC3,
		SUB_ACC.SUB_NM_E AS SUB_NM_E ,
		(INV_LINE_T.INV_AMT) AS ENT_AMT, 						
		INVOICE_T.SAL_TAX  AS ENT_TAX,              
		((INV_LINE_T.INV_AMT)+INVOICE_T.SAL_TAX) AS TOTAL_AMT, 						
		CUR_CODE.CUR_NAME AS CUR_NAME,
		SUB_ACC.ACC_NU AS ACC_NU,
		SUB_ACC.SUB_NU AS SUB_NU            
    
	FROM INVOICE_T INNER JOIN
		INV_LINE_T ON INVOICE_T.INV_ID = INV_LINE_T.INV_ID
		INNER JOIN SUB_ACC ON INVOICE_T.SUB_NU = SUB_ACC.SUB_NU AND INVOICE_T.ACC_NU = SUB_ACC.ACC_NU 
		INNER JOIN CUR_CODE ON INVOICE_T.INV_CUR = CUR_CODE.CUR_NU                          
            
	WHERE        
		INVOICE_T.INV_DAT BETWEEN Convert(datetime,@FmDate) AND Convert(datetime,@ToDate)
		AND (INV_LINE_T.INV_NU is not NULL) 
		And (SUB_ACC.ACC_NU = @MainAcc Or @MainAcc IS NULL)
		And (SUB_ACC.SUB_NU = @SubAcc Or @SubAcc Is Null)
			--ORDER BY INV_LINE_T.INV_NU Commented By khaled
END










