-- =============================================
CREATE procEDURE [Finance].[SPACCO3510]
	  @USR_C varchar(10)
	, @FmDate datetime = null 
	, @ToDate datetime = null
	, @Vehicle int=null
	,@VehicleName varchar(60)=null
AS
BEGIN
    -- Delete statements for procedure here

	delete  FROM TMP_ACCO3510 WHERE USR_C=@USR_C
	
	 -- Insert statements for procedure here
	INSERT INTO TMP_ACCO3510 
	(USR_C,JRN_DATE,JRN_NU,ENT_REC1,JRN_TYP,ENT_21DES,ENT_21QTY,ENT_21AMT,ENT_21KM,SUB_NU,VECHILE_REG_NO,ACC_NU,ACC_NM_A,ACC_NM_E)
 
	
SELECT        @USR_C AS USR_C,
			  ENTRY_21.JRN_DATE AS JRN_DATE,
			  ENTRY_21.JRN_NU AS JRN_NU,
		      ENTRY_21_DETAILS.ENT_REC1 AS ENT_REC1,
			  ENTRY_TP.JRN_TYP AS JRN_TYP,
              ENTRY_21_DETAILS.ENT_21DES AS ENT_21DES,
              ENTRY_21_DETAILS.ENT_21QTY AS ENT_21QTY,
              ENTRY_21_DETAILS.ENT_21AMT AS ENT_21AMT,
              ENTRY_21_DETAILS.ENT_21KM AS ENT_21KM,
              ENTRY_21_DETAILS.SUB_NU AS SUB_NU, 
              ENTRY_21_DETAILS.VECHILE_REG_NO AS VECHILE_REG_NO,
              ENTRY_21_DETAILS.ACC_NU AS ACC_NU,
              MAIN_ACC.ACC_NM_A AS ACC_NM_A,
              MAIN_ACC.ACC_NM_E AS ACC_NM_E
              
FROM         ENTRY_21 INNER JOIN
             ENTRY_21_DETAILS ON ENTRY_21.Entry_21_ID = ENTRY_21_DETAILS.Entry_21_ID INNER JOIN
             ENTRY_TP ON ENTRY_21.JRN_TYP_ID = ENTRY_TP.ID INNER JOIN MAIN_ACC ON ENTRY_21_DETAILS.ACC_NU = MAIN_ACC.ACC_NU
             
WHERE        ENTRY_21.JRN_DATE BETWEEN Convert(datetime,@FmDate) AND Convert(datetime,@ToDate)
	         AND (( ENTRY_21_DETAILS.SUB_NU = @Vehicle )or(@Vehicle is null)) 
