CREATE procEDURE [Finance].[SPACCO3514]
	  @USR_C varchar(10)
	, @FmDate varchar(100) = null 
	, @ToDate varchar(100) = null
	, @Vehicle varchar(8000)=null
AS
BEGIN

  if @Vehicle ='All'
 SET @Vehicle =NULL
 
 DECLARE @temp TABLE (item nvarchar(4000)) -- Convert Type From In By Khaled 20-04-2015
										   -- Size Changed To 4000 By Khaled in 06-05-2014
	INSERT INTO @temp
	execute SPSplitDelimiterString @Vehicle, ',' 
    -- Delete statements for procedure here

	delete  FROM TMP_ACCO3514 WHERE USR_C=@USR_C
	
    -- Insert statements for procedure here
 
    --Insert All Revenue
    ---------------------------------------------
	INSERT INTO [TMP_ACCO3514] 
	(USR_C,SUB_NU,AMT_EXP,AMT_REV,KM_TOTAL,SUB_NM,FLG)
	
SELECT        @USR_C AS USR_C,
			  ENTRY_20.SUB_NU AS SUB_NU, 
		       0,
			  ((ENTRY_20_DETAILS.ENT_AMT)*(SELECT TOP (1) CUR.CUR_CONV 
						FROM  CUR INNER JOIN CUR_CODE ON CUR.CUR_NU = CUR_CODE.CUR_NU
						WHERE (CUR.CUR_NU = ENTRY_20.CUR_NU) 
						AND (CUR.CUR_DATE <= ENTRY_20.JRN_DATE)
						ORDER BY CUR.CUR_DATE DESC))AS AMT_REV,
			  
             (ENTRY_20_DETAILS.ENT_END- ENTRY_20_DETAILS.ENT_STR)AS KM_TOTAL,
              ENTRY_20.VECHILE_REG_NO AS SUB_NM,
              1
FROM          ENTRY_20 INNER JOIN
              ENTRY_20_DETAILS ON ENTRY_20.Entry_20_ID = ENTRY_20_DETAILS.Entry_20_ID
WHERE                
			  ENTRY_20.JRN_DATE BETWEEN Convert(datetime,@FmDate) AND Convert(datetime,@ToDate)
              AND ((ENTRY_20.VECHILE_REG_NO in (select item from @temp) )or(@Vehicle is null))   
              -- Old Form Changed By Khaled In 20-04-2015 Because The Sub_nu's results return Data From Maulti Main ACC 
