/****** Object:  StoredProcedure [Finance].[SPACCO4000_1]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Finance].[SPACCO4000_1]
	-- Add the parameters for the stored procedure here
	@fromdate datetime
	, @todate datetime
	, @usercode nvarchar(250)
	, @prgcode nvarchar(250)
AS
BEGIN
select 
 (SELECT     CO_NAMEE
                        FROM         SYS_PARA) AS CompanyName,
(sys_prg+'  '+ prg_des)as Program,
prg_para as 'screen Flags',
PRG_GRP,
mdl_nm_a as NameAR,
mdl_nm_e as NameEN,
count(*)as errorcount
from sys_log as sl
join sys_prg as sp
on sl.sys_prg=sp.prg_code
join sys_mdl as sm
on sp.prg_grp=sm.mdl_code
where
(
@usercode is not null and @prgcode is not null
and
cast(SYS_DATE as date) between @fromdate and @todate
 and sys_user=@usercode and prg_code=@prgcode
 )
 or
 (
 @usercode is not null and @prgcode is  null
and
 cast(SYS_DATE as date) between @fromdate and @todate
 and sys_user=@usercode 
 )
 or
 (
 @usercode is  null and @prgcode is not null
and
 cast(SYS_DATE as date) between @fromdate and @todate
 and prg_code=@prgcode
 )
 or
 (
 @usercode is  null and @prgcode is  null
and
 cast(SYS_DATE as date) between @fromdate and @todate
 )

group by sys_user,sys_prg,prg_des,prg_para,prg_grp,mdl_nm_a,mdl_nm_e



END








