	DECLARE @xx varchar (6)
	
	--1
	delete  FROM TMP_ACC4500B WHERE USR_C=@USR_C
	delete  FROM TMP_TRIAL_BALANCE WHERE USR_C=@USR_C
	insert into TMP_TRIAL_BALANCE(USR_C,From_No,To_No,LN) 
	select @USR_C ,ACC_NU  ,ACC_NU  ,LINE_NO from TRIAL_BALANCE WHERE  [CODE]=@Code 
	
	--EXTEND ACCOUNT NO 1100->1199 ,1110->1119
	--update TMP_TRIAL_BALANCE set TO_NO=119999 where from_no=110000 
	--*******************************************
	--EXTEND ACCOUNT NO 1100->1199 ,1110->1119
	
		insert into TMP_ACC4500B (USR_C,acc,acc_to,ent_dr,ent_cr,str_dr,str_cr,LN,BAL_CODE) 
		select @USR_C,From_No,REPLACE ( To_No , '0' , '9' ),0,0,0,0,LN,@Code from TMP_TRIAL_BALANCE  where  USR_C=@USR_C 

	

	
	--*******************************************
	
	UPDATE       TMP_ACC4500B
SET                ENT_DR = t.SDR, ENT_CR = t.SCR
FROM            (SELECT        TMP_ACC4500B_1.ACC, isnull(SUM(isnull(round(ENTRY.ENT_DR,2),0)),0) AS SDR, isnull(SUM(isnull(round(ENTRY.ENT_CR,2),0)),0) AS SCR
                           FROM            JOURNAL INNER JOIN
                                                    ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID INNER JOIN
                                                    TMP_ACC4500B AS TMP_ACC4500B_1 ON ENTRY.ACC_NU >= TMP_ACC4500B_1.ACC AND ENTRY.ACC_NU <= TMP_ACC4500B_1.ACC_TO
                           WHERE        (JOURNAL.JRN_DATE >= @FmDate) AND (JOURNAL.JRN_DATE <= @ToDate) AND (TMP_ACC4500B_1.USR_C = @USR_C) AND 
