	--5
			update TMP_ACC4710 
			set  TMP_ACC4710.KOL1=(SELECT isnull(SUM(TMP_ACC4710M.GOZE1) ,0)
			 from TMP_ACC4710 AS TMP_ACC4710M  
			 where  TMP_ACC4710.LN_NO=TMP_ACC4710M.KOL_NO 
			  AND  TMP_ACC4710.USR_C=TMP_ACC4710M.USR_C and 
			   TMP_ACC4710.ACC_TOT ='2' and TMP_ACC4710.USR_C=@USR_C )
				 where TMP_ACC4710.USR_C=@USR_C
	--6
   update TMP_ACC4710 set  TMP_ACC4710.MG=(SELECT SUM (TMP_ACC4710M.KOL1)  from TMP_ACC4710 AS TMP_ACC4710M  where  TMP_ACC4710.LN_NO=TMP_ACC4710M.KOL_NO  AND  TMP_ACC4710.USR_C=TMP_ACC4710M.USR_C and  TMP_ACC4710.ACC_TOT ='3' and TMP_ACC4710.USR_C=@USR_C )
     where TMP_ACC4710.USR_C=@USR_C
	

