	--1
	delete  FROM TMP_ACC4810 WHERE USR_C=@USR_C
	
	--2
	insert into TMP_ACC4810 
	(USR_C,CODE,LN_NO,KOL_NO,ACC_TOT,ACC_NU,ACC_NAME,GOZE1,KOL1,MG,TO_ACC) 
	SELECT @USR_C,CODE,LINE_NO,LINE_NO_GROUP,ACC_TYPE,ACC_NU,ACC_NAME,0,0,0,REPLACE ( Acc_nu , '0' , '9' ) 
	FROM FINANCIAL_STATEMENT where CODE =@Code

	
	--3
	update TMP_ACC4810 
	set  GOZE1= ISNULL(
	
	(SELECT SUM(isnull((ENTRY.ENT_DR),0)-isnull((ENTRY.ENT_CR),0))  
	FROM   JOURNAL INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID 
	--LEFT OUTER JOIN ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID 
	WHERE ENTRY.ACC_NU>=TMP_ACC4810.ACC_NU 
	and ENTRY.ACC_NU<=TMP_ACC4810.TO_ACC 
	and JRN_DATE >= @FmStrDate
	and JRN_DATE <= @ToDate
	and ACC_TOT='1' 
	and  USR_C=@USR_C 
	-- AND (JRN_TYP='1' OR JRN_TYP='2') // ??KH
	--AND JRN_TYP<>'AA' AND JRN_TYP<>'CC' // ??KH
