	--3
	update TMP_ACC4810 
	set  GOZE1= ISNULL(
	
	(SELECT SUM(isnull((ENTRY.ENT_DR),0)-isnull((ENTRY.ENT_CR),0))  
	FROM   JOURNAL INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID 
	--LEFT OUTER JOIN ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID 
	WHERE ENTRY.ACC_NU>=TMP_ACC4810.ACC_NU 
	and ENTRY.ACC_NU<=TMP_ACC4810.TO_ACC 
	and JRN_DATE >= @FmDate
	and JRN_DATE <= @ToDate
	and ACC_TOT='1' 
	and  USR_C=@USR_C 
	-- AND (JRN_TYP='1' OR JRN_TYP='2') // ??KH
	--AND JRN_TYP<>'AA' AND JRN_TYP<>'CC' // ??KH
	and (
				(JRN_TYP  in( @EntryType1 , @EntryType2 , @EntryType3, @EntryType4, @EntryType5, @EntryType6, @EntryType7, @EntryType8, @EntryType9, @EntryType10, @EntryType11, @EntryType12,@EntryType13,@EntryType14,@EntryType15,@EntryType16 ) 
				or (@EntryType1 is null and @EntryType2 is null and @EntryType3 is null and @EntryType4 is null and @EntryType5 is null and @EntryType6 is null and @EntryType7 is null and @EntryType8 is null and @EntryType9 is null and @EntryType10 is null and @EntryType11 is null and @EntryType12 is null and @EntryType13 is null and @EntryType14 is null and @EntryType15 is null and @EntryType16 is null ) 
				)
