	--7
	update TMP_ACC4810 
	set   kol1=KOL1 + ISNULL((SELECT SUM(isnull(B.GOZE1,0))  
	from TMP_ACC4810 AS B   
	where  TMP_ACC4810.LN_NO=B.KOL_NO  
	AND TMP_ACC4810.ACC_TOT ='2' 
	and TMP_ACC4810.USR_C=@USR_C 
	and B.USR_C=@USR_C  )
	,0) where TMP_ACC4810.USR_C=@USR_C
	
	
	--8
	update TMP_ACC4810 
	set   MG=MG + ISNULL((SELECT SUM(isnull(B.KOL1,0))  
	from TMP_ACC4810 AS B   
	where  TMP_ACC4810.LN_NO=B.KOL_NO  
	AND TMP_ACC4810.ACC_TOT ='3' 
