	update TMP_ACC4900 set GOZE1= 
	
isnull(
(SELECT SUM(isnull(ENTRY.ENT_CR,0) - isnull(ENTRY.ENT_DR,0)) 
FROM Finance.JOURNAL 
INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID 
--INNER JOIN ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID 
WHERE   
ENTRY.ACC_NU >= TMP_ACC4900.ACC_NU AND ENTRY.ACC_NU <= TMP_ACC4900.TO_ACC 
and (MONTH(JOURNAL.JRN_DATE) = 1) AND (YEAR(Finance.JOURNAL.JRN_DATE) = @Year) AND (Finance.TMP_ACC4900.ACC_TOT = '1') AND 
(Finance.TMP_ACC4900.USR_C = @USR_C) --and TMP_ACC4900.ACC_NU=ENTRY.ACC_NU
and (
				(JRN_TYP  in( @EntryType1 , @EntryType2 , @EntryType3, @EntryType4, @EntryType5, @EntryType6, @EntryType7, @EntryType8, @EntryType9, @EntryType10, @EntryType11, @EntryType12,@EntryType13,@EntryType14,@EntryType15,@EntryType16 ) 
				or (@EntryType1 is null and @EntryType2 is null and @EntryType3 is null and @EntryType4 is null and @EntryType5 is null and @EntryType6 is null and @EntryType7 is null and @EntryType8 is null and @EntryType9 is null and @EntryType10 is null and @EntryType11 is null and @EntryType12 is null and @EntryType13 is null and @EntryType14 is null and @EntryType15 is null and @EntryType16 is null ) 
				)
				) 
AND 
 
((JRN_TYP <> @NotEntryType1)OR(@NotEntryType1 IS NULL))
and((JRN_TYP <> @NotEntryType2)OR(@NotEntryType2 IS NULL))
and((JRN_TYP <> @NotEntryType3)OR(@NotEntryType3 IS NULL))
and((JRN_TYP <> @NotEntryType4)OR(@NotEntryType4 IS NULL))
and((JRN_TYP <> @NotEntryType5)OR(@NotEntryType5 IS NULL))
and((JRN_TYP <> @NotEntryType6)OR(@NotEntryType6 IS NULL))
and((JRN_TYP <> @NotEntryType7)OR(@NotEntryType7 IS NULL))
and((JRN_TYP <> @NotEntryType8)OR(@NotEntryType8 IS NULL))
and((JRN_TYP <> @NotEntryType9)OR(@NotEntryType9 IS NULL))
