	--6
update TMP_ACC4900 set GOZE3= 
isnull(
(SELECT SUM(isnull(ENTRY.ENT_CR,0) - isnull(ENTRY.ENT_DR,0)) 
FROM Finance.JOURNAL 
INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID 
--INNER JOIN ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID 
WHERE   
ENTRY.ACC_NU >= TMP_ACC4900.ACC_NU AND ENTRY.ACC_NU <= TMP_ACC4900.TO_ACC 
and (MONTH(JOURNAL.JRN_DATE) = 3) AND (YEAR(Finance.JOURNAL.JRN_DATE) = @Year) AND (Finance.TMP_ACC4900.ACC_TOT = '1') AND 
(Finance.TMP_ACC4900.USR_C = @USR_C)-- and TMP_ACC4900.ACC_NU=ENTRY.ACC_NU
and (
				(JRN_TYP  in( @EntryType1 , @EntryType2 , @EntryType3, @EntryType4, @EntryType5, @EntryType6, @EntryType7, @EntryType8, @EntryType9, @EntryType10, @EntryType11, @EntryType12,@EntryType13,@EntryType14,@EntryType15,@EntryType16 ) 
