	--10
	update TMP_ACC4900 set GOZE7= 
	isnull(
(SELECT SUM(isnull(ENTRY.ENT_CR,0) - isnull(ENTRY.ENT_DR,0)) 
FROM Finance.JOURNAL 
INNER JOIN ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID 
