/****** Object:  StoredProcedure [Finance].[SPACCOS3000]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [Finance].[SPACCOS3000] 
AS 
SELECT  
 (SELECT CO_NAMEE FROM SYS_PARA) AS CompanyName,
[Id]
,u.[UserId]
,UserName
,User_Name
,up.[PRG_CODE]
,[PRG_DES]
,case [PRG_ADD]  when 1 then 'Y' else 'N' end as [Add]
,case [PRG_UPD] when 1 then 'Y' else 'N' end as [Update]
,case [PRG_DEL] when 1 then 'Y' else 'N' end as [Delete]
,case [PRG_DIS] when 1 then 'Y' else 'N' end as [Dispaly]
,case [PRG_PRT] when 1 then 'Y' else 'N' end as [Print]
FROM 
ctrl as u  
left join [SYS_USER] as up 
on up .userid=u.userid
join [SYS_PRG] as sp
on up.prg_code=sp.prg_code








GO
/****** Object:  StoredProcedure [Finance].[SPACCOS3200]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [Finance].[SPACCOS3200] 
    @PrgCode VARCHAR(15)
AS 
SELECT (SELECT CO_NAMEE FROM SYS_PARA) AS CompanyName,
[Username]  =(SELECT Username FROM CTRL AS C WHERE C.UserID =SU.UserId)
,[USER_NAME]=(SELECT USER_NAME FROM CTRL AS C WHERE C.UserID =SU.UserId)
,PRG_CODE,PRG_ADD,PRG_UPD,PRG_DEL,PRG_DIS,PRG_PRT
FROM Finance.SYS_USER AS SU
WHERE SU.PRG_CODE = @PrgCode








GO
