CREATE procEDURE [Finance].[SPACCOS6000]

AS
BEGIN

SELECT     ENTRY_TP.JRN_TYP, ENTRY_TP.JRN_DES, ENTRY_TP_DETAIL.ACC_NU, MAIN_ACC.ACC_NM_E,CompanyName=(SELECT CO_NAMEE FROM SYS_PARA)
FROM       ENTRY_TP INNER JOIN
           ENTRY_TP_DETAIL ON ENTRY_TP.ID = ENTRY_TP_DETAIL.ENTRY_TP_ID INNER JOIN
           MAIN_ACC ON ENTRY_TP_DETAIL.ACC_NU = MAIN_ACC.ACC_NU
END
