开䄀䌀䌀 伀一 䌀伀匀吀开吀倀⸀䄀䌀䌀开一唀 㴀 䴀䄀䤀一开䄀䌀䌀⸀䄀䌀䌀开一唀ഀ਀䔀一䐀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䘀椀渀愀渀挀攀崀⸀嬀匀倀䄀䌀䌀伀匀㤀㐀　　崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀
CREATE procEDURE [Finance].[SPACCOS9400]

	  @USR_C VARCHAR(10)
	, @fromdate datetime 
	, @todate datetime
	, @fromMainAccount int
	, @toMainAccount int
as
begin

-- ********* Calculate Year ************* using to add in str_bal ****************************************
 DECLARE @Months_Diff float 
 set  @Months_Diff =abs (DATEDIFF(month,@todate,@fromdate)) --(SELECT DATEDIFF(day,@todate,@fromdate) AS DiffDate)/30
 print @Months_Diff
 DECLARE @year int 
 IF (year(@todate) =  year(@fromdate))
 begin 
	SET @year  = Year( @todate) +1
 End 
 else IF (year(@todate) > year(@fromdate)) AND (@Months_Diff <= 12)
 begin 
	SET @year  = Year( @todate)
 End 
 ELSE 
	SET @year  = Year(@todate) + 1 
-- *************************************************************************************
 print @year
delete from str_bal where STR_YEAR = @year AND  ACC_NU >= @fromMainAccount AND ACC_NU <= @toMainAccount


Insert into str_bal (ACC_NU,SUB_NU,STR_BAL,STR_YEAR,STR_TYP,CUR_NU) 
SELECT     entry.ACC_NU   ,entry.sub_NU  AS SUB_NU, ISNULL(SUM(ISNULL(Finance.ENTRY.ENT_DR, 0)), 0) - ISNULL(SUM(ISNULL(Finance.ENTRY.ENT_CR, 0)), 0) AS bal, @year AS [year], 1 AS STR_TYP, 
                         1 AS CUR_NU
FROM            Finance.ENTRY INNER JOIN
                         Finance.JOURNAL ON Finance.ENTRY.JRN_ID = Finance.JOURNAL.JRN_ID
WHERE        (Finance.ENTRY.ACC_NU >= @fromMainAccount) AND (Finance.ENTRY.ACC_NU <= @toMainAccount) AND (Finance.JOURNAL.JRN_DATE >= @fromdate) AND 
                         (Finance.JOURNAL.JRN_DATE <= @todate)
group by ENTRY.ACC_NU,entry.sub_NU 

print 'nabila'

	UPDATE    STR_BAL
						SET   STR_BAL.STR_BAL = STR_BAL.STR_BAL + T.sTR_DR
				       FROM  (SELECT        ACC_NU, ISNULL(SUB_NU, 0) AS SUB_NU, ROUND(sum(ISNULL(STR_BAL, 0)), 2)  AS sTR_DR 
                         ,STR_YEAR AS STR_YEAR
				FROM            STR_BAL as STR_BAL_M
				where STR_TYP = 1
				GROUP BY ACC_NU, ISNULL(SUB_NU, 0), STR_YEAR
				HAVING        (STR_YEAR = @year-1)) as t
				INNER JOIN
                      STR_BAL ON T.ACC_NU = STR_BAL.ACC_NU AND T.SUB_NU = STR_BAL.SUB_NU
     WHERE STR_BAL.STR_YEAR=@year 


	 UPDATE    STR_BAL
