CREATE procEDURE [Finance].[SPACCOS9410]

	  @USR_C VARCHAR(10)
	, @todate datetime
	, @MyYear int
	
as
begin

-- ********* Calculate Year ************* using to add in str_bal ****************************************
   DECLARE @ACCOUNTING_MONTH int 
   DECLARE @fromdate datetime 
   DECLARE @MYD varchar(2) 
   DECLARE @MYM varchar(2) 
   DECLARE @MYY varchar(4) 
   DECLARE @ExpAcc  int
   DECLARE @RevAcc  int
	DECLARE @ACC_TYPE  int
   DECLARE @Acc_nu real
    DECLARE @Sub_nu real
	 DECLARE @MYbal float
	 	DECLARE @sqlCommand varchar(8000)
 set  @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From SYS_DATA )
 IF @ACCOUNTING_MONTH=0 
 SET @ACCOUNTING_MONTH=1
 IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = @ACCOUNTING_MONTH
		SET @MYY = @MyYear-1
		
	END
ELSE
		begin
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = @MyYear
		
		end
	 print @MYM
	 print @MYD
	 print @MYY

	

SET @fromdate = @MYM + '/' + @MYD +'/'+  @MYY
print 'MyDates'
print @fromdate
print @todate
