洀㄀  瘀愀爀挀栀愀爀⠀㔀　⤀ഀ਀ऀ搀攀挀氀愀爀攀 䀀伀瘀攀爀吀愀砀㄀ 昀氀漀愀琀ഀ਀ऀ猀攀琀 䀀匀夀匀开䐀䄀吀䔀㴀挀漀渀瘀攀爀琀⠀瘀愀爀挀栀愀爀⠀㄀　⤀Ⰰ 最攀琀搀愀琀攀⠀⤀Ⰰ ㄀㄀　⤀ഀ਀ऀ猀攀琀 䀀匀夀匀开吀䤀䴀䔀㴀䌀伀一嘀䔀刀吀⠀嘀䄀刀䌀䠀䄀刀⠀㔀⤀Ⰰ最攀琀搀愀琀攀⠀⤀Ⰰ㄀　㠀⤀ഀ਀ऀ瀀爀椀渀琀 ✀䄀椀爀䄀爀愀戀椀愀吀漀䜀愀琀猀✀ഀ਀ऀഀ਀ऀⴀⴀ甀瀀搀愀琀攀 猀礀猀开搀愀琀愀开愀椀爀 眀椀琀栀 搀愀琀愀 搀攀昀愀甀氀琀ഀ਀ऀ甀瀀搀愀琀攀 匀夀匀开䐀䄀吀䄀开䄀䤀刀 ഀ਀
	set CONV_PRICE =@Convprice,
		CStamp=@CStamp,
		Cleaving=@Cleaving,
		CPrcTax1=@CPrcTax1,
		CPrcTax2=@CPrcTax2,
		CMAXTax1=@CMAXTax1,
		CMAXTax2=@CMAXTax2,
		MinTktTotalInDirham=@MinTktTotalInDirham

	--Get Carrir Code
	set @MyQueryString = 'select @out_param = TKT'+ substring(cast(@Tkt_Nu as varchar(30)),1,1) +' from [SYS_DATA_AIR] '
	--print @MyQueryString
	EXEC sp_executesql @MyQueryString, N'@out_param varchar(3) OUTPUT', @out_param = @AIR_COMP OUTPUT
	--print @AIR_COMP
	
	--Get Acc_Nu
	Set @Acc_Nu=(select cus_air from sys_data )


	set @TKT_TOT = Round(@TKT_TOT * @ConvPrice, 2)

	
	BEGIN TRY
	BEGIN TRANSACTION	
	--get max Air_Cod
	Select @AIR_COD =(SELECT Max(isnull(AIR_COD,0))+1 as AIR_COD FROM  AIR_LINE )
	if 	@AIR_COD is Null  Set @AIR_COD = 1 
	PRINT @AIR_COD
	--************************************************
	--get @@MyRem1 --get @@Mytax3--get @@Mystamp--get @@@MyBasic
	
	if EXISTS (select * from AIR_TKT Where TKT_NR=@Tkt_Nu and TKT_PASS=@TKT_PASS)
	
	begin --penality
	print 'what'
		set @MyBasic= @TKT_TOT
		print 'total'
		set @MyRem1='Penalty'
		set @Mytax3=0
		set @Mystamp=0
		IF @TKT_TOT>0
			SET @air_k_typ='2'
		ELSE
			SET @air_k_typ='3'
		
	end
	
	else --not penality
	begin
		print 'not penalty'
		set @MyBasic=round(@TKT_TOT-@CStamp -@Cleaving,2)
		
		set @MyRem1=''
		set @Mytax3=@Cleaving
		set @Mystamp=@CStamp
		IF @TKT_TOT>0
			SET @air_k_typ='1'
		ELSE
			SET @air_k_typ='3'
	end
		
          	
	--get @@MYTax1
	--get @@MYTax2
	set @MYTax2 = Round((@MyBasic * (@CPrcTax2) / (@CPrcTax1 + @CPrcTax2 + 100)), 2) --'total*5/130
	print @MYTax2
	
		
	 If PARSENAME(@MYTax2,1) > 0
	
		set @MYTax2 = cast (@MYTax2 as int  ) + 1
		print @MYTax2

	If @MYTax2 > @CMAXTax2 And @CMAXTax2 <> 0 
	begin
        set  @MYTax2 = @CMAXTax2
        set  @MYTax1 = Round(((@MyBasic - @CMAXTax2) * (@CPrcTax1) / (@CPrcTax1 + 100)), 2)  --'total*25/130
            If @MYTax1 > @CMaxTax1 And @CMaxTax1 <> 0 
			begin
				set @OverTax1 = @MYTax1 - @CMaxTax1
				set @MYTax1 = @CMaxTax1
			end
            Else
