/****** Object:  StoredProcedure [Finance].[SPAirlineEntry]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Finance].[SPAirlineEntry]
 @Air_code int,
 @User_Name varchar(10)=null,
 @Mode varchar(1) = null,
 @OldBranch varchar(3) = null
AS
 
BEGIN
----------------------------------- Variables Declaration ---------------------------------
	Declare @BranchFlag nvarchar(20)	-- Flag For 2000T
	Declare @EntryTP_ID int		
	Declare @Date DateTime	
	Declare @AirLine_Type varchar(1)
	Declare @K_Type varchar(1)
	Declare	@AIR_P_TY varchar(1)	
	Declare	@JournalID bigint
	Declare @AirLineBranch varchar(3) 
	Declare @FormOfPayment varchar(1)
	Declare @Jrn_Des varchar(100) =''
	Declare @JRN_TYP_ID int
	Declare @CompanySub real
	Declare @EntryDesc varchar(120)
	Declare @Ent_Red4 DateTime
	Declare @Cost_nu varchar(15)	
	--Declare @AIRPOST_FLAG_NAT varchar(1)
	----------------------------------- Variables Intialization ---------------------------------
	--------------------------------------------------------------------------
	--Get Air_Post("Type") Condation = @AirLine_Type
	Set @AirLine_Type = 'I'
	select @AIR_P_TY = AIR_P_TY, @K_Type = AIR_K_TYP , @Date = case when @K_Type=3 then AIR_LINE.AIR_DAT else AIR_LINE.AIR_ISS end	,@AirLineBranch=AIR_BRAN
	 , @AirLine_Type = 
		case 
			when (AIR_LINE.AIR_K_TYP = 1 OR AIR_LINE.AIR_K_TYP = 2)And AIR_LINE.AIR_C_PY <> 2 Then 'I' 
			when (AIR_LINE.AIR_K_TYP = 1 OR AIR_LINE.AIR_K_TYP = 2)And AIR_LINE.AIR_C_PY = 2 Then 'C' 
			when AIR_LINE.AIR_K_TYP = 3  And AIR_LINE.AIR_C_PY <> 2 Then 'R' 
			when AIR_LINE.AIR_K_TYP = 3  And AIR_LINE.AIR_C_PY = 2 Then 'F'			
		end
	 from AIR_LINE Where AIR_LINE.AIR_COD = @Air_code
	--------------------------------------------------------------------------
	
	-- get falg Of Branch In 2000t
	select  @BranchFlag = ISNULL(SUBSTRING(PRG_PARA,6,1),'-') from SYS_PRG Where PRG_CODE = 'ACCO2000T'										
