	----------------------------------- Delete Before Update For Not Void Tickets ---------------------------------
	if (@Mode = 'D' OR @Mode = 'U' And @K_Type <> '4')
	Begin
		Delete C From COST_ENT C INNER JOin Journal J On J.JRN_ID = C.JRN_ID Where J.JRN_NU = @Air_code And J.JRN_TYP = @EntryTP_ID AND J.JRN_DATE = Cast (@Date as datetime)
		Delete from Journal Where Journal.JRN_NU = @Air_code And Journal.JRN_TYP = @EntryTP_ID AND Journal.JRN_DATE = @Date
	END
	print('------------Mode---------')	
	print(@K_Type)print('---@K_Type')	
	print(@Date)print('---@Date')
	print(@Air_code)print('---@Air_code')		
	print(@EntryTP_ID)print('---@EntryTP_ID')
	print @mode	
	print('-------------------------')		 
