			Null
			,0 --ent_conv
			,--	Ent_Dr
			case 
					when (DB_CR = 'D') Then ABS(@Value)
					else 0
				End
			
			
			,--Ent_CR	
			   case 
					when (DB_CR = 'C') Then ABS(@Value)
					else 0
				End
			
			,@EntryDesc --Ent_desc
			
			, INVOICE_FLAG --Ent_Flg
			
			,-- Ent_rec3
			  case 
					when (INVOICE = 'AIR_REC1') Then
					  AIR_REC1										
				End
			,@date--[ENT_RED3]
			,-- [ENT_RED4]	
			 case  when (INVOICE <> ' ') Then  @Ent_Red4 else '01/01/1990' end
							
			From AIR_POST Inner Join AIR_LINE On AIR_POST.TYPE = @AirLine_Type 
			Where AIR_COD = @Air_code And LINE_NO = @LINE_NO And @Value <> 0 And @Value is not null
			-------------------------------------------------End Of Entry' Records Insert-------------------------------------------------
			print 'End Insert  Into Entry'
			
			
			-------------------------------------------------Insert Into Cost_ENT-------------------------------------------------
			select  @EntryID = ENT_ID From ENTRY Where ENTRY.JRN_ID = @JournalID						
			select  @AirLine_ACC = AIR_ACC,@Cost_nu=Cost_NU ,@CST_NO = CST_NO From AIR_LINE Where AIR_COD=@Air_code
			
			
			if(select Replace(str(CUS_TOURS_EX),' ','') From SYS_DATA Where CUS_TOURS_EX IS NOT Null) = SUBSTRING(CAST(@AirLine_ACC AS nvarchar(15)),1,2) 
											OR (select Replace(str(CUS_JOURNEY_EX),' ','') From SYS_DATA Where CUS_JOURNEY_EX IS NOT Null) = SUBSTRING(CAST(@AirLine_ACC AS nvarchar(15)),1,2)
						and @Cost_nu <>''
						
			Begin										
				Print '-----START COST_ENT'
				Insert Into COST_ENT			
				Select @EntryID,@JournalID,@AirLine_ACC,@CST_NO,null,null,@Cost_nu,null -- @Cost_nu
						,'01/01/1990', null	,ABS(@Value) ,null  ,'01/01/1990',ABS(@Value),0,@EntryDesc,
						ROW_NUMBER() OVER(ORDER BY SUB_ACC),
						case 
							when (AIR_POST.DB_CR = 'C') Then 2 
