CREATE procEDURE [Finance].[SPAutoUpdateEntry_20]

 @fromdate datetime
, @todate datetime
,@Entry20_ID bigint = null
,@Entry20_JRNTYP bigint = null
,@DeleteOnly bit = 0
AS
 
BEGIN
Declare @Flag nvarchar(20);
Declare @Cost_nu varchar(15)
Declare @Entry_20DAcc real
declare @EntryID bigint
Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2020'
select @Entry_20DAcc = ACC_NU from ENTRY_20 Where Entry_20_ID = @Entry20_ID

IF @DeleteOnly = 0 AND SUBSTRING( @Flag,2,1) = 'P' 
Begin

	Declare @JRN_ID BigInt;
	Declare @CONV real;		
	Declare @Description nvarchar(200);
   
	DECLARE tEntry_cursor CURSOR FOR    
