							, ACC_NU, ACC_NU_C, SUB_NU, SUB_NU_C, BDG_TYP_Y,BDG_TYP_N,BDG_TBL
			From BDG_ACC Where BDG_CODE = @OldCode and BDG_YEAR = @OldYear
		
		UPDATE	BDG_ACC
		SET	BDG_LINE_ID = BDG_LINE.BDG_LINE_ID
		FROM BDG_LINE INNER JOIN BDG_ACC 
			ON BDG_LINE.BDG_YEAR = BDG_ACC.BDG_YEAR 
				AND BDG_LINE.BDG_CODE = BDG_ACC.BDG_CODE 
				AND BDG_LINE.BDG_LIN = BDG_ACC.BDG_LIN
		WHERE BDG_ACC.BDG_CODE = @NewCode and BDG_ACC.BDG_YEAR = @NewYear and BDG_ACC.BDG_LINE_ID is null

		UPDATE	BDG_EQT
		SET	BDG_LINE_ID = BDG_LINE.BDG_LINE_ID
		FROM BDG_LINE INNER JOIN BDG_EQT 
			ON BDG_LINE.BDG_YEAR = BDG_EQT.BDG_YEAR 
				AND BDG_LINE.BDG_CODE = BDG_EQT.BDG_CODE 
				AND BDG_LINE.BDG_LIN = BDG_EQT.BDG_LIN
		WHERE BDG_EQT.BDG_CODE = @NewCode and BDG_EQT.BDG_YEAR = @NewYear and BDG_EQT.BDG_LINE_ID is null

	COMMIT TRAN
	print 'SUCCESS'
	-- ReturnValue
	select 'S' + @NewCode
	END TRY
BEGIN CATCH
	IF @@TRANCOUNT > 0
		ROLLBACK TRAN --RollBack in case of Error
	print 'ERROR'
	--log the ERROR
	insert into [SYS_ERR](  ERR_DATE, ERR_TIME, ERR_MSG, PRG_CODE)
	values( GETDATE(), '00:00', ERROR_MESSAGE(),'CopyBudget')  
	select '-1'    
END CATCH
END











