GO


CREATE procEDURE [Finance].[SPF1GetAirLineByTicket]
	@USR_C varchar(10)
	,@AirCode varchar(200)	
	,@TMPFields varchar(200)  	
	,@Fields varchar(300) 
AS
BEGIN
declare @MySql Varchar(2000)
	set @MySql = 'Insert INTO TMP_Search (USR_C,' + @TMPFields +') SELECT '''+ @USR_C +''',' + @Fields + 
					' FROM   Finance.AIR_LINE AS AIR_LINE Inner Join AIR_TKT On AIR_LINE.AIR_COD  = AIR_TKT.AIR_COD 
					 WHERE  AIR_TKT.TKT_NR = '+@AirCode
  print @MySql

	
	execute (@MySql)
END










