GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Finance].[SPF1GetNotActiveInvoiceRequests]
	@USR_C varchar(10)
	,@SubAcc varchar(15)	
	,@TMPFields varchar(200)  	
	,@Fields varchar(200) 
AS
BEGIN
declare @MySql Varchar(2000)
declare @OptionalSql Varchar(500)
set @OptionalSql = ''	
IF @SubAcc = ''
	set @OptionalSql =' OR @SubAcc= '''')'
Else set @OptionalSql =')'
set @MySql = '
				declare @SubAcc Varchar(15)		
				set @SubAcc = ''''
				Insert INTO TMP_Search (USR_C,' + @TMPFields +') SELECT '''+ @USR_C +''',' + @Fields + 
				' from AIR_LINE Where NOT EXISTS( SELECT INV_REP0,INV_REP1,INV_REP2,INV_REP3,INV_REP4,INV_REP5,INV_REP6,INV_REP7
											,INV_REP8,INV_REP9,INV_REPA,INV_REPB,INV_REPC,INV_REPD,INV_REPE,INV_REPF
												,INV_REPG,INV_REPH,INV_REPI,INV_REPJ,INV_REPK,INV_REPL,INV_REPM,INV_REPN,INV_REPO
												AS AIR_COD FROM INVOICE_A WHERE
												AIR_LINE.AIR_COD in(INV_REP0,INV_REP1,INV_REP2,INV_REP3,INV_REP4,INV_REP5,INV_REP6,INV_REP7
											,INV_REP8,INV_REP9,INV_REPA,INV_REPB,INV_REPC,INV_REPD,INV_REPE,INV_REPF
												,INV_REPG,INV_REPH,INV_REPI,INV_REPJ,INV_REPK,INV_REPL,INV_REPM,INV_REPN,INV_REPO)
												 ) 
								 AND  AIR_K_TYP <> 4 AND (CST_NO = '''+@SubAcc+'''' + @OptionalSql
  print @MySql

	
	execute (@MySql)
END










GO
