	-- Add the parameters for the stored procedure here
	 @MAIN_ACC Float
	, @SUB_ACC Float =null
	, @FROM_DATE datetime
	, @TO_DATE datetime
	,@MyYear int
	
	
AS
BEGIN

--	DECLARE @str_Year  int
--	DECLARE @ACCOUNTING_MONTH  int
--	DECLARE @FMyFrom_Date datetime
	DECLARE @MyBalPeriod float
	DECLARE @mybalPDr float
	DECLARE @mybalPCr float
	DECLARE @GETBal float

--	SET @str_Year = Year(@FROM_DATE)
	set @MyBalPeriod=0
	set @mybalPDr=0
	set @mybalPCr=0
	set @GETBal=0
	print @MyYear
	print @FROM_DATE
	print @TO_DATE
	print @MAIN_ACC
	print @SUB_ACC

   -- Insert statements for procedure here
	
	if @SUB_ACC is null 
		begin
		print @SUB_ACC
		print 'na'
			set @MyBalPeriod=isnull((SELECT SUM((isnull(ENT_DR,0) - isnull(ENT_CR,0))) 
					 FROM ENTRY 
						 INNER JOIN JOURNAL ON 
						 ENTRY.JRN_ID = JOURNAL.JRN_ID 
					 WHERE JRN_DATE between @FROM_DATE and @TO_DATE
						 AND Acc_Nu = @MAIN_ACC ),0)

			set @mybalPDr =isnull(( SELECT (STR_BAL)
						   FROM STR_BAL Where Acc_Nu =  @MAIN_ACC 
						   and STR_YEAR = @MyYear and  STR_TYP=1),0)

			set @mybalPCr =isnull(( SELECT (STR_BAL)
						   FROM STR_BAL Where Acc_Nu =  @MAIN_ACC 
						   and STR_YEAR = @MyYear and  STR_TYP=2),0)

			set @GETBal =round((@mybalPDr-@mybalPCr+@MyBalPeriod),2)


		end
	else
		begin
			set @MyBalPeriod=isnull((SELECT SUM((isnull(ENT_DR,0) - isnull(ENT_CR,0))) 
					 FROM ENTRY 
						 INNER JOIN JOURNAL ON 
						 ENTRY.JRN_ID = JOURNAL.JRN_ID 
					 WHERE JRN_DATE between @FROM_DATE and @TO_DATE
						 AND Acc_Nu = @MAIN_ACC
						 and SUB_NU = @SUB_ACC ),0)

			set @mybalPDr =isnull(( SELECT (STR_BAL)
						   FROM STR_BAL Where Acc_Nu =  @MAIN_ACC 
						   and SUB_NU = @SUB_ACC
						   and STR_YEAR = @MyYear and  STR_TYP=1),0)

			set @mybalPCr =isnull(( SELECT (STR_BAL)
						   FROM STR_BAL Where Acc_Nu =  @MAIN_ACC 
						   and SUB_NU = @SUB_ACC
						   and STR_YEAR = @MyYear and  STR_TYP=2),0)

			set @GETBal =round((@mybalPDr-@mybalPCr+@MyBalPeriod),2)
		end

select 	@GETBal as bal
END















