CREATE procEDURE [Finance].[SPGetCashBalance] 
	-- Add the parameters for the stored procedure here
	 @cash varchar(10)
	, @date Datetime 
	,@ENTRY_10_PAY_ID int = null

AS
BEGIN
	/*DECLARE @cash VARCHAR(2)
DECLARE @date DATETIME
SET @cash='1'
SET @date='01/01/2014' */
;
DECLARE @NewDate DateTime 
set @NewDate = (select max(JRN_DATE) from ENTRY_10 where JRN_DATE <= @date and CASH_NU = @cash)
print @NewDate
print @date

IF not EXISTS (SELECT * FROM entry_10 WHERE JRN_DATE = @date and CASH_NU = @cash )
set @date=@NewDate
print @date


begin
with t as (
SELECT    
Cash.CASH_NU,Cash.CASH_NAME
, isnull((SELECT top 1 ENT_BAL   FROM  ENTRY_10 WHERE CASH_NU = @cash AND JRN_DATE = @date) ,0)AS ENT_BAL_With_Check
--,sum(ISNULL(e10.ENT_DR, 0)) AS Sum_Debit
,Sum_Debit =ISNULL((SELECT SUM(ISNULL( ENT_DR,0)) 
