FROM      CASH_NAME  as Cash

WHERE  (Cash.CASH_NU = @cash) 

Group By Cash.CASH_NU,CASH_NAME
)
select 
ENT_BAL_WITHOUT_CHECK=(CASE T.ENT_BAL_With_Check +t.Sum_Debit
						 WHEN 0 THEN 0 
						 
						 --forwored balance + (debit and check debit )-(Credit and check Credit)- Total Chech - total Advance
						 ELSE T.ENT_BAL_With_Check  + (t.Sum_Debit + t.sum_Debit_CHeck )- (t.sum_Credit  + t.sum_Credit_CHeck) - T.checkValue -t.Advance 
					 END ) 
  
 from t;
 end

END














