CREATE procEDURE [Finance].[SPGETINVOICEByF5]
	@JRN_Date DateTime =null ,
	@ACC_NU int =null,
	@SUB_NU int =null,
	@CUR_NU int =null,
	@AMT_TAX int =null,--%
	@ENT_REC5 float =null,--Update
	@Mode varchar(1)-- A:Add,U:Update
AS
BEGIN
   declare @Cust_Sup varchar(1)-- 1=cust,2=supp
	declare @Rate int-- 1=cust,-1=supp
	
	declare @AMT_TAX_CUR float = null
	declare @AMT_TAX_Loc float = null
	declare @DIFF float = null	
	declare @X nvarchar(1) = '-'
	IF @Mode = 'A'
	Begin
		If SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '1' Or SUBSTRING(CONVERT(varchar(10),@ACC_NU),1,1) = '3'
		begin
			set @Cust_Sup='C'
			set @Rate=1
		end
	 else
		begin
			set @Cust_Sup='S'
			set @Rate=-1
		end
		print @Cust_Sup
		Print @JRN_Date
		print dateadd(year, -1, @JRN_Date)	
		Select	Entry_I.ENT_REC3,
		CUR_CODE.CUR_NAME,		
		Case When ENTRY_I.CUR_NU <> 1 then 
			abs(sum(case when ENTRY_I.ENT_CR = 0 OR ENTRY_I.ENT_CR IS NULL then ENTRY_I.ENT_CONV
			else ENTRY_I.ENT_CONV * -1 end))
		--max(c.Value_cr)
		else
			abs(ROUND(SUM(ISNULL(ENT_DR,0)) - SUM(ISNULL(ENT_CR,0)),2)) 
			end
			--Case When @Cust_Sup = 'C' then ROUND(SUM(ISNULL(ENT_DR,0)),2) else ROUND(SUM(ISNULL(ENT_CR,0)),2) end
		  AS VALUE ,
		(SELECT TOP (1) CUR.CUR_CONV 
				FROM  CUR INNER JOIN CUR_CODE ON CUR.CUR_NU = CUR_CODE.CUR_NU
