-- =============================================
-- Author:		<Neama Ramadan>
-- alter date: <26/05/2014>
-- Description:	<Get Opening Balance>
-- =============================================
CREATE procEDURE [Finance].[SPGetOpeningBalance]
	-- Add the parameters for the stored procedure here
	 @MAIN_ACC Float
	, @SUB_ACC Float
	, @FROM_DATE datetime
	, @TO_DATE datetime
	,  @USR VARCHAR(10)
	, @TmpDate datetime 
	, @MyDate datetime
AS
BEGIN

	DECLARE @MyYear  int
	DECLARE @MyDay  int
	DECLARE @MyMonth  int
	SET @MyYear = Year(@FROM_DATE)
	SET @MyDay = Day(@FROM_DATE)
	SET @MyMonth = Month(@FROM_DATE)

	DECLARE @MYD varchar(2) 
	DECLARE @MYM varchar(2)
	DECLARE @MYY varchar(4)
	
	
	--DECLARE @MyDate  datetime
	--DECLARE @TmpDate  datetime
	
	DECLARE @STR_YEAR  int
	DECLARE @ACCOUNTING_MONTH int 

	DECLARE @ENT_CR float 
	DECLARE @ENT_DR float 
	set @ENT_CR = 0
	set @ENT_DR = 0

	DECLARE @STR_CR float 
	DECLARE @STR_DR float 
	set @STR_CR = 0
	set @STR_DR = 0

	DECLARE @BAL_CR float  
	DECLARE @BAL_DR float 
	set @BAL_CR = 0 
	set @BAL_DR = 0
	
	
	DECLARE @SBAL_CR float  
	DECLARE @SBAL_DR float 
	set @SBAL_CR = 0 
	set @SBAL_DR = 0

-- ******** Calculate Year ***********************************************************
	SET @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From Sys_data)
	IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		IF @MyMonth >= @ACCOUNTING_MONTH 
		BEGIN
			SET @STR_YEAR = Year(@FROM_DATE)
		END
		ELSE
			SET @STR_YEAR = Year(@FROM_DATE)- 1 
	END
	ELSE 
		SET @STR_YEAR = Year(@FROM_DATE)
-- **************************************************************************
-- ******** Calculate MONTH ***********************************************************
	IF @ACCOUNTING_MONTH = 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = Year(@FROM_DATE) 
	END
	ELSE
		SET @MYD = 1 
