-- =============================================
-- Author:		<Neama Ramadan>
-- alter date: <26/05/2014>
-- Description:	<Get Opening Balance>
-- =============================================
CREATE procEDURE [Finance].[SPGetOpeningBalanceCL]
	-- Add the parameters for the stored procedure here
	 @MAIN_ACC Float
	, @SUB_ACC Float

AS
BEGIN
	DECLARE  @FROM_DATE datetime
	DECLARE @TO_DATE datetime
	
	DECLARE @MYD varchar(2) 
	DECLARE @MYM varchar(2)
	
	DECLARE @MYDT varchar(2) 
	DECLARE @MYMT varchar(2)
	DECLARE @MYY varchar(4)
	

	DECLARE @ENT_CR float 
	DECLARE @ENT_DR float 
	set @ENT_CR = 0
	set @ENT_DR = 0

	DECLARE @STR_CR float 
	DECLARE @STR_DR float 
	set @STR_CR = 0
	set @STR_DR = 0

	DECLARE @BAL float  
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = year(GETDATE())
		set @MYMT=Month(GETDATE()) 
		set @MYDT=Day(GETDATE()) 
	
	
	SET @FROM_DATE = @MYM + '/' + @MYD +'/'+  @MYY
	SET @TO_DATE = @MYMT+ '/' + @MYDT + '/' + @MYY
	
  
set @ENT_DR = ISNULL((SELECT SUM(ENTRY.ENT_DR)/1 FROM ENTRY INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID where  ENTRY.ACC_NU=@MAIN_ACC and ((ENTRY.SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and JRN_DATE BETWEEN @FROM_DATE AND @TO_DATE  ),0)
set @ENT_CR = ISNULL((SELECT SUM(ENTRY.ENT_CR)/1 FROM ENTRY INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID where  ENTRY.ACC_NU=@MAIN_ACC and ((ENTRY.SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and JRN_DATE BETWEEN @FROM_DATE AND @TO_DATE  ),0)



