--set @ENT_CR = ISNULL((SELECT SUM(isnull(ENTRY.ENT_cr,0)) FROM ENTRY INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID where  ENTRY.ACC_NU=@MAIN_ACC and ((ENTRY.SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and JRN_DATE < @FROM_DATE and ENTRY.ENT_CR>00 and CUR_NU=@Cur_No),0)

--set @Bal_Equ =  abs(@ENT_CR_Equ - @ENT_DR_Equ)

IF @ENT_CR - @ENT_DR > 0
BEGIN
set @Bal_CR =  @ENT_CR - @ENT_DR  --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
END

IF @ENT_DR - @ENT_CR > 0
BEGIN
set @Bal_DR =  @ENT_DR - @ENT_CR  --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
END

IF @ENT_CR_Equ - @ENT_DR_Equ > 0
BEGIN
set @Bal_Equ_cR =  @ENT_CR_Equ - @ENT_DR_Equ  --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
END

IF @ENT_DR_Equ - @ENT_CR_Equ > 0
BEGIN
set @Bal_Equ_DR =  @ENT_DR_Equ - @ENT_CR_Equ  --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
END




--Select  @Bal_DR,@Bal_CR,Bal_Equ_DR as Equ_dr ,Bal_Equ_cR as Equ_cr
Select  @Bal_DR as Dr,@Bal_CR as cr,@Bal_Equ_DR as Equ_dr ,@Bal_Equ_cR as Equ_cr

