䈀开䄀䌀䌀 ⤀漀爀⠀䀀匀唀䈀开䄀䌀䌀 椀猀 渀甀氀氀⤀⤀  愀渀搀 匀吀刀开吀夀倀 㴀 ㄀ 愀渀搀  匀吀刀开夀䔀䄀刀 㴀 䀀匀吀刀开夀䔀䄀刀  ⤀Ⰰ　⤀ഀ਀
set @STR_CR = @STR_CR + ISNULL((SELECT SUM(STR_BAL)/1  from str_bal  WHERE ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and STR_TYP = 2 and STR_YEAR = @STR_YEAR ),0)


--******* UPDATE STR_DR FROM ENTRY
set @STR_DR = @STR_DR + ISNULL((SELECT SUM(ENTRY.ent_dr)/1 from ENTRY  INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID  where  ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))   AND JRN_DATE <= @TmpDate AND JRN_DATE >= @MyDate   ),0)
set @STR_CR = @STR_CR + ISNULL((SELECT SUM(ENTRY.ent_cr)/1 from ENTRY  INNER JOIN JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID  where  ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))   AND JRN_DATE <= @TmpDate AND JRN_DATE >= @MyDate   ),0)


IF @STR_CR - @STR_DR > 0
BEGIN
set @BAL_CR =  @STR_CR - @STR_DR   --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
END

IF  @STR_DR - @STR_CR > 0
BEGIN
set @BAL_DR = @STR_DR - @STR_CR   --where @ENT_CR - @ENT_DR + @STR_CR - @STR_DR > 0
END
	
	
	
--IF @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
--BEGIN
--set @SBAL_CR = @ENT_CR - @ENT_DR + @STR_DR - @STR_CR --where @ENT_DR - @ENT_CR + @STR_DR - @STR_CR > 0
--END

--IF @ENT_CR - @ENT_DR + @STR_CR - @STR_DR > 0
--BEGIN
--set @SBAL_DR = @ENT_CR - @ENT_DR + @STR_DR - @STR_CR --where @ENT_CR - @ENT_DR + @STR_CR - @STR_DR > 0
--END

	
	
	
	--Select  @BAL_DR as My_Cr , @BAL_CR as MyDr ,@BAL_DR-@BAL_CR as bal
	
	Select  @BAL_CR as My_Dr , @BAL_DR as My_Cr ,@BAL_DR-@BAL_CR as bal
			--, abs(@SBAL_CR) as SBALCR 	,  abs(@SBAL_DR) as SBALDR
	
END
















