 㴀⠀猀攀氀攀挀琀 䌀唀匀开吀伀唀刀匀 昀爀漀洀 匀夀匀开䐀䄀吀䄀   ⤀ഀ਀    ⴀⴀ猀攀氀攀挀琀 ⨀ 昀爀漀洀 匀夀匀开倀刀䜀 眀栀攀爀攀 倀刀䜀开䌀伀䐀䔀㴀✀䄀䌀䌀伀㈀㄀　　✀ഀ਀    猀攀琀 䀀䴀礀䘀氀最倀爀最㴀猀甀戀猀琀爀椀渀最⠀⠀猀攀氀攀挀琀 倀刀䜀开倀䄀刀䄀 䘀刀伀䴀 匀夀匀开倀刀䜀 圀䠀䔀刀䔀 倀刀䜀开䌀伀䐀䔀㴀✀䄀䌀䌀伀㈀㄀　　✀⤀Ⰰ㜀Ⰰ㄀⤀ഀ਀    瀀爀椀渀琀 䀀䴀礀䘀氀最倀爀最ഀ਀ऀ椀昀 䀀洀礀昀氀最瀀爀最㴀✀夀✀ഀ਀ऀ 戀攀最椀渀ഀ਀
	 insert into INTEGRITY_TMP (USR_C,JRN_TYP,JRN_DATE,JRN_NU,ENT_COST,[DES],ACC_NU,SUB_NU,FLAG)  
	 
	 SELECT @User_Name ,ENTRY_TP.JRN_TYP, JOURNAL.JRN_DATE, JOURNAL.JRN_NU,  ENTRY.ent_id , 
	 ENTRY.ENT_DES,ENTRY.ACC_NU,ENTRY.SUB_NU ,'V'   
	  FROM         ENTRY INNER JOIN
                      JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID LEFT OUTER JOIN
                      ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID LEFT OUTER JOIN
                      COST_ENT ON JOURNAL.JRN_ID = COST_ENT.JRN_ID AND ENTRY.ENT_ID = COST_ENT.ENT_ID
	  WHERE (Jrn_Date BETWEEN @FmDate AND @ToDate) AND  ((ENTRY.ACC_NU =@MyCust  )
	   Or   (left(ENTRY.ACC_NU, 2) = @MyREV)
	   Or (left(ENTRY.ACC_NU, 2) =  @MyEx)
	   )
	   AND (COST_ENT.COST_ID IS NULL)
	  
	  end
	else
	begin
	     insert into INTEGRITY_TMP (USR_C,JRN_TYP,JRN_DATE,JRN_NU,ENT_COST,[DES],ACC_NU,SUB_NU,FLAG) 
	      SELECT @User_Name,ENTRY_TP.JRN_TYP,
	       JOURNAL.JRN_DATE, JOURNAL.JRN_NU, 
	        ENTRY.ent_id , ENTRY.ENT_DES ,ENTRY.ACC_NU,ENTRY.SUB_NU ,'V'   
	        
	       FROM         ENTRY INNER JOIN
                      JOURNAL ON ENTRY.JRN_ID = JOURNAL.JRN_ID LEFT OUTER JOIN
                      ENTRY_TP ON JOURNAL.JRN_TYP = ENTRY_TP.ID LEFT OUTER JOIN
                      COST_ENT ON JOURNAL.JRN_ID = COST_ENT.JRN_ID AND ENTRY.ENT_ID = COST_ENT.ENT_ID
	        WHERE  (Jrn_Date BETWEEN @FmDate AND @ToDate) AND
					(   (left(ENTRY.ACC_NU, 2) = @MyREV)
	   Or (left(ENTRY.ACC_NU, 2) =  @MyEx))
	        AND (COST_ENT.COST_ID IS NULL)
	end


end
 
if @Type = 9
begin
	
