	insert into INTEGRITY_TMP(JRN_TYP,JRN_DATE,JRN_NU,ENT_COST,[DES],FLAG)  
	select jrn_typ,jrn_date,jrn_nu,cost_ent.cost_id, cost_ent.CST_DES,'F' 
	from  cost_ent,CostEntryHoldkey 
	where jrn_typ = CostEntryHoldkey.jrn_typ 
		and  jrn_date = CostEntryHoldkey.jrn_date 
		and  jrn_nu = CostEntryHoldkey.jrn_nu 
		and  cost_ent.cost_id=CostEntryHoldkey.cost_id 
		and  cost_ent.cost_nu=CostEntryHoldkey.cost_nu 
		AND  cost_ent.ENT_VAL=CostEntryHoldkey.ENT_VAL 
		AND  cost_ent.CST_DES=CostEntryHoldkey.CST_DES

     drop table CostEntryHoldkey
	
	--**************************************************************
	--COSTINTRYWITHOUTENTRY
	select JRN_TYP,JRN_DATE,JRN_NU,COST_id
	into CostENTRYkey 
	from	JOURNAL INNER JOIN
            ENTRY ON JOURNAL.JRN_ID = ENTRY.JRN_ID INNER JOIN
            COST_ENT ON ENTRY.ENT_ID = COST_ENT.ENT_ID
	GROUP BY JRN_TYP,JRN_DATE,JRN_NU,COST_id
	
	
	delete CostENTRYkey 
	from CostENTRYkey,[journal] 
	where CostENTRYkey.JRN_TYP=JRN_TYP 
	and CostENTRYkey.JRN_DATE=JRN_DATE 
	and CostENTRYkey.JRN_NU=JRN_NU  
	and CostENTRYkey.COST_id=COST_id

     insert into INTEGRITY_TMP(JRN_TYP,JRN_DATE,JRN_NU,ENT_COST,[DES],FLAG)   
     select jrn_typ,jrn_date,jrn_nu,ENT_COST,CST_DES,'G' 
     from  CosT_ENT,journal,CostENTRYkey 
