CREATE procEDURE [Finance].[SPPostEntry_2206]
	@ENT_REC5 INT,	
	@JRN_DATE DateTime,
	@RECIVE_FM varchar(70),    
    @CUR_NU smallint = NULL,
    @ENT_AMT float = NULL,
    @ENT_T_AMT float = NULL,
	@TAX_NAME_ACC float = NULL,
	@TAX_NAME_SUB float = NULL,
	@RECIVE_FM_ACC float = NULL,
	@RECIVE_FM_SUB float = NULL,
	@USER_CREATE uniqueidentifier = null,
	@USER_UPDATE uniqueidentifier = null,
	@Mode varchar(2) = null -- 2 Characters first = A:ADD, U:Update    second = I:Invoice,N:Normal 
AS
 
BEGIN
	Declare @Flag nvarchar(20);
	Declare @Jrn_TYPE int
	declare @JrnId bigint	
	declare @Jrn_Des varchar(100)
	declare @ENT_CONV float
	declare @Cur_Rate float
	declare @Dr float
	declare @Cr float

	Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2206'
	Select @Jrn_TYPE = ENTRY_ACC2206 From SYS_DATA

	Print @Flag

	if SUBSTRING( @Flag,2,1) = 'P' 
	begin 		
		--'delete previous
		set @JrnId= (select jrn_id from Journal where JRN_TYP=@Jrn_TYPE and JRN_DATE=@Jrn_date and JRN_NU=@ENT_REC5)
		if @JrnId<>0
		begin
			--delete from entry where JRN_ID=@JrnId
			delete from JOURNAL where JRN_ID=@JrnId
		end

		set @Jrn_Des= 'خصم ضرائب منبع من ' + @RECIVE_FM 
		set @Jrn_Des=SUBSTRING( @Jrn_Des,1,100)
		--insert in journal
		insert into journal (JRN_TYP,JRN_DATE,JRN_NU,JRN_DES ,JRN_USER,SYS_DATE,SYS_TIME)
	    values(@Jrn_TYPE,@Jrn_date, @ENT_REC5 ,@Jrn_Des,
--****	
		Case When substring(@Mode,1,1) = 'A' then @USER_CREATE else @USER_UPDATE end
		,cast(convert(varchar(10), getdate(), 110) as datetime), CONVERT(VARCHAR(5),getdate(),108))
		
		-- get id inserted in journal
		set @JrnId= (select jrn_id from Journal where JRN_TYP=@Jrn_TYPE and JRN_DATE=@Jrn_date and JRN_NU=@ENT_REC5)
		if @JrnId<>0
		begin 
			
			if substring(@Mode,2,1) <> 'I'
			Begin
				 --ent conv
				if @CUR_NU=1 
				begin
					set @ENT_CONV=0  
					set @Dr=@ENT_T_AMT 
					set @Cr=@ENT_T_AMT 
				end
			 else  
				begin
