/****** Object:  StoredProcedure [Finance].[SPPutComBetweenChars]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Finance].[SPPutComBetweenChars] 
@String VARCHAR(100),
@ReturnedResult nvarchar(200) OUT
AS
BEGIN
   DECLARE @pos INT, @result VARCHAR(100); 
   SET @result = @String; 
   SET @pos = 2 -- location where we want first space 
   WHILE @pos < LEN(@result)+1 
   BEGIN 
       SET @result = STUFF(@result, @pos, 0, ','); 
       SET @pos = @pos+2; 
   END 
   set @ReturnedResult =  @result
END








