/****** Object:  StoredProcedure [Finance].[SPSearch]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Finance].[SPSearch]
	@USR_C varchar(10)
	,@Description nvarchar(200)=null
	,@Table varchar(1000)
	,@TMPFields varchar(500)  	
	,@Fields varchar(500) 
	,@Conditions nvarchar(500) = null
	,@Group bit = 0 -- 0 not group
	
AS
BEGIN
declare @MySql Varchar(1000)
delete from TMP_Search Where USR_C = @USR_C
if @Description Is Null
Begin
	set @MySql = 'Insert INTO [Finance].TMP_Search (USR_C,' + @TMPFields +') SELECT '''+ @USR_C +''',' + @Fields + ' From ' + @Table
	if @Conditions is not null
		begin
			set @MySql = @MySql + ' where ' +  @Conditions 	
		end 
	if @Group <> 0
		begin
			set @MySql = @MySql + ' group by ' + @Fields
		end 
	execute (@MySql)
End
Else
Begin
	if @Conditions Is Not Null
		exec ('exec ' + @Description +' '+ @USR_C +' , '''+ @Conditions +''' , '''+ @TMPFields +''' , '''+ @Fields+'''') 	
	Else
	exec ('exec ' + @Description +' '+ @USR_C +' , '''+ @TMPFields +''' , '''+ @Fields+'''') 	
End
select * From TMP_Search Where USR_C = @USR_C
END







