CREATE procEDURE [Finance].[SPSplitTwoDimDelimiterString] 
	-- Add the parameters for the stored procedure here
    @StringWithDelimiter1 VARCHAR(8000),
	@StringWithDelimiter2 VARCHAR(8000),
    @Delimiter VARCHAR(8)
AS
BEGIN
    DECLARE @StartingPosition1 INT;
    DECLARE @ItemInString1 VARCHAR(8000);
	DECLARE @StartingPosition2 INT;
    DECLARE @ItemInString2 VARCHAR(8000);
    Declare @ItemTable TABLE (
	Item1 VARCHAR(8000),
	Item2 VARCHAR(8000)
	);
    

    SELECT @StartingPosition1 = 1;
    --Return if string is null or empty
    IF LEN(@StringWithDelimiter1) = 0 OR @StringWithDelimiter1 IS NULL RETURN; 
    
    WHILE @StartingPosition1 > 0
    BEGIN
        --Get starting index of delimiter .. If string
        --doesn't contain any delimiter than it will returl 0 
        SET @StartingPosition1 = CHARINDEX(@Delimiter,@StringWithDelimiter1); 
		SET @StartingPosition2 = CHARINDEX(@Delimiter,@StringWithDelimiter2); 
        
        --Get item from string        
        IF @StartingPosition1 > 0 
		Begin               
            SET @ItemInString1 = SUBSTRING(@StringWithDelimiter1,0,@StartingPosition1)
			SET @ItemInString2 = SUBSTRING(@StringWithDelimiter2,0,@StartingPosition2)
		End
        ELSE
		Begin
            SET @ItemInString1 = @StringWithDelimiter1;
			SET @ItemInString2 = @StringWithDelimiter2;
		End
        --If item isn't empty than add to return table    
        IF( LEN(@ItemInString1) > 0)
		Begin
            INSERT INTO @ItemTable(Item1,Item2) VALUES (@ItemInString1,@ItemInString2);            
		End
        
        --Remove inserted item from string
        SET @StringWithDelimiter1 = SUBSTRING(@StringWithDelimiter1,@StartingPosition1 + 
                     LEN(@Delimiter),LEN(@StringWithDelimiter1) - @StartingPosition1)
		SET @StringWithDelimiter2 = SUBSTRING(@StringWithDelimiter2,@StartingPosition2 + 
                     LEN(@Delimiter),LEN(@StringWithDelimiter2) - @StartingPosition2)
        
        --Break loop if string is empty
        IF LEN(@StringWithDelimiter1) = 0 BREAK;
    END
    select * from  @ItemTable;
END











