CREATE procEDURE [Finance].[SPTourism_CP]
 @Receipt_No int,
 @Recepit_Date Datetime,
 @CstAcc_NU real,--file
 @CstSub_Nu Real,
 @Amount float,
 @Inv_Cur_Code varchar(10),
 @BankAcc_NU real,--file
 @BankSub_Nu Real,
 @Payment  varchar(15),
 @Inv_no  varchar(10),
 @Desc  varchar(120)
AS
 
BEGIN
	DECLARE @Cur_Nu  smallint
	DECLARE @NAT_ID  int
	DECLARE @JRN_TYP_ID  int
	DECLARE @COST_DES  varchar(50)
	DECLARE @COST_ADD  varchar(50)
	DECLARE @Jrn_Nu  float
	DECLARE @JRN_DES  varchar(100)
	Declare @Flag nvarchar(20);
	Declare @JrnId bigint;
	declare @ENT_CONV float
	declare @DR float
	declare @CR float
	declare @Cur_Rate float
	Declare @EntId bigint; 
	--Tourism
	 /****** Add File In Cost If Not Found ************/
	

	 print 'strat'
	 set @Cur_Nu=(select CUR_NU  from CUR_CODE where  CUR_CODE=@Inv_Cur_Code)
	 set @JRN_TYP_ID=(select ID  from ENTRY_TP where  JRN_TYP='CP')
	
	/****** Add Entry In Journal ************/
	print 'start get Journal no'
	Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2100'
	Select @JRN_NU = (case when SUBSTRING( @Flag,5,1) = '-' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) > Year(@Recepit_Date)-1 AND JRN_TYP = @JRN_TYP_ID)
			 when SUBSTRING( @Flag,5,1) = 'M' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) = Year(@Recepit_Date) AND Month(JRN_DATE) = Month(@Recepit_Date) AND JRN_TYP = @JRN_TYP_ID)
			 else (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) = Year(@Recepit_Date) AND Month(JRN_DATE) = Month(@Recepit_Date) )
			 end)	
	if 	@JRN_NU is Null  Set @JRN_NU = 1 
	print @JRN_NU
	print 'start get Journal desc'
	
	SET @JRN_DES= substring(@desc +  ' Payment : '+ @Payment,1,120)
	
	print @JRN_DES
	print 'start insert Journal '
	insert into Journal(JRN_TYP, JRN_DATE, JRN_NU, JRN_DES, JRN_USER, SYS_DATE, SYS_TIME)
	values(@JRN_TYP_ID,@Recepit_Date,@Jrn_nu,@JRN_DES,(select UserID From CTRL where Username='Tourism')
	,convert(varchar, getdate(), 101) ,
