	 set @Emp_Code=(select EMP_CODE from Emp where EMP_NAME=@Emp_Name)
	 set @Cost_Type=(select COST_TYP  from COST_NUM where  COST_TYP=SUBSTRING(@cost_nu,1,3))
	 set @Cur_Nu=(select CUR_NU  from CUR_CODE where  CUR_CODE=@Cur_Code)
	 set @NAT_ID=(select NAT_ID  from COST_NATIONALITY where  COST_NAT=@COST_NAT)
	  select @COST_DES=SUB_NM_E , @COST_ADD=SUB_DES from SUB_ACC where  ACC_NU=@Acc_NU and SUB_NU=@Sub_Nu 
	  set @COST_SERVICE='اقامة' + @TextFileName
	 if @MyCostNu=''
