爀渀开䐀攀猀ഀ਀ऀऀऀऀऀऀ  ⤀ഀ਀ऀऀऀऀऀ䤀昀 䀀䤀渀瘀开䄀洀漀甀渀琀 㸀　 ഀ਀
						set @EntId= isnull((select isnull(Ent_id,0) from Entry where Jrn_Id=@JrnId and ACC_NU =@RevAcc_Nu and (SUB_NU=@Rev_Sub_Nu OR SUB_NU IS NULL)  and round(ent_cr,2)= case when @Cur_Nu=1 then  round(@Cr-@Tax_Amount,2) else round(@Cr-round(@Tax_Amount *@Cur_Rate ,2),2) end ),0)
					else
						set @EntId= isnull((select isnull(Ent_id,0) from Entry where Jrn_Id=@JrnId and ACC_NU =@RevAcc_Nu and (SUB_NU=@Rev_Sub_Nu OR SUB_NU IS NULL) and round(ent_dr,2)=case when @Cur_Nu=1 then  round(@Dr-@Tax_Amount,2) else round(@Dr-round(@Tax_Amount *@Cur_Rate ,2),2) end ),0)
					PRINT 'ADD COST ENT'
					print @EntId
					if @EntId<>0
					begin
						PRINT 'ADD COST ENT'
						insert into COST_ENT( ENT_ID, JRN_ID, ACC_NU, SUB_NU, ENT_REC1, ENT_REC2, COST_NU, ENT_INV, ENT_INVD, ENT_INVT, ENT_VAL, ENT_ORG, CST_DES, LIN_NO, DR_CR, CUR_NU)
						values(@EntId,@JrnId,@RevAcc_Nu,CASE WHEN @Rev_Sub_Nu=0 THEN NULL ELSE  @Rev_Sub_Nu END
								,'','',@COST_NU,cast(@InvNo as varchar(10))
								,@Inv_Date,'',ABS(ROUND((abs(@Inv_Amount)-abs(@Tax_Amount)) * @Cur_Rate,2)),round(ABS(@Inv_Amount)-abs(@Tax_Amount),2),@JRN_DES,1,CASE WHEN @Inv_Amount>0 THEN 1 ELSE 2 END ,@Cur_Nu
								)
					END

					--insert in Entry Add Cr (Line Tax)
					insert into entry ([JRN_ID],[ACC_NU],[SUB_NU],[CUR_NU],[ENT_CONV],[ENT_DR],[ENT_CR],[ENT_FLG],[ENT_REC3],[ENT_RED3],ENT_DES)
					values(@JrnId,@Tax_Acc_Nu,  CASE WHEN @Tax_Sub_Nu=0 THEN NULL ELSE  @Rev_Sub_Nu END
						   ,@Cur_Nu,case when @Cur_Nu=1 then 0 else round(@Tax_Amount,2) end,(CASE WHEN @Inv_Amount>0 THEN 0 ELSE (case when @Cur_Nu=1 then round(@Tax_Amount,2) else (round(@Tax_Amount *@Cur_Rate ,2)) end) END) ,(CASE WHEN @Inv_Amount>0 THEN
						     (case when @Cur_Nu=1 then round(@Tax_Amount,2) else (round(@Tax_Amount *@Cur_Rate ,2))  end) ELSE 0 END),(CASE WHEN @Inv_Amount>0 THEN '2' ELSE '1' END),'',@Inv_Date,@Jrn_Des
						  )
				end


	end
END
















