						  CUR_SUB_PAY, CUR_ACC_CST, CUR_SUB_CST, CUR_PRCENT, CUS_1, CUS_2, CUS_3, CUS_4, CUS_5, SUP_1, SUP_2, SUP_3, SUP_4, SUP_5, 
						  ACCOUNTING_MONTH, CUS_6, CUS_7, CUS_8, CUS_9, SUP_6, SUP_7, SUP_8, SUP_9, CUS_JOURNEY, CUS_JOURNEY_EX, CUS_JOURNEY_REV, INVOICE_YEARS, 
