	--uPDATE  ACCOUNTING_MONTH =1 If ACCOUNTING_MONTH=0
	set @sqlCommand ='UPDATE '+  @ToDataBAse +'.Finance.SYS_DATA
							SET    ACCOUNTING_MONTH  = 1
				           where ACCOUNTING_MONTH=0'
	EXEC (@sqlCommand)


