SET            '+@ToDataBAse+'.[Finance].[INV_LINE_A]. ID_INVOICE_A ='+@ToDataBAse+'.[Finance].[INVOICE_A].ID_INVOICE_A
                      
FROM         '+@ToDataBAse+'.[Finance].[INV_LINE_A] INNER JOIN
                      '+@ToDataBAse+'.[Finance].[INVOICE_A] ON 
                      '+@ToDataBAse+'.[Finance].[INV_LINE_A].INV_SER = '+@ToDataBAse+'.[Finance].[INVOICE_A].INV_SER                     
                  AND '+@ToDataBAse+'.[Finance].[INV_LINE_A].INV_DAT = '+@ToDataBAse+'.[Finance].[INVOICE_A].INV_DAT 
                  AND '+@ToDataBAse+'.Finance.INV_LINE_A.INV_TYP = '+@ToDataBAse+'.[Finance].[INVOICE_A].INV_TYP 
                  AND '+@ToDataBAse+'.[Finance].[INV_LINE_A].INV_CR_DR = '+@ToDataBAse+'.[Finance].[INVOICE_A].INV_CR_DR                    
                  WHERE '+@ToDataBAse+'.[Finance].[INV_LINE_A].INV_SER = '+@ToDataBAse+'.[Finance].[INVOICE_A].INV_SER'
	--print @sqlCommand
	EXEC (@sqlCommand) 
