-- Update   ENTRY_10_PAY_ID in ENTRY_10 from ENTRY_10_PAY
set @sqlCommand ='UPDATE '+  @ToDataBAse +'.Finance.ENTRY_10
				SET     ENTRY_10_PAY_ID = Ent_10_Pay.ENTRY_10_PAY_ID
				FROM   '+  @ToDataBAse +'.Finance.ENTRY_10_PAY as Ent_10_Pay INNER JOIN
                      '+  @ToDataBAse +'.Finance.ENTRY_10  as Ent_10  ON
                       Ent_10_Pay.CASH_NU = Ent_10.CASH_NU 
                       AND Ent_10_Pay.JRN_DATE = Ent_10.JRN_DATE 
                       AND Ent_10_Pay.ENT_REC2 = Ent_10.ENT_REC2'
	--print @sqlCommand
	EXEC (@sqlCommand) 

--///////////////////
-- Update   ENTRY_10_Rec_ID in ENTRY_10 from ENTRY_10_Rec
set @sqlCommand ='UPDATE '+  @ToDataBAse +'.Finance.ENTRY_10
				SET     ENTRY_10_REC_ID = Ent_10_rec.ENTRY_10_REC_ID
				FROM   '+  @ToDataBAse +'.Finance.ENTRY_10_REC as Ent_10_rec INNER JOIN
                      '+  @ToDataBAse +'.Finance.ENTRY_10  as Ent_10  ON
                       Ent_10_rec.CASH_NU = Ent_10.CASH_NU 
                       AND Ent_10_rec.JRN_DATE = Ent_10.JRN_DATE 
                       AND Ent_10_rec.ENT_REC1 = Ent_10.ENT_REC1'
                       
    --print @sqlCommand
	EXEC (@sqlCommand) 
