--******************************************************************************
		set @sqlCommand ='INSERT INTO '+@ToDataBAse+'.[Finance].[INVOICE_T] (
	 	[INV_NU]       ,[INV_A_DAT]      ,[INV_D_DAT]      ,[INV_DAT]      ,[ACC_NU]
      ,[SUB_NU]      ,[CTC_NAME]      ,[SAL_TAX]      ,[INV_ACCOUNTING_DEPT]
      ,[INV_OPERATION_DEPT]      ,      [INV_ATTENTION]      ,[INV_CUR]      ,[INV_ONLY]
      ,[INV_ONL1]      ,[INV_DISCOUNT]      ,[JRN_USER]      ,[SYS_DATE]      ,[SYS_TIME]    	)

SELECT 
	 [INV_NU]      ,[INV_A_DAT]      ,[INV_D_DAT]      ,[INV_DAT]      ,[ACC_NU]
      ,[SUB_NU]      ,[CTC_NAME]      ,[SAL_TAX]      ,[INV_ADD1]      ,[INV_ADD2]
      ,[INV_RE]      ,[INV_CUR]      ,[INV_ONLY]      ,[INV_ONL1]      ,[INV_DISCOUNT]
      , '+@ToDataBAse+'.Finance.CTRL.UserID as JRN_USER       ,[INV_ON],  SUBSTRING( convert(varchar, getdate(), 108),1,5) as SYS_TIME     
   
   FROM      '+@ToDataBAse+'.Finance.CTRL CROSS JOIN
                      '+@FromDataBase+'.Finance.INVOICE_T
	WHERE       ('+@ToDataBAse+'.Finance.CTRL.USERNAME = ''emp001'') '
	--print @sqlCommand
	EXEC (@sqlCommand) 
	
