----ENTRY_20
--**********************************************************************************
		 	set @sqlCommand ='INSERT INTO '+@ToDataBAse+'.[Finance].[ENTRY_20] (
	 [JRN_DATE]      ,[JRN_NU]      ,[JRN_TYP_ID]      ,[ACC_NU]      ,[ACC_NU_TRANS]
      ,[SUB_NU]      ,[CUR_NU]      ,[ENT_CUST_NAME]      ,[VECHILE_REG_NO]      ,[JRN_USER]
      ,[SYS_DATE]      ,[SYS_TIME]
	)
	
SELECT distinct
	   [JRN_DATE]      ,[JRN_NU]      ,'+@ToDataBAse+'.Finance.ENTRY_TP.ID as [JRN_TYP_ID] ,'+@FromDataBase+'.Finance.ENTRY_20.[ACC_NU]      
	   ,'+@FromDataBase+'.Finance.SYS_DATA_TRANS.ACC_NU as[ACC_NU_TRANS]
	   ,[SUB_NU]       ,[CUR_NU]   ,[ENT_CUST_NAME] ,[SUB_NM_E] as [VECHILE_REG_NO]
	  , '+@ToDataBAse+'.Finance.CTRL.UserID as JRN_USER,convert(varchar, getdate(), 101) as SYS_DATE
	  ,  SUBSTRING( convert(varchar, getdate(), 108),1,5) as SYS_TIME


