/****** Object:  StoredProcedure [Finance].[User_ChangePassword]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Finance].[User_ChangePassword]
(
@password nvarchar(128),
@userName nvarchar(255),
@applicationName nvarchar(255)
)
AS
BEGIN

	SET NOCOUNT ON;

  Update ctrl Set
  Password=@password,
  LastPasswordChangedDate=GetDate()
  Where (
  (UserName=@userName)
  And
  (ApplicationName=@applicationName)
  )

END









