/****** Object:  StoredProcedure [Finance].[User_lock]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Finance].[User_lock]
(
  @userName nvarchar(255),
  @applicationName nvarchar(255)
)
AS
BEGIN

  Update ctrl Set
  IsLockedOut=1,
  LastLockedOutDate=GetDate()
  Where
  (
  (UserName=@userName)
  And (ApplicationName = @applicationName)
  )
  
END








