CREATE procEDURE [Finance].[User_Sel]
(
  @userName nvarchar(255),
  @applicationName nvarchar(255)
)
AS
BEGIN
  Select
  UserID,
  Username, 
  Email, 
  PasswordQuestion,
  Comment, 
  IsApproved, 
  IsLockedOut, 
  CreationDate, 
  LastLoginDate,
  LastActivityDate, 
  LastPasswordChangedDate, 
  LastLockedOutDate ,
  [Password],
  IsOnLine,
  [user_name],
  [PASS1],
  [PASS_DATE1]
  ,[PASS2]
  ,[PASS_DATE2]
  ,[PASS3]
  ,[PASS_DATE3],
  PasswordDate 
  From ctrl  
  Where
  (
  (UserName=@userName)
  And (ApplicationName = @applicationName)
  )
  
END









