/****** Object:  StoredProcedure [Finance].[Users_NumberOnline]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [Finance].[Users_NumberOnline]
(
  @applicationName nvarchar(255),
  @compareDate datetime
)
AS
BEGIN

  Select Count(*) 
  From ctrl  Where
  ((LastActivityDate > @compareDate)
  AND (ApplicationName = @applicationName)
  AND (IsOnLine = 1)
  )

END











