/****** Object:  StoredProcedure [Finance].[Users_Online]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [Finance].[Users_Online]
(
  @applicationName nvarchar(255),
  @compareDate datetime
)
AS
BEGIN

  Select
  UserID,
  Username, 
  USER_NAME, 
  Email, 
  PasswordQuestion,
  Comment, 
  IsApproved, 
  IsLockedOut, 
  CreationDate, 
  LastLoginDate,
  LastActivityDate, 
  LastPasswordChangedDate, LastLockedOutDate ,
  [user_name],[PASS1]
      ,[PASS_DATE1]
      ,[PASS2]
      ,[PASS_DATE2]
      ,[PASS3]
      ,[PASS_DATE3],PasswordDate
  From ctrl  Where
  (
  (LastLoginDate >  CONVERT(DATETIME, @compareDate,102))
  AND (ApplicationName = @applicationName)
  )

END











