	end

	--AIR_Pay PREPARATIONS
	if @AIR_PAY_Details <> '' and @AIR_PAY_Details is not null
	begin
		declare @AIR_Pay_Tbl table (RowID int not null primary key identity
				,  AIR_COD int, LINE_NU int, PAY_TYP varchar(1),PAY_AMT float, PAY_DES varchar(20))
		
		insert into @AIR_Pay_Tbl exec (@AIR_PAY_Details)
		print 'exec (AIR_PAY_Details)'
		
		INSERT INTO  [AIR_PAY] ([AIR_COD], LINE_NU, PAY_TYP, PAY_AMT, PAY_DES)
		SELECT @AIR_COD ,LINE_NU, PAY_TYP, PAY_AMT, PAY_DES
		FROM @AIR_Pay_Tbl 
	end

	--AIR_SRV PREPARATIONS
	if @AIR_SRV_Details <> '' and @AIR_SRV_Details is not null
	begin
		declare @AIR_SRV_Tbl table (RowID int not null primary key identity
				,  AIR_COD int, SRV_TYP varchar(3), SRV_DES varchar(250),SRV_AMT float, SRV_COM float)
		
		insert into @AIR_SRV_Tbl exec (@AIR_SRV_Details)
		print 'exec (@AIR_SRV_Details)'
		
		INSERT INTO  [AIR_SRV] ([AIR_COD], SRV_TYP, SRV_DES, SRV_AMT, SRV_COM)
		SELECT @AIR_COD , SRV_TYP, SRV_DES, SRV_AMT, SRV_COM
		FROM @AIR_SRV_Tbl 
	end

	--***********************************************************************************
		COMMIT TRAN
		-- ReturnValue
		set @MyReturn_Nu =(select LTRIM(STR([AIR_COD], 25,0)) from Air_line Where [AIR_COD] = @AIR_COD )
		set @MyReturn_Nu='S' +@MyReturn_Nu
		select @MyReturn_Nu 
		
	--end try
	END TRY
BEGIN CATCH
	IF @@TRANCOUNT > 0
		print 'rollback'
		ROLLBACK TRAN --RollBack in case of Error
		
		insert into [SYS_ERR](  ERR_DATE, ERR_TIME, ERR_MSG, PRG_CODE)
		values( @SYS_DATE, @SYS_TIME,ERROR_MESSAGE(),'ACCO2000T')  
		SELECT '-1'  
END CATCH
	

END








