CREATE proc [Finance].[usp_AIR_POSTSelect] 
AS 
	select M.ACC_NM_E,M.ACC_NM_A,* from AIR_POST as P
	join MAIN_ACC as M
	on M.ACC_NU=P.Acc_No
	--SELECT [LINE_NO], [TYPE], [FLAG], [ACC_NO], [SUB_ACC], [DB_CR], [TABLE], [FIELDS], [DEC], [JRN_TYP], [INVOICE], [INVOICE_FLAG], [AIR_BRAN] 
	--FROM   [Finance].[AIR_POST] 








