CREATE proc [Finance].[usp_AIR_POSTUpdate] 
    @LINE_NO int,
    @TYPE varchar(1),
    @FLAG varchar(1) = NULL,
    @ACC_NO int = NULL,
    @SUB_ACC varchar(6) = NULL,
    @DB_CR varchar(1) = NULL,
    @TABLE varchar(12) = NULL,
    @FIELDS varchar(80) = NULL,
    @DEC varchar(20) = NULL,
    @JRN_TYP varchar(2) = NULL,
    @INVOICE varchar(10) = NULL,
    @INVOICE_FLAG varchar(1) = NULL,
    @AIR_BRAN varchar(3) = NULL
AS 
	UPDATE [Finance].[AIR_POST]
	SET    [LINE_NO] = @LINE_NO, [TYPE] = @TYPE, [FLAG] = @FLAG, [ACC_NO] = @ACC_NO, [SUB_ACC] = @SUB_ACC, [DB_CR] = @DB_CR, [TABLE] = @TABLE, [FIELDS] = @FIELDS, [DEC] = @DEC, [JRN_TYP] = @JRN_TYP, [INVOICE] = @INVOICE, [INVOICE_FLAG] = @INVOICE_FLAG, [AIR_BRAN] = @AIR_BRAN
	WHERE  [LINE_NO] = @LINE_NO








GO
