CREATE proc [Finance].[usp_AIR_TKTUpdate] 
    @AIR_TKT_ID int,
    @AIR_COD int,
    @TKT_TYP varchar(1) = NULL,
    @TKT_NR float = NULL,
    @TKT_OR varchar(10) = NULL,
    @TKT_CAR varchar(3) = NULL,
    @TKT_FB varchar(10) = NULL,
    @TKT_PER real = NULL,
    @TKT_AMT float = NULL,
    @TKT_TOT float = NULL,
    @TKT_PASS varchar(40) = NULL,
    @TKT_BONUS float = NULL
AS 
	UPDATE [Finance].[AIR_TKT]
	SET    [AIR_COD] = @AIR_COD, [TKT_TYP] = @TKT_TYP, [TKT_NR] = @TKT_NR, [TKT_OR] = @TKT_OR, [TKT_CAR] = @TKT_CAR, [TKT_FB] = @TKT_FB, [TKT_PER] = @TKT_PER, [TKT_AMT] = @TKT_AMT, [TKT_TOT] = @TKT_TOT, [TKT_PASS] = @TKT_PASS, [TKT_BONUS] = @TKT_BONUS
	WHERE  [AIR_TKT_ID] = @AIR_TKT_ID








