CREATE proc [Finance].[usp_BDG_LINE_DetailsInsert]
@BDG_LINE_ID bigint,
@BDG_YEAR smallint,
@BDG_CODE varchar(8),
@BDG_LIN smallint,
@BDG_TYP tinyint,
@BDG_REP varchar(1),
@ROW_ORD smallint,
@BDG_TTL varchar(50),
@TTL_ALIN tinyint,
@LIN_FNTZ tinyint,
@LIN_FNTB tinyint,
@LIN_HRZ tinyint,
@BDG_EQT_ID bigint,
@BDG_EQT varchar(300),
@CELL_FM tinyint,
@CELL_LINF smallint,
@CELL_TO tinyint,
@COL_FM tinyint,
@COL_TO tinyint,
@CELL_LINT smallint,
@ROW_CRT tinyint,
@BDG_ACC_Arr nvarchar(max),
@mode char
as
begin
	BEGIN TRY
			BEGIN TRANSACTION

				if @mode = 'I'
				begin
					insert into BDG_LINE
					values
					(
						@BDG_YEAR,
						@BDG_CODE,
						@BDG_LIN,
						@BDG_TYP,
						@BDG_REP,
						@ROW_ORD,
						@BDG_TTL,
						@TTL_ALIN,
						@LIN_FNTZ,
						@LIN_FNTB,
						@LIN_HRZ
					)

					set @BDG_LINE_ID = (select max(BDG_LINE_ID) from BDG_LINE)
				end
				else
				begin
					update BDG_LINE
					set
						BDG_TYP = @BDG_TYP,
						BDG_REP = @BDG_REP,
						ROW_ORD = @ROW_ORD,
						BDG_TTL = @BDG_TTL,
						TTL_ALIN = @TTL_ALIN,
						LIN_FNTZ = @LIN_FNTZ,
						LIN_FNTB = @LIN_FNTB,
						LIN_HRZ = @LIN_HRZ
					where BDG_LINE_ID = @BDG_LINE_ID
				end

				if @BDG_TYP = '2' --Sum of Accounts
				begin
					if @BDG_ACC_Arr <> ''
					begin
						declare @BDG_ACC_Tbl table (RowID int not null primary key identity,
						BDG_ACC_ID bigint, BDG_LINE_ID bigint, BDG_YEAR smallint, BDG_CODE varchar(8),
						BDG_LIN smallint, BDG_ORD smallint, ACC_NU real, ACC_NU_C real, SUB_NU real, 
						SUB_NU_C real, BDG_TYP_Y int, BDG_TYP_N int, BDG_TBL tinyint)
	
						insert into @BDG_ACC_Tbl exec (@BDG_ACC_Arr)

						update @BDG_ACC_Tbl
						set BDG_LINE_ID = @BDG_LINE_ID

						if @mode = 'U'
						begin
							----delete old data from BDG_ACC
							delete from BDG_ACC where BDG_LINE_ID = @BDG_LINE_ID
						end

						INSERT INTO BDG_ACC
						(
							BDG_LINE_ID,
							BDG_YEAR,
							BDG_CODE,
							BDG_LIN,
							BDG_ORD,
							ACC_NU,
							ACC_NU_C,
							SUB_NU,
							SUB_NU_C,
							BDG_TYP_Y,
							BDG_TYP_N,
							BDG_TBL
						)
						SELECT
