/****** Object:  StoredProcedure [Finance].[usp_CHK_DATADelete]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_CHK_DATADelete] 
    @CHK_BOOK int
AS 
	DELETE
	FROM   [Finance].[CHK_DATA]
	WHERE  [CHK_BOOK] = @CHK_BOOK

    delete from [CHK_SER] where [CHK_BOOK] = @CHK_BOOK







GO
/****** Object:  StoredProcedure [Finance].[usp_CHK_DATAInsert]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_CHK_DATAInsert] 
    @CHK_BOOK int,
    @CHK_DATE datetime = NULL,
    @ACC_NU real = NULL,
    @SUB_NU real = NULL,
    @CHK_FM float = NULL,
    @CHK_TO float = NULL
AS 

	select @CHK_BOOK = (select  isnull(max(CHK_BOOK),0)+1 from [CHK_DATA] )

	INSERT INTO [Finance].[CHK_DATA] ([CHK_BOOK], [CHK_DATE], [ACC_NU], [SUB_NU], [CHK_FM], [CHK_TO])
	SELECT @CHK_BOOK, @CHK_DATE, @ACC_NU, @SUB_NU, @CHK_FM, @CHK_TO

	Declare @CHK_SER float 
	Declare @count bigint = @CHK_FM

while (@count <= @CHK_TO)
begin
 -- some statements
	---------- insert into Check Serial --------------------------------------------------------------------
	INSERT INTO [Finance].[CHK_SER] ([CHK_BOOK], [CHK_SER], [CHK_DATE], [ACC_NU], [SUB_NU], [CHK_IND])
	SELECT @CHK_BOOK, @count, @CHK_DATE, @ACC_NU, @SUB_NU , ''
	--------------------------------------------------------------------------------------------------------
	set @count += 1 -- basically increment by 1 day
end
  select CONVERT(VARCHAR(10), CHK_BOOK ,10)
	  from [CHK_DATA] Where CHK_BOOK = @CHK_BOOK






GO
