CREATE proc [Finance].[usp_CHK_PRINTUpdate] 
    @CHK_PRINT_ID int,
    @ACC_NU real,
    @SUB_NU real,
    @AMT_LINE float = NULL,
    @AMT_POS float = NULL,
    @DATE_LINE float = NULL,
    @DATE_POS float = NULL,
    @DES1_LINE float = NULL,
    @DES1_POS float = NULL,
    @DES2_LINE float = NULL,
    @DES2_POS float = NULL,
    @CHK_NAME_LINE float = NULL,
    @CHK_NAME_POS float = NULL,
    @CUR_LINE float = NULL,
    @CUR_POS float = NULL,
    @NAME_LINE float = NULL,
    @NAME_POS float = NULL
AS 
	UPDATE [Finance].[CHK_PRINT]
	SET    [ACC_NU] = @ACC_NU, [SUB_NU] = @SUB_NU, [AMT_LINE] = @AMT_LINE, [AMT_POS] = @AMT_POS, [DATE_LINE] = @DATE_LINE, [DATE_POS] = @DATE_POS, [DES1_LINE] = @DES1_LINE, [DES1_POS] = @DES1_POS, [DES2_LINE] = @DES2_LINE, [DES2_POS] = @DES2_POS, [CHK_NAME_LINE] = @CHK_NAME_LINE, [CHK_NAME_POS] = @CHK_NAME_POS, [CUR_LINE] = @CUR_LINE, [CUR_POS] = @CUR_POS, [NAME_LINE] = @NAME_LINE, [NAME_POS] = @NAME_POS
	WHERE  [CHK_PRINT_ID] = @CHK_PRINT_ID








GO
