CREATE proc [Finance].[usp_ENTRY_11Update] 
    @ENTRY_11_ID int,
    @CASH_NU varchar(2),
    @JRN_DATE datetime,
    @ENTRY_11_SER real,
    @ENT_11_DES varchar(90) = NULL,
    @ENT_11_AMT float = NULL,
    @ENT_11_ORG_AMT float = NULL,
    @ENT_LINE int,
    @ADV_NU int = NULL,
    @EMP_CODE varchar(10) = NULL,
    @SYS_DATE datetime = NULL,
    @SYS_TIME varchar(5) = NULL,
    @JRN_USER uniqueidentifier = NULL,
    @RECEIPT_STATUS varchar(1) = NULL,
	@ModType varchar(1) = NULL

AS 

if @ModType='D'
begin
	UPDATE [Finance].[ENTRY_11]
	SET    [RECEIPT_STATUS] = 'C'
	WHERE  [ENTRY_11_ID] = @ENTRY_11_ID

end
else
begin 
	UPDATE [Finance].[ENTRY_11]
	SET    [CASH_NU] = @CASH_NU, [JRN_DATE] = @JRN_DATE, [ENTRY_11_SER] = @ENTRY_11_SER, [ENT_11_DES] = @ENT_11_DES, [ENT_11_AMT] = @ENT_11_AMT, [ENT_11_ORG_AMT] = @ENT_11_ORG_AMT, [ENT_LINE] = @ENT_LINE, [ADV_NU] = @ADV_NU, [EMP_CODE] = @EMP_CODE, [SYS_DATE] = @SYS_DATE, [SYS_TIME] = @SYS_TIME, [JRN_USER] = @JRN_USER, [RECEIPT_STATUS] = @RECEIPT_STATUS
	WHERE  [ENTRY_11_ID] = @ENTRY_11_ID
end

-- ReturnValue
		select Replace('REC_NO='+ STR(ADV_NU)+ '-cur=' + STR(CUR_NU) + '-amount=' +  STR(ENT_11_AMT) + '-ID=' + STR(ENTRY_11_ID),' ','')		
		From ENTRY_11 Inner Join CASH_NAME On ENTRY_11.CASH_NU = CASH_NAME.CASH_NU
		Where ENTRY_11_ID = @ENTRY_11_ID







GO
