AS 

	Declare @Flag nvarchar(20);
	Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2205'


	INSERT INTO [Finance].[ENTRY_12_CHK] ([JRN_REC3], [JRN_DATE], [PAY_TO], [ENT_CR], [CUR_NU], [ENT_DES], [ACC_NU], [SUB_NU], [ACC_NU_D], [SUB_NU_D], [JRN_CHK], [ENT_REM], [DLV_DATE], [JRN_USER], [SYS_DATE], [SYS_TIME])
	SELECT
	
	
	Max(JRN_REC3)+1,
	 
	 @JRN_DATE, @PAY_TO, @ENT_CR, @CUR_NU, @ENT_DES, @ACC_NU, @SUB_NU, @ACC_NU_D, @SUB_NU_D, @JRN_CHK, @ENT_REM, @DLV_DATE, @JRN_USER, @SYS_DATE, @SYS_TIME
	From ENTRY_12_CHK

-- ReturnValue 
	 select Replace('Receipt='+ STR(JRN_REC3)+ '-cur=' + STR(CUR_NU) + '-amount=' +  STR(ENT_CR),' ','')
	 from ENTRY_12_CHK Where JRN_REC3 = (select Max(JRN_REC3) from ENTRY_12_CHK)	








