			UPDATE [Finance].[ENTRY_12_TAX]
			SET      [RECIVE_FM] = @RECIVE_FM, [ENT_AMT] = @ENT_AMT, [ENT_TAX] = @ENT_TAX, [ENT_T_AMT] = @ENT_T_AMT, [CUR_NU] = @CUR_NU, [TAX_FILE] = @TAX_FILE, [TAX_CARD] = @TAX_CARD, [TAX_NAME] = @TAX_NAME, [RECIVE_FM_ACC] = @RECIVE_FM_ACC, [RECIVE_FM_SUB] = @RECIVE_FM_SUB, [TAX_NAME_ACC] = @TAX_NAME_ACC, [TAX_NAME_SUB] = @TAX_NAME_SUB, [TAX_FLG] = @TAX_FLG, [SUPP_ADD] = @SUPP_ADD, [TAX_TYPE] = @TAX_TYPE, [USER_CREATE] = @USER_CREATE, [DATE_CREATE] = @DATE_CREATE, [TIME_CREATE] = @TIME_CREATE, [USER_UPDATE] = @USER_UPDATE, [DATE_UPDATE] = @DATE_UPDATE, [TIME_UPDATE] = @TIME_UPDATE
			WHERE  [ENT_REC5] = @ENT_REC5
		end

