CREATE proc [Finance].[usp_ENTRY_20_ROUTUpdate] 
    @ROUT_CODE int,
    @ROUT_DES varchar(100) = NULL,
    @ROUT_PRICE real = NULL,
    @DRIVER_MOTIVATION real = NULL,
    @PARKING_TCK float = NULL,
    @ROAD_TCK float = NULL
AS 
	UPDATE [Finance].[ENTRY_20_ROUT]
	SET    [ROUT_CODE] = @ROUT_CODE, [ROUT_DES] = @ROUT_DES, [ROUT_PRICE] = @ROUT_PRICE, [DRIVER_MOTIVATION] = @DRIVER_MOTIVATION, [PARKING_TCK] = @PARKING_TCK, [ROAD_TCK] = @ROAD_TCK
	WHERE  [ROUT_CODE] = @ROUT_CODE







