/****** Object:  StoredProcedure [Finance].[usp_ENTRY_20Delete]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_ENTRY_20Delete] 
    @JRN_DATE datetime,
	@JRN_NU float,
	@JRN_TYP_ID int
AS
begin 
	
	-- delete old data from ENTRY_20
	delete from ENTRY_20
	where JRN_DATE = @JRN_DATE and JRN_NU = @JRN_NU and JRN_TYP_ID = @JRN_TYP_ID

	--delete old data from JOURNAL
	delete from JOURNAL
	where JRN_DATE = @JRN_DATE and JRN_NU = @JRN_NU and JRN_TYP = @JRN_TYP_ID

	select CONVERT(VARCHAR(50), cast(@JRN_NU as bigint), 128) 
end







