		from @ENTRY_20_DETAILS_Tbl
	end
	
	

	COMMIT TRAN
	print 'SUCCESS'
	-- ReturnValue
	select 'S' + CONVERT(VARCHAR(50), cast(@JRN_NU as bigint), 128) + 'ID' + CONVERT(VARCHAR(50), cast(@Entry_20_ID as bigint), 128)
	END TRY
BEGIN CATCH
	IF @@TRANCOUNT > 0
		ROLLBACK TRAN --RollBack in case of Error
	print 'ERROR'
	--log the ERROR
	insert into [SYS_ERR](  ERR_DATE, ERR_TIME, ERR_MSG, PRG_CODE)
	values( @SYS_DATE, @SYS_TIME, ERROR_MESSAGE(),'ACCO2020')  
	select '-1'    
END CATCH
	end
