CREATE proc [Finance].[usp_ENTRY_20Update] 
    @Entry_20_ID bigint,
    @JRN_DATE datetime,
    @JRN_NU float,
    @JRN_TYP_ID int = NULL,
    @ACC_NU real = NULL,
    @ACC_NU_TRANS real = NULL,
    @SUB_NU real = NULL,
    @CUR_NU smallint = NULL,
    @ENT_CUST_NAME varchar(40) = NULL,
    @VECHILE_REG_NO varchar(30) = NULL,
    @JRN_USER uniqueidentifier = NULL,
    @SYS_DATE datetime = NULL,
    @SYS_TIME varchar(5) = NULL
AS 
	UPDATE [Finance].[ENTRY_20]
	SET    [JRN_DATE] = @JRN_DATE, [JRN_NU] = @JRN_NU, [JRN_TYP_ID] = @JRN_TYP_ID, [ACC_NU] = @ACC_NU, [ACC_NU_TRANS] = @ACC_NU_TRANS, [SUB_NU] = @SUB_NU, [CUR_NU] = @CUR_NU, [ENT_CUST_NAME] = @ENT_CUST_NAME, [VECHILE_REG_NO] = @VECHILE_REG_NO, [JRN_USER] = @JRN_USER, [SYS_DATE] = @SYS_DATE, [SYS_TIME] = @SYS_TIME
