CREATE proc [Finance].[usp_ENTRY_21Delete] 
    @JRN_DATE datetime,
	@JRN_NU float,
	@JRN_TYP_ID int
AS 
begin
	
	DELETE
	FROM   [Finance].[ENTRY_21]
	WHERE  
	JRN_DATE = @JRN_DATE
	and JRN_NU = @JRN_NU
	and JRN_TYP_ID = @JRN_TYP_ID

	DELETE 
	FROM JOURNAL
	where 
	JRN_DATE = @JRN_DATE
	and JRN_NU = @JRN_NU
	and JRN_TYP = @JRN_TYP_ID

	select CONVERT(VARCHAR(50), cast(@JRN_NU as bigint), 128)
end






GO
/****** Object:  StoredProcedure [Finance].[usp_ENTRY_21Insert]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_ENTRY_21Insert] 
    @Entry_21_ID bigint,
	@JRN_DATE datetime,
    @JRN_NU float,
    @JRN_TYP_ID int = NULL,
    @ACC_NU real = NULL,
    @SUB_NU real = NULL,
    @ENT_REC3 varchar(10) = NULL,
    @JRN_USER uniqueidentifier = NULL,
    @SYS_DATE datetime = NULL,
    @SYS_TIME varchar(5) = NULL,
	@ENTRY_21_DETAILS_Array nvarchar(max),
	@mode char
AS 
begin
if @ENTRY_21_DETAILS_Array <>''
	begin
		BEGIN TRY
	BEGIN TRANSACTION
	
	if @mode = 'I'
	begin
			--calculate JRN_NU
			set @JRN_NU = (select max(JRN_NU)+1 from ENTRY_21 where YEAR(JRN_DATE) = YEAR(@JRN_DATE) and JRN_TYP_ID = @JRN_TYP_ID)
			print @JRN_NU
			if 	@JRN_NU is Null  
				set @JRN_NU = 1 

			-- insert into ENTRY_21
			INSERT INTO [Finance].[ENTRY_21] 
			([JRN_DATE]
			, [JRN_NU]
			, [JRN_TYP_ID]
			, [ACC_NU]
			, [SUB_NU]
			, [ENT_REC3]
			, [JRN_USER]
			, [SYS_DATE]
			, [SYS_TIME])
			values( 
			@JRN_DATE
			, @JRN_NU
			, @JRN_TYP_ID
			, @ACC_NU
			, @SUB_NU
			, @ENT_REC3
			, @JRN_USER
			, @SYS_DATE
			, @SYS_TIME)
	end
	else
	begin
			UPDATE [Finance].[ENTRY_21]
			SET    
			  [ACC_NU] = @ACC_NU
			, [SUB_NU] = @SUB_NU
			, [ENT_REC3] = @ENT_REC3
			, [JRN_USER] = @JRN_USER
			, [SYS_DATE] = @SYS_DATE
			, [SYS_TIME] = @SYS_TIME
			WHERE  [Entry_21_ID] = @Entry_21_ID
	end
	

	--get Entry_20_ID
	print 'get id'
	set @Entry_21_ID = (select isnull(Entry_21_ID,0) from ENTRY_21 where JRN_DATE = @JRN_DATE and JRN_NU = CONVERT(VARCHAR(50), cast(@JRN_NU as bigint), 128) and JRN_TYP_ID = @JRN_TYP_ID)
	print @Entry_21_ID
