/****** Object:  StoredProcedure [Finance].[usp_ENTRY_B_DetailsInsert]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_ENTRY_B_DetailsInsert]
@ENTRY_B_DETAILS_Array nvarchar(max),
@fromDate datetime,
@toDate datetime,
@mode char
as
begin
	if @ENTRY_B_DETAILS_Array <> ''
	begin
		BEGIN TRY
			BEGIN TRANSACTION

				declare @ENTRY_B_Tbl table (RowID int not null primary key identity,
				JRN_TYP varchar(2), JRN_DATE datetime, JRN_NU float, ACC_NU real, 
				SUB_NU real, ENT_DR float, ENT_CR float, ENT_DES varchar(120), ENT_COST int, JRN_CHK varchar(15))
	
				insert into @ENTRY_B_Tbl exec (@ENTRY_B_DETAILS_Array)

				declare @Sub_nu_Found real, @ACC_NU REAL, @SUB_NU REAL
				declare @length int = (select count(*) from @ENTRY_B_Tbl)

				if @mode = 'U'
				begin
					----delete old data from ENTRY_B
					SELECT @ACC_NU = ACC_NU, @SUB_NU = SUB_NU FROM @ENTRY_B_Tbl WHERE RowID = 1
					delete from ENTRY_B where ACC_NU = @ACC_NU and SUB_NU = @SUB_NU
					and JRN_DATE between @fromDate and @toDate
				end

				declare @counter int = 1
				while @counter <= @length
				begin
					set @Sub_nu_Found = null
					--GET ACC_NU, SUB_NU
					SELECT @ACC_NU = ACC_NU, @SUB_NU = SUB_NU FROM @ENTRY_B_Tbl WHERE RowID = @counter
					SET @Sub_nu_Found = (SELECT SUB_NU  from SUB_ACC  where ACC_NU = @ACC_NU and  SUB_NU=@SUB_NU)
	
					INSERT INTO [Finance].[ENTRY_B] 
					(
					[JRN_TYP]
					, [JRN_DATE]
					, [JRN_NU]
					, [ACC_NU]
					, [SUB_NU]
					, [ENT_DR]
					, [ENT_CR]
					, [ENT_DES]
					, [ENT_COST]
					, [JRN_CHK]
					)
					SELECT
					   JRN_TYP
					 , JRN_DATE
					 , JRN_NU
					 , ACC_NU
					 , @Sub_nu_Found
					 , ENT_DR
					 , ENT_CR
					 , ENT_DES
					 , ENT_COST
					 , JRN_CHK
					 from @ENTRY_B_Tbl where RowID = @counter
					 		
					--INCREASE COUNTER
					set @counter = @counter + 1
				end

			COMMIT TRAN
			print 'SUCCESS'
			-- ReturnValue
			select 'S'
		END TRY
		BEGIN CATCH
			IF @@TRANCOUNT > 0
				ROLLBACK TRAN --RollBack in case of Error
			print 'ERROR'
