/****** Object:  StoredProcedure [Finance].[usp_ENTRY_COM_DetailInsert]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_ENTRY_COM_DetailInsert]
@ENTRY_COM_DETAILS_Array nvarchar(max),
@mode char
as
begin
	if @ENTRY_COM_DETAILS_Array <> ''
	begin
		BEGIN TRY
			BEGIN TRANSACTION
				declare @ENT_CODE real 				
				declare @ENTRY_COM_Tbl table (RowID int not null primary key identity,
				ENT_CODE real, ACC_NU real, SUB_ACC real, CUR_NU smallint, 
				ENT_DES varchar(120), JRN_DES varchar(40), ENT_DR float, ENT_CR float, LINE_NO int)
	
				insert into @ENTRY_COM_Tbl exec (@ENTRY_COM_DETAILS_Array)				

				declare @Sub_nu_Found real, @ACC_NU REAL, @SUB_NU REAL
				declare @length int = (select count(*) from @ENTRY_COM_Tbl)

				if @mode = 'I'
				begin
					set @ENT_CODE = (select  Max(isnull(ENT_CODE, 0)) + 1 from ENTRY_COM)
					if 	@ENT_CODE is Null  Set @ENT_CODE = 1 

					update @ENTRY_COM_Tbl set ENT_CODE = @ENT_CODE
				end
				else
				begin
					set @ENT_CODE = (select ENT_CODE from @ENTRY_COM_Tbl where RowID = 1)
					----delete old data from ENTRY_COM
					delete from ENTRY_COM 
					where ENT_CODE =  @ENT_CODE
				end

				declare @counter int = 1
				while @counter <= @length
				begin
					set @Sub_nu_Found = null
