CREATE proc [Finance].[usp_ENTRY_COMUpdate] 
    @ID int,
    @ENT_CODE real = NULL,
    @ACC_NU real = NULL,
    @SUB_ACC real = NULL,
    @CUR_NU smallint = NULL,
    @ENT_DES varchar(120) = NULL,
    @JRN_DES varchar(40) = NULL,
    @ENT_DR float = NULL,
    @ENT_CR float = NULL,
    @LINE_NO int = NULL
AS 
	UPDATE [Finance].[ENTRY_COM]
	SET    [ENT_CODE] = @ENT_CODE, [ACC_NU] = @ACC_NU, [SUB_ACC] = @SUB_ACC, [CUR_NU] = @CUR_NU, [ENT_DES] = @ENT_DES, [JRN_DES] = @JRN_DES, [ENT_DR] = @ENT_DR, [ENT_CR] = @ENT_CR, [LINE_NO] = @LINE_NO
	WHERE  [ID] = @ID








GO
