CREATE proc [Finance].[usp_FILES_EXPENSES_DISTRIBUTIONDelete] 
    @COST_TYP nvarchar(5),
	@LINE_NO INT
AS 
	DELETE
	FROM   [Finance].[FILES_EXPENSES_DISTRIBUTION]
	WHERE  [COST_TYP] = @COST_TYP
	AND [LINE_NO] = @LINE_NO







