/****** Object:  StoredProcedure [Finance].[usp_FINANCIAL_STATEMENTUpdate]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_FINANCIAL_STATEMENTUpdate] 
    @ID int,
    @CODE varchar(3),
    @ACC_NU real = NULL,
    @ACC_NAME varchar(100) = NULL,
    @LINE_NO real = NULL,
    @ACC_TYPE varchar(1) = NULL,
    @LINE_NO_GROUP real = NULL
AS 
	UPDATE [Finance].[FINANCIAL_STATEMENT]
	SET    [CODE] = @CODE, [ACC_NU] = @ACC_NU, [ACC_NAME] = @ACC_NAME, [LINE_NO] = @LINE_NO, [ACC_TYPE] = @ACC_TYPE, [LINE_NO_GROUP] = @LINE_NO_GROUP
	WHERE  [ID] = @ID








