/****** Object:  StoredProcedure [Finance].[usp_Get_Select_ServiceOrder_INVOICE_T]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_Get_Select_ServiceOrder_INVOICE_T] 
    @CUR_NU int  ,
	@FmDate Datetime ,
	@ToDate Datetime,
	@ACC_NU real ,
	@SUB_NU real ,
    @Flag varchar(1)-- G For GetInvoiceData S For SelectServicesData
AS 

if @Flag='G'
	begin
		SELECT HDR.JRN_DATE , EntRout.ROUT_DES , DTL.ENT_OPR , DTL.ENT_AMT , HDR.VECHILE_REG_NO FROM   ENTRY_20 AS HDR 
				INNER JOIN  
				ENTRY_20_DETAILS AS DTL
				ON HDR.Entry_20_ID = DTL.Entry_20_ID
				inner join ENTRY_20_ROUT EntRout
				on DTL.ROUT_CODE =EntRout.ROUT_CODE
				WHERE HDR.JRN_DATE >= @FmDate AND HDR.JRN_DATE <= @ToDate 
