   䀀䄀䌀䌀开一唀 爀攀愀氀 㴀 一唀䰀䰀Ⰰഀ਀    䀀匀唀䈀开一唀 爀攀愀氀 㴀 一唀䰀䰀Ⰰഀ਀    䀀䄀䌀䌀开一䄀䴀䔀 瘀愀爀挀栀愀爀⠀㐀　⤀ 㴀 一唀䰀䰀Ⰰഀ਀    䀀䤀一嘀开䄀䐀䐀㄀ 瘀愀爀挀栀愀爀⠀㌀　⤀ 㴀 一唀䰀䰀Ⰰഀ਀    䀀䤀一嘀开䄀䐀䐀㈀ 瘀愀爀挀栀愀爀⠀㌀　⤀ 㴀 一唀䰀䰀Ⰰഀ਀    䀀䌀伀匀吀开䘀䰀䄀䜀 瘀愀爀挀栀愀爀⠀㄀⤀ 㴀 一唀䰀䰀Ⰰഀ਀    䀀䤀一嘀开刀䔀䘀䔀刀䔀一䌀䔀 瘀愀爀挀栀愀爀⠀㌀　⤀ 㴀 一唀䰀䰀Ⰰഀ਀
    @INV_CUR smallint = NULL,
    @INV_ONLY varchar(100) = NULL,
    @INV_ONL1 varchar(100) = NULL,
    @INV_USER_CREATE uniqueidentifier = NULL,
    @INV_DATE_CREATE datetime = NULL,
    @INV_FLG tinyint = NULL,
    @INV_TYP varchar(3),
    @INV_DATE_CONFIRM datetime = NULL,
    @SUB_DES varchar(60) = NULL,
    @SUB_DES1 varchar(60) = NULL,
    @SUB_DES2 varchar(60) = NULL,
    @SUB_DES3 varchar(60) = NULL,
    @REMARKS varchar(170) = NULL
AS 	

	Declare @Flag varchar(20)
	Declare @COST_TYP nvarchar(3)
	
	select  @Flag = ISNULL(SUBSTRING(PRG_PARA,2,1),'-') from SYS_PRG Where PRG_CODE = 'INVO1200'	
	
	select  @COST_TYP = COST_TYP from  COST  where COST_NU = @COST_NU
	
	if @Flag = 'A'	
			select @INV_NU = isnull(max(INV_NU),0)+1 
				from INVOICE_B where COST_FLAG = @COST_FLAG And INV_TYP = @INV_TYP
		else
			select @INV_NU = isnull(max(INV_NU),0)+1 
				from INVOICE_B Inner Join COST ON COST.COST_NU = INVOICE_B.COST_NU  
				where INVOICE_B.COST_FLAG = @COST_FLAG And INV_TYP = @INV_TYP AND COST_TYP = @COST_TYP

	
	INSERT INTO [Finance].[INVOICE_B] ([INV_NU], [COST_NU], [COST_ARRIVAL_DATE], [COST_DEPARTURE_DATE], [INV_PAX], [INV_ISSUE_DATE], [INV_COVERING], [ACC_NU], [SUB_NU], [ACC_NAME], [INV_ADD1], [INV_ADD2], [COST_FLAG], [INV_REFERENCE], [INV_CUR], [INV_ONLY], [INV_ONL1], [INV_USER_CREATE], [INV_DATE_CREATE], [INV_FLG], [INV_TYP], [INV_DATE_CONFIRM], [SUB_DES], [SUB_DES1], [SUB_DES2], [SUB_DES3], [REMARKS])
	SELECT @INV_NU, @COST_NU, @COST_ARRIVAL_DATE, @COST_DEPARTURE_DATE, @INV_PAX, @INV_ISSUE_DATE, @INV_COVERING, @ACC_NU, @SUB_NU, @ACC_NAME, @INV_ADD1, @INV_ADD2, @COST_FLAG, @INV_REFERENCE, @INV_CUR, @INV_ONLY, @INV_ONL1, @INV_USER_CREATE, @INV_DATE_CREATE, @INV_FLG, @INV_TYP, @INV_DATE_CONFIRM, @SUB_DES, @SUB_DES1, @SUB_DES2, @SUB_DES3, @REMARKS

-- ReturnValue
 --select CHAR( @INV_NU)
	 select CONVERT(VARCHAR(10), INV_NU ,10)
	  from INVOICE_B Where INV_ID = (select Max(INV_ID) from INVOICE_B)	






GO
