CREATE proc [Finance].[usp_INVOICE_Details__AInsert]
    @ID_INVOICE_A int,
    @INV_SER float,
    @INV_BRN varchar(3) = NULL,
    @INV_DAT datetime = NULL,
    @INV_TYP varchar(1) = NULL,
    @INV_NU float = NULL,
    @INV_REP1 float = NULL,
    @INV_REP2 float = NULL,
    @INV_REP3 float = NULL,
    @INV_REP4 float = NULL,
    @INV_REP5 float = NULL,
    @INV_REP6 float = NULL,
    @INV_REP7 float = NULL,
    @INV_REP8 float = NULL,
    @INV_REP9 float = NULL,
    @INV_REP0 float = NULL,
    @INV_REPA float = NULL,
    @INV_REPB float = NULL,
    @INV_REPC float = NULL,
    @INV_REPD float = NULL,
    @INV_REPE float = NULL,
    @INV_REPF float = NULL,
    @INV_REPG float = NULL,
    @INV_REPH float = NULL,
    @INV_REPI float = NULL,
    @INV_REPJ float = NULL,
    @INV_REPK float = NULL,
    @INV_REPL float = NULL,
    @INV_REPM float = NULL,
    @INV_REPN float = NULL,
    @INV_REPO float = NULL,
    @INV_D_DAT datetime = NULL,
    @COST_NU varchar(15) = NULL,
    @AIR_LINE float = NULL,
    @SUB_NU float = NULL,
    @CTC_NAME varchar(50) = NULL,
    @CTC_TITLE varchar(50) = NULL,
    @INV_NAME varchar(60) = NULL,
    @INV_ADD1 varchar(60) = NULL,
    @INV_ADD2 varchar(60) = NULL,
    @INV_CITY varchar(60) = NULL,
    @CST_CNTRY varchar(60) = NULL,
    @INV_ONLY varchar(120) = NULL,
    @EMP_CODE varchar(10) = NULL,
    @INV_ON_DATE datetime = NULL,
    @INV_TIME varchar(5) = NULL,
    @INV_CC varchar(1) = NULL,
    @INV_CR_DR varchar(3),
    @INV_FLG tinyint = NULL,
    @INV_CUR smallint = NULL,
	@INV_LINE_A_Array nvarchar(max),
	@User_Name varchar(10)=null,
	@mode char
as
begin	
	if @INV_LINE_A_Array <> ''
	begin
		BEGIN TRY
	BEGIN TRANSACTION
	
	if @mode = 'I'
	begin
			--calculate INV_SER
			set @INV_SER = (select max(INV_SER) + 1 from INVOICE_A)			
			if 	@INV_SER is null  
				set @INV_SER = 1 
			--print @INV_NU

			--calculate INV_NU
			set @INV_NU = (select max(INV_NU) + 1 from INVOICE_A where INV_TYP = @INV_TYP)			
			if 	@INV_NU is null  
				set @INV_NU = 1 

			INSERT INTO [Finance].[INVOICE_A] 
			([INV_SER]
			, [INV_BRN]
