	delete from INV_LINE_A where ID_INVOICE_A = @ID_INVOICE_A

	declare @INV_LINE_A_Tbl table (RowID int not null primary key identity,
	INV_LINE_ID int, INV_SER float, INV_BRN varchar(3), INV_DAT datetime, INV_TYP varchar(1),
	LIN_NU smallint, INV_S varchar(70), INV_PP float, INV_TKT float, INV_CAR varchar(3), ID_INVOICE_A int
	)
	
	insert into @INV_LINE_A_Tbl exec (@INV_LINE_A_Array)

	if @ID_INVOICE_A <> 0
	begin

		INSERT INTO [Finance].[INV_LINE_A] 
		( [INV_SER]
		, [INV_BRN]
		, [INV_DAT]
		, [INV_TYP]
		, [LIN_NU]
		, [INV_S]
		, [INV_PP]
		, [INV_TKT]
		, [INV_CAR]
		, [INV_CR_DR]
		, [ID_INVOICE_A])
		SELECT 
		  @INV_SER
		, INV_BRN
		, INV_DAT
		, INV_TYP
		, LIN_NU
		, INV_S
		, INV_PP
		, INV_TKT
		, INV_CAR
		, @INV_TYP
		, @ID_INVOICE_A
		from @INV_LINE_A_Tbl

