CREATE proc [Finance].[usp_INVOICE_T_Insert]
@INV_ID int,
@INV_NU int,
@INV_A_DAT datetime,
@INV_D_DAT datetime,
@INV_DAT datetime,
@ACC_NU real,
@SUB_NU real,
@CTC_NAME varchar(40),
@SAL_TAX real,
@INV_ACCOUNTING_DEPT varchar(30),
@INV_OPERATION_DEPT varchar(30),
@INV_ATTENTION varchar(30),
@INV_CUR smallint,
@INV_ONLY varchar(100),
@INV_ONL1 varchar(100),
@INV_DISCOUNT real,
@JRN_USER uniqueidentifier,
@SYS_DATE datetime,
@SYS_TIME varchar(5),
@INV_LINE_T_Array nvarchar(max),
@mode char
as
begin	
	if @INV_LINE_T_Array <>''
	begin
		BEGIN TRY
	BEGIN TRANSACTION
	
	if @mode = 'I'
	begin
			--calculate INV_NU
			set @INV_NU = (select max(INV_NU) + 1 from INVOICE_T)			
			if 	@INV_NU is Null  
