/****** Object:  StoredProcedure [Finance].[usp_JOURNAL_ENTRYInsert]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Finance].[usp_JOURNAL_ENTRYInsert]
	@JRN_ID bigint,
	@JRN_TYP int,
    @JRN_DATE datetime,
    @JRN_NU float,
    @JRN_REC3 varchar(15) = NULL,
    @JRN_CHK varchar(15) = NULL,
    @JRN_DES varchar(100) = NULL,
    @JRN_USER uniqueidentifier = NULL,
    @SYS_DATE datetime = NULL,
    @SYS_TIME varchar(5) = NULL,
    @ATTACHMENT varchar(250) = NULL,
    @CASH_NU varchar(2) = NULL,
	@ENTRYList nvarchar(max),
	@COST_ENTList NVARCHAR(MAX),
	@mode char
as
begin
declare @MyReturnJrn_Nu  varchar(50)
BEGIN TRY

	BEGIN TRANSACTION
	if @mode = 'I'
		begin
			--DELETE OLD DATA FROM JOURNAL
			--DELETE
			--FROM   JOURNAL
			--WHERE  JRN_DATE = @JRN_DATE and JRN_NU = @JRN_NU and JRN_TYP = @JRN_TYP

			-- INSERT NEW DATA INTO JOURNAL 
			-- Get Serial Number 
			Declare @Flag varchar(20)
			-----		
			Select @Flag = PRG_PARA From SYS_PRG Where PRG_CODE = 'ACCO2100'
			Select @JRN_NU = (case when SUBSTRING( @Flag,5,1) = '-' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) > Year(@JRN_DATE)-1 AND JRN_TYP = @JRN_TYP)
						when SUBSTRING( @Flag,5,1) = 'M' then (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) = Year(@JRN_DATE) AND Month(JRN_DATE) = Month(@JRN_DATE) AND JRN_TYP = @JRN_TYP)
						else (select Max(isnull(JRN_NU,0))+1 From JOURNAL Where Year(JRN_DATE) = Year(@JRN_DATE) AND Month(JRN_DATE) = Month(@JRN_DATE) )
						end)	
			if 	@JRN_NU is Null  Set @JRN_NU = 1 
