CREATE proc [Finance].[usp_JOURNALUpdate] 
    @JRN_ID bigint,
    @JRN_TYP int,
    @JRN_DATE datetime,
    @JRN_NU float,
    @JRN_REC3 varchar(15) = NULL,
    @JRN_CHK varchar(15) = NULL,
    @JRN_DES varchar(100) = NULL,
    @JRN_USER uniqueidentifier = NULL,
    @SYS_DATE datetime = NULL,
    @SYS_TIME varchar(5) = NULL,
    @ATTACHMENT varchar(250) = NULL,
    @CASH_NU varchar(2) = NULL
AS 
	UPDATE [Finance].[JOURNAL]
	SET    [JRN_TYP] = @JRN_TYP, [JRN_DATE] = @JRN_DATE, [JRN_NU] = @JRN_NU, [JRN_REC3] = @JRN_REC3, [JRN_CHK] = @JRN_CHK, [JRN_DES] = @JRN_DES, [JRN_USER] = @JRN_USER, [SYS_DATE] = @SYS_DATE, [SYS_TIME] = @SYS_TIME, [ATTACHMENT] = @ATTACHMENT, [CASH_NU] = @CASH_NU
	WHERE  [JRN_ID] = @JRN_ID








GO
