			-- --------------------------------------------------------------------------------------------------------------------
			 print @COST_TYPE
			 print @INV_TYP
			 set @Lin_NO=0
			 DECLARE Line_cursor CURSOR FOR    SELECT   INV_POST_ID 	FROM  COST_INV_POST   where COST_TYPE=@COST_TYPE and [TRANS_TYPE]=@INV_TYP and [TRANS_TYPE]<>'N'ORDER BY INV_POST_ID
				OPEN Line_cursor  DECLARE @LineID REAL
				FETCH NEXT FROM Line_cursor INTO @LineID
				WHILE (@@FETCH_STATUS <> -1) 
				BEGIN  
					-------------------------------------
					print 'test'
					select @ACC_NU=ACC_NU,@Post_SUB_NU=SUB_ACC  ,@INVOICE_FLAG=INVOICE_FLAG ,@Post_DB_CR = DB_CR,@Post_TRANS_TYPE=TRANS_TYPE ,@Post_FIELDS=FIELDS  from COST_INV_POST where INV_POST_ID=@LineID
				   
				 --   print 'lines'
					
					--INvoice Ent_Rec3
					if @INVOICE_FLAG='1'
						begin
							set @ENT_REC3=@INV_NU
							set @ENT_RED3=@INV_ISSUE_DATE
						end 
					else
						begin
							set @ENT_REC3=''
							set @ENT_RED3='01/01/1990'
						end
					--Sub Acc
					if @Post_SUB_NU='CST'
						begin
							set @SUB_NU=@Inv_SUB_NU
							set @ENT_FLG = '1'
						end
					else
						begin
							if @Post_SUB_NU='' or @Post_SUB_NU=null
								begin
									set @SUB_NU=null
								end 
							else
							begin
								set @SUB_NU=@Post_SUB_NU
							end
							set @ENT_FLG = ''
							set @ENT_REC3 = ''
						end
						
						---DR and CR and CONV
						if ((@Post_TRANS_TYPE<>'C' and upper(@Post_DB_CR) ='D') or (@Post_TRANS_TYPE='C' and upper(@Post_DB_CR) ='C'))
							begin
								if @Post_TRANS_TYPE<>'C'
									begin
										--set @ENT_DR = 40
										set @ENT_DR = @amount * @Cur_Rate;
										set @ENT_CR = 0;
									end
								else
									begin
										--set @ENT_CR = 50
										set @ENT_CR = @amount * @Cur_Rate;
										set @ENT_DR = 0;
									end
							end
					--	----------------------------------
						else if  (@Post_TRANS_TYPE<>'C' and upper(@Post_DB_CR) ='C') or (@Post_TRANS_TYPE='C' and upper(@Post_DB_CR) ='D')
							begin
								--set @ENT_DR = 10
								
								if @Post_TRANS_TYPE<>'C'
