	DECLARE @STR_DR float 
	set @STR_CR = 0
	set @STR_DR = 0

	DECLARE @BAL_CR float  
	DECLARE @BAL_DR float 
	set @BAL_CR = 0 
	set @BAL_DR = 0
	
	
	DECLARE @SBAL_CR float  
	DECLARE @SBAL_DR float 
	set @SBAL_CR = 0 
	set @SBAL_DR = 0

-- ******** Calculate Year ***********************************************************
	SET @ACCOUNTING_MONTH = (SELECT ACCOUNTING_month From Sys_data)
	IF @ACCOUNTING_MONTH <> 1 
	BEGIN
		IF @MyMonth >= @ACCOUNTING_MONTH 
		BEGIN
			SET @STR_YEAR = Year(@FROM_DATE)
		END
		ELSE
			SET @STR_YEAR = Year(@FROM_DATE)- 1 
	END
	ELSE 
		SET @STR_YEAR = Year(@FROM_DATE)
-- **************************************************************************
-- ******** Calculate MONTH ***********************************************************
	IF @ACCOUNTING_MONTH = 1 
	BEGIN
		SET @MYD = 1 
		SET @MYM = 1 
		SET @MYY = Year(@FROM_DATE) 
	END
	ELSE
		SET @MYD = 1 
		SET @MYM = @ACCOUNTING_MONTH 
		SET @MYY = @STR_YEAR
-- **************************************************************************
	SET @MyDate = @MYM + '/' + @MYD +'/'+  @MYY
	SET @TmpDate = DATEADD(DAY , -1 ,@FROM_DATE )


   -- Insert statements for procedure here
	
	
set @ENT_DR = ISNULL((SELECT SUM(ENT_DR)/1 FROM ENTRY INNER JOIN Finance.JOURNAL ON Finance.ENTRY.JRN_ID = Finance.JOURNAL.JRN_ID where  ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and JRN_DATE BETWEEN @FROM_DATE AND @TO_DATE),0)
set @ENT_CR = ISNULL((SELECT SUM(ENT_CR)/1 FROM ENTRY INNER JOIN Finance.JOURNAL ON Finance.ENTRY.JRN_ID = Finance.JOURNAL.JRN_ID where  ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and JRN_DATE BETWEEN @FROM_DATE AND @TO_DATE),0)



set @STR_DR = @STR_DR + ISNULL((SELECT SUM(STR_BAL)/1 from str_bal  where ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and STR_TYP = 1 and  STR_YEAR = @STR_YEAR  ),0)
set @STR_CR = @STR_CR + ISNULL((SELECT SUM(STR_BAL)/1  from str_bal  WHERE ACC_NU=@MAIN_ACC and ((SUB_NU = @SUB_ACC )or(@SUB_ACC is null))  and STR_TYP = 2 and STR_YEAR = @STR_YEAR ),0)


