/****** Object:  StoredProcedure [Finance].[xxSPACCO2100T]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Finance].[xxSPACCO2100T]
	-- Add the parameters for the stored procedure here
		@FromDate datetime
		,@ToDate datetime
		,@JRN_TYP int = null
		,@JRN_NU float = null
		,@Amount float = null
		,@CheckNo varchar(15) = null 
		
AS
BEGIN
/*

declare @FromDate datetime
declare @ToDate datetime

declare @JRN_TYP varchar(50)
declare @JRN_NU int

declare @Amount int 
declare @CheckNo  varchar(15)
set @FromDate='01/01/2013'
set @ToDate='01/01/2014'

set @JRN_TYP=null
set @JRN_NU=null
set @Amount =null
set @CheckNo = null
*/

SELECT  
(SELECT CO_NAMEE FROM SYS_PARA) AS CompanyName
, convert(nvarchar(20),   j.JRN_DATE,103) as JRN_DATE
, j.JRN_NU
, j.JRN_REC3
, j.JRN_CHK
,convert(nvarchar(20),  j.SYS_DATE,103) as SYS_DATE 
, j.SYS_TIME
, j.JRN_DES
, e.ENT_ID
, e.ACC_NU
, e.SUB_NU
, e.CUR_NU
, e.ENT_REC1
, e.ENT_REC2
, e.ENT_CONV
, e.ENT_DR
, e.ENT_CR
, e.ENT_REC3
, e.ENT_DES

, etp.JRN_TYP AS TypeName
, ma.ACC_NM_A
, ma.ACC_NM_E
, sa.SUB_NM_A
, sa.SUB_NM_E
, c.Username
, cc.CUR_NAME
, cc.CUR_CODE
, J.JRN_ID
FROM Finance.JOURNAL AS j 

INNER JOIN ENTRY AS e 
ON j.JRN_ID = e.JRN_ID 

INNER JOIN ENTRY_TP AS etp 
ON j.JRN_TYP = etp.ID 

INNER JOIN MAIN_ACC AS ma 
ON e.ACC_NU = ma.ACC_NU 

left JOIN SUB_ACC AS sa 
ON e.SUB_NU = sa.SUB_NU AND e.ACC_NU = sa.ACC_NU 

INNER JOIN CTRL AS c 
ON j.JRN_USER = c.UserID

join CUR_CODE as cc 
on e.CUR_NU=cc.CUR_NU

where
					
