                         + ' ' + ISNULL(Nursing.Employee.LastNameEn, '') AS FullNameEn, ISNULL(Employee_1.FirstName, '') + ' ' + ISNULL(Employee_1.MiddleName, '') + ' ' + ISNULL(Employee_1.BeforeLastName, '') 
                         + ' ' + ISNULL(Employee_1.LastName, '') AS ToStockEmpName, ISNULL(Employee_1.FirstNameEn, '') + ' ' + ISNULL(Employee_1.MiddleNameEn, '') + ' ' + ISNULL(Employee_1.BeforeLastNameEn, '') 
