                         GeneralStores.IssueRequestdetails ON GeneralStores.IssueRequest.ID = GeneralStores.IssueRequestdetails.IssueRequestId INNER JOIN
                         GeneralStores.Items ON GeneralStores.IssueRequestdetails.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Stocks ON GeneralStores.IssueRequest.MainStockID = GeneralStores.Stocks.ID INNER JOIN
                         GeneralStores.Stocks AS Stocks_1 ON GeneralStores.IssueRequest.SubStockID = Stocks_1.ID LEFT OUTER JOIN
                         Nursing.Employee ON GeneralStores.IssueRequest.EmpRequestID = Nursing.Employee.Id LEFT OUTER JOIN
                         JCIT_MembershipDB.dbo.AspNetUsers ON Stocks_1.UserCharge = JCIT_MembershipDB.dbo.AspNetUsers.Id LEFT OUTER JOIN
