CREATE procEDURE [GeneralStores].[GetItemCostPrice](@FromDate   nvarchar(20)=null,
                                                 @ToDate     nvarchar(20)=null,
												 @FromClassificationID int=null,
												  @ToClassificationID int=null,
												  @FromItemID int=null,
												   @ToItemID int=null,

												    @FromItemType int=null,
												   @ToItemType int=null,
												      @FromStock int=null,
												   @ToStock int=null
												 )
	-- Add the parameters for the stored procedure here
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
select distinct ItemCode,ItemName,ItemNameAr,CostPrice,u.UnitName,u.UnitNameEn,it.CreatedDate 
,s.StockName,s.StockNameAr
 from GeneralStores.Items it
left outer join GeneralStores.Units u on it.UnitTemplateID=u.ID
left outer join GeneralStores.StockControl sc on sc.ItemID=it.ID
left outer join GeneralStores.Stocks s on sc.StockID=s.ID 

where (@FromItemID is null or it.id>=@FromItemID)
and (@ToItemID is null or it.id<=@ToItemID)
and (@FromClassificationID is null or it.ClassificationId>=@FromClassificationID)
and (@ToClassificationID is null or it.ClassificationId<=@ToClassificationID)

and (@FromItemType is null or it.ItemTypeID>=@FromItemType)
and (@ToItemType is null or it.ItemTypeID<=@ToItemType)


and (@FromStock is null or s.ID>=@FromStock)
and (@ToStock is null or s.ID<=@ToStock)
END



GO
