, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) > 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) ELSE 0 END AS [OldPositiveAdjustment]
, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [OldNegativeAdjustment]
,isNull(OldTransferIN.InQty,0) OldTransferINQty
--,isNull(TransferOut.InQty,0) TransferOutQty
 from GeneralStores.Items It
Left Outer join
(
--Select Purchase
select V_TStocksMov.ItemID
,Sum(isNull(V_TStocksMov.PurchQty,0)) PurchQty,'0' as OutQty,N'مشتريات' as Mtype
from V_TStocksMov 
where ISNULL(V_TStocksMov.openingBalance, 0) = 0 and (issueToDepartment is null or issueToDepartment=0) and
 (@StFrom IS NULL OR V_TStocksMov.[StockID] >= @StFrom) AND (@StTo IS NULL OR V_TStocksMov.[StockID] <= @StTo)
 and 
  (@classFrom IS NULL OR V_TStocksMov.ClassID >= @classFrom) AND (@classTo IS NULL OR V_TStocksMov.ClassID <= @classTo)
 and
((@itemFrom is null or ItemID>=@itemFrom) 
 and (@itemTo is null or ItemID<=@itemTo)) and 
(@dateFrom is null or purchDate< @dateFrom) 
group by V_TStocksMov.ItemID
) as OldPurchase on It.ID=OldPurchase.ItemID
Left Outer Join 
(
--Select V_dispenseItems
select V_dispenseItems.ItemID,Sum(isNull(V_dispenseItems.DispenseQty,0)) DispenseQty ,N'مبيعات' as Mtype

 from V_dispenseItems inner join V_itemClassification itC on itC.id=V_dispenseItems.ItemID
inner join GeneralStores.Stocks St on St.id=V_dispenseItems.StockID
where (@StFrom IS NULL OR V_dispenseItems.[StockID] >= @StFrom) AND (@StTo IS NULL OR V_dispenseItems.[StockID] <= @StTo)
 and 
  (@classFrom IS NULL OR itC.ClassID >= @classFrom) AND (@classTo IS NULL OR itC.ClassID <= @classTo)
 and
((@itemFrom is null or ItemID>=@itemFrom) 
 and (@itemTo is null or ItemID<=@itemTo)) and 
(@dateFrom is null or V_dispenseItems.CreatedDate< @dateFrom)

 group by V_dispenseItems.ItemID
)as OldDispense on It.ID=OldDispense.ItemID
Left Outer Join 
(
--Select V_ReturndispenseItems
select V_DispenseItemsReturn.ItemID,Sum(isNull(V_DispenseItemsReturn.ReturnQTY,0)) RDispenseQty ,N' مردود مبيعات' as Mtype

 from V_DispenseItemsReturn 
