/****** Object:  StoredProcedure [GeneralStores].[ItemCard_purchase]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [GeneralStores].[ItemCard_purchase]
(@dateTo datetime,@dateFrom datetime,@itemID int)
as
begin

select * from
V_ItemPurch
where ItemID=@itemID and 
(purchDate>= @dateFrom and purchDate<=@dateTo) 

end



