CREATE proc [GeneralStores].[ItemCard_ReturnPurch]
(@dateTo datetime,@dateFrom datetime,@itemID int)
as
begin

select * from
V_ReturnPurch
where ItemID=@itemID and 
(PRDate>= @dateFrom and PRDate<=@dateTo) 

end



