/****** Object:  StoredProcedure [GeneralStores].[ItemsSalesDetailed]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE proc [GeneralStores].[ItemsSalesDetailed] 
@FromDate datetime,
@Todate datetime,
@StockID int null,
@ItemID int null,
@UserId nvarchar(128)  null
as
select 
[generalstores].[IssuetoDepartment].[IssueNumber] as IssueNumber,
[generalstores].[IssuetoDepartmentReturn].[IssueReturnNumber] as IssueReturnNumber,
FORMAT([generalstores].[IssuetoDepartment].[IssueDate], 'MM-dd-yyyy') as IssueDate,
[generalstores].items.ItemCode as ItemCode,
[generalstores].items.ItemName as ItemName,
[generalstores].units.UnitName as UnitName,
[generalstores].ItemTypes.TypeName as TypeName,
[generalstores].items.IPSellingPrice as IPSellingPrice,
[generalstores].items.OPSellingPrice as OPSellingPrice
from  [generalstores].[IssuetoDepartment] left join [generalstores].[IssuetoDepartmentReturn]
on [generalstores].[IssuetoDepartment].[StockID] =  [generalstores].[IssuetoDepartmentReturn].[StockID]
left join [generalstores].Stocks
on  [generalstores].[IssuetoDepartmentReturn].[StockID] = generalstores.Stocks.ID
 left join  [generalstores].Stock_Items
on  [generalstores].Stocks.ID =  [generalstores].Stock_Items.StockID
left join  [generalstores].Items 
on [generalstores].Stock_Items.ItemID =[generalstores].items.ID 
left join [generalstores].ItemTypes 
on [generalstores].Items .ItemTypeID = [generalstores].ItemTypes.Id
left join [generalstores].Units
on  [generalstores].Items.BaseUnitID =[generalstores].Units.ID 
left join [JCIT_MembershipDB].[dbo].[AspNetUsers] as users
on [generalstores].[IssuetoDepartmentReturn].CreatedBy COLLATE SQL_Latin1_General_CP1_CI_AS=users.Id COLLATE SQL_Latin1_General_CP1_CI_AS
where 
[generalstores].[IssuetoDepartment].[IssueDate]>= convert(datetime,@FromDate,103)
and [generalstores].[IssuetoDepartment].[IssueDate] < convert(datetime,@Todate,103)
