,V_TStocksMov.ItemName,V_TStocksMov.PriceFC Value,V_TStocksMov.PurchQtyNoTConv Qty,N'مشتريات' as Mtype

from V_TStocksMov 
where (issueToDepartment is null or issueToDepartment=0) and V_TStocksMov.openingBalance=0 and 
((@Stockfrom is null or V_TStocksMov.StockID>=@Stockfrom    ) and 
(@StockTo is null or V_TStocksMov.StockID<=@StockTo    )) and
((@itemFrom is null or ItemID>=@itemFrom) 
 and (@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or purchDate>= @dateFrom) and (@dateTo is null or purchDate<=@dateTo))

UNION

--Select V_ReturnPurch (Return Purchase) in
select distinct  St.ID AS StockID,St.StockName, V_ReturnPurch.PurchaseReturnNumber,V_ReturnPurch.PRDate,
V_ReturnPurch.ItemID,ItemName,V_ReturnPurch.PriceFC Value,V_ReturnPurch.ReturnQTYNoTConv Qty,N'مردود مشتريات' as Mtype

from V_ReturnPurch inner join V_itemClassification it on it.id=V_ReturnPurch.ItemID
inner join GeneralStores.Stocks St on St.id=V_ReturnPurch.StockID
where (issueToDepartment is null or issueToDepartment=0) and ((@StockFrom is null or StockID>=@StockFrom) and
 (@StockTo is null or StockID<=@StockTo))and
((@itemFrom is null or ItemID>=@itemFrom) and 
(@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or PRDate>= @dateFrom)and 
(@dateTo is null or PRDate<=@dateTo))

union

--Select V_Transfer out
select  St.ID AS StockID,St.StockName, IssueNumber,V_Transfer.TransferDate,
ItemID,ItemName,CostPrice Value,IssueQty Qty,N'تحويلات من  ' as Mtype

from V_Transfer

inner join GeneralStores.Stocks St on St.id=V_Transfer.MainStockID
where ((@StockFrom is null or V_Transfer.MainStockID>=@StockFrom) and 
(@StockTo is null or V_Transfer.MainStockID<=@StockTo) )and
((@itemFrom is null or ItemID>=@itemFrom) and
(@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or TransferDate>= @dateFrom)
 and (@dateTo is null or TransferDate<=@dateTo))

union


--Select V_TransferCycle (Return Transfer) out
select  St.ID AS StockID,St.StockName, coalesce(IssueReturnNumber,'0')as IssueReturnNumber,V_TransferCycle.TransferDate,
ItemID,ItemName,coalesce(CostPrice,0) Value,coalesce(IssueReturnQtyNOTConv,0) Qty,N'مرتجع تحويلات من' as Mtype

from V_TransferCycle

