  SELECT
	  [StockID]
	, [StockName]
	, COALESCE(PhysiacalNO, '0') PhysiacalNO
	, adjDate
	,[ItemID]
	, ItemName
	, COALESCE(CostPrice, 0) AS [Value]
	, COALESCE(QtYDifference, 0)*-1 AS [Qty]
	, N'حرد سالب' AS [Mtype]

	
FROM
	V_PhysicalAdjastment
where QtYDifference<0 and   
((@StockFrom is null or StockID=@StockFrom) and
(@StockTo is null or StockID=@StockTo))and
((@itemFrom is null or ItemID>=@itemFrom)and 
(@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or adjDate>= @dateFrom)and 
(@dateTo is null or adjDate<=@dateTo))
 


end



