CREATE procEDURE [GeneralStores].[OpenBalanceStock] 
	-- Add the parameters for the stored procedure here
	@ID int
AS
SELECT  ST.StockName, LPOH.PONumber, It.ItemName, LPOD.Price, LPOD.Amount, LPOD.DiscountAmount, LPOD.AcceptQTY, It.ItemCode, It.BarCode
FROM GeneralStores.LocalPurchaseOrderHeader LPOH inner join GeneralStores.LocalPurchaseOrderDetails LPOD on LPOH.ID = LPOD.LPOID
     inner join GeneralStores.Stocks ST on ST.ID=LPOH.StockID inner join GeneralStores.Items It on It.ID =LPOD.ItemID 
WHERE LPOH.ID= @ID ;



