CREATE PROCEDURE [GeneralStores].[RepSalesDaily]
@DepartmentID int =null,
@DateFrom datetime =null,
@DateTo datetime =null
AS
select  SDpt.NameEn as DepartmentName,
RSD.Id,S.StockName,
I.ItemCode,
I.ItemName,
RSD.Quantity,
U.UnitTemplateNameEn,
I.CostPrice,
RSD.Price,
RSD.Price*RSD.Quantity as totalcostPrice,
(((select top(1) Vat  from ApplicationSetup.Setting)*RSD.Price*RSD.Quantity)/100)+RSD.Price*RSD.Quantity as totalwithdiscount 


from InPatient.RequestSuppliesHeader RSH
join Registration.Doctors D on RSH.DoctorID=D.Id 
JOIN HR.Department Dpt on Dpt.ID=d.DepartmentId
JOIN HR.SubDepartment SDpt on SDpt.DepartmentId=Dpt.ID
join InPatient.RequestSuppliesDetails RSD on RSD.RequestSuppliesHeaderID=RSH.Id
join GeneralStores.Items I on I.ID=RSD.ItemID
join GeneralStores.UnitTemplate U on I.UnitTemplateID=u.ID
join GeneralStores.Stocks S on S.ID=RSH.SubStoreID

where SDpt.ID=@DepartmentID and 
(convert(date,SDpt.CreatedDate) >= convert(date,@DateFrom) or @DateFrom is null)
and (convert(date,SDpt.CreatedDate)  <= CONVERT(date,@DateTo) or @DateTo is null)

GO
