CREATE  procEDURE [GeneralStores].[RepScrapMaster]
@ID int 
AS
BEGIN

SELECT        scrapMaster.ID, fromstock.StockName AS fromSubstoreName, fromstock.StockNameAr AS fromSubstoreNameAr, tostock.StockName AS toSubstoreName, tostock.StockName, GeneralStores.Items.ItemName AS DrugName, 
                         GeneralStores.Units.UnitName, GeneralStores.Units.UnitNameEn, GeneralStores.Batches.BatchNo, scrapDetail.ScrapQty, scrapMaster.ScrapDate, scrapMaster.Remarks, scrapMaster.ScrapNumber, 
                         GeneralStores.Batches.ExpiryDate
FROM            GeneralStores.Batches INNER JOIN
                         GeneralStores.StockBatches ON GeneralStores.Batches.Id = GeneralStores.StockBatches.BatchId RIGHT OUTER JOIN
                         GeneralStores.UnitTemplate INNER JOIN
                         GeneralStores.Units ON GeneralStores.UnitTemplate.BaseUnitID = GeneralStores.Units.ID INNER JOIN
