/****** Object:  StoredProcedure [GeneralStores].[RPT_ItemExpiryEn]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
	  create procedure [GeneralStores].[RPT_ItemExpiryEn](@FromDate   Nvarchar(20)=null,
                                                 @ToDate      Nvarchar(20)=null,
												 
												  @FromItemID int=null,
												   @ToItemID int=null,
												    @FromStock int=null,
													 @ToStock int =null
												 )
AS
select it.ItemCode,it.ItemName,s.StockName,b.ExpiryDate
,sb.AcceptedQty,GRN_D.PriceFC,
isnull(sb.AcceptedQty,0)*isnull(GRN_D.PriceFC,0) as TotBalance
  
 from GeneralStores.Items it
inner join GeneralStores.StockControl sc
on it.id=sc.ItemID
inner join GeneralStores.Stocks s
on s.id=sc.StockID
inner join GeneralStores.GoodsReceivedNoteDetails GRN_D
on GRN_D.ItemID=it.id 
inner join GeneralStores.Batches B
on B.GRNDetailsId=GRN_D.id
inner join GeneralStores.StockBatches SB on
SB.BatchId=b.Id
where (@FromDate IS NULL OR b.ExpiryDate >=CONVERT(date,@FromDate) )
      AND (@ToDate IS NULL OR b.ExpiryDate<= CONVERT(date,@ToDate) )
	  and  (@FromItemID IS NULL OR it.ID >=@FromItemID )
      AND (@ToItemID IS NULL OR it.ID >=@ToItemID )
	  and  (@FromStock IS NULL OR s.id >=@FromStock )
      AND (@ToStock IS NULL OR s.ID >=@ToStock )

GO
/****** Object:  StoredProcedure [GeneralStores].[Rpt_StockLimits_Observe]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 
CREATE proc  [GeneralStores].[Rpt_StockLimits_Observe]
 
@StockID int null,
@FromClassification int null,
@ToClassification int null,
@FromItem int null,
@ToItem int null, 
@MinQty int null,
@ReOrderQty	int null
as
select cl.Name,it.ItemName,it.ItemCode,sc.MinQuantity,sc.StockOnHand  from GeneralStores.Items It
inner join GeneralStores.StockControl SC
on  It.ID=sc.ItemID
inner join GeneralStores.Stocks S
on Sc.StockID=s.id
left outer join GeneralStores.ItemClassification Cl
on cl.Id=it.ClassificationId
where S.id=@StockID
