 (select GeneralStores.Stocks.StockName from GeneralStores.Stocks where GeneralStores.Stocks.ID=GeneralStores.IssuetoDepartment.MainStockID) as MainStockName,
(select GeneralStores.Stocks.StockName from GeneralStores.Stocks where GeneralStores.Stocks.ID=GeneralStores.IssuetoDepartment.StockID) as BranchStockName,
                         GeneralStores.IssuetoDepartmentEntry.IssueQty,
						  GeneralStores.IssuetoDepartmentEntry.Date,
						   GeneralStores.IssuetoDepartmentEntry.TotalReturnQty,
						 (select GeneralStores.Items.ItemName from GeneralStores.Items where GeneralStores.Items.ID= GeneralStores.IssuetoDepartmentEntry.ItemID) as ItemName, 
                          --GeneralStores.IssuetoDepartmentEntry.CurrentQty,
						 (GeneralStores.IssuetoDepartmentEntry.IssueQty- GeneralStores.IssuetoDepartmentEntry.TotalReturnQty) as CurrentQty,
						  GeneralStores.Units.UnitNameEn 
FROM               GeneralStores.UnitConversionFactor INNER JOIN
                         GeneralStores.Units ON GeneralStores.UnitConversionFactor.UnitID = GeneralStores.Units.ID INNER JOIN
                         GeneralStores.IssuetoDepartment INNER JOIN
                         GeneralStores.IssuetoDepartmentEntry ON GeneralStores.IssuetoDepartment.ID = GeneralStores.IssuetoDepartmentEntry.IssuetoDepartmentId INNER JOIN
                         GeneralStores.Stocks ON GeneralStores.IssuetoDepartment.StockID = GeneralStores.Stocks.ID INNER JOIN
                         GeneralStores.Items ON GeneralStores.IssuetoDepartmentEntry.ItemID = GeneralStores.Items.ID ON GeneralStores.UnitConversionFactor.ID = GeneralStores.IssuetoDepartmentEntry.UnitConversionID

						 where GeneralStores.IssuetoDepartment.ID=@ID 
END





