			where grn.Status=2 order by det.id desc) grnPending on RD.ItemID=grnPending.ItemID
inner join [GeneralStores].Items Items
on RD.ItemID = Items.id

inner join [ApplicationSetup].Service Serv
on Items.ServiceId=serv.Id
left join (select sum(StockOnHand) StockOnHand,ItemID from GeneralStores.StockControl 
inner join GeneralStores.stocks on StockControl.StockID =Stocks.ID
where stocks.IsScrap!=1
group by ItemID 
) as  st on Items.id=st.ItemID
inner join [GeneralStores].UnitTemplate tmp
on Items.UnitTemplateID=tmp.ID
inner join  [GeneralStores].UnitConversionFactor fac on tmp.id=fac.UnitTemplateID
 inner join [GeneralStores].Units unit
 on fac.UnitID=unit.id
  Left Join GeneralStores.ReOrderHistoryDetails on ReOrderHistoryDetails.ItemID=Items.ID 
  and ReOrderHistoryDetails.MasterID=@Edit 
 Left Join GeneralStores.ReOrderHistoryMaster on  ReOrderHistoryDetails.MasterID=ReOrderHistoryMaster.ID
,[GeneralStores].InventorySettings settings
where (RH.CreatedDate>=@Todate or @Todate=null)  and fac.ID=(
  select top 1 id from 
  [GeneralStores].UnitConversionFactor 
  where [GeneralStores].UnitConversionFactor.UnitTemplateID=tmp.ID
  order by ConversionValue ASC
  )
group by ReOrderHistoryDetails.ID,ReOrderHistoryDetails.ReOrderQTY,Items.ID,grnDone.PriceFC,serv.Cost,serv.price,Items.ItemName,Items.ItemCode, 
fac.ConversionValue,unit.UnitName,grnPending.AcceptQTY,slowMove,fac.ID,ReOrderHistoryMaster.purchaseReqId,grnPending.PriceFC,st.StockOnHand
order by totItemQty desc
End 
