/****** Object:  StoredProcedure [GeneralStores].[SP_GetAllPurchaseReturnInfo]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [GeneralStores].[SP_GetAllPurchaseReturnInfo] 
@PRId INT
AS
BEGIN
	SELECT
		[LocalPurchaseOrderHeader].[PONumber]
		,[PurchaseReturnHeader].ID
		, [PurchaseReturnHeader].[PurchaseReturnNumber]
		, [PurchaseReturnHeader].[ReturnDate]
		, [Stocks].[StockName]
		, [Suppliers].[SupplierName]
		, [Items].[ItemCode]
		, [Items].[ItemName]
		, [PurchaseReturnDetails].[ReturnQTY]
		, [Units].[UnitName]
		,	[PurchaseReturnDetails].Price-([PurchaseReturnDetails].discount*ReturnQTY) [Amount]
		,([PurchaseReturnDetails].Price/[PurchaseReturnDetails].ReturnQTY)-(ISNULL([PurchaseReturnDetails].discount,1)) [Price]
		,
		--, ([GoodsReceivedNoteDetails].[AmountFC] - [GoodsReceivedNoteDetails].[DiscountAmount]) / ([GoodsReceivedNoteDetails].[AcceptQTY] + [GoodsReceivedNoteDetails].[BonusQTY]) AS [Price]
		--, (([GoodsReceivedNoteDetails].[AmountFC] - [GoodsReceivedNoteDetails].[DiscountAmount]) / ([GoodsReceivedNoteDetails].[AcceptQTY] + [GoodsReceivedNoteDetails].[BonusQTY]))
		--	*
			[PurchaseReturnDetails].[ReturnQTY]
		 AS [Amount]

	 
	FROM
		[GeneralStores].[PurchaseReturnHeader]
		INNER JOIN [GeneralStores].[PurchaseReturnDetails] 
		ON [PurchaseReturnHeader].[ID] = [PurchaseReturnDetails].[PurchaseReturnHeaderId]
		INNER JOIN [GeneralStores].[Stocks] ON [PurchaseReturnHeader].[StockID] = [Stocks].[ID]
		INNER JOIN [GeneralStores].[GoodsReceivedNoteHeader] on [PurchaseReturnHeader].GrnNo = [GoodsReceivedNoteHeader].GRNNO
