CREATE proc [GeneralStores].[SP_GetSuppliers]
(
@ID int = null
)
as
SELECT [ID]
      ,[SupplierCode]
      ,[SupplierName]
      ,sp.[SupplierTypeID]
      ,[CurrencyID]
      ,[Status]
      ,[ShippingModeID]
      ,[DeliveryTermID]
      ,[DeliveryTime]
      ,[DeliveryTimeType]
      ,[CreditLimit]
      ,[CreditPeriod]
      ,[CreditPeriodType]
      ,[PaymentTime]
      ,[PaymentTimeType]
      ,[PaymentModeID]
      ,[PaymentGroupID]
      ,[PaymentTermsID]
      ,[Address1]
      ,[Address2]
      ,[Address3]
      ,[POBox]
      ,[City]
      ,[Country]
      ,[ZipCode]
      ,[Email]
      ,sp.[CreatedBy]
      ,sp.[CreatedDate]
      ,sp.[LastModifiedBy]
      ,sp.[LastModifiedDate]
      ,[MainAcc]
      ,[SubAcc]
      ,sp.[CompanyID]
	  ,SupplierTypeName
  FROM [GeneralStores].[Suppliers] sp
  join [GeneralStores].[SupplierType] st on sp.[SupplierTypeID] = st.SupplierTypeID
  where @ID is null or [ID]  = @ID



GO
/****** Object:  StoredProcedure [GeneralStores].[Sp_IssueToDepartmentReturn]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procedure [GeneralStores].[Sp_IssueToDepartmentReturn]( @id int)
as
begin
select 
St.StockName StockName,MSt.StockName MStockName, IssueNumber, IssueReturnDate,
IssueReturnNumber,IssueReturnQtyNOTConv,ItemName,(IssueQty-TotalReturnQty) as currentQty,UnitName

 from V_TransferCycle
inner join GeneralStores.Stocks St on St.ID=V_TransferCycle.StockID
inner join GeneralStores.Stocks MSt on MSt.ID=V_TransferCycle.MainStockID

where V_TransferCycle.ID=@id
end



GO
