CREATE proc [GeneralStores].[SP_ItemsList]
@StockID int null ,
@ItemTypeID int null 
as
select 
[generalstores].ItemTypes.TypeName,
[GeneralStores].Stocks.StockName,
[generalstores].Items.ItemCode,
[generalstores].Brands.BrandName,
[generalstores].Items.ItemName,
'' as Batch,
'' as expiry,
