on [generalstores].LocalPurchaseOrderHeader.StockID=[generalstores].Stocks.ID
left join  [generalstores].Items
on  [generalstores].LocalPurchaseOrderDetails.ItemID= [generalstores].Items.ID
left join [generalstores].Units
on [generalstores].Items.BaseUnitID = [generalstores].Units.ID
left join [GeneralStores].[GRN_LPOs]
on [GeneralStores].[GRN_LPOs].LPOID=[generalstores].LocalPurchaseOrderHeader.id
left join [generalstores].GoodsReceivedNoteHeader
on [GeneralStores].[GRN_LPOs].GRNID=[generalstores].GoodsReceivedNoteHeader.id
left join [generalstores].GoodsReceivedNoteDetails
on [generalstores].GoodsReceivedNoteHeader.ID=[generalstores].GoodsReceivedNoteDetails.GRNId
where ([generalstores].LocalPurchaseOrderHeader.StockID=@StockID  or @StockID  is null )
and  ([generalstores].LocalPurchaseOrderHeader.SupplierID=@SupplierID or @SupplierID is null )
and ([generalstores].Items.ID = @ItemID or @ItemID is null )
and  ([generalstores].LocalPurchaseOrderHeader.Status=@Status or @Status is null )
and [generalstores].LocalPurchaseOrderHeader.PODate >= CONVERT(datetime, @FromDate , 103)
and [generalstores].LocalPurchaseOrderHeader.PODate <=CONVERT(datetime, @ToDate , 103) 

end
if(@ISGrnOrLPO = 2)
begin
select 
[generalstores].LocalPurchaseOrderHeader.PONumber,
[generalstores].LocalPurchaseOrderHeader.PODate,
[generalstores].Suppliers.SupplierName,
[generalstores].LocalPurchaseOrderHeader.Status,
[generalstores].LocalPurchaseOrderHeader.TotalAmount,
[generalstores].Stocks.StockName,
[generalstores].Items.ItemCode,
[generalstores].Items.ItemName,
[generalstores].LocalPurchaseOrderDetails.OrderedQTY,
[generalstores].LocalPurchaseOrderDetails.BonusQuantity,
0 as AcceptQTY,
[generalstores].LocalPurchaseOrderDetails.Amount
from [generalstores].LocalPurchaseOrderHeader left join [generalstores].LocalPurchaseOrderDetails
on [generalstores].LocalPurchaseOrderHeader.ID = [generalstores].LocalPurchaseOrderDetails.LPOID
left join [generalstores].Suppliers
on [generalstores].LocalPurchaseOrderHeader.SupplierID = [generalstores].Suppliers.ID
left join [generalstores].Stocks
