CREATE proc [GeneralStores].[SP_SearchGRN]
@FromDate datetime = null,
@ToDate datetime = null,
@StockID int null,
@GetInvoicedOnly int null
as
SELECT Grn.[ID]
      ,Grn.[LPOId]
      ,[GRNNO]
      ,[GRNDate]
      ,Grn.[PaymentTermsID]
      ,[DeliveryNoteNo]
      ,[DeliveryNoteDate]
      ,[InvoiceNO]
      ,[InvoiceDate]
      ,[TotalExpensesAmount]
      ,[TotallandedAmount]
      ,[TotalGRNValueFC]
      ,[TotalGRNValueLC]
      ,[GRNPreparedDate]
      ,Grn.[Remarks]
      ,Grn.[Status]
	  ,GrnD.[AcceptQTY]
      ,GrnD.[OrderedQTY]
      ,GrnD.[BonusQTY]
      --,[PriceLC]
      --,[AmountLC]
      ,GrnD.[DiscountAmount]
      ,GrnD.[DiscountPrecint]
      ,GrnD.[PriceFC]
      --,[UnitConversionFactorId]
      ,GrnD.[AmountFC]
	  ,[ItemCode]
      ,[ItemName]
	  ,Units.UnitName
	  ,Suppliers.SupplierName
	  ,Stocks.StockName
	     ,Suppliers.TaxRegistrationNumber
	  --,[ExpenseName]
	  --,[Amount]
  FROM      GeneralStores.GoodsReceivedNoteHeader Grn
  left join GeneralStores.GoodsReceivedNoteDetails GrnD on Grn.[ID] = GrnD.[GRNId]
  
  left join GeneralStores.Items itm on grnd.[ItemID] = itm.[ID]
       join GeneralStores.LocalPurchaseOrderHeader lpo on Grn.[LPOId] = lpo.[ID]
       join GeneralStores.UnitConversionFactor UnitFo on GrnD.UnitConversionFactorId = UnitFo.ID
       join GeneralStores.Units Units on UnitFo.UnitID = Units.ID
	   join GeneralStores.GRN_LPOs on GeneralStores.GRN_LPOs.GRNID=grn.id

	   join GeneralStores.LocalPurchaseOrderHeader LopH on GeneralStores.GRN_LPOs.LPOId = LopH.ID
	   join GeneralStores.LocalPurchaseOrderDetails LopD on LopH.ID = LopD.LPOID
	   join GeneralStores.Suppliers Suppliers on Suppliers.ID = LopH.SupplierID
	   jOIN GeneralStores.Stocks Stocks ON Stocks.ID = LopH.StockID

 --left join [GeneralStores].[GoodsReceivedNoteExpenses] grne on Grn.[ID] = grne.[GRNId]
