椀渀琀㴀渀甀氀氀Ⰰഀ਀  䀀椀琀攀洀䘀爀漀洀 椀渀琀㴀渀甀氀氀Ⰰഀ਀  䀀匀琀吀漀 椀渀琀㴀渀甀氀氀Ⰰഀ਀  䀀匀琀䘀爀漀洀 椀渀琀㴀渀甀氀氀Ⰰഀ਀  䀀挀氀愀猀猀䘀爀漀洀 䤀一吀㴀一唀䰀䰀Ⰰഀ਀  䀀挀氀愀猀猀吀漀 䤀一吀 㴀一唀䰀䰀⤀ ഀ਀  愀猀ഀ਀ഀ਀ⴀⴀ䐀䔀䌀䰀䄀刀䔀 䀀搀愀琀攀吀漀 渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀㬀ഀ਀ⴀⴀ䐀䔀䌀䰀䄀刀䔀 䀀搀愀琀攀䘀爀漀洀 渀瘀愀爀挀栀愀爀⠀㈀　⤀㴀渀甀氀氀㬀ഀ਀ⴀⴀ䐀䔀䌀䰀䄀刀䔀 䀀椀琀攀洀吀漀 椀渀琀㴀渀甀氀氀㬀ഀ਀
--DECLARE @itemFrom int=null;
--DECLARE @StTo int=null;
--DECLARE @StFrom int=null;
--DECLARE @classFrom INT=NULL;
--DECLARE @classTo INT =NULL;
if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end;




WITH

	[OpenBalance] AS
	(
		SELECT
			[Items].[ID] AS [ItemID]
			, [LocalPurchaseOrderHeader].[StockID]
			, SUM(ISNULL([GoodsReceivedNoteDetails].[AcceptQTY], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [AcceptQTY]
		FROM
			[GeneralStores].[LocalPurchaseOrderHeader]
			inner join GeneralStores.GRN_LPOs on [GeneralStores].[LocalPurchaseOrderHeader].id=GeneralStores.GRN_LPOs.LPOID
			INNER JOIN [GeneralStores].[GoodsReceivedNoteHeader] ON GeneralStores.GRN_LPOs.GRNID = [GoodsReceivedNoteHeader].ID
			INNER JOIN [GeneralStores].[GoodsReceivedNoteDetails] ON [GoodsReceivedNoteHeader].[ID] = [GoodsReceivedNoteDetails].[GRNId]
			INNER JOIN [GeneralStores].[Items] ON [GoodsReceivedNoteDetails].[ItemID] = [Items].[ID]
			LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [GoodsReceivedNoteDetails].[UnitConversionFactorId] = [UnitConversionFactor].[ID]
		WHERE 
			ISNULL([GoodsReceivedNoteHeader].OpeningBalance, 0) = 1
			AND (@itemFrom IS NULL OR [Items].[ID] >= @itemFrom) AND (@itemTo IS NULL OR [Items].[ID] <= @itemTo)
			AND (@StFrom IS NULL OR [LocalPurchaseOrderHeader].[StockID] >= @StFrom) AND (@StTo IS NULL OR [LocalPurchaseOrderHeader].[StockID] <= @StTo)
			AND (@classFrom IS NULL OR [Items].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Items].[ClassificationId] <= @classTo)
			AND (@dateFrom IS NULL OR [LocalPurchaseOrderHeader].[PODate] >= @dateFrom) AND (@dateTo IS NULL OR [LocalPurchaseOrderHeader].[PODate] <= @dateTo)
		GROUP BY
			[Items].[ID]
			, [LocalPurchaseOrderHeader].[StockID]
	)
	, [Purchases] AS
	(
		SELECT
			[Items].[ID] AS [ItemID]
			, [LocalPurchaseOrderHeader].[StockID]
			, SUM((ISNULL([GoodsReceivedNoteDetails].[AcceptQTY], 0) + ISNULL([GoodsReceivedNoteDetails].[BonusQTY], 0)) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [AcceptQTY]
		FROM
			[GeneralStores].[LocalPurchaseOrderHeader]
