			--INNER JOIN [GeneralStores].[Items] ON [GoodsReceivedNoteDetails].[ItemID] = [Items].[ID]
			--LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [GoodsReceivedNoteDetails].[UnitConversionFactorId] = [UnitConversionFactor].[ID]
			--zeinab
		WHERE (issueToDepartment is null or issueToDepartment=0) and
			(@itemFrom IS NULL OR R.ItemID >= @itemFrom) AND (@itemTo IS NULL OR R.ItemID  <= @itemTo)
			AND (@StFrom IS NULL OR R.[StockID] >= @StFrom) AND (@StTo IS NULL OR R.[StockID] <= @StTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) AND (@classTo IS NULL OR it.ClassID <= @classTo)
			AND (@dateFrom IS NULL OR R.PRDate >= @dateFrom) AND (@dateTo IS NULL OR R.PRDate <= @dateTo)
			--zeinab
		GROUP BY
			R.ItemID
			, R.[StockID]
	)
	, [Sales] AS
	(
		SELECT
			V_dispenseItems.ItemID AS [ItemID]
			, V_dispenseItems.[StockID]
			, SUM(ISNULL(V_dispenseItems.DispenseQty, 0)) AS [Quantity]
		FROM
		V_dispenseItems inner join V_itemClassification it on it.id=V_dispenseItems.ItemID
			WHERE
			(@itemFrom IS NULL OR V_dispenseItems.ItemID >= @itemFrom) AND (@itemTo IS NULL OR V_dispenseItems.ItemID <= @itemTo)
			AND (@StFrom IS NULL OR V_dispenseItems.[StockID] >= @StFrom) AND (@StTo IS NULL OR V_dispenseItems.[StockID] <= @StTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) AND (@classTo IS NULL OR it.ClassID  <= @classTo)
			AND (@dateFrom IS NULL OR V_dispenseItems.CreatedDate >= @dateFrom) AND (@dateTo IS NULL OR V_dispenseItems.[CreatedDate] <= @dateTo)
		GROUP BY
			V_dispenseItems.ItemID
			, V_dispenseItems.[StockID]
	)
	, [SalesReturns] AS
	(
		SELECT
			V_DispenseItemsReturn.ItemID AS [ItemID]
			, V_DispenseItemsReturn.[StockID]
			, SUM(ISNULL(V_DispenseItemsReturn.[ReturnQty], 0)) AS [ReturnedQty]
		FROM V_DispenseItemsReturn 
