	, [DirectSubtractions] AS
	(
		SELECT 
			[Items].[ID] AS [ItemID]
			,[DirectSubstractHeader].[StockID]
			,SUM(ISNULL([DirectSubstractDetails].[QTY], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [QTY]
		FROM
			[GeneralStores].[DirectSubstractHeader]
			INNER JOIN [GeneralStores].[DirectSubstractDetails] ON [DirectSubstractHeader].[ID] = [DirectSubstractDetails].[HeaderID]
			INNER JOIN [GeneralStores].[Items] ON [DirectSubstractDetails].[ItemID] = [Items].[ID]
			LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [DirectSubstractDetails].[UnitConversionFactorId] = [UnitConversionFactor].[ID]
		WHERE
			(@itemFrom IS NULL OR [Items].[ID] >= @itemFrom) AND (@itemTo IS NULL OR [Items].[ID] <= @itemTo)
			AND (@StFrom IS NULL OR [DirectSubstractHeader].[StockID] >= @StFrom) AND (@StTo IS NULL OR [DirectSubstractHeader].[StockID] <= @StTo)
			AND (@classFrom IS NULL OR [Items].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Items].[ClassificationId] <= @classTo)
			AND (@dateFrom IS NULL OR [DirectSubstractHeader].[OperationDate] >= @dateFrom) AND (@dateTo IS NULL OR [DirectSubstractHeader].[OperationDate] <= @dateTo)
		GROUP BY
			[Items].[ID]
			,[DirectSubstractHeader].[StockID]
	)
	, [StockAdjustment] AS
	(
		SELECT
			V_PhysicalAdjastment.ItemID AS [ItemID]
			, V_PhysicalAdjastment.[StockID]
			,SUM(ISNULL(V_PhysicalAdjastment.[QtYDifference], 0)) AS [QtYDifference]
