攀洀猀崀⸀嬀䤀䐀崀 㰀㴀 䀀椀琀攀洀吀漀⤀ഀ਀ऀऀऀ䄀一䐀 ⠀䀀匀琀䘀爀漀洀 䤀匀 一唀䰀䰀 伀刀 嬀䰀漀挀愀氀倀甀爀挀栀愀猀攀伀爀搀攀爀䠀攀愀搀攀爀崀⸀嬀匀琀漀挀欀䤀䐀崀 㸀㴀 䀀匀琀䘀爀漀洀⤀ 䄀一䐀 ⠀䀀匀琀吀漀 䤀匀 一唀䰀䰀 伀刀 嬀䰀漀挀愀氀倀甀爀挀栀愀猀攀伀爀搀攀爀䠀攀愀搀攀爀崀⸀嬀匀琀漀挀欀䤀䐀崀 㰀㴀 䀀匀琀吀漀⤀ഀ਀
			AND (@classFrom IS NULL OR [Items].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Items].[ClassificationId] <= @classTo)
			AND [LocalPurchaseOrderHeader].[PODate] < @dateFrom
		GROUP BY
			[Items].[ID]
			, [LocalPurchaseOrderHeader].[StockID]
	)
	, [OldPurchasesReturns] AS
	(
		SELECT
			V_ReturnPurch.ItemID AS [ItemID]
			, V_ReturnPurch.[StockID]
			, SUM(ISNULL(V_ReturnPurch.[ReturnQTY], 0) ) AS [ReturnQTY]
		FROM

		V_ReturnPurch inner join V_itemClassification it on it.id=V_ReturnPurch.ItemID
			--[GeneralStores].[GoodsReceivedNoteDetails]
			--INNER JOIN [GeneralStores].[Batches] ON [GoodsReceivedNoteDetails].[ID] = [Batches].[GRNDetailsId]
			--INNER JOIN [GeneralStores].[StockBatches] ON [Batches].[Id] = [StockBatches].[BatchId]
			--INNER JOIN [GeneralStores].[PurchaseReturnDetails] ON [StockBatches].[Id] = [PurchaseReturnDetails].[StockBatchesId]
			--INNER JOIN [GeneralStores].[PurchaseReturnHeader] ON [PurchaseReturnDetails].[PurchaseReturnHeaderId] = [PurchaseReturnHeader].[ID]
			--INNER JOIN [GeneralStores].[Items] ON [GoodsReceivedNoteDetails].[ItemID] = [Items].[ID]
			--LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [GoodsReceivedNoteDetails].[UnitConversionFactorId] = [UnitConversionFactor].[ID]
		WHERE (issueToDepartment is null or issueToDepartment=0) and
			(@itemFrom IS NULL OR V_ReturnPurch.ItemID  >= @itemFrom) AND (@itemTo IS NULL OR V_ReturnPurch.ItemID  <= @itemTo)
			AND (@StFrom IS NULL OR [StockID] >= @StFrom) AND (@StTo IS NULL OR [StockID] <= @StTo)
			AND (@classFrom IS NULL OR ClassID >= @classFrom) AND (@classTo IS NULL OR ClassID <= @classTo)
			AND PRDate < @dateFrom
		GROUP BY
			V_ReturnPurch.ItemID
			, [StockID]
	)
	, [OldSales] AS
	(
	SELECT
			V_dispenseItems.ItemID AS [ItemID]
			, V_dispenseItems.[StockID]
			, SUM(ISNULL(V_dispenseItems.DispenseQty, 0)) AS [Quantity]
		FROM
		V_dispenseItems inner join V_itemClassification it on it.id=V_dispenseItems.ItemID
