			INNER JOIN [GeneralStores].[IssuetoDepartmentEntry] ON [IssuetoDepartment].[ID] = [IssuetoDepartmentEntry].[IssuetoDepartmentId]
			INNER JOIN [GeneralStores].[Items] ON [IssuetoDepartmentEntry].[ItemID] = [Items].[ID]
			LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [IssuetoDepartmentEntry].[UnitConversionID] = [UnitConversionFactor].[ID]
		WHERE
			(@itemFrom IS NULL OR [Items].[ID] >= @itemFrom) AND (@itemTo IS NULL OR [Items].[ID] <= @itemTo)
			AND (@StFrom IS NULL OR [IssuetoDepartment].[StockID] >= @StFrom) AND (@StTo IS NULL OR [IssuetoDepartment].[StockID] <= @StTo)
			AND (@classFrom IS NULL OR [Items].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Items].[ClassificationId] <= @classTo)
			AND [IssuetoDepartment].[IssueDate] < @dateFrom
		GROUP BY
			[IssuetoDepartment].[StockID]
			, [Items].[ID]
	)
	, [OldTransfersOut] AS
	(
		SELECT
			[IssuetoDepartment].[MainStockID] AS [StockID]
			, [Items].[ID] AS [ItemID]
			, SUM(ISNULL([IssuetoDepartmentEntry].[IssueQty], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [IssueQty]
		FROM
			[GeneralStores].[IssuetoDepartment]
			INNER JOIN [GeneralStores].[IssuetoDepartmentEntry] ON [IssuetoDepartment].[ID] = [IssuetoDepartmentEntry].[IssuetoDepartmentId]
			INNER JOIN [GeneralStores].[Items] ON [IssuetoDepartmentEntry].[ItemID] = [Items].[ID]
			LEFT OUTER JOIN [GeneralStores].[UnitConversionFactor] ON [IssuetoDepartmentEntry].[UnitConversionID] = [UnitConversionFactor].[ID]
		WHERE
			(@itemFrom IS NULL OR [Items].[ID] >= @itemFrom) AND (@itemTo IS NULL OR [Items].[ID] <= @itemTo)
			AND (@StFrom IS NULL OR [IssuetoDepartment].[MainStockID] >= @StFrom) AND (@StTo IS NULL OR [IssuetoDepartment].[MainStockID] <= @StTo)
			AND (@classFrom IS NULL OR [Items].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Items].[ClassificationId] <= @classTo)
			AND [IssuetoDepartment].[IssueDate] < @dateFrom
		GROUP BY
			[IssuetoDepartment].[MainStockID]
			, [Items].[ID]
	)
		,[OldRTransfersOut] As
	(
	SELECT 
	V_TransferCycle.[StockID] AS [StockID]
			, V_TransferCycle.[ItemID] AS [ItemID]
