			, ISNULL([SalesReturns].[ReturnedQty], 0) AS [SalesReturnsQuantity]
			, ISNULL([DirectAdditions].[QTY], 0) AS [AdditionsQuantity]
			, ISNULL([DirectSubtractions].[QTY], 0) AS [SubtractionsQuantity]
			, ISNULL([PurchasesReturns].[ReturnQTY], 0) AS [PurchasesReturnsQuantity]
			, ISNULL([TransfersIn].[IssueQty], 0) AS [TransferInQuantity]
			, ISNULL([TransfersOut].[IssueQty], 0) AS [TransferOutQuantity]
			, ISNULL([RTransfersIN].[RIssueQty], 0) AS [RTransferInQuantity]
			, ISNULL([RTransfersOut].[RIssueQty], 0) AS [RTransferOutQuantity]
			, CASE WHEN ISNULL([StockAdjustment].[QtYDifference], 0) > 0 THEN ISNULL([StockAdjustment].[QtYDifference], 0) ELSE 0 END AS [PositiveAdjustment]
			, CASE WHEN ISNULL([StockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([StockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [NegativeAdjustment]

			-- Old Items
			, ISNULL([OldPurchases].[AcceptQTY], 0) AS [OldPurchasesQuantity]
			, ISNULL([OldSales].[Quantity], 0) AS [OldSalesQuantity]
			, ISNULL([OldSalesReturns].[ReturnedQty], 0) AS [OldSalesReturnsQuantity]
			, ISNULL([OldDirectAdditions].[QTY], 0) AS [OldAdditionsQuantity]
			, ISNULL([OldDirectSubtractions].[QTY], 0) AS [OldSubtractionsQuantity]
			, ISNULL([OldPurchasesReturns].[ReturnQTY], 0) AS [OldPurchasesReturnsQuantity]
			, ISNULL([OldTransfersIn].[IssueQty], 0) AS [OldTransferInQuantity]
			, ISNULL([OldTransfersOut].[IssueQty], 0) AS [OldTransferOutQuantity]
			, ISNULL([OldRTransfersIN].[RIssueQty], 0) AS [OldRTransferInQuantity]
			, ISNULL([OldRTransfersOut].[RIssueQty], 0) AS [OldRTransferOutQuantity]
			, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) > 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) ELSE 0 END AS [OldPositiveAdjustment]
			, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [OldNegativeAdjustment]
		FROM
			[GeneralStores].[Items]
