			LEFT OUTER JOIN [OldTransfersOut] ON [Items].[ID] = [OldTransfersOut].[ItemID] AND [Stocks].[ID] = [OldTransfersOut].[StockID]
			LEFT OUTER JOIN [OldRTransfersIN] ON [Items].[ID] = [RTransfersIN].[ItemID] AND [Stocks].[ID] = [RTransfersIN].[StockID]
			LEFT OUTER JOIN [OldRTransfersOut] ON [Items].[ID] = [RTransfersOut].[ItemID] AND [Stocks].[ID] = [RTransfersOut].[StockID]

			LEFT OUTER JOIN [OldDirectAdditions] ON [Items].[ID] = [OldDirectAdditions].[ItemID] AND [Stocks].[ID] = [OldDirectAdditions].[StockID]
			LEFT OUTER JOIN [OldDirectSubtractions] ON [Items].[ID] = [OldDirectSubtractions].[ItemID] AND [Stocks].[ID] = [OldDirectSubtractions].[StockID]
			LEFT OUTER JOIN [OldStockAdjustment] ON [Items].[ID] = [OldStockAdjustment].[ItemID] AND [Stocks].[ID] = [OldStockAdjustment].[StockID]
		) AS [T]
	) AS [T]
WHERE
	(@itemFrom IS NULL OR [ItemId] >= @itemFrom)
	AND
	(@itemTo IS NULL OR [ItemId] <= @itemTo)
	AND
	(@StFrom IS NULL OR [StockId] >= @StFrom)
	AND
	(@StTo IS NULL OR [StockId] <= @StTo)
	AND
	(@classFrom IS NULL OR [ClassificationId] >= @classFrom)
	AND
	(@classTo IS NULL OR [ClassificationId] <= @classTo)
ORDER BY
	[ItemId] ASC
	, [StockId] ASC




