CREATE proc [GeneralStores].[SP_Stocks]
as
begin
select
[generalstores].[Stocks].StockName,
[ApplicationSetup].CostCenter.Name
 from [generalstores].[Stocks]
join [ApplicationSetup].CostCenter
on [generalstores].[Stocks].CostCenterCompaniesID = [ApplicationSetup].[Costcenter].Id
end





