CREATE proc [GeneralStores].[SP_StockTransferReport]
@FromDate datetime null,
@ToDate Datetime null,
@FromStock int ,
@ToStock int null
as
select 
[GeneralStores].Stocks.StockName as FromStock,
[generalStores].StockTransfer.RequestNo,
[generalStores].StockTransfer.RequestedDate,
