/****** Object:  StoredProcedure [GeneralStores].[StagnantItems]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 
CREATE proc [GeneralStores].[StagnantItems] --2,'asd' --12 --'2023-07-10','2021-07-10'

as

declare @Day int
set @Day=(select top 1 GeneralStores.InventorySettings.RecessionPeriodInDays from GeneralStores.InventorySettings)

SELECT        TOP (2000000) SUM(GeneralStores.StockControlDetail.Qty * GeneralStores.StockControlDetail.SignValue) AS Expr1, GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, GeneralStores.Stocks.StockName, 
                         CAST(MAX(GeneralStores.StockControlDetail.TransactionDate) AS date) AS LastTrans, GeneralStores.Suppliers.SupplierName, GeneralStores.Batches.BatchNo, GeneralStores.Batches.ExpiryDate
FROM            GeneralStores.StockControlDetail INNER JOIN
                         GeneralStores.StockControl ON GeneralStores.StockControlDetail.StockControlID = GeneralStores.StockControl.ID INNER JOIN
                         GeneralStores.Items ON GeneralStores.StockControl.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Stocks ON GeneralStores.StockControl.StockID = GeneralStores.Stocks.ID INNER JOIN
                         GeneralStores.GoodsReceivedNoteDetails ON GeneralStores.StockControlDetail.GRNDetailID = GeneralStores.GoodsReceivedNoteDetails.ID INNER JOIN
                         GeneralStores.GoodsReceivedNoteHeader ON GeneralStores.Stocks.ID = GeneralStores.GoodsReceivedNoteHeader.StockID AND 
                         GeneralStores.GoodsReceivedNoteDetails.GRNId = GeneralStores.GoodsReceivedNoteHeader.ID INNER JOIN
                         GeneralStores.Suppliers ON GeneralStores.GoodsReceivedNoteHeader.SupplierID = GeneralStores.Suppliers.ID LEFT OUTER JOIN
                         GeneralStores.Batches ON GeneralStores.GoodsReceivedNoteDetails.ID = GeneralStores.Batches.GRNDetailsId
