Create proc [GeneralStores].[StagnantItemsNe] --2,'asd' --12 --'2023-07-10','2021-07-10'
as
declare @ExpDay int
set @ExpDay=(select top 1 GeneralStores.InventorySettings.ExpiaryPeriodDays from  GeneralStores.InventorySettings)


SELECT        TOP (2000000) SUM(GeneralStores.StockControlDetail.Qty * GeneralStores.StockControlDetail.SignValue) AS Expr1, GeneralStores.Items.ItemCode, GeneralStores.Items.ItemName, GeneralStores.Stocks.StockName, 
                         CAST(MAX(GeneralStores.StockControlDetail.TransactionDate) AS date) AS LastTrans, GeneralStores.Suppliers.SupplierName, GeneralStores.Batches.BatchNo, GeneralStores.Batches.ExpiryDate
FROM            GeneralStores.StockControlDetail INNER JOIN
                         GeneralStores.StockControl ON GeneralStores.StockControlDetail.StockControlID = GeneralStores.StockControl.ID INNER JOIN
                         GeneralStores.Items ON GeneralStores.StockControl.ItemID = GeneralStores.Items.ID INNER JOIN
                         GeneralStores.Stocks ON GeneralStores.StockControl.StockID = GeneralStores.Stocks.ID INNER JOIN
                         GeneralStores.GoodsReceivedNoteDetails ON GeneralStores.StockControlDetail.GRNDetailID = GeneralStores.GoodsReceivedNoteDetails.ID INNER JOIN
                         GeneralStores.GoodsReceivedNoteHeader ON GeneralStores.Stocks.ID = GeneralStores.GoodsReceivedNoteHeader.StockID AND 
                         GeneralStores.GoodsReceivedNoteDetails.GRNId = GeneralStores.GoodsReceivedNoteHeader.ID INNER JOIN
ਊ                         䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀甀瀀瀀氀椀攀爀猀 伀一 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䜀漀漀搀猀刀攀挀攀椀瘀攀搀一漀琀攀䠀攀愀搀攀爀⸀匀甀瀀瀀氀椀攀爀䤀䐀 㴀 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀甀瀀瀀氀椀攀爀猀⸀䤀䐀 䰀䔀䘀吀 伀唀吀䔀刀 䨀伀䤀一ഀ਀                         䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䈀愀琀挀栀攀猀 伀一 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䜀漀漀搀猀刀攀挀攀椀瘀攀搀一漀琀攀䐀攀琀愀椀氀猀⸀䤀䐀 㴀 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䈀愀琀挀栀攀猀⸀䜀刀一䐀攀琀愀椀氀猀䤀搀ഀ਀ऀऀऀऀऀऀ   眀栀攀爀攀 䔀砀瀀椀爀礀䐀愀琀攀 㸀㴀 䜀䔀吀䐀䄀吀䔀⠀⤀ 愀渀搀 䔀砀瀀椀爀礀䐀愀琀攀 㰀㴀 䐀䄀吀䔀䄀䐀䐀⠀搀愀礀Ⰰ 䀀䔀砀瀀䐀愀礀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀  ഀ਀䜀刀伀唀倀 䈀夀 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䤀琀攀洀猀⸀䤀琀攀洀䌀漀搀攀Ⰰ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䤀琀攀洀猀⸀䤀琀攀洀一愀洀攀Ⰰ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀琀漀挀欀猀⸀匀琀漀挀欀一愀洀攀Ⰰ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀甀瀀瀀氀椀攀爀猀⸀匀甀瀀瀀氀椀攀爀一愀洀攀Ⰰ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䈀愀琀挀栀攀猀⸀䈀愀琀挀栀一漀Ⰰ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䈀愀琀挀栀攀猀⸀䔀砀瀀椀爀礀䐀愀琀攀ഀ਀ 栀愀瘀椀渀最 ⠀匀唀䴀⠀䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀琀漀挀欀䌀漀渀琀爀漀氀䐀攀琀愀椀氀⸀儀琀礀 ⨀ 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀匀琀漀挀欀䌀漀渀琀爀漀氀䐀攀琀愀椀氀⸀匀椀最渀嘀愀氀甀攀⤀ 㸀 　⤀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䜀攀渀攀爀愀氀匀琀漀爀攀猀崀⸀嬀匀甀瀀瀀氀椀攀爀䄀挀挀漀甀渀琀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀攀搀甀爀攀 嬀䜀攀渀攀爀愀氀匀琀漀爀攀猀崀⸀嬀匀甀瀀瀀氀椀攀爀䄀挀挀漀甀渀琀崀⠀䀀䘀爀漀洀䐀愀琀攀   一嘀䄀爀挀栀愀爀⠀㈀　⤀Ⰰഀ਀                                                 䀀吀漀䐀愀琀攀     一嘀䄀爀挀栀愀爀⠀㈀　⤀Ⰰഀ਀ऀऀऀऀऀऀऀऀऀऀऀऀ 䀀匀甀瀀瀀氀椀攀爀䤀䐀 椀渀琀⤀ഀ਀䄀匀ഀ਀匀䔀䰀䔀䌀吀ഀ਀ऀ⨀ഀ਀ऀⰀ 椀猀渀甀氀氀⠀嬀伀瀀攀渀 䈀愀氀愀渀挀攀崀Ⰰ　⤀ ⬀ 椀猀渀甀氀氀⠀嬀吀漀琀愀氀䈀攀昀漀爀攀䈀愀氀愀渀挀攀崀Ⰰ　⤀ ⬀ 匀唀䴀⠀嬀䐀攀戀椀琀崀 ⴀ 嬀挀爀攀搀椀琀崀⤀ 伀嘀䔀刀 ഀ਀ऀ⠀倀䄀刀吀䤀吀䤀伀一 䈀夀 嬀匀甀瀀瀀氀椀攀爀䤀搀崀 伀刀䐀䔀刀 䈀夀 嬀一攀眀刀漀眀一甀洀戀攀爀崀 䄀匀䌀⤀ 䄀匀 嬀䈀愀氀愀渀挀攀崀ഀ਀䘀刀伀䴀ഀ਀ऀ⠀ഀ਀ऀ猀攀氀攀挀琀ഀ਀ऀऀ⨀ഀ਀ऀऀⰀ 刀伀圀开一唀䴀䈀䔀刀⠀⤀ 伀嘀䔀刀 ⠀倀䄀刀吀䤀吀䤀伀一 䈀夀 嬀匀甀瀀瀀氀椀攀爀䤀搀崀 伀刀䐀䔀刀 䈀夀 嬀伀瀀攀爀愀琀椀漀渀 䐀愀琀攀崀 䄀匀䌀⤀ 䄀匀 嬀一攀眀刀漀眀一甀洀戀攀爀崀ഀ਀ऀऀⰀ ⴀⴀ ✀䐆ㄆ㔆䨆⼆ ✀䐆✆䄆⨆⨆✆ⴆ䤆ആ਀ऀऀऀ⠀匀䔀䰀䔀䌀吀 ⠀䤀匀一唀䰀䰀⠀匀䈀⸀䐀攀戀椀琀Ⰰ 　⤀ⴀ䤀匀一唀䰀䰀⠀匀䈀⸀䌀爀攀搀椀琀Ⰰ 　⤀⤀ 䘀刀伀䴀 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䄀搀搀匀甀瀀瀀氀椀攀爀䈀愀氀愀渀挀攀 䄀匀 匀䈀 ഀ਀ऀऀऀ圀䠀䔀刀䔀 匀䈀⸀匀甀瀀瀀氀椀攀爀䤀䐀 㴀 䀀匀甀瀀瀀氀椀攀爀䤀䐀 䄀一䐀 匀䈀⸀䤀猀伀瀀攀渀椀渀最䈀愀氀愀渀挀攀 㴀 ㄀⤀ 䄀匀 嬀伀瀀攀渀 䈀愀氀愀渀挀攀崀ഀ਀ऀऀⰀ ⴀⴀ ─Ⰶ䔆✆䐆䤆 䔀✆ 䈀⠆䐆䜆ആ਀ऀऀऀ⠀ഀ਀ऀऀऀऀ匀䔀䰀䔀䌀吀ഀ਀ऀऀऀऀऀⴀⴀ 䔀㐆⨆ㄆ䨆✆⨆ ㌀✆⠆䈆⤆ആ਀ऀऀऀऀऀ⠀匀䔀䰀䔀䌀吀 䤀匀一唀䰀䰀⠀匀唀䴀⠀嬀䜀刀䠀崀⸀嬀吀漀琀愀氀䜀刀一嘀愀氀甀攀䘀䌀崀⤀Ⰰ 　⤀ ഀ਀ऀऀऀऀऀ䘀刀伀䴀 嬀䜀攀渀攀爀愀氀匀琀漀爀攀猀崀⸀嬀䰀漀挀愀氀倀甀爀挀栀愀猀攀伀爀搀攀爀䠀攀愀搀攀爀崀 䄀匀 嬀䰀倀伀崀 ഀ਀ऀऀऀऀऀ椀渀渀攀爀 樀漀椀渀 䜀攀渀攀爀愀氀匀琀漀爀攀猀⸀䜀刀一开䰀倀伀猀 漀渀 氀瀀漀⸀䤀䐀㴀䜀刀一开䰀倀伀猀⸀䰀倀伀䤀䐀ഀ਀ऀऀऀऀऀ䤀一一䔀刀 䨀伀䤀一 嬀䜀攀渀攀爀愀氀匀琀漀爀攀猀崀⸀嬀䜀漀漀搀猀刀攀挀攀椀瘀攀搀一漀琀攀䠀攀愀搀攀爀崀 嬀䜀刀䠀崀 伀一 嬀䜀刀䠀崀⸀䤀䐀 㴀 䜀刀一开䰀倀伀猀⸀嬀䤀䐀崀 ഀ਀ऀऀऀऀऀ圀䠀䔀刀䔀 䰀倀伀⸀匀甀瀀瀀氀椀攀爀䤀䐀 㴀 䀀匀甀瀀瀀氀椀攀爀䤀䐀 䄀一䐀 嬀䜀刀䠀崀⸀嬀吀漀琀愀氀䜀刀一嘀愀氀甀攀䘀䌀崀 䤀匀 一伀吀 一唀䰀䰀 䄀一䐀 ഀ਀ऀऀऀऀऀ 嬀䜀刀䠀崀⸀嬀䜀刀一䐀愀琀攀崀 㰀 䌀伀一嘀䔀刀吀⠀䐀䄀吀䔀Ⰰ 䀀䘀爀漀洀䐀愀琀攀⤀⤀ഀ਀ऀऀऀऀऀⴀഀ਀ऀऀऀऀऀⴀⴀ 䔀ㄆ⨆Ⰶ㤆✆⨆ ㌀✆⠆䈆⤆ആ਀ऀऀऀऀऀ⠀匀䔀䰀䔀䌀吀 䤀匀一唀䰀䰀⠀匀唀䴀⠀䤀匀一唀䰀䰀⠀嬀倀刀䠀崀⸀嬀吀漀琀愀氀䄀洀漀甀渀琀崀Ⰰ 　⤀⤀Ⰰ 　⤀ 䘀刀伀䴀 ഀ਀ऀऀऀऀऀ嬀䜀攀渀攀爀愀氀匀琀漀爀攀猀崀⸀嬀䰀漀挀愀氀倀甀爀挀栀愀猀攀伀爀搀攀爀䠀攀愀搀攀爀崀 䄀匀 嬀䰀倀伀崀 䤀一一䔀刀 䨀伀䤀一 ഀ਀
					  GeneralStores.GRN_LPOs on [LPO].ID=GRN_LPOs.LPOID
					INNER JOIN [GeneralStores].[GoodsReceivedNoteHeader] [GRN] ON [GRN].ID = GRN_LPOs.[ID] 
					INNER JOIN [GeneralStores].[PurchaseReturnHeader] AS [PRH] ON [PRH].[GrnNo] = [GRN].[GRNNO] 
					WHERE LPO.SupplierID = @SupplierID AND  [PRH].[ReturnDate] < CONVERT(DATE, @FromDate))
					+
					-- تسويات سابقة
					ISNULL((SELECT SUM(ISNULL([AddSupplierBalance].[Debit], 0)) - 
					SUM(ISNULL([AddSupplierBalance].[Credit], 0)) FROM [GeneralStores].[AddSupplierBalance] 
					WHERE [AddSupplierBalance].[SupplierID] = @SupplierID AND [AddSupplierBalance].[IsOpeningBalance] = 0 AND [AddSupplierBalance].[TransactionDate] < @FromDate), 0)
					-
					-- مدفوعات نقدية سابقة
					ISNULL((SELECT SUM(ISNULL([PaymentSupplier].[ForiegnValue], 0)) FROM 
					[GeneralStores].[PaymentSupplier] WHERE [PaymentSupplier].[SupplierID] = @SupplierID 
					AND [PaymentSupplier].[PaymentDate] < @FromDate), 0)
					-
					-- مدفوعات بنكية سابقة
					ISNULL((SELECT SUM(ISNULL([BankPayment].[Value], 0)) FROM [GeneralStores].[BankPayment] WHERE
					 [BankPayment].[SupplierID] = @SupplierID AND [BankPayment].[chequeStatus] = 1 AND 
					 [BankPayment].[DueDate] < @FromDate), 0)
			) AS [TotalBeforeBalance]
	from
		(
			(
				select S.ID AS [SupplierId], S.SupplierName,
				CONVERT(date,GRH.GRNDate) [Operation Date],0 Debit,GRH.TotalGRNValueFC as credit,(N'مشتريات') 
				as [Operation Type]
				from  GeneralStores.Suppliers S
				  join GeneralStores.LocalPurchaseOrderHeader LPO on LPO.SupplierID= S.ID
				  join GeneralStores.GoodsReceivedNoteHeader GRH on GRH.LPOId=LPO.ID
				where S.ID = @SupplierID and GRH.TotalGRNValueFC IS NOT NULL
			)
			union all
			(
				select  S.ID AS [SupplierId], S.SupplierName,
				CONVERT(date,PRH.ReturnDate) [Operation Date],[PRH].[TotalAmount] as debit ,0 credit ,(N'مرتجعات') 
				as [Operation Type]
				from  GeneralStores.Suppliers S
				 join GeneralStores.LocalPurchaseOrderHeader LPO on LPO.SupplierID= S.ID
				  inner join GeneralStores.GRN_LPOs on [LPO].ID=GRN_LPOs.LPOID
					INNER JOIN [GeneralStores].[GoodsReceivedNoteHeader] [GRN] ON [GRN].ID = GRN_LPOs.[ID] 
