/****** Object:  StoredProcedure [GeneralStores].[SupplierAccount_Old]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE procedure [GeneralStores].[SupplierAccount_Old](@FromDate   NVArchar(20),
                                                 @ToDate     NVArchar(20),
												 @SupplierID int)
AS
SELECT
	*
	, isnull([Open Balance],0) + isnull([TotalBeforeBalance],0) + SUM([Debit] - [credit]) OVER 
	(PARTITION BY [SupplierId] ORDER BY [NewRowNumber] ASC) AS [Balance]
FROM
	(
	select
		*
		, ROW_NUMBER() OVER (PARTITION BY [SupplierId] ORDER BY [Operation Date] ASC) AS [NewRowNumber]
		, -- الرصيد الافتتاحى
			(SELECT (ISNULL(SB.Debit, 0)-ISNULL(SB.Credit, 0)) FROM GeneralStores.AddSupplierBalance AS SB 
			WHERE SB.SupplierID = @SupplierID AND SB.IsOpeningBalance = 1) AS [Open Balance]
		, -- إجمالى ما قبله
			(
				SELECT
					-- مشتريات سابقة
					(SELECT ISNULL(SUM([GRH].[TotalGRNValueFC]), 0) 
					FROM [GeneralStores].[LocalPurchaseOrderHeader] AS [LPO] 
					INNER JOIN [GeneralStores].[GoodsReceivedNoteHeader] [GRH] ON [GRH].[LPOId] = [LPO].[ID] 
					WHERE LPO.SupplierID = @SupplierID AND [GRH].[TotalGRNValueFC] IS NOT NULL AND 
					 [GRH].[GRNDate] < CONVERT(DATE, @FromDate))
					-
					-- مرتجعات سابقة
					(SELECT ISNULL(SUM(ISNULL([PRH].[TotalAmount], 0)), 0) FROM 
					[GeneralStores].[LocalPurchaseOrderHeader] AS [LPO] INNER JOIN 
					[GeneralStores].[GoodsReceivedNoteHeader] AS [GRN] ON [LPO].[ID] = [GRN].[LPOId] 
					INNER JOIN [GeneralStores].[PurchaseReturnHeader] AS [PRH] ON [PRH].[GrnNo] = [GRN].[GRNNO] 
					WHERE LPO.SupplierID = @SupplierID AND  [PRH].[ReturnDate] < CONVERT(DATE, @FromDate))
					+
					-- تسويات سابقة
					ISNULL((SELECT SUM(ISNULL([AddSupplierBalance].[Debit], 0)) - 
					SUM(ISNULL([AddSupplierBalance].[Credit], 0)) FROM [GeneralStores].[AddSupplierBalance] 
					WHERE [AddSupplierBalance].[SupplierID] = @SupplierID AND [AddSupplierBalance].[IsOpeningBalance] = 0 AND [AddSupplierBalance].[TransactionDate] < @FromDate), 0)
					-
