CREATE procedure [GeneralStores].[SupplierAcountSubReport](@FromDate   NVArchar(20),
														   @SupplierID int)
AS

select ISNULL(( ISNULL(v1.AllDebit,0) - ISNULL(v2.AllCredit,0)),0) As TotalBeforeBalance from  

  (select SUM(GRH.TotalGRNValueFC) AllDebit
from  GeneralStores.Suppliers S
join GeneralStores.LocalPurchaseOrderHeader LPO on LPO.SupplierID= S.ID
join GeneralStores.GoodsReceivedNoteHeader GRH on GRH.LPOId=LPO.ID
where S.ID = @SupplierID and GRH.TotalGRNValueFC IS NOT NULL and  GRH.GRNDate < CONVERT(date,@FromDate)) as v1   

CROSS JOIN

