/****** Object:  StoredProcedure [GeneralStores].[SupplierPurchaseDetailsEn]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create proc [GeneralStores].[SupplierPurchaseDetailsEn]
(
    @dateTo nvarchar(50) = null,
    @dateFrom nvarchar(50) = null,
    @itemTo int = null,
    @itemFrom int = null,
    @StFrom int = null,
    @StTo int = null,
    @classTo int = null,
    @classFrom int = null,
    @SupplierFrom int = null,
    @SupplierTo int = null
)
as
begin

Select
    PurchDate,
    ItemCode,
    ItemName,
    GRNNO,
    N'Purchases' TType,
    AcceptQTY,
    PriceFC,
    AcceptAmount,
    DiscountAmount,
    SupplierName,
    (AcceptAmount - DiscountAmount) Balance
from V_TStocksMov
where
    (@SupplierFrom is null or supplierID >= @SupplierFrom)
    AND (@SupplierTo is null or supplierID <= @SupplierTo)
    AND (@StFrom is null or StockID >= @StFrom)
    AND (@StTo is null or StockID <= @StTo)
    AND (@classFrom is null or ClassID >= @classFrom)
    AND (@classTo is null or ClassID <= @classTo)
    AND (@itemFrom is null or ItemID >= @itemFrom)
    AND (@itemTo is null or ItemID <= @itemTo)
    AND (@dateFrom is null or PurchDate >= Cast(@dateFrom as date)
    AND (@dateTo is null or PurchDate <= Cast(@dateTo as date)))

Union

Select
    PRDate,
    ItemCode,
    ItemName,
    PurchaseReturnNumber,
    N'Purchase Return' TType,
    ReturnQTYNoTConv,
    PriceFC,
    QtyValue,
    0 DiscountAmount,
    SupplierName,
    ReturnQTYNoTConv Balance
from V_ReturnPurch
inner join GeneralStores.Items
    on Items.ID = V_ReturnPurch.ItemID
where
    (@SupplierFrom is null or supplierID >= @SupplierFrom)
    AND (@SupplierTo is null or supplierID <= @SupplierTo)
    AND (@StFrom is null or StockID >= @StFrom)
    AND (@StTo is null or StockID <= @StTo)
    AND (@classFrom is null or GeneralStores.Items.ClassificationId >= @classFrom)
    AND (@classTo is null or GeneralStores.Items.ClassificationId <= @classTo)
    AND (@itemFrom is null or ItemID >= @itemFrom)
    AND (@itemTo is null or ItemID <= @itemTo)
    AND (@dateFrom is null or PRDate >= Cast(@dateFrom as date)
