CREATE proc [GeneralStores].[TStockMovement]
(@dateTo nvarchar(50)=null,@dateFrom nvarchar(50)=null, @itemTo int=null, @itemFrom int=null,@StTo int=null,@StFrom int=null,@classFrom INT=NULL,@classTo INT =NULL)
as
begin
if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end

Select TblTAfter.ItemID,TblTAfter.ItemName,TblTAfter.ItemCode,TblTAfter.incoming,
TblTAfter.Outgoing,TblTAfter.new_row_id,ISNULL(TblTBefore.lastT,0)lastT,TblTAfter.StockName,TblTAfter.StockID
,ISNULL(AddQty,0)TAddQty,ISNULL(SuntracQTY,0)TSuntracQTY,((ISNULL(AddQty,0)+incoming+ISNULL(lastT,0))-Outgoing-ISNULL(Subtraction.SuntracQTY,0)) Balance from (


Select ROW_NUMBER() OVER (ORDER BY itemID desc) Bnew_row_id,  ItemID BItemID, StockID BStockID,StockName,COALESCE(( Sum(incoming) -Sum (Outgoing)),0) lastT  ,ItemCode BItemCode
from(
select  ItemID , StockID,StockName, 0 Outgoing,COALESCE(Sum(PurchQty),0) incoming ,PurchDate,ItemCode,ItemName,'purch' describe
from V_TStocksMov 
where (issueToDepartment is null or issueToDepartment=0) 
group by ClassID,ItemID,ItemCode,ItemName,StockID ,PurchDate,StockName 
having 
  ((@StFrom is null or StockID>=@StFrom) and  
 (@StTo is null or StockID<=@StTo)) and
  ((@classFrom is null or V_TStocksMov.ClassID>=@classFrom) and
