琀攀⤀⤀ഀ਀ 愀渀搀 ⠀䀀搀愀琀攀吀漀 椀猀 渀甀氀氀 漀爀 瀀甀爀挀栀䐀愀琀攀㰀㴀䌀䄀匀吀⠀䀀搀愀琀攀吀漀 䄀匀 搀愀琀攀⤀⤀⤀ഀ਀ഀ਀ ഀ਀甀渀椀漀渀ഀ਀ⴀⴀ匀攀氀攀挀琀 嘀开吀爀愀渀猀昀攀爀 椀渀ഀ਀
select ItemID ,StockID,StockName ,0  outgoing,(Sum(TransferQty)) as incomming ,TransferDate,V_Transfer.ItemCode,V_Transfer.ItemName,'TransIn' describe
from V_Transfer
inner join V_itemClassification it on it.id=V_Transfer.ItemID
inner join GeneralStores.Stocks St on St.id=V_Transfer.StockID
group by ClassID,ItemID,V_Transfer.ItemCode,V_Transfer.ItemName ,StockID,TransferDate,StockName 
having   ((@StFrom is null or StockID>=@StFrom) and  
 (@StTo is null or StockID<=@StTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@itemFrom is null or ItemID>=@itemFrom) 
 and (@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or TransferDate>= CAST(@dateFrom AS date))
 and (@dateTo is null or TransferDate<=CAST(@dateTo AS date)))




union
--Select V_TransferCycle (Return Transfer) in
select ItemID ,V_TransferCycle.MainStockID,StockName ,0 TransOut,Sum(coalesce(IssueReturnQty,0))  as TransIn ,TransferDate,V_TransferCycle.ItemCode,V_TransferCycle.ItemName,'TransIn' describe
from V_TransferCycle 
inner join V_itemClassification it on it.id=V_TransferCycle.ItemID
inner join GeneralStores.Stocks St on St.id=V_TransferCycle.MainStockID
group by ClassID,ItemID,V_TransferCycle.ItemCode,V_TransferCycle.ItemName ,V_TransferCycle.MainStockID,TransferDate,StockName 
having 
  ((@StFrom is null or  V_TransferCycle.MainStockID>=@StFrom) and  
 (@StTo is null or  V_TransferCycle.MainStockID<=@StTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@itemFrom is null or ItemID>=@itemFrom) 
 and (@itemTo is null or ItemID<=@itemTo)) and 
((@dateFrom is null or TransferDate>= CAST(@dateFrom AS date))
 and (@dateTo is null or TransferDate<=CAST(@dateTo AS date)))


union
--Select V_ReturnPurch (Return Purchase) in
select ItemID ,StockID,StockName ,(Sum(ReturnQTY)) as  Outgoing, 0 as incoming,PRDate  ,ItemCode,ItemName,'purchReturn' describe
from V_ReturnPurch inner join V_itemClassification it on it.id=V_ReturnPurch.ItemID
inner join GeneralStores.Stocks St on St.id=V_ReturnPurch.StockID
where (issueToDepartment is null or issueToDepartment=0)
