/****** Object:  StoredProcedure [GL].[BudgetVsActualByaccount]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GL].[BudgetVsActualByaccount]
	(@year int)
	as
	BEGIN 
	declare @acc nvarchar= (select AccountNo from gl.accounts where id=(select  MainRevenueAccount from GL.GLSetting))
	declare @acc2 nvarchar= (select AccountNo from gl.accounts where id=(select MainExpenseAccount from GL.GLSetting))


select accounts.AcountNameEn,(isnull(BudgetForecast.month1,0)+isnull(BudgetForecast.month2,0)+isnull(BudgetForecast.month3,0)+isnull(BudgetForecast.month4,0)+isnull(BudgetForecast.month5,0)+isnull(BudgetForecast.month6,0)+isnull(BudgetForecast.month7,0)
+isnull(BudgetForecast.month8,0)+isnull(BudgetForecast.month9,0)+isnull(BudgetForecast.month10,0)+isnull(BudgetForecast.month11,0)+isnull(BudgetForecast.month12,0))/1000  as budget
,
Case when AccountNo LIKE CONCAT(@acc,'%') then Sum(GL.JournalDetails.Credit-GL.JournalDetails.Debit)/1000 
else Sum(GL.JournalDetails.Debit-GL.JournalDetails.Credit)/1000 end as balance 
	
from gl.accounts 	
inner join 	
	 GL.JournalDetails on gl.accounts.id=JournalDetails.AccountId
	 inner join gl.BudgetForecast on BudgetForecast.AccountID=accounts.id and BudgetForecast.AccountID=JournalDetails.AccountId
	 inner join gl.FiscalYearHeader on FiscalYearHeader.Id=BudgetForecast.FiscalYearID
	 and year(JournalDetails.CreatedDate)= year(FiscalYearHeader.DateFrom)
	 inner join GL.Journal on GL.Journal.JournalId= GL.JournalDetails.JournalId
	where 
	GL.Journal.IsDeleted=0 and 
	((AccountNo like CONCAT(@acc,'%') or AccountNo like CONCAT(@acc,'%')) 
	and year(JournalDetails.CreatedDate)=@year and year(FiscalYearHeader.DateFrom)=@year)
	group by 
 AccountNo,accounts.AcountNameEn,(isnull(BudgetForecast.month1,0)+isnull(BudgetForecast.month2,0)+isnull(BudgetForecast.month3,0)+isnull(BudgetForecast.month4,0)+isnull(BudgetForecast.month5,0)+isnull(BudgetForecast.month6,0)+isnull(BudgetForecast.month7,0)
