CREATE procEDURE [GL].[ClinicRevenuesReport] --'ad',20200101,20240101 
	-- Add the parameters for the stored procedure here
	@title nvarchar(4000),
	@DateFrom int,
	@DateTo int,
	@SpecialityId int
AS
if @SpecialityId=0 set @SpecialityId=null
select NameEnglish,NameArabic,Name,SUM(amount) amount,sum(Consultant) Consultant,sum(FollowUp)  FollowUp,SpecialityGroup
from (
SELECT DISTINCT 
                        OutPatient.ClinicSetup.NameEnglish, OutPatient.ClinicSetup.NameArabic,OutPatient.SpecialityGroupMaster.Name SpecialityGroup,  Registration.Doctors.Name, 
				sum(		 isnull(Billing.PatientBillservices.Amount,0)) amount,count(distinct Billing.PatientBillservices.OP_IPNumber) as Consultant,0 as FollowUp
FROM            Registration.DoctorsDailyScheduleDetails INNER JOIN
                         OutPatient.ClinicSetup ON Registration.DoctorsDailyScheduleDetails.ClinicId = OutPatient.ClinicSetup.ID INNER JOIN
                         OutPatient.ClinicProcedures ON Registration.DoctorsDailyScheduleDetails.ProcedureId = OutPatient.ClinicProcedures.ProcedureID 
