						 and ClinicProcedures.ClinicID=ClinicSetup.ID
						 INNER JOIN
						 OutPatient.SpecialityGroupMaster on OutPatient.SpecialityGroupMaster.ID=OutPatient.ClinicSetup.SpeciaityGroupID
						  INNER JOIN

                         Registration.DoctorsDailySchedule ON Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID = Registration.DoctorsDailySchedule.Id INNER JOIN
                         OutPatient.PrepareVisitSlip ON Registration.DoctorsDailyScheduleDetails.Id = OutPatient.PrepareVisitSlip.ScheduleAppointmentID INNER JOIN
                         Registration.Doctors ON OutPatient.PrepareVisitSlip.DoctorsID = Registration.Doctors.Id AND OutPatient.PrepareVisitSlip.DoctorsID = Registration.Doctors.Id INNER JOIN
                         Billing.PatientBillservices ON OutPatient.PrepareVisitSlip.OPnumber = Billing.PatientBillservices.OP_IPNumber
						 and PatientBillservices.ItemID=ClinicProcedures.ServiceID
WHERE        (Billing.PatientBillservices.Paid = 1)AND(OutPatient.ClinicSetup.SpeciaityGroupID = @SpecialityId or @SpecialityId is NULL) AND (Billing.PatientBillservices.Canceled IS NULL)
and cast(CONVERT(char(8), Billing.PatientBillservices.PaidDate,112 ) as bigint) between @DateFrom and @DateTo and Registration.DoctorsDailyScheduleDetails.ProcedureId=3
group by  OutPatient.ClinicSetup.NameEnglish, OutPatient.ClinicSetup.NameArabic,   Registration.Doctors.Name,OutPatient.SpecialityGroupMaster.Name


Union

---- patient is admitted and need consultation						 
SELECT DISTINCT 
                          OutPatient.ClinicSetup.NameEnglish,OutPatient.SpecialityGroupMaster.Name SpecialityGroup, OutPatient.ClinicSetup.NameArabic,  Registration.Doctors.Name 

		 	,sum(		 isnull(Billing.PatientBillservices.Amount,0)) amount,count(distinct Billing.PatientBillservices.OP_IPNumber) as Consultant,0 as FollowUp

FROM     
InPatient.AdmitPatients inner join     
 Billing.PatientBillservices on PatientBillservices.OP_IPNumber =AdmitPatients.IPNumber
 inner join OutPatient.ClinicProcedures on PatientBillservices.ItemID=ClinicProcedures.ServiceID
 
 inner join OutPatient.ClinicSetup on ClinicProcedures.ClinicID=ClinicSetup.ID  and PatientBillservices.ClinicId=ClinicSetup.ID 
