SET QUOTED_IDENTIFIER ON
GO

CREATE proc [GL].[GetExpensesOfPL]  --20220101,20230101
(
@Title nvarchar(4000),
@FromDate int,
@DateTo int
)

AS
BEGIN
 
begin
 
WITH cteDiscount AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select CashDiscountAccountID from Gl.GLSetting)  or  Id = (select EarnedDiscountAccount from Gl.GLSetting) 
 or Id = (select GoodsSoldAccount from GLSetting) or  Id = (select OperationExpenses from Gl.GLSetting) 
 or Id = (select salaryAccount from GLSetting) or Id = (select NonOperatingExpenseAccountID from GLSetting) 
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteDiscount c ON a.MainAccountNo =cast( c.id as varchar)
  )
 select ISNULL(sum(Debit)-sum(Credit),0) Expenses , id,AccountNo


  from 
  (
  SELECT distinct Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cteDiscount
  
left join 
(
select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit 
,ISNULL(Debit,0.00) Debit,JournalDetails.CreatedDate
