CREATE proc  [GL].[GetGLAccountValueDiff1] --20210101,20210630,'20202021',2
(


 @DateFrom int,
 @DateTo int,
 @YearNo int,
 

  @Title1 nvarchar,
    @Title2 nvarchar,
     @Title3 nvarchar,
  @Title4 nvarchar
)


as
begin

SELECT       ROW_NUMBER() OVER(ORDER BY AccountNo ASC) AS Row#, GL.accounts.id, GL.accounts.AccountNo, GL.accounts.MainAccountNo, GL.accounts.AccountNameAr, GL.accounts.AcountNameEn, GL.accounts.AccountType, GL.accounts.AccountLevel, 
                         SUM(Budgeting.Yearly_Budget.BudgetValue) AS BudgetValue,0 AmountValue,0 PrevBudgetValue,0 PrevAmountValue,0 TransActionAccountID,0 PrevTransActionAccountID,0 TransActionToAccountID,0 PrevTransActionToAccountID
INTO #TempTable FROM            GL.accounts LEFT OUTER JOIN
                         Budgeting.Yearly_Budget ON GL.accounts.id = Budgeting.Yearly_Budget.AccountID
						 where (cast(replace([YearNo],'/','') as bigint)=@YearNo or [YearNo] is null)
GROUP BY GL.accounts.id, GL.accounts.AccountNo, GL.accounts.MainAccountNo, GL.accounts.AccountNameAr, GL.accounts.AcountNameEn, GL.accounts.AccountType, GL.accounts.AccountLevel
declare @ROwsCountx int
 set @ROwsCountx=(select count(*) from #TempTable)
 declare @i int
 set @i=1
WHILE @i <= @ROwsCountx
BEGIN

