		GL.Journal inner join GL.JournalDetails on Journal.JournalId = JournalDetails.JournalId
		INNER JOIN GL.accounts
			ON accounts.id = JournalDetails.AccountId 
			inner join ApplicationSetup.Currency AccCurency
			on AccCurency.id=accounts.CurrencyId
			inner join ApplicationSetup.Currency JournalCurrency
			on JournalCurrency.Id=JournalDetails.CurrencyId
WHERE
     GL.accounts.AccountType = 0 
	 and 
((@DateFrom is null or Journal.Date>= Cast(@DateFrom as date))
 and (@DateTo is null or Journal.Date<=DATEADD(day,1,Cast(@DateTo as date))))

	 And  accounts.id = @AccountID
 ) as bb

