 CREATE proc [GL].[GetRevenueAndExpenseLevel] --0,99999999,null,0
 (
 @from int,
 @to int,
 @isPert bit,
 @ParantID int
 )
 as
 
 


  select 'A' as G,gl.accounts.Id,gl.accounts.AccountLevel ,cast(replace(gl.accounts.[MainAccountNo],'#','0') as bigint) [MainAccountNo],gl.accounts.AccountNo+'-'+accounts.AcountNameEn Name,isnull( SUM(GL.JournalDetails.LocalDebit),0) -isnull( SUM(GL.JournalDetails.LocalCredit),0) AS Expr1 from gl.accounts left join 
 
            GL.JournalDetails
			  ON gl.accounts.Id=   GL.JournalDetails.AccountId 
			 left JOIN
                         GL.Journal ON GL.JournalDetails.JournalId = GL.Journal.JournalId
						 where( cast( convert( char(8), GL.JournalDetails.CreatedDate,112) as bigint) between @from and @to or GL.JournalDetails.CreatedDate is null)
						 and  cast(replace(gl.accounts.[MainAccountNo],'#','0') as bigint) = @ParantID
