CREATE proc [GL].[GetRevenueAndExpenseNew]  --20220101,20230101
(
@Title nvarchar(4000),
@FromDate int,
@DateTo int
)

AS
BEGIN
Declare @MainRevenueAccount float
Declare @Discount float=0
Declare @Salary float
Declare @GoadSold float
Declare @MainExpenseAccount float
Declare @NonOperatingIncomeAccountID float
Declare @NonOperatingExpenseAccountID float
begin

WITH cte AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE AccountNo like convert(nvarchar,(select AccountNo from GL.GLSetting inner join gl.accounts on GLSetting.MainRevenueAccount= gl.accounts.id ))+'%'
  )
