爀渀愀氀⸀夀攀愀爀䌀氀漀猀攀 椀猀 渀甀氀氀⤀ 愀渀搀  挀愀猀琀⠀挀漀渀瘀攀爀琀⠀挀栀愀爀⠀㠀⤀Ⰰ䜀䰀⸀䨀漀甀爀渀愀氀⸀䐀愀琀攀Ⰰ㄀㄀㈀⤀ 愀猀 戀椀最椀渀琀⤀  戀攀琀眀攀攀渀 䀀䘀爀漀洀䐀愀琀攀 愀渀搀 䀀䐀愀琀攀吀漀ഀ਀⤀ 愀猀 䨀䐀ഀ਀漀渀 挀琀攀䌀愀瀀椀琀愀氀䄀挀挀漀甀渀琀⸀椀搀㴀樀䐀⸀䄀挀挀漀甀渀琀䤀搀ഀ਀ഀ਀ⴀⴀ眀栀攀爀攀   ⠀挀爀攀搀椀琀℀㴀渀甀氀氀 漀爀 䐀攀戀椀琀㸀　⤀  ഀ਀⤀ 愀猀 倀爀漀昀椀琀䰀漀猀猀⤀ ഀ਀ഀ਀攀渀搀ഀ਀戀攀最椀渀ഀ਀
WITH cteSalary AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select SalaryExpenses from GLSetting) 
  or a.id =
  (select  [GLSetting].salaryCoinsuranceExp from [GL].[GLSetting])
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteSalary c ON a.MainAccountNo =cast( c.id as varchar)
  )
  select @Salary =( select sum(Debit)-sum(Credit)


  from (
  SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cteSalary
  
  left join 
(select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit 
,ISNULL(Debit,0.00)Debit,JournalDetails.CreatedDate
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  cast(convert(char(8),GL.Journal.Date,112) as bigint)  between @FromDate and @DateTo
) as JD
on cteSalary.id=jD.AccountId

--where   (credit!=null or Debit>0)  
) as Salary) 

end
begin
WITH cteNonOperatingExpenseAccountID AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select NonOperatingExpenseAccountID from GLSetting) 
  or a.id =
  (select  [GLSetting].ticketsExpenses from [GL].[GLSetting])
  or a.id =
  (select  [GLSetting].pensionExpenses from [GL].[GLSetting])
  
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteNonOperatingExpenseAccountID c ON a.MainAccountNo =cast( c.id as varchar)
  )
  select @NonOperatingExpenseAccountID =( select sum(Debit)-sum(Credit)


  from (
  SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cteNonOperatingExpenseAccountID
  
