  left join 
(select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit 
,ISNULL(Debit,0.00)Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
