昀爀漀洀 ⠀ഀ਀  匀䔀䰀䔀䌀吀  䤀搀Ⰰ 䴀愀椀渀䄀挀挀漀甀渀琀一漀Ⰰ 䄀挀挀漀甀渀琀一漀Ⰰ䄀挀挀漀甀渀琀䰀攀瘀攀氀Ⰰ嬀䄀挀挀漀甀渀琀一愀洀攀䄀爀崀Ⰰ嬀䄀挀漀甀渀琀一愀洀攀䔀渀崀Ⰰ䌀爀攀搀椀琀Ⰰ䐀攀戀椀琀Ⰰ䌀爀攀愀琀攀搀䐀愀琀攀ഀ਀ഀ਀  䘀刀伀䴀 挀琀攀䄀猀猀攀琀䄀挀挀漀甀渀琀ഀ਀  ഀ਀  氀攀昀琀 樀漀椀渀 ഀ਀
(select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit ,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
,ISNULL(Debit,0.00)Debit 
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  year(GL.Journal.Date)= @Year
) as JD
on cteAssetAccount.id=jD.AccountId

--where   (credit!=null or Debit>0)  
) as ProfitLoss) 

end
begin
WITH cteCapitalAccount AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select NonOperatingIncomeAccountID from GLSetting) 
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteCapitalAccount c ON a.MainAccountNo =cast( c.id as varchar)
  )
  select @NonOperatingIncomeAccountID =( select sum(Debit)-sum(Credit)


  from (
  SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cteCapitalAccount
  
  left join 
(select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit 
,ISNULL(Debit,0.00)Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  year(GL.Journal.Date)= @Year
) as JD
on cteCapitalAccount.id=jD.AccountId

--where   (credit!=null or Debit>0)  
) as ProfitLoss) 

end
begin
WITH cteSalary AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select SalaryExpenses from GLSetting) or a.id =
  (select  [GLSetting].salaryCoinsuranceExp from [GL].[GLSetting])
