begin

WITH cte AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE  AccountNo like convert(nvarchar,(select AccountNo from GL.GLSetting inner join gl.accounts on GLSetting.MainRevenueAccount= gl.accounts.id ))+'%'
  )
  select @MainRevenueAccountP=( select sum(Credit)-sum(Debit)

  from (
  select  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  from (
  SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cte
  
  left join 
(select AccountId,LocalCredit,ISNULL(Credit,0.00)Credit, LocalDebit 
,ISNULL(Debit,0.00)Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  year(GL.Journal.Date)= @Year-1
) as JD
on cte.id=jD.AccountId

--where   (credit!=null or Debit>0)  
--union
-- SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit

--  FROM gl.accounts
  
--  left join 
--(select AccountId,LocalCredit,Credit, LocalDebit 
--,Debit
--from gl.JournalDetails
--left join gl.Journal
--on gl.JournalDetails.JournalId=gl.Journal.JournalId
--where year(GL.JournalDetails.CreatedDate)= @Year
--) as JD
--on gl.accounts.id=jD.AccountId

--where   (credit!=null or Debit>0) 
) as ProfitLoss) as ProfitLoss2)


end
begin
WITH cteDiscount AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select CashDiscountAccountID from GLSetting)  or  Id = (select EarnedDiscountAccount from GLSetting) 
