CREATE proc [GL].[GetRevenueOfPL]  --20220101,20230101
(
@Title nvarchar(4000),
@FromDate int,
@DateTo int
)

AS
BEGIN
WITH cte AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE AccountNo like convert(nvarchar,(select AccountNo from GL.GLSetting inner join gl.accounts on GLSetting.MainRevenueAccount= gl.accounts.id ))+'%'
  or AccountNo like convert(nvarchar,(select AccountNo from GL.GLSetting inner join gl.accounts on GLSetting.NonOperatingIncomeAccountID= gl.accounts.id ))+'%'
  )
