/****** Object:  StoredProcedure [GL].[GL_AgingRPT_Supp]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GL].[GL_AgingRPT_Supp]
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH AgingCTE AS
    (
        SELECT *,
               LAG(Age_Days, 1, 0) OVER (ORDER BY Age_Days) AS PrevDays
        FROM [GL].AgingSettings
    ),
    PaidCTE AS
    (
        SELECT
            supplierDuesId,
            SUM(ISNULL(LocalValue,0)) AS PaidValue
        FROM GeneralStores.SupplierInvoicePayment
        GROUP BY supplierDuesId
    ),
    DataCTE AS
    (
        SELECT
            c.ID,
            c.SupplierName     AS NameEnglish,
            c.SupplierNameAr   AS NameArabic,
            a.AgeName,
            a.AgeNameen,
            a.Age_Days,
            ISNULL(
                SUM(
                    SupplierDues.MoneyAmount
                  + SupplierDues.VatTax
                  + SupplierDues.Expenses
                  - ISNULL(p.PaidValue,0)
                ),0
            ) AS Value
        FROM [GeneralStores].Suppliers c
        CROSS JOIN AgingCTE a
        LEFT JOIN Billing.SupplierDues
            ON c.ID = SupplierDues.SupplierID
           AND SupplierDues.DueDate >= DATEADD(day, -a.Age_Days, GETDATE())
           AND SupplierDues.DueDate <  DATEADD(day, -a.PrevDays, GETDATE())
        LEFT JOIN PaidCTE p
            ON SupplierDues.Id = p.supplierDuesId
        GROUP BY
            c.ID,
            c.SupplierName,
            c.SupplierNameAr,
            a.AgeName,
            a.AgeNameen,
            a.Age_Days
    )
    SELECT
        ID,
        NameEnglish,
        NameArabic,
        AgeName,
        AgeNameen,
        Age_Days,
        Value
    FROM DataCTE d
    WHERE EXISTS
    (
        SELECT 1
        FROM DataCTE d2
        WHERE d2.ID = d.ID
          AND d2.Value <> 0
    )
    ORDER BY
        ID,
        Age_Days;
END

