-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
create procEDURE [GL].[GL_AgingRPTOld] 
	-- Add the parameters for the stored procedure here
AS
BEGIN
	 SELECT
  c.ID,
  c.NameEnglish ,c.[NameArabic],
  a.AgeName, a.AgeNameen,
  a.Age_Days,
  ISNULL(SUM(b.ClaimValue)- sum( ISNULL(ic.paidValue,0)),0) as Value
FROM [Billing].InsuranceCompanies c
JOIN [Receivable].InsuranceClaimsMaster b ON b.Ins_Id = c.ID
Left join 
(select sum(ISNULL(ic.LpaidValue,0)) paidValue,ClaimID from 
[Receivable].InsuranceClaims ic 
group by ClaimID
)
  ic on b.Id =ic.ClaimID
JOIN (
    SELECT *,
      PrevDays = LAG(Age_Days, 1, 0) OVER (ORDER BY Age_Days)
    FROM [GL].AgingSettings
) a ON b.createDate >= DATEADD(day, -a.Age_Days, GETDATE())
   AND b.createDate < DATEADD(day, -PrevDays, GETDATE())
GROUP BY
  c.ID,
  c.NameEnglish,c.[NameArabic],
  a.Age_Days,a.AgeNameen,
  a.AgeName;
END




    SELECT *
    FROM [GL].AgingSettings


