                         GL.accounts AS accounts_1 ON CONVERT(nvarchar, GL.accounts.id) = accounts_1.MainAccountNo LEFT OUTER JOIN
                         GL.JournalDetails JD ON accounts_1.id = JD.AccountId
						 left join ApplicationSetup.Currency  curr
on  GL.accounts.CurrencyId = curr.Id
where  (GL.accounts.ID >= @FromAccount or @FromAccount is null)  
and (GL.accounts.ID <= @ToAccount or @ToAccount is null) 
--where  (GL.accounts.ID >= 13 or 13 is null)  
--and (GL.accounts.ID <= 13 or 13 is null)  
 and GL.accounts.AccountType=@AccountType 
 --and GL.accounts.accountLevel!=0 
 --and GL.accounts.IncomeType!=0
group by     GL.accounts.AccountNo  , GL.accounts.AccountNameAr  
--, accounts_1.AccountNo , accounts_1.AccountNameAr  
 --, GL.JournalDetails.Debit, GL.JournalDetails.Credit
,GL.accounts.AccountLevel,GL.accounts.AccountType,GL.accounts.CostCenterDistributionId,curr.Name , curr.NameAr
,GL.accounts.MainAccountNo,GL.accounts.AccountNameAr,GL.accounts.AcountNameEn
ORDER BY GL.accounts.AccountNo asc

end

end



