CREATE procEDURE [GL].[Gl_ReportAr]
@FromAccount int ,
@ToAccount int ,
@AccountType bit null
as
begin 
--select Acc.ID, Acc.AccountNo,Acc.MainAccountNo,Acc.AccountNameAr,Acc.AcountNameEn,Acc.AccountLevel,Acc.AccountType,
--curr.Name ,curr.NameAr
--from GL.Accounts Acc
--join ApplicationSetup.Currency  curr
--on Acc.CurrencyId = curr.Id
--where Acc.ID >= @FromAccount and Acc.ID <= @ToAccount




if(@AccountType=0 or @AccountType=null)
begin
select 0 grp,  Acc.ID, Acc.AccountNo,Acc.MainAccountNo,Acc.AccountNameAr,Acc.AcountNameEn,Acc.AccountLevel,Acc.AccountType
