CREATE procEDURE [GL].[GlJournalDailyH] 
	-- Add the parameters for the stored procedure here

@FromSerial bigint=null,
@ToSerial bigint= null,
@FromDate nvarchar(20)= null,
@ToDate nvarchar(20)  =null,
@Post int
AS
BEGIN
SELECT        JournalId, Date, Serial, Description, TotalDebitCredit
FROM            GL.Journal
					 where (@FromDate is null or @FromDate='' or  gl.Journal.Date >= CAST(@FromDate AS date))
 and (@ToDate is null or @ToDate='' or gl.Journal.Date <= CAST(@ToDate AS date))
 and (@FromSerial is null or @FromSerial=0 or gl.Journal.Serial>=@FromSerial)
 and (@ToSerial is null or @ToSerial=0 or gl.Journal.Serial<=@ToSerial)
 and (isnull(gl.Journal.isPosted,0)=@Post or @Post=-1)
END



GO
