CREATE proc [GL].[GLNoneCostCenterReport]
@AccountIDTO int ,
@AccountIDFrom int ,
@FromDate datetime,
@ToDate datetime
as
begin 
select JD.CreatedDate, Acc.ID, Acc.AccountNo,Acc.AccountNameAr,Acc.AcountNameEn,acc.CurrencyBalance,JD.Credit,JD.Debit,
sum(JD.Debit-JD.Credit) over (order by JD.CreatedDate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as cumTotal
,case when acc.CurrencyBalance<0 then acc.CurrencyBalance*-1 else 0 end  as Accbalancecredite,
case when acc.CurrencyBalance>0 then acc.CurrencyBalance else 0 end  as Accbalancedepite

from GL.Accounts Acc
left join Gl.JournalDetails JD 
on Acc.ID=JD.AccountId


--where (Acc.ID  between @AccountIDTO and @AccountIDFrom or Acc.ID  between @AccountIDFrom and @AccountIDTO)
where(Acc.CostCenterDistributionId is null) and (( (@AccountIDFrom is null or Acc.ID>= @AccountIDFrom)  and (@AccountIDTO is null or Acc.ID<= @AccountIDTO) )
or ( (@AccountIDFrom is null or Acc.ID<= @AccountIDFrom ) and (@AccountIDTO is null or Acc.ID>= @AccountIDTO) ))
and (((@FromDate is null or JD.CreatedDate>= Cast(@FromDate as date))
 and (@ToDate is null or JD.CreatedDate<= Cast(@ToDate as date))))
end

GO
