/****** Object:  StoredProcedure [GL].[OverallBudgetreport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [GL].[OverallBudgetreport]
	(@year int)
	as
	BEGIN 
	declare @acc nvarchar= (select AccountNo from gl.accounts where id=(select  MainRevenueAccount from GL.GLSetting))
	declare @acc2 nvarchar= (select AccountNo from gl.accounts where id=(select MainExpenseAccount from GL.GLSetting))

select * from(
select 'm'+convert (nvarchar,month (Journal.Date))  mmonth, 
	sum(GL.JournalDetails.Debit-GL.JournalDetails.Credit) as Prbalance ,'profit' tit
from gl.accounts 	
left join 	
	 GL.JournalDetails on gl.accounts.id=JournalDetails.AccountId
	 left join GL.Journal on  GL.Journal.JournalId=GL.JournalDetails.JournalId
	where 
	GL.Journal.IsDeleted=0 and
	--AccountNo like CONCAT('2','%') and
	AccountNo like CONCAT(@acc,'%') and
	year(Journal.Date)=@year
group by 
month (Journal.Date)

union 
	

	select 'm'+convert (nvarchar,month (Journal.Date)) mmonth,
	sum(GL.JournalDetails.Debit-GL.JournalDetails.Credit) as exbalance  ,'Expenses' tit 
from gl.accounts 	
left join 	
	 GL.JournalDetails on gl.accounts.id=JournalDetails.AccountId
	left join GL.Journal on  GL.Journal.JournalId=GL.JournalDetails.JournalId
	where 
	GL.Journal.IsDeleted=0 and
	--AccountNo like CONCAT('1','%') and
	AccountNo like CONCAT(@acc2,'%') and
	year(Journal.Date)=@year
group by 
month (Journal.Date)
) as mytable
pivot(max(Prbalance)
for mmonth  in (m1,m2,m3,m4,m5,m6,m7,m8,m9,m10,m11,m12) 
 
) piv;
End

