begin
WITH cteDepreciation AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select DepreciationAccount from GLSetting) 
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteDepreciation c ON a.MainAccountNo =cast( c.id as varchar)
  )
  select @Depreciation=( select sum(Debit)-sum(Credit)


  from (
  SELECT  Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],ISNULL(Credit,0)Credit,ISNULL(Debit,0)Debit,CreatedDate

  FROM cteDepreciation
  
  left join 
(select AccountId,LocalCredit,ISNULL(Credit,0)Credit, LocalDebit ,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
,ISNULL(Debit,0) Debit
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and  year(gl.Journal.Date)=@Year
) as JD
on cteDepreciation.id=jD.AccountId

  
) as ProfitLoss) 

end


begin
WITH cteAssetAccount AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select fixedAsset from GLSetting) 
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteAssetAccount c ON a.MainAccountNo =cast( c.id as varchar)
  )
