create procEDURE [GL].[RepGeneralBudgetOld] 
@costCenterId int =NULL,
@DateFrom datetime=NULL,
@DateTo datetime=NULL,
@LevelNo int =NULL,
@accountId int =NULL
AS
BEGIN

WITH [cteRN] AS 
(
    select A.id,A.AccountNo,A.MainAccountNo,A.AcountNameEn,A.AccountNameAr ,
jD.Credit,
jD.Debit
,A.AccountLevel,cc.CostCenterId,
        ROW_NUMBER() OVER (
            PARTITION BY MainAccountNo ORDER BY MainAccountNo) AS [ROW_NUMBER]
