declare @HoldingtaxAccount float
declare @RevenuCostAccountID float
declare @discount float
if(@LevelNo is null)
set @LevelNo=1
if(@costCenterId=0)
begin
begin
WITH cte AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE AccountNo like convert(nvarchar,(select AccountNo from GL.GLSetting inner join gl.accounts on GLSetting.MainRevenueAccount= gl.accounts.id))+'%'
  )


select @MainRevenueAccount =(select sum(Credit)-sum(Debit)
from ( 


SELECT Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,CreatedDate

  FROM cte
  
  left join 
(select AccountId,LocalCredit,Credit, LocalDebit 
,ISNULL(Debit,0.00)Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  Year(gl.Journal.Date)=@Year
) as JD
on cte.id=jD.AccountId
) as MainRevenueAccountTable)
end
begin
WITH cteExpenseAccount AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id = (select  top 1 OperationExpenses from GL.GLSetting) 
  OR Id = (select NonOperatingExpenseAccountID from GLSetting) 
  or a.id =
  (select  [GLSetting].ticketsExpenses from [GL].[GLSetting])
  or a.id =
  (select  [GLSetting].pensionExpenses from [GL].[GLSetting])
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteExpenseAccount c ON a.MainAccountNo =cast( c.id as varchar)
  )


select @ExpenseAccount =(select sum(Debit)-sum(Credit)
from ( 


SELECT Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit, JD.CreatedDate

  FROM cteExpenseAccount
  
