  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE Id =  (select  top 1 HoldingtaxAccount from GL.GLSetting)
  UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cteHoldingtaxAccount c ON a.MainAccountNo =cast( c.id as varchar)
  )
 
 select @HoldingtaxAccount= (select sum(Debit)-sum(Credit) from
 ( SELECT Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],Credit,Debit,JD. CreatedDate

  FROM cteHoldingtaxAccount
  
  left join 
(select AccountId,LocalCredit,Credit, LocalDebit 
,Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) CreatedDate,CostCenterId
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
inner join Gl.DetailsCostCenter on JournalDetails.JournalDetailsId=DetailsCostCenter.JournalDetailsId
where GL.Journal.IsDeleted=0 and (Gl.Journal.YearClose=0 OR Gl.Journal.YearClose is null) and  year( gl.Journal.Date)=@Year
) as JD
on cteHoldingtaxAccount.id=jD.AccountId
left join gl.CostCenter cc on cc.CostCenterId =JD.CostCenterId
where   AccountLevel>=@LevelNo and cc.CostCenterId=@costCenterId
) as HoldingtaxAccountTable)
end
