CREATE procEDURE [GL].[RepIncomeListOLDHany] 
@costCenterId int =NULL,
@DateFrom datetime=NULL,
@DateTo datetime=NULL,
@LevelNo int =NULL,
@accountId int =NULL
AS
BEGIN

WITH [cteRN] AS 
(
    select A.id,A.AccountNo,A.MainAccountNo,A.AcountNameEn,A.AccountNameAr ,
jD.Credit,
jD.Debit
,A.AccountLevel,cc.CostCenterId,
        ROW_NUMBER() OVER (
            PARTITION BY MainAccountNo ORDER BY MainAccountNo) AS [ROW_NUMBER]
from gl.accounts A
left join 
(select AccountId,LocalCredit,Credit, LocalDebit 
,Debit
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where gl.Journal.Date>=@DateFrom and gl.Journal.Date<=@DateTo
) as JD
on A.id=jD.AccountId
left join gl.CostCenter cc on cc.CostCenterId =A.CostCenterDistributionId

group by A.id,A.AccountNo,A.MainAccountNo,A.AccountLevel,jD.Credit,
jD.Debit,A.AcountNameEn, 
A.AccountNameAr ,cc.CostCenterId
),
[cteHierarchy] AS 
(
    SELECT CAST(
            CAST(hierarchyid::GetRoot() AS VARCHAR(100))
            + CAST([ROW_NUMBER] AS VARCHAR(100))
            + '/' AS HIERARCHYID
        ) AS [Node],
        *
    FROM [cteRN]
    WHERE  AccountLevel <= @LevelNo and Id=@accountId
    UNION ALL
    SELECT CAST(
            hierarchy.Node.ToString()
            + CAST(RN.[ROW_NUMBER] AS VARCHAR(100)
        ) + '/' AS HIERARCHYID),
        rn.*
    FROM [cteRN] rn
    INNER JOIN [cteHierarchy] hierarchy
        ON rn.MainAccountNo =Cast( hierarchy.[Id] as nvarchar)
)
SELECT X.AccountLevel,x.AccountNo,
    x.[Id], x.MainAccountNo, x.AcountNameEn,x.AccountNameAr,x.Credit,x.Debit
FROM [cteHierarchy] x
LEFT JOIN [cteHierarchy] child
