CREATE proc [GL].[RepMainExpenseAccount]  --0,'2022-01-01','2025-01-01','asd'
(
@costCenterId int =NULL,
@DateFrom datetime=NULL,
@DateTo datetime=NULL,
@costCenterName nvarchar(4000)

 

 
)

AS
BEGIN



WITH cte AS 
 (
  SELECT a.Id, a.MainAccountNo, a.AccountNo,AccountLevel,CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn] 
  FROM [GL].[accounts] a
  WHERE a.id =
  (select  GLSetting.MainExpenseAccount from GLSetting)
    UNION ALL
  SELECT a.Id, a.MainAccountNo, a.AccountNo,a.AccountLevel,a.CostCenterDistributionId,a.[AccountNameAr],a.[AcountNameEn]
  FROM [GL].[accounts] a JOIN cte c ON a.MainAccountNo =cast( c.id as varchar)
  )
  SELECT Id, MainAccountNo, AccountNo,AccountLevel,[AccountNameAr],[AcountNameEn],(Debit-Credit) As MoneyTotal,MonthDate
  ,'E' As T
  FROM cte
  
  left join 
(select AccountId,sum(LocalCredit) LocalCredit ,sum(Credit)Credit, sum(LocalDebit)LocalDebit 
,sum(Debit) Debit,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar) as MonthDate
from gl.JournalDetails
left join gl.Journal
on gl.JournalDetails.JournalId=gl.Journal.JournalId
where gl.Journal.Date>=@DateFrom and gl.Journal.Date<=@DateTo
group by AccountId,cast(Month(gl.Journal.Date) as varchar) + '-' + Cast(Year(gl.Journal.Date)as varchar)
) as JD
on cte.id=jD.AccountId
left join gl.CostCenter cc on cc.CostCenterId =cte.CostCenterDistributionId
where   (credit!=null or Debit>0) 
group by cte.id,cte.AccountNo,cte.MainAccountNo,cte.AccountLevel,jD.Credit,
jD.Debit,cte.AcountNameEn, MonthDate,
cte.AccountNameAr
order by cast( cte.AccountNo as nvarchar)
print 'adsd'
end



 

  

