inner join GL.JournalDetails JD on DetailsCostCenter.JournalDetailsId=JD.JournalDetailsId
inner join GL.accounts Acc on Acc.id =JD.AccountId
inner join ApplicationSetup.Currency CR on CR.Id = Acc.CurrencyId
inner join Gl.Journal on JD.JournalId =Journal.JournalId

where GL.Journal.IsDeleted=0 and  CC.CenterNature = @CenterNature
and (((@AccountFrom is null Or Acc.id >= @AccountFrom ) and (@AccountTo is null Or Acc.id <= @AccountTo ))
OR  ((@AccountFrom is null Or Acc.id <= @AccountFrom ) and (@AccountTo is null Or Acc.id >= @AccountTo )))

and (((@CostCenterFrom is null Or CC.CostCenterId >= @CostCenterFrom ) and (@costCenterTo is null Or CC.CostCenterId <= @costCenterTo ))
OR  ((@CostCenterFrom is null Or CC.CostCenterId <= @CostCenterFrom ) and (@costCenterTo is null Or CC.CostCenterId >= @costCenterTo )))

and ((Journal.Date >= @DateFrom or @DateFrom is null)
and (Journal.Date <= DATEADD(day,1,@dateTo) or @dateTo is null))

GO
/****** Object:  StoredProcedure [GL].[Sp_totalPatientsBill]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
