-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE[GL].[Sp_totalPatientsBill]
	-- Add the parameters for the stored procedure here
	(@DateFrom datetime,@dateTo datetime)
AS
BEGIN
	select RP.Code,isnull(RP.FirstName,'') +' '+ isnull(RP.MiddleName1,'') +' ' +isnull(RP.MiddleName2,'')+ ' '+isnull(RP.LastName,'') as  ArabicFullName
	,isnull(RP.TranslatedFallName ,'')  as  EnglishFullName
	--,isnull(BPS.Discount,0) as discount
	--,isnull(BPS.Vat,0) as vat
	
	,count(BPS.ReceiptNo) as TotalInvoices
	,sum(isnull(BPS.Amount,0)) as sales  
	,sum(isnull(BPS.ReceiptDescount,0)) as Discount  
	,sum(isnull(BPS.Amount,0)-isnull(BPS.ReceiptDescount,0)) as netsales  
	,sum(isnull(BPS.PatVat+SpoVat,0)) Vat
	,sum(isnull(BPS.Amount,0)+ isnull(BPS.PatVat+SpoVat,0)-isnull(BPS.ReceiptDescount,0)) as netsaleswithtaxes

	from Billing.PatientBill BP
	left JOIN
    Billing.PatientBillservices BPS 
	ON BPS.PatientBillID = BP.Id 
	left JOIN
