--   select JD.Credit as  TaxCredit,JD.Debit  as TaxDebit ,JD.Description as Description ,JD.CreatedDate,acc.AcountNameEn,acc.AccountNameAr
--   ,J.Serial,JD.AccountId
-- --select TaxAccountNo   from [GeneralStores].[Tax]
-- from gl.JournalDetails JD 
-- left join GL.Journal J on JD.JournalId=J.JournalId
-- left join GL.accounts acc on JD.AccountId=acc.AccountNo
-- -- where (JD.AccountId=(select TaxAccountNo   from [GeneralStores].[Tax]) 
-- -- and (@FromDate is null or JD.CreatedDate >= CAST(@FromDate AS date)) 
-- --and (@ToDate is null or JD.CreatedDate <= CAST(@ToDate AS date)))
--  order by JD.CreatedDate
 WITH cte_quantity
AS
(select JD.Credit as VatCredit,JD.Debit as VatDebit ,JD.Description as Description,JD.CreatedDate,acc.AcountNameEn,acc.AccountNameAr
 ,J.Serial,acc.AccountNo
 from gl.JournalDetails JD
 left join GL.Journal J on JD.JournalId=J.JournalId
 left join GL.accounts acc on JD.AccountId=acc.id
 where (JD.AccountId in ((select VatAccountID   from gl.GlSetting) ,(select TaxAccountNo   from [GeneralStores].[Tax])) 
 and (@FromDate is null or JD.CreatedDate >= CAST(@FromDate AS date)) 
and (@ToDate is null or JD.CreatedDate <=DATEADD(DAY,1, CAST(@ToDate AS date))))  
 ) 
 select * ,(select Top(1) (cte1.VatDebit-cte1.VatCredit)  from cte_quantity as cte1) as firstBa
 ,(select top(1) (cte2.VatDebit-cte2.VatCredit) last from cte_quantity as cte2 order by cte2.CreatedDate  desc )LastB
 from cte_quantity 
END
