/****** Object:  StoredProcedure [HR].[AppointmentsReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [HR].[AppointmentsReport] @Material int ,@AppointmentDate datetime
AS
select  A.DoctorName,A.NationalID,A.BirthDate,A.GraduationYear,A.GPA,MG.Degree ,A.AppointmentDate,SGM.Name from HR.Appointments A

JOIN HR.MaterialGrades MG on MG.AppointmentsID=A.ID
JOIN OutPatient.SpecialityGroupMaster SGM on SGM.ID=MG.SpecialityGroupMasterID
WHERE MG.SpecialityGroupMasterID=@Material and A.AppointmentDate like @AppointmentDate
order by A.GPA DESC ,MG.Degree DESC,A.GraduationYear DESC ,A.BirthDate


GO
/****** Object:  StoredProcedure [HR].[BabySettingInfo]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE proc [HR].[BabySettingInfo](@date nvarchar(10))
 as
 begin
 

 declare @ts int= HR.FBabySettingTS (@date,NULL);
 select * ,@ts AllTS, HR.FBabySettingTS (@date,HR.V_Babysetting.EmployeeId) as EmpTS from HR.V_Babysetting
 where  convert(nvarchar(10),FORMAT (FromDate,'MM/yyyy'))=@date

 end

GO
/****** Object:  StoredProcedure [HR].[BabySettingTS]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [HR].[BabySettingTS](@date nvarchar(10),@emp int,@Num decimal(18,2) out)
as
begin
set @Num =(
Select Sum(TS.BasicS) from 
(
select SUM(Emp.BasicSalary) BasicS from Nursing.Employee Emp 
where 
(@emp is NULL or Emp.Id=@emp) and 
Emp.id in(SELECT V_Babysetting.EmployeeId
from HR.V_Babysetting)
union

 select    SUM(svv.Value) sallary 
 from HR.MainElements ME
Inner join HR.SubElements SE on ME.ID = SE.MainElementID 
Left Join Hr.EmployeeSalaryVariablesVar svv  on SE.ID =svv.SubElementID 
inner join Nursing.Employee on Employee.Id=svv.EmpID
where   me.[Type]=2 and SE.InsuranceType=2 And
svv.EmpID in(SELECT V_Babysetting.EmployeeId
from HR.V_Babysetting)

and (@emp is NULL or Employee.Id=@emp)
and ( @date=svv.[Month]) 
and ID_Close IS not NULL
) as TS)
