-- Cursor for Emp permissions
set @PermissionCountTaken=(select count(*) from Hr.EmployeePermission
where EmployeeID = @EmployeeId
and isnull(ApprovealStatus, 0) = 2
and isnull(IsCalculated, 0) = 0  and EmployeePermission.PermissionDate >= @sdate and PermissionDate<=@edate )
print((ISNULL(@vacDays,0)+ISNULL(@PermissionCountTaken,0)+ISNULL(@weekends,0)+ISNULL(@holidays,0)))

