-- Cursor for Emp vacations forl atency
DECLARE NeededCursorempvacationsforlatency cursor LOCAL FORWARD_ONLY READ_ONLY for

select sum(vacDays) from Hr.EmployeeVacations
where EmpId = @EmployeeId
and Year = @CurrentYear
and isnull(ISLatency, 0) = 1

open NeededCursorempvacationsforlatency

FETCH NEXT FROM NeededCursorempvacationsforlatency INTO @vacDaysLatency
WHILE @@FETCH_STATUS =0
			BEGIN


FETCH NEXT FROM NeededCursorempvacationsforlatency INTO @vacDaysLatency
END

close NeededCursorempvacationsforlatency
DEALLOCATE NeededCursorempvacationsforlatency;

