DECLARE NeededCursor cursor LOCAL FORWARD_ONLY READ_ONLY for
 

select 
	  ISNULL(hr.SubElements.ElementValue,0)ElementValue,
      [Precentage]
      ,hr.SalaryVariablesAll.[MaximumValue]
      ,[MinimumValue]
      ,[PercentageValue]
      ,[PercentageElement]
      ,[Month]
      ,hr.SalaryVariablesAll.[Status] status2,
	  Formula,
	  IsFormula, 
	  hr.SubElements.NameArabic,
	  hr.SubElements.NameEnglish,
	  hr.SubElements.MainElementID,
	  hr.SubElements.ID SubElementsID,
	  hr.SubElements.Taxable
	  ,MainElements.[Type],hr.SubElements.InsuranceType,isEmp

 from hr.SalaryVariablesAll inner join hr.SubElements

