-- //Employee salary variable var
DECLARE NeededCursorEmpSalVars cursor LOCAL FORWARD_ONLY READ_ONLY for
 

select 
	  hr.EmployeeSalaryVariablesVar.Value,
      0
      ,0
      ,0
      ,0
      ,0
      ,0
      ,1,
	  Formula,
	  IsNULL(IsFormula,0), 
	  hr.SubElements.NameArabic,
	  hr.SubElements.NameEnglish,
	  hr.SubElements.MainElementID,
	  hr.SubElements.ID SubElementsID,
	  hr.SubElements.Taxable,
	  hr.MainElements.Type,hr.SubElements.InsuranceType,SubElements.IsEmp
 from hr.EmployeeSalaryVariablesVar inner join hr.SubElements inner join hr.MainElements on MainElementID=MainElements.ID
 on 
 hr.EmployeeSalaryVariablesVar.SubElementID = hr.SubElements.ID
 where EmpID = @EmployeeId and EmployeeSalaryVariablesVar.ID_Close is null
 and [Month]=@CurrentMonth and IsApproval=1
OPEN NeededCursorEmpSalVars
