			DECLARE NeededCursorAttendance cursor LOCAL FORWARD_ONLY READ_ONLY for
 
				select 
					[AttendanceDate], isnull(DelayMinutes, 0), isnull(EarlyLeaveMinutes, 0)
				from PayRoll.AttendanceSchedule
				where [EmployeeID] = @EmployeeId



			OPEN NeededCursorAttendance
			FETCH NEXT FROM NeededCursorAttendance INTO @AttendanceDate, @DelayMinutes, @EarlyLeaveMinutes
			
						WHILE @@FETCH_STATUS =0
						BEGIN
			
			set @DelayMinutesAll = @DelayMinutesAll + @DelayMinutes
			set @EarlyLeaveMinutesAll = @EarlyLeaveMinutesAll + @EarlyLeaveMinutes
			 
			FETCH NEXT FROM NeededCursorAttendance INTO @AttendanceDate, @DelayMinutes, @EarlyLeaveMinutes

						end


			CLOSE NeededCursorAttendance;
			DEALLOCATE NeededCursorAttendance;

			set @LateDaysNumber = isnull(@DelayMinutesAll, 0) + isnull(@EarlyLeaveMinutesAll, 0)
			set @LateDaysNumber = @LateDaysNumber / 120
			set @LateDaysNumber = @LateDaysNumber - @vacDaysLatency



			

			if @LateDaysNumber > 0
			begin
			
