DECLARE NeededCursordvj cursor LOCAL FORWARD_ONLY READ_ONLY for
 
 select 
	  ISNULL(hr.SubElements.ElementValue,0)ElementValue,
      [Precentage]
      ,hr.DegreeVariablesJobs.[MaximumValue]
      ,[MinimumValue]
      ,[PercentageValue]
      ,[PercentageElement]
      ,[Month]
      ,hr.DegreeVariablesJobs.[Status] status2,
	  Formula,
	  IsNULL(IsFormula,0), 
	  hr.SubElements.NameArabic,
	  hr.SubElements.NameEnglish,
	  hr.SubElements.MainElementID,
	  hr.SubElements.ID SubElementsID,
	  hr.SubElements.Taxable
	  ,MainElements.[Type],hr.SubElements.InsuranceType,isEmp
 from hr.DegreeVariablesJobs inner join hr.SubElements
 on 
 hr.DegreeVariablesJobs.SubElementID = hr.SubElements.ID
 inner join hr.MainElements on MainElementID=MainElements.ID
 where hr.DegreeVariablesJobs.DegreeID = @JobdegreeID
 and (hr.DegreeVariablesJobs.Month is null or hr.DegreeVariablesJobs.Month = @CurrentMonth)


OPEN NeededCursordvj
			FETCH NEXT FROM NeededCursordvj INTO
			 @Value, @Precentage, @MaximumValue, @MinimumValue, @PercentageValue, @PercentageElement,
			 @Month, @Status, @Formula, @IsFormula, @NameArabic, @NameEnglish, @MainElementID,
			 @SubElementID, @IsTaxable,@maintype,@InsuranceType,@isEmp
			WHILE @@FETCH_STATUS =0
			BEGIN

			INSERT INTO  @NeededTbl (Value,
Precentage,
MaximumValue,
MinimumValue, 
PercentageValue, 
PercentageElement, 
Month, 
Status,
Formula, 
IsFormula, 
NameArabic, 
NameEnglish,
MainElementID,
SubElementID,
IsTaxable,
Examption,
EmployeeId,MainType,InsuranceType,isEmp) 
				values (@Value, @Precentage, @MaximumValue, @MinimumValue, @PercentageValue, @PercentageElement,
				 @CurrentMonth, @Status, @Formula, @IsFormula, @NameArabic, @NameEnglish, @MainElementID, 
				 @SubElementID, @IsTaxable, 0, @EmployeeId,@maintype,@InsuranceType,@isEmp);

				 FETCH NEXT FROM NeededCursordvj INTO
			 @Value, @Precentage, @MaximumValue, @MinimumValue, @PercentageValue, @PercentageElement,
