DECLARE NeededCursoruvd cursor LOCAL FORWARD_ONLY READ_ONLY for
 
   select 
	  ISNULL(hr.SubElements.ElementValue,0)ElementValue,
      [Precentage]
      ,hr.SalaryVariablesDepartment.[MaximumValue]
      ,[MinimumValue]
      ,[PercentageValue]
      ,[PercentageElement]
      ,[Month]
      ,hr.SalaryVariablesDepartment.[Status] ,
	  Formula,
	  IsNULL(IsFormula,0), 
	  hr.SubElements.NameArabic,
	  hr.SubElements.NameEnglish,
	  hr.SubElements.MainElementID,
	  hr.SubElements.ID SubElementsID,
	  hr.SubElements.Taxable
	  ,MainElements.[Type],hr.SubElements.InsuranceType,isEmp
 from hr.SalaryVariablesDepartment inner join hr.SubElements
 on 
 hr.SalaryVariablesDepartment.SubElementID = hr.SubElements.ID
 inner join MainElements on MainElementID=MainElements.ID
 where hr.SalaryVariablesDepartment.DepartmentID = @DepartmentID
 and (hr.SalaryVariablesDepartment.Month is null or hr.SalaryVariablesDepartment.Month ='' or  hr.SalaryVariablesDepartment.Month = @CurrentMonth)

OPEN NeededCursoruvd
			FETCH NEXT FROM NeededCursoruvd INTO
			 @Value, @Precentage, @MaximumValue, @MinimumValue, @PercentageValue, @PercentageElement,
			 @Month, @Status, @Formula, @IsFormula, @NameArabic, @NameEnglish, @MainElementID,
			 @SubElementID, @IsTaxable,@maintype,@InsuranceType,@isEmp
			WHILE @@FETCH_STATUS =0
			BEGIN

			INSERT INTO  @NeededTbl (Value,
Precentage,
MaximumValue,
MinimumValue, 
PercentageValue, 
PercentageElement, 
Month, 
Status,
Formula, 
IsFormula, 
NameArabic, 
NameEnglish,
MainElementID,
SubElementID, 
IsTaxable,
Examption,
EmployeeId,MainType,InsuranceType,isEmp) 
				 values (@Value, @Precentage, @MaximumValue, @MinimumValue, @PercentageValue, @PercentageElement,
				 @CurrentMonth, @Status, @Formula, @IsFormula, @NameArabic, @NameEnglish, @MainElementID, 
				 @SubElementID, @IsTaxable, 0, @EmployeeId,@maintype,@InsuranceType,@isEmp);

