/****** Object:  StoredProcedure [HR].[EmployeeCoursessReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[EmployeeCoursessReport] @Employee int=null,@coursessetupID int=null
as
select 
 isnull(e.FirstName ,'')+' '+  isnull(e.MiddleName ,'')+' '+isnull(E.BeforeLastName,'') + ' ' +isnull(e.LastName  ,'')as Employee,

  isnull(e.FirstNameAr ,'')+' '+  isnull(e.MiddleNameAr ,'')+' '+isnull(E.BeforeLastNameAr,'') + ' ' +isnull(e.LastNameAr  ,'')as EmployeeNameAr,
 isnull(e.FirstNameEn ,'')+' '+  isnull(e.MiddleNameEn ,'')+' '+isnull(E.BeforeLastNameEn,'') + ' ' +isnull(e.LastNameEn  ,'')as EmployeeNameEn ,
 cs.coursessetupDescription as Course ,
 cs.coursessetupDescriptionAr as CourseAr
 
 
 
 ,   FORMAT (CoursesDate, 'dd/MM/yyyy ')  as CoursesDate
 
 
 ,FORMAT (CoursesExpiredate, 'dd/MM/yyyy ') CoursesExpiredate
from HR.EmployeeCoursess ec left join Nursing.Employee e on ec.EmployeeID=e.Id
left join HR.CourseSetup cs on ec.coursessetupID=cs.ID
where (ec.EmployeeID = @Employee or @Employee is null)
and (ec.coursessetupID = @coursessetupID or @coursessetupID is null)










GO
/****** Object:  StoredProcedure [HR].[EmployeeDefinitionReportI]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [HR].[EmployeeDefinitionReportI] 
(
@EmpID int

)
as

select
 e.FirstNameAr+' '+e.MiddleNameAr+' '+e.LastNameAr as EmployeeAr,
 e.FirstNameEn+' '+e.MiddleNameEn+' '+e.LastNameEn as EmployeeEn,
 e.NationalID,
 e.JoiningDate,
 HR.Jobs.JobName,
 HR.Jobs.JobNameEn, 
 empSub.NameEn DepartmentEN,
 empSub.Name Department,
 Nationalities.Name Nationalities,
 Nationalities.NameEn NationalitiesEN

 from Nursing.Employee E
	join HR.SubDepartment empSub on empSub.ID = E.SubDepartmentId
	join HR.Jobs on E.JobId = Jobs.Id
	join Registration.Nationalities Nationalities on Nationalities.id = E.Nationality
	WHERE E.Id=@EmpID
GO
