/****** Object:  StoredProcedure [HR].[EmployeeGrant]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[EmployeeGrant] 
@GrantID int,
@FromDate varchar(20),
@ToDate varchar(20), 
@EmpID int,
@GrantsType int 
as
Begin

if(@GrantID=0)
set @GrantID =NULL
if(@GrantsType=-1)
set @GrantsType =NULL
	select SocialServiceMemo.GrantID, e.FirstName+' '+e.MiddleName+' '+e.LastName as Employee,ec.GrantValue ,Grants.NameAr,ec.[Description],CAST(ec.RequestDate as date) as RequestDate
			
			, cast( e.FirstName+' '+e.MiddleName+' '+e.LastName as nvarchar(500)) as EmployeeName
			from HR.EmployeeGrants ec  join Nursing.Employee e on ec.EmployeeID=e.Id
		left 	join PayRoll.Grants on Grants.ID = ec.GrantType
			left JOIN hr.SocialServiceMemo ON ec.ID = HR.SocialServiceMemo.GrantID 
			where 
			 SocialServiceMemo.ISLoan=0 and
		(@EmpID IS NULL or  e.Id = @EmpID )and 
			(@GrantsType IS NULL or ec.GrantType = @GrantsType) and 
