CREATE procEDURE [HR].[EmployeeJobHistoryReport]

(@dateTo nvarchar(50) = null
,@dateFrom nvarchar(50) = null
, @EmployeeID int = null )

AS
BEGIN

select emp.[Id],
	[EmployeeCode] ,
	emp.[FirstNameEn]+' '+emp.[MiddleNameEn]+' '+ coalesce(emp.BeforeLastNameEn,'')+' '+emp.[LastNameEn]  as FullName,
	emp.[FirstNameAr]+' '+emp.[MiddleNameAr]+' '+ coalesce(emp.BeforeLastNameAr,'')+' '+emp.[LastNameAr]  as FullNameAr,

	emp.[Type],
	emp.[IsActive],
	emp.[JobId],
	emp.[EmpDesignation],
    emp.[MilitaryState],
	cast (emp.MilitaryStateEndDate as Date ) As MilitaryStateEndDate,
	[CardNumber],
     cast (emp.BirthDate as Date ) As BirthDate,
	emp.[EmergencyContactPhone],
	emp.[LocalAddress1],
	emp.[LocalAddress2],
	emp.[LocalAddress3],
	emp.[LocalAddress4],
	Case emp.[Gender] 
	  when 1 then 'Male'
	  when 2 then 'Female'
	  else 'other'
	  end,
	emp.[Nationality],
	emp.[MaritalStatus],
