GO

CREATE proc [HR].[EmployeeLoan] 
@LoanID int,
@FromDate varchar(20),
@ToDate varchar(20) ,
@EmpID int
as
Begin


if(@LoanID=0)
set @LoanID =NULL
if(@EmpID = 0 )
set @EmpID =NULL

			select distinct ec.ID, e.FirstNameAr+' '+e.MiddleNameAr+' '+e.LastNameAr as Employee,
			ec.LoanValue  ,
			ec.[Description],
			CAST(ec.RequestDate as date) as RequestDate,
			empSub.Name as empDept
			,e.BasicSalary,
			ISNULL(
			(select  sum(EID.InstallmentAmount) from HR.EmployeeInstallment EI join HR.EmployeeInstallmentDetail EID on EI.ID=EID.EmployeeInstallmentID 
			 where ei.EmployeeID=e.Id and EID.IsPaied=0),0) as TradInstalments
			,eCo.FirstNameAr+' '+eCo.MiddleNameAr+' '+eCo.LastNameAr  as CoName ,
			 coSub.Name ,ec.loanInstallments,ec.loanInstallmentValue,ISNULL((select SocialServiceMemo.result from HR.SocialServiceMemo
