CREATE proc [HR].[EmployeeVacationValueReport](@DateFrom NVARCHAR(20),
@DateTo NVARCHAR(20),
@EmpID int,
@DeptID int
							    )
AS
BEGIN

select emp.id as EmpID, emp.EmployeeCode , 
isnull(emp.FirstName , ' ') + ' '+ isnull(emp.MiddleName , ' ' ) +' '+ 
isnull(emp.BeforeLastName, ' ')+ ' '+isnull(emp.LastName,' ' )as EmpName
	,
	isnull(emp.FirstNameAr , ' ') + ' '+ isnull(emp.MiddleNameAr , ' ' ) +' '+ 
isnull(emp.BeforeLastNameAr, ' ')+ ' '+isnull(emp.LastNameAr,' ' )as EmpNameAr , 
isnull(emp.FirstNameEn , ' ') + ' '+ isnull(emp.MiddleNameEn , ' ' ) +' '+ 
isnull(emp.BeforeLastNameEn, ' ')+ ' '+isnull(emp.LastNameEn,' ' )as EmpNameEn,
emp.JoiningDate,nat.Name as NatName,nat.NameEn as natNameEN,
dept.ID as DeptID,dept.Code as DeptCode,Dept.Name as DeptName,dept.NameEn as deptNameEn,
isnull(sum(JournalDet.Debit),0) Debit,
isnull(sum(JournalDet.Credit),0)as Credit,
0 as Salary,
0 as VacDays
 
 from [Nursing].Employee emp
inner join [hr].Department dept
on emp.SubDepartmentId=dept.ID
inner join [Registration].Nationalities Nat 
on emp.Nationality=nat.id
inner join gl.JournalDetails JournalDet
on emp.VacAccount=JournalDet.AccountId
inner join gl.Journal Journal on 
JournalDet.JournalId=Journal.JournalId
 
where Journal.Date >= CONVERT(datetime,@DateFrom,103)
and  Journal.Date <= CONVERT(datetime,@DateTo,103)
and (emp.Id = @EmpID or @EmpID is null)
 and (emp.SubDepartmentId = @DeptID or @DeptID is null)
group by 
emp.id , emp.EmployeeCode , 
 
dept.ID ,dept.Code ,Dept.Name ,dept.NameEn ,
emp.FirstName ,emp.MiddleName,emp.BeforeLastName,
emp.LastName,emp.FirstNameAr ,emp.MiddleNameAr ,
emp.BeforeLastNameAr,emp.LastNameAr , emp.FirstNameEn , emp.MiddleNameEn , 
emp.BeforeLastNameEn,emp.LastNameEn,emp.JoiningDate,nat.Name ,nat.NameEn



END 




GO
