/****** Object:  StoredProcedure [HR].[InComplteFilesByDept]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 CREATE proc [HR].[InComplteFilesByDept](@TotFile decimal(18,2))
as
begin
select SubDepartment.NameEn, SubDepartment.Name ,count(HDEF.ID) NoOfFiles ,convert(decimal(18,2), count(HDEF.ID)/@TotFile) Percentage from 
  HR.HieringDocumentEmployeeFile HDEF  
 inner join HR.HieringDocumentEmployee on HDEF.HieringDocumentEmployeeID=HieringDocumentEmployee.ID
inner join Nursing.Employee on HieringDocumentEmployee.EmpLoyeeID = Employee.Id 
inner join HR.SubDepartment on Employee.SubDepartmentId =SubDepartment.ID 
where HDEF.HieringDocumentFile is null or HDEF.HieringDocumentFile=''
group by  SubDepartment.NameEn, SubDepartment.Name
order by count(HDEF.ID) desc
end
GO
/****** Object:  StoredProcedure [HR].[JobDetailsReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[JobDetailsReport] 
as
select jobdetailsCode,jobdetailsDescription,SalaryFrom,SalaryTo,u.Name as currency,qulification,experinces,c.Name as costcenter,j.JobName as jobname 
from HR.JobDetails jd left join HR.Jobs j on jd.JobID=j.Id
left join ApplicationSetup.CostCenter c on jd.costcenterID=c.Id
left join ApplicationSetup.Currency u on jd.currency=u.Id





GO
/****** Object:  StoredProcedure [HR].[JobToBranshReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[JobToBranshReport] (@Employee int=null,@department int=null,@job int=null,@branch int=null)
as
select e.FirstName+' '+e.MiddleName+' '+e.LastName as Employee,cc.Name as Department,o.Name,b.NameAr
from HR.JobToBransh j LEFT JOIN ApplicationSetup.CostCenter cc on j.departemetID=cc.Id
left join HR.Branches b on j.BranchID=b.ID left join Nursing.Employee e on j.EmployeeID=e.Id
left join HR.Unit_Job o on j.jobID=o.Id
where (j.EmployeeID = @Employee or @Employee is null)
and (j.departemetID = @department or @department is null)
and (j.jobID = @job or @job is null)
and (j.BranchID = @branch or @branch is null)





GO
