CREATE procEDURE [HR].[RepAbsentDays] --0,'2019-01-01','2023-02-21',0
	@EmployeeID int null,
	@DateFrom datetime null,
	@DateTo datetime null,
	@DepartmentId int null
AS
Declare @WeekEnd INT = 0

SET @WeekEnd = (DATEDIFF(day,@DateFrom,@DateTo)+1) /CAST(7 AS DECIMAL(12,0));

select distinct absentRepo.EmployeeCode,
absentRepo.EmployeeName,
absentRepo.ActualAbsentDays -- AbsentDays
,

absentRepo.DeptName,
--ActualAbsentDays DayswithWeekend + الاجازات الرسمية 
-- absentRepo.ActualAbsentDays التى لم يحضر فيها الموظف 
(DATEDIFF(day,@DateFrom,@DateTo)+1) - ActualAbsentDays 
---absentRepo.ActualAbsentDays   
 as ExpectedPayableDays
from (
select
EmployeeCode,
ISNULL(FirstNameEn,'')+' '+ISNULL(MiddleNameEn,'')+' '+ISNULL(LastNameEn,'') as EmployeeName,
subDept.NameEn as DeptName,

--when IsNull(AbsentDays,0) < (HolidayPerPeriod.NumberOfHolidayDaysPerPeriod
--+HolidayonMonth.NumberOfHolidayDaysPerMonth
--)
--then  --IsNull(AbsentDays,
--(DATEDIFF(day,@DateFrom,@DateTo)+1) - HolidayPerPeriod.NumberOfHolidayDaysPerPeriod
--- HolidayonMonth.NumberOfHolidayDaysPerMonth 

----then (DATEDIFF(day,@DateFrom,@DateTo)+1) - (HolidayPerPeriod.NumberOfHolidayDaysPerPeriod+HolidayonMonth.NumberOfHolidayDaysPerMonth )
--else (HolidayPerPeriod.NumberOfHolidayDaysPerPeriod
--+HolidayonMonth.NumberOfHolidayDaysPerMonth
--) -IsNull(AbsentDays,(DATEDIFF(day,@DateFrom,@DateTo)+1)) 
--end as ActualAbsentDays,
ISNULL(
AbsentDays-
(ISNULL(HolidayPerPeriod.NumberOfHolidayDaysPerPeriod,0)
+ISNULL(HolidayonMonth.NumberOfHolidayDaysPerMonth,0)
),0)
ActualAbsentDays,


emp.Id as employeeId,
subDept.ID as departmentId
from [Nursing].[Employee] as emp

left join [HR].[SubDepartment] subDept on subDept.ID =emp.SubDepartmentId

cross join (select isnull(sum(holperiod.PeriodDays),0) as NumberOfHolidayDaysPerPeriod 
from hr.HolidayYear holyear
