CREATE procEDURE [HR].[RepCurrentEmployee]

(
@DateFrom datetime = null,
@DateTo datetime = null, 
@UserBranchId int = null 
,@EmployeeID int = null  
)

AS
SELECT DISTINCT Emp.[Id],[EmployeeCode],Emp.BranchId ,HR.Branches.NameEn as BranchName ,
       [FirstName],[MiddleName],
       [LastName] [EmployeeCode],
	   [FirstName]+' '+[MiddleName]+' '+COALESCE([BeforeLastName], '')+' '+[LastName] as FullName,
	 ISNULL(  [FirstNameEn] , '' )+' '+ ISNULL([MiddleNameEn] ,'' )+' '+ISNULL(BeforeLastNameEn ,'')+' '+ ISNULL([LastNameEn] , '') as EngName  ,
	   [Type],[IsActive],
	   joblevels.[JobId],
	   [EmpDesignation]
      ,[EmpGrade],[EmergencyContactName],
	   [EmergencyContactRelation],
	   [EmergencyContactPhone],[LocalAddress1],
	   
	   [LocalAddress2]
	  ,[LocalAddress3],[LocalAddress4],
	  [PermanentAddress1],[PermanentAddress2],
