create   procEDURE [HR].[RepCurrentEmployeeAr]

(
@DateFrom datetime = null,
@DateTo datetime = null, 
@UserBranchId int = null,
@EmployeeID int = null  
)

AS
SELECT DISTINCT 
       Emp.[Id],
       [EmployeeCode]            AS N'كود الموظف',
       Emp.BranchId              AS N'رقم الفرع',
       HR.Branches.NameAr        AS N'اسم الفرع',
       [FirstName]               AS N'الاسم الأول',
       [MiddleName]              AS N'الاسم الأوسط',
       [LastName]                AS N'اسم العائلة',
       [FirstName]+' '+[MiddleName]+' '+COALESCE([BeforeLastName], '')+' '+[LastName] AS N'الاسم بالكامل',
       JobLevels.[JobId]         AS N'رقم الوظيفة',
       [EmpDesignation]          AS N'المسمى الوظيفي',
       [EmpGrade]                AS N'الدرجة الوظيفية',
       [EmergencyContactName]    AS N'اسم جهة الاتصال للطوارئ',
       [EmergencyContactRelation] AS N'صلة القرابة',
       [EmergencyContactPhone]   AS N'هاتف جهة الاتصال للطوارئ',
       [LocalAddress1]           AS N'العنوان المحلي 1',
       [LocalAddress2]           AS N'العنوان المحلي 2',
       [LocalAddress3]           AS N'العنوان المحلي 3',
       [LocalAddress4]           AS N'العنوان المحلي 4',
       [PermanentAddress1]       AS N'العنوان الدائم 1',
       [PermanentAddress2]       AS N'العنوان الدائم 2',
       [PermanentAddress3]       AS N'العنوان الدائم 3',
       [PermanentAddress4]       AS N'العنوان الدائم 4',
       CAST([BirthDate] AS DATE) AS N'تاريخ الميلاد',
       [Gender]                  AS N'النوع',
       [Nationality]             AS N'الجنسية',
       [MaritalStatus]           AS N'الحالة الاجتماعية',
       CAST([AppiontmentDate] AS DATE) AS N'تاريخ التعيين',
       CAST([JoiningDate] AS DATE) AS N'تاريخ الالتحاق',
       CAST([ConfermationDate] AS DATE) AS N'تاريخ التثبيت',
       [ProbationPeriod]         AS N'فترة التجربة',
       [Remark]                  AS N'ملاحظات',
