/****** Object:  StoredProcedure [HR].[RepEarlyHours]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [HR].[RepEarlyHours]
	-- Add the parameters for the stored procedure here
	@FromDate datetime null,
	@Todate datetime null,
	@Department int = null,
	@Employee int = null

AS
	
	SELECT IsNULL(emp.FirstNameEn,'') + ' ' +  IsNULL(emp.MiddleNameEn,'')  + ' ' +  IsNULL(emp.BeforeLastNameEn,'') + ' ' +  IsNULL(emp.LastNameEn,'') as EmployeeFullName ,
	emp.EmployeeCode as Empcode ,
	ISNULL(convert(nvarchar(50),FORMAT(cast(Att.AttendanceDate as datetime),'dd/MM/yyyy')),'Absence') as ATTDate ,
	Sesion.SessionName,  
	att.EarlyLeaveMinutes as LeaveEarlyHours,
	convert(nvarchar,Format(cast( Sesion.StartTime as datetime),'hh:mm:ss')) +' - '+
	 convert(nvarchar,Format(cast( Sesion.EndTime as datetime),'hh:mm:ss')) as SheftTime,
	 subDep.NameEn as DepartmentName,
	  Att.LeaveDate
	,ISNULL(convert(nvarchar(50),Format(cast( Att.TimeFrom as datetime),'hh:mm:ss tt')),'Absence') as timein , 
	ISNULL(convert(nvarchar,Format(cast( Att.TimeTo as datetime),'hh:mm:ss tt')),'Not Declared') as Timeoutt,
	DATEDIFF(MINUTE,
	DATEADD(DAY, DATEDIFF(DAY,0,convert(datetime, Att.AttendanceDate)) ,convert(datetime, Att.TimeFrom)),
	DATEADD(DAY, DATEDIFF(DAY,0,convert(datetime, Att.LeaveDate)) ,convert(datetime, Att.TimeTo))) as TotalHours


	FROM Nursing.Employee emp 
	left outer join PayRoll.AttendanceSchedule Att on emp.id = Att.EmployeeID
	left join  HR.EmployeeShift empshift on emp.Id= empshift.EmployeeID
	 join Registration.Sessions Sesion on Sesion.Id=emp.SessionID
	 inner join HR.SubDepartment subDep on emp.SubDepartmentId = subDep.Id

where 
--(emp.IsActive=1 and emp.TerminateID is null)
(att.EarlyLeaveMinutes > 0)
and
((@Department is null) or(subDep.ID=@Department))
 and
