/****** Object:  StoredProcedure [HR].[RepEmployeeGrants]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create procEDURE  [HR].[RepEmployeeGrants]
@grantId int  null,
@datefrom datetime null,
@dateto datetime null
as
begin
select 
distinct
Emp.FirstNameAr+' '+Emp.MiddleNameAr +' '+Emp.LastNameAr as employeeName
,Emp.EmployeeCode
,SubDep.Name
,Emp.boxmembershipnumber
,Grants.NameAr
,EmpGrants.Description
,(case 
when ISSalary=1 then N'الراتب'
when ISSalary=0 then N'فوري'
end)as GrantPaymentMethod
,EmpGrants.RequestDate
,
(case 
when EmpGrants.status=1 then N'انتظار الاعتماد'
when EmpGrants.status=2 then N'معتمد'
when EmpGrants.status=3 then N'تمت الموافقة (مدير الخدمة الأجتماعية)'
when EmpGrants.status=4 then N'تم إدخال نتيجة اللجنة'
when EmpGrants.status=5 then N'تم الرفض'
when EmpGrants.status=6 then N'ملغي'
ELSE ''
end) as RequestStatus
,SSM.result
,SSM.ResultDate
,EmpGrants.RejectReason
from [HR].[EmployeeGrants] EmpGrants
inner join [Nursing].Employee Emp on Emp.Id = EmpGrants.EmployeeID
inner join [HR].SubDepartment SubDep on SubDep.ID = Emp.SubDepartmentId
inner join [PayRoll].[Grants] Grants on Grants.ID = EmpGrants.GrantType
left join [HR].SocialServiceMemo SSM on SSM.GrantID = EmpGrants.GrantType
where 
EmpGrants.GrantType=@grantId and
EmpGrants.RequestDate between @datefrom and @dateto

end
GO
