䰀 漀爀  嬀䔀洀瀀氀漀礀攀攀崀⸀嬀䨀漀戀䤀搀崀 㸀㴀 䀀䨀漀戀䘀爀洀⤀ 愀渀搀 ഀ਀ऀऀऀ⠀䀀䨀漀戀吀漀 䤀匀 一唀䰀䰀 漀爀  嬀䔀洀瀀氀漀礀攀攀崀⸀嬀䨀漀戀䤀搀崀 㰀㴀 䀀䨀漀戀吀漀⤀ 愀渀搀ഀ਀ऀऀऀ⠀䀀䐀攀瀀琀䘀爀洀 䤀匀 一唀䰀䰀 漀爀  嬀䔀洀瀀氀漀礀攀攀崀⸀匀甀戀䐀攀瀀愀爀琀洀攀渀琀䤀搀 㸀㴀 䀀䐀攀瀀琀䘀爀洀⤀ 愀渀搀 ഀ਀ऀऀऀ⠀䀀䐀攀瀀琀吀漀 䤀匀 一唀䰀䰀 漀爀  嬀䔀洀瀀氀漀礀攀攀崀⸀匀甀戀䐀攀瀀愀爀琀洀攀渀琀䤀搀 㰀㴀 䀀䐀攀瀀琀吀漀⤀ഀ਀ഀ਀甀渀椀漀渀ഀ਀ഀ਀ऀഀ਀
		SELECT
			[Employee].[Id] AS [EmployeeId]
			, [Employee].[EmployeeCode]
			, [Employee].FirstNameEn
			, [Employee].[MiddleNameEn]
			, [Employee].[LastNameEn]
			, [Employee].[FirstName]
			, [Employee].[MiddleName]
			, [Employee].[LastName]
			,JobLevels.BasicSalary
			, [Jobs].[Id] AS [JobId]
			, [Jobs].[JobCode]
			, [Jobs].[JobName]
			, [Jobs].[JobNameEN]
			, [SubDepartment].[Id] AS [DepartmentId]
			, [SubDepartment].[Code] AS [DepartmentCode]
			, [SubDepartment].[Name] AS [CostCenterName]
			, [SubDepartment].[NameEn] AS [CostCenterNameEn]
			, [SE].[Id] AS [SubElementId]
			, [SE].[Code] AS [SubElementCode]
			, [SE].[NameArabic] AS [SubElementNameArabic]
			, [SE].[NameEnglish] AS [SubElementNameEnglish]
			, [ME].[ID] AS [MainElementId]
			, [ME].[Code] AS [MainElementCode]
			, [ME].[NameArabic] AS [MainElementNameArabic]
			, [ME].[NameEnglish] AS [MainElementNameEnglish]
			, [ME].[Type] AS [MainElementType]
			, [Vars].Value 
			,ISNULL((select Sum(VarsSubM.Value) from HR.EmployeeSalaryVariablesVar VarsSubM
			inner join HR.SubElements SEM on VarsSubM.SubElementID = SEM.ID
inner join HR.MainElements MEM on SEM.MainElementID = MEM.ID
			 where  VarsSubM.EmpID= Vars.EmpID and VarsSubM.ID_Close=@Month and MEM.[Type]=2 ),0) TM

			 ,ISNULL((select Sum(VarsSub.Value) from HR.EmployeeSalaryVariablesVar VarsSub
			inner join HR.SubElements SED on VarsSub.SubElementID = SED.ID
inner join HR.MainElements MED on SED.MainElementID = MED.ID
			 where  VarsSub.EmpID= Vars.EmpID and VarsSub.ID_Close=@Month and MED.[Type]=1 ),0) TD
			  
	 from 
	 
	 
	 HR.EmployeeSalaryVariablesVar Vars
inner join HR.SubElements SE on Vars.SubElementID = SE.ID
inner join HR.MainElements ME on SE.MainElementID = ME.ID
inner join Nursing.Employee  on Vars.EmpID =[Employee].Id
inner join HR.Jobs on [Employee].JobId =Jobs.Id
left join hr.JobLevels on JobLevels.JobId=Jobs.Id and JobLevels.id=Employee.JobDegreeID
inner join HR.SubDepartment on [Employee].SubDepartmentId =SubDepartment.ID
where Employee.ExcludeFromPayroll= 0 and Vars.ID_Close=@Month and
			(@EmpFrm IS NULL or  [Employee].[Id] >= @EmpFrm) and 
