		@Month nvarchar = null
	AS
	BEGIN



		WITH [DepartmentsVariables] AS
			(
				SELECT
					[Employee].[Id] AS [EmployeeId]
					, [SubElements].*
					, [SalaryVariablesDepartment].Value
				FROM
					[Nursing].[Employee]
					INNER JOIN [HR].[SubDepartment] ON [Employee].SubDepartmentId = [SubDepartment].[Id]
					INNER JOIN [HR].[Department] ON [SubDepartment].[DepartmentId] = [Department].[Id]
					INNER JOIN [HR].[SalaryVariablesDepartment] ON [Department].[ID] = [SalaryVariablesDepartment].[DepartmentID]
					INNER JOIN [HR].[SubElements] ON [SalaryVariablesDepartment].[SubElementID] = [SubElements].[Id]
					
			)
			, [JobsVariables] AS
			(
				SELECT
					[Employee].[Id] AS [EmployeeId]
					, [SubElements].*
					, [SalaryVariablesJobs].Value
				FROM
					[Nursing].[Employee]
					INNER JOIN [Hr].[SalaryVariablesJobs] ON [Employee].[JobId] = [SalaryVariablesJobs].[JobID]
					INNER JOIN [HR].[SubElements] ON [SalaryVariablesJobs].[SubElementID] = [SubElements].[Id]
			)
			, [EmployeeVariables] AS
			(
				SELECT
					[Employee].[Id] AS [EmployeeId]
					, [SubElements].*
					, [EmployeeSalaryVariables].Value
				FROM
					[Nursing].[Employee]
					INNER JOIN [HR].[EmployeeSalaryVariables] ON [Employee].[Id] = [EmployeeSalaryVariables].[EmpID]
					INNER JOIN [HR].[SubElements] ON [EmployeeSalaryVariables].[SubElementID] = [SubElements].[Id]
			)
			,[EmployeeSalaryVariablesVar] AS
			(
				SELECT
					[Employee].[Id] AS [EmployeeId]
					, [SubElements].*
					, [EmployeeSalaryVariablesVar].Value
				FROM
					[Nursing].[Employee]
					INNER JOIN [HR].[EmployeeSalaryVariablesVar] ON [Employee].[Id] = [EmployeeSalaryVariablesVar].[EmpID]
					INNER JOIN [HR].[SubElements] ON [EmployeeSalaryVariablesVar].[SubElementID] = [SubElements].[Id]
					where variableTypeId is null and [Month]=@Month
			)
			,[EmployeeSalaryVariablesVarAdvance] AS
			(
				SELECT
					[Employee].[Id] AS [EmployeeId]
					, [SubElements].*
					, [EmployeeSalaryVariablesVar].Value
				FROM
