攀洀攀渀琀猀崀 伀一 嬀吀礀瀀攀猀䤀渀猀甀爀愀渀挀攀崀⸀嬀倀䔀䘀开䘀椀砀攀搀䐀攀搀甀挀琀椀漀渀崀 㴀 嬀匀甀戀䔀氀攀洀攀渀琀猀崀⸀嬀䤀搀崀ഀ਀ऀऀऀ⤀ഀ਀ऀऀऀⰀ 嬀䤀渀猀甀爀愀渀挀攀䜀爀漀甀瀀吀礀瀀攀猀崀 䄀匀ഀ਀ऀऀऀ⠀ഀ਀ऀऀऀऀ匀䔀䰀䔀䌀吀ഀ਀ऀऀऀऀऀ嬀䔀洀瀀氀漀礀攀攀崀⸀嬀䤀搀崀 䄀匀 嬀䔀洀瀀氀漀礀攀攀䤀搀崀ഀ਀ऀऀऀऀऀⰀ 嬀匀甀戀䔀氀攀洀攀渀琀猀崀⸀⨀ഀ਀
					, case when (select sum(value) from [AllSubElements] where [Staus]=2 and [Type]=2)<[InsuranceOffice].MonthlyMaxChangedSalary 
					then (select sum(value) from [AllSubElements] where [Staus]=2 and [Type]=2)*([TypesInsurance].PercentageEmployeeFromChanged/100)
					else [InsuranceOffice].MonthlyMaxChangedSalary end  as Value
				FROM
					[Nursing].[Employee]
					INNER JOIN [HR].[InsuranceGroupDetail] ON [Employee].[InsuranceID] = [InsuranceGroupDetail].[InsuranceGroupId]
					INNER JOIN [HR].[InsuranceOfficeAndTypeInsurance] ON [InsuranceGroupDetail].[InsuranceOfficeAndTypeInsuranceId] = [InsuranceOfficeAndTypeInsurance].[Id]
					INNER JOIN [HR].[InsuranceOffice] ON [InsuranceOfficeAndTypeInsurance].[InsuranceOfficeID] = [InsuranceOffice].[Id]
					INNER JOIN [HR].[TypesInsurance] ON [InsuranceOfficeAndTypeInsurance].[InsuranceOfficeID] = [TypesInsurance].[Id]
					INNER JOIN [HR].[SubElements] ON [TypesInsurance].[PEC_FixedDeduction] = [SubElements].[Id]
			)
			
			, [TotalAllSubElements] AS
			(
				(SELECT * FROM [DepartmentsVariables])
				UNION
				(SELECT * FROM [JobsVariables])
				UNION
				(SELECT * FROM [EmployeeVariables])
				UNION
				(SELECT * FROM [InsuranceGroupOffice])
				UNION
				(SELECT * FROM [InsuranceGroupTypes])
				UNION
				(SELECT * FROM [TaxDistinctionDetails])
			)
		SELECT
			[Employee].[Id] AS [EmployeeId]
			, [Employee].[EmployeeCode]
			, [Employee].[FirstName]
			, [Employee].[MiddleName]
			, [Employee].[LastName]
			, [Jobs].[Id] AS [JobId]
			, [Jobs].[JobCode]
			, [Jobs].[JobName]
			, [Jobs].[JobNameEN]
			, [Department].[Id] AS [DepartmentId]
			, [Department].[Code] AS [DepartmentCode]
			, [Department].[Name] AS [CostCenterName]
			, [TotalAllSubElements].[Id] AS [SubElementId]
			, [TotalAllSubElements].[Code] AS [SubElementCode]
			, [TotalAllSubElements].[NameArabic] AS [SubElementNameArabic]
			, [TotalAllSubElements].[NameEnglish] AS [SubElementNameEnglish]
			, [MainElements].[ID] AS [MainElementId]
			, [MainElements].[Code] AS [MainElementCode]
