䤀渀猀甀爀愀渀挀攀伀昀昀椀挀攀䤀䐀崀 㴀 嬀䤀渀猀甀爀愀渀挀攀伀昀昀椀挀攀崀⸀嬀䤀搀崀ഀ਀ऀऀऀऀऀ䤀一一䔀刀 䨀伀䤀一 嬀䠀刀崀⸀嬀吀礀瀀攀猀䤀渀猀甀爀愀渀挀攀崀 伀一 嬀䤀渀猀甀爀愀渀挀攀伀昀昀椀挀攀䄀渀搀吀礀瀀攀䤀渀猀甀爀愀渀挀攀崀⸀嬀䤀渀猀甀爀愀渀挀攀伀昀昀椀挀攀䤀䐀崀 㴀 嬀吀礀瀀攀猀䤀渀猀甀爀愀渀挀攀崀⸀嬀䤀搀崀ഀ਀
					INNER JOIN [HR].[SubElements] ON [TypesInsurance].[PEC_FixedDeduction] = [SubElements].[Id]
			)
			
			, [TotalAllSubElements] AS
			(
				(SELECT * FROM [DepartmentsVariables])
				UNION
				(SELECT * FROM [JobsVariables])
				UNION
				(SELECT * FROM [EmployeeVariables])
				UNION
				(SELECT * FROM [InsuranceGroupOffice])
				UNION
				(SELECT * FROM [InsuranceGroupTypes])
				UNION
				(SELECT * FROM [TaxDistinctionDetails])
			)
		SELECT
			[Employee].[Id] AS [EmployeeId]
			, [Employee].[EmployeeCode]
			, [Employee].[FirstName]
			, [Employee].[MiddleName]
			, [Employee].[LastName]
			, [Jobs].[Id] AS [JobId]
			, [Jobs].[JobCode]
			, [Jobs].[JobName]
			, [Jobs].[JobNameEN]
			, [Department].[Id] AS [DepartmentId]
			, [Department].[Code] AS [DepartmentCode]
			, [Department].[Name] AS [CostCenterName]
			, [TotalAllSubElements].[Id] AS [SubElementId]
			, [TotalAllSubElements].[Code] AS [SubElementCode]
			, [TotalAllSubElements].[NameArabic] AS [SubElementNameArabic]
			, [TotalAllSubElements].[NameEnglish] AS [SubElementNameEnglish]
			, [MainElements].[ID] AS [MainElementId]
			, [MainElements].[Code] AS [MainElementCode]
			, [MainElements].[NameArabic] AS [MainElementNameArabic]
			, [MainElements].[NameEnglish] AS [MainElementNameEnglish]
			, [MainElements].[Type] AS [MainElementType]
			,case when [MainElements].[Type]=1 then 
			 -1*[TotalAllSubElements].Value else [TotalAllSubElements].Value end as Value
		FROM
			[Nursing].[Employee]
			INNER JOIN [HR].[Jobs] ON [Employee].[JobId] = [Jobs].[Id]
			INNER JOIN [HR].[SubDepartment] ON [Employee].SubDepartmentId = [SubDepartment].[Id]
			INNER JOIN [HR].[Department] ON [SubDepartment].[DepartmentId] = [Department].[ID]
			LEFT OUTER JOIN [TotalAllSubElements] ON [Employee].[Id] = [TotalAllSubElements].[EmployeeId]
			LEFT OUTER JOIN [HR].[MainElements] ON [TotalAllSubElements].[MainElementID] = [MainElements].[Id]
		WHERE
			(@EmpFrm IS NULL or  [Employee].[Id] >= @EmpFrm) and 
			(@EmpTo IS NULL or  [Employee].[Id] <= @EmpTo) and 
