/****** Object:  StoredProcedure [HR].[RepEmployeeSalaryDetailsM]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

	CREATE procEDURE [HR].[RepEmployeeSalaryDetailsM] 
		@EmpFrm int = null,
		@EmpTo int = null,
		@JobFrm int = null,
		@JobTo int = null,
		@DeptFrm int = null,
		@DeptTo int = null,
		@Month nvarchar = null
	AS
	BEGIN


	 select * from [hr].EmployeeSalaryVariablesVar inner join 
			[Nursing].[Employee]
			on [hr].EmployeeSalaryVariablesVar.EmpID=[Nursing].[Employee].Id
			 
			
				WHERE
			(@EmpFrm IS NULL or  [Employee].[Id] >= @EmpFrm) and 
			(@EmpTo IS NULL or  [Employee].[Id] <= @EmpTo) and 
			(@JobFrm IS NULL or  [Employee].[JobId] >= @JobFrm) and 
			(@JobTo IS NULL or  [Employee].[JobId] <= @JobTo) and
			(@DeptFrm IS NULL or  [Employee].SubDepartmentId >= @DeptFrm) and 
			(@DeptTo IS NULL or  [Employee].SubDepartmentId <= @DeptTo)
	END




GO
