/****** Object:  StoredProcedure [HR].[RepEmployees'Vacations]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

	CREATE Procedure [HR].[RepEmployees'Vacations] 
		@EmpID	int,
        @FromDate datetime,
        @ToDate dateTime
	AS
	BEGIN
		--EmployeeName
	Select 
	Vacation.Reason,
	 isnull(Emp.FirstNameEn,' ') +' '+ ISnull(Emp.MiddleNameEn,' ' )+' '+ ISnull(Emp.BeforeLastNameEn,' ')+' '+ ISnull(Emp.LastNameEn,' ') as EmpName
	    	,--Cast(Vacation.vacStartDate   as date ) vacStartDate
			FORMAT (Vacation.vacStartDate, 'dd/MM/yyyy ')vacStartDate
			, FORMAT (Vacation.vacEndDate, 'dd/MM/yyyy ') vacEndDate
          --,Cast(Vacation.vacEndDate as date ) vacEndDate 
		,
		
	'VacationType'  =Case
		
		when HR.VacationSettings.VacationType = 1 then 'Regular Vacation' 
        when HR.VacationSettings.VacationType=2 then 'Casual Vacation' 
        when HR.VacationSettings.VacationType =6 then 'NoSallary' 
		when HR.VacationSettings.VacationType = 3 then 'Sick Leave' 
         when HR.VacationSettings.VacationType=4 then 'Haj Vacation' 
         when HR.VacationSettings.VacationType =5 then 'Laying Vacation'
		end    ,
		Vacation.Status
	   -- ,Cast(Vacation.LastModifiedDate as date) ApprovedDate
	   ,FORMAT (Vacation.LastModifiedDate, 'dd/MM/yyyy ') ApprovedDate
		,Vacation.vacDays 
		,HR.VacationSettings.vac_NameAr as vac_NameAr
		,HR.VacationSettings.vac_NameEn as vac_NameEn
		,Vacation.vacID 
		,[HR].[GetRemainingDaysUpdate] (Vacation.EmpID ,Vacation.vacID  ,Vacation.Year ,Vacation.vacEndDate ) as RemainingDays
	-- DaysAfter Calculations
	from    Nursing.Employee As Emp
	
inner Join  HR.EmployeeVacations As Vacation
	 on  Emp.Id = Vacation.EmpID
	 inner join  HR.VacationSettings 
	 on Vacation.vacID = HR.VacationSettings.ID and 
	 Vacation.vacStartDate between    @FromDate and @ToDate  and
	  Vacation.EmpID = @EmpID
	-- exec sp_executesql @query
	END



