SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procEDURE  [HR].[RepIncentiveBonuses]
@JobId int  null,
@JobDegreeId int null,
@Year int null

as
begin
Declare @EmpAssessment  table(EmpID int,Year1  int , Year2 int,Year3 int,Year4 int,Year5 int )
insert into @EmpAssessment(EmpID,Year1,Year2,Year3,Year4,Year5)  EXEC [HR].[SP_EmployeeAssessment] @YY = @Year
 
 
 
 select Distinct
        EMP.[FirstNameEn] +' '+EMP.[MiddleNameEn]+' '+EMP.[LastNameEn] as EmployeeNameEn
	   ,EMP.[FirstNameAr]+' '+ EMP.[MiddleNameAr]+' '+ EMP.[LastNameAr] as EmployeeNameAr
	   ,EMP.JobId
	   ,Jobs.JobName
	   ,jobs.JobNameEn
	   ,JD.JobdegreeDescription
	   ,JD.JobdegreeDescriptionAr
	   ,EMP.JobDegreeID
	   ,EMP.BirthDate
	   ,EMP.JoiningDate
	   ,Penality.NumberofDays
	   ,JG.NameAr
	   ,JG.NameEn
	   ,Year1--small
	   ,Year2
	   ,Year3
	   ,Year4
	   ,Year5
  from [Nursing].[Employee] as EMP
  inner join [HR].Jobs as Jobs ON  Jobs.Id =Emp.JobId
  left join [HR].JobGroup JG on JG.ID = Jobs.JobGroupID
  left join [HR].JobDegree JD ON JD.ID = EMP.JobDegreeID
  left join  @EmpAssessment as EmpAssessment On EmpAssessment.EmpID = EMP.Id
  left join (
  select SUM(NumberofDyas) NumberofDays,EmployeeID from [HR].[Penalties]
  WHERE YEAR(PenaltyDate) IN(Cast(@Year as nvarchar(10)),Cast(@Year-1 as nvarchar(10)) ,Cast(@Year-2 as nvarchar(10)) ,Cast(@Year-3 as nvarchar(10)),Cast(@Year-4 as nvarchar(10)))
  GROUP BY EmployeeID) as Penality on Penality.EmployeeID= EMP.Id
  WHERE
    (@JobId IS NULL OR EMP.JobId = @JobId)
    AND (@JobDegreeId IS NULL OR EMP.JobDegreeID = @JobDegreeId);
 -- where  EMP.JobId =@JobId or Emp.JobDegreeID=ISNULL(@JobDegreeId,NULL)
 
 end

