CREATE procEDURE [HR].[RepLateHours] --'11-27-2022','11-28-2022',null,null
	-- Add the parameters for the stored procedure here
	@FromDate datetime null,
	@Todate datetime null,
	@Department int = null,
	@Employee int = null

AS
	begin
	SELECT 
	IsNULL(emp.FirstNameEn,'') + ' ' +  
	IsNULL(emp.MiddleNameEn,'')  + ' ' +  
	IsNULL(emp.BeforeLastNameEn,'') + ' ' +  
	IsNULL(emp.LastNameEn,'') as EmployeeFullName 
	---------------
	,emp.EmployeeCode as Empcode 
	,Sesion.SessionName,att.DelayMinutes as LateHours
	,convert(nvarchar(50),Format(cast( Sesion.StartTime as datetime),'hh:mm tt'))
	  +' - '+
	 convert(nvarchar,Format(cast( Sesion.EndTime as datetime),'hh:mm tt')) as SheftTime
