	             @EmployeeID int = null 

AS
BEGIN
	

select [Nursing].[Employee].[Id],
	[EmployeeCode] ,
	[Nursing].[Employee].[FirstNameEn]+' '+[MiddleNameEn]+' '+[LastNameEn] as FullName,
	[Type],
	[IsActive],
	[JobId],
