/****** Object:  StoredProcedure [HR].[ReportComprehensiveSocialResearchRequestFamilyMember]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[ReportComprehensiveSocialResearchRequestFamilyMember]
(
@ComprehensiveSocialResearchRequestID int
)
as

select ROW_NUMBER() over(order by id)RowNo, * 
,MonthlyIncomeIntegerPart = cast(MonthlyIncome AS int), MonthlyIncomeDecimalPart =round( MonthlyIncome - cast(MonthlyIncome AS int),2)
from hr.ComprehensiveSocialResearchRequestFamilyMember as cssrfm
where cssrfm.ComprehensiveSocialResearchRequestID=@ComprehensiveSocialResearchRequestID


GO
/****** Object:  StoredProcedure [HR].[ReportComprehensiveSocialResearchRequestProfessionalHistory]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [HR].[ReportComprehensiveSocialResearchRequestProfessionalHistory]
(
@ComprehensiveSocialResearchRequestID int
)
as

SELECT  ROW_NUMBER() over(order by id)RowNo,
      ID, 
	  ComprehensiveSocialResearchRequestID, 
	  ClientName, 
	  ClientAdress, 
	  Occupation, 
	  MonthlyWage, 
	  WorkStartDate=format(WorkStartDate,'dd/MM/yyyy','ar-EG'), 
	  WorkEndDate=format(WorkEndDate,'dd/MM/yyyy','ar-EG'), 
	  ResonsAndNotes, 
	  CAST(MonthlyWage AS int) AS MonthlyWageIntegerPart, 
                         ROUND(MonthlyWage - CAST(MonthlyWage AS int), 2) AS MonthlyWageDecimalPart
FROM            HR.ComprehensiveSocialResearchRequestProfessionalHistory AS cssrph
where cssrph.ComprehensiveSocialResearchRequestID=@ComprehensiveSocialResearchRequestID


GO
