/****** Object:  StoredProcedure [HR].[RepTimeAttendanceSheet]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procEDURE [HR].[RepTimeAttendanceSheet] 
	@EmployeeID int null,
	@DateFrom datetime null,
	@DateTo datetime null,
	@DepartmentId int null
AS

SELECT 
ISNULL(FirstNameEn,'')+' '+ISNULL(MiddleNameEn,'')+' '+ISNULL(LastNameEn,'') as EmployeeName,
emp.EmployeeCode,
subDept.NameEn,
emp.Id,
Format(cast( attendSchedule.AttendanceDate as date)    ,'dd/MM/yyyy') as AttendanceDate,
 
 convert(nvarchar(50),Format(cast( attendSchedule.TimeFrom as datetime),'hh:mm:ss tt')) as TimeFrom , 
 convert(nvarchar,Format(cast( attendSchedule.TimeTo as datetime),'hh:mm:ss tt'))   as TimeTo,
Format(cast( _session.StartTime as datetime)    ,'hh:mm:ss tt') as StartTime,
Format(cast( _session.EndTime as datetime),'hh:mm:ss tt') EndTime, 
_session.SessionName,
subDept.NameEn as deptname,
attendSchedule.EarlyLeaveMinutes as LeaveEarlyHours,
attendSchedule.DelayMinutes as LateHours,
DATEDIFF(HOUR,
	DATEADD(DAY, DATEDIFF(DAY,0,convert(datetime, attendSchedule.AttendanceDate)) ,convert(datetime, _session.StartTime)),
	DATEADD(DAY, DATEDIFF(DAY,0,convert(datetime, attendSchedule.AttendanceDate)) ,convert(datetime, _session.EndTime))) as TotalHours
from [Nursing].[Employee] as emp 
 join [HR].[SubDepartment] subDept on subDept.ID =emp.SubDepartmentId
 join [PayRoll].[AttendanceSchedule] as attendSchedule on attendSchedule.EmployeeID=emp.Id
left join [Registration].[Sessions]  as _session on _session.Id = emp.SessionID
where 
(attendSchedule.AttendanceDate >= convert(datetime, @DateFrom ,103) or @DateFrom is null)
and 
(attendSchedule.AttendanceDate  < convert(datetime,DATEADD(dd,1,@DateTo),103) or @DateTo is null)
and
((@EmployeeID is null) or(emp.Id=@EmployeeID))
and((@DepartmentId is null) or(subDept.ID=@DepartmentId) )
 
 

GO
