伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䠀刀崀⸀嬀匀倀开䔀洀瀀氀漀礀攀攀䄀猀猀攀猀猀洀攀渀琀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ⴀⴀ䐀攀挀氀愀爀攀 渀攀挀攀猀猀愀爀礀 瘀愀爀椀愀戀氀攀猀ഀ਀ഀ਀ ഀ਀
CREATE proc [HR].[SP_EmployeeAssessment] (@YY int)
as
begin
DECLARE   @SQLQuery AS NVARCHAR(MAX)
DECLARE   @PivotColumns AS NVARCHAR(MAX)
SELECT   @PivotColumns= COALESCE(@PivotColumns + ',','') + QUOTENAME(Year)
FROM (SELECT DISTINCT [Year] FROM hr.EmployeeAssessment where Year<=@YY and Year >=@YY-4) AS PivotExample

--to generate 5 columns of years
if CHARINDEX(Cast(@YY as nvarchar(10)),@PivotColumns) = 0   
begin  
 SET @PivotColumns = '['+ Cast(@YY as nvarchar(10))+']';
end  
 if CHARINDEX(Cast(@YY-1 as nvarchar(10)),@PivotColumns) = 0   
begin  

 SET @PivotColumns = '['+ Cast(@YY-1 as nvarchar(10))+'],' +@PivotColumns;
end 
if CHARINDEX(Cast(@YY-2 as nvarchar(10)),@PivotColumns) = 0   
begin  
 SET @PivotColumns = '['+ Cast(@YY-2 as nvarchar(10))+'],' +@PivotColumns;
end 
if CHARINDEX(Cast(@YY-3 as nvarchar(10)),@PivotColumns) = 0   
begin  
 SET @PivotColumns =  '['+Cast(@YY-3 as nvarchar(10))+'],' +@PivotColumns;
end 
if CHARINDEX(Cast(@YY-4 as nvarchar(10)),@PivotColumns) = 0   
begin  
 SET @PivotColumns = '['+ Cast(@YY-4 as nvarchar(10))+'],'+@PivotColumns;
end 
 
--Create the dynamic query with all the values for 
--pivot column at runtime
SET   @SQLQuery = 
    N'SELECT EmpID, ' +   @PivotColumns + '
   FROM ( SELECT [EmpId],[Year],[GradeValue]
     FROM HR.EmployeeAssessment 
   ) ps
    PIVOT( SUM(GradeValue) 
          FOR Year IN (' + @PivotColumns + ')) AS P'
 
 

--Execute dynamic query
EXEC sp_executesql @SQLQuery
end





GO
