CREATE procEDURE [HR].[SP_EmployeeDocs_Report]

AS
Select
 Employee.FirstName+' '+Employee.MiddleName+' '+Employee.LastName as EmployeeName,
 EmployeeDocs.StartDate,EmployeeDocs.endDate,EmployeeDocs.DocName
from HR.EmployeeDocs as EmployeeDocs
join Nursing.Employee as Employee on EmployeeDocs.EmployeeID=Employee.Id








