SELECT   Nursing.Employee.[EmployeeCode]   ,  Nursing.Employee.FirstNameAr + ' ' + ISNULL(Nursing.Employee.MiddleNameAr, '') + ' ' + ISNULL(Nursing.Employee.BeforeLastNameAr, '') + ' ' + ISNULL(Nursing.Employee.LastNameAr, '') AS EmpNameAr, 
                         Nursing.Employee.FirstNameEn + ' ' + ISNULL(Nursing.Employee.MiddleNameEn, '') + ' ' + ISNULL(Nursing.Employee.BeforeLastNameEn, '') + ' ' + ISNULL(Nursing.Employee.LastNameEn, '') AS EmpNameEN, 
                         ISNULL(HR.JobLevels.BasicSalary, Nursing.Employee.BasicSalary) AS BasicSalary, CASE WHEN Employee.transferallow != 1 THEN 0 ELSE ISNULL
                             ((SELECT        TOP (1) SubElements.ElementValue
                                 FROM            HR.HRSettings JOIN
                                                          HR.SubElements ON HR.SubElements.ID = HRSettings.TransferAllowance), 0) END AS transferallowness, CASE WHEN Employee.housingAllow = 0 THEN 0 ELSE ISNULL
                             ((SELECT        TOP (1) SubElements.ElementValue
                                 FROM            HR.HRSettings JOIN
                                                          HR.SubElements ON HR.SubElements.ID = HRSettings.AccommodationAllowance), 0) END AS Housigallowness, Nursing.Employee.JoiningDate, HR.SubDepartment.Name, HR.SubDepartment.NameEn
,Nursing.Employee.TerminateDate
, [HR].[GetRemainingDays](  Nursing.Employee.id,1,year(Nursing.Employee.TerminateDate),Nursing.Employee.TerminateDate) as  RemainingDays



,(select ( Select SUM(UnionTabl.BasicS) As TS from (

-- select All Basic Sallary 
select ISNULL(JobLevels.BasicSalary, Emp.BasicSalary) BasicS from 

Nursing.Employee Emp 
left join HR.JobLevels on Emp.JobDegreeID =JobLevels.Id
where (    Emp.Id=@EmpID)

 union
 select    SUM(svv.Value) sallary 
 from HR.MainElements ME
Inner join HR.SubElements SE on ME.ID = SE.MainElementID 
Left Join Hr.EmployeeSalaryVariablesVar svv  on SE.ID =svv.SubElementID 
inner join Nursing.Employee on Employee.Id=svv.EmpID
where   me.[Type]=2 and SE.InsuranceType=2 

and ( Employee.Id=@EmpID)and (month( DATEADD(month, -1, Nursing.Employee.TerminateDate))=svv.[Month]) 

