/****** Object:  StoredProcedure [HR].[SP_ManPowerRep]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [HR].[SP_ManPowerRep] @dateFrom nvarchar(50),@dateTo nvarchar(50)
as
begin

select distinct *,DATEDIFF(YEAR,mp.birthdate,GETDATE()) Age from [HR].[Vw_ManPower]  mp
 where mp.JoiningDate between  CONVERT(DATE,@dateFrom ,103)  and  CONVERT(DATE,@dateTo  ,103)
end
GO
