CREATE PROCEDURE  [HR].[Sp_VaraibleBenefitsReport] 
	-- Add the parameters for the stored procedure here
 @date nvarchar(10) 

AS
BEGIN
	Print @date

Declare @ts  decimal ;
 EXEC [HR].CalculateTotalSallary 
 @date = @date   ,
  @emp= null,
  @ts= @ts out
-- 1
Select
@date  thedate,
 @ts  Comprehensivepay, 
.12*@ts     Comprehensivepay12 ,
.9*@ts      Comprehensivepay9 ,
.125*@ts    Comprehensivepay125 , 
.03*@ts    Comprehensivepay3 , 
.01*@ts     Comprehensivepay1F , 
.01*@ts     Comprehensivepay1S , 
.01*@ts     Comprehensivepay1th ,
Sum (VaraibleBenefits.VaraibleBenefitsValue) as VaraibleBenefits ,
 
Sum (Loanabroad.LoanabroadInstallmentAmount)  PreviousPeriod  ,Sum (Pensions.PensionsInstallmentAmount)Loanabroad
from(
Select  
EmployeeID ,
PPI.InstallmentAmount LoanabroadInstallmentAmount  ,

--Sum (PPI.InstallmentAmount) ,
 PPI.SubElementID
 --,EmployeeID
from [HR].PreviousInstallmentDetail PPI
