                         HR.SubDepartment AS subDept ON emp.SubDepartmentId = subDept.ID INNER JOIN
                         HR.HieringDocumentEmployee AS HringDocEmp ON emp.Id = HringDocEmp.EmpLoyeeID INNER JOIN
                         HR.HieringDocumentEmployeeFile AS HringDocEmpFiles ON HringDocEmpFiles.HieringDocumentEmployeeID = HringDocEmp.ID INNER JOIN
