CREATE proc [HR].[StaffcompletionRateRep] --202101,202103
(@dFrom nvarchar(50),@dTo nvarchar(50) ) 
as
begin




declare @EmpCpont decimal(18,2)=(select COUNT( TEmp.Id)   from Nursing.Employee TEmp
inner join HR.HieringDocumentEmployee TEHD on TEHD.EmpLoyeeID = TEmp.Id)
print @EmpCpont

declare @CompleteFiles decimal(18,2)=(select COUNT(HieringDocumentEmployeeID)

from
(
select COUNT(ID) AllDocs,HieringDocumentEmployeeID ,(select count(ID) from HR.HieringDocumentEmployeeFile inn
where inn.HieringDocumentFile is not null and inn.HieringDocumentEmployeeID=oute.HieringDocumentEmployeeID and
   FORMAT(inn.IssueDate,'yyyyMM') between @dFrom  and @dTo) CompDoc

 from HR.HieringDocumentEmployeeFile oute

group by HieringDocumentEmployeeID)
as test
where test.AllDocs = test.CompDoc
) 

 declare @InComCompleteDocs decimal(18,2)=

(select count(ID) from  HR.HieringDocumentEmployeeFile

where (HieringDocumentEmployeeFile.HieringDocumentFile is null or HieringDocumentEmployeeFile.HieringDocumentFile=''))

 


