CREATE proc [HR].[Test1]
@EmpID int
as

SELECT        HR.EmployeeSalaryVariablesVar.Value, HR.SubElements.NameArabic, HR.SubElements.NameEnglish
FROM            HR.EmployeeSalaryVariablesVar INNER JOIN
                         HR.SubElements ON HR.EmployeeSalaryVariablesVar.SubElementID = HR.SubElements.ID
WHERE        (HR.EmployeeSalaryVariablesVar.EmpID = @EmpID) and MainElementID=32 


