Select * from (

select 
  EmployeeId
	  ,DMId
	  ,DiseaseName
	  ,Case StHD_Status when 1 then N'Yes' when 0 then 'No' when 2 then 'Unknown' End as StHD_Status
	  ,Case StHD_Status when 1 then N'نعم' when 0 then N'لا' when 2 then N'غيرمعروف' End as StHD_StatusAr
	  ,STHD_Comment
	  ,STH_Comment
	  ,SubDeptName
	  ,DeptName
	  ,EmployeeCode
	  ,EmpName
	  ,StHD_Status as intStHD_Status
 ,case category when 1 then 'Communicable Disease' when 2 then 'Chronic Disease'  else 'Chronic Disease' end as [Type]
  ,case category when 1 then N'مرض معدٍ' when 2 then N'مرض مزمن'  else N'مرض مزمن'  end as [TypeAr]
  ,DeptNameAr,SubDeptNameAr,EmpNameEn,DiseaseNameAr
 from InfectionControl.V_StuffHelthCareProgramDis
  
union 
select 
EmployeeId
 ,VMId
,vaccinationName
,Case StHV_Status when 1 then'Yes' when 0 then 'No' when 2 then 'Unknown' End as StHV_Status
  ,Case StHV_Status when 1 then N'نعم' when 0 then N'لا' when 2 then N'غيرمعروف' End as StHD_StatusAr
,STHV_Comment
,STH_Comment
,SubDeptName
,DeptName

,EmployeeCode
,EmpName,StHV_Status
,'Vaccination' as [Type]
,N'تطعيم' as [TypeAr] ,DeptNameAr,SubDeptNameAr,EmpNameEn,VaccinationNameAr
 from InfectionControl.V_StuffHelthCareProgramVacc
 ) as UnionTbl
 where (@type is Null or UnionTbl.[Type]=@categ ) 
 and  (@status is Null or UnionTbl.intStHD_Status=@status ) 
 and (@dis is Null or UnionTbl.DMId=@dis)
 order by UnionTbl.[Type]
 End


GO
