CREATE PROCEDURE [InfectionControl].[EmployeesVaccinationsReport] @Type int
AS
	IF(@Type=1)--التهاب كبدى
		SELECT  
		ISNULL(EM.FirstName,'') +' '+ ISNULL(EM.MiddleName,'') +' '+isNULL(EM.BeforeLastName,'')+' '+ isNULL(EM.LastName,'')  as FullName ,
		EM.NationalID NationalID ,
		datediff(YY, EM.BirthDate,getdate()) as Age , 
		Js.JobName as Job,
		SD.Name as Department,
		CAST(
         CASE
         WHEN EM.Gender=1 
         THEN N'مذكر'
          ELSE N'مؤنث'
          END AS nvarchar(20)) as Gender,
	    EV.FirstDose,
		EV.SecondDose,
		EV.ThirdDose,
		EV.FourthDose, 
		EV.FifthDose,
