CREATE proc  [InfectionControl].[HandHiginReport] -- 20200101,20221212,''
@from int,
@to int
,
@Title  nvarchar(4000)
as

--declare @to int=20221018
--declare @from int=20221010 
--declare @Title  nvarchar(4000)='ggg'
select Facility,StartTime,Endtime,date,

 sum(FHR) FHR, sum( FHW) FHW, sum(FMissed) FMissed, sum( FFHR) FFHR, sum( FFHW) FFHW, sum( FFMissed) FFMissed, sum( FFFHR) FFFHR, sum( FFFHW) FFFHW, sum( FFFMissed) FFFMissed, sum( FFFFHR) FFFFHR, sum( FFFFHW) FFFFHW, sum( FFFFMissed) FFFFMissed
 from (

SELECT        TOP (200) InfectionControl.HandHigine.Facility, InfectionControl.HandHigine.StartTime, InfectionControl.HandHigine.Endtime, InfectionControl.HandHigineDet.ProfCat, InfectionControl.HandHigine.date, 
                    count(InfectionControl.HandHigineDet.HHaction) FHR,0 FHW,0 FMissed,0 FFHR,0 FFHW,0 FFMissed,0 FFFHR,0 FFFHW,0 FFFMissed,0 FFFFHR,0 FFFFHW,0 FFFFMissed



FROM            InfectionControl.HandHigine INNER JOIN
                         InfectionControl.HandHigineDet ON InfectionControl.HandHigine.Id = InfectionControl.HandHigineDet.HandHigineID
						 	where ProfCat=4  and HHaction=1
            
						 group by InfectionControl.HandHigine.Facility, InfectionControl.HandHigine.StartTime, InfectionControl.HandHigine.Endtime, InfectionControl.HandHigineDet.ProfCat, InfectionControl.HandHigine.date
						 ,  InfectionControl.HandHigineDet.HHaction
