/****** Object:  StoredProcedure [InfectionControl].[ICUCCUPATIENTReport_Ar]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create   PROCEDURE [InfectionControl].[ICUCCUPATIENTReport_Ar]
    @FromDate DATETIME,
    @ToDate   DATETIME
AS
BEGIN
    SELECT
        CONVERT(DATE, AdmitPatients.AdmissionDate) AS [تاريخ الدخول],
        patient.Code AS [الكود],
        patient.FirstName + ' ' + ISNULL(patient.MiddleName1, '') + ' ' + ISNULL(patient.MiddleName2, '') + ' ' + ISNULL(patient.LastName, '') AS [اسم المريض],
        icd.Diagnosis AS [التشخيص],
        'CVP' AS [CVP],
        N'التهوية' AS [التهوية]
    FROM InPatient.AdmitPatients AS AdmitPatients
    INNER JOIN InPatient.Ward ON AdmitPatients.AdmissionWardID = Ward.Id
    JOIN Registration.Patients AS patient ON AdmitPatients.PatientId = patient.Id
    JOIN InPatient.V_ICDDiagnosisCommaSeprator icd ON AdmitPatients.Id = icd.AdmitPatientID
    WHERE Ward.IsICU = 1 
      AND AdmitPatients.CreatedDate BETWEEN @FromDate AND @ToDate
    ORDER BY AdmitPatients.AdmissionDate DESC;
END

GO
/****** Object:  StoredProcedure [InfectionControl].[ICUReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [InfectionControl].[ICUReport](@Fdate nvarchar(50),@Tdate  nvarchar(50))
as
begin
select 
 unionTblsTotalGroup.MRN
	,unionTblsTotalGroup.Name
	,unionTblsTotalGroup.OPIPNumber
	,unionTblsTotalGroup.serv
	,unionTblsTotalGroup.Code
	,Sum(unionTblsTotalGroup.servDays) TCVCDays
    ,unionTblsTotalGroup.Diagnosis
	--,unionTblsTotalGroup.Drain
from
(
select 
     P.Code MRN
	,isnull(P.FirstName,'')+' '+isnull(p.MiddleName1,'')+' '+isnull(p.MiddleName2,'')+' '+isnull(p.LastName,'') Name
	,IRH.OP_IPNumber OPIPNumber
	,unionTblsGroup.serv
	,unionTblsGroup.Code
	,unionTblsGroup.servDays 
	,CSep.Diagnosis
from 
Registration.Patients P
Left Outer join [InPatient].[V_ICDDiagnosisCommaSeprator] CSep on P.Id = CSep.patId
inner join OutPatient.InvestigationRequestHeader IRH on P.Id=IRH.PatientID
inner join
