/****** Object:  StoredProcedure [InfectionControl].[InfectionEvaluationReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

	CREATE procEDURE [InfectionControl].[InfectionEvaluationReport] 
		@Area_ID int,
		@DateFrom NVARCHAR(20)=null,
		@DateTo NVARCHAR(20)=null
	AS
	BEGIN



	
		SELECT
			Header.[Id] AS [HeaderId]
			, Header.Area_ID
			, Detail.Element_Id as Element_Id
			, Detail.groupID as groupID
			, Header.DateOfInspection
			, Header.TotalScore
			, Area.NameAr as Area_NameAr
			, Area.NameEn as Area_NameEn
		    , [Group].NameAr as Group_NameAr
			, [Group].NameEn as Group_NameEn
			, Element.NameAr as Element_NameAr
			, Element.NameEn as Element_NameAr
	
			

	 from [InfectionControl].InfectionEvaluationHeader Header
inner join [InfectionControl].Areas Area on Header.Area_ID = Area.Id
inner join [InfectionControl].InfectionEvaluationDetail Detail on Detail.InfectionEvaluationHeader_ID = Header.Id
inner join [InfectionControl].Element  on Detail.Element_Id = Element.Id
inner join [InfectionControl].[Group]  on Detail.groupID = [Group].ID
where 
(Header.Area_ID = @Area_ID) 
and (Header.[DateOfInspection] >= Convert(datetime2(7),@DateFrom)  or @DateFrom is null) 
 and (Header.[DateOfInspection]  <=dateadd(DAY,1,Convert(datetime2(7), @DateTo))  or @DateTo is null) 
 	END


GO
