SET QUOTED_IDENTIFIER ON
GO

 CREATE PROCEDURE [InfectionControl].[NotificationsAcupunctureReport] @DateFrom datetime, @DateTo datetime,@Type int
AS
SELECT
  
CASE
    WHEN EM.ID is null THEN Pa.FirstName+' '+Pa.MiddleName1+' '+Pa.LastName 
    WHEN Pa.Id is null THEN EM.FirstName+' '+EM.MiddleName+' '+EM.LastName 
END as FullName ,

CASE
    WHEN EM.ID is null THEN Pa.PassportNumber
    WHEN Pa.Id is null THEN EM.NationalID
END as NationalID ,

CASE
    WHEN EM.ID is null THEN datediff(YY,Pa.DateOfBirth,getdate()) 
    WHEN Pa.Id is null THEN datediff(YY, EM.BirthDate,getdate())
END as Age , 

 NA.Job,
 NA.Department,
CASE WHEN  CASE
    WHEN EM.ID is null THEN Pa.GenderId
    WHEN Pa.Id is null THEN EM.Gender
END =1 THEN 'Male'
else 'Female' END as Gender,

CASE
    WHEN EM.ID is null THEN Pa.Code
    WHEN Pa.Id is null THEN CAST(EM.Id as varchar(10)) 
END as 'File Number' , 

CASE   
    WHEN NA.TypeofIncident=1 THEN 'Needle_Stick' 
	WHEN NA.TypeofIncident=2 THEN 'Scalpel_Cut' 
    WHEN NA.TypeofIncident=3 THEN 'Splash_Of_Blood_On_The_Face' 
	WHEN NA.TypeofIncident=4 THEN 'Splash_Of_Fluid_On_The_Face' 
END as 'Type of Incident' ,
NA.IncidentDate as 'Incident Date',
NA.IncidentTime as 'Incident Time',
NA.IncidentPlace as 'Incident Place',
NA.Affectedbodypart as 'Affected body part',
NA.positionofvaccinations as 'position of vaccinations',
NA.Positionanalysis as 'Positionan alysis',

CASE   
    WHEN NA.AIDS =1 and NA.hepatitis =1 THEN 'AIDS/hepatitis' 
	WHEN NA.AIDS =1 and NA.hepatitis =0 THEN 'AIDS' 
	WHEN NA.AIDS= 0 and NA.hepatitis =1 THEN 'hepatitis' 
	WHEN NA.AIDS =0 and NA.hepatitis =0 THEN '' 
END as 'analysis Type' ,
NA.infectioncontrolReplay as 'infection control Replay',
NA.analysisNote as 'analysis Note'
,
CASE
    WHEN EM.ID is null THEN 2
    WHEN Pa.Id is null THEN 1
END as Typess 

from [infectioncontrol].NotificationsAcupuncture NA
left join Nursing.Employee EM on NA.Employee_Id=EM.ID
left join Registration.Patients Pa on NA.Patient_ID=Pa.Id

WHERE NA.[Date] between  convert(datetime,@DateFrom) AND CONVERT(datetime,@DateTo) 
	and CASE
    WHEN EM.ID is null THEN 2
    WHEN Pa.Id is null THEN 1
END=@Type

GO
