CREATE proc [InfectionControl].[PreventiveMedicineReport]  --20210901,20000101
(@dateFrom DateTime = null,@dateTo DateTime = null,@Desc nvarchar(4000) )
as
SELECT        TOP (200) InfectionControl.PreventiveMedicine.Id, InfectionControl.PreventiveMedicine.Type, InfectionControl.PreventiveMedicine.PersonID, InfectionControl.PreventiveMedicine.NationalID, 
                         InfectionControl.PreventiveMedicine.phonenumber, InfectionControl.PreventiveMedicine.CreatedBy, InfectionControl.PreventiveMedicine.CreatedDate, InfectionControl.PreventiveMedicine.LastModifiedBy, 
