/****** Object:  StoredProcedure [InfectionControl].[RepInfectionEvaluation]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE  [InfectionControl].[RepInfectionEvaluation]
@Area int  null,
@Date datetime  null
 
as
begin



select Emp.EmployeeCode,
	 case  WHEN IED.Result = 1  then N'?' else '-' end as 'Yes',
	 	 case  WHEN IED.Result = 2  then N'?' else '-' end as 'Not completely',
		 	 case  WHEN IED.Result = 3  then N'?' else '-' end as 'No',
			 	 case  WHEN IED.Result = 4  then '?' else '-' end as 'not apply',

	 G.ID 'GroupID',  G.NameEn 'GroupNameEn' , G.NameAr 'GroupName' , G.ID 'GroupID',E.NameAr 'ElementName',E.NameEn 'ElementNameEN',E.Id 'ElementId',
	 IED.Result,IEH.DateOfInspection, A.NameAr,IEH.DateOfInspection, A.NameEn, IEH.Id 'HeaderId',IEH.TotalScore ,
	 IED.Note,IEH.CreatedDate,Emp.FirstName +' '+ Emp.MiddleName +' ' + Emp.LastName as CreatedName,
	 Emp.FirstNameEn +' '+ Emp.MiddleNameEn +' ' + Emp.LastNameEn as CreatedNameEn
	,ag.ID AS AGID , GE. ID EGID
	from InfectionControl.InfectionEvaluationDetail IED  
join InfectionControl.InfectionEvaluationHeader IEH on IEH.Id=IED.InfectionEvaluationHeader_ID
join [InfectionControl].Areas A on a.id= IEH.Area_ID
join [InfectionControl].Element E on E.Id=IED.Element_Id
join [InfectionControl].[Group] G on g.ID= IED.groupID 
JOIN InfectionControl.AreaGroups  ag ON ag.AreaId = a.Id AND ag.GroupId=g.ID
JOIN InfectionControl.GroupElements GE ON GE.GroupId = g.ID AND GE.ElementId = E.Id
join [JCIT_MembershipDB].[dbo].[AspNetUsers] ANUsers on ANUsers.Id = IEH.CreatedBy
