/****** Object:  StoredProcedure [InfectionControl].[RepInfectionEvaluation_Datetime]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE  [InfectionControl].[RepInfectionEvaluation_Datetime]
@Area int null,
@Date datetime null
as
begin

set @Date= Format(@Date,'yyyy-MM-dd')

select
	 case  WHEN IED.Result = 1  then N'?' else '-' end as 'Yes',
	 	 case  WHEN IED.Result = 2  then N'?' else '-' end as 'Not completely',
		 	 case  WHEN IED.Result = 3  then N'?' else '-' end as 'No',
			 	 case  WHEN IED.Result = 4  then '?' else '-' end as 'not apply',

	 G.ID 'GroupID',  G.NameAr 'GroupName' , G.ID 'GroupID', G.NameAr 'GroupName' ,E.NameAr 'ElementName',E.Id 'ElementId',
	 IED.Result,IEH.DateOfInspection, A.NameAr, IEH.Id 'HeaderId',IEH.TotalScore ,
	 IED.Note,IEH.CreatedDate,Emp.FirstName +' '+ Emp.MiddleName +' ' + Emp.LastName as CreatedName
	
	from InfectionControl.InfectionEvaluationDetail IED  
join InfectionControl.InfectionEvaluationHeader IEH on IEH.Id=IED.InfectionEvaluationHeader_ID
join [InfectionControl].Areas A on a.id= IEH.Area_ID
join [InfectionControl].Element E on E.Id=IED.Element_Id
join [InfectionControl].[Group] G on g.ID= IED.groupID 
join [JCIT_MembershipDB].[dbo].[AspNetUsers] ANUsers on ANUsers.Id = IEH.CreatedBy
join [Nursing].Employee Emp on Emp.Id= ANUsers.EmployeeID
WHERE  
	A.Id =case when @Area is null or @Area=''or @Area= 0 then A.Id else @Area end
	and
	CAST( IEH.DateOfInspection as DATE) =case when @Date is null or @Date=''or @Date= 0 then IEH.DateOfInspection else CAST(@Date as date) end
 
ਊ最爀漀甀瀀 戀礀 䤀䔀䠀⸀䤀搀Ⰰ䜀⸀一愀洀攀䄀爀Ⰰ䔀⸀一愀洀攀䄀爀Ⰰ䤀䔀䐀⸀刀攀猀甀氀琀Ⰰ䤀䔀䠀⸀吀漀琀愀氀匀挀漀爀攀Ⰰ䤀䔀䠀⸀䐀愀琀攀伀昀䤀渀猀瀀攀挀琀椀漀渀Ⰰ䄀⸀一愀洀攀䄀爀Ⰰ䜀⸀䤀䐀Ⰰ䔀⸀䤀搀Ⰰ刀攀猀甀氀琀Ⰰ䤀䔀䐀⸀一漀琀攀Ⰰ䤀䔀䠀⸀䌀爀攀愀琀攀搀䐀愀琀攀ഀ਀Ⰰ䔀洀瀀⸀䘀椀爀猀琀一愀洀攀 Ⰰ 䔀洀瀀⸀䴀椀搀搀氀攀一愀洀攀 Ⰰ 䔀洀瀀⸀䰀愀猀琀一愀洀攀 ഀ਀ഀ਀攀渀搀ഀ਀ഀ਀搀攀挀氀愀爀攀 䀀眀栀攀渀 搀愀琀攀琀椀洀攀 㴀 䜀䔀吀唀吀䌀䐀䄀吀䔀⠀⤀ഀ਀猀攀氀攀挀琀 䀀眀栀攀渀 ⴀⴀ 搀愀琀攀 ⬀ 琀椀洀攀ഀ਀搀攀挀氀愀爀攀 䀀搀愀礀 搀愀琀攀琀椀洀攀 㴀 䌀䄀匀吀⠀䘀䰀伀伀刀⠀䌀䄀匀吀⠀䀀眀栀攀渀 愀猀 昀氀漀愀琀⤀⤀ 愀猀 搀愀琀攀琀椀洀攀⤀ഀ਀猀攀氀攀挀琀 䀀搀愀礀 ⴀⴀ 搀愀琀攀 漀渀氀礀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀刀瀀琀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀开䄀刀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀䌀刀䔀䄀吀䔀   倀刀伀䌀䔀䐀唀刀䔀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀刀瀀琀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀开䄀刀崀ഀ਀    䀀䘀爀漀洀 搀愀琀攀Ⰰഀ਀    䀀吀漀   搀愀琀攀ഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀    匀䔀吀 一伀䌀伀唀一吀 伀一㬀ഀ਀ഀ਀    㬀圀䤀吀䠀 刀攀瀀漀爀琀刀漀眀猀 䄀匀ഀ਀    ⠀ഀ਀        匀䔀䰀䔀䌀吀ഀ਀            䰀吀刀䤀䴀⠀刀吀刀䤀䴀⠀䌀伀一䌀䄀吀⠀ഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䘀椀爀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䴀椀搀搀氀攀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䈀攀昀漀爀攀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀ഀ਀            ⤀⤀⤀ 䄀匀 嬀✀㌆䔆 ✀䐆䔆䠆㠆䄆崆Ⰰഀ਀            䔀⸀䌀愀爀搀一甀洀戀攀爀 䄀匀 嬀㄀䈆䔆 ✀䐆⠆㜆✆䈆⤆崆Ⰰഀ਀            䐀䴀⸀䐀椀猀攀愀猀攀一愀洀攀䄀爀 䄀匀 嬀✀䐆䔆ㄆ㘆崆Ⰰഀ਀            䌀䄀匀吀⠀一唀䰀䰀 䄀匀 渀瘀愀爀挀栀愀爀⠀㈀　　⤀⤀ 䄀匀 嬀✀䐆⨆㜆㤆䨆䔆崆Ⰰഀ਀            䌀䄀匀吀⠀䐀⸀匀琀愀琀甀猀䐀愀琀攀 䄀匀 搀愀琀攀⤀ 䄀匀 嬀⨀✆ㄆ䨆⸆ ✀䐆ⴆ✆䐆⤆崆ഀ਀        䘀刀伀䴀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀崀 匀ഀ਀        䤀一一䔀刀 䨀伀䤀一 嬀一甀爀猀椀渀最崀⸀嬀䔀洀瀀氀漀礀攀攀崀 䔀ഀ਀            伀一 䔀⸀䤀搀 㴀 匀⸀䔀洀瀀氀漀礀攀攀䤀搀ഀ਀        䤀一一䔀刀 䨀伀䤀一 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀䐀攀琀愀椀氀猀崀 䐀ഀ਀            伀一 䐀⸀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀䤀搀 㴀 匀⸀䤀搀ഀ਀        䰀䔀䘀吀 䨀伀䤀一 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀䐀椀猀攀愀猀攀䴀愀猀琀攀爀崀 䐀䴀ഀ਀            伀一 䐀䴀⸀䤀搀 㴀 䐀⸀䐀椀猀攀愀猀攀䴀愀猀琀攀爀䤀搀ഀ਀        圀䠀䔀刀䔀 䐀⸀匀琀愀琀甀猀䐀愀琀攀 㸀㴀 䀀䘀爀漀洀ഀ਀          䄀一䐀 䐀⸀匀琀愀琀甀猀䐀愀琀攀 㰀 䐀䄀吀䔀䄀䐀䐀⠀搀愀礀Ⰰ ㄀Ⰰ 䀀吀漀⤀ഀ਀ഀ਀        唀一䤀伀一 䄀䰀䰀ഀ਀ഀ਀        匀䔀䰀䔀䌀吀ഀ਀            䰀吀刀䤀䴀⠀刀吀刀䤀䴀⠀䌀伀一䌀䄀吀⠀ഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䘀椀爀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䴀椀搀搀氀攀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䈀攀昀漀爀攀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀Ⰰഀ਀                ✀ ✀Ⰰഀ਀                䤀匀一唀䰀䰀⠀䔀⸀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀ഀ਀            ⤀⤀⤀ 䄀匀 嬀✀㌆䔆 ✀䐆䔆䠆㠆䄆崆Ⰰഀ਀            䔀⸀䌀愀爀搀一甀洀戀攀爀 䄀匀 嬀㄀䈆䔆 ✀䐆⠆㜆✆䈆⤆崆Ⰰഀ਀            䌀䄀匀吀⠀一唀䰀䰀 䄀匀 渀瘀愀爀挀栀愀爀⠀㈀　　⤀⤀ 䄀匀 嬀✀䐆䔆ㄆ㘆崆Ⰰഀ਀            嘀䴀⸀嘀愀挀挀椀渀愀琀椀漀渀一愀洀攀䄀爀 䄀匀 嬀✀䐆⨆㜆㤆䨆䔆崆Ⰰഀ਀            䌀䄀匀吀⠀嘀⸀匀琀愀琀甀猀䐀愀琀攀 䄀匀 搀愀琀攀⤀ 䄀匀 嬀⨀✆ㄆ䨆⸆ ✀䐆ⴆ✆䐆⤆崆ഀ਀
        FROM [InfectionControl].[StaffHealthCareProgram] S
        INNER JOIN [Nursing].[Employee] E
            ON E.Id = S.EmployeeId
        INNER JOIN [InfectionControl].[StaffHealthCareProgramDetails_Vac] V
            ON V.StaffHealthCareProgramId = S.Id
        LEFT JOIN [OutPatient].[VaccinationMaster] VM
            ON VM.Id = V.Vaccinationd
        WHERE V.StatusDate >= @From
          AND V.StatusDate < DATEADD(day, 1, @To)
    )
    SELECT
        [اسم الموظف],
        [رقم البطاقة],
        [المرض],
        [التطعيم],
        [تاريخ الحالة]
    FROM ReportRows
    ORDER BY [تاريخ الحالة], [اسم الموظف];
END

GO
/****** Object:  StoredProcedure [InfectionControl].[RptStaffHealthCare_EN]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [InfectionControl].[RptStaffHealthCare_EN]
    @from date,
    @to   date
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH ReportRows AS
    (
        SELECT
            LTRIM(RTRIM(CONCAT(
                ISNULL(E.FirstNameEn, ''),
                ' ',
                ISNULL(E.MiddleNameEn, ''),
                ' ',
                ISNULL(E.BeforeLastNameEn, ''),
                ' ',
                ISNULL(E.LastNameEn, '')
            ))) AS [Employee Name],
            E.CardNumber AS [Staff ID],
            DM.DiseaseName AS [Disease],
            CAST(NULL AS nvarchar(200)) AS [Vaccine],
            CAST(D.StatusDate AS date) AS [Episode Date]
        FROM [InfectionControl].[StaffHealthCareProgram] S
        INNER JOIN [Nursing].[Employee] E
            ON E.Id = S.EmployeeId
        INNER JOIN [InfectionControl].[StaffHealthCareProgramDetails] D
            ON D.StaffHealthCareProgramId = S.Id
        LEFT JOIN [OutPatient].[DiseaseMaster] DM
            ON DM.Id = D.DiseaseMasterId
        WHERE D.StatusDate >= @From
          AND D.StatusDate < DATEADD(day, 1, @To)

        UNION ALL

        SELECT
            LTRIM(RTRIM(CONCAT(
                ISNULL(E.FirstNameEn, ''),
                ' ',
                ISNULL(E.MiddleNameEn, ''),
                ' ',
                ISNULL(E.BeforeLastNameEn, ''),
                ' ',
ਊ                䤀匀一唀䰀䰀⠀䔀⸀䰀愀猀琀一愀洀攀䔀渀Ⰰ ✀✀⤀ഀ਀            ⤀⤀⤀ 䄀匀 嬀䔀洀瀀氀漀礀攀攀 一愀洀攀崀Ⰰഀ਀            䔀⸀䌀愀爀搀一甀洀戀攀爀 䄀匀 嬀匀琀愀昀昀 䤀䐀崀Ⰰഀ਀            䌀䄀匀吀⠀一唀䰀䰀 䄀匀 渀瘀愀爀挀栀愀爀⠀㈀　　⤀⤀ 䄀匀 嬀䐀椀猀攀愀猀攀崀Ⰰഀ਀            嘀䴀⸀嘀愀挀挀椀渀愀琀椀漀渀一愀洀攀 䄀匀 嬀嘀愀挀挀椀渀攀崀Ⰰഀ਀            䌀䄀匀吀⠀嘀⸀匀琀愀琀甀猀䐀愀琀攀 䄀匀 搀愀琀攀⤀ 䄀匀 嬀䔀瀀椀猀漀搀攀 䐀愀琀攀崀ഀ਀        䘀刀伀䴀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀崀 匀ഀ਀        䤀一一䔀刀 䨀伀䤀一 嬀一甀爀猀椀渀最崀⸀嬀䔀洀瀀氀漀礀攀攀崀 䔀ഀ਀            伀一 䔀⸀䤀搀 㴀 匀⸀䔀洀瀀氀漀礀攀攀䤀搀ഀ਀        䤀一一䔀刀 䨀伀䤀一 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀䐀攀琀愀椀氀猀开嘀愀挀崀 嘀ഀ਀            伀一 嘀⸀匀琀愀昀昀䠀攀愀氀琀栀䌀愀爀攀倀爀漀最爀愀洀䤀搀 㴀 匀⸀䤀搀ഀ਀        䰀䔀䘀吀 䨀伀䤀一 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀嘀愀挀挀椀渀愀琀椀漀渀䴀愀猀琀攀爀崀 嘀䴀ഀ਀            伀一 嘀䴀⸀䤀搀 㴀 嘀⸀嘀愀挀挀椀渀愀琀椀漀渀搀ഀ਀        圀䠀䔀刀䔀 嘀⸀匀琀愀琀甀猀䐀愀琀攀 㸀㴀 䀀䘀爀漀洀ഀ਀          䄀一䐀 嘀⸀匀琀愀琀甀猀䐀愀琀攀 㰀 䐀䄀吀䔀䄀䐀䐀⠀搀愀礀Ⰰ ㄀Ⰰ 䀀吀漀⤀ഀ਀    ⤀ഀ਀    匀䔀䰀䔀䌀吀ഀ਀        嬀䔀洀瀀氀漀礀攀攀 一愀洀攀崀Ⰰഀ਀        嬀匀琀愀昀昀 䤀䐀崀Ⰰഀ਀        嬀䐀椀猀攀愀猀攀崀Ⰰഀ਀        嬀嘀愀挀挀椀渀攀崀Ⰰഀ਀        嬀䔀瀀椀猀漀搀攀 䐀愀琀攀崀ഀ਀    䘀刀伀䴀 刀攀瀀漀爀琀刀漀眀猀ഀ਀    伀刀䐀䔀刀 䈀夀 嬀䔀瀀椀猀漀搀攀 䐀愀琀攀崀Ⰰ 嬀䔀洀瀀氀漀礀攀攀 一愀洀攀崀㬀ഀ਀䔀一䐀ഀ਀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀猀瀀开䄀䤀䐀匀开椀渀瘀攀猀琀椀最愀琀椀漀渀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀攀搀甀爀攀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀猀瀀开䄀䤀䐀匀开椀渀瘀攀猀琀椀最愀琀椀漀渀崀⠀䀀椀搀 椀渀琀⤀ഀ਀䄀猀ഀ਀猀攀氀攀挀琀 椀渀瘀⸀⨀Ⰰ猀甀爀瘀⸀⨀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 攀洀瀀⸀嬀䘀椀爀猀琀一愀洀攀䄀爀崀  䔀䰀匀䔀 瀀愀琀⸀嬀䘀椀爀猀琀一愀洀攀崀  䔀一䐀 䄀匀 䘀椀爀猀琀一愀洀攀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 攀洀瀀⸀嬀䴀椀搀搀氀攀一愀洀攀䄀爀崀 䔀䰀匀䔀 瀀愀琀⸀嬀䴀椀搀搀氀攀一愀洀攀㄀崀  䔀一䐀 䄀匀 䴀椀搀搀氀攀一愀洀攀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 攀洀瀀⸀嬀䈀攀昀漀爀攀䰀愀猀琀一愀洀攀䄀爀崀 䔀䰀匀䔀 瀀愀琀⸀嬀䴀椀搀搀氀攀一愀洀攀㈀崀  䔀一䐀 䄀匀 䈀攀昀漀爀攀䰀愀猀琀一愀洀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 攀洀瀀⸀嬀䰀愀猀琀一愀洀攀䄀爀崀 䔀䰀匀䔀 瀀愀琀⸀嬀䰀愀猀琀一愀洀攀崀  䔀一䐀 䄀匀 䰀愀猀琀一愀洀攀 Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 攀洀瀀⸀嬀䈀椀爀琀栀䐀愀琀攀崀 䔀䰀匀䔀 瀀愀琀⸀嬀䐀愀琀攀伀昀䈀椀爀琀栀崀  䔀一䐀 䄀匀 䐀愀琀攀伀昀䈀椀爀琀栀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 䔀洀瀀匀攀砀⸀嬀一愀洀攀崀 䔀䰀匀䔀 倀愀琀匀攀砀⸀嬀一愀洀攀崀  䔀一䐀 䄀匀 䜀攀渀搀攀爀Ⰰഀ਀䌀䄀匀䔀 圀䠀䔀一  椀渀瘀⸀倀愀琀椀攀渀琀䤀䐀 䤀匀 一唀䰀䰀 吀䠀䔀一 ഀ਀  ഀ਀挀愀猀攀 圀栀攀渀 攀洀瀀⸀䜀攀渀搀攀爀 㴀 ✀㄀✀ 吀䠀䔀一 䔀洀瀀匀漀挀匀琀愀琀甀猀⸀嬀猀漀挀椀愀氀猀琀愀琀甀猀䐀攀猀挀爀椀瀀琀椀漀渀䄀爀䴀愀氀攀崀ഀ਀攀氀猀攀 䔀洀瀀匀漀挀匀琀愀琀甀猀⸀嬀猀漀挀椀愀氀猀琀愀琀甀猀䐀攀猀挀爀椀瀀琀椀漀渀䄀爀䘀攀洀愀氀攀崀ഀ਀䔀渀搀ഀ਀ഀ਀ 䔀䰀匀䔀  ഀ਀ 挀愀猀攀 圀栀攀渀 瀀愀琀⸀䜀攀渀搀攀爀䤀搀 㴀 ✀㄀✀ 吀䠀䔀一 倀愀琀匀漀挀匀琀愀琀甀猀⸀嬀猀漀挀椀愀氀猀琀愀琀甀猀䐀攀猀挀爀椀瀀琀椀漀渀䄀爀䴀愀氀攀崀ഀ਀攀氀猀攀 倀愀琀匀漀挀匀琀愀琀甀猀⸀嬀猀漀挀椀愀氀猀琀愀琀甀猀䐀攀猀挀爀椀瀀琀椀漀渀䄀爀䘀攀洀愀氀攀崀ഀ਀䔀渀搀ഀ਀ ഀ਀䔀渀搀 ഀ਀ 䄀匀 猀漀挀椀愀氀猀琀愀琀甀猀Ⰰഀ਀
CASE WHEN  inv.PatientID IS NULL THEN emp.[NationalID] ELSE pat.[PassportNumber]  END AS NationalID,
CASE WHEN  inv.PatientID IS NULL THEN emp.[EmergencyContactPhone] ELSE pat.[MobileNumber]  END AS MobileNumber,
cty.[Name] ctyName,subDep.[Name] Dept,_cty.[Name] ResCtyName,dist.[DistrictName] ResState,
Doc.[NameAr] DocName

 from [InfectionControl].[AIDS_investigation] inv
join [InfectionControl].[AIDS_Survey] surv on inv.id= surv.[AIDS_InvestigationID]
left join [Nursing].[Employee] emp on emp.[Id]=inv.EmpID
left join [Registration].[Patients] pat on pat.[Id]=inv.PatientID
left join [ApplicationSetup].[City] cty on cty.Id=inv.City
left join [HR].[SubDepartment] subDep on subDep.Id=inv.[DepartmentID]
left join [ApplicationSetup].[City] _cty on _cty.Id=inv.ResidenceCity
left join [ApplicationSetup].District dist on dist.Id=inv.ResidenceState
left join [Registration].Doctors Doc on Doc.[Id]=inv.[DoctorID]
left join [Registration].[Sex] EmpSex on EmpSex.[Id]=emp.[Gender]
left join [Registration].[Sex] PatSex on PatSex.[Id]=pat.[GenderId]
left join [HR].[SocialStatus] EmpSocStatus on EmpSocStatus.ID=emp.[MaritalStatus]
left join [HR].[SocialStatus] PatSocStatus on PatSocStatus.ID=pat.[MaritalStatusId]
where inv.Id=@id


GO
/****** Object:  StoredProcedure [InfectionControl].[SP_BloodExposureReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [InfectionControl].[SP_BloodExposureReport]
    @from varchar(30),
    @to  varchar(30)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
     
        ISNULL(E.FirstNameEn, '') + ' ' + 
        ISNULL(E.MiddleNameEn, '') + ' ' +
        ISNULL(E.BeforeLastNameEn, '') + ' ' +
        ISNULL(E.LastNameEn, '') AS EmployeeName,

        ISNULL(P.TranslatedFallName, '') AS PatientName  ,
		     
        P.Code AS MRN,

        
        CASE B.TypeOfExposureId
            WHEN 1 THEN 'Needle Stick'
            WHEN 2 THEN 'Scalpel Cut'
            WHEN 3 THEN 'Splash Of Blood On The Face'
            WHEN 4 THEN 'Splash Of Fluid On The Face'
            ELSE 'Unknown'
        END AS TypeOfInjured,

     B.IncidentDate

    FROM InfectionControl.BloodExposure B

ਊ    䰀䔀䘀吀 䨀伀䤀一 一甀爀猀椀渀最⸀䔀洀瀀氀漀礀攀攀 䔀ഀ਀        伀一 䈀⸀䔀洀瀀䤀䐀 㴀 䔀⸀䤀搀ഀ਀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀 倀ഀ਀        伀一 䈀⸀倀愀琀椀攀渀琀䤀䐀 㴀 倀⸀䤀搀ഀ਀ഀ਀    圀䠀䔀刀䔀 䈀⸀䤀渀挀椀搀攀渀琀䐀愀琀攀 㸀㴀 䀀昀爀漀洀ഀ਀  䄀一䐀 䈀⸀䤀渀挀椀搀攀渀琀䐀愀琀攀 㰀 䐀䄀吀䔀䄀䐀䐀⠀䐀䄀夀Ⰰ ㄀Ⰰ 䀀琀漀⤀ഀ਀ഀ਀䔀一䐀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀倀开䈀氀漀漀搀䔀砀瀀漀猀甀爀攀刀攀瀀漀爀琀䄀爀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀䌀刀䔀䄀吀䔀   倀刀伀䌀䔀䐀唀刀䔀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀倀开䈀氀漀漀搀䔀砀瀀漀猀甀爀攀刀攀瀀漀爀琀䄀爀崀ഀ਀    䀀昀爀漀洀 瘀愀爀挀栀愀爀⠀㌀　⤀Ⰰഀ਀    䀀琀漀   瘀愀爀挀栀愀爀⠀㌀　⤀ഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀    匀䔀吀 一伀䌀伀唀一吀 伀一㬀ഀ਀ഀ਀    匀䔀䰀䔀䌀吀ഀ਀     ഀ਀        䤀匀一唀䰀䰀⠀䔀⸀䘀椀爀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀ ഀ਀        䤀匀一唀䰀䰀⠀䔀⸀䴀椀搀搀氀攀一愀洀攀䄀爀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀ഀ਀        䤀匀一唀䰀䰀⠀䔀⸀䈀攀昀漀爀攀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀ഀ਀        䤀匀一唀䰀䰀⠀䔀⸀䰀愀猀琀一愀洀攀䄀爀Ⰰ ✀✀⤀ 䄀匀 ✀✀㌆䔆 ✀䐆䔆䠆㠆䄆✆Ⰰഀ਀ഀ਀        䤀匀一唀䰀䰀⠀倀⸀䘀椀爀猀琀一愀洀攀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀਀        䤀匀一唀䰀䰀⠀倀⸀䴀椀搀搀氀攀一愀洀攀㄀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀਀        䤀匀一唀䰀䰀⠀倀⸀䴀椀搀搀氀攀一愀洀攀㈀Ⰰ ✀✀⤀ ⬀ ✀ ✀ ⬀਀        䤀匀一唀䰀䰀⠀倀⸀䰀愀猀琀一愀洀攀Ⰰ ✀✀⤀ 䄀匀 ✀✀㌆䔆 ✀䐆䔆ㄆ䨆㘆✆Ⰰഀ਀ऀऀ     ഀ਀        倀⸀䌀漀搀攀 䄀匀 ✀䐆䌆䠆⼆Ⰶഀ਀ഀ਀        ഀ਀    䌀䄀匀䔀 䈀⸀吀礀瀀攀伀昀䔀砀瀀漀猀甀爀攀䤀搀ഀ਀    圀䠀䔀一 ㄀ 吀䠀䔀一 一✀䠀⸆㈆ ─⠆ㄆ⤆✆ഀ਀    圀䠀䔀一 ㈀ 吀䠀䔀一 一✀Ⰰㄆⴆ ⠀䔆㐆ㄆ㜆✆ഀ਀    圀䠀䔀一 ㌀ 吀䠀䔀一 一✀⨀䘆✆⬆ㄆ ⼀䔆 㤀䐆䤆 ✀䐆䠆Ⰶ䜆✆ഀ਀    圀䠀䔀一 㐀 吀䠀䔀一 一✀⨀䘆✆⬆ㄆ ㌀䠆✆☆䐆 㤀䐆䤆 ✀䐆䠆Ⰶ䜆✆ഀ਀    䔀䰀匀䔀 一✀㨀䨆ㄆ 䔀㤆ㄆ䠆䄆✆ഀ਀ऀ䔀一䐀 䄀匀 ✀䘀䠆㤆 ✀䐆┆㔆✆⠆⤆✆Ⰰഀ਀ഀ਀     䈀⸀䤀渀挀椀搀攀渀琀䐀愀琀攀 愀猀 ✀⨀✆ㄆ䨆⸆ ✀䐆ⴆ✆⼆⬆⤆✆ഀ਀ഀ਀    䘀刀伀䴀 䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀⸀䈀氀漀漀搀䔀砀瀀漀猀甀爀攀 䈀ഀ਀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 一甀爀猀椀渀最⸀䔀洀瀀氀漀礀攀攀 䔀ഀ਀        伀一 䈀⸀䔀洀瀀䤀䐀 㴀 䔀⸀䤀搀ഀ਀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀 倀ഀ਀        伀一 䈀⸀倀愀琀椀攀渀琀䤀䐀 㴀 倀⸀䤀搀ഀ਀ഀ਀    圀䠀䔀刀䔀 䈀⸀䤀渀挀椀搀攀渀琀䐀愀琀攀 㸀㴀 䀀昀爀漀洀ഀ਀  䄀一䐀 䈀⸀䤀渀挀椀搀攀渀琀䐀愀琀攀 㰀 䐀䄀吀䔀䄀䐀䐀⠀䐀䄀夀Ⰰ ㄀Ⰰ 䀀琀漀⤀ഀ਀ഀ਀䔀一䐀ഀ਀䜀伀ഀ਀⼀⨀⨀⨀⨀⨀⨀ 伀戀樀攀挀琀㨀  匀琀漀爀攀搀倀爀漀挀攀搀甀爀攀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀倀开䤀渀昀攀挀琀椀漀甀猀䐀椀猀攀愀猀攀崀    匀挀爀椀瀀琀 䐀愀琀攀㨀 㠀⼀㈀㜀⼀㈀　㈀㘀 ㈀㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 倀刀伀䌀䔀䐀唀刀䔀 嬀䤀渀昀攀挀琀椀漀渀䌀漀渀琀爀漀氀崀⸀嬀匀倀开䤀渀昀攀挀琀椀漀甀猀䐀椀猀攀愀猀攀崀ഀ਀    䀀䘀爀漀洀䐀愀琀攀 䐀䄀吀䔀吀䤀䴀䔀 㴀 一唀䰀䰀Ⰰഀ਀    䀀吀漀䐀愀琀攀 䐀䄀吀䔀吀䤀䴀䔀 㴀 一唀䰀䰀ഀ਀䄀匀ഀ਀䈀䔀䜀䤀一ഀ਀    匀䔀吀 一伀䌀伀唀一吀 伀一㬀ഀ਀    ഀ਀    䈀䔀䜀䤀一 吀刀夀ഀ਀        䐀䔀䌀䰀䄀刀䔀 䀀匀琀愀爀琀䐀愀琀攀 䐀䄀吀䔀吀䤀䴀䔀 㴀 䤀匀一唀䰀䰀⠀䀀䘀爀漀洀䐀愀琀攀Ⰰ 䌀伀一嘀䔀刀吀⠀䐀䄀吀䔀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀⤀ഀ਀        䐀䔀䌀䰀䄀刀䔀 䀀䔀渀搀䐀愀琀攀 䐀䄀吀䔀吀䤀䴀䔀 㴀 䤀匀一唀䰀䰀⠀䀀吀漀䐀愀琀攀Ⰰ 䌀伀一嘀䔀刀吀⠀䐀䄀吀䔀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀⤀ഀ਀        ഀ਀        ⴀⴀ 嘀愀氀椀搀愀琀攀 搀愀琀攀 爀愀渀最攀ഀ਀        䤀䘀 䀀匀琀愀爀琀䐀愀琀攀 㸀 䀀䔀渀搀䐀愀琀攀ഀ਀        䈀䔀䜀䤀一ഀ਀            吀䠀刀伀圀 㔀　　　㄀Ⰰ ✀䘀爀漀洀䐀愀琀攀 挀愀渀渀漀琀 戀攀 最爀攀愀琀攀爀 琀栀愀渀 吀漀䐀愀琀攀✀Ⰰ ㄀ഀ਀        䔀一䐀ഀ਀ഀ਀        匀䔀䰀䔀䌀吀 ഀ਀
            -- Facility Information
            ISNULL(br.NameEn, 'Unknown Facility') AS [FACILITY NAME],
            
            -- Patient Information
            p.Code AS [S.N. / PATIENT ID / MRN],
            CONCAT(ISNULL(p.FirstName, ''), ' ', ISNULL(p.MiddleName1, ''), ' ', ISNULL(p.LastName, '')) AS [PATIENT NAME],
            p.MobileNumber AS [PATIENT MOBILE NUMBER],
            p.Email AS [PATIENT EMAIL],
            
            -- Patient Status
            CASE 
                WHEN p.PatientClassificationId = 1 THEN 'UAE Citizen'
                WHEN p.PatientClassificationId = 2 THEN 'Resident'
                WHEN p.PatientClassificationId = 3 THEN 'International Patient'
                ELSE 'Unknown'
            END AS [Resident/ International Patient / UAE Citizen],
            
            p.IdNumber AS [EID],
            p.PassportNumber AS [PASSPORT],
            
            CASE WHEN p.GenderId = 1 THEN 'Male' WHEN p.GenderId = 2 THEN 'Female' ELSE 'Unknown' END AS [GENDER],
            
            ISNULL(UPPER(c.Name), '') AS [NATIONALITY],
            CAST(p.DateOfBirth AS DATE) AS [DATE OF BIRTH],
            DATEDIFF(YEAR, p.DateOfBirth, GETDATE()) AS [AGE],
            
            -- Residence Information
            '' AS [EMIRATE OF RESIDENCE],
            '' AS [EMIRATE OF WORK],
            p.Address AS [ADDRESS],
            p.Occupation AS [OCCUPATION],
            
            '' AS [PEOPLE OF DETERMINATION (YES / NO)],
            
            -- Infection Information
            CAST(vics.StartDate AS DATE) AS [INFECTION DATE],--vics.StartDate AS [INFECTION DATE],
            ISNULL(CONVERT(VARCHAR(8), vics.StartDate, 108), '') AS [INFECTION TIME],
            
            -- Patient Outcome
            CASE WHEN vics.EndDate IS NOT NULL THEN 'Discharged' ELSE 'Ongoing' END AS [OUTCOME],
           CAST(vics.EndDate  AS DATE) AS  [DATE OF OUTCOME],-- vics.EndDate AS [DATE OF OUTCOME],
            
            -- Vital Signs
            ISNULL((SELECT TOP 1 vs.Weight FROM [InPatient].[VitalSigns] vs 
                    WHERE vs.PatientID = p.Id 
ਊ                    䄀一䐀 䌀䄀匀吀⠀瘀猀⸀嬀䐀愀琀攀崀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瘀猀⸀嬀䐀愀琀攀崀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀倀䄀吀䤀䔀一吀 圀䔀䤀䜀䠀吀崀Ⰰഀ਀                    ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 瘀猀⸀䠀攀椀最栀琀 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀匀椀最渀猀崀 瘀猀 ഀ਀                    圀䠀䔀刀䔀 瘀猀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瘀猀⸀嬀䐀愀琀攀崀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瘀猀⸀嬀䐀愀琀攀崀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀倀䄀吀䤀䔀一吀 䠀䔀䤀䜀䠀吀崀Ⰰഀ਀                    ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 䤀匀一唀䰀䰀⠀瘀猀⸀䈀氀漀漀搀倀爀攀猀猀甀爀攀开匀夀匀吀伀䰀䤀䌀Ⰰ 瘀猀⸀匀礀猀琀漀氀攀开䴀䴀开䠀最⤀ 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀匀椀最渀猀崀 瘀猀 ഀ਀                    圀䠀䔀刀䔀 瘀猀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瘀猀⸀嬀䐀愀琀攀崀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瘀猀⸀嬀䐀愀琀攀崀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀匀夀匀吀伀䰀䤀䌀 䈀䰀伀伀䐀 倀刀䔀匀匀唀刀䔀崀Ⰰഀ਀                    ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 䤀匀一唀䰀䰀⠀瘀猀⸀䈀氀漀漀搀倀爀攀猀猀甀爀攀开䐀䤀䄀匀吀伀䰀䤀䌀Ⰰ 瘀猀⸀䐀椀愀猀琀漀氀攀开䴀䴀开䠀最⤀ 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀匀椀最渀猀崀 瘀猀 ഀ਀                    圀䠀䔀刀䔀 瘀猀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瘀猀⸀嬀䐀愀琀攀崀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瘀猀⸀嬀䐀愀琀攀崀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀䐀䤀䄀匀吀伀䰀䤀䌀 䈀䰀伀伀䐀 倀刀䔀匀匀唀刀䔀崀Ⰰഀ਀                    ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 瘀猀⸀吀攀洀瀀䌀 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀匀椀最渀猀崀 瘀猀 ഀ਀                    圀䠀䔀刀䔀 瘀猀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瘀猀⸀嬀䐀愀琀攀崀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瘀猀⸀嬀䐀愀琀攀崀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀倀䄀吀䤀䔀一吀 吀䔀䴀倀䔀刀䄀吀唀刀䔀崀Ⰰഀ਀            ഀ਀            ⴀⴀ 䐀椀猀攀愀猀攀 䤀渀昀漀爀洀愀琀椀漀渀 ⴀ 倀爀椀洀愀爀礀 䐀椀愀最渀漀猀椀猀ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 椀挀搀⸀䤀䌀䐀䌀漀搀攀 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀䴀攀搀椀挀愀氀伀戀猀攀爀瘀愀琀椀漀渀䤀䌀䐀䌀漀搀攀猀崀 洀漀椀挀搀ഀ਀                    䤀一一䔀刀 䨀伀䤀一 嬀一甀爀猀椀渀最崀⸀嬀䤀䌀䐀䌀漀搀攀猀崀 椀挀搀 伀一 洀漀椀挀搀⸀䤀䌀䐀䌀漀搀攀䤀䐀 㴀 椀挀搀⸀䤀搀ഀ਀                    圀䠀䔀刀䔀 洀漀椀挀搀⸀䴀攀搀椀挀愀氀伀戀猀攀爀瘀愀琀椀漀渀䤀䐀 䤀一 ⠀ഀ਀                        匀䔀䰀䔀䌀吀 洀漀⸀䤀搀 䘀刀伀䴀 嬀䤀渀倀愀琀椀攀渀琀崀⸀嬀䴀攀搀椀挀愀氀伀戀猀攀爀瘀愀琀椀漀渀崀 洀漀 ഀ਀                        圀䠀䔀刀䔀 洀漀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀 ഀ਀                        䄀一䐀 䌀䄀匀吀⠀洀漀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ 㸀㴀 䌀䄀匀吀⠀愀瀀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    ⤀ഀ਀                    䄀一䐀 洀漀椀挀搀⸀吀礀瀀攀 㴀 ㄀ഀ਀                    伀刀䐀䔀刀 䈀夀 洀漀椀挀搀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䐀䔀匀䌀⤀Ⰰ ✀✀⤀ 䄀匀 嬀䐀䤀匀䔀䄀匀䔀 䤀䌀䐀 䌀伀䐀䔀崀Ⰰഀ਀                    ഀ਀
            ISNULL((SELECT TOP 1 icd.ICDDescription FROM [InPatient].[MedicalObservationICDCodes] moicd
                    INNER JOIN [Nursing].[ICDCodes] icd ON moicd.ICDCodeID = icd.Id
                    WHERE moicd.MedicalObservationID IN (
                        SELECT mo.Id FROM [InPatient].[MedicalObservation] mo 
                        WHERE mo.PatientID = p.Id 
                        AND CAST(mo.CreatedDate AS DATE) >= CAST(ap.AdmissionDate AS DATE)
                    )
                    AND moicd.Type = 1
                    ORDER BY moicd.CreatedDate DESC), '') AS [DISEASE NAME],
            
            -- Case Classification
            ISNULL(vics.NameEn, '') AS [CASE CLASSIFICATION],
            
            -- Physician Information
            ISNULL(d.Name, '') AS [PHYSICIAN NAME],
            ISNULL(ds.Name, '') AS [PHYSICIAN SPECIALTY],
            ISNULL(d.LINCESE, '') AS [PHYSICIAN LICENSE NUMBER]
            
        FROM [Registration].[Patients] p
        INNER JOIN [InPatient].[AdmitPatients] ap 
            ON p.Id = ap.PatientID
            AND CAST(ap.AdmissionDate AS DATE) >= CAST(@StartDate AS DATE)
            AND CAST(ap.AdmissionDate AS DATE) <= CAST(@EndDate AS DATE)
        LEFT JOIN [InfectionControl].[VUGetInfectionControlICUServices] vics
            ON p.Id = ap.PatientID
            AND CAST(vics.StartDate AS DATE) >= CAST(@StartDate AS DATE)
            AND CAST(vics.StartDate AS DATE) <= CAST(@EndDate AS DATE)
        LEFT JOIN [HR].[Branches] br 
            ON ap.BranchId = br.ID
        LEFT JOIN [Registration].[Doctors] d 
            ON ap.AdmitDoctorID = d.Id
        LEFT JOIN [ApplicationSetup].[Doctor] ds 
            ON d.SpecialtyId = ds.Id
        LEFT JOIN [ApplicationSetup].[Country] c 
            ON p.NationalityId = c.Id
        
        WHERE ap.Id IS NOT NULL
        ORDER BY ap.AdmissionDate DESC, p.Id
        
    END TRY
