/****** Object:  StoredProcedure [InfectionControl].[StuffHelthCareProgramREp]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [InfectionControl].[StuffHelthCareProgramREp](@EmpID int )
as
begin
select 
  EmployeeId
	  
	  ,DiseaseName
	  ,Case StHD_Status when 1 then'Yes' when 0 then 'No' when 2 then 'Unknown' End as StHD_Status
	  ,STHD_Comment
	  ,STH_Comment
	  ,SubDeptName
	  ,DeptName
	  ,EmployeeCode
	  ,EmpName
	  ,StatusDate
	  ,EmpNameEn

 , case category when 1 then 'Disease Communicable' when 2 then 'Disease Chronic' end as [Type]
 from InfectionControl.V_StuffHelthCareProgramDis
where V_StuffHelthCareProgramDis.EmployeeID =@EmpID
union 
select 
EmployeeId
	  ,vaccinationName
	 
	  ,Case StHV_Status when 1 then'Yes' when 0 then 'No' when 2 then 'Unknown' End as StHV_Status
	  ,STHV_Comment
	  ,STH_Comment
	  ,SubDeptName
	  ,DeptName
	  ,EmployeeCode
	  ,EmpName
	  ,StatusDate
	  	  ,EmpNameEn
 ,'Vaccination' as [Type]
 from InfectionControl.V_StuffHelthCareProgramVacc
where V_StuffHelthCareProgramVacc.EmployeeID =@EmpID
 End












