/****** Object:  StoredProcedure [InPatient].[BedOccupancyReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [InPatient].[BedOccupancyReport]
@WardID int,
@IPNO  nvarchar(50)
as
select 
InPatient.Ward.Name,
InPatient.Room.RoomNumber,
InPatient.Bed.BedNumber,
Registration.Patients.Code,
Registration.Patients.FirstName +' '+ Registration.Patients.MiddleName1 +' '+ Registration.Patients.MiddleName2 +' '+ Registration.Patients.LastName as PatientName,
case when Registration.Patients.GenderId = 1 then 'M'
     when Registration.Patients.GenderId = 2 then 'F' else 'Other'  end as Gender,

InPatient.AdmitPatients.IPNumber,
Registration.Doctors.Name,
InPatient.AdmitPatients.AdmissionDate
from InPatient.Ward left join InPatient.Room
on InPatient.Ward.Id=InPatient.Room.WardId
left join InPatient.Bed 
on InPatient.Room.Id = InPatient.Bed.RoomId
left join InPatient.BedStatus
on InPatient.Bed.BedStatusId = InPatient.BedStatus.Id
left join InPatient.AdmitPatients
on InPatient.Bed.Id=InPatient.AdmitPatients.BedNO
left join Registration.Patients
on InPatient.AdmitPatients.PatientID=Registration.Patients.Id
left join Registration.Doctors
on InPatient.AdmitPatients.DoctorID=Registration.Doctors.Id
where InPatient.BedStatus.Name != 'Vacant'
and (InPatient.Ward.Id = @WardID or @WardID is null)
and (InPatient.AdmitPatients.IPNumber = @IPNO or @IPNO is null )







GO
