-- =============================================
CREATE procEDURE [InPatient].[Daily_Sponser_Report](@TodayDate   Nvarchar(20)=null )

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	
		SELECT [InPatient].Ward.[Name] as WardName ,
	       [InPatient].Ward.[Description],

		   [InPatient].WardType.[Name] as WardType ,

	       [Registration].Patients.FirstName
							+''+ [Registration].Patients.MiddleName1
							+''+ [Registration].Patients.MiddleName2
							+''+ [Registration].Patients.LastName As PatientName,
            [Registration].Patients.Code As PatientCode,
            [InPatient].Room.RoomNumber   AS RoomNumber,
		    [InPatient].Room.Id  AS RoomID,
			[InPatient].Room.Code AS RoomCode,

			[InPatient].Bed.BedNumber AS BedNumber,
			[InPatient].Bed.Code AS BedCode,
			[InPatient].Bed.Id AS BedID,

			[Registration].Doctors.Id  AS DoctorID,
			[Registration].Doctors.NameAr AS DoctorName,

			[Billing].Sponsor.Id AS SponsorID,
			[Billing].Sponsor.Name AS SponsorName


			
	from [InPatient].Ward
	    
	    join [InPatient].WardType on [InPatient].Ward.WardTypeId=[InPatient].WardType.Id
		join [InPatient].Room on [InPatient].Ward.Id=[InPatient].Room.WardId		
