CREATE proc [InPatient].[DailyAdmissionDischargeSummary]
@AdmissionDate datetime ,
@WardID	int,
@IPNo nvarchar(50)
as
begin
select
row_number() over (order by newid()) ,
InPatient.AdmitPatients.AdmissionDate,
InPatient.Ward.Name,
InPatient.Bed.BedNumber,
Registration.Patients.Code,
Registration.Patients.FirstName +' '+ Registration.Patients.MiddleName1 +' '+Registration.Patients.MiddleName2 +' '+  Registration.Patients.LastName ,
CASe when Registration.Patients.GenderId = 1 then 'M'
     when Registration.Patients.GenderId = 2 then 'F' else 'Other' end ,
InPatient.AdmitPatients.IPNumber,
Registration.Doctors.Name,
Billing.CustomerMaster.CustomerName
from InPatient.AdmitPatients left join Registration.Patients
on  InPatient.AdmitPatients.PatientID = Registration.Patients.Id
left join Registration.Doctors
on InPatient.AdmitPatients.DoctorID = Registration.Doctors.Id
left join InPatient.AdmissionRequest
on InPatient.AdmitPatients.AdmissionRequestID = InPatient.AdmissionRequest.Id
left join  InPatient.Ward
on InPatient.AdmissionRequest.AdmissionWardID=InPatient.Ward.Id
left join InPatient.Bed
on InPatient.AdmissionRequest.BedNO=InPatient.Bed.Id
left join Billing.CustomerMaster
on Registration.Patients.SponsorId = Billing.CustomerMaster.Id
where InPatient.AdmitPatients.DischargeStatusId = 4
and  CAST( InPatient.AdmitPatients.AdmissionDate as date) =CAST(@AdmissionDate as date)
and (InPatient.Ward.Id=@WardID or @WardID is null)
and (InPatient.AdmitPatients.IPNumber=@IPNo or @IPNo is null)
end







