, Nursing.ICDCodes.ICDCode, Nursing.ICDCodes.ICDDescription

,REPLACE(InPatient.AdmitPatients.AdmissionTime,'.0000000','')AdmissionTime , InPatient.AdmitPatients.AdmissionDate, InPatient.PatientDischarge.DeathDate, InPatient.PatientDischarge.DeathTime, Emergency.EmergencyUnit.[Date]

FROM            Registration.Nationalities RIGHT OUTER JOIN
                         Emergency.EmergencyUnit INNER JOIN
                         Registration.Patients INNER JOIN
                         ApplicationSetup.IdentificationTypes ON Registration.Patients.TypeId = ApplicationSetup.IdentificationTypes.Id INNER JOIN
                         ApplicationSetup.City ON Registration.Patients.Active = ApplicationSetup.City.Id INNER JOIN
                         InPatient.AdmitPatients ON Registration.Patients.Id = InPatient.AdmitPatients.PatientID INNER JOIN
                         InPatient.PatientDischarge ON Registration.Patients.Id = InPatient.PatientDischarge.PatientId ON Emergency.EmergencyUnit.ID = InPatient.PatientDischarge.EmergencyUnitID LEFT OUTER JOIN
                         InPatient.MedicalObservation ON InPatient.AdmitPatients.IPNumber = InPatient.MedicalObservation.IP_OP ON Registration.Nationalities.Id = Registration.Patients.NationalityId LEFT OUTER JOIN
                         InPatient.MedicalObservationICDCodes ON InPatient.MedicalObservation.Id = InPatient.MedicalObservationICDCodes.MedicalObservationID LEFT OUTER JOIN
                         Nursing.ICDCodes ON InPatient.MedicalObservationICDCodes.ICDCodeID = Nursing.ICDCodes.Id
WHERE        (InPatient.PatientDischarge.DisChargeTypeId = 8)

and cast( CONVERT(char(8), inPatient.PatientDischarge.DeathDate,112) as bigint) between @FromDate and @Todate
