GO
CREATE PROC [InPatient].[Dars_PatientsData]-- '',20200101,20251231,1
    @Title NVARCHAR(4000),
    @FromDate INT,
    @Todate INT,
    @PatientTypeId INT = NULL  -- الباراميتر الجديد
AS
BEGIN
    SET NOCOUNT ON;

    /* =====================================================
       ICD DATA (ONCE FOR ALL)
       ===================================================== */
    WITH ICD_CTE AS
    (
        SELECT
            MO.IP_OP,
            IC.ICDCode + '-' + IC.ICDDescription AS ICDValue,
            ROW_NUMBER() OVER
            (
                PARTITION BY MO.IP_OP
                ORDER BY IC.ICDCode
            ) AS RN
        FROM InPatient.MedicalObservation MO
        INNER JOIN InPatient.MedicalObservationICDCodes MOI
            ON MO.Id = MOI.MedicalObservationID
        INNER JOIN Nursing.ICDCodes IC
            ON MOI.ICDCodeID = IC.Id
    ),
    ICD_PIVOT AS
    (
        SELECT
            IP_OP,
            MAX(CASE WHEN RN = 1 THEN ICDValue END) AS ICDcode1,
            MAX(CASE WHEN RN = 2 THEN ICDValue END) AS ICDcode2,
            MAX(CASE WHEN RN = 3 THEN ICDValue END) AS ICDcode3,
            MAX(CASE WHEN RN = 4 THEN ICDValue END) AS ICDcode4,
            MAX(CASE WHEN RN = 5 THEN ICDValue END) AS ICDcode5,
            MAX(CASE WHEN RN = 6 THEN ICDValue END) AS ICDcode6,
            MAX(CASE WHEN RN = 7 THEN ICDValue END) AS ICDcode7,
            MAX(CASE WHEN RN = 8 THEN ICDValue END) AS ICDcode8
        FROM ICD_CTE
        GROUP BY IP_OP
    )

ਊ    ⼀⨀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀       伀倀 倀䄀吀䤀䔀一吀匀ഀ਀       㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀 ⨀⼀ഀ਀    匀䔀䰀䔀䌀吀 ഀ਀        䌀吀⸀一愀洀攀䔀渀 䄀匀 挀漀甀渀琀爀礀一愀洀攀Ⰰഀ਀        ⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 匀攀爀椀愀氀一甀洀 䘀刀伀䴀 䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀䌀漀洀瀀愀渀礀⤀ 䄀匀 匀攀爀椀愀氀一甀洀Ⰰഀ਀        䌀䄀匀䔀 ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㄀ 吀䠀䔀一 ✀䴀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㈀ 吀䠀䔀一 ✀䘀攀洀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㌀ 吀䠀䔀一 ✀唀渀搀攀琀攀爀洀椀渀攀搀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 㐀 吀䠀䔀一 ✀唀渀搀椀昀昀攀爀攀渀琀椀愀琀攀搀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 㔀 吀䠀䔀一 ✀匀攀砀挀栀愀渀最攀搀琀漀䴀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 㘀 吀䠀䔀一 ✀匀攀砀挀栀愀渀最攀搀琀漀昀攀洀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 㜀 吀䠀䔀一 ✀一漀琀䌀漀洀瀀氀攀琀攀搀✀ ഀ਀            䔀䰀匀䔀 ✀✀ ഀ਀        䔀一䐀 䄀匀 䜀䔀一䐀䔀刀Ⰰ   ഀ਀        䌀䄀匀䔀 圀䠀䔀一 倀⸀吀礀瀀攀䤀搀 㴀 ㄀ 吀䠀䔀一 ✀䔀洀椀爀愀琀攀猀 䤀䐀✀ 䔀䰀匀䔀 ✀倀愀猀猀瀀漀爀琀✀ 䔀一䐀 䄀匀 䐀吀礀瀀攀Ⰰഀ਀        瀀⸀䴀漀戀椀氀攀一甀洀戀攀爀Ⰰഀ਀        ⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 一愀洀攀 䘀刀伀䴀 䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀䌀漀洀瀀愀渀礀⤀ 䄀匀 嬀䘀愀挀椀氀椀琀礀 一愀洀攀崀Ⰰഀ਀        倀⸀䌀漀搀攀 䄀匀 嬀匀⸀一⸀ ⼀ 倀䄀吀䤀䔀一吀 䤀䐀 ⼀ 䴀刀一崀Ⰰഀ਀        倀⸀吀爀愀渀猀氀愀琀攀搀䘀愀氀氀一愀洀攀Ⰰഀ਀        䤀匀一唀䰀䰀⠀倀⸀䘀椀爀猀琀一愀洀攀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ 䤀匀一唀䰀䰀⠀倀⸀䴀椀搀搀氀攀一愀洀攀㄀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ 䤀匀一唀䰀䰀⠀倀⸀䴀椀搀搀氀攀一愀洀攀㈀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ 䤀匀一唀䰀䰀⠀倀⸀䰀愀猀琀一愀洀攀Ⰰ✀✀⤀ 䄀匀 嬀倀䄀吀䤀䔀一吀 一䄀䴀䔀崀Ⰰഀ਀        倀⸀䴀漀戀椀氀攀一甀洀戀攀爀Ⰰഀ਀        倀⸀䔀洀愀椀氀Ⰰഀ਀        倀⸀䤀搀一甀洀戀攀爀Ⰰഀ਀        倀⸀倀愀猀猀瀀漀爀琀一甀洀戀攀爀Ⰰഀ਀        䌀䄀匀䔀 倀⸀吀礀瀀攀䤀搀ഀ਀            圀䠀䔀一 ㄀ 吀䠀䔀一 ✀唀䄀䔀 䌀椀琀椀稀攀渀✀ഀ਀            圀䠀䔀一 ㈀ 吀䠀䔀一 ✀刀攀猀椀搀攀渀琀✀ഀ਀            䔀䰀匀䔀 ✀椀渀琀攀爀渀愀琀椀漀渀愀氀✀ഀ਀        䔀一䐀 䄀匀 吀礀瀀攀Ⰰഀ਀        ✀伀倀✀ 䄀匀 嬀倀䄀吀䤀䔀一吀 吀夀倀䔀崀Ⰰഀ਀        一⸀一愀洀攀䔀渀 䄀匀 一䄀吀䤀伀一䄀䰀吀夀Ⰰഀ਀        䌀䄀匀吀⠀倀⸀䐀愀琀攀伀昀䈀椀爀琀栀 䄀匀 䐀䄀吀䔀⤀ 䄀匀 䐀愀琀攀伀昀䈀椀爀琀栀Ⰰഀ਀        䐀䄀吀䔀䐀䤀䘀䘀⠀夀䔀䄀刀Ⰰ 倀⸀䐀愀琀攀伀昀䈀椀爀琀栀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀ ⴀഀ਀        䌀䄀匀䔀ഀ਀            圀䠀䔀一 䐀䄀吀䔀䄀䐀䐀⠀夀䔀䄀刀Ⰰ 䐀䄀吀䔀䐀䤀䘀䘀⠀夀䔀䄀刀Ⰰ 倀⸀䐀愀琀攀伀昀䈀椀爀琀栀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀Ⰰ 倀⸀䐀愀琀攀伀昀䈀椀爀琀栀⤀ 㸀 䜀䔀吀䐀䄀吀䔀⠀⤀ഀ਀            吀䠀䔀一 ㄀ 䔀䰀匀䔀 　ഀ਀        䔀一䐀 䄀匀 䄀最攀Ⰰഀ਀        䌀⸀一愀洀攀䔀渀 䄀匀 嬀䔀䴀䤀刀䄀吀䔀 伀䘀 刀䔀匀䤀䐀䔀一䌀䔀崀Ⰰഀ਀        ✀✀ 䄀匀 嬀䔀䴀䤀刀䄀吀䔀 伀䘀 圀伀刀䬀崀Ⰰഀ਀        倀⸀䄀搀搀爀攀猀猀Ⰰഀ਀        倀⸀伀挀挀甀瀀愀琀椀漀渀Ⰰഀ਀        ✀一漀✀ 䄀匀 嬀倀䔀伀倀䰀䔀 伀䘀 䐀䔀吀䔀刀䴀䤀一䄀吀䤀伀一崀Ⰰഀ਀        䤀刀䠀⸀伀倀开䤀倀一甀洀戀攀爀Ⰰഀ਀        䐀⸀一愀洀攀 䄀匀 䐀漀挀琀漀爀一愀洀攀Ⰰഀ਀        匀䜀⸀一愀洀攀 䄀匀 匀瀀攀挀椀愀氀椀琀礀Ⰰഀ਀        倀嘀匀⸀伀倀渀甀洀戀攀爀Ⰰഀ਀        䌀䄀匀吀⠀倀嘀匀⸀吀椀洀攀伀昀嘀椀猀椀琀 䄀匀 嘀䄀刀䌀䠀䄀刀⤀ 䄀匀 吀漀琀愀氀洀攀搀椀挀愀氀猀瀀攀渀搀椀渀䄀䔀䐀Ⰰഀ਀        ✀伀甀琀ⴀ倀愀琀椀攀渀琀✀ 䄀匀 倀愀琀椀攀渀琀吀礀瀀攀伀昀嘀椀猀椀琀Ⰰഀ਀        䐀䐀匀⸀匀挀栀攀搀甀氀攀䐀愀琀攀 䄀匀 䐀愀琀攀漀昀愀搀洀椀猀猀椀漀渀Ⰰഀ਀        䐀䐀匀⸀匀挀栀攀搀甀氀攀䐀愀琀攀 䄀匀 䐀椀猀挀栀愀爀最䐀愀琀攀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㄀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㈀Ⰰഀ਀
        ICD.ICDcode3,
        ICD.ICDcode4,
        ICD.ICDcode5,
        ICD.ICDcode6,
        ICD.ICDcode7,
        ICD.ICDcode8
    FROM Registration.Patients P
    INNER JOIN OutPatient.InvestigationRequestHeader IRH ON P.Id = IRH.PatientID
    INNER JOIN OutPatient.PrepareVisitSlip PVS ON IRH.OP_IPNumber = PVS.OPnumber
    INNER JOIN Registration.Doctors D ON IRH.DoctorID = D.Id
    INNER JOIN OutPatient.SpecialityGroupDetails SG ON D.Id = SG.ID
    INNER JOIN Registration.DoctorsDailyScheduleDetails DDSD ON PVS.ScheduleAppointmentID = DDSD.Id
    INNER JOIN Registration.DoctorsDailySchedule DDS ON DDSD.DoctorsDailyScheduleID = DDS.Id
    LEFT JOIN Registration.Nationalities N ON P.NationalityId = N.Id
    LEFT JOIN ApplicationSetup.City C ON P.Active = C.Id
    LEFT JOIN ICD_PIVOT ICD ON ICD.IP_OP = PVS.OPnumber
    LEFT JOIN ApplicationSetup.Country CT ON P.CountryId = CT.Id
    WHERE
        PVS.VisitStatus = 2
        AND CONVERT(INT, CONVERT(CHAR(8), IRH.ReqDate, 112)) BETWEEN @FromDate AND @Todate
        AND (@PatientTypeId IS NULL OR P.TypeId = @PatientTypeId)

    UNION ALL

    /* =====================================================
       IP PATIENTS
       ===================================================== */
    SELECT 
        CT.NameEn AS countryName,
        (SELECT TOP 1 SerialNum FROM ApplicationSetup.Company) AS SerialNum,
        CASE 
            WHEN P.GenderId = 1 THEN 'Male' 
            WHEN P.GenderId = 2 THEN 'Female' 
            WHEN P.GenderId = 3 THEN 'Undetermined' 
            WHEN P.GenderId = 4 THEN 'Undifferentiated' 
            WHEN P.GenderId = 5 THEN 'SexchangedtoMale' 
            WHEN P.GenderId = 6 THEN 'Sexchangedtofemale' 
            WHEN P.GenderId = 7 THEN 'NotCompleted' 
            ELSE '' 
        END AS GENDER,   
        CASE WHEN P.TypeId = 1 THEN 'Emirates ID' ELSE 'Passport' END AS DType,
        p.MobileNumber,
        (SELECT TOP 1 Name FROM ApplicationSetup.Company),
        P.Code,
        P.TranslatedFallName,
        ISNULL(P.FirstName,'') + ' ' + ISNULL(P.MiddleName1,'') + ' ' + ISNULL(P.MiddleName2,'') + ' ' + ISNULL(P.LastName,''),
        P.MobileNumber,
        P.Email,
ਊ        倀⸀䤀搀一甀洀戀攀爀Ⰰഀ਀        倀⸀倀愀猀猀瀀漀爀琀一甀洀戀攀爀Ⰰഀ਀       䌀䄀匀䔀 倀⸀吀礀瀀攀䤀搀ഀ਀            圀䠀䔀一 ㄀ 吀䠀䔀一 ✀唀䄀䔀 䌀椀琀椀稀攀渀✀ഀ਀            圀䠀䔀一 ㈀ 吀䠀䔀一 ✀刀攀猀椀搀攀渀琀✀ഀ਀            䔀䰀匀䔀 ✀椀渀琀攀爀渀愀琀椀漀渀愀氀✀ഀ਀        䔀一䐀 䄀匀 吀礀瀀攀Ⰰഀ਀        ✀䤀倀✀Ⰰഀ਀        一⸀一愀洀攀䔀渀Ⰰഀ਀        䌀䄀匀吀⠀倀⸀䐀愀琀攀伀昀䈀椀爀琀栀 䄀匀 䐀䄀吀䔀⤀Ⰰഀ਀        䐀䄀吀䔀䐀䤀䘀䘀⠀夀䔀䄀刀Ⰰ 倀⸀䐀愀琀攀伀昀䈀椀爀琀栀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀Ⰰഀ਀        䌀⸀一愀洀攀䔀渀Ⰰഀ਀        ✀✀Ⰰഀ਀        倀⸀䄀搀搀爀攀猀猀Ⰰഀ਀        倀⸀伀挀挀甀瀀愀琀椀漀渀Ⰰഀ਀        ✀一漀✀Ⰰഀ਀        倀䐀⸀䤀倀一漀Ⰰഀ਀        䐀⸀一愀洀攀Ⰰഀ਀        匀䜀⸀一愀洀攀Ⰰഀ਀        倀䐀⸀䤀倀一漀Ⰰഀ਀        䌀䄀匀吀⠀䐀䄀吀䔀䐀䤀䘀䘀⠀䐀䄀夀Ⰰ 䄀倀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀Ⰰ 倀䐀⸀䐀椀猀挀栀愀爀最䐀愀琀攀⤀ ⬀ ㄀ 䄀匀 嘀䄀刀䌀䠀䄀刀⤀ 䄀匀 吀漀琀愀氀洀攀搀椀挀愀氀猀瀀攀渀搀椀渀䄀䔀䐀Ⰰഀ਀        ✀䤀渀倀愀琀椀攀渀琀✀ 䄀匀 倀愀琀椀攀渀琀吀礀瀀攀伀昀嘀椀猀椀琀Ⰰഀ਀        䄀倀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀 䄀匀 䐀愀琀攀漀昀愀搀洀椀猀猀椀漀渀Ⰰഀ਀        倀䐀⸀䐀椀猀挀栀愀爀最䐀愀琀攀 䄀匀 䐀椀猀挀栀愀爀最䐀愀琀攀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㄀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㈀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㌀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㐀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㔀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㘀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㜀Ⰰഀ਀        䤀䌀䐀⸀䤀䌀䐀挀漀搀攀㠀ഀ਀    䘀刀伀䴀 刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀猀 倀ഀ਀    䤀一一䔀刀 䨀伀䤀一 伀甀琀倀愀琀椀攀渀琀⸀䤀渀瘀攀猀琀椀最愀琀椀漀渀刀攀焀甀攀猀琀䠀攀愀搀攀爀 䤀刀䠀 伀一 倀⸀䤀搀 㴀 䤀刀䠀⸀倀愀琀椀攀渀琀䤀䐀ഀ਀    䤀一一䔀刀 䨀伀䤀一 䤀渀倀愀琀椀攀渀琀⸀䄀搀洀椀琀倀愀琀椀攀渀琀猀 䄀倀 伀一 䤀刀䠀⸀伀倀开䤀倀一甀洀戀攀爀 㴀 䄀倀⸀䤀倀一甀洀戀攀爀ഀ਀    䤀一一䔀刀 䨀伀䤀一 䤀渀倀愀琀椀攀渀琀⸀倀愀琀椀攀渀琀䐀椀猀挀栀愀爀最攀 倀䐀 伀一 䄀倀⸀䤀倀一甀洀戀攀爀 㴀 倀䐀⸀䤀倀一漀ഀ਀    䤀一一䔀刀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀䐀漀挀琀漀爀猀 䐀 伀一 䤀刀䠀⸀䐀漀挀琀漀爀䤀䐀 㴀 䐀⸀䤀搀ഀ਀    䤀一一䔀刀 䨀伀䤀一 伀甀琀倀愀琀椀攀渀琀⸀匀瀀攀挀椀愀氀椀琀礀䜀爀漀甀瀀䐀攀琀愀椀氀猀 匀䜀 伀一 䐀⸀䤀搀 㴀 匀䜀⸀䤀䐀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 刀攀最椀猀琀爀愀琀椀漀渀⸀一愀琀椀漀渀愀氀椀琀椀攀猀 一 伀一 倀⸀一愀琀椀漀渀愀氀椀琀礀䤀搀 㴀 一⸀䤀搀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀䌀椀琀礀 䌀 伀一 倀⸀䄀挀琀椀瘀攀 㴀 䌀⸀䤀搀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䤀䌀䐀开倀䤀嘀伀吀 䤀䌀䐀 伀一 䤀䌀䐀⸀䤀倀开伀倀 㴀 倀䐀⸀䤀倀一漀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀䌀漀甀渀琀爀礀 䌀吀 伀一 倀⸀䌀漀甀渀琀爀礀䤀搀 㴀 䌀吀⸀䤀搀ഀ਀    圀䠀䔀刀䔀ഀ਀        䌀伀一嘀䔀刀吀⠀䤀一吀Ⰰ 䌀伀一嘀䔀刀吀⠀䌀䠀䄀刀⠀㠀⤀Ⰰ 䄀倀⸀䄀搀洀椀猀猀椀漀渀䐀愀琀攀Ⰰ ㄀㄀㈀⤀⤀ 䈀䔀吀圀䔀䔀一 䀀䘀爀漀洀䐀愀琀攀 䄀一䐀 䀀吀漀搀愀琀攀ഀ਀        䄀一䐀 ⠀䀀倀愀琀椀攀渀琀吀礀瀀攀䤀搀 䤀匀 一唀䰀䰀 伀刀 倀⸀吀礀瀀攀䤀搀 㴀 䀀倀愀琀椀攀渀琀吀礀瀀攀䤀搀⤀ഀ਀ഀ਀    唀一䤀伀一 䄀䰀䰀ഀ਀ഀ਀    ⼀⨀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀       䔀䴀䔀刀䜀䔀一䌀夀 倀䄀吀䤀䔀一吀匀ഀ਀       㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀 ⨀⼀ഀ਀    匀䔀䰀䔀䌀吀 ഀ਀        䌀吀⸀一愀洀攀䔀渀 䄀匀 挀漀甀渀琀爀礀一愀洀攀Ⰰഀ਀        ⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 匀攀爀椀愀氀一甀洀 䘀刀伀䴀 䄀瀀瀀氀椀挀愀琀椀漀渀匀攀琀甀瀀⸀䌀漀洀瀀愀渀礀⤀ 䄀匀 匀攀爀椀愀氀一甀洀Ⰰഀ਀        䌀䄀匀䔀 ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㄀ 吀䠀䔀一 ✀䴀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㈀ 吀䠀䔀一 ✀䘀攀洀愀氀攀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 ㌀ 吀䠀䔀一 ✀唀渀搀攀琀攀爀洀椀渀攀搀✀ ഀ਀            圀䠀䔀一 倀⸀䜀攀渀搀攀爀䤀搀 㴀 㐀 吀䠀䔀一 ✀唀渀搀椀昀昀攀爀攀渀琀椀愀琀攀搀✀ ഀ਀
            WHEN P.GenderId = 5 THEN 'SexchangedtoMale' 
            WHEN P.GenderId = 6 THEN 'Sexchangedtofemale' 
            WHEN P.GenderId = 7 THEN 'NotCompleted' 
            ELSE '' 
        END AS GENDER,   
        CASE WHEN P.TypeId = 1 THEN 'Emirates ID' ELSE 'Passport' END AS DType,
        p.MobileNumber,
        (SELECT TOP 1 Name FROM ApplicationSetup.Company),
        P.Code,
        P.TranslatedFallName,
        ISNULL(P.FirstName,'') + ' ' + ISNULL(P.MiddleName1,'') + ' ' + ISNULL(P.MiddleName2,'') + ' ' + ISNULL(P.LastName,''),
        P.MobileNumber,
        P.Email,
        P.IdNumber,
        P.PassportNumber,
        CASE P.TypeId
            WHEN 1 THEN 'UAE Citizen'
            WHEN 2 THEN 'Resident'
            ELSE 'international'
        END AS Type,
        'ER',
        N.NameEn,
        CAST(P.DateOfBirth AS DATE),
        DATEDIFF(YEAR, P.DateOfBirth, GETDATE()),
        C.NameEn,
        '',
        P.Address,
        P.Occupation,
        'No',
        IRH.OP_IPNumber,
        D.Name,
        SG.Name,
        IRH.organizationdoctor,
        CAST(DATEDIFF(MINUTE, EU.[Date], EU.SeenDateTime) AS VARCHAR) + ' MINUTE' AS TotalmedicalspendinAED,
        'Emergency' AS PatientTypeOfVisit,
        EU.[Date] AS Dateofadmission,
        EU.SeenDateTime AS DischargDate,
        ICD.ICDcode1,
        ICD.ICDcode2,
        ICD.ICDcode3,
        ICD.ICDcode4,
        ICD.ICDcode5,
        ICD.ICDcode6,
        ICD.ICDcode7,
        ICD.ICDcode8
    FROM Registration.Patients P
    INNER JOIN OutPatient.InvestigationRequestHeader IRH ON P.Id = IRH.PatientID
    INNER JOIN Emergency.EmergencyUnit EU ON IRH.PatientID = EU.PatientID
    INNER JOIN Registration.Doctors D ON IRH.DoctorID = D.Id
    INNER JOIN OutPatient.SpecialityGroupDetails SG ON D.Id = SG.ID
    LEFT JOIN Registration.Nationalities N ON P.NationalityId = N.Id
    LEFT JOIN ApplicationSetup.City C ON P.Active = C.Id
    LEFT JOIN ICD_PIVOT ICD ON ICD.IP_OP = IRH.OP_IPNumber
    LEFT JOIN ApplicationSetup.Country CT ON P.CountryId = CT.Id
    WHERE
        IRH.OP_IPNumber LIKE 'er%'
        AND CONVERT(INT, CONVERT(CHAR(8), EU.[Date], 112)) BETWEEN @FromDate AND @Todate
