CREATE proc [InPatient].[Dobutamine_Stress_Echocardiography_CommentsReport]
@ID bigint
as

SELECT     [Id] ,[Dobutamine_Stress_EchocardiographyID],[BP],[HR],
									 CASE
    WHEN [Dose] =1 THEN '5 µgm/kg/min'
    WHEN [Dose] =2 THEN '10 µgm/kg/min'
	WHEN [Dose] =3 THEN '20 µgm/kg/min'
	WHEN [Dose] =4 THEN '30 µgm/kg/min'
	WHEN [Dose] =5 THEN '40 µgm/kg/min'
	WHEN [Dose] =6 THEN 'Atropine '
		WHEN [Dose] =7 THEN 'Recovery'
	else ''
	end as [Dose]		 
			

FROM         [InPatient].[Dobutamine_Stress_Echocardiography_Comments]
						 where [InPatient].[Dobutamine_Stress_Echocardiography_Comments].[Dobutamine_Stress_EchocardiographyID]=@ID




GO
