SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE proc [InPatient].[Dobutamine_Stress_Echocardiography_MGMReport]
@ID bigint
as

select 
						 
						 CASE
    WHEN [MGM] =1 THEN '5 µgm/kg/min'
    WHEN [MGM] =2 THEN '10 µgm/kg/min'
	WHEN [MGM] =3 THEN '20 µgm/kg/min'
	WHEN [MGM] =4 THEN '30 µgm/kg/min'
	WHEN [MGM] =5 THEN '40 ugm/kg/min + atropine'
	WHEN [MGM] =6 THEN '50 µgm/kg/min'
		WHEN [MGM] =7 THEN 'Recovery'
	else ''
	end as MGMValue,

		 CASE
    WHEN [Type] =1 THEN 'Antroseptal'
    WHEN [Type] =2 THEN 'Posterior'
	WHEN [Type] =3 THEN 'Inferior'
	WHEN [Type] =4 THEN 'Anterior'
	WHEN [Type] =5 THEN 'Lateral'
	WHEN [Type] =6 THEN 'Infroseptal'
		
	else ''
	end as MGMType,

			[Basal]			,[Mid],[Apical]
FROM            [InPatient].[Dobutamine_Stress_Echocardiography_MGM]
where [Dobutamine_Stress_EchocardiographyID]=@ID



GO
