/****** Object:  StoredProcedure [InPatient].[DoctorNameByNoofOrdersSubRep]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [InPatient].[DoctorNameByNoofOrdersSubRep]
@DoctorId	int ,
@DateFrom datetime ,
@DateTo datetime 
as
begin
 
 select count(Ordermaster.ID ) as NoofOrders , 
Ordermaster.DoctorId ,

Registration.Doctors.Name
--Ordermaster .OrderDate 
from InPatient.PatientOrderMaster as Ordermaster 
inner join InPatient.PatientOrderDetail as Orderdetail
on Ordermaster .ID =  Orderdetail.PatientOrderMasterId
inner join Registration.Doctors
on Ordermaster.DoctorId=Registration.Doctors.Id
where Ordermaster .DoctorId = @DoctorId 
and Ordermaster.OrderDate between @DateFrom and @DateTo
group by Ordermaster.DoctorId,Registration.Doctors.Name
--,Ordermaster.DoctorId  


 end


GO
/****** Object:  StoredProcedure [InPatient].[DoctorsDailyReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [InPatient].[DoctorsDailyReport]
	-- Add the parameters for the stored procedure here
	@Day VArchar(20) = null 
AS
	
	SELECT P.FirstName + ' ' + P.LastName as PatientName ,DocSched.ScheduleDate , P.Code , Visit.OPnumber, InP.BedNO ,Doc.Name as DoctorName, Dep.Name as DepartmentName
	FROM Registration.Patients P left outer join InPatient.AdmitPatients InP on P.Id = InP.PatientID
	inner join  Registration.Doctors Doc on P.PrimaryDoctorId= Doc.Id 
	inner join ApplicationSetup.CostCenter Dep on Doc.DepartmentId = Dep.Id
	inner join OutPatient.PrepareVisitSlip Visit on P.Id = Visit.PatientID 
	inner join Registration.DoctorsDailyScheduleDetails SchedDet on Visit.ScheduleAppointmentID = SchedDet.Id
	inner join Registration.DoctorsDailySchedule DocSched on SchedDet.DoctorsDailyScheduleID = DocSched.Id
	WHERE (@Day is null or Convert(date,@Day) = DocSched.ScheduleDate)



GO
