/****** Object:  StoredProcedure [InPatient].[GetMedicalObservationDental]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create proc  [InPatient].[GetMedicalObservationDental]
(
@MedicalObservationID int
)
as
SELECT        InPatient.MedicalObservationDental.*, ApplicationSetup.Service.RecordName, ApplicationSetup.Service.Code, ApplicationSetup.Service.NameAr, ApplicationSetup.Service.NameEn, ApplicationSetup.Service.Cost
FROM            InPatient.MedicalObservationDental INNER JOIN
                         ApplicationSetup.Service ON InPatient.MedicalObservationDental.ServiceID = ApplicationSetup.Service.Id
						 where MedicalObservationDental.MedicalObservationID=@MedicalObservationID
GO
/****** Object:  StoredProcedure [InPatient].[GetMedicalObservationICDCodes]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [InPatient].[GetMedicalObservationICDCodes] --7369
(@MedicalObservationID int )
as
SELECT   isnull(   Nursing.ICDCodes.ICDCode,'')+' - '+    isnull(  Nursing.ICDCodes.ICDDescription,'')+' - '+isnull( Nursing.ICDCodes.ICDAlias,'')
FROM            InPatient.MedicalObservationICDCodes INNER JOIN
                         Nursing.ICDCodes ON InPatient.MedicalObservationICDCodes.ICDCodeID = Nursing.ICDCodes.Id
WHERE        (InPatient.MedicalObservationICDCodes.MedicalObservationID = @MedicalObservationID)
GO
