/****** Script for SelectTopNRows command from SSMS  ******/
CREATE procEDURE [InPatient].[GetPharmacyPatientsProfile]
	@IPNumber nvarchar(max)=null,
	@PatientID int =null
AS
BEGIN
  SELECT 
  'Presc' as [Type]
,[PrescriptionDate] as Date_Time
,'Doctor: '+ ISNULL(Doc.Name,'')+
'; Drugs: '+ISNULL(drug.DrugName,'')  as Details

  FROM [OutPatient].[PrescriptionsHeader] preH
  join [OutPatient].[PrescriptionsDetails] preD

  on preH.[Id] = preD.PrescriptionID

  join [Pharmacy].[Drugs] drug
  on preD.[DrugID] = drug.ID

   join [Registration].[Doctors] Doc

  on preH.[DoctorID] = Doc.Id

   where preH.[PatientID]=@PatientID
  --preH.OPNumber=@IPNumber and 

   UNION
   SELECT 
'Vital' as [Type]
,[StartDate] as Date_Time
,'Remarks: '+ ISNULL(preH.Remarks,'')+
'; Value: '+ISNULL(CONVERT(nvarchar(max), preH.Value),'')+';VitalName:'+ISNULL(vital.Name,'')  as Details


  FROM [OutPatient].[PatientVitals] preH
  join [OutPatient].[VitalParametersDeptWise] Dept on dept.Id = preH.VitalParametersDeptWiseId
  join [InPatient].[VitalParameters] vital on vital.Id = Dept.vitalparameterID
  where preH.PateintId = @PatientID
  --and preH.OP_IP = @IPNumber
     UNION
   SELECT 
'Diag' as [Type]
,Medical.CreatedDate as Date_Time,
'Height: '+ ISNULL(CONVERT(nvarchar(max),Medical.Height),'')+
