CREATE proc [InPatient].[IPBedTransferReport]
@DateFrom datetime,
@DateTo datetime,
@IPNO nvarchar(50)
as
select 
InPatient.RoomTransfer.TransferDate,
InPatient.RoomTransfer.TransferTime,
(select InPatient.Ward.Name from InPatient.Ward where InPatient.Ward.Id=InPatient.RoomTransfer.FromWardId) as  FromWardName,
(select InPatient.Bed.BedNumber from InPatient.Bed where InPatient.Bed.Id=InPatient.RoomTransfer.FromBedId) as  FromBedNO,
(select InPatient.Ward.Name from InPatient.Ward where InPatient.Ward.Id=InPatient.RoomTransfer.ToWardId) as  ToWardName,
(select InPatient.Bed.BedNumber from InPatient.Bed where InPatient.Bed.Id=InPatient.RoomTransfer.ToBedId) as  TOBedNO,
Registration.Patients.Code,
Registration.Patients.FirstName +' '+ Registration.Patients.MiddleName1 +' '+ Registration.Patients.MiddleName2 +' '+ Registration.Patients.LastName,
InPatient.RoomTransfer.IPNumber
from InPatient.RoomTransfer left join Registration.Patients
on InPatient.RoomTransfer.PatientID = Registration.Patients.Id
where InPatient.RoomTransfer.TransferDate >= convert(datetime,@DateFrom,103)
and  InPatient.RoomTransfer.TransferDate <= convert(datetime,@DateTo,103)
and (InPatient.RoomTransfer.IPNumber = @IPNO or @IPNO is null)



