InPatient.Bed.BedNumber,
InPatient.Bed.Description,
InPatient.BedLockPurpose.Name
from  InPatient.Room left join InPatient.Bed 
on InPatient.Room.Id = InPatient.Bed.RoomId
left join InPatient.BedStatus
on InPatient.Bed.BedStatusId = InPatient.BedStatus.Id
left join InPatient.BedStatusChangeTracker
on InPatient.Bed.Id = InPatient.BedStatusChangeTracker.BedId
left join InPatient.BedLockPurpose
on InPatient.BedStatusChangeTracker.BedLockPurposeId=InPatient.BedLockPurpose.Id
where InPatient.BedStatus.Name='Disactive'
and (InPatient.BedLockPurpose.Id = @PurposeID or @PurposeID is null )
end








