/****** Object:  StoredProcedure [InPatient].[myocardialperfusionimagingreport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [InPatient].[myocardialperfusionimagingreport]  @id int
	
	,
	@Docname nvarchar(4000) 
	as 
	 select top 1 @Docname as Docname, t1.*,t2.FirstName+' '+t2.MiddleName1+' '+t2.LastName as fullname from [InPatient].[MyocardialPerfusionImaging] t1
		join [Registration].Patients t2 on t2.Id = t1.PatientID
	where t1.Id=@id



