/****** Object:  StoredProcedure [InPatient].[OrdersByDoctorsReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [InPatient].[OrdersByDoctorsReport]
@DoctorId	int ,
@DateFrom datetime ,
@DateTo datetime 
as
begin
 
 select 
 Ordermaster.DoctorId ,
Ordermaster.ID as OrderNumber ,

FORMAT (Ordermaster .OrderDate , 'dd/MM/yyyy ') as Orderdate ,
Registration.Patients.Code   as MRN ,
 Registration.Patients.TranslatedFallName ,
Registration.Doctors.Name as DoctorName ,
'OrderPrority'
 = 
  CASE 
     WHEN Ordermaster.Priority = 1 THEN 'Routine'
     WHEN Ordermaster.Priority =2  THEN 'Mid'
     WHEN Ordermaster.Priority =3  THEN ' Urgent'
    
     ELSE ''
  END  ,
InPatient.OrderCategoryMaster.EnglishNameDescription as CategoryOrdered ,
appservice.NameEn  as ServicesOrdered ,
 

 'OrderStatus'
 = 
  CASE 
     WHEN Ordermaster.OrderStatus =  1 THEN 'Ordered'
     WHEN Ordermaster.OrderStatus =2  THEN ' Initiated'
     WHEN Ordermaster.OrderStatus =3  THEN ' Done'
