CREATE procEDURE [InPatient].[PatientResidenceReport] 
	-- Add the parameters for the stored procedure here
	@FromDate VarChar(20) = null,
	@ToDate VarChar(20) = null,
	@PatientName NVarChar(20) = null
AS

	SELECT P.Code, P.FirstName + ' ' +P.LastName as PatientName , DocSched.ScheduleDate, InP.ExpectedDateOfDischarge, Room.RoomNumber,
	DATEDIFF(day,DocSched.ScheduleDate,InP.ExpectedDateOfDischarge)as Period
	FROM Registration.Patients P inner join InPatient.AdmitPatients InP on P.Id = InP.PatientID
	inner join OutPatient.PrepareVisitSlip Visit on P.Id= Visit.PatientID
	inner join Registration.DoctorsDailyScheduleDetails SchedDet on Visit.ScheduleAppointmentID = SchedDet.Id
	inner join Registration.DoctorsDailySchedule DocSched on SchedDet.DoctorsDailyScheduleID = DocSched.Id,
	InPatient.Room Room inner join InPatient.Bed Bed on Room.Id =Bed.RoomId
	WHERE InP.BedNO = Bed.Id and(@FromDate is null or Convert(date,@FromDate) <= DocSched.ScheduleDate) and 
	(@ToDate is null or Convert(date,@ToDate) >= DocSched.ScheduleDate) and
	(@PatientName is null or @PatientName = P.FirstName);



GO
