CREATE Proc [InPatient].[ProOcaf] --15798,15798,0,99999999,0,999999,'kjk'
(@PatIDFrom int,@PatIDTo int,
@DTFrom int,@DTo int,
@INsFrom int,@INsTo int
,
@title nvarchar(4000)=''


)
as

SELECT DISTINCT 
                  Billing.ins_Company_Class.ClassNO,    Billing.PatientInsuranceLimitdetail.ApprovalCode,    Registration.Patients.PatientType,          Billing.Ins_Company_Policy.Expiry_Date,  Billing.Ins_Company_Policy.PolicyNo, Billing.Ins_Company_Policy.PolicyHolder, [Billing].[Ins_Company_Policy].PolicyHolder,[Billing].[Ins_Company_Policy].PolicyNo, DATEDIFF(year,Registration.Patients.DateOfBirth,GETDATE()) age,  Registration.Patients.GenderId, Registration.PatientInsurance.MemberShipId, Registration.Patients.MaritalStatusId,(select HospitalName from ApplicationSetup.Setting ) HospitalName,
						Registration.Patients.Id PatID, 
					case	 Registration.Patients.GenderId when 1 then 'Male'
					 when 2 then 'FeMale'
					 else '' end As gender,
						
						  InPatient.MedicalObservation.Id AS MedicalObservationId, Registration.Patients.Id AS PatientID, Billing.InsuranceCompanies.NameEnglish, Billing.InsuranceCompanies.NameArabic, 
                         Billing.InsuranceCompanies.Code, Registration.Patients.Code AS PatientsCode, ISNULL(Registration.Patients.FirstName, N'') + ' ' + ISNULL(Registration.Patients.MiddleName1, N'') 
                         + ' ' + ISNULL(Registration.Patients.MiddleName2, N'') + ' ' + ISNULL(Registration.Patients.LastName, N'') AS FullName, Registration.Patients.TranslatedFallName, InPatient.MedicalObservation.IP_OP, 
