                         InPatient.OCAF.[Permanent], InPatient.OCAF.Disposable, InPatient.OCAF.Frames, InPatient.OCAF.SpecifyOfPairs, InPatient.OCAF.txtLensesSR, InPatient.OCAF.txtFrameSR, InPatient.OCAF.txtPhysicianSignature, 
                         InPatient.OCAF.txtDate, InPatient.OCAF.txtNameRelationship, InPatient.OCAF.txtSignature, InPatient.OCAF.txtDateTime
FROM            Registration.Patients INNER JOIN
                         Registration.PatientInsurance ON Registration.Patients.Id = Registration.PatientInsurance.PatientId
						  INNER JOIN
                         Billing.ins_Company_Class ON Registration.PatientInsurance.ins_ClassID = Billing.ins_Company_Class.ID
						  INNER JOIN
                         Billing.InsuranceCompanies ON Registration.PatientInsurance.SponsorId = Billing.InsuranceCompanies.ID INNER JOIN
                         InPatient.MedicalObservation ON Registration.Patients.Id = InPatient.MedicalObservation.PatientID 
						 	 	INNER JOIN
                         Billing.Ins_Company_Policy ON Registration.PatientInsurance.Ins_PolicyID = Billing.Ins_Company_Policy.ID
						 LEFT OUTER JOIN
                         InPatient.OCAF ON InPatient.MedicalObservation.IP_OP = InPatient.OCAF.IPOP AND InPatient.MedicalObservation.PatientID = InPatient.OCAF.Patient LEFT OUTER JOIN
                         InPatient.EyesightMeasurement ON InPatient.MedicalObservation.Id = InPatient.EyesightMeasurement.MedicalObservationID LEFT OUTER JOIN
                         Billing.PatientInsuranceLimitdetail ON InPatient.MedicalObservation.IP_OP = Billing.PatientInsuranceLimitdetail.IPOPNo RIGHT OUTER JOIN
                         Nursing.Employee ON Billing.PatientInsuranceLimitdetail.CreatedBy = Nursing.Employee.UserId
WHERE        (Registration.Patients.Id IS NOT NULL) AND (InPatient.MedicalObservation.Id IN
                             (SELECT        Id
                               FROM            (SELECT        MAX(Id) AS Id, PatientID
