/****** Object:  StoredProcedure [InPatient].[RepBodyMassIndex]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE  [InPatient].[RepBodyMassIndex]
@PatientId int  null,
@DateFrom int,
@DateTo int 
as
begin
select  PatientID, BMI, CONVERT(varchar(10), CreatedDate, 111) AS CreatedDate, Height, Weight
 from  [InPatient].[MedicalObservation]
WHERE PatientID=@PatientId and cast(convert(char(8),CreatedDate,112) as bigint) Between @DateFrom and @DateTo
end



GO
/****** Object:  StoredProcedure [InPatient].[RepBodyMassIndexIn]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


Create procEDURE  [InPatient].[RepBodyMassIndexIn]
@PatientId int  null,
@DateFrom int,
@DateTo int,
@H1 float,
 @H2 float,
 @W1 float,
 @W2 float

as
begin
select BMI
 from  [InPatient].[MedicalObservation]
WHERE PatientID=@PatientId and cast(convert(char(8),CreatedDate,112) as bigint) Between @DateFrom and @DateTo
and [Height] between @H1 and @H2 and [Weight] between @w1 and @w2
  
end



GO
