GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [InPatient].[RepDoctorServices] 
	-- Add the parameters for the stored procedure here
	@ID int =null
AS
	SELECT P.FirstName+' ' +P.LastName as PatientName , Doc.Name, Visit.VisitNo, DocSched.ScheduleDate, Serv.RecordName , InvD.QTY , InvD.Amount 
	FROM Registration.Patients P inner join OutPatient.PrepareVisitSlip Visit on P.Id = Visit.PatientID
	inner join OutPatient.InvestigationRequestHeader InvH on Visit.OPnumber = InvH.OP_IPNumber
	inner join OutPatient.InvestigationRequestDetails InvD on InvH.Id = InvD.InvestigationRequestId
	inner join Registration.Doctors Doc on InvH.DoctorID = Doc.Id
	inner join ApplicationSetup.Service Serv on InvD.ServiceId = Serv.Id
	inner join Registration.DoctorsDailyScheduleDetails SchedDet on Visit.ScheduleAppointmentID = SchedDet.Id
	inner join Registration.DoctorsDailySchedule DocSched on SchedDet.DoctorsDailyScheduleID = DocSched.Id
	WHERE (@ID is null or @ID = Doc.Id) ;



GO
