CREATE procEDURE [InPatient].[RepPatientServices] 
	-- Add the parameters for the stored procedure here
	@ID int =null
AS
	SELECT P.FirstName+' ' +P.LastName as PatientName , Visit.VisitNo, DocSched.ScheduleDate, Serv.RecordName , InvD.QTY , InvD.Amount 
	FROM Registration.Patients P inner join OutPatient.PrepareVisitSlip Visit on P.Id = Visit.PatientID
	inner join OutPatient.InvestigationRequestHeader InvH on Visit.OPnumber = InvH.OP_IPNumber
	inner join OutPatient.InvestigationRequestDetails InvD on InvH.Id = InvD.InvestigationRequestId
	inner join ApplicationSetup.Service Serv on InvD.ServiceId = Serv.Id
	inner join Registration.DoctorsDailyScheduleDetails SchedDet on Visit.ScheduleAppointmentID = SchedDet.Id
	inner join Registration.DoctorsDailySchedule DocSched on SchedDet.DoctorsDailyScheduleID = DocSched.Id
	WHERE (@ID is null or @ID = P.Id) ;



GO
/****** Object:  StoredProcedure [InPatient].[RequestSupply_rep]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [InPatient].[RequestSupply_rep](@ID int)
AS
BEGIN
  select isnull(P.FirstName, ' ') [Patient First Name], isnull(p.LastName, ' ') [Patient Last Name], RSH.OP_IPNo [Patient Number] ,RSH.RequestNo [Request Number],RSH.CreatedDate [Request Date],
  CASE WHEN RSH.PatientTypeID =1 THEN 'OP' ELSE 'IP' END [Patient Type],D.Name [Doctor Name],S.StockName [Stock Name],
   I.ItemName [Item Name], I.ItemCode [Item Code],U.UnitName [Unit Name], RSD.Quantity
   from InPatient.RequestSuppliesHeader RSH 
  join InPatient.RequestSuppliesDetails RSD on RSD.RequestSuppliesHeaderID = RSH.Id
  join Registration.Patients P on P.ID = RSH.PatientID
  join Registration.Doctors D on D.Id = RSH.DoctorID 
  join GeneralStores.Stocks S on S.ID = RSH.SubStoreID
  join GeneralStores.Items I on I.ID = RSD.ItemID
  join GeneralStores.UnitConversionFactor UC on UC.ID = RSD.UnitConversionID
  join GeneralStores.Units U on UC.UnitID = U.ID
  where RSH.Id=@ID
  END



