/****** Object:  StoredProcedure [InPatient].[SP_BedsReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [InPatient].[SP_BedsReport]

(
    @FromDate NVarChar(40),
    @ToDate   NVarChar(40)
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        br.NameEn AS [FACILITY NAME],

        w.Name AS [BED SPECIALTY ],
		

        ISNULL(SUM(ap.Days), 0) AS [NUMBER OF DAYS SERVED],


        SUM
(
    CASE 
        WHEN TRY_CONVERT(INT, ap.EncounterAdmit) = 1

             AND TRY_CONVERT(date, ap.AdmissionDate) IS NOT NULL
        THEN
            CASE 
                WHEN DATEDIFF
                     (
                         DAY,
                         TRY_CONVERT(date, ap.AdmissionDate),
                         ISNULL
                         (
                             TRY_CONVERT(date, ap.ExpectedDateOfDischarge),
                             TRY_CONVERT(date, @ToDate)
                         )
                     ) < 0
                THEN 0
                ELSE
                     DATEDIFF
                     (
                         DAY,
                         TRY_CONVERT(date, ap.AdmissionDate),
                         ISNULL
                         (
                             TRY_CONVERT(date, ap.ExpectedDateOfDischarge),
                             TRY_CONVERT(date, @ToDate)
                         )
                     )
            END
        ELSE 0
    END
) AS [TOTAL AVAILABLE DAYS OF CARE],


        
        SUM(CASE WHEN b.Active = 1 THEN 1 ELSE 0 END)
        AS [TOTAL ACTIVE],

      
        SUM(CASE WHEN b.Active = 0 THEN 1 ELSE 0 END)
        AS [TOTAL INACTIVE]

    FROM hr.Branches br

    Left JOIN InPatient.Ward w
        ON w.BranchId = br.ID

    Left JOIN InPatient.Room r
        ON r.WardId = w.Id

    Left JOIN InPatient.Bed b
        ON b.RoomId = r.Id

    Left JOIN InPatient.AdmitPatients ap
        ON ap.AdmissionWardId = w.Id
        AND ap.AdmissionDate BETWEEN @FromDate AND @ToDate

    GROUP BY
        br.NameEn,
        w.Name

    ORDER BY
        br.NameEn,
        w.Name;
END
