/****** Object:  StoredProcedure [InPatient].[SP_ICDCodeEntry_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [InPatient].[SP_ICDCodeEntry_Report]
 @patientType int,
 @patientId int,
 @episodeDate date

AS
Select
patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
 patient.Code as PatientId,
 MedicalObservation.Remarks as Remarks,
MedicalObservation.IP_OP as IP_OP,
ICDCodes.ICDCode as ICDCode,
ICDCodes.ICDDescription as ICDDescription
 

from InPatient.MedicalObservation as MedicalObservation
join InPatient.MedicalObservationICDCodes as MedicalObservationICDCodes  on MedicalObservation.Id=MedicalObservationICDCodes.MedicalObservationID
join Nursing.ICDCodes as ICDCodes on MedicalObservationICDCodes.ICDCodeID=ICDCodes.Id
join Registration.Patients as patient on MedicalObservation.PatientId=patient.Id


where MedicalObservation.PateintType=@patientType
and MedicalObservation.PatientID = @patientId
and MedicalObservation.CreatedDate >= @episodeDate










GO
/****** Object:  StoredProcedure [InPatient].[SP_InvestigationAndTreatmentHistory_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [InPatient].[SP_InvestigationAndTreatmentHistory_Report]
 @patientId int

AS
Select  

Patients.FirstName+' '+Patients.MiddleName1+' '+Patients.MiddleName2+' '+Patients.LastName as PatientName,
Doctors.Name as DoctorName,
convert(date,MedicalObservation.CreatedDate) as VisitDate,
MedicalObservation.IP_OP as IP_OP,
CostCenter.Name as Department

FROM    InPatient.MedicalObservation as MedicalObservation
JOIN    Registration.Patients as Patients ON MedicalObservation.PatientID = Patients.Id
JOIN    Registration.Doctors as Doctors ON MedicalObservation.DoctorID = Doctors.Id
JOIN    ApplicationSetup.CostCenter as CostCenter ON Doctors.DepartmentId = CostCenter.Id

where  MedicalObservation.PatientID = @patientId 











