/****** Object:  StoredProcedure [InPatient].[SP_TelephoneChargesReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [InPatient].[SP_TelephoneChargesReport]
@PatientID int
as
begin
select [Registration].[Patients].FirstName +' '+[Registration].[Patients].MiddleName1 +' '+ [Registration].[Patients].MiddleName2 +' '+
[Registration].[Patients].LastName , [InPatient].[TelephoneCharges].[LastIPNumber],[InPatient].[TelephoneCharges].ChargeDate,
[InPatient].[TelephoneCharges].TelephoneNo , [InPatient].[TelephoneCharges].Duration,[InPatient].[TelephoneCharges].Amount
from [InPatient].[TelephoneCharges]
join [Registration].[Patients] on [InPatient].[TelephoneCharges].PatientID = [Registration].[Patients].Id
where ([InPatient].[TelephoneCharges].[PatientID] = @PatientID)
End






