CREATE procedure [InPatient].[SP_VitalParameters]
as
begin
select [InPatient].VitalParameters.Code,[InPatient].VitalParameters .Name,[InPatient].VitalParameters.[Description]
,[InPatient].VitalTypeGroup.Name as VitalTypeGroup,[InPatient].Finding.Name as Finding
