join OutPatient.SpecialityGroupDetails SPGroupDetails on PrimaryDoctor.SpecialtyId=SPGroupDetails.ID
--join OutPatient.SpecialityGroupMaster SPGroupMaster on SPGroupDetails.SpecialityMasterID=SPGroupMaster.ID
left join Registration.Patients on AdmitPatients.PatientID = Patients.Id
left join InPatient.Ward on AdmitPatients.AdmissionWardID = Ward.Id
left join InPatient.Bed on AdmitPatients.BedNO = Bed.Id
left join InPatient.Room on Bed.RoomId = Room.Id

where (@PrimaryDoctorId is null or AdmitPatients.DoctorID = @PrimaryDoctorId) 
and (@AdmissionWardID is null or AdmitPatients.AdmissionWardID = @AdmissionWardID) 
and (@SpecialityID is null or SPGroupDetails.ID = @SpecialityID) 
and (@DateFrom is null or AdmitPatients.AdmissionDate >= @DateFrom) 
and (@DateTo is null or AdmitPatients.AdmissionDate < @DateTo) and AdmitPatients.DischargeStatusId=1



GO
