CREATE proc [InPatient].[WardPharamcyReport]
@MedicalObservationId	int
as
begin
 
  select 
   convert(date,InPatient.MedicalObservation.CreatedDate) as CreatedDate,
  Registration.Patients.Code, Doctor.Name,
  Registration.Patients.FirstName +''+Registration.Patients.MiddleName1+''+Registration.Patients.MiddleName2 as patientName ,
  InPatient.MedicalObservation.Complaints, InPatient.MedicalObservation.HistoryOFPresentIllness, InPatient.MedicalObservation.HospitalizationHistory,InPatient.MedicalObservation.Remarks,
  InPatient.Tags.Name as TagName, 
  case   
  when    Type = 1 then 'PastMedicalHistory_Diseases'
  when    type = 2 then 'PastMedicalHistory_SpecialConsiderations'  
  when    type = 3 then 'FamilyHistory_Diseases'    
  when    type = 4 then 'FamilyHistory_SpecialConsiderations' 
  when    type = 5 then 'DrugReactions' 
  when    type = 6 then 'FamilyHistory_PersonalHistory' 
  when    type = 7 then 'PhysicalExaminationNAD' 
  when    type = 8 then 'SystemReview' 
  when    type = 9 then 'FunctionalScreening' 
  when    type = 10  then  'NutritionalScreening' 
  when    type = 11  then  'PsychologicalScreening' 
  when    type = 12  then  'SocioEconomicScreening' 
  when    type = 13  then  'PainAssessment' 
  when    type = 14  then  'DietaryRegime'
  else 'N/A' end as Type,
  InPatient.MedicalObservation_TagsValues.Value1 as Value1,
  InPatient.MedicalObservation_TagsValues.Value2 as Value2,
  InPatient.MedicalObservation_TagsValues.Value3 as Value3,
  InPatient.MedicalObservation_TagsValues.Value4 as Value4

