from OutPatient.InvestigationRequestHeader left join OutPatient.InvestigationRequestDetails
on  OutPatient.InvestigationRequestHeader.id=   OutPatient.InvestigationRequestDetails.InvestigationRequestId
left join Registration.Patients
on  OutPatient.InvestigationRequestHeader.PatientID=Registration.Patients.Id
left join ApplicationSetup.Service
on  OutPatient.InvestigationRequestDetails.ServiceId = ApplicationSetup.Service.Id
left join ApplicationSetup.CostCenterCompanies
on  ApplicationSetup.Service.CostCenterCompaniesId=ApplicationSetup.CostCenterCompanies.Id
left join ApplicationSetup.CostCenter
on ApplicationSetup.CostCenterCompanies.CostCenterId=ApplicationSetup.CostCenter.Id
left join Billing.PatientBillservices
on OutPatient.InvestigationRequestHeader.Code = Billing.PatientBillservices.RequestNumber
and OutPatient.InvestigationRequestDetails.ServiceId=Billing.PatientBillservices.ItemID
left join  Billing.PatientBill
on Billing.PatientBill.Id=Billing.PatientBillservices.PatientBillID
where ApplicationSetup.CostCenter.Id =10008
and OutPatient.InvestigationRequestHeader.ReqDate >=convert( datetime,@FromDate,103 )
and OutPatient.InvestigationRequestHeader.ReqDate <convert( datetime,@Todate,103 )
and (OutPatient.InvestigationRequestDetails.ServiceId =@serviceID or @serviceID is null)
and (OutPatient.InvestigationRequestHeader.PatientID = @patientID or @patientID is null)























GO
