/****** Object:  StoredProcedure [Laboratory].[GetPatientRedResult_Pats]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [Laboratory].[GetPatientRedResult_Pats] 
    @BranchId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT P.*
    FROM OutPatient. InvestigationRequestDetails IRD
    INNER JOIN OutPatient.InvestigationRequestHeader IR
        ON IRD.InvestigationRequestId = IR.Id
    INNER JOIN Laboratory. ResultEntryDetail RED
        ON IRD.Id = RED.InvestigationDetailsId
    INNER JOIN Registration. Patients P
        ON IR.PatientId = P.Id
    INNER JOIN ApplicationSetup. Service S
        ON IRD.ServiceId = S.Id
    WHERE S.ServiceType = 7   -- Laboratory
      AND RED.BranchId = @BranchId;
END
GO
/****** Object:  StoredProcedure [Laboratory].[Investigationrequeststatistics]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Laboratory].[Investigationrequeststatistics]
@FromDate datetime,
@Todate Datetime,
@patientID int null,
@serviceID int null,
@DoctorID int null

as
select
ApplicationSetup.Service.Code,
ApplicationSetup.Service.RecordName,
Registration.Patients.Code,
OutPatient.InvestigationRequestHeader.Code as requestCode,
OutPatient.InvestigationRequestHeader.ReqDate,
isnull(Billing.PatientBillservices.AmountAfter,0) as Amount,
Billing.PatientBill.Status,
OutPatient.InvestigationRequestHeader.RequestStatus
from OutPatient.InvestigationRequestHeader left join OutPatient.InvestigationRequestDetails
on  OutPatient.InvestigationRequestHeader.id=   OutPatient.InvestigationRequestDetails.InvestigationRequestId
left join Registration.Patients
