+' '+Registration.Patients.LastName as PatientName,Patients.Code as PatCode
, Registration.Patients.TranslatedFallName as EnglishPatientName
,DATEDIFF(hour,DateOfBirth,Laboratory.ResultEntryDetail.TestDate)/8766 AS Age,Registration.Patients.GenderId
FROM Laboratory.ResultEntry inner JOIN
Laboratory.ResultEntryDetail ON Laboratory.ResultEntry.Id = Laboratory.ResultEntryDetail.ResultEntry_Id 
-- Edited 28/09/2021
left join Laboratory.TestDetails ON Laboratory.ResultEntryDetail.TestDetailsId = Laboratory.TestDetails.Id
left JOIN Laboratory.ResultValueHeader ON Laboratory.TestDetails.ComponentId = Laboratory.ResultValueHeader.ID 

left JOIN Registration.Patients ON Laboratory.ResultEntry.PatientId = Registration.Patients.Id
left join  OutPatient.InvestigationRequestHeader AS invH on invH.PatientID=Patients.id 
left join OutPatient.InvestigationRequestDetails InvD on invH.Id =InvD.InvestigationRequestId  and InvD.Id=ResultEntryDetail.InvestigationDetailsId
-- NotUsed
