left JOIN Laboratory.Sections ON Laboratory.ResultEntry.SectionID = Laboratory.Sections.Id
left JOIN ApplicationSetup.Service ON Laboratory.ResultEntry.ServiceID =ApplicationSetup.Service.Id
left JOIN Laboratory.Results ON Laboratory.ResultEntry.ResultId = Laboratory.Results.ResultID
left JOIN Registration.Technicians ON Laboratory.ResultEntry.TechnicianId = Registration.Technicians.Id
where ResultEntry.Id=@ResultEntryId
--@ResultEntryId
