select Distinct * ,
'MaxNormalRangeX'=
CASE
    WHEN [DepartmentsVariables].MaxNormalAge  != 0
	--%1=0
	 THEN FORMAT([DepartmentsVariables].MaxNormalAge, '#,#')

    ELSE 
	[DepartmentsVariables].MaxNormalAge
END ,
'MinNormalRangeX'=
CASE
    WHEN [DepartmentsVariables].MinNormalRange
	!= 0
	 --%1=0
	  THEN FORMAT([DepartmentsVariables].MinNormalRange, '#,#')

    ELSE
	 [DepartmentsVariables].MinNormalRange
END 
