AS
select P.FirstName +' ' + P.MiddleName1 + ' ' + P.MiddleName2+ ' ' + P.LastName as PName
, P.Code as MRN ,pf.PatientType,
pf.TestDate ,f.NameAr as Farm_NameAr,f.NameEn as Farm_NameEn,
pfd.TestResult,A.AntibioticName,pfd.PatientFarmID
 from  
[Registration].Patients P
inner join [Laboratory].Patient_Farms PF on P.id=pf.PatientID
inner join [Laboratory].Farms F on pf.FarmID=F.id
inner join [Laboratory].PatientFarm_Details PFD on pf.id=PFD.PatientFarmID
inner join [Laboratory].Antibiotics A on pfd.AntibioticID=A.AntibioticsID
 
 
where (@PatientID is null or pf.PatientID =@PatientID)
and (@FarmID is null or pf.FarmID=@FarmID)
and (@FromDate is null or CAST(pf.TestDate as date) >=CAST(@FromDate as date) )
and (@ToDate is null or CAST(pf.TestDate as date)<=CAST(@ToDate as date))
 





GO
