CREATE   PROCEDURE  [Laboratory].[RepRadReportPorc2]-- 3158
 @RadFindingID int,
  @qrPath Nvarchar(4000)=''
as
select distinct  replace(@qrPath,'\\','\') qrPath
	,F.Id,p.Age,
VauleDetails.MaxNormalAge MaximumValue  ,
VauleDetails .MinNormalRange MinimumValue ,
labunit.UnitName,red.ValueP,
 RED .Value ,
Header.NameEn,
labRH.Id ,
invH.OP_IPNumber ,
p.Id, p.Code AS MRN,
ISNULL(p.FirstName, '') 
+ ' ' + ISNULL(p.MiddleName1, '')
+ ' ' + ISNULL(p.MiddleName2, '') 
+ ' ' + ISNULL(p.LastName, '') AS ArabicFullName,
p.MobileNumber,
p.TranslatedFallName,
p.Age ,p.DateOfBirth DOF,
CASE WHEN RED.Value > VauleDetails.MaxNormalAge THEN 'High' 
when RED.Value < VauleDetails.MinNormalRange THEN 'Low'
when  VauleDetails.MinNormalRange is null then ''
 ELSE 'Normal' END AS Res, 

CASE WHEN IsPositive is null THEN '' 
when RED.ValueP ='Positive' and IsPositive=1 THEN 'Normal' ELSE 'UpNormal' END AS Res1,
CASE WHEN invH.DoctorId IS NULL THEN 'Lab' ELSE ReqDoc.Name END AS OrderedDoctor   ,
