inner join  OutPatient.InvestigationRequestHeader AS invH on invH.PatientID=p.id
left  join Registration.Doctors AS ReqDoc on invH.DoctorID=ReqDoc.Id
left join  InPatient.MedicalObservation Assesment on Assesment.PatientID=p.id
left join  InPatient.MedicalObservationICDCodes AS AssesmentDiagnosis 
on AssesmentDiagnosis.MedicalObservationID=Assesment.Id
inner join OutPatient.InvestigationRequestDetails AS invD
on invH.id=invD.InvestigationRequestId
inner join Laboratory.ResultEntryDetail  RED

on 
RED.InvestigationDetailsId=invD.Id
inner join Laboratory.TestDetails  as VauleDetails 
on 
RED .TestDetailsId = VauleDetails.ID
inner join Laboratory.ResultValueHeader Header 
on Header.ID = VauleDetails.ComponentId 
inner join ApplicationSetup.Service serv on serv.Id=invD.ServiceId

inner join  Laboratory.ResultEntryDetails_Findings AS F on
labRH.Id = F.ResultEntryID
inner join Nursing.Employee WrittenBy on
WrittenBy.Id = F.EmpID
left join InPatient.AdmitPatients admit
 on admit.PatientID=p.id
 and admit.DischargeStatusId=1
 left join InPatient.Ward ward on
 admit.AdmissionWardID=ward.Id
 left join Registration.Doctors PDoc on
 admit.DoctorID=PDoc.id
 left join InPatient.Bed bed on
 bed.id=admit.BedNO
 left join InPatient.Room room on
 room.id=bed.RoomId

--added by abanoub makram 02-09-2021 task 907
--collecter name
join Laboratory.SamplesReceivedDetails SRD on SRD.InvestigationDetailID=invD.Id
join JCIT_MembershipDB.dbo.AspNetUsers Collectuser on Collectuser.id = SRD.CreatedBy
join Nursing.Employee CollectEmp on CollectEmp.Id = Collectuser.EmployeeID

-- specimen name
join Laboratory.SampleEntry SE on SE.InvestigationRequestDetailsId=invD.Id
left join Laboratory.SpecimenTypes SpecimenTypes on SpecimenTypes.SpecimenTypesID = SE.SpecimenID

--labroratory name
join Laboratory.Labs Labs on Labs.LabCode = SE.LabId

--receiver name 
join Nursing.Employee RecieverEmployee on RecieverEmployee.UserId = RED.CreatedBy

-- Revised name
left  join Nursing.Employee RevisedBy on RevisedBy.Id = F.FinalFindEmpId
