on OutPatient.InvestigationRequestHeader.DoctorID=Registration.Doctors.Id
left join Laboratory.SampleEntry
on OutPatient.InvestigationRequestDetails.Id=Laboratory.SampleEntry.InvestigationRequestDetailsId
left join Laboratory.ResultEntry
on  Laboratory.SampleEntry.SampleNo=Laboratory.ResultEntry.SampleNo
where ApplicationSetup.CostCenter.Id =10008
and OutPatient.InvestigationRequestHeader.ReqDate >=convert( datetime,@FromDate,103 )
and OutPatient.InvestigationRequestHeader.ReqDate <convert( datetime,@Todate,103 )
and (OutPatient.InvestigationRequestDetails.ServiceId =@serviceID or @serviceID is null)
and (OutPatient.InvestigationRequestHeader.PatientID = @patientID or @patientID is null)
and (OutPatient.InvestigationRequestHeader.DoctorID = @DoctorID or @DoctorID is null)
and (OutPatient.InvestigationRequestDetails.Priority = @PeriortyType or @PeriortyType is null)




















