/****** Object:  StoredProcedure [Laboratory].[SampleRejectionReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [Laboratory].[SampleRejectionReport]
@FromDate nvarchar(50),
@Todate nvarchar(50) ,
@TechnicianIdID int = null


as
SELECT  
 Registration.Patients.TranslatedFallName ,

Registration.Patients.Code as MRN ,
format( OutPatient.InvestigationRequestHeader.ReqDate ,  'dd/MM/yyyy, hh:mm:ss tt ')as RequestedDate ,
Laboratory.SampleEntry.SampleNo ,
Laboratory.SampleEntry.Other ,
Laboratory.SpecimenTypes.SpecimenTypesName ,
isnull(Nursing.Employee.FirstNameEn  , '')+ ' '+  isnull(Nursing.Employee.MiddleNameEn  , '') +' '+  isnull(Nursing.Employee.BeforeLastNameEn  , '') +' '+  isnull(Nursing.Employee.LastNameEn  , '')  as RejectedBy ,
 
 JCIT_MembershipDB.dbo.AspNetUsers.EnglishName ,
 Laboratory.SampleEntry.RejectionReasonId ,
 HR.SubDepartment.NameEn as departmentName  ,Laboratory.SampleEntry.TechnicanID,
 Laboratory.SampleEntry.RejectionReasonId,
 "Rejection Reason" = 
 CASE 
     WHEN  Laboratory.SampleEntry.RejectionReasonId = 1 THEN 'Sample was collected in improper container'
     WHEN  Laboratory.SampleEntry.RejectionReasonId = 2 THEN 'Sample not properly sealed was leaking'
