/****** Object:  StoredProcedure [Laboratory].[SP_ComponentsBasedonResultEntryID]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE  proc [Laboratory].[SP_ComponentsBasedonResultEntryID]

@ResultEntryID int null


as
select  ValueHeader.NameEn as ComponentNameEnglish ,
ValueHeader.NameAr as ComponentNameArarbic ,
ValueDetails.MaximumValue ,
ValueDetails.MinimumValue ,
Details.Value 
from Laboratory.ResultValueHeader as ValueHeader
join Laboratory.ResultValueDetails as ValueDetails
on ValueDetails.ResultValueHeaderID = ValueHeader.ID
join Laboratory.ResultEntryDetail  as Details 
on Details.TestDetailsId =  ValueHeader.ID
where Details.ResultEntry_Id = @ResultEntryID
























GO
/****** Object:  StoredProcedure [Laboratory].[SP_ExternalAgencies]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Laboratory].[SP_ExternalAgencies]

@HospitalID int null

as
select OtherHospitals.HospitalName,Patients.FirstName+' '+Patients.MiddleName1+' '+Patients.MiddleName2+' '+Patients.LastName as PatientName,
CustomerMaster.CustomerName,Nationalities.Name
from Laboratory.ExternalAgencies as ExternalAgencies
join Pharmacy.OtherHospitals as OtherHospitals
on ExternalAgencies.HospitalId=OtherHospitals.Id
join Registration.Patients as Patients
on ExternalAgencies.PatientId=Patients.Id
join Billing.CustomerMaster as CustomerMaster
on ExternalAgencies.CustomerId=CustomerMaster.Id
join Registration.Nationalities as Nationalities
on ExternalAgencies.NationalityId=Nationalities.Id



where (ExternalAgencies.HospitalId=@HospitalID or @HospitalID is null)
























