/****** Object:  StoredProcedure [LegalAffairs].[GeneralSavingReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [LegalAffairs].[GeneralSavingReport] --'2020-12-11 00:00:00','2020-12-27 23:59:59'
(
@FromDate datetime null,
@ToDate datetime null
)
as 
select 
gs.GeneralInventoryNumber,
gs.Topic,
e.FirstNameAr+' '+e.MiddleNameAr+' '+e.LastNameAr as EmployeeName,
gs.TransferDate,
gs.FinalDecision,
SavingType=
(
case gs.SavingType when 1
then N'تحقيق'
when 2
then N'عقد قانوني'
when 3
then N'فتوى'
when 4
then N'شكوي'
when 5
then N'قضية قانونية'
when 6
then N'تم الرد من قسم'
end 
)
,
gs.Notes
 from LegalAffairs.GeneralSaving as gs
 join Nursing.Employee as e on e.Id=gs.EmployeeId
 where gs.TransferDate>=cast(@FromDate as date) and gs.TransferDate<=cast(@ToDate as date)


GO
/****** Object:  StoredProcedure [LegalAffairs].[IncomingReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [LegalAffairs].[IncomingReport]
(
@FromDate nvarchar(20),
@ToDate nvarchar(20)
)
as 
select  
i.ImportNo,
i.GeneralInventoryNo,
ImportDate=format(i.ImportDate,'dd/MM/yyyy','ar-EG'),
i.ImportEntity,
i.Title,
IncomingType=(
case IncomingType when 1
then N'تحقيق'
when 2
then N'عقد قانوني'
when 3
then N'الفتوى و الرأي'
when 4
then N'تظلم'
when 5
then N'قضية قانونية'
when 6
then N'تم الرد من قسم'
when 7
then N'الأعمال القانونية الأخرى'
end 
)
 from LegalAffairs.Incoming as i

where i.ImportDate>=cast(@FromDate as date) and i.ImportDate<=cast(@ToDate as date)


GO
