CREATE procEDURE  [LegalAffairs].[RepoprtFatwa]
@fromDate datetime null,
@toDate datetime null,
@inventoryNo nvarchar(50)
,
@EmpFrom nvarchar(50),
@EmpTo nvarchar(50)
as
begin
		SELECT LegalAffairs.Fatwa.Id AS FatwaId, 
		LegalAffairs.Fatwa.IncomingId, 
		LegalAffairs.Incoming.IncomingType, 
		LegalAffairs.Incoming.ImportNo, 
		LegalAffairs.Incoming.GeneralInventoryNo, 
		LegalAffairs.Incoming.Notes,
        LegalAffairs.Fatwa.ReferralDate, 
		Nursing.Employee.FirstNameAr + ' ' + Nursing.Employee.MiddleNameAr + ' ' + Nursing.Employee.LastNameAr as FullName, 
		LegalAffairs.Fatwa.Description, 
		LegalAffairs.Fatwa.RegistrationNo, 
		LegalAffairs.Fatwa.FatwaDate
FROM            Nursing.Employee RIGHT OUTER JOIN
                         LegalAffairs.Fatwa ON Nursing.Employee.Id = LegalAffairs.Fatwa.ReferralEmployee LEFT OUTER JOIN
                         LegalAffairs.Incoming ON LegalAffairs.Fatwa.IncomingId = LegalAffairs.Incoming.Id
		where (@fromDate is null or LegalAffairs.Fatwa.ReferralDate >= @fromDate ) and (@toDate is null or LegalAffairs.Fatwa.ReferralDate <= @toDate )
		and (@inventoryNo is null or LegalAffairs.Incoming.GeneralInventoryNo like '%' + @inventoryNo + '%')
		and
		 	 LegalAffairs.Fatwa.ReferralEmployee between cast(@EmpFrom as bigint) and cast(@EmpTo as bigint)
		 
end





GO
