CREATE proc [LegalAffairs].[succinctnessReport] 
(@dateTo bigint = null ,@dateFrom bigint = null, @AffairIDFrom int = null , @AffairIDTo int = null )
as
if(@dateFrom  is null)
bEgin
set @dateFrom=0
end
if(@dateTo  is null)
bEgin
set @dateTo=99999999
end
SELECT        LegalAffairs.Incoming.GeneralInventoryNo, LegalAffairs.Affair.Id, LegalAffairs.Affair.AffairSerial, LegalAffairs.Affair.AffairNo, LegalAffairs.Affair.Incomingdate, LegalAffairs.Affair.Name, LegalAffairs.Affair.opponentName, 
                         LegalAffairs.Affair.RecordNo, LegalAffairs.Affair.AmountOfTheFee, LegalAffairs.Affair.Appealprocedures, LegalAffairs.Affair.RegistratioNumber, LegalAffairs.Affair.CreatedBy, LegalAffairs.Affair.CreatedDate, 
                         LegalAffairs.Affair.LastModifiedBy, LegalAffairs.Affair.LastModifiedDate, LegalAffairs.Affair.MemberID, LegalAffairs.Affair.status, LegalAffairs.Affair.IncomingID, 
                         Nursing.Employee.FirstNameAr + ' ' + Nursing.Employee.MiddleNameAr + ' ' + Nursing.Employee.LastNameAr AS FullNameAr, 
                         Nursing.Employee.FirstNameEn + ' ' + Nursing.Employee.MiddleNameEn + ' ' + Nursing.Employee.LastNameEn AS FullNameEn, LegalAffairs.Affair.affairStatus, 
                         CASE WHEN LegalAffairs.succinctness.AffairType = 1 THEN 'With Hospital' WHEN LegalAffairs.Affair.AffairType = 2 THEN 'Against The Hospital' ELSE '' END AS AffairTypeEn, 
                         CASE WHEN LegalAffairs.succinctness.AffairType = 1 THEN N'صالح المستشفي ' WHEN LegalAffairs.Affair.AffairType = 2 THEN N' ضد المستشفى ' ELSE '' END AS AffairTypeAr, LegalAffairs.succinctness.AffairType, 
