e.FirstNameAr+' '+e.LastNameAr+' '+e.LastNameAr,
c.FinalDecision,
format(c.CreatedDate,'dd/MM/yyyy','ar-EG') as AffairDate,
c.FinalDecision,
format(c.ApprovalDate,'dd/MM/yyyy','ar-EG') as CreatedDate,
'' as Notes
 from LegalAffairs.Incoming as i 
join LegalAffairs.Complaint as c on i.Id=c.IncomingId
join Nursing.Employee as e on c.AssignedMemberId=e.Id
left join LegalAffairs.lawyer as l on l.EmployeeID=e.Id
and i.IncomingType=l.LawyerWorkType
where (i.GeneralInventoryNo=@InventoryNo or @InventoryNo is null)
and c.ReferralDate>=cast(@FromDate as date) and c.ReferralDate <=cast(@ToDate as date)

union
select 
i.GeneralInventoryNo,
IncomingType=(
case IncomingType when 1
then N'تحقيق'
when 2
then N'عقد قانوني'
when 3
then N'فتوة'
when 4
then N'شكوي'
when 5
then N'قضية قانونية'
when 6
then N'تم الرد من قسم'
end 
),
l.DistributionNo,
format(f.FatwaDate,'dd/MM/yyyy','ar-Eg') as Incomingdate,
e.FirstNameAr+' '+e.LastNameAr+' '+e.LastNameAr,
null as ActionsTaken,
null as  ActionsDate,
null as FinalDecision,
null as  ApprovalDate,
'' as Notes
 from LegalAffairs.Incoming as i 
join LegalAffairs.Fatwa as f on i.Id=f.IncomingId
join Nursing.Employee as e on f.ReferralEmployee=e.Id
left join LegalAffairs.lawyer as l on l.EmployeeID=e.Id
and i.IncomingType=l.LawyerWorkType
where (i.GeneralInventoryNo=@InventoryNo or @InventoryNo is null)
and f.FatwaDate>=cast(@FromDate as date) and f.FatwaDate<=cast(@ToDate as date)

union
select 
i.GeneralInventoryNo,
IncomingType=(
case IncomingType when 1
then N'تحقيق'
when 2
then N'عقد قانوني'
when 3
then N'فتوة'
when 4
then N'شكوي'
when 5
then N'قضية قانونية'
when 6
then N'تم الرد من قسم'
end 
),
l.DistributionNo,
format(inv.ActionsDate,'dd/MM/yyyy','ar-Eg') as Incomingdate,
e.FirstNameAr+' '+e.LastNameAr+' '+e.LastNameAr,
inv.Actions,
format(inv.ActionsDate,'dd/MM/yyyy','ar-EG') as AffairDate,
inv.FinalAction,
format(inv.ApprovalDate,'dd/MM/yyyy','ar-EG') as CreatedDate,
'' as Notes
 from LegalAffairs.Incoming as i 
join LegalAffairs.Investigation as inv on i.Id=inv.IncomingId
join Nursing.Employee as e on inv.ReferralEmployee=e.Id
