/****** Object:  StoredProcedure [Maintenance].[MaintenanceRequestsReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Maintenance].[MaintenanceRequestsReport] --'Legal Affairs'
@srch nvarchar(4000)=''
AS 
select MR.RequesterName,
CASE
    WHEN MR.RequestTypeId =1 THEN 'Maintenance'
    else  'Scrapping'
END 'RequestType',
SD.Name AS DepartmentNameAR,
SD.NameEN AS DepartmentNameEn,
MR.RequestDate,
WSH.NameAr AS WorkeshopeNameAR,
WSH.NameEn AS WorkeshopeNameEn,
CASE
		WHEN CMR.[Status]  =0 THEN 'New'
		WHEN CMR.[Status]  =1 THEN 'WaitingForTechnicalReport'
		WHEN CMR.[Status]  =2 THEN 'Repaired'
		WHEN CMR.[Status]  =3 THEN 'RequestItems'
		WHEN CMR.[Status]  =4 THEN 'AddressTheCompany'
		WHEN CMR.[Status]  =5 THEN 'Speculated'

END 'Status',

CASE
		    WHEN CMR.[Status]  = 0 THEN N'جديد'
    WHEN  CMR.[Status]  =1 THEN N'بانتظار التقرير الفني'
    WHEN  CMR.[Status]  =2 THEN N'تم الإصلاح'
    WHEN  CMR.[Status]  =3 THEN N'طلب قطع غيار'
    WHEN  CMR.[Status]  =4 THEN N'تم تحويله إلى الشركة'
    WHEN  CMR.[Status]  =5 THEN N'تم التقييم'
    ELSE N'غير معروف'

END 'StatusAr',
CASE
    WHEN MR.RequestTypeId =1 THEN N'صيانة'
    else  N'تخريد'
