CREATE procedure [Maintenance].[SP_MaintenanceRecorde]
as
begin
select [Maintenance].[MaintenanceRecorde].MaintenanceRecordeCode ,[Maintenance].[MaintenanceType].MaintenanceName
,[Assets].FX_Location.LocationName as Location ,[Assets].FX_Assets.Asset_Name,[Maintenance].[MaintenanceRecorde].AssetSerialNumber
,[Maintenance].[MaintenanceRecorde].AlarmDate
from [Maintenance].[MaintenanceRecorde] 
left outer join [Maintenance].[MaintenanceType]
on [Maintenance].[MaintenanceRecorde].MaintenanceTypeID=[Maintenance].[MaintenanceType].Id
left outer join [Assets].FX_Location
on [Maintenance].[MaintenanceRecorde].LocationID=[Assets].FX_Location.ID
Left outer join [Assets].FX_Assets 
on [Maintenance].[MaintenanceRecorde].AssteID=[Assets].FX_Assets.Asset_ID
End





