CREATE PROCEDURE  [Maintenance].[VehiclesBonProc] 
	-- Add the parameters for the stored procedure here
 @CarID int
AS
BEGIN
	select req.StartDate, isnull(emp.FirstName,'') +' '+ isnull(Emp.MiddleName,'') +' ' 
	  +isnull(emp.LastName,'')  EnFullName,
	   isnull(emp.FirstNameAr,'') +' '+ isnull(Emp.MiddleNameAr,'') +' ' 
	  +isnull(emp.LastNameAr,'')  ArFullName,req.BonID ,
	  req.ReadingWhenSupply ,req.VehicleID,
	  case when v.Gas_Type=1 then setting.GasValueInLiter
when v.Gas_Type=2 then setting.DieselValueInLiter 

end as Litres,setting.OilLiterCouponValue

 from Maintenance.VehicleRequest req
inner join Maintenance.Vehicles v
on req.VehicleID=v.id
inner join Nursing.Employee emp 
