/****** Object:  StoredProcedure [Maintenance].[VehiclesKiloProc]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROCEDURE  [Maintenance].[VehiclesKiloProc] 
	-- Add the parameters for the stored procedure here
 @CarID int
AS
BEGIN
	select   OperatingNo,StartKilometer,Endkilometer,RoadType,
CASE
    WHEN RoadType = 2 THEN Endkilometer-StartKilometer else 0  end as CountryKilo,
   case when RoadType=1  then Endkilometer-StartKilometer else 0 end as CityKilo
     ,DriverID,
	 isnull(emp.FirstName,'') +' '+ isnull(Emp.MiddleName,'') +' ' 
	  +isnull(emp.LastName,'')  EnFullName,
	   isnull(emp.FirstNameAr,'') +' '+ isnull(Emp.MiddleNameAr,'') +' ' 
	  +isnull(emp.LastNameAr,'')  ArFullName,req.VehicleID
 from Maintenance.VehicleRequest req
 inner join Nursing.Employee emp on Req.DriverID=
 emp.id
where req.Status=2
 

  and req.VehicleID=@CarID






END


GO
/****** Object:  StoredProcedure [Maintenance].[VehiclesOperationProc]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
create PROCEDURE  [Maintenance].[VehiclesOperationProc] 
	-- Add the parameters for the stored procedure here
 @CarID int
AS
BEGIN
	select v.*,
isnull(emp.FirstNameAr,'') +' '+ isnull(emp.MiddleNameAr,'') +' ' +isnull(emp.LastNameAr,'')+ ' '
  ArabicFullName,
  isnull(emp.FirstNameEn,'') +' '+ isnull(emp.MiddleNameEn,'') +' ' +isnull(emp.LastNameEn,'')+ ' '
  EnglishFullName,
req.StartKilometer,req.Endkilometer 
, case	when req.RoadType=1 then 	req.Endkilometer-req.StartKilometer else 0  end CityKilometer
, case	when req.RoadType=2 then 	req.Endkilometer-req.StartKilometer else 0  end CountryKilometer
,req.MissionNotes,req.ReadingWhenSupply,BonID,req.StartDate,StartTime
from [Maintenance].Vehicles v
left join [Maintenance].VehicleRequest req
on v.id=req.VehicleID
left join [Nursing].Employee emp
on req.DriverID=emp.Id
where req.Status=2

 and v.Id=@CarID






END


