/****** Object:  StoredProcedure [Marketing].[ReportLeads]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Marketing].[ReportLeads]
@Employee int null
as
select t.Code,t.Subject,t.Comment,e.FirstName+' '+e.MiddleName+' '+e.LastName as EmployeeName,q.Name as QualifyingProcess,r.Name as Rating,s.Name as salesUnit
from Marketing.LeadsTransAction t left join Nursing.Employee e on t.EmployeeId=e.Id
left join Marketing.QualifyingProcess q on t.QualifyingProcess=q.ID
left join Marketing.Rating r on t.RatingId=r.ID
left join Marketing.SalesUnit s on t.SalesUnitId=s.ID
where(t.EmployeeId = @Employee or @Employee is null)






GO
/****** Object:  StoredProcedure [Marketing].[ReportOpportunities]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Marketing].[ReportOpportunities]
@FromDate datetime null,
@Todate datetime null,
@Employee int null
as
select o.Code,o.Subject,o.Name,o.Date,o.EstimatedRevenue,e.FirstName+' '+e.MiddleName+' '+e.LastName as EmployeeName,s.Name as salesUnit,p.Name as Prognosis
from Marketing.Opportunities o left join Nursing.Employee e on o.EmployeeId=e.Id
left join Marketing.SalesUnit s on o.SalesUnitId=s.ID
left join Marketing.Prognosis p on o.ProbabilityId=p.ID
where
(o.Date >= convert(datetime,@FromDate,103) or @FromDate is null)
and (o.Date < convert(datetime,@Todate,103) or @Todate is null)
and (o.EmployeeId = @Employee or @Employee is null)






GO
/****** Object:  StoredProcedure [Marketing].[ReportSalesOrder]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Marketing].[ReportSalesOrder]
@FromDate datetime null,
@Todate datetime null
as
select s.Code,s.Name,s.DeliveryName,s.Status,s.DeliveryContact,s.RequestedReceiptDate,s.RequestedShipDate
from Marketing.SalesOrder s
where
(s.RequestedReceiptDate >= convert(datetime,@FromDate,103) or @FromDate is null)
and (s.RequestedReceiptDate < convert(datetime,@Todate,103) or @Todate is null)






