/****** Object:  StoredProcedure [Marketing].[SP_Contact]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [Marketing].[SP_Contact]
as
begin
select  [Marketing].[Contact].[Code],[ApplicationSetup].[Company].[Name]
,[Marketing].[Contact].FirstName,[Marketing].[Contact].MiddleName,[Marketing].[Contact].LastName
,[Registration].[Titles].ArabicTitleName,[Marketing].functions.functionsName,[Marketing].[Contact].[Profession]
,[Marketing].[Contact].[Phone],[Marketing].[Contact].Street,[Marketing].[Contact].EMailAddress
,[Marketing].[Contact].Extension,[Marketing].[Contact].[Department],[Marketing].[Contact].[PostalCode]
,[Marketing].[Contact].[Fax],[ApplicationSetup].Country.Name as CountryName,[ApplicationSetup].City.Name as CityName
from [Marketing].[Contact]
left join [ApplicationSetup].[Company] on [Marketing].[Contact].CompanyLookup=[ApplicationSetup].[Company].Id
left join [Registration].[Titles] on [Marketing].[Contact].[JobTitle]=[Registration].[Titles].Id
left join [Marketing].functions on [Marketing].[Contact].[FunctionPersonId]=[Marketing].functions.ID
left join [ApplicationSetup].Country on [Marketing].[Contact].CountryId=[ApplicationSetup].[Country].Id
left join [ApplicationSetup].City on [Marketing].[Contact].CityId=[ApplicationSetup].City.Id 
end





GO
