CREATE procedure [Marketing].[SP_SalesOrderDetails]
@SalesId int null
as
begin
select [Marketing].[SalesOrder].Code,[Marketing].[SalesOrder].Name,[GeneralStores].[Stocks].StockName,[GeneralStores].[Items].ItemName
,[Marketing].[SalesOrderDetails].Quantity,[GeneralStores].Units.UnitName,[Marketing].[SalesOrderDetails].[UnitPrice]
,[Marketing].[SalesOrderDetails].Discount,[Marketing].[SalesOrderDetails].[DiscountPercentage]
,[Marketing].[SalesOrderDetails].NetAmount,[Marketing].[SalesOrderDetails].[DeliveryNow]
from  [Marketing].[SalesOrderDetails]
left join [Marketing].[SalesOrder] on [Marketing].[SalesOrderDetails].SalesOrder=[Marketing].[SalesOrder].ID
left join [GeneralStores].[Stocks] on [Marketing].[SalesOrderDetails].StockId=[GeneralStores].[Stocks].ID
left join [GeneralStores].[Items] on [Marketing].[SalesOrderDetails].ItemId=[GeneralStores].[Items].ID
left join [GeneralStores].Units on  [Marketing].[SalesOrderDetails].UnitId = [GeneralStores].Units.ID
where
([Marketing].[SalesOrderDetails].SalesOrder = @SalesId or @SalesId is null)
