/****** Object:  StoredProcedure [Nuitration].[DiettypesCounter]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Nuitration].[DiettypesCounter]
@fromdate datetime,
@Todate datetime
as
begin

select Nuitration.DietTypes.LocalDescription,count(*) 
from Nuitration.DietRequest left join Nuitration.DietTypes
on Nuitration.DietRequest.DietTypeID=Nuitration.DietTypes.ID
where Nuitration.DietRequest.RequestDate >= convert( datetime,@fromdate ,103)
and Nuitration.DietRequest.RequestDate <= convert( datetime,@Todate ,103)
group by Nuitration.DietTypes.LocalDescription

end









