 from Nuitration.TPNOrderHeader TPNOH
 join Nuitration.TPNTemplate Temp on TPNOH.TPNTemplateId=Temp.Id
join Nuitration.TPNOrderCentralLineFormulas TPNOCF on TPNOH.Id=TPNOCF.TPNOrderHeaderId
join Nuitration.TPNCentralLineFormulas TPNCF on TPNOCF.TPNCentralLineFormulasId=TPNCF.Id
join Pharmacy.UnitConversionFactor UCF on TPNCF.UCFId = UCF.ID
join Pharmacy.Units UN on UCF.UnitID = UN.ID
left join Pharmacy.Drugs Dr on TPNCF.DrugId = Dr.ID
left join Pharmacy.GenericNames Gen on TPNCF.GenericID = Gen.ID
left join Pharmacy.StrenghtUnitMaster Stren on TPNCF.StrengthID = Stren.ID
