/****** Object:  StoredProcedure [Nuitration].[SP_SetDietTypeToMeal]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Nuitration].[SP_SetDietTypeToMeal] 
@MealTypeID int null,
@DietTypeID int null
as
begin
select [Nuitration].[MealTypes].[LatinDescription] as MealType,[Nuitration].[DietTypes].[LatinDescription] as DietType
from Nuitration.AssginDiteMeal
join Nuitration.MealTypes
on Nuitration.AssginDiteMeal.MealTypeID = Nuitration.MealTypes.ID
join Nuitration.DietTypes 
on Nuitration.AssginDiteMeal.DietTypeID = Nuitration.DietTypes.ID
where Nuitration.AssginDiteMeal.MealTypeID =@MealTypeID
and Nuitration.AssginDiteMeal.DietTypeID=@DietTypeID
End





