CREATE proc [Nursing].[Pensioners]
(
@EmpName nvarchar(50),
@Year nvarchar(20)
)
as 
select DATEADD(year, 60, Employee.BirthDate),* from Employee left join HR.Jobs on Employee.JobId = Jobs.id
left join HR.JobDegree on Employee.JobDegreeID = JobDegree.ID
where 
