/****** Object:  StoredProcedure [Nursing].[WorkCommencement]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Nursing].[WorkCommencement]
(
@EmpName nvarchar(50)
--@FromDate nvarchar(20),
--@ToDate nvarchar(20)
)
as 
select  *, 
degree = (select top(1) ScentificdegreeDescription from HR.Scentificdegree 
			inner join HR.EmployeeScentificdegree on EmployeeScentificdegree.ScentificdegreeID = Scentificdegree.Id 
			where EmployeeScentificdegree.EmployeeID = Employee.Id order by EmployeeScentificdegree.ID desc),
ScentificdegreeDate = (select top(1) ScentificdegreeDate from HR.EmployeeScentificdegree 
			where EmployeeScentificdegree.EmployeeID = Employee.Id order by EmployeeScentificdegree.ID desc),
KidsCount = (select count(ID) from HR.EmployeeRelatives 
			where EmployeeRelatives.EmployeeID = Employee.Id and (EmployeeRelatives.Relativetype = 9 or EmployeeRelatives.Relativetype = 10))
from nursing.Employee 
left join HR.Jobs on Employee.JobId = Jobs.id
left join HR.JobDegree on Employee.JobDegreeID = JobDegree.ID
left join ApplicationSetup.Nationality on Employee.Nationality = Nationality.Id
left join HR.SocialStatus on Employee.MaritalStatus = SocialStatus.ID
where @EmpName = '' or  @EmpName is null
or FirstNameAr like '%' + @EmpName + '%'
or MiddleNameAr like '%' + @EmpName + '%'
or LastNameAr like '%' + @EmpName + '%' 



--exec [Nursing].WorkCommencement ''

GO
