/****** Object:  StoredProcedure [Operations].[RepConsumablesCalculation]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Operations].[RepConsumablesCalculation]
	@DoctorId int null,
	@OperationId int null,
	@FromDate datetime null,
	@Todate datetime null
  AS

select distinct
isnull(pat.FirstName,'') +' '+ isnull(pat.MiddleName1,'') +' '+ isnull(pat.MiddleName2,'') +' '+ isnull(pat.LastName,'') patientName,
pat.code as MRN,
Serv.NameEn as [OperationName],
FORMAT((OperationReservation.OTDate),'dd/MM/yyyy') as [Date],
Doctor.Name as [DoctorName],
DoctorAnesthesiologist.Name as [Anesthesiologist],
LinkedItemservice.NameEn as LinkedItemName,LinkedItem.Value,LinkedItem.Price

from [JCIT_Temp_Database_Private].[Registration].[Patients] pat 
inner join [Operations].[OperationReservation] OperationReservation on 
OperationReservation.PatientId = pat.ID
inner join [Operations].[OperationSetupMaster] OperationMaster
on OperationReservation.OperationSetupID = OperationMaster.ID
inner join [ApplicationSetup].[Service] Serv 
on OperationMaster.OperationId = Serv.Id
inner join [Registration].[Doctors] Doctor on 
Doctor.Id = OperationReservation.SurgeonId
inner join [Registration].[Doctors] DoctorAnesthesiologist on 
DoctorAnesthesiologist.Id = OperationReservation.AnesthesiologistId
left join [Operations].[AnesthesiaRecord] AnesthesiaRecord on
AnesthesiaRecord.OperationReservationId = OperationReservation.ID
inner join [ApplicationSetup].[LinkedItem] LinkedItem on LinkedItem.ServiceID = Serv.Id
inner join [ApplicationSetup].[Service] LinkedItemservice on LinkedItemservice.Id= LinkedItem.LinkedServiceID 
where Doctor.Id= 	@DoctorId or @DoctorId is null
and  Serv.Id=@OperationId or @OperationId is null
and (OperationReservation.OTDate >= convert(date,@FromDate,103) or @FromDate is null)
and (OperationReservation.OTDate  < convert(date,@Todate,103) or @Todate is null)


GO
