     伀一 愀搀⸀倀愀琀椀攀渀琀䤀䐀 㴀 瀀⸀䤀搀ഀ਀ഀ਀ऀ䰀䔀䘀吀 䨀伀䤀一 䤀渀倀愀琀椀攀渀琀⸀圀愀爀搀 眀ഀ਀        伀一 眀⸀䤀搀 㴀 愀搀⸀䄀搀洀椀猀猀椀漀渀圀愀爀搀䤀䐀ഀ਀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 伀瀀攀爀愀琀椀漀渀猀⸀伀瀀攀爀愀琀椀漀渀刀攀猀攀爀瘀愀琀椀漀渀 漀瀀ഀ਀        伀一 漀瀀⸀倀愀琀椀攀渀琀䤀搀 㴀 瀀⸀䤀搀ഀ਀     䄀一䐀 漀瀀⸀䐀漀渀攀 㴀 ㄀ഀ਀ഀ਀    䰀䔀䘀吀 䨀伀䤀一 伀瀀攀爀愀琀椀漀渀吀礀瀀攀䴀愀猀琀攀爀 漀琀洀ഀ਀
        ON otm.ID = op.OTTypeId

    LEFT JOIN LatestVitalSigns vs
        ON vs.PatientID = p.Id
       AND vs.RN = 1

    LEFT JOIN PrimaryDiagnosis pd
        ON pd.PatientID = p.Id
       AND pd.RN = 1

    LEFT JOIN InPatient.MedicalObservation mo
        ON mo.PatientID = p.Id

	LEFT JOIN ApplicationSetup.nationality n 
           ON n.Id = p.NationalityId

    
	LEFT JOIN Registration.Doctors d 
           ON d.Id = mo.DoctorID


    LEFT JOIN OutPatient.SpecialityGroupDetails sp
        ON sp.ID = d.SpecialtyId
	
	LEFT JOIN Registration.sex sx 
           ON sx.ID = p.GenderId

    LEFT JOIN HR.Department dept
        ON dept.ID = d.DepartmentId

    LEFT JOIN HR.Branches br
        ON br.Id = ed.BranchId

    LEFT JOIN ApplicationSetup.Service srv
    ON srv.Id = op.OperationSetupID



    LEFT JOIN ApplicationSetup.cptcode cpt
    ON cpt.Id = srv.CPTcodeId

	LEFT JOIN InPatient.PreAnesthesiaEvaluation pae
    ON pae.PatientID = p.Id



   WHERE ed.VisiteDate >= @FromDate
  AND ed.VisiteDate < DATEADD(DAY, 1, @ToDate)

END


