/****** Object:  StoredProcedure [Operations].[spSurgeonStatisticsRepor]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Operations].[spSurgeonStatisticsRepor]
(
    @PrimaryDoctorId INT = NULL,
    @SurgonId INT = NULL,
    @OperationId INT = NULL,
    @DateFrom DATETIME = NULL,
    @DateTo DATETIME = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        OPR.ID AS Id,
        OPR.OTDate AS OperationDate,
        Serv.NameEn AS OperationName,
        Anesth.Name AS AnesthesiologistName,
        PreVer.CirculatingNurse,
        Surgeon.Name AS Surgeon,
        SpecMaster.Name AS SpecialityName,
        FORMAT(CAST(AnR.AnesthesiaFrom AS DATETIME), 'hh:mm tt') AS TimeFrom,
        FORMAT(CAST(AnR.RoomOutTime AS DATETIME), 'hh:mm tt') AS TimeTo,
        DATEDIFF(HOUR, AnR.AnesthesiaFrom, AnR.RoomOutTime) AS TotalHours
    FROM Operations.OperationReservation OPR
    JOIN Operations.PreOperative PreOp
        ON OPR.ID = PreOp.OperationReservationId
    JOIN Operations.OperationSetupMaster OSM
