/****** Object:  StoredProcedure [OutPatient].[AppointmentSponsersReport_AR]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   PROCEDURE [OutPatient].[AppointmentSponsersReport_AR]
    @FromDate DATETIME,
    @ToDate DATETIME
AS
BEGIN

    SELECT 

        FORMAT(CAST(Registration.DoctorsDailySchedule.ScheduleDate AS DATE), 'dd/MM/yyyy') 
        AS N'تاريخ_الحجز',

        Patient.FirstName + ' ' + Patient.MiddleName1 + ' ' + 
        Patient.MiddleName2 + ' ' + Patient.LastName 
        AS N'اسم_المريض',

        Patient.Code AS N'الرقم_الطبي',

        PrepareVisitSlip.OPnumber AS N'رقم_الزيارة',

        Clinics.NameArabic AS N'اسم_العيادة',

        Doc.NameAr AS N'اسم_الطبيب',

        FORMAT(CAST(PrepareVisitSlip.TimeOfVisit AS DATETIME), 'hh:mm:ss') 
        AS N'وقت_الكشف',

        Bill.AmountBefore AS N'المبلغ_المدفوع',

        (CASE
            WHEN PrepareVisitSlip.VisitSlipStatus = 1 THEN N'جديد'
            WHEN PrepareVisitSlip.VisitSlipStatus = 2 THEN N'مدفوع'
            WHEN PrepareVisitSlip.VisitSlipStatus = 3 THEN N'تم الكشف'
            WHEN PrepareVisitSlip.VisitSlipStatus = 4 THEN N'ملغي'
            WHEN PrepareVisitSlip.VisitSlipStatus = 5 THEN N'منتهي'
            WHEN PrepareVisitSlip.VisitSlipStatus = 6 THEN N'تم النقل'
            WHEN PrepareVisitSlip.VisitSlipStatus = 7 THEN N'تغيير طبيب'
            WHEN PrepareVisitSlip.VisitSlipStatus = 8 THEN N'إلغاء مع استرجاع'
            ELSE N''
        END) AS N'حالة_الزيارة',
