				   @dateFrom int,
				      @dateTo int

AS
BEGIN
	
	Select Registration.DoctorsDailySchedule.Id as DoctorsDailyScheduleID,
	       Registration.DoctorsDailySchedule.DoctorID as DoctorID,
		   Registration.DoctorsDailySchedule.ScheduleDate  as ScheduleDate,

	       Details.DoctorsDailyScheduleID as DoctorsDailyScheduleID,
		 
		   Proced.NameEnglish as ProcedureNameEnglish,
		   Proced.NameArabic as  ProcedureNameArabic,
		   Proced.Code as ProcedureCode,

