       瀀⸀䌀漀搀攀 䄀匀 嬀䴀刀一崀Ⰰഀ਀ഀ਀        ഀ਀        䰀吀刀䤀䴀⠀刀吀刀䤀䴀⠀ഀ਀            䤀匀一唀䰀䰀⠀瀀⸀䘀椀爀猀琀一愀洀攀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ഀ਀            䤀匀一唀䰀䰀⠀瀀⸀䴀椀搀搀氀攀一愀洀攀㄀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ഀ਀            䤀匀一唀䰀䰀⠀瀀⸀䴀椀搀搀氀攀一愀洀攀㈀Ⰰ✀✀⤀ ⬀ ✀ ✀ ⬀ഀ਀            䤀匀一唀䰀䰀⠀瀀⸀䰀愀猀琀一愀洀攀Ⰰ✀✀⤀ഀ਀
        )) AS [PATIENT NAME],

        
        p.MobileNumber AS [PATIENT MOBILE NUMBER],
        p.Email        AS [PATIENT EMAIL],

     
     CASE 
     WHEN p.PatientClassificationId = 1 THEN 'UAE Citizen'
     WHEN p.PatientClassificationId = 2 THEN 'Resident'
     WHEN p.PatientClassificationId = 3 THEN 'International Patient'
     ELSE 'Unknown'
     END AS [Resident/ International Patient / UAE Citizen],

       
        p.IdNumber       AS [EID],
        p.PassportNumber AS [PASSPORT],

 
        sx.NameEn AS [GENDER],
        nat.Name  AS [NATIONALTY],
        Convert(Date,p.DateOfBirth) AS [DATE OF BIRTH],
        p.Age  AS [AGE],

 
        p.City AS [EMIRATE OF RESIDENCE],
        p.City  AS [EMIRATE OF WORK],
        p.Address   AS [ADDRESS],
        p.Occupation AS [OCCUPATION],

      
        CASE 
            WHEN p.ImportantPatient = 1 THEN 'YES'
            ELSE 'NO'
        END AS [PEOPLE OF DETERMINATION (YES / NO)],

    
       Convert(Date, p.RegistrationDate) AS [APPOINTMENT DATE],
        CAST(mobd.CreatedDate AS DATE) AS [ACTIVITY DATE],
        Format(mobd.CreatedDate, 'hh:mm tt') AS [ACTIVITY TIME],

        Format(p.RegistrationDate, 'hh:mm tt') AS [TIME OF REGISTRATION],
        Format(lo.CreatedDate,'hh:mm tt')     AS [TIME OF DOCTOR ENTRY],
         Format(lo.LastModifiedDate, 'hh:mm tt') AS [TIME OF LEAVE],

       
        CASE 
            WHEN lo.LastModifiedDate IS NULL THEN NULL
            ELSE
                CAST(DATEDIFF(MINUTE, p.RegistrationDate, lo.LastModifiedDate) / 60 AS VARCHAR)
                + ' hrs '
                + CAST(DATEDIFF(MINUTE, p.RegistrationDate, lo.LastModifiedDate) % 60 AS VARCHAR)
                + ' mins'
        END AS [FULL WAITING TIME],

        
       cpt.Code AS [DENTAL CPT CODE],
       cpt.Description AS [DENTAL CPT DESCRIPTION],


        
        d.Name     AS [DENTIST NAME],
        sp.Name    AS [DENTIST SPECIALTY],
        d.LINCESE  AS [DENTIST LICENSE NUMBER]

    FROM Registration.Patients p

    
    LEFT JOIN LatestObservation lo
        ON p.Id = lo.PatientID
       AND lo.RN = 1

    
    inner JOIN InPatient.MedicalObservationDental mobd
