/****** Object:  StoredProcedure [OutPatient].[PrintBarcode]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [OutPatient].[PrintBarcode]
@Barcode Nvarchar(4000),
@Req int,
@SampleCollectDate datetime null
as
begin
select pat.TranslatedFallName  as PatientFullName ,pat.Code, @Barcode

 from Laboratory.SamplesReceivedHeader SH
inner join  Registration.Patients pat
on SH.PatientID = pat.Id
where SH.Id=@Req
end 

GO
/****** Object:  StoredProcedure [OutPatient].[RepAppointmentSchedule]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [OutPatient].[RepAppointmentSchedule]
	-- Add the parameters for the stored procedure here
	@ClinicId int = null,@Date VarChar (20) = null
AS
	
SELECT pvs.Id,SUBSTRING(Convert(nvarchar, pvs.Time),1,8) as Time,SUBSTRING(Convert(nvarchar, pvs.TimeOfVisit),1,8) as TimeOfVisit
,pvs.PatientID,pvs.DoctorsID,Pat.FirstName+' '+Pat.MiddleName1+' '+Pat.MiddleName2+' '+Pat.LastName as PatientName,doc.Name as DoctorName
,SchedDet.ProcedureId,SchedDet.ClinicId,PD.NameEnglish as ProcedureName,CS.NameEnglish as ClinicName,Sched.ScheduleDate

FROM OutPatient.PrepareVisitSlip pvs
inner Join Registration.Doctors doc on pvs.DoctorsID = doc.Id 
inner Join Registration.Patients Pat on pvs.PatientID = Pat.Id 
inner Join Registration.DoctorsDailyScheduleDetails SchedDet on pvs.ScheduleAppointmentID = SchedDet.Id 
inner Join Registration.DoctorsDailySchedule Sched on Sched.Id = SchedDet.DoctorsDailyScheduleID
inner Join OutPatient.ProceduresDetails PD on PD.ID = SchedDet.ProcedureId
inner Join OutPatient.ClinicSetup CS on CS.ID = SchedDet.ClinicId

WHERE (@ClinicId is null or  @ClinicId = SchedDet.ClinicId)
and (@Date is null or Convert(date, @Date) = Convert(date,Sched.ScheduleDate))
--group by DailySched.ScheduleDate


