/****** Object:  StoredProcedure [OutPatient].[RepClinicListDetails]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [OutPatient].[RepClinicListDetails]
AS
	
SELECT OutPatient.ClinicSetup.ID AS ClinicID, OutPatient.ClinicSetup.NameEnglish as ClinicName
, OutPatient.ClinicSetup.ClinicTypeID, OutPatient.ClinicType.NameEnglish as ClinicType
, Registration.Doctors.Name as DoctorName, 
OutPatient.ClinicSchedule.DoctorID, OutPatient.SpecialityGroupMaster.Name AS SpecialityName
, OutPatient.ClinicSetup.SpeciaityGroupID
FROM OutPatient.ClinicSetup INNER JOIN
OutPatient.ClinicType ON OutPatient.ClinicSetup.ClinicTypeID = OutPatient.ClinicType.ID INNER JOIN
OutPatient.ClinicSchedule ON OutPatient.ClinicSetup.ID = OutPatient.ClinicSchedule.ClinicID INNER JOIN
Registration.Doctors ON OutPatient.ClinicSchedule.DoctorID = Registration.Doctors.Id INNER JOIN
OutPatient.SpecialityGroupMaster ON OutPatient.ClinicSetup.SpeciaityGroupID = OutPatient.SpecialityGroupMaster.ID



GO
