else
begin
	select p.id, d.DrugID, p.code,p.TranslatedFallName,dr.DrugName,
       Dose_No = n.n ,d.id as DetailID,
	   case when d.TypeId=1 then  ((24/F.Value)*365*Period)+1
when d.TypeId=2 then ((24/F.Value)*30*Period)+1
else ((24/F.Value)*Period)+1
 end DoseCountM, d.DoseQty DoseCount,
       Dose_DateTime =FORMAT ( dateadd(hour, (n-1) * f.Value, dt.StartDateTime), 'dd-MM-yyyy hh:mm:ss tt')  
from   [Registration].Patients p
       inner join [OutPatient].PrescriptionsHeader r on r.PatientID = p.id
       inner join [OutPatient].PrescriptionsDetails d on d.PrescriptionID = r.id
