(select 
distinct
ISNULL(pat.FirstName,'')+' '+ ISNULL(pat.MiddleName1,'')+' '+ ISNULL(pat.MiddleName2,'')+' '+ ISNULL(pat.LastName,'')  patientName,
PrepareVisitSlip.OPnumber,
admitPatient.IPNumber,
EmergencyDetails.Code,
admitPatient.DischargeStatusId,
PrepareVisitSlip.VisitSlipStatus,
EmergencyDetails.DischargeStatuse,
DoctDailyScheduleDetails.PatientSeenDate,
DoctDailyScheduleDetails.EndVisitDate,
EmergencyDetails.VisiteDate,
EmergencyDetails.DischargeDate,
PrepareVisitSlipDoct.NameAr as PrepareVisitSlipDoctNameAr,
PrepareVisitSlipDoct.Name as PrepareVisitSlipDoctNameEn,
PatientDischarge.DischargDate as EndAdmitDate,
admitPatient.AdmissionDate ,
admitPatientDoct.NameAr as admitPatientDoctNameAr,
admitPatientDoct.Name as admitPatientDoctNameEn,
EmergencyDetailsDoct.NameAr as EmergencyDetailsDoctNameAr,
EmergencyDetailsDoct.Name as EmergencyDetailsDoctNameEn,
ClinicSetup.NameArabic,
ClinicSetup.NameEnglish,
ward.NameAr,
ward.Name,
CASE
    WHEN PrepareVisitSlip.VisitSlipStatus=5 THEN 'End'
    WHEN PrepareVisitSlip.VisitSlipStatus = 3 THEN 'Open'
END as PrepareVisitSlipStatus,
CASE
    WHEN admitPatient.DischargeStatusId=4 THEN 'End'
    WHEN admitPatient.DischargeStatusId != 5 THEN 'Open'
END as admitPatientStatus,
CASE
    WHEN EmergencyDetails.DischargeStatuse=4 THEN 'End'
    WHEN EmergencyDetails.DischargeStatuse != 5 THEN 'Open'
END as EmergencyDetailsStatus,
CASE
    WHEN PrepareVisitSlip.Id is not null and admitPatient.Id is not null THEN 'InPatient'
    WHEN PrepareVisitSlip.Id is not null and EmergencyDetails.ID is not null  THEN 'OutPatient'
    WHEN admitPatient.Id is not null and EmergencyDetails.ID is not null THEN 'InPatient'
	WHEN admitPatient.Id is not null THEN 'InPatient'
	WHEN PrepareVisitSlip.Id is not null THEN 'OutPatient'
    WHEN EmergencyDetails.ID is not null THEN 'Emergency'
END as PatientType

from [Registration].[Patients] pat 
left join [OutPatient].[PrepareVisitSlip] PrepareVisitSlip on PrepareVisitSlip.PatientID = pat.Id
left join [Registration].[DoctorsDailySchedule] DoctDailySchedule on DoctDailySchedule.Id = PrepareVisitSlip.ScheduleAppointmentID
