/****** Object:  StoredProcedure [OutPatient].[SP_DiagnosisAnswers_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [OutPatient].[SP_DiagnosisAnswers_Report]
 @DiagnosisQuestionId int = null,
  @DiagnosisGroupId int = null

AS
Select  
DiagnosisQuestion.DiagnosisQuestionName as DiagnosisQuestionName,
  
  DiagnosisAnswers.DiagnosisAnswerName

FROM    OutPatient.DiagnosisAnswers as DiagnosisAnswers
JOIN    OutPatient.DiagnosisQuestion as DiagnosisQuestion ON DiagnosisQuestion.Id = DiagnosisAnswers.DiagnosisQuestionID
JOIN    OutPatient.DiagnosisGroups as DiagnosisGroups ON DiagnosisGroups.Id = DiagnosisAnswers.DiagnosisGroupID



where ( DiagnosisAnswers.DiagnosisQuestionID = @DiagnosisQuestionId or @DiagnosisQuestionId is null)
and ( DiagnosisAnswers.DiagnosisGroupID = @DiagnosisGroupId or @DiagnosisGroupId is null)










GO
/****** Object:  StoredProcedure [OutPatient].[SP_DiagnosisGroups_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [OutPatient].[SP_DiagnosisGroups_Report]
 @departmentId int = null


AS
Select  
  DiagnosisGroups.DiagnosisGroupName as DiagnosisGroupName

FROM            OutPatient.DiagnosisGroups as DiagnosisGroups
  INNER JOIN    ApplicationSetup.CostCenter as Department ON DiagnosisGroups.CostCenterID = Department.Id


where ( DiagnosisGroups.CostCenterID = @departmentId or @departmentId is null)










GO
