CREATE procEDURE [OutPatient].[SP_DoctorsPersonalList_Report]
 @doctorId int = null

AS
Select  
Doctors.Name as DoctorName,
  
  DoctorsPersonalList.Description as Description,
  DoctorsPersonalList.Remarks as Remarks

FROM    OutPatient.DoctorsPersonalList as DoctorsPersonalList
JOIN    Registration.Doctors as Doctors ON DoctorsPersonalList.doctorId = Doctors.Id




where ( DoctorsPersonalList.doctorId = @doctorId or @doctorId is null)











GO
/****** Object:  StoredProcedure [OutPatient].[SP_DoctorsScheduleSummary_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [OutPatient].[SP_DoctorsScheduleSummary_Report]
 @DepartmentId int,
 @DoctorId int,
 @ScheduleDate datetime,
 @SessionId int

AS
Select DoctorsDailySchedule.DepartmentID,DoctorsDailySchedule.DoctorID,DoctorsDailySchedule.ScheduleDate,
SUBSTRING( CONVERT(nvarchar,Details.Time),0,9) as Time,
 patient.Code as PatientId,
 patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
 patient.SponsorName as SponsorName,
patient.PhoneNumber as PhoneNumber,
patient.MobileNumber as MobileNumber



from Registration.DoctorsDailySchedule as DoctorsDailySchedule
join Registration.DoctorsDailyScheduleDetails as Details on DoctorsDailySchedule.Id=Details.DoctorsDailyScheduleID
join ApplicationSetup.CostCenter as Department on DoctorsDailySchedule.DepartmentID=Department.Id
join Registration.Doctors as Doctors on DoctorsDailySchedule.DoctorID=Doctors.Id
join Registration.Sessions as Sessions on DoctorsDailySchedule.SessionID=Sessions.Id
join Registration.Patients as patient on Details.PatientId=patient.Id


