CREATE procEDURE [OutPatient].[SP_PatientVitals_Report]
 @PateintId int,
 @StartDate datetime,
 @ReadingDate Datetime

AS
Select PatientVitals.Value,CONVERT(date ,PatientVitals.StartDate,101) as StartDate,CONVERT(date ,PatientVitals.ReadingDate,101) as EndDate,PatientVitals.MonitoredDays, LTRIM(RIGHT(CONVERT(VARCHAR(20), PatientVitals.StartTime, 100), 7)) as VitalTime,PatientVitals.PateintId

FROM   OutPatient.PatientVitals as PatientVitals


where PatientVitals.PateintId = @PateintId and CONVERT( date,PatientVitals.StartDate,103) >= convert( date,@StartDate,103 ) and CONVERT( date,PatientVitals.ReadingDate,103) <= convert( date,@ReadingDate,103 )





GO
/****** Object:  StoredProcedure [OutPatient].[SP_PendingObservationList_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE procEDURE [OutPatient].[SP_PendingObservationList_Report]
 @doctorId int,
 @dateFrom datetime,
 @dateTo datetime


AS
Select 
patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
 Doctors.Name as DoctorName,
 MedicalObservation.Remarks as Remarks,
MedicalObservation.IP_OP as IP_OP,
MedicalObservation.MedicalObservationNO as MedicalObservationNO
 

from InPatient.MedicalObservation as MedicalObservation
join Registration.Doctors as Doctors on MedicalObservation.DoctorID=Doctors.Id
join Registration.Patients as patient on MedicalObservation.PatientId=patient.Id


where MedicalObservation.DoctorID=@doctorId
and MedicalObservation.CreatedDate >= @dateFrom
and MedicalObservation.CreatedDate <= @dateTo
and MedicalObservation.MedicalObservationStatus=1









GO
