/****** Object:  StoredProcedure [OutPatient].[SP_Prescriptions_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [OutPatient].[SP_Prescriptions_Report]
 @DateFrom Datetime = null,
 @DateTo Datetime = null,
 @PrescriptionNo int
AS
Select  Details.TypeId,Details.Period,
case
when Details.TypeId = 1 then Convert(varchar ,Details.Period) + ' ' + 'Days'
when Details.TypeId = 2 then Convert(varchar ,Details.Period) + ' ' + 'Month'
when Details.TypeId = 3 then Convert(varchar ,Details.Period) + ' ' + 'Year'
else ''
end as Duration,
Patients.Code,
Patients.TranslatedFallName as PatientNameAr,
Patients.TranslatedFallName as PatientNameEn,
Doctors.Name as DoctorName,
Header.PrescriptionDate as PrescriptionDate,
Header.OPNumber as OPNumber,
Header.PrescriptionNo as PrescriptionNo,
Drugs.DrugName as DrugName,
Units.UnitName as UnitName,
Details.Dosage as Dosage,
Frequencies.Name as FrequencyName,
Details.DoseQty as DoseQty,
case when Cast(Header.CreatedDate as date)= Cast(GETDATE() as date)
then (
select count(*) from OutPatient.PrescriptionsHeader where Cast(PrescriptionsHeader.CreatedDate as date)= Cast(GETDATE() as date))
else 
0
end
as number ,
--count (case when Cast(Header.CreatedDate as date)= Cast(GETDATE() as date)  then 1 else null end) as countpres,

Convert(varchar, FORMAT (Details.StartDate, 'dd/MM/yyyy '),20) as StartDate,
SUBSTRING(CONVERT(nvarchar, Details.StartTime),0,9) as StartTime,
DrugForm.FormName

	 ,gen.GenericNames,gen.GenericNamesAr

FROM    OutPatient.PrescriptionsHeader as Header
left JOIN    OutPatient.PrescriptionsDetails as Details ON Details.PrescriptionID = Header.Id
left JOIN    Registration.Patients as Patients ON Header.PatientID = Patients.Id
left JOIN    Registration.Doctors as Doctors ON Header.DoctorID = Doctors.Id
