/****** Object:  StoredProcedure [OutPatient].[SP_RepOutPatient]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [OutPatient].[SP_RepOutPatient]
    @FromDate DATETIME = NULL,
    @ToDate DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        DECLARE @StartDate DATETIME = ISNULL(@FromDate, CONVERT(DATE, GETDATE()))
        DECLARE @EndDate DATETIME = ISNULL(@ToDate, CONVERT(DATE, GETDATE()))
        
        -- Validate date range
        IF @StartDate > @EndDate
        BEGIN
            THROW 50001, 'FromDate cannot be greater than ToDate', 1
        END

        SELECT 
            -- Facility Information
            ISNULL(b.NameEn, 'Unknown Facility') AS FacilityName,
            
            -- Patient Information
            p.Code AS [S.N. / PATIENT ID],
            p.Code AS [MRN],
            CONCAT(ISNULL(p.FirstName, ''), ' ', ISNULL(p.MiddleName1, ''), ' ', ISNULL(p.LastName, '')) AS [PATIENT NAME],
            p.MobileNumber AS [PATIENT MOBILE NUMBER],
            p.Email AS [PATIENT EMAIL],
            
            -- Patient Status
            CASE 
                WHEN p.PatientClassificationId = 1 THEN 'UAE Citizen'
                WHEN p.PatientClassificationId = 2 THEN 'Resident'
                WHEN p.PatientClassificationId = 3 THEN 'International Patient'
                ELSE 'Unknown'
            END AS [Resident/ International Patient / UAE Citizen],
            
            p.IdNumber AS [EID],
            p.PassportNumber AS [PASSPORT],
            
            CASE WHEN p.GenderId = 1 THEN 'Male' WHEN p.GenderId = 2 THEN 'Female' ELSE 'Unknown' END AS [GENDER],
            
ਊ            䤀匀一唀䰀䰀⠀唀倀倀䔀刀⠀挀⸀一愀洀攀⤀Ⰰ ✀✀⤀ 䄀匀 嬀一䄀吀䤀伀一䄀䰀䤀吀夀崀Ⰰഀ਀            䌀䄀匀吀⠀瀀⸀䐀愀琀攀伀昀䈀椀爀琀栀 䄀匀 䐀䄀吀䔀⤀ 䄀匀 嬀䐀䄀吀䔀 伀䘀 䈀䤀刀吀䠀崀Ⰰⴀⴀ 瀀⸀䐀愀琀攀伀昀䈀椀爀琀栀 䄀匀 嬀䐀䄀吀䔀 伀䘀 䈀䤀刀吀䠀崀Ⰰഀ਀            䐀䄀吀䔀䐀䤀䘀䘀⠀夀䔀䄀刀Ⰰ 瀀⸀䐀愀琀攀伀昀䈀椀爀琀栀Ⰰ 䜀䔀吀䐀䄀吀䔀⠀⤀⤀ 䄀匀 嬀䄀䜀䔀崀Ⰰഀ਀            ഀ਀            ⴀⴀ 刀攀猀椀搀攀渀挀攀 䤀渀昀漀爀洀愀琀椀漀渀ഀ਀            ✀✀ 䄀匀 嬀䔀䴀䤀刀䄀吀䔀 伀䘀 刀䔀匀䤀䐀䔀一䌀䔀崀Ⰰഀ਀            ✀✀ 䄀匀 嬀䔀䴀䤀刀䄀吀䔀 伀䘀 圀伀刀䬀崀Ⰰഀ਀            瀀⸀䄀搀搀爀攀猀猀 䄀匀 嬀䄀䐀䐀刀䔀匀匀崀Ⰰഀ਀            瀀⸀伀挀挀甀瀀愀琀椀漀渀 䄀匀 嬀伀䌀䌀唀倀䄀吀䤀伀一崀Ⰰഀ਀            ഀ਀            ✀✀ 䄀匀 嬀倀䔀伀倀䰀䔀 伀䘀 䐀䔀吀䔀刀䴀䤀一䄀吀䤀伀一 ⠀夀䔀匀 ⼀ 一伀⤀崀Ⰰഀ਀            ഀ਀            ⴀⴀ 嘀椀猀椀琀 䤀渀昀漀爀洀愀琀椀漀渀ഀ਀            䌀䄀匀䔀 圀䠀䔀一 瀀瘀猀⸀嘀椀猀椀琀吀礀瀀攀 㴀 ㄀ 吀䠀䔀一 ✀一攀眀✀ 圀䠀䔀一 瀀瘀猀⸀嘀椀猀椀琀吀礀瀀攀 㴀 ㈀ 吀䠀䔀一 ✀䘀漀氀氀漀眀 唀瀀✀ 䔀䰀匀䔀 ✀唀渀欀渀漀眀渀✀ 䔀一䐀 䄀匀 嬀吀礀瀀攀 漀昀 嘀椀猀椀琀㨀 一攀眀 漀爀 䘀漀氀氀漀眀 甀瀀崀Ⰰഀ਀            ഀ਀            瀀瘀猀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䄀匀 嬀䌀刀䔀䄀吀䤀伀一⼀䄀倀倀伀䤀一吀䴀䔀一吀 䐀䄀吀䔀崀Ⰰഀ਀            瀀瘀猀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䄀匀 嬀嘀䤀匀䤀吀 䐀䄀吀䔀崀Ⰰഀ਀            䌀伀一嘀䔀刀吀⠀嘀䄀刀䌀䠀䄀刀⠀㠀⤀Ⰰ 瀀瘀猀⸀吀椀洀攀Ⰰ ㄀　㠀⤀ 䄀匀 嬀嘀䤀匀䤀吀 吀䤀䴀䔀崀Ⰰഀ਀            䤀匀一唀䰀䰀⠀䌀伀一嘀䔀刀吀⠀嘀䄀刀䌀䠀䄀刀⠀㠀⤀Ⰰ 瀀瘀猀⸀䌀爀攀愀琀攀搀䐀愀琀攀Ⰰ ㄀　㠀⤀Ⰰ ✀✀⤀ 䄀匀 嬀吀䤀䴀䔀 伀䘀 刀䔀䜀䤀匀吀刀䄀吀䤀伀一崀Ⰰഀ਀            ✀✀ 䄀匀 嬀吀䤀䴀䔀 伀䘀 䐀伀䌀吀伀刀 䔀一吀刀夀崀Ⰰഀ਀            ✀✀ 䄀匀 嬀吀䤀䴀䔀 伀䘀 䰀䔀䄀嘀䔀崀Ⰰഀ਀            ഀ਀            　 䄀匀 嬀䘀唀䰀䰀 圀䄀䤀吀䤀一䜀 吀䤀䴀䔀崀Ⰰഀ਀            ഀ਀            ⴀⴀ 嘀椀琀愀氀 匀椀最渀猀 ⠀昀爀漀洀 倀愀琀椀攀渀琀嘀椀琀愀氀猀⤀ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 瀀瘀⸀嘀愀氀甀攀 䘀刀伀䴀 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀倀愀琀椀攀渀琀嘀椀琀愀氀猀崀 瀀瘀 ഀ਀                    䤀一一䔀刀 䨀伀䤀一 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀䐀攀瀀琀圀椀猀攀崀 瘀瀀搀 伀一 瀀瘀⸀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀䐀攀瀀琀圀椀猀攀䤀搀 㴀 瘀瀀搀⸀䤀搀ഀ਀                    圀䠀䔀刀䔀 瀀瘀⸀倀愀琀攀椀渀琀䤀搀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 瘀瀀搀⸀瘀椀琀愀氀瀀愀爀愀洀攀琀攀爀䤀䐀 㴀 ⠀匀䔀䰀䔀䌀吀 瘀瀀⸀䌀漀搀攀 䘀刀伀䴀 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀崀 瘀瀀 圀䠀䔀刀䔀 瘀瀀⸀䌀漀搀攀 㴀 ✀圀攀椀最栀琀✀⤀ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瀀瘀⸀刀攀愀搀椀渀最䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ 㴀 䌀䄀匀吀⠀瀀瘀猀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀                    伀刀䐀䔀刀 䈀夀 瀀瘀⸀刀攀愀搀椀渀最䐀愀琀攀 䐀䔀匀䌀⤀Ⰰ 　⤀ 䄀匀 嬀倀䄀吀䤀䔀一吀 圀䔀䤀䜀䠀吀崀Ⰰഀ਀                    ഀ਀            䤀匀一唀䰀䰀⠀⠀匀䔀䰀䔀䌀吀 吀伀倀 ㄀ 瀀瘀⸀嘀愀氀甀攀 䘀刀伀䴀 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀倀愀琀椀攀渀琀嘀椀琀愀氀猀崀 瀀瘀 ഀ਀                    䤀一一䔀刀 䨀伀䤀一 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀䐀攀瀀琀圀椀猀攀崀 瘀瀀搀 伀一 瀀瘀⸀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀䐀攀瀀琀圀椀猀攀䤀搀 㴀 瘀瀀搀⸀䤀搀ഀ਀                    圀䠀䔀刀䔀 瀀瘀⸀倀愀琀攀椀渀琀䤀搀 㴀 瀀⸀䤀搀 ഀ਀                    䄀一䐀 瘀瀀搀⸀瘀椀琀愀氀瀀愀爀愀洀攀琀攀爀䤀䐀 㴀 ⠀匀䔀䰀䔀䌀吀 瘀瀀⸀䌀漀搀攀 䘀刀伀䴀 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀嘀椀琀愀氀倀愀爀愀洀攀琀攀爀猀崀 瘀瀀 圀䠀䔀刀䔀 瘀瀀⸀䌀漀搀攀 㴀 ✀䠀攀椀最栀琀✀⤀ഀ਀                    䄀一䐀 䌀䄀匀吀⠀瀀瘀⸀刀攀愀搀椀渀最䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ 㴀 䌀䄀匀吀⠀瀀瘀猀⸀䌀爀攀愀琀攀搀䐀愀琀攀 䄀匀 䐀䄀吀䔀⤀ഀ਀
                    ORDER BY pv.ReadingDate DESC), 0) AS [PATIENT HEIGHT],
                    
            ISNULL((SELECT TOP 1 pv.Value FROM [OutPatient].[PatientVitals] pv 
                    INNER JOIN [OutPatient].[VitalParametersDeptWise] vpd ON pv.VitalParametersDeptWiseId = vpd.Id
                    WHERE pv.PateintId = p.Id 
                    AND vpd.vitalparameterID = (SELECT vp.Code FROM [OutPatient].[VitalParameters] vp WHERE vp.Code = 'SystolicBP')
                    AND CAST(pv.ReadingDate AS DATE) = CAST(pvs.CreatedDate AS DATE)
                    ORDER BY pv.ReadingDate DESC), 0) AS [SYSTOLIC BLOOD PRESSURE],
                    
            ISNULL((SELECT TOP 1 pv.Value FROM [OutPatient].[PatientVitals] pv 
                    INNER JOIN [OutPatient].[VitalParametersDeptWise] vpd ON pv.VitalParametersDeptWiseId = vpd.Id
                    WHERE pv.PateintId = p.Id 
                    AND vpd.vitalparameterID = (SELECT vp.Code FROM [OutPatient].[VitalParameters] vp WHERE vp.Code = 'DiastolicBP')
                    AND CAST(pv.ReadingDate AS DATE) = CAST(pvs.CreatedDate AS DATE)
                    ORDER BY pv.ReadingDate DESC), 0) AS [DIASTOLIC BLOOD PRESSURE],
                    
            ISNULL((SELECT TOP 1 pv.Value FROM [OutPatient].[PatientVitals] pv 
                    INNER JOIN [OutPatient].[VitalParametersDeptWise] vpd ON pv.VitalParametersDeptWiseId = vpd.Id
                    WHERE pv.PateintId = p.Id 
                    AND vpd.vitalparameterID = (SELECT vp.Code FROM [OutPatient].[VitalParameters] vp WHERE vp.Code = 'Temperature')
                    AND CAST(pv.ReadingDate AS DATE) = CAST(pvs.CreatedDate AS DATE)
                    ORDER BY pv.ReadingDate DESC), 0) AS [PATIENT TEMPERATURE],
            
            -- Primary Diagnosis (ICD Code)
            ISNULL((SELECT TOP 1 icd.ICDCode FROM [OutPatient].[ICDCode] icd 
                    WHERE icd.PatientID = p.Id 
                    AND icd.OPNO = pvs.OPnumber
                    AND CAST(icd.OPDate AS DATE) = CAST(pvs.CreatedDate AS DATE)
                    ORDER BY icd.CreatedDate DESC), '') AS [ICD CODE (PRIMARY DIAGNOSIS)],
                    
