CREATE procEDURE [OutPatient].[SP_VaccinationDetails_Report]
 @vaccinationId int 

AS
Select  
  VaccinationDetails.DosageNo as DosageNo,
  VaccinationDetails.MinMonth as MinMonth,
  VaccinationDetails.MaxMonth as MaxMonth,
  Service.RecordName as Service,
  VaccinationDetails.Rate as Rate


FROM       OutPatient.VaccinationDetails as VaccinationDetails
JOIN       OutPatient.VaccinationMaster as VaccinationMaster ON VaccinationMaster.Id = VaccinationDetails.VaccinationID
join       ApplicationSetup.Service as Service ON Service.Id = VaccinationDetails.ServiceID



where VaccinationDetails.VaccinationID = @vaccinationId











GO
