	-- Add the parameters for the stored procedure here
	@Date VarChar (20) = null
AS
	--SELECT COUNT(DISTINCT DailySched.DoctorID) NumOfDoctors
	--, sum(case when isnull(SchedDet.Visited,'')=''  then 1 else 0 end)  as Pending 
	--, sum(case when isnull(SchedDet.Visited,'')=''   then 0 else 1 end) as Visited
	--,DailySched.ScheduleDate
	--FROM Registration.DoctorsDailyScheduleDetails SchedDet 
	--inner Join Registration.DoctorsDailySchedule DailySched on SchedDet.DoctorsDailyScheduleID = DailySched.Id 

	--group by DailySched.ScheduleDate

SELECT COUNT(DISTINCT DailySched.DoctorID) NumOfDoctors
--, sum(case when isnull(SchedDet.Visited,'')=''  then 1 else 0 end)  as Pending 
, sum(case when isnull(SchedDet.Visited,'')=''   then 0 else 1 end) as Visited
, sum(case when pvs.VisitSlipStatus=4   then 1 else 0 end) as canceled
, sum(case when pvs.VisitSlipStatus=5   then 1 else 0 end) as Done
, sum(SER.price) as price

,DailySched.ScheduleDate
FROM Registration.DoctorsDailyScheduleDetails SchedDet 
inner Join Registration.DoctorsDailySchedule DailySched on SchedDet.DoctorsDailyScheduleID = DailySched.Id 
inner Join OutPatient.PrepareVisitSlip pvs on pvs.ScheduleAppointmentID = DailySched.Id 
inner Join OutPatient.ClinicProcedures CP on CP.ProcedureID = SchedDet.ProcedureId
inner Join ApplicationSetup.Service SER on SER.Id = CP.ServiceID

WHERE (@Date is null or Convert(date, @Date) = Convert(date,DailySched.ScheduleDate))
group by DailySched.ScheduleDate


GO
