CREATE PROCEDURE  [OutPatient].[VisitSlipReport]
@OpNumber nvarchar(50)
AS


	SELECT
	Patients.TranslatedFallName ,
	      isnull( Patients.FirstName , '') + ' ' + isnull(Patients.MiddleName1 , '') + ' ' + isnull(Patients.MiddleName2 ,'') + ' ' + isnull(Patients.LastName ,'') AS PatientName,
