㨀㌀㔀㨀㐀㘀 倀䴀 ⨀⨀⨀⨀⨀⨀⼀ഀ਀匀䔀吀 䄀一匀䤀开一唀䰀䰀匀 伀一ഀ਀䜀伀ഀ਀匀䔀吀 儀唀伀吀䔀䐀开䤀䐀䔀一吀䤀䘀䤀䔀刀 伀一ഀ਀䜀伀ഀ਀ഀ਀ഀ਀ⴀⴀ 㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀㴀ഀ਀ഀ਀䌀刀䔀䄀吀䔀 瀀爀漀挀䔀䐀唀刀䔀 嬀伀甀琀倀愀琀椀攀渀琀崀⸀嬀圀愀椀琀椀渀最䤀渀琀攀爀瘀愀氀刀攀瀀漀爀琀崀ഀ਀ऀऀऀऀऀ 䀀䌀氀椀渀椀挀䤀䐀 椀渀琀Ⰰഀ਀ऀऀऀऀऀ 䀀䐀漀挀琀漀爀䤀䐀 椀渀琀Ⰰഀ਀
					  @FromDate Datetime=null,
					@ToDate Datetime=null
					

AS
BEGIN
	
	Select Registration.DoctorsDailySchedule.Id as DoctorsDailyScheduleID,
	       Registration.DoctorsDailySchedule.DoctorID as DoctorID,
		   Cast(Registration.DoctorsDailySchedule.ScheduleDate as date) as ScheduleDate,
		   Doc.NameAr  as DoctorNameArabic ,
		   Doc.Name as DoctorNameEnglish,

	       Details.DoctorsDailyScheduleID as DoctorsDailyScheduleID,
		   Details.EndVisitDate as EndVisitDate,
		   Details.PatientSeenDate as PatientSeenDate,
		   convert(char(5), Details.PatientSeenDate , 108) [Seentime] ,
		
		   Details.PatientArrivalDate as PatientArrivalDate,
		   convert(char(5), Details.PatientArrivalDate  , 108) [Arrivalime],
		   cast(Details.PatientArrivalDate  as time) arrtime,
		   cast(Details.PatientSeenDate  as time )seetime,
		   DATEDIFF(MINUTE, Details.PatientArrivalDate, Details.PatientSeenDate ) waitinginMinutes ,
		
           Patient.Id as PatientID,
		   Patient.Code as PatientCode,
		   Patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,

		   Clinics.ID as ClinicID,
	       Clinics.NameArabic as ClinicNameArabic,
		   Clinics.NameEnglish as ClinicNameEnglish
		  -- ,Registration.DoctorsDailyScheduleDetails.
		   ,Prepare.VisitNo

	from Registration.DoctorsDailySchedule 
	     join Registration.DoctorsDailyScheduleDetails as Details on DoctorsDailySchedule.Id=Details.DoctorsDailyScheduleID
		 join Registration.Doctors as Doc on Registration.DoctorsDailySchedule.DoctorID=Doc.Id
		 join Registration.Patients as Patient on Patient.Id = Details.PatientID
		 join OutPatient.ClinicSetup as Clinics on Details.ClinicId = Clinics.ID
		 join OutPatient.PrepareVisitSlip as Prepare on Details.Id= Prepare.ScheduleAppointmentID
		 --and Details.PatientID = Prepare.PatientID



   where( Details.ClinicId = @ClinicID or @ClinicID is null)
        and (DoctorsDailySchedule.DoctorID = @DoctorID or	@DoctorID is null)     
		and (DoctorsDailySchedule.ScheduleDate >= Convert(Datetime,@FromDate,103) or @FromDate is null)
		and (DoctorsDailySchedule.ScheduleDate < Convert(Datetime,@ToDate,103) or @ToDate is null) 
