/****** Object:  StoredProcedure [PayRoll].[HoursCollectionByDepartment]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [PayRoll].[HoursCollectionByDepartment]
@CostCenterID int,
@FromDate datetime,
@Todate Datetime
as
begin
select
Nursing.Employee.EmployeeCode as EmpCode,
(select isnull(e.FirstName,'FirstName') +' '+ ISnull(e.MiddleName,'MiddleName' )+' '+ ISnull(e.LastName,'LastName') from  Nursing.Employee e where e.Id=Nursing.Employee.Id )as EmpName,
ApplicationSetup.CostCenter.Name as Department,
ApplicationSetup.CostCenter.Code as DepartmentCode,
(select sum(A.NumbersOFHoures) from PayRoll.AttendanceSchedule a where a.EmployeeID= Nursing.Employee.Id and a.AttendanceDate >=convert( datetime,@FromDate,103) and a.AttendanceDate <= convert( datetime,@Todate,103))as actualWorkHours,

(select DATEDIFF(hh,s.StartTime ,s.EndTime) *22 from Registration.Sessions s where s.Id= Nursing.Employee.SessionID) as Shouldwork,

(select  Sum( h.NumberOFDays) from PayRoll.EmployeeHolidays h where h.EmployeeID=Nursing.Employee.Id and h.HolidayDateFrom >= convert( datetime,@FromDate,103) and h.HolidayDateTo <= convert( datetime,@Todate,103))as holidays

from Nursing.Employee  left join ApplicationSetup.CostCenterCompanies
on Nursing.Employee.SubDepartmentId  = ApplicationSetup.CostCenterCompanies.Id
left join ApplicationSetup.CostCenter
on ApplicationSetup.CostCenterCompanies.CostCenterId = ApplicationSetup.CostCenter.Id
left join Registration.Sessions
