/****** Object:  StoredProcedure [PayRoll].[RepEmployeeBounsAr]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   procEDURE  [PayRoll].[RepEmployeeBounsAr]
@startEmployeeID int null,
@startSubElementID int null,
@StartBounsDate date null,
@endBounsDate date null

as
begin
SELECT        ISNULL(E.FirstNameAr, '') + ' ' + ISNULL(E.MiddleNameAr, '') + ' ' + ISNULL(E.BeforeLastNameAr, '') + ' ' + E.LastNameAr AS 'Full Name', SE.NameArabic, convert(nvarchar(50),FORMAT(EB.BounsDate ,'dd/MM/yyyy'))as BounsDate, EB.Value, E.EmployeeCode, E.BasicSalary, EB.Reason
,

(select sum(BasicSalary) from(
SELECT      distinct E.EmployeeCode, E.BasicSalary
FROM            PayRoll.EmployeeBouns AS EB INNER JOIN
                         Nursing.Employee AS E ON E.Id = EB.EmployeeID INNER JOIN
                         HR.SubElements AS SE ON SE.ID = EB.SubElementID
						where   
				EB.EmployeeID =case when @startEmployeeID is null or @startEmployeeID=''or @startEmployeeID= 0 then EB.EmployeeID else @startEmployeeID end
	
			and
				EB.SubElementID =case when @startSubElementID is null or @startSubElementID='' or @startSubElementID= 0 then EB.SubElementID else @startSubElementID end	
			and
			EB.BounsDate between case when @StartBounsDate is null or @StartBounsDate='' then EB.BounsDate else @StartBounsDate end	 and case when @endBounsDate is null or @endBounsDate='' then EB.BounsDate else @endBounsDate end	 
 ) as tt) as Total

FROM            PayRoll.EmployeeBouns AS EB INNER JOIN
