  @AttendanceDate datetime,
  @EmployeeID int 
AS
Select FirstName,MiddleName,AttendanceDate,CONVERT(varchar(15),CAST(TimeFrom AS TIME),100) as TimeFrom,CONVERT(varchar(15),CAST(TimeTo AS TIME),100) as TimeTo,NumbersOFHoures
from PayRoll.AttendanceSchedule as header
join Nursing.Employee as detail
 on header.EmployeeID=detail.Id

where Month(header.AttendanceDate)=Month(Convert(datetime,@AttendanceDate,103))
and header.EmployeeID=@EmployeeID










GO
/****** Object:  StoredProcedure [PayRoll].[SP_EmployeeActivities_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
