CREATE procEDURE [PayRoll].[SP_EmployeeActivities_Report]
  @ActivityDate datetime,
  @EmployeeID int 
AS
Select EmployeeActivityCode,FirstName,MiddleName,ActivityDate,Notes,SalaryItemName,[Description],value,Details
from PayRoll.EmployeeActivities as header
join PayRoll.EmployeeActivityDetails as detail
on detail.EmployeeActivityID=header.ID
join Nursing.Employee as name
on name.Id=header.EmployeeID
join PayRoll.SalaryItems as item
on item.ID=detail.SalaryItemID

where year(header.ActivityDate)=year(Convert(datetime,@ActivityDate,103))
and header.EmployeeID=@EmployeeID









GO
