CREATE procEDURE [PayRoll].[SP_EmployeeHolidays_Report]
  @HolidayDateFrom datetime,
  @EmployeeID int 
AS
Select EmployeeHolidayCode,FirstName,MiddleName,HolidayRoleName,HolidayDateFrom,HolidayDateTo,HolidayResoan,NumberOFDays
from PayRoll.EmployeeHolidays as header
join HR.HolidayRole as detail
on header.HolidayTypeID=detail.ID
join Nursing.Employee as name
on name.Id=header.EmployeeID

where year(header.HolidayDateFrom)=year(Convert(datetime,@HolidayDateFrom,103))
and header.EmployeeID=@EmployeeID









GO
