/****** Object:  StoredProcedure [Pharmacy].[AgingRPT_Supp]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Pharmacy].[AgingRPT_Supp] 
	-- Add the parameters for the stored procedure here
AS
BEGIN
 SELECT
  c.ID,
  c.SupplierName NameEnglish ,c.SupplierNameAr NameArabic ,
  a.AgeName, a.AgeNameen,
  a.Age_Days,
	  ISNULL(SUM(SupplierDues.MoneyAmount+SupplierDues.VatTax+SupplierDues.expenses)- sum( ISNULL(paidAmount.paidvalue,0)),0) as Value
	 -- ISNULL(SUM(.TotalGRNValueFC+b.VatValue+b.TotalExpensesAmount)- sum( ISNULL(ic.paidValue,0)),0) as Value
FROM [Pharmacy]. Suppliers c
--JOIN [Pharmacy].GoodsReceivedNoteHeader b ON b.SupplierID = c.ID
join Billing.SupplierDues on  c.ID=SupplierDues.SupplierID
Left join
( 
select sum( ISNULL(ic.LocalValue,0)) paidvalue,ic.PharmacyHeaderID

from
[Pharmacy].PharmacySupplierInvoicePayment ic 
group by ic.PharmacyHeaderID
) as paidAmount
on paidAmount.PharmacyHeaderID=SupplierDues.Id
JOIN (
    SELECT *,
      PrevDays = LAG(Age_Days, 1, 0) OVER (ORDER BY Age_Days)
    FROM [GL].AgingSettings
) a ON SupplierDues.DueDate >= DATEADD(day, -a.Age_Days, GETDATE())
   AND SupplierDues.DueDate < DATEADD(day, -PrevDays, GETDATE())
GROUP BY
  c.ID,
  c.SupplierName ,c.SupplierNameAr ,
  a.Age_Days,a.AgeNameen,
  a.AgeName;




END
GO
