-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Pharmacy].[DrugOrderingPerUser]
	-- Add the parameters for the stored procedure here
	@FromDate datetime null,
	@Todate datetime null,
	@Employee int = null

AS
	
	SELECT        OD.ID, pH.PrescriptionNo, Drugs.DrugCode, GN.GenericNames, Drugs.DrugName, OD.Qty AS OrderedQTY, D.Name AS DoctorName, NSD.DispensedQty, NSD.CreatedBy AS DispensedBy, pD.PrescriptionID, 
                         OD.PrescriptionsDetailsID, OD.CreatedDate AS OrderedDate , NSD.DispensedPharmacy as dispencedStore
FROM            InPatient.PatientOrderMaster AS pat INNER JOIN
                         InPatient.PatientOrderDetail AS OD ON pat.ID = OD.PatientOrderMasterId LEFT OUTER JOIN
                         InPatient.NurseStation_Drug AS NSD ON OD.ID = NSD.DestinationOrderDetailID INNER JOIN
                         Pharmacy.Drugs AS Drugs ON OD.DrugID = Drugs.ID INNER JOIN
                         Pharmacy.GenericNames AS GN ON Drugs.GenericName_ID = GN.Id LEFT OUTER JOIN
                         OutPatient.PrescriptionsDetails AS pD ON OD.PrescriptionsDetailsID = pD.Id LEFT OUTER JOIN
                         OutPatient.PrescriptionsHeader AS pH ON pH.Id = pD.PrescriptionID LEFT OUTER JOIN
                         Registration.Doctors AS D ON pH.DoctorID = D.Id
						 inner join Nursing.Employee as Emp on D.EmployeeId = Emp.Id

where 
(OD.CreatedDate >= convert(date,@FromDate,103) or @FromDate is null)
and 
(OD.CreatedDate  < convert(date,@Todate,103) or @Todate is null)
and
(@Employee is null) or(D.Id=@Employee)

 
GO
