create proc [Pharmacy].[DrugSalesDetailed_old] 
@FromDate datetime,
@Todate datetime,
@substoreID int null,
@DrugID int null,
@PatientID int null,
@User nvarchar(50) null,
@doctorID int null,
@IPOPNo nvarchar(50) null
as
select 
'Sales' as type, 
Registration.Patients.Code as Code,
InPatient.WardPharmacy.ReceiptNo as ReceiptNo,
InPatient.WardPharmacy.IPNO as IPOP,
