from InPatient.WardPharmacy inner join Pharmacy.RefundDrugsHeader
on InPatient.WardPharmacy.ReceiptNo = Pharmacy.RefundDrugsHeader.ReceiptNo
left join Pharmacy.RefundDrugsDetails
on  Pharmacy.RefundDrugsHeader.ID= Pharmacy.RefundDrugsDetails.ReturnReceiptHeaderId
left join InPatient.WardPharmacyDetails
on  Pharmacy.RefundDrugsDetails.ReceptDetailsId = InPatient.WardPharmacyDetails.Id
left join Pharmacy.Drugs
on  InPatient.WardPharmacyDetails.DrugID = Pharmacy.Drugs.ID
left join Pharmacy.Units
on InPatient.WardPharmacyDetails.UnitID=Pharmacy.Units.ID
left join Pharmacy.Substores
on InPatient.WardPharmacy.SubStoreID=Pharmacy.Substores.ID
left join Registration.Patients
on InPatient.WardPharmacy.PatientID = Registration.Patients.Id
left join Registration.Doctors
on  InPatient.WardPharmacy.DoctorID=Registration.Doctors.Id
left join [JCIT_MembershipDB].[dbo].[AspNetUsers] as users
on  Pharmacy.RefundDrugsHeader.CreatedBy COLLATE SQL_Latin1_General_CP1_CI_AS=users.Id COLLATE SQL_Latin1_General_CP1_CI_AS
where 
Pharmacy.RefundDrugsHeader.ReturnReceiptDate >= convert(datetime,@FromDate,103)
and Pharmacy.RefundDrugsHeader.ReturnReceiptDate<= convert(datetime,@Todate,103)
and (InPatient.WardPharmacy.SubStoreID = @substoreID or @substoreID is null)
and (InPatient.WardPharmacyDetails.DrugID= @DrugID or @DrugID is null)
and (InPatient.WardPharmacy.PatientID= @PatientID or @PatientID is null)
and (Pharmacy.RefundDrugsHeader.CreatedBy= @User or @User is null)
and (InPatient.WardPharmacy.DoctorID= @doctorID or @doctorID is null)
and (InPatient.WardPharmacy.IPNO=@IPOPNo or @IPOPNo is null)






GO
