	-- interfering with SELECT statements.
	SELECT       (select top 1 [Image] from [ApplicationSetup].[QRImage] where [ReportName]=N'PharmacyStoresLocal' and [InvoiceId]=@LPOID order by id desc) as QRImage,   Pharmacy.LocalPurchaseOrderHeader.PONumber, Pharmacy.LocalPurchaseOrderHeader.PODate, Pharmacy.Substores.SubstoreName, Pharmacy.Suppliers.SupplierName, Drugs_1.DrugCode, Drugs_1.DrugName, 
                         Pharmacy.Units.UnitName, Pharmacy.UnitTemplate.UnitTemplateName, Pharmacy.LocalPurchaseOrderDetails.OrderedQTY, Pharmacy.LocalPurchaseOrderDetails.Price, 
                         Pharmacy.LocalPurchaseOrderDetails.BonusQuantity, 
						"DiscountAmount"	= 
			
