CREATE proc [Pharmacy].[GetEmergencypurchaserequestsResponseDelayedDept] 
as
						SELECT        TOP (200) Pharmacy.IssueRequest.ID, Pharmacy.IssueRequest.RequestNumber, Pharmacy.IssueRequest.RequestDate, Pharmacy.IssueRequest.MainSubstoreID, Pharmacy.IssueRequest.SubSubstoreID, 
                         Pharmacy.IssueRequest.Status, Pharmacy.IssueRequest.CreatedBy, Pharmacy.IssueRequest.CreationDate, Pharmacy.IssueRequest.ModifiedBy, Pharmacy.IssueRequest.ModificationDate, 
                         Pharmacy.IssueRequest.Priority, Pharmacy.IssueRequestdetails.DrugID, Pharmacy.IssueRequestdetails.UnitConversionID, Pharmacy.IssueRequestdetails.Quantity, Pharmacy.Drugs.DrugCode, 
                         Pharmacy.Drugs.DrugName, Pharmacy.Substores.SubstoreName, Substores_1.SubstoreName AS ToStockName, 'Waiting Reply(' + CONVERT(varchar(5), DATEDIFF(s, Pharmacy.IssueRequest.CreationDate, GETDATE()) / 3600) 
                         + ':' + CONVERT(varchar(5), DATEDIFF(s, Pharmacy.IssueRequest.CreationDate, GETDATE()) % 3600 / 60) + ':' + CONVERT(varchar(5), DATEDIFF(s, Pharmacy.IssueRequest.CreationDate, GETDATE()) % 60) + ')' AS Expr1, 
                         Pharmacy.IssueRequest.EmpRequestID, Nursing.Employee.EmployeeCode, ISNULL(Nursing.Employee.FirstName, '') + ' ' + ISNULL(Nursing.Employee.MiddleName, '') + ' ' + ISNULL(Nursing.Employee.BeforeLastName, '') 
