/****** Object:  StoredProcedure [Pharmacy].[ItemBalanceInStocks]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procEDURE [Pharmacy].[ItemBalanceInStocks]
(
@dateTo nvarchar(20)=null,
@dateFrom nvarchar(20)=null,
 @DrugTo int=null,
  @DrugFrom int=null,
  @SupStoreTo int=null,
  @SupStoreFrom int=null,
  @classFrom INT=NULL,
  @classTo INT =NULL) 
  as
  Begin
  
  if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end
Select * from(

select It.ID,It.DrugName,It.DrugCode,
isNull(OpenBalance.OBQty,0) OBQty,
isNull(Purchase.PurchQty,0) PurchQty,
isNULL(ReturnPurchase.RPurchaseQty,0) RPurchaseQty,
isNull(Dispense.DispenseQty,0) DispenseQty,
isNull(ReturnDispense.RDispenseQty,0) as RDispenseQty,
isNull(Addition.AddQty,0) AddQty,
isNull(subtraction.SubTractionQty,0) SubTractionQty
, CASE WHEN ISNULL([StockAdjustment].[QtYDifference], 0) > 0 THEN ISNULL([StockAdjustment].[QtYDifference], 0) ELSE 0 END AS [PositiveAdjustment]
, CASE WHEN ISNULL([StockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([StockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [NegativeAdjustment]
,isNull(TransferIN.InQty,0) TransferINQty
--,isNull(TransferOut.InQty,0) TransferOutQty
 from Pharmacy.Drugs It
Left Outer join

-- select Openinng Stock
(select Pharmacy.V_TStocksMov.DrugID
,Sum(isNull(Pharmacy.V_TStocksMov.ConversionAcceptQTY,0)) OBQty,N'رصيد افتتاحى' as Mtype
from Pharmacy.V_TStocksMov 
where  ISNULL(Pharmacy.V_TStocksMov.openingBalance, 0) = 1
			AND (@DrugFrom IS NULL OR Pharmacy.V_TStocksMov.DrugID >= @DrugFrom) AND (@DrugTo IS NULL OR  Pharmacy.V_TStocksMov.DrugID <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR Pharmacy.V_TStocksMov.[SubStoreID] >= @SupStoreFrom) AND (@SupStoreTo IS NULL OR Pharmacy.V_TStocksMov.[SubStoreID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR Pharmacy.V_TStocksMov.ClassID >= @classFrom) AND (@classTo IS NULL OR Pharmacy.V_TStocksMov.ClassID <= @classTo)
