AND (@SupStoreTo IS NULL OR Pharmacy.V_ReturnPurch.[SubstoreID] <= @SupStoreTo)
AND (@classFrom IS NULL OR ClassID >= @classFrom) 
AND (@classTo IS NULL OR ClassID <= @classTo) and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
((@dateFrom is null or PRDate>= @dateFrom)
 and (@dateTo is null or PRDate<=@dateTo))
 group by V_ReturnPurch.DrugID
 ) as ReturnPurchase on ReturnPurchase.DrugID=it.ID
 left outer join 
 (
 SELECT
  [DrugID]
, SUM(ISNULL(Pharmacy.V_Transfer.[TransferQty], 0)) AS [InQty]
FROM Pharmacy.V_Transfer 	
INNER JOIN [Pharmacy].[Drugs] ON [Pharmacy].[V_Transfer].[DrugID] = [Drugs].[ID]
WHERE
(@DrugFrom IS NULL OR DrugID >= @DrugFrom) AND (@DrugTo IS NULL OR DrugID <= @DrugTo)
AND (@SupStoreFrom IS NULL OR [StockID] >= @SupStoreFrom) AND (@SupStoreTo IS NULL OR [StockID] <= @SupStoreTo)
AND (@classFrom IS NULL OR [Drugs].[ClassificationId] >= @classFrom) AND (@classTo IS NULL OR [Drugs].[ClassificationId] <= @classTo)
AND (@dateFrom IS NULL OR TransferDate >= @dateFrom) AND (@dateTo IS NULL OR TransferDate <= @dateTo)
GROUP BY [DrugID]
) as TransferIN on TransferIN.DrugID=It.ID
) as TblAFter left outer join 
(
Select ID,(OldPurchQty+OldRDispenseQty+OldAddQty+[OldPositiveAdjustment]+OldTransferINQty-OldRPurchaseQty-OldDispenseQty-OldSubTractionQty-[OldNegativeAdjustment]) as Old
from(

select It.ID,It.DrugName,It.DrugCode,

isNull(OldPurchase.PurchQty,0) OldPurchQty,
isNULL(OldReturnPurchase.RPurchaseQty,0) OldRPurchaseQty,
isNull(OldDispense.DispenseQty,0) OldDispenseQty,
isNull(OldReturnDispense.RDispenseQty,0) as OldRDispenseQty,
isNull(OldAddition.AddQty,0) OldAddQty,
isNull(Oldsubtraction.SubTractionQty,0) OldSubTractionQty
, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) > 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) ELSE 0 END AS [OldPositiveAdjustment]
, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [OldNegativeAdjustment]
,isNull(OldTransferIN.InQty,0) OldTransferINQty
--,isNull(TransferOut.InQty,0) TransferOutQty
 from Pharmacy.Drugs It
Left Outer join
