Left Outer Join(
SELECT
	[Pharmacy].[Drugs].[ID] AS [DrugID]
	
	,Sum( COALESCE([DirectAddationDetails].[QTY], 0)) AS [AddQty]
	
	, N'إضافة مباشرة' AS [Mtype]
	
FROM
	[Pharmacy].[Drugs]
	LEFT OUTER JOIN [Pharmacy].[DrugClassification] ON [Pharmacy].[Drugs].[ClassificationId] = [Pharmacy].[DrugClassification].[ID]
	INNER JOIN [Pharmacy].[DirectAddationDetails] ON [Pharmacy].[Drugs].[ID] = [Pharmacy].[DirectAddationDetails].[DrugID]
	INNER JOIN [Pharmacy].[DirectAddationHeader] ON [Pharmacy].[DirectAddationDetails].[HeaderID] = [Pharmacy].[DirectAddationHeader].[ID]
	INNER JOIN [Pharmacy].[Substores] ON [Pharmacy].[DirectAddationHeader].[SubStockID] = [Pharmacy].[Substores].[ID]
where (@SupStoreFrom IS NULL OR [Pharmacy].[DirectAddationHeader].[SubStockID] >= @SupStoreFrom) 
AND (@SupStoreTo IS NULL OR [Pharmacy].[DirectAddationHeader].[SubStockID] <= @SupStoreTo)
 and (@classFrom IS NULL OR [DrugClassification].ID >= @classFrom) 
 AND (@classTo IS NULL OR [Pharmacy].[DrugClassification].ID <= @classTo) 
  and((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
(@dateFrom is null or [Pharmacy].[DirectAddationHeader].[OperationDate]< @dateFrom)
 
 group by [Drugs].[ID]
 ) as OldAddition on OldAddition.DrugID=it.ID
  
Left Outer Join(

SELECT
	
	 [Drugs].[ID] AS [DrugID]
	
	, Sum(COALESCE([DirectSubstractDetails].[QTY], 0)) AS [SubTractionQty]
	, N'خصم مباشر' AS [Mtype]
	
FROM
	[Pharmacy].[Drugs]
	LEFT OUTER JOIN [Pharmacy].[DrugClassification] ON [Pharmacy].[Drugs].[ClassificationId] = [Pharmacy].[DrugClassification].[ID]
	INNER JOIN [Pharmacy].[DirectSubstractDetails] ON [Pharmacy].[Drugs].[ID] = [Pharmacy].[DirectSubstractDetails].[DrugID]
	INNER JOIN [Pharmacy].[DirectSubstractHeader] ON [Pharmacy].[DirectSubstractDetails].[HeaderID] = [Pharmacy].[DirectSubstractHeader].[ID]
