, SUM(ISNULL(Pharmacy.V_Transfer.[TransferQty], 0)) AS [InQty]
FROM
V_Transfer 	INNER JOIN [Pharmacy].[Drugs] ON [Pharmacy].[V_Transfer].[DrugID] = [Drugs].[ID]
WHERE
(@DrugFrom IS NULL OR DrugID >= @DrugFrom) 
AND (@DrugTo IS NULL OR DrugID <= @DrugTo)
AND (@SupStoreFrom IS NULL OR [StockID] >= @SupStoreFrom) 
AND (@SupStoreTo IS NULL OR [StockID] <= @SupStoreTo)
AND (@classFrom IS NULL OR [Drugs].[ClassificationId] >= @classFrom) 
AND (@classTo IS NULL OR [Drugs].[ClassificationId] <= @classTo)
AND (@dateFrom IS NULL OR TransferDate < @dateFrom) 
GROUP BY [DrugID]
) as OldTransferIN on OldTransferIN.DrugID=It.ID
) as OldValues

) as TblBefore on TblBefore.ID=TblAFter.ID
where 
(@DrugFrom IS NULL OR TblAFter.ID>= @DrugFrom) AND (@DrugTo IS NULL OR TblAFter.ID <= @DrugTo)
  End





