, @DrugTo int = null 
, @DrugFrom int = null 
,@SubStoreFrom int = null 
,@SubStoreTo int = null )
as
begin

if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end
if @DrugTo =0
set @DrugTo=NULL;
if @DrugFrom =0
set @DrugFrom=NULL;
--Select V_Transfer in
select  ST.ID AS StockID,
St.SubstoreName,
St.SubstoreNameAr,
 '0'AS IssueNumber,
cast ( StockControlDetail.TransactionDate as date) TransactionDate,
StockControlDetail.TransactionDate as d,
DrugID
,DrugName
,DrugNameAr
,CostPrice Value,StockControlDetail.Qty Qty,StockControlDetail.TransactionNotes as Mtype ,StockControlDetail.TransactionNotes as MtypeEn
from Pharmacy.StockControlDetail inner join Pharmacy.StockControl on StockControl.ID=StockControlDetail.StockControlID
inner join Pharmacy.Substores St on St.id=StockControl.SubStoreID
inner join Pharmacy.Drugs  on Drugs.id=StockControl.DrugID
where
((@SubStoreFrom is null or SubstoreID=@SubStoreFrom) and
(@SubStoreTo is null or SubstoreID=@SubStoreTo))and
((@DrugFrom is null or DrugID>=@DrugFrom)and 
(@DrugTo is null or DrugID<=@DrugTo)) and 
((@dateFrom is null or TransactionDate>= @dateFrom)and 
(@dateTo is null or TransactionDate<=@dateTo))
 

--from Pharmacy. V_Transfer.
--inner join Pharmacy.Substores St on St.id=V_Transfer.StockID

--where ((@SubStoreFrom is null or V_Transfer.StockID>=@SubStoreFrom)and
