--((@DrugFrom is null or DrugID>=@DrugFrom) and 
--(@DrugTo is null or DrugID<=@DrugTo)) and 
--((@dateFrom is null or TransferDate>= @dateFrom)and
--(@dateTo is null or TransferDate>= @dateTo))

