/****** Object:  StoredProcedure [Pharmacy].[OpenBalanceStock]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Pharmacy].[OpenBalanceStock] 
	-- Add the parameters for the stored procedure here
	@ID int
AS
SELECT  ST.SubstoreName, LPOH.PONumber, It.DrugName, LPOD.Price, LPOD.Amount, LPOD.DiscountAmount, LPOD.AcceptQTY, It.DrugCode, It.BarCode
FROM Pharmacy.LocalPurchaseOrderHeader LPOH inner join Pharmacy.LocalPurchaseOrderDetails LPOD on LPOH.ID = LPOD.LPOID
     inner join Pharmacy.Substores ST on ST.ID=LPOH.SubstoreID inner join Pharmacy.Drugs It on It.ID =LPOD.DrugID 
WHERE LPOH.ID= @ID ;



GO
