CREATE procEDURE [Pharmacy].[PatirntDrugs]
	@dateTo nvarchar(50)=null,
	@dateFrom nvarchar(50)=null, 
	@PatientID int=null
AS
BEGIN
Select Patients.Code, ISNULL(Patients.FirstName+' '+ Patients.MiddleName1 +' '+Patients.MiddleName2 +' '+Patients.LastName,Patients.TranslatedFallName) as Name  , Pharmacy.RequestSuppliesHeader.PatientID ,PatientTypeID, OP_IPNo, SubStoreID, RequestSuppliesHeaderID ,DrugID ,Quantity,DrugCode , DrugName 
