--users.UserName as Users
from Pharmacy.StockControl
 inner join Pharmacy.Substores on Pharmacy.Substores.ID = Pharmacy.StockControl.SubStoreID
 inner join Pharmacy.Drugs on Pharmacy.Drugs.ID = Pharmacy.StockControl.DrugID
 inner join Pharmacy.LocalPurchaseOrderHeader on Pharmacy.LocalPurchaseOrderHeader.SubStoreID= Pharmacy.Substores.ID
 inner join Pharmacy.LocalPurchaseOrderDetails on Pharmacy.LocalPurchaseOrderDetails.LPOID =Pharmacy.LocalPurchaseOrderHeader.ID
 inner join Pharmacy.LocalPurchaseOrderDetails loc on loc.DrugID=Pharmacy.Drugs.ID
 inner join JCIT_MembershipDB.dbo.AspNetUsers Us on Us.Id =Pharmacy.LocalPurchaseOrderDetails.CreatedBy 
-- inner join JCIT_MembershipDB.dbo.AspNetUsers  on JCIT_MembershipDB.dbo.AspNetUsers.Id =Pharmacy.LocalPurchaseOrderDetails.CreatedBy 
 

where  (@substoreID is null or Pharmacy.Substores.ID=@substoreID) 
and ((@FromClass is null or Pharmacy.Drugs.ClassificationId<=@FromClass) and
     (@ToClass is null or Pharmacy.Drugs.ClassificationId<=@ToClass)   )
and( (@FromDrug is null or Pharmacy.StockControl.DrugID<=@FromDrug) and
     (@ToDrug is null or Pharmacy.StockControl.DrugID>=@ToDrug) )
--((@FromDate is null or Pharmacy.LocalPurchaseOrderDetails.CreatedDate <= Cast(@FromDate as date)and
--(@ToDate  is null or Pharmacy.LocalPurchaseOrderDetails.CreatedDate >= Cast(@ToDate  as date))






end






