CREATE PROCEDURE [Pharmacy].[PharmacyRequestSupply_rep] -- 2297
 (@ID int)
AS
BEGIN
  select 
   ( select top 1 [Image] from [ApplicationSetup].[QRImage] where [ApplicationSetup].[QRImage].InvoiceId=@ID and [ApplicationSetup].[QRImage].ReportName=N'RepDrugSales'     order by id desc) as QrImage,
       (select top 1 Company.taxfileNo  from [ApplicationSetup].Company ) as hospitalTax,
  case when p.id   IS NULL then RSH.OutPatName
 else P.FirstName+' '+p.MiddleName1+' '+p.MiddleName2+' '+p.LastName end  [Patient Full Name]
  ,
  case when p.id   IS NULL then RSH.OutPatName
 else p.TranslatedFallName end as TranslatedFallName
