/****** Object:  StoredProcedure [Pharmacy].[ReorderReportDrugs]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procedure [Pharmacy].[ReorderReportDrugs] 

@Todate datetime,
@Edit int=0

as
Begin
if @Edit=0
begin
 select  0 HDid,0 ReorderQty
 , pd.drugid,ceiling(sum(DoseQty)) totDoseQty
 ,isnull(grnDone.PriceLC,grnPending.PriceFC) PurchPrice,serv.Cost as initPurchCost
  ,serv.price as SellPrice
  ,drg.DrugName
  ,drg.DrugCode
  ,floor((isnull(st.StockOnHand,0))/fac.ConversionValue) TotStock,
unit.UnitName,0 as Selected,isnull(grnPending.AcceptQTY,0) as PendingQty,
ceiling((cast(ReorderLvel as decimal)/100)*(sum(DoseQty)/fac.ConversionValue)) Shortage,
ceiling((((sum(DoseQty)/fac.ConversionValue)/IsNULL(st.StockOnHand,1))-(cast( ReorderLvel as decimal)/100))*(sum(DoseQty)/fac.ConversionValue) -isnull(grnPending.AcceptQTY,0)) suggestedQty,

ceiling(((cast( ReorderLvel as decimal)/100)-((sum(DoseQty)/fac.ConversionValue)/IsNULL(st.StockOnHand,1)))*(sum(DoseQty)/fac.ConversionValue) -isnull(grnPending.AcceptQTY,0)) suggestedQty1
 ,fac.ID UCFID,0 purchaseReqId
 from [OutPatient].PrescriptionsDetails Pd
 inner join [OutPatient].PrescriptionsHeader Ph on
pd.PrescriptionID=ph.Id
left join (select top 1 drugid,PriceLC  from [Pharmacy].GoodsReceivedNoteDetails det
           inner join [Pharmacy].GoodsReceivedNoteHeader grn on grn.id=det.GRNId
           where grn.Status=2 order by det.id desc) grnDone on pd.DrugID=grnDone.DrugID
left join (select top 1 drugid,PriceFC,det.OrderedQTY AcceptQTY from [Pharmacy].LocalPurchaseOrderDetails det
			inner join [Pharmacy].LocalPurchaseOrderHeader grn on grn.id=det.LPOID
			where grn.Status=2 order by det.id desc) grnPending on pd.DrugID=grnPending.DrugID
