/****** Object:  StoredProcedure [Pharmacy].[RepMaxItemsQuantityInStock]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create procedure [Pharmacy].[RepMaxItemsQuantityInStock]
AS
select Stocks.SubstoreName
 ,Stocks.SubstoreNameAr
,StockControl.MaxQuantity,
StockControl.StockOnHand,
Items.DrugName,Items.DrugNameAr,
StockControl.RecordQuantity
 from  Pharmacy.StockControl StockControl
 inner join Pharmacy.Substores Stocks on Stocks.Id =StockControl.SubStoreID
 inner join Pharmacy.Drugs Items on Items.Id =StockControl.DrugID
  where StockControl.StockOnHand >=StockControl.MaxQuantity
GO
