  inner join [Pharmacy].[Drugs] Druge1 on DirectAddDel.DrugID=Druge1.ID 
join [Pharmacy].[Substores] Substores1 on Substores1.[ID] = DirectAdd.SubStockID 
where  
(borrowing.ID = @pharmacyID  or @pharmacyID = 0  or @pharmacyID  is null)
and(convert(date,DirectAdd.OperationDate) >= convert(date,@FromDate) or @FromDate is null)
and (convert(date,DirectAdd.OperationDate)  <= CONVERT(date,@ToDate) or @ToDate is null)


union 

SELECT borrowing.NameEN,
   
Substores2.SubstoreName,

 Druge2.DrugCode, Druge2.DrugName, 0 addition,
  DirectSubDel.QTY subtraction,
  'subtraction' stat
       
  FROM [Pharmacy].[Borrowing] borrowing

   inner join [Pharmacy].[DirectSubstractHeader] DirectSub on DirectSub.BorrowingID=borrowing.[ID]
   inner join [Pharmacy].[DirectSubstractDetails] DirectSubDel on DirectSubDel.HeaderID=DirectSub.ID
    
  inner join [Pharmacy].[Drugs] Druge2 on DirectSubDel.DrugID=Druge2.ID

  inner join [Pharmacy].[Substores] Substores2 on Substores2.[ID] = DirectSub.SubStockID
   
  
where  
(borrowing.ID = @pharmacyID  or @pharmacyID = 0  or @pharmacyID  is null)
and(convert(date,DirectSub.OperationDate) >= convert(date,@FromDate) or @FromDate is null)
and (convert(date,DirectSub.OperationDate)  <= CONVERT(date,@ToDate) or @ToDate is null)
) as brrowingtab
group by 
brrowingtab.NameEN,


brrowingtab.SubstoreName,

  brrowingtab.DrugName,
   brrowingtab.DrugCode
GO
