CREATE procEDURE [Pharmacy].[SP_Brands_Report]
 @GenericNamesId int = null


AS
Select  
	    GenericNames.GenericNames as GenericNames,
	    Brands.BrandName as BrandName
		
			   
FROM           
 Pharmacy.Brands as Brands
   JOIN Pharmacy.GenericNames as GenericNames ON GenericNames.Id = Brands.GenericNamesId
   


where ( Brands.GenericNamesId = @GenericNamesId or @GenericNamesId is null)










GO
