/****** Object:  StoredProcedure [Pharmacy].[Sp_PharmacyControlDetail]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [Pharmacy].[Sp_PharmacyControlDetail](@DateFrom datetime,@DateTo datetime,@storeID int)
as
begin
select 
Drugs.DrugCode,
Drugs.DrugName,
Drugs.DrugNameAr,
Sc.StockOnHand 
,Case when(Scd.SignValue > 0) then Scd.GRNDetailBalance else 0 end InQty
,Case when(Scd.SignValue < 0) then Scd.GRNDetailBalance else 0 end OutQty
,Case when(Scd.SignValue > 0) then Scd.TransactionNotes else '' end IFrom
,Case when(Scd.SignValue < 0) then Scd.TransactionNotes else '' end OTo
,AspNetUsers.EnglishName
, FORMAT (Scd.TransactionDate, 'dd/MM/yyyy, hh:mm')  TransactionDate
 from
Pharmacy.StockControl Sc
inner join Pharmacy.StockControlDetail Scd on Scd.StockControlID=Sc.ID
inner join Pharmacy.Drugs on Sc.DrugID=Drugs.ID
inner join Pharmacy.Substores on Sc.SubStoreID =Substores.ID
Left Join JCIT_MembershipDB.dbo.AspNetUsers on Scd.userId=AspNetUsers.Id
where Sc.SubStoreID = @storeID 
and (@DateFrom is null or  Scd.TransactionDate >= CAST(@DateFrom  AS date))and
    (@DateTo is null or Scd.TransactionDate  <= DATEADD(day,1,CAST(@DateTo AS date))) 

end
GO
