CREATE proc [Pharmacy].[SP_SearchGRN] --'2021-09-05','2022-01-20',25,1
@FromDate datetime = null,
@ToDate datetime = null,
@StockID int null,
@GetInvoicedOnly int null
as
select *, 
( select top 1 [Image] from [ApplicationSetup].[QRImage] where [ApplicationSetup].[QRImage].[PatID]=@StockID and [ApplicationSetup].[QRImage].ReportName=N'PharmacyRepGRNList'       order by id desc) as QrImage
 
 
 from 
