CREATE procEDURE [Pharmacy].[Sp_StockMovementDetails](
@dateTo 
--date = null
nvarchar(50) = null
,@dateFrom  
--date  null ,
nvarchar(50)
 = null ,
 @DrugTo int=null,
  @DrugFrom int=null,
  @SupStoreTo int=null,
  @SupStoreFrom int=null,
  @classFrom INT=NULL,
  @classTo INT =NULL) 
  as
if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end;

if @DrugTo =0
set @DrugTo=NULL;
if @DrugFrom =0
set @DrugFrom=NULL;


WITH

	[OpenBalance] AS
	(
		SELECT
			[Pharmacy].[Drugs].[ID] AS [DrugID]
			, [Pharmacy].[LocalPurchaseOrderHeader].[SubStoreID]
			, SUM(ISNULL([Pharmacy].[GoodsReceivedNoteDetails].[AcceptQTY], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [AcceptQTY]
		FROM
			[Pharmacy].[LocalPurchaseOrderHeader]
			inner join [Pharmacy].GRN_LPOs on [LocalPurchaseOrderHeader].ID = GRN_LPOs.LPOID
			INNER JOIN [Pharmacy].[GoodsReceivedNoteHeader] ON [Pharmacy].GRN_LPOs.GRNID = [Pharmacy].[GoodsReceivedNoteHeader].ID
			
			INNER JOIN [Pharmacy].[GoodsReceivedNoteDetails] ON [Pharmacy].[GoodsReceivedNoteHeader].[ID] = [Pharmacy].[GoodsReceivedNoteDetails].[GRNId]
			INNER JOIN [Pharmacy].[Drugs] ON [Pharmacy].[GoodsReceivedNoteDetails].[DrugID] = [Pharmacy].[Drugs].[ID]
			LEFT OUTER JOIN [Pharmacy].[UnitConversionFactor] ON [Pharmacy].[GoodsReceivedNoteDetails].[UnitConversionFactorId] = [Pharmacy].[UnitConversionFactor].[ID]
		WHERE 
			ISNULL([Pharmacy].[GoodsReceivedNoteHeader].OpeningBalance, 0) = 1
			AND (@DrugFrom IS NULL OR [Pharmacy].[Drugs].[ID] >= @DrugFrom) AND (@DrugTo IS NULL OR [Pharmacy].[Drugs].[ID] <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR [Pharmacy].[LocalPurchaseOrderHeader].[SubStoreID] >= @SupStoreFrom) AND (@SupStoreTo IS NULL OR [Pharmacy].[LocalPurchaseOrderHeader].[SubStoreID] <= @SupStoreTo)
