		GROUP BY
			[Pharmacy].[Drugs].[ID]
			, [Pharmacy].[LocalPurchaseOrderHeader].[SubstoreID]
	)
	, [PurchasesReturns] AS
	(
		SELECT
			Pharmacy.V_ReturnPurch.DrugID AS [DrugID]
			, Pharmacy.V_ReturnPurch.[SubstoreID]
			, SUM(ISNULL(V_ReturnPurch.[ReturnQTY], 0) ) AS [ReturnQTY]
		FROM

		  Pharmacy.V_ReturnPurch inner join 
		  Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_ReturnPurch.DrugID

		WHERE (issueToDepartment is null or issueToDepartment=0) and
			(@DrugFrom IS NULL OR Pharmacy.V_ReturnPurch.DrugID >= @DrugFrom) 
			AND (@DrugTo IS NULL OR Pharmacy.V_ReturnPurch.DrugID  <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR Pharmacy.V_ReturnPurch.[SubstoreID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR Pharmacy.V_ReturnPurch.[SubstoreID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) 
			AND (@classTo IS NULL OR it.ClassID <= @classTo)
			AND (@dateFrom IS NULL OR Pharmacy.V_ReturnPurch.PRDate >= @dateFrom) 
			AND (@dateTo IS NULL OR Pharmacy.V_ReturnPurch.PRDate <= @dateTo)
		GROUP BY
			Pharmacy.V_ReturnPurch.DrugID
			, Pharmacy.V_ReturnPurch.[SubstoreID]
	)
	, [Sales] AS
	(
		SELECT
			Pharmacy.V_DispenseItems.DrugID AS [DrugID]
			, Pharmacy.V_DispenseItems.[StockID]
			, SUM(ISNULL(Pharmacy.V_DispenseItems.DispenseQty, 0)) AS [Quantity]
		FROM
		    Pharmacy.V_DispenseItems inner join 
			Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_DispenseItems.DrugID
			WHERE
			(@DrugFrom IS NULL OR Pharmacy.V_DispenseItems.DrugID >= @DrugFrom) 
			AND (@DrugTo IS NULL OR Pharmacy.V_DispenseItems.DrugID <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR Pharmacy.V_DispenseItems.[StockID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR Pharmacy.V_DispenseItems.[StockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) 
			AND (@classTo IS NULL OR it.ClassID  <= @classTo)
			AND (@dateFrom IS NULL OR Pharmacy.V_DispenseItems.CreatedDate >= @dateFrom) 
			AND (@dateTo IS NULL OR Pharmacy.V_DispenseItems.[CreatedDate] <= @dateTo)
