洀愀挀礀崀⸀嬀䐀爀甀最猀崀⸀嬀䤀䐀崀 䄀匀 嬀䐀爀甀最䤀䐀崀ഀ਀ऀऀऀⰀ 匀唀䴀⠀䤀匀一唀䰀䰀⠀嬀倀栀愀爀洀愀挀礀崀⸀嬀䤀猀猀甀攀琀漀䐀攀瀀愀爀琀洀攀渀琀䔀渀琀爀礀崀⸀嬀䤀猀猀甀攀儀琀礀崀Ⰰ 　⤀ ⨀ 䤀匀一唀䰀䰀⠀嬀唀渀椀琀䌀漀渀瘀攀爀猀椀漀渀䘀愀挀琀漀爀崀⸀嬀䌀漀渀瘀攀爀猀椀漀渀嘀愀氀甀攀崀Ⰰ ㄀⤀⤀ 䄀匀 嬀䤀猀猀甀攀儀琀礀崀ഀ਀ऀऀ䘀刀伀䴀ഀ਀ऀऀऀ嬀倀栀愀爀洀愀挀礀崀⸀嬀䤀猀猀甀攀琀漀䐀攀瀀愀爀琀洀攀渀琀崀ഀ਀
			INNER JOIN [Pharmacy].[IssuetoDepartmentEntry] ON [IssuetoDepartment].[ID] = [Pharmacy].[IssuetoDepartmentEntry].[IssuetoDepartmentId]
			INNER JOIN [Pharmacy].[Drugs] ON [IssuetoDepartmentEntry].[DrugID] = [Drugs].[ID]
			LEFT OUTER JOIN [Pharmacy].[UnitConversionFactor] ON [Pharmacy].[IssuetoDepartmentEntry].[UnitConversionID] = [UnitConversionFactor].[ID]
		WHERE
			(@DrugFrom IS NULL OR [Pharmacy].[Drugs].[ID] >= @DrugFrom) 
			AND (@DrugTo IS NULL OR [Pharmacy].[Drugs].[ID] <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR [Pharmacy].[IssuetoDepartment].[StockID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR [Pharmacy].[IssuetoDepartment].[StockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR [Pharmacy].[Drugs].[ClassificationId] >= @classFrom) 
			AND (@classTo IS NULL OR [Pharmacy].[Drugs].[ClassificationId] <= @classTo)
			AND (@dateFrom IS NULL OR [IssuetoDepartment].[IssueDate] >= @dateFrom)
			 AND (@dateTo IS NULL OR [IssuetoDepartment].[IssueDate] <= @dateTo)
		GROUP BY
			[Pharmacy].[IssuetoDepartment].[StockID]
			, [Pharmacy].[Drugs].[ID]
	)
	, [TransfersOut] AS
	(
		SELECT
			[Pharmacy].[IssuetoDepartment].[MainStockID] AS [SubStockID]
			, [Pharmacy].[Drugs].[ID] AS [DrugID]
			, SUM(ISNULL([Pharmacy].[IssuetoDepartmentEntry].[IssueQty], 0) * ISNULL([Pharmacy].[UnitConversionFactor].[ConversionValue], 1)) AS [IssueQty]
		FROM
			[Pharmacy].[IssuetoDepartment]
			INNER JOIN [Pharmacy].[IssuetoDepartmentEntry] ON [Pharmacy].[IssuetoDepartment].[ID] = [Pharmacy].[IssuetoDepartmentEntry].[IssuetoDepartmentId]
			INNER JOIN [Pharmacy].[Drugs] ON [IssuetoDepartmentEntry].[DrugID] = [Drugs].[ID]
			LEFT OUTER JOIN [Pharmacy].[UnitConversionFactor] ON [Pharmacy].[IssuetoDepartmentEntry].[UnitConversionID] = [Pharmacy].[UnitConversionFactor].[ID]
		WHERE
			(@DrugFrom IS NULL OR [Drugs].[ID] >= @DrugFrom) 
			AND (@DrugTo IS NULL OR [Pharmacy].[Drugs].[ID] <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR [IssuetoDepartment].[MainStockID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR [IssuetoDepartment].[MainStockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR [Drugs].[ClassificationId] >= @classFrom) 
