			AND (@dateFrom IS NULL OR V_TransferCycle.[IssueReturnDate] >= @dateFrom) AND (@dateTo IS NULL OR V_TransferCycle.[IssueReturnDate]  <= @dateTo)
		GROUP BY
			Pharmacy.V_TransferCycle.[MainStockID]
			, Pharmacy.V_TransferCycle.[DrugID]
