	, [DirectAdditions] AS
	(
		SElECT
			[Pharmacy].[Drugs].[ID] AS [DrugID]
			, [DirectAddationHeader].[SubStockID]
			, SUM(ISNULL([DirectAddationDetails].[QTY], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [QTY]
		FROM
			[Pharmacy].[DirectAddationHeader]
			INNER JOIN [Pharmacy].[DirectAddationDetails] ON [DirectAddationHeader].[ID] = [DirectAddationDetails].[HeaderID]
			INNER JOIN [Pharmacy].[Drugs] ON [DirectAddationDetails].[DrugID] = [Drugs].[ID]
			LEFT OUTER JOIN [Pharmacy].[UnitConversionFactor] ON [DirectAddationDetails].[UnitConversionFactorId] = [UnitConversionFactor].[ID]
		WHERE
			(@DrugFrom IS NULL OR [Pharmacy].[Drugs].[ID] >= @DrugFrom) 
			AND (@DrugTo IS NULL OR [Pharmacy].[Drugs].[ID] <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR [Pharmacy].[DirectAddationHeader].[SubStockID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR [Pharmacy].[DirectAddationHeader].[SubStockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR [Pharmacy].[Drugs].[ClassificationId] >= @classFrom) 
			AND (@classTo IS NULL OR [Pharmacy].[Drugs].[ClassificationId] <= @classTo)
			AND (@dateFrom IS NULL OR [Pharmacy].[DirectAddationHeader].[OperationDate] >= @dateFrom) AND (@dateTo IS NULL OR [DirectAddationHeader].[OperationDate] <= @dateTo)
		GROUP BY
			[Pharmacy].[Drugs].[ID]
			,[Pharmacy].[DirectAddationHeader].[SubStockID]
	)
	, [DirectSubtractions] AS
	(
		SELECT 
			[Pharmacy].[Drugs].[ID] AS [DrugID]
			,[Pharmacy].[DirectSubstractHeader].[SubStockID]
			,SUM(ISNULL([Pharmacy].[DirectSubstractDetails].[QTY], 0) * ISNULL([Pharmacy].[UnitConversionFactor].[ConversionValue], 1)) AS [QTY]
		FROM
			[Pharmacy].[DirectSubstractHeader]
			INNER JOIN [Pharmacy].[DirectSubstractDetails] ON [DirectSubstractHeader].[ID] = [DirectSubstractDetails].[HeaderID]
			INNER JOIN [Pharmacy].[Drugs] ON [Pharmacy].[DirectSubstractDetails].[DrugID] = [Pharmacy].[Drugs].[ID]
