	, [OldSalesReturns] AS
	(
		SELECT
			Pharmacy.V_DispenseItemsReturn.DrugID AS [DrugID]
			, Pharmacy.V_DispenseItemsReturn.[SubstoreID]
			, SUM(ISNULL(Pharmacy.V_DispenseItemsReturn.[ReturnQty], 0)) AS [ReturnedQty]
		FROM Pharmacy.V_DispenseItemsReturn 
		--inner join V_itemClassification it on it.id=V_DispenseDrugsReturn.DrugID
			--[InPatient].[RequestSupplyReturnHeader]
			--INNER JOIN [InPatient].[RequestSupplyReturnDetails] ON [RequestSupplyReturnHeader].[ID] = [RequestSupplyReturnDetails].[RequestSupplyReturnHeaderID]
			--INNER JOIN [InPatient].[RequestSuppliesDetails] ON [RequestSupplyReturnDetails].[RequestSupplyDetailsID] = [RequestSuppliesDetails].[Id]
			--INNER JOIN [Pharmacy].[Drugs] ON [RequestSuppliesDetails].[DrugID] = [Drugs].[ID]
			--INNER JOIN [Pharmacy].[StockBatches] ON [RequestSuppliesDetails].[StockBatchId] = [StockBatches].[Id]
			--LEFT OUTER JOIN [Pharmacy].[UnitConversionFactor] ON [RequestSuppliesDetails].[UnitConversionID] = [UnitConversionFactor].[ID]
		WHERE
			(@DrugFrom IS NULL OR Pharmacy.V_DispenseItemsReturn.DrugID >= @DrugFrom) 
			AND (@DrugTo IS NULL OR Pharmacy.V_DispenseItemsReturn.DrugID <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR Pharmacy.V_DispenseItemsReturn.[SubstoreID] >= @SupStoreFrom) 
			AND (@SupStoreTo IS NULL OR Pharmacy.V_DispenseItemsReturn.[SubstoreID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR Pharmacy.V_DispenseItemsReturn.ClassID >= @classFrom) 
			AND (@classTo IS NULL OR Pharmacy.V_DispenseItemsReturn.ClassID <= @classTo)
			AND (@dateFrom IS NULL OR Pharmacy.V_DispenseItemsReturn.[RefundDate] < @dateFrom) 
		GROUP BY
			Pharmacy.V_DispenseItemsReturn.DrugID
			, Pharmacy.V_DispenseItemsReturn.[SubstoreID]
	)
	, [OldTransfersIn] AS
	(
		SELECT
