			[Pharmacy].[IssuetoDepartment].[StockID]
			, [Pharmacy].[Drugs].[ID]
	)
		,[OldRTransfersOut] As
	(
	SELECT 
	V_TransferCycle.[StockID] AS [SubStockID]
			, V_TransferCycle.[DrugID] AS [DrugID]
			, SUM(ISNULL(V_TransferCycle.IssueReturnQty, 0)) AS [RIssueQty]
			from V_TransferCycle
			inner join GeneralStores.V_itemClassification it on it.id=V_TransferCycle.DrugID
			WHERE
			(@DrugFrom IS NULL OR V_TransferCycle.DrugID >= @DrugFrom) AND (@DrugTo IS NULL OR V_TransferCycle.DrugID <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR V_TransferCycle.[StockID] >= @SupStoreFrom) AND (@SupStoreTo IS NULL OR V_TransferCycle.[StockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) AND (@classTo IS NULL OR it.ClassID <= @classTo)
			AND (@dateFrom IS NULL OR V_TransferCycle.[IssueReturnDate] < @dateFrom)
		GROUP BY
			V_TransferCycle.[StockID]
			, V_TransferCycle.[DrugID]
	)


	,[OldRTransfersIN] As
	(
	SELECT 
	V_TransferCycle.[StockID] AS [SubStockID]
			, V_TransferCycle.[DrugID] AS [DrugID]
			, SUM(ISNULL(V_TransferCycle.IssueReturnQty, 0)) AS [RIssueQty]
			from V_TransferCycle
			inner join GeneralStores.V_itemClassification it on it.id=V_TransferCycle.DrugID
			WHERE
			(@DrugFrom IS NULL OR V_TransferCycle.DrugID >= @DrugFrom) AND (@DrugTo IS NULL OR V_TransferCycle.DrugID <= @DrugTo)
			AND (@SupStoreFrom IS NULL OR V_TransferCycle.[StockID] >= @SupStoreFrom) AND (@SupStoreTo IS NULL OR V_TransferCycle.[StockID] <= @SupStoreTo)
			AND (@classFrom IS NULL OR it.ClassID >= @classFrom) AND (@classTo IS NULL OR it.ClassID <= @classTo)
			AND (@dateFrom IS NULL OR V_TransferCycle.[IssueReturnDate] < @dateFrom)
		GROUP BY
			V_TransferCycle.[StockID]
			, V_TransferCycle.[DrugID]
	)
	, [OldDirectAdditions] AS
	(
		SElECT
			[Drugs].[ID] AS [DrugID]
			, [DirectAddationHeader].[SubStockID]
			, SUM(ISNULL([DirectAddationDetails].[QTY], 0) * ISNULL([UnitConversionFactor].[ConversionValue], 1)) AS [QTY]
		FROM
			[Pharmacy].[DirectAddationHeader]
			INNER JOIN [Pharmacy].[DirectAddationDetails] ON [DirectAddationHeader].[ID] = [DirectAddationDetails].[HeaderID]
			INNER JOIN [Pharmacy].[Drugs] ON [DirectAddationDetails].[DrugID] = [Drugs].[ID]
