			, CASE WHEN ISNULL([OldStockAdjustment].[QtYDifference], 0) < 0 THEN ISNULL([OldStockAdjustment].[QtYDifference], 0) * -1 ELSE 0 END AS [OldNegativeAdjustment]
		FROM
			[Pharmacy].[Drugs]
			INNER JOIN [Pharmacy].[StockControl] ON [Drugs].[ID] = [StockControl].[DrugID]
			INNER JOIN [Pharmacy].[Substores] ON [StockControl].[SubStoreID] = [Substores].[ID]

			LEFT OUTER JOIN [OpenBalance] ON [Drugs].[ID] = [OpenBalance].[DrugID] AND [Substores].[ID] = [OpenBalance].[SubStoreID]
			LEFT OUTER JOIN [Purchases] ON [Drugs].[ID] = [Purchases].[DrugID] AND [Substores].[ID] = [Purchases].[SubStoreID]
			LEFT OUTER JOIN [PurchasesReturns] ON [Drugs].[ID] = [PurchasesReturns].[DrugID] AND [Substores].[ID] = [PurchasesReturns].[SubStoreID]
			LEFT OUTER JOIN [Sales] ON [Drugs].[ID] = [Sales].[DrugID] AND [Substores].[ID] = [Sales].[StockID]
			LEFT OUTER JOIN [SalesReturns] ON [Drugs].[ID] = [SalesReturns].[DrugID] AND [Substores].[ID] = [SalesReturns].[SubstoreID]
			LEFT OUTER JOIN [TransfersIn] ON [Drugs].[ID] = [TransfersIn].[DrugID] AND [Substores].[ID] = [TransfersIn].[StockID]
			LEFT OUTER JOIN [TransfersOut] ON [Drugs].[ID] = [TransfersOut].[DrugID] AND [Substores].[ID] = [TransfersOut].[SubStockID]
			LEFT OUTER JOIN [DirectAdditions] ON [Drugs].[ID] = [DirectAdditions].[DrugID] AND [Substores].[ID] = [DirectAdditions].[SubStockID]
			LEFT OUTER JOIN [DirectSubtractions] ON [Drugs].[ID] = [DirectSubtractions].[DrugID] AND [Substores].[ID] = [DirectSubtractions].[SubStockID]
			LEFT OUTER JOIN [StockAdjustment] ON [Drugs].[ID] = [StockAdjustment].[DrugID] AND [Substores].[ID] = [StockAdjustment].[SubStoreID]
			LEFT OUTER JOIN [RTransfersIN] ON [Drugs].[ID] = [RTransfersIN].[DrugID] AND [Substores].[ID] = [RTransfersIN].[SubStockID]
			LEFT OUTER JOIN [RTransfersOut] ON [Drugs].[ID] = [RTransfersOut].[DrugID] AND [Substores].[ID] = [RTransfersOut].[SubStockID]

			-- Older than specified from date tables
			LEFT OUTER JOIN [OldPurchases] ON [Drugs].[ID] = [OldPurchases].[DrugID] AND [Substores].[ID] = [OldPurchases].[SubStoreID]
