CREATE proc [Pharmacy].[StagnantItemsNE]  --1,'asdasd'--12 --'2023-07-10','2021-07-10'
as
declare @ExpDay int
set @ExpDay=(select top 1 Pharmacy.PharmacySettings.ExpiaryPeriodDays from  Pharmacy.PharmacySettings)


SELECT        SUM(Pharmacy.StockControlDetail.SignValue * Pharmacy.StockControlDetail.Qty) AS qty, Pharmacy.Substores.SubstoreName, Pharmacy.Drugs.DrugCode, Pharmacy.Drugs.DrugName, 
                       cast(  MAX(Pharmacy.StockControlDetail.TransactionDate) as date) AS Pharmacy, Pharmacy.Batches.BatchNo, Pharmacy.Batches.ExpiryDate, Pharmacy.Suppliers.SupplierName, Pharmacy.Suppliers.SupplierCode
FROM            Pharmacy.StockControl INNER JOIN
                         Pharmacy.StockControlDetail ON Pharmacy.StockControl.ID = Pharmacy.StockControlDetail.StockControlID INNER JOIN
                         Pharmacy.Substores ON Pharmacy.StockControl.SubStoreID = Pharmacy.Substores.ID INNER JOIN
                         Pharmacy.Drugs ON Pharmacy.StockControl.DrugID = Pharmacy.Drugs.ID INNER JOIN
                         Pharmacy.GoodsReceivedNoteDetails ON Pharmacy.StockControlDetail.GRNDetailID = Pharmacy.GoodsReceivedNoteDetails.ID INNER JOIN
                         Pharmacy.GoodsReceivedNoteHeader ON Pharmacy.GoodsReceivedNoteDetails.GRNId = Pharmacy.GoodsReceivedNoteHeader.ID INNER JOIN
                         Pharmacy.Batches ON Pharmacy.GoodsReceivedNoteDetails.ID = Pharmacy.Batches.GRNDetailsId INNER JOIN
                         Pharmacy.Suppliers ON Pharmacy.GoodsReceivedNoteHeader.SupplierId = Pharmacy.Suppliers.ID
						  where ExpiryDate >= GETDATE() and ExpiryDate <= DATEADD(day, @ExpDay, GETDATE()) 
