set @DrugTo=NULL
if @DrugFrom =0
set @DrugFrom=NULL

if @dateTo is not null
begin
set @dateTo=DATEADD(day,1,Cast(@dateTo as date))
end

Select TblTAfter.DrugID,TblTAfter.DrugName,TblTAfter.DrugCode,TblTAfter.incoming,
TblTAfter.Outgoing,TblTAfter.new_row_id,ISNULL(TblTBefore.lastT,0)lastT,TblTAfter.SubstoreName,TblTAfter.SubstoreID
,ISNULL(AddQty,0)TAddQty,ISNULL(SuntracQTY,0)TSuntracQTY,((ISNULL(AddQty,0)+incoming+ISNULL(lastT,0))-Outgoing-ISNULL(Subtraction.SuntracQTY,0)) Balance from (


Select ROW_NUMBER() OVER (ORDER BY DrugID desc) Bnew_row_id,  DrugID BDrugID, SubStoreID BStockID,SubstoreName,COALESCE(( Sum(incoming) -Sum (Outgoing)),0) lastT  ,DrugCode BDrugCode
from(
select  DrugID , SubStoreID,SubstoreName, 0 Outgoing,COALESCE(Sum(PurchQty),0) incoming ,PurchDate,DrugCode,DrugName,'purch' describe
from Pharmacy.V_TStocksMov 
where (issueToDepartment is null or issueToDepartment=0) 
group by ClassID,DrugID,DrugCode,DrugName,SubStoreID ,PurchDate,SubstoreName 
having 
  ((@SubStoreFrom is null or SubStoreID>=@SubStoreFrom) and  
 (@SubStoreTo is null or SubStoreID<=@SubStoreTo)) and
  ((@classFrom is null or V_TStocksMov.ClassID>=@classFrom) and
  (@classTo is null or V_TStocksMov.ClassID>=@classTo))  and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
(@dateFrom is null or purchDate< CAST(@dateFrom AS date)) 

 
union
--Select V_Transfer in
select DrugID ,StockID,SubStoreName ,0  outgoing,COALESCE(Sum(TransferQty),0) as incomming 
,TransferDate,Pharmacy.V_Transfer.DrugCode,Pharmacy.V_Transfer.DrugName,'TransIn' describe
from Pharmacy.V_Transfer
inner join Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_Transfer.DrugID
inner join Pharmacy.Substores St on St.id=Pharmacy.V_Transfer.StockID
group by ClassID,DrugID,Pharmacy.V_Transfer.DrugCode,Pharmacy.V_Transfer.DrugName ,StockID,TransferDate,SubStoreName 
having   ((@SubStoreFrom is null or StockID>=@SubStoreFrom) and  
 (@SubStoreTo is null or StockID<=@SubStoreTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
