,TransferDate,V_Transfer.DrugCode,V_Transfer.DrugName,'TransIn' describe
from Pharmacy.V_Transfer
inner join Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_Transfer.DrugID
inner join Pharmacy.Substores St on St.id=Pharmacy.V_Transfer.MainStockID
group by ClassID,DrugID,Pharmacy.V_Transfer.DrugCode,Pharmacy.V_Transfer.DrugName ,Pharmacy.V_Transfer.MainStockID,TransferDate,SubstoreName 
having
 ((@SubStoreFrom is null or Pharmacy.V_Transfer.MainStockID>=@SubStoreFrom) and  
 (@SubStoreTo is null or Pharmacy.V_Transfer.MainStockID<=@SubStoreTo))  and 
 ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
(@dateFrom is null or TransferDate < CAST(@dateFrom AS date))



union

--Select V_TransferCycle (Return Transfer) out
select DrugID ,StockID,SubstoreName ,Sum(coalesce(IssueReturnQty,0))  TransOut, 0 as TransIn ,
TransferDate,Pharmacy.V_TransferCycle.DrugCode,Pharmacy.V_TransferCycle.DrugName,'TransIn' describe
from Pharmacy.V_TransferCycle
inner join Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_TransferCycle.DrugID
inner join Pharmacy.Substores St on St.id=V_TransferCycle.StockID
group by it.ClassID,DrugID,Pharmacy.V_TransferCycle.DrugCode,Pharmacy.V_TransferCycle.DrugName ,StockID,TransferDate,SubstoreName 
having 
((@SubStoreFrom is null or Pharmacy.V_TransferCycle.StockID>=@SubStoreFrom) and  
 (@SubStoreTo is null or StockID<=@SubStoreTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
(@dateFrom is null or TransferDate< CAST(@dateFrom AS date)) 



union

--Select V_dispenseDrugs
select  DrugID , StockID,SubstoreName, sum(COALESCE(Pharmacy.V_dispenseItems.DispenseQty,0)) Outgoing,0 incoming ,Pharmacy.V_DispenseItems.CreatedDate,it.DrugCode,it.DrugName,'sell' describe
 from Pharmacy.V_DispenseItems inner join Pharmacy.V_DrugClassification it on it.id=Pharmacy.V_DispenseItems.DrugID
inner join Pharmacy.Substores St on St.id=Pharmacy.V_DispenseItems.StockID
