union
--Select V_Transfer in
select DrugID ,StockID,SubstoreName ,0  outgoing,(Sum(TransferQty)) as incomming ,
TransferDate,Pharmacy.V_Transfer.DrugCode,Pharmacy.V_Transfer.DrugName,'TransIn' describe
from V_Transfer
inner join Pharmacy.V_DrugClassification it on it.id=V_Transfer.DrugID
inner join Pharmacy.Substores St on St.id=Pharmacy.V_Transfer.StockID
group by ClassID,DrugID,Pharmacy.V_Transfer.DrugCode,Pharmacy.V_Transfer.DrugName ,StockID,TransferDate,SubstoreName 
having   ((@SubStoreFrom is null or StockID>=@SubStoreFrom) and  
 (@SubStoreTo is null or StockID<=@SubStoreTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
((@dateFrom is null or TransferDate>= CAST(@dateFrom AS date))
 and (@dateTo is null or TransferDate<=CAST(@dateTo AS date)))




union
--Select V_TransferCycle (Return Transfer) in
select DrugID ,Pharmacy.V_TransferCycle.MainStockID,SubstoreName ,
0 TransOut,Sum(coalesce(IssueReturnQty,0))  as TransIn ,
TransferDate,Pharmacy.V_TransferCycle.DrugCode,V_TransferCycle.DrugName,'TransIn' describe
from Pharmacy.V_TransferCycle 
inner join Pharmacy.V_DrugClassification it on it.id=V_TransferCycle.DrugID
inner join Pharmacy.Substores St on St.id=V_TransferCycle.MainStockID
group by ClassID,DrugID,Pharmacy.V_TransferCycle.DrugCode,
         Pharmacy.V_TransferCycle.DrugName ,Pharmacy.V_TransferCycle.MainStockID,TransferDate,SubstoreName 
having 
  ((@SubStoreFrom is null or  V_TransferCycle.MainStockID>=@SubStoreFrom) and  
 (@SubStoreTo is null or  V_TransferCycle.MainStockID<=@SubStoreTo)) and
  ((@classFrom is null or it.ClassID>=@classFrom) and
  (@classTo is null or it.ClassID>=@classTo))  and
((@DrugFrom is null or DrugID>=@DrugFrom) 
 and (@DrugTo is null or DrugID<=@DrugTo)) and 
((@dateFrom is null or TransferDate>= CAST(@dateFrom AS date))
 and (@dateTo is null or TransferDate<=CAST(@dateTo AS date)))


