/****** Object:  StoredProcedure [Radiology].[Dars]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


--[Radiology].Dars 'adsda',20200101,20251219
CREATE proc [Radiology].[Dars]
@Title Nvarchar(4000),
@FromDate int,
@Todate int
as
SELECT     (select top 1 Name from [ApplicationSetup].[Company])  'Facility Name', Registration.Patients.Code AS [S.N. / PATIENT ID / MRN], Registration.Patients.TranslatedFallName, isnull(Registration.Patients.FirstName, '') + ' ' + isnull(Registration.Patients.MiddleName1, '') 
                         + ' ' + isnull(Registration.Patients.MiddleName2, '') + ' ' + isnull(Registration.Patients.LastName, '') AS [PATIENT NAME ], Registration.Patients.MobileNumber, Registration.Patients.Email, 

                        Registration.Patients.IdNumber,  Registration.Patients.PassportNumber
						 ,

					CASE 
    WHEN Registration.Patients.TypeId = 1 THEN 'UAE Citizen' 
    WHEN Registration.Patients.TypeId = 2 THEN 'Resident' 
    ELSE 'international' 
END AS Type,	CASE 
    WHEN Registration.Patients.PatientType = 1 THEN 'OP' 
    WHEN Registration.Patients.PatientType = 2 THEN 'IP' 
	   WHEN Registration.Patients.PatientType =3 THEN 'DC' 
	      WHEN Registration.Patients.PatientType = 4 THEN 'ER' 
    ELSE '' 
END AS [PATIENT TYPE],
			CASE 
