FROM            Radiology.RadiologyReceptions INNER JOIN
                         Registration.Patients INNER JOIN
                         ApplicationSetup.IdentificationTypes ON Registration.Patients.TypeId = ApplicationSetup.IdentificationTypes.Id INNER JOIN
                         Registration.Nationalities ON Registration.Patients.NationalityId = Registration.Nationalities.Id INNER JOIN
                         ApplicationSetup.City ON Registration.Patients.Active = ApplicationSetup.City.Id INNER JOIN
                         OutPatient.PrepareVisitSlip ON Registration.Patients.Id = OutPatient.PrepareVisitSlip.PatientID INNER JOIN
                         Registration.DoctorsDailyScheduleDetails DocDailSchDet ON DocDailSchDet.Id = OutPatient.PrepareVisitSlip.ScheduleAppointmentID INNER JOIN
                         Registration.DoctorsDailySchedule DocDailSch ON DocDailSch.Id = DocDailSchDet.DoctorsDailyScheduleID INNER JOIN
                         OutPatient.InvestigationRequestHeader ON OutPatient.PrepareVisitSlip.OPnumber = OutPatient.InvestigationRequestHeader.OP_IPNumber INNER JOIN
                         OutPatient.InvestigationRequestDetails ON OutPatient.InvestigationRequestHeader.Id = OutPatient.InvestigationRequestDetails.InvestigationRequestId INNER JOIN
                         ApplicationSetup.Service ON OutPatient.InvestigationRequestDetails.ServiceId = ApplicationSetup.Service.Id INNER JOIN
                         Radiology.PatientRadReception ON OutPatient.InvestigationRequestDetails.Id = Radiology.PatientRadReception.InvestigationRequestDetailsID INNER JOIN
                         Radiology.ResultEntryDetails ON OutPatient.InvestigationRequestDetails.Id = Radiology.ResultEntryDetails.InvestigationDetailsId INNER JOIN
                         Radiology.ResultEntryDetails_Findings ON Radiology.ResultEntryDetails.Id = Radiology.ResultEntryDetails_Findings.ResultEntryDetailsID ON 
