CREATE proc [Radiology].[ExamRequestRep] 

@PatientID int null,
@FromDate datetime null,
@Todate datetime null
as
Begin
select InvestigationRequestHeader.PatientID,
InvestigationRequestHeader.OP_IPNumber , Service.NameEn,ISNULL(Doctors.Name,'Radiology Reception') Name ,
Convert(varchar ,  FORMAT (InvestigationRequestHeader.ReqDate, 'dd/MM/yyyy HH:mm:ss'),20) as ReqDate ,InvestigationRequestDetails.QTY,InvestigationRequestDetails.Done,
case
when Findings.Id is null then 'Pending'
when Findings.Status=1 then 'Report First Draft'
else 'Report Done'
--when InvestigationRequestDetails.Done = 'True' then 'Done'
--when InvestigationRequestDetails.Done = 'False' then 'Pending'
--else 'Pending'
end as Statuss,
Patients.FirstName+' '+Patients.MiddleName1+' '+Patients.MiddleName2+' '+Patients.LastName as FullName,
Patients.TranslatedFallName as fullnameen

,Patients.Code
from OutPatient.InvestigationRequestHeader  
inner join  OutPatient.InvestigationRequestDetails on 
InvestigationRequestHeader.Id =InvestigationRequestDetails.InvestigationRequestId
left join Registration.Doctors on InvestigationRequestHeader.DoctorID =Doctors.Id
inner join Registration.Patients on InvestigationRequestHeader.PatientID =Patients.Id
 inner join ApplicationSetup.Service on InvestigationRequestDetails.ServiceId=Service.Id 
 left join Radiology.ResultEntryDetails on ResultEntryDetails.InvestigationDetailsId=InvestigationRequestDetails.Id
 left join Radiology.ResultEntryDetails_Findings Findings on Findings.ResultEntryDetailsID=ResultEntryDetails.Id

where
Service.ServiceType=8
and
(InvestigationRequestHeader.ReqDate >= convert(datetime,@FromDate,103) or @FromDate is null)
and 
(InvestigationRequestHeader.ReqDate < convert(datetime,(DATEADD(DAY,1,@Todate)),103) or @Todate is null)
and
 (InvestigationRequestHeader.PatientID = @PatientID or @PatientID is null)
 END













GO
