/****** Object:  StoredProcedure [Radiology].[ExamRequestReport]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Radiology].[ExamRequestReport] 
@FromDate datetime null,
@Todate datetime null,
@PatientID int null
as

select 
Patients.FirstName+' '+Patients.MiddleName1+' '+Patients.MiddleName2+' '+Patients.LastName as FullName,IPNumber,AccessionNo,ExamRequest.ExamDate,
ExamRequest.[Status],Exams.LocalName

from Radiology.ExamRequest as ExamRequest
join Registration.Patients as Patients
on ExamRequest.PatientID = Patients.Id
join Radiology.Exams as Exams
on ExamRequest.ExamID = Exams.ID

where
(ExamRequest.ExamDate >= convert(datetime,@FromDate,103) or @FromDate is null)
and (ExamRequest.ExamDate < convert(datetime,@Todate,103) or @Todate is null)
and (ExamRequest.PatientID = @PatientID or @PatientID is null)







GO
/****** Object:  StoredProcedure [Radiology].[GetPatientRedResult_Pats]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create proc [Radiology].[GetPatientRedResult_Pats]
as
SELECT DISTINCT p.*
FROM OutPatient.InvestigationRequestDetails ird
INNER JOIN [OutPatient].[InvestigationRequestHeader] ir
    ON ird.InvestigationRequestId = ir.Id
INNER JOIN ApplicationSetup.Service s
    ON ird.ServiceId = s.Id
INNER JOIN Radiology.ResultEntryDetails red
    ON red.InvestigationDetailsId = ird.Id
INNER JOIN Registration.Patients p
    ON p.Id = ir.PatientID
WHERE s.ServiceType = 8

