/****** Object:  StoredProcedure [Radiology].[SP_InvestigationRequest_ReportNew]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Radiology].[SP_InvestigationRequest_ReportNew]
 @patientId int = null,
 @ServiceId int = null,
 @ReqDate datetime
AS
Select  
Patients.FirstName+' '+Patients.MiddleName1+' '+Patients.MiddleName2 as PatientName,
  Doctors.Name as Doctor,
  Header.OP_IPNumber as OP_IPNumber,
 CONVERT(date, Header.ReqDate) as ReqDate,
  Header.Code as Code,
  Service.RecordName as Service,
  Details.Amount as Amount,
  ExamRequests.Notes as Notes,
  ExamRequests.RequestDate as RequestDate,
  Exam.LatinName as LatinName,
  Exam. LocalName as LocalName

FROM    OutPatient.InvestigationRequestHeader as Header
JOIN    OutPatient.InvestigationRequestDetails as Details ON Details.InvestigationRequestId = Header.Id
JOIN    Registration.Doctors as Doctors ON Header.doctorId = Doctors.Id
JOIN    Registration.Patients as Patients ON Header.PatientID = Patients.Id
JOIN    ApplicationSetup.Service as Service ON Details.ServiceId = Service.Id
join    Radiology.ExamRequest as ExamRequests on Details.ServiceId=ExamRequests.ServiceId
join    Radiology.Exams  as Exam on ExamRequests.ExamID=Exam.ID



where Header.PatientID = @patientId
and Service.Id = @ServiceId
and CONVERT(date, Header.ReqDate)= convert(date,@ReqDate)








