CREATE proc [Receivable].[GetInsuranceClaimsMaster]
(@InsuranceClaimsMasterID int)
as

SELECT TOP (200) Receivable.InsuranceClaimsMaster.Id, Receivable.InsuranceClaimsMaster.Ins_Id, Receivable.InsuranceClaimsMaster.ClaimValue, Receivable.InsuranceClaimsMaster.createDate, 
                 Receivable.InsuranceClaimsMaster.FromDate, Receivable.InsuranceClaimsMaster.ToDate, Receivable.InsuranceClaimsMaster.EntryCodes, Receivable.InsuranceClaimsMaster.CompanyID, 
                 Receivable.InsuranceClaims.ClaimValue AS Expr1, Receivable.InsuranceClaims.FpaidValue, Receivable.InsuranceClaims.CurrencyID, ApplicationSetup.Currency.Name, Billing.InsuranceCompanies.NameEnglish, 
                 Billing.InsuranceCompanies.NameArabic,
(SELECT TOP (1) Image  FROM  ApplicationSetup.QRImage
WHERE (InvoiceId = @InsuranceClaimsMasterID) AND (ReportName = 'CashPaymentForInsurance')) AS img, Receivable.InsuranceClaims.createDate AS Expr2
FROM Receivable.InsuranceClaimsMaster left JOIN
