/****** Object:  StoredProcedure [Registration].[GetAllScheduledList]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Registration].[GetAllScheduledList]  
(
 @SessionID int = 0,  
 @ScheduleDate datetime = 0,
  @DoctorID int = 0
  )
AS
select  Id = sc_d.Id,
        DoctorsDailyScheduleID = sc_d.DoctorsDailyScheduleID,
        PatientID = sc_d.PatientID,
        PatientName = pat.FirstName +''+pat.MiddleName1+''+pat.LastName,
		PatientMobileNumber = pat.MobileNumber,
		PatientPhoneNumber = pat.PhoneNumber,
        [Time] = sc_d.[Time],
        Interval = null,
        Visited = sc_d.Visited,
        Sponcer = sc_d.Sponcer,
        ContactNo = sc_d.ContactNo,
        Seen = sc_d.Seen,
        Triage = sc_d.Triage,
        DoctorName = doc.Name ,
		Department =dept.Name
from [Registration].[DoctorsDailyScheduleDetails] as sc_d
join [Registration].[DoctorsDailySchedule] as sc on sc_d.DoctorsDailyScheduleID = sc.Id
join [Registration].[Doctors] as doc on sc.DoctorID = doc.Id
join [Registration].[Patients]  as pat on pat.Id=sc_d.PatientID
join [ApplicationSetup].[CostCenter] as dept on sc.DepartmentID = dept.Id 
where 
          sc_d.OverBookingStatus = 0 and 
          (@SessionID = 0 or sc.SessionID = @SessionID) 
          and   (@ScheduleDate = 0 or (convert(date, sc.ScheduleDate) = convert(date,@ScheduleDate)))
		  and  (@DoctorID = 0 or doc.Id =@DoctorID) 



GO
