insert into @SysTable 
select s.name as SchemaName, t.name as TableName,c.name as ColumnName from sys.tables as t
join sys.columns as c on t.object_id=c.object_id
join sys.schemas as s on t.schema_id=s.schema_id
where c.name  = 'PatientID'
order by t.name
DECLARE @SchemaName nvarchar(max),@TableName nvarchar(max),    
    @ColumnName nvarchar(max);    
DECLARE SysTable_Cursor CURSOR FOR     
SELECT *
FROM @SysTable
ORDER BY TableName
OPEN SysTable_Cursor    
FETCH NEXT FROM SysTable_Cursor     
INTO @SchemaName ,@TableName ,
    @ColumnName 
WHILE @@FETCH_STATUS = 0    
BEGIN    
   set @sql =@sql+ N'update '+ @SchemaName +'.'+@TableName +' set '+@ColumnName +'='+cast( @ParentPatientID as nvarchar(20)) +' where '+@ColumnName +' in ( select PatientIDToMerge  from Registration.MergePatientDetail where MergePatientID='+cast(@MergePatientID as nvarchar(20))+' ) ;'
	
	
    FETCH NEXT FROM SysTable_Cursor     
INTO @SchemaName ,@TableName ,
    @ColumnName 
END     
CLOSE SysTable_Cursor;    
DEALLOCATE SysTable_Cursor; 
print @sql
exec ( @sql)
update InPatient.PreAnesthesiaEvaluation set PatientID=@ParentPatientID  where PatientID in ( select PatientIDToMerge  from Registration.MergePatientDetail where MergePatientID=@MergePatientID  )
update OutPatient.PrescriptionsDetails set PatientID=@ParentPatientID  where PatientID in ( select PatientIDToMerge  from Registration.MergePatientDetail where MergePatientID=@MergePatientID  )
update Registration.MergePatient
set IsMereged=1
where ID=@MergePatientID
delete from Registration.Patients
where Id in (select PatientIDToMerge  from Registration.MergePatientDetail where MergePatientID=@MergePatientID )
--COMMIT 
END TRY  
BEGIN CATCH  
    --ROLLBACK
print error_message();
END CATCH



GO
