CREATE proc [Registration].[PatientMRN]
(@PatientID int = null  )
as
begin

--declare @PatientID int = 4

Select Id as VisitID, OP_IPNumber,servID,paID,RecordName,ParentId,FirstName,MiddleName1,Co from OutPatient.InvestigationRequestHeader inner join (

select * from(
Select id as servID,[Registration].[V_PatientService].patientID as paID, [V_PatientService].RecordName,[V_PatientService].ParentId,[V_PatientService].FirstName,[V_PatientService].MiddleName1,[V_PatientService].ServiceCode
,[Registration].[V_PatientService].patientCode as Co
from [Registration].[V_PatientService] 

where [Registration].[V_PatientService].ParentId is null and @PatientID is null or [Registration].[V_PatientService].PatientID=@PatientID

union
select id as drg,
[Registration].[V_PationtDrugs].PatientID as PatientID,
[Registration].[V_PationtDrugs].DrugName,
0 ParentId,[Registration].[V_PationtDrugs].FirstName ,
[Registration].[V_PationtDrugs].MiddleName1,
[Registration].[V_PationtDrugs].DrugCode,[Registration].[V_PationtDrugs].patientCode as Co

FROM [Registration].[V_PationtDrugs]
where (@PatientID is null or [Registration].[V_PationtDrugs].PatientID=@PatientID )
) as innertbl
) as serv on serv.paID=OutPatient.InvestigationRequestHeader.patientID

