CREATE procEDURE [Registration].[Rep_PatientsByAddress] 
	-- Add the parameters for the stored procedure here
	@FromDate varchar(20) = null,
	@ToDate varchar(20) = null,
	@CountryId int = null,
	@CityId int = null, 
	@DistrictId int = null
AS
	SELECT 
	P.Code, 
	CASE 
		WHEN P.TranslatedFallName = NULL THEN p.FirstName
		ELSE p.TranslatedFallName 
	END As PatientName,
	P.RegistrationDate, Dr.Name as DrName
	, Con.Name as country, City.Name as city, Dis.DistrictName as district
	
	FROM Registration.Patients P left outer join Registration.Doctors Dr on P.PrimaryDoctorId = Dr.Id left outer join 
		 ApplicationSetup.Country Con on Con.Id = P.CountryId left outer join 
		 ApplicationSetup.City City on City.Id = p.CityId left outer join 
		 ApplicationSetup.District Dis on Dis.Id = p.DistrictId   
		 --and City.Id = P.CityId and Dis.Id = P.DistrictId 

	WHERE (@FromDate is null or  P.RegistrationDate >= @FromDate) and
		  (@ToDate is null or DATEADD(DAY, 1, @ToDate) >= P.RegistrationDate) and
		  (@CountryId is null or @CountryId = Con.Id) and
		  (@CityId is null or @CityId = P.CityId ) and 
		  (@DistrictId is null or @DistrictId = p.DistrictId);



GO
/****** Object:  StoredProcedure [Registration].[Rep_PatientsBySponsor]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create   procEDURE [Registration].[Rep_PatientsBySponsor] 
	-- Add the parameters for the stored procedure here
	@FromDate varchar(20) = null,
	@ToDate varchar(20) = null,
	@SponsorId int = null
	
AS
	SELECT P.Code, isnull(P.TranslatedFallName,'') As PatientName,
	 P.RegistrationDate, p.Code as Code,p.MobileNumber as MobileNumber,Pay.PaymentModeDescription 
	
	FROM Registration.Patients P  join Billing.PaymentModes Pay on P.PaymentType = Pay.Id 
		 
		

	WHERE
(@FromDate is null or  P.RegistrationDate >= CAST(@FromDate  AS date))and
    (@ToDate  is null or  P.RegistrationDate  <= DATEADD(day,1,CAST(@ToDate  AS date))) 
	AND
		  (@SponsorId is null or @SponsorId = p.PaymentType)
		




GO
