/****** Object:  StoredProcedure [Registration].[RepNewRegisteredPatientsAr]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create procEDURE [Registration].[RepNewRegisteredPatientsAr]
	-- Add the parameters for the stored procedure here
	@FromDate nVarChar(50) = null,
	@ToDate nVarChar(50) = null
AS
	SELECT p.FirstName + ' ' + p.MiddleName1 + ' ' + p.MiddleName2 + ' ' + p.LastName as 'Arabic Patient Name' ,
	 P.Code, P.FirstName + ' '+ p.MiddleName1 + ' ' + p.MiddleName2 + ' ' + P.LastName as 'PatientName',
	 Doc.NameAr , 
	  convert(datetime, P.CreatedDate, 103)as Registereddate
	FROM Registration.Patients P 
left join Registration.Doctors Doc on P.PrimaryDoctorId = Doc.Id
	WHERE 
	--P.RegistrationDate between @FromDate and @ToDate
	 (@FromDate is  null or @FromDate <=P.RegistrationDate) and
		  (@ToDate is   null or DATEADD(day, 1, @ToDate) >= P.RegistrationDate)
	 order by 

		 convert(datetime, P.CreatedDate, 103) Desc
GO
/****** Object:  StoredProcedure [Registration].[RepPatientsByHearAbout]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE procEDURE [Registration].[RepPatientsByHearAbout]
	-- Add the parameters for the stored procedure here
	@FromDate VarChar(20)= null,
	@ToDate VarChar(20) = null,
	@MedID int = null
AS
	SELECT P.Code, P.FirstName + ' ' + P.LastName as PatientName , Doc.Name as DoctorName,P.MobileNumber, P.RegistrationDate ,MM.Name
	FROM Registration.Patients P inner join  Registration.MarketingMedia MM on P.HearAbout = MM.Id 
		 left outer join Registration.Doctors Doc on P.PrimaryDoctorId = Doc.Id
	WHERE (@FromDate is null or Convert(date,@FromDate) <= P.RegistrationDate ) and
		  (@ToDate is null or Convert(date,@ToDate)>= P.RegistrationDate) and
