/****** Object:  StoredProcedure [Registration].[SADetailsAccptnonAccept]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE proc [Registration].[SADetailsAccptnonAccept]-- 1,0,99999999,'',''
(
 @QuestionID int,
 @From int,
 @To int,
 @Question nvarchar(max),
 @Title nvarchar(max))
as




declare @Sum int




set @Sum=( SELECT     sum(Tot) 
from (


SELECT        Registration.SurveyAnswers.QuestAns, COUNT(Registration.PatientSurveyDetail.ServAnswer) AS Tot
FROM            Registration.PatientSurvey INNER JOIN
                         Registration.PatientSurveyDetail ON Registration.PatientSurvey.Id = Registration.PatientSurveyDetail.MasterID RIGHT OUTER JOIN
                         Registration.SurveyAnswers ON Registration.PatientSurveyDetail.ServAnswer = CAST(Registration.SurveyAnswers.Id AS varchar)
WHERE        (Registration.SurveyAnswers.QuestId = @QuestionID)  AND (CAST(CONVERT(char(8), Registration.PatientSurvey.CreatedDate, 112) AS bigint) BETWEEN @From AND @To) 
GROUP BY Registration.SurveyAnswers.QuestAns
) as tt
)

SELECT        case when Registration.SurveyAnswers.QuestAns <4 then 'Non Accepatable' else 'Acceptable' End as 'SType'  , COUNT(Registration.PatientSurveyDetail.ServAnswer) AS Total, CAST(COUNT(Registration.PatientSurveyDetail.ServAnswer) AS decimal) / CAST(@Sum AS decimal) * 100 AS Per
 into #Temp
FROM            Registration.PatientSurvey INNER JOIN
                         Registration.PatientSurveyDetail ON Registration.PatientSurvey.Id = Registration.PatientSurveyDetail.MasterID RIGHT OUTER JOIN
                         Registration.SurveyAnswers ON Registration.PatientSurveyDetail.ServAnswer = CAST(Registration.SurveyAnswers.Id AS varchar)
