  刀攀最椀猀琀爀愀琀椀漀渀⸀䐀漀挀琀漀爀猀⸀䤀搀 㴀 刀攀最椀猀琀爀愀琀椀漀渀⸀倀愀琀椀攀渀琀匀甀爀瘀攀礀⸀䐀漀挀琀漀爀䤀䐀ഀ਀
WHERE        (Registration.SurveyAnswers.QuestId = @QuestionID) AND (CAST(CONVERT(char(8), Registration.PatientSurvey.CreatedDate, 112) AS bigint) BETWEEN @From AND @To) AND (Registration.SurveyAnswers.QuestAns IN (N'1', 
                         N'2', N'3'))
GROUP BY OutPatient.SpecialityGroupDetails.NameAr, OutPatient.SpecialityGroupDetails.Name
) as tt
)

SELECT        COUNT(Registration.PatientSurveyDetail.ServAnswer) AS Total, CAST(COUNT(Registration.PatientSurveyDetail.ServAnswer) AS decimal) / CAST(@Sum AS decimal) * 100 AS Per, 
                         OutPatient.SpecialityGroupDetails.NameAr AS Name, OutPatient.SpecialityGroupDetails.Name AS NameEn
FROM            OutPatient.SpecialityGroupDetails INNER JOIN
                         Registration.Doctors ON OutPatient.SpecialityGroupDetails.ID = Registration.Doctors.SpecialtyId INNER JOIN
                         Registration.SurveyAnswers INNER JOIN
                         Registration.PatientSurvey INNER JOIN
                         Registration.PatientSurveyDetail ON Registration.PatientSurvey.Id = Registration.PatientSurveyDetail.MasterID ON CAST(Registration.SurveyAnswers.Id AS varchar) = Registration.PatientSurveyDetail.ServAnswer ON 
                         Registration.Doctors.Id = Registration.PatientSurvey.DoctorID
WHERE        (Registration.SurveyAnswers.QuestId = @QuestionID) AND (CAST(CONVERT(char(8), Registration.PatientSurvey.CreatedDate, 112) AS bigint) BETWEEN @From AND @To) AND (Registration.SurveyAnswers.QuestAns IN (N'1', 
                         N'2', N'3'))
GROUP BY OutPatient.SpecialityGroupDetails.NameAr, OutPatient.SpecialityGroupDetails.Name
order by  COUNT(Registration.PatientSurveyDetail.ServAnswer) desc

GO
