CREATE proc [Registration].[SANonDetailDoctor]-- 1,0,99999999,'',''
(
 @QuestionID int,
 @From int,
 @To int,
 @Question nvarchar(max),
 @Title nvarchar(max))
as



declare @Sum int




set @Sum=( SELECT     sum(Total) 
from (


SELECT        COUNT(Registration.PatientSurveyDetail.ServAnswer) AS Total, CAST(COUNT(Registration.PatientSurveyDetail.ServAnswer) AS decimal) / CAST(@Sum AS decimal) * 100 AS Per, Registration.Doctors.Code, 
                         Registration.Doctors.Name, Registration.Doctors.NameAr
FROM            Registration.PatientSurveyDetail INNER JOIN
                         Registration.SurveyAnswers ON Registration.PatientSurveyDetail.ServAnswer = CAST(Registration.SurveyAnswers.Id AS varchar) INNER JOIN
                         Registration.PatientSurvey ON Registration.PatientSurveyDetail.MasterID = Registration.PatientSurvey.Id INNER JOIN
                         Registration.Doctors ON Registration.PatientSurvey.DoctorID = Registration.Doctors.Id
						 WHERE        (Registration.SurveyAnswers.QuestId = @QuestionID) AND (CAST(CONVERT(char(8), Registration.PatientSurvey.CreatedDate, 112) AS bigint) BETWEEN @From AND @To) AND (Registration.SurveyAnswers.QuestAns in('1','2','3'))
GROUP BY Registration.Doctors.Code, Registration.Doctors.Name, Registration.Doctors.NameAr
) as tt
)

