/****** Object:  StoredProcedure [Registration].[SP_ChoricPatientsReport_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Registration].[SP_ChoricPatientsReport_Report]
@departmentId int = null,
@DateFrom datetime = null ,
@DateTo datetime = null
	
AS
Select
CostCenter.Name as Department,
patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
COUNT(PrepareVisitSlip.PatientId ) as NoOfVisits 
    

from OutPatient.PrepareVisitSlip as PrepareVisitSlip 
join ApplicationSetup.CostCenter as CostCenter on CostCenter.Id=PrepareVisitSlip.DepartmentID
join Registration.Patients as patient on patient.Id=PrepareVisitSlip.PatientId

where  (PrepareVisitSlip.CreatedDate >= convert( datetime,@DateFrom,103 ) or @DateFrom is null)
and (PrepareVisitSlip.CreatedDate <= convert( datetime,@DateTo,103 ) or @DateTo is null)
and (PrepareVisitSlip.DepartmentID = @departmentId or @departmentId is null)


group by CostCenter.Name, patient.FirstName,patient.MiddleName1,patient.MiddleName2,patient.LastName

Union
Select
CostCenter.Name as Department,
'No Data Found' as PatientName,
0 as NoOfVisits from  ApplicationSetup.CostCenter as CostCenter where CostCenter.Id = @departmentId or @departmentId is null
and not exists(select 1 from OutPatient.PrepareVisitSlip as PrepareVisitSlip 
join ApplicationSetup.CostCenter as CostCente on CostCente.Id=PrepareVisitSlip.DepartmentID
join Registration.Patients as patient on patient.Id=PrepareVisitSlip.PatientId and CostCente.Id != CostCenter.Id )










GO
