/****** Object:  StoredProcedure [Registration].[SP_DoctorScheduleSummary_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Registration].[SP_DoctorScheduleSummary_Report]
 @DepartmentID int,
 @DoctorID int,
 @DateFrom Date = null,
 @DateTo Date = null
	
AS
Select
 detail.Day, 
 convert(varchar, detail.SessionDateFrom, 108) as TimeFrom,
convert(varchar, detail.SessionDateTo, 108) as TimeTo,
session.SessionName


from Registration.DoctorDutyRosters as header
join Registration.DoctorDutyRostersDetails as detail on header.Id=detail.DoctorDutyRostersHeaderId
join Registration.Sessions as session on detail.SessionsID=session.Id


where header.DepartmentID=@DepartmentID
and header.DoctorID=@DoctorID
and (header.DateFrom <= @DateFrom or @DateFrom is null)
and (header.DateTo >= @DateTo or @DateTo is null)









GO
