CREATE procEDURE [Registration].[SP_ImmunizationReport_Report]
 @DepartmentID int,
  @DateFrom datetime = null,
  @DateTo datetime = null
	
AS
Select
CostCenter.Name,
VaccinationMaster.VaccinationName

