CREATE procEDURE [Registration].[SP_NationalityGroupWise_Report]
 @nationalityGroupId int =null


AS
Select

NationalityGroups.GroupName ,
COUNT (PrepareVisitSlip.VisitNo) as TotalVisits

 

from OutPatient.PrepareVisitSlip as PrepareVisitSlip
join Registration.Patients as patient on PrepareVisitSlip.PatientId=patient.Id
join Registration.Nationalities as Nationalities on patient.NationalityId=Nationalities.Id
join Registration.NationalityGroups as NationalityGroups on Nationalities.NationalityGroupId=NationalityGroups.Id

where (NationalityGroups.Id=@nationalityGroupId or @nationalityGroupId is null)

group by NationalityGroups.GroupName

UNION ALL
  SELECT  NationalityGroup.GroupName ,0 as totalvisit from Registration.NationalityGroups as NationalityGroup where NationalityGroup.Id =@nationalityGroupId or  @nationalityGroupId is null
  and NOT EXISTS(select 1 from OutPatient.PrepareVisitSlip as PrepareVisitSlip
join Registration.Patients as patient on PrepareVisitSlip.PatientId=patient.Id
join Registration.Nationalities as Nationalities on patient.NationalityId=Nationalities.Id
join Registration.NationalityGroups as NationalityGroups on Nationalities.NationalityGroupId=NationalityGroups.Id where NationalityGroups.Id=NationalityGroup.Id) group by NationalityGroup.GroupName










GO
