from ApplicationSetup.CostCenter as CostCenter

where not exists
(select 1 from OutPatient.PrepareVisitSlip as PrepareVisitSlip 
join ApplicationSetup.CostCenter as CostCenter on CostCenter.Id=PrepareVisitSlip.DepartmentID
join Registration.Doctors as Doctors on Doctors.Id=PrepareVisitSlip.DoctorsID

where  (PrepareVisitSlip.CreatedDate >= convert( datetime,@DateFrom,103 ) or @DateFrom is null) 
and (PrepareVisitSlip.CreatedDate <= convert( datetime,@DateTo,103 ) or @DateTo is null) 
and (PrepareVisitSlip.DoctorsID = @DoctorsID or @DoctorsID is null)


group by CostCenter.Name,Doctors.Name)









