/****** Object:  StoredProcedure [Registration].[SP_OPStatisticsDepartmentWise_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE procEDURE [Registration].[SP_OPStatisticsDepartmentWise_Report]
  @DateFrom datetime ,
  @DateTo datetime 
	
AS
Select
CostCenter.Name,

	 COUNT( case when PrepareVisitSlip.VisitType='1' then 1 end) as 'New',
     COUNT( case when PrepareVisitSlip.VisitType='2' then 1 end) as 'Review',
	 COUNT( case when PrepareVisitSlip.VisitType='3' then 1 end) as 'Follow Up',

	( COUNT( case when PrepareVisitSlip.VisitType='1' then 1 end)+
	  COUNT( case when PrepareVisitSlip.VisitType='2' then 1 end)+
	  COUNT( case when PrepareVisitSlip.VisitType='3' then 1 end) ) as Total
from OutPatient.PrepareVisitSlip as PrepareVisitSlip 
join ApplicationSetup.CostCenter as CostCenter on CostCenter.Id=PrepareVisitSlip.DepartmentID

where  PrepareVisitSlip.CreatedDate >= @DateFrom 
and PrepareVisitSlip.CreatedDate <= @DateTo 


group by CostCenter.Name

UNION all
select CostCenter.Name,0 as 'New',0 as 'Review',0 as 'Follow Up',0 as Total from ApplicationSetup.CostCenter where
not exists (Select 1
from OutPatient.PrepareVisitSlip as PrepareVisitSlip 
join ApplicationSetup.CostCenter as CostCenter on CostCenter.Id=PrepareVisitSlip.DepartmentID

where  PrepareVisitSlip.CreatedDate >= @DateFrom 
and PrepareVisitSlip.CreatedDate <= @DateTo 
group by CostCenter.Name)









