/****** Object:  StoredProcedure [Registration].[SP_ReceiveMedical_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE procEDURE [Registration].[SP_ReceiveMedical_Report]
 @MRD int

AS
Select
 patient.FirstName+' '+ patient.MiddleName1+' '+patient.MiddleName2+' '+patient.LastName as PatientName,
 Request.OPNumber as OPNumber,
Department.Name as RequestedBy,
MRD.CounterName as MRD,
Request.RequiredOn as RequestDate,
CONVERT(date,Request.LastModifiedDate) as SentDate,
CONVERT(nvarchar,Request.LastModifiedDate,108) as SentTime,
patient.Code as PatientId,
Users.UserName as SentBy

from Registration.RequestMedicalRecordTransfer as Request
join ApplicationSetup.CostCenter as Department on Department.Id=Request.RequestedBy
join Registration.Patients as patient on patient.Id=Request.PatientId
join Registration.MedicalRecordDepartments as MRD on MRD.Id=Request.MRD
join JCIT_MembershipDB.dbo.AspNetUsers as Users on Users.Id COLLATE SQL_Latin1_General_CP1_CI_AS =Request.LastModifiedBy COLLATE SQL_Latin1_General_CP1_CI_AS

where Request.MRD=@MRD
and Request.Status='2'


GO
