/****** Object:  StoredProcedure [Registration].[SP_ViewPatientRegistrationForm_Report]    Script Date: 8/27/2026 2:35:46 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE proc [Registration].[SP_ViewPatientRegistrationForm_Report]
 @PatientID int
	
AS
BEGIN
select
(select top 1 [Image] from [ApplicationSetup].[QRImage] where  [ApplicationSetup].[QRImage].ReportName=N'patientQRCode' and [ApplicationSetup].[QRImage].[PatID]=@PatientID   order by id desc) as QrImage,
	 P.id,code MRN ,T.ArabicTitleName,T.EnglishTitleName , 
	 isnull (P.TranslatedFallName ,p.FirstName + '' + p.MiddleName1  +''  +p.MiddleName2+ p.LastName )AS ENName ,
isnull(p.FirstName,'') +' '+ isnull(p.MiddleName1,'') +' ' +isnull(p.MiddleName2,'')+ ' '+isnull(p.LastName,'') as  ArabicFullName,
P.RegistrationDate,p.MobileNumber,n.Name NatNameAr,n.NameEn NatNameEn,R.Name ReligonNameAr,R.NameEn ReligonNameEn,
p.PassportNumber IDNum,p.PassportValidityEndDate IDEndDate,
CASE
    WHEN p.PatientType =0 THEN N'All'
    WHEN p.PatientType =1 THEN N'OutPateint'
    WHEN p.PatientType =2 THEN N'InPateint'
    WHEN p.PatientType =3 THEN N'Referred'
    WHEN p.PatientType =4 THEN N'Emergancy'
    ELSE ''
END AS PatientTypeEn,
CASE
    WHEN p.PatientType =0 THEN N'الكل'
    WHEN p.PatientType =1 THEN N'خارجى'
    WHEN p.PatientType =2 THEN N'داخلى'
    WHEN p.PatientType =3 THEN N'محول'
    WHEN p.PatientType =4 THEN N'طوارئ'
    ELSE ''
END AS PatientTypeAr,
CASE
    
    WHEN p.RegisterPatientsType =1 THEN N'normal'
    WHEN p.RegisterPatientsType =2 THEN N'Special'
    WHEN p.RegisterPatientsType =3 THEN N'Call_Center'
    WHEN p.RegisterPatientsType =4 THEN N'Emergency'
    ELSE ''
END AS RegisterPatientTypeEn,
CASE
   
    WHEN p.RegisterPatientsType =1 THEN N'عادي'
    WHEN p.RegisterPatientsType =2 THEN N'خاص'
