create Proc [Registration].[usp_GetAllScheduledListByScheduleDateCount]
(@Sdate nvarchar(50))
as
SELECT       count(*)
FROM            Registration.DoctorsDailySchedule INNER JOIN
                         Registration.DoctorsDailyScheduleDetails ON Registration.DoctorsDailySchedule.Id = Registration.DoctorsDailyScheduleDetails.DoctorsDailyScheduleID
WHERE        (Registration.DoctorsDailySchedule.ScheduleDate = @Sdate)
GO
