CREATE  procEDURE [Registration].[wristbandBarCode] --2
	-- Add the parameters for the stored procedure here
	@paID int

AS
	SELECT  
	 (isnull( P.Code,'' ) 
	 +' '+ CASE 
     WHEN P.GenderId  =  1 THEN 'Male'
     WHEN P.GenderId  =  2THEN 'Female'
    
     ELSE ''
  END 
	   +' '+ CASE 
     WHEN p.PatientType= '1'   THEN 
	  ISNULL(format  ( OutPatient.PrepareVisitSlip.Time, 'hh:mm:ss')  ,'') 
     WHEN p.PatientType= '2'  THEN
	 ISNULL( format  (  InPatient.AdmitPatients.AdmissionTime, 'hh:mm:ss')  , '') 
